window.ITEMS=[{"id": "et101-08", "exam": "et101", "nums": [8], "form": "單題", "img": "img/et101-08.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["典故出處", "文化常識"], "passage": "", "translation": "", "keywords": [{"w": "簞食瓢飲", "m": "一竹筐飯、一瓢水，形容生活清苦（顏回的故事）"}, {"w": "移山填海", "m": "愚公移山、精衛填海兩個神話寓言合成，比喻意志堅定"}, {"w": "初識之無", "m": "白居易幼時便認得「之」「無」二字，後指剛開始識字"}, {"w": "周行不息", "m": "循環運行不停止"}], "questions": [{"n": 8, "qtype": "單選", "stem": "下列選項「」內的成語，何者不是源自於事件或神話寓言？", "options": {"A": "人如果能知足，真可以傲視王侯，雖「簞食瓢飲」，也富可敵國(思果〈幸福何在〉)", "B": "春夏秋冬，四時之氣，「周行不息」，而後歲歲年年，人道賴以永存(唐君毅〈說青年之人生〉)", "C": "吾心信其可行，則「移山填海」之難，終有成功之日(孫文〈心理建設自序〉)", "D": "自我「初識之無」以迄於今，將近半個世紀，讀過的書為數究有多少，從來未有統計(莊因〈詩情與俠骨〉)"}, "answer": "B", "explain": "先判斷每個成語背後有沒有「一段故事」。(A)「簞食瓢飲」出自《論語‧雍也》，孔子稱讚顏回「一簞食，一瓢飲，在陋巷，人不堪其憂，回也不改其樂」，是一件真實事件。(B)「周行不息」只是描述四季之氣循環運行、永不停止，概念近於《老子》「周行而不殆」，是一般的描述語，背後沒有事件或寓言，所以是答案。(C)「移山填海」結合「愚公移山」（《列子》寓言）與「精衛填海」（《山海經》神話），源自神話寓言。(D)「初識之無」出自白居易〈與元九書〉：他出生六、七個月時，乳母指「之」「無」二字給他看，他就能認得，是事件典故。", "skill": "遇到「源自事件或寓言」的成語題，問自己：這個成語能不能說出「誰、做了什麼事」？說不出故事的，就是一般描述語。"}], "difficulty": "中", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-10", "exam": "et101", "nums": [10], "form": "單題", "img": "img/et101-10.png", "source": "江盈科〈催科〉", "author": "江盈科", "genre": "說理議論", "types": ["字詞解釋"], "passage": "為令之難，難於催科。催科與撫字，往往相妨，不能相濟。", "translation": "當縣令的難處，就難在催收賦稅。催收賦稅和安撫照顧百姓，常常互相妨礙，沒辦法兩全。", "keywords": [{"w": "令", "m": "縣令"}, {"w": "催科", "m": "催收租稅"}, {"w": "撫字", "m": "安撫、養育百姓"}, {"w": "相濟", "m": "互相成全、互相幫助"}], "questions": [{"n": 10, "qtype": "單選", "stem": "江盈科〈催科〉：「為令之難，難於催科。催科與撫字，往往相妨，不能相濟。」對於「科」字的解釋，下列何者正確？", "options": {"A": "科舉考試", "B": "科技發展", "C": "科學實驗", "D": "科稅條目"}, "answer": "D", "explain": "「催科」和「撫字」對舉：一個是向百姓要錢，一個是照顧百姓，所以兩者「往往相妨」。縣令要「催」的是賦稅，「科」就是依條目徵收的租稅，答案(D)科稅條目。(A)科舉考試是選拔人才的制度，縣令不會去「催」科舉；(B)科技發展、(C)科學實驗都是現代詞義，放回古文完全不通。", "skill": "古文字詞不要用現代常用義直接套，先看它和哪個詞對舉（催科／撫字），再從文意反推意思。"}], "difficulty": "易", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-11", "exam": "et101", "nums": [11], "form": "單題", "img": "img/et101-11.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "子之燕居，申申如也，夭夭如也／縱一葦之所如，凌萬頃之茫然／字字清脆，聲聲宛轉，如新鶯出谷，乳燕歸巢／如有離違，宜別圖之，以濟大事", "translation": "孔子在家閒居的時候，神情舒展從容，臉色和悅愉快／任憑那像一片蘆葦的小船，漂到它要去的地方，越過浩瀚無邊的江面／每個字都清楚響亮，每個音都婉轉動聽，好像剛飛出山谷的黃鶯、剛回到巢裡的小燕子／如果他們彼此離心不合，就應該另作打算，來成就大事", "keywords": [{"w": "申申如", "m": "舒展從容的樣子；「如」是形容詞詞尾"}, {"w": "縱一葦之所如", "m": "任憑小船到它要去的地方；「如」是「往、到」"}, {"w": "如有離違", "m": "如果有分歧不合"}], "questions": [{"n": 11, "qtype": "單選", "stem": "下列選項中的「如」字，何者作「往」的意思解釋？", "options": {"A": "子之燕居，申申「如」也，夭夭如也(《論語‧述而》)", "B": "縱一葦之所「如」，凌萬頃之茫然(蘇軾〈前赤壁賦〉)", "C": "字字清脆，聲聲宛轉，「如」新鶯出谷，乳燕歸巢(劉鶚《老殘遊記‧明湖居聽書》)", "D": "「如」有離違，宜別圖之，以濟大事(司馬光《資治通鑑‧赤壁之戰》)"}, "answer": "B", "explain": "(B)〈前赤壁賦〉「縱一葦之所如」，意思是任憑像一片蘆葦的小船漂到它要去的地方，「所如」就是「所往」，「如」作「往、到」，是答案。(A)「申申如也，夭夭如也」形容孔子閒居時舒坦和悅的樣子，「如」是形容詞詞尾，等於「……的樣子」。(C)「如新鶯出谷」是「好像」，屬譬喻。(D)「如有離違」是「如果」，表假設。", "skill": "「如」的常見義：像、如果、往、……的樣子。看到「所如」，或「如」後面直接接地點（如「如齊」），優先想「往」。"}], "difficulty": "易", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-12", "exam": "et101", "nums": [12], "form": "單題", "img": "img/et101-12.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "民不易物，惟德繄物／願陛下託臣以討賊興復之效，不效，則治臣之罪／愛其子，擇師而教之，於其身也，則恥師焉／陳相見許行而大悅，盡棄其學而學焉", "translation": "百姓獻上的祭品都一樣，只有德行才是神明真正看重的祭品／希望陛下把討伐曹賊、復興漢室的任務交給我，如果沒有成功，就治我的罪／人們疼愛自己的孩子，會挑選老師來教他；但對於自己，卻以跟老師學習為恥／陳相見到許行後非常高興，完全拋棄了原先所學的學問，改向許行學習", "keywords": [{"w": "繄", "m": "是（語助、判斷）"}, {"w": "效", "m": "①效命的事、任務；②成效、成功"}, {"w": "恥師", "m": "以向人學習為恥"}, {"w": "許行", "m": "戰國農家學者"}], "questions": [{"n": 12, "qtype": "單選", "stem": "下列選項「」中的字義解釋，何者錯誤？", "options": {"A": "民不易「物」，惟德繄「物」：第一個「物」是「享用祭物」，第二個「物」是「祭物」(《左傳‧宮之奇諫假道》)", "B": "願陛下託臣以討賊興復之「效」，不「效」，則治臣之罪：第一個「效」是「任務」，第二個「效」是「成功」(諸葛亮〈出師表〉)", "C": "愛其子，擇「師」而教之，於其身也，則恥「師」焉：第一個「師」是「老師」，第二個「師」是「學習」(韓愈〈師說〉)", "D": "陳相見許行而大悅，盡棄其「學」而「學」焉：第一個「學」是「學問」，第二個「學」是「學習」(《孟子‧滕文公上》)"}, "answer": "A", "explain": "題目問「錯誤」。(A)〈宮之奇諫假道〉「民不易物，惟德繄物」，意思是「百姓祭祀用的祭品並沒有不同，只有德行才是真正（決定神是否享用）的祭品」，兩個「物」都指「祭品」，選項說第一個是「享用祭物」，解釋錯了，所以是答案。(B)「託臣以討賊興復之效」的「效」是要我效命完成的任務；「不效」是沒有成功，正確。(C)「擇師而教之」的「師」是老師；「恥師焉」是以向人學習為恥，「師」作動詞「學習、從師」，正確。(D)「盡棄其學」的「學」是原本的學問，「而學焉」的「學」是向許行學習，正確。", "skill": "同一句出現兩個相同字，先判斷詞性：前面有「其」多是名詞，後面接「焉、之」多是動詞。"}], "difficulty": "中", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-13", "exam": "et101", "nums": [13], "form": "單題", "img": "img/et101-13.png", "source": "《詩經‧衛風‧伯兮》", "author": "", "genre": "古典詩詞曲", "types": ["字詞解釋", "詩詞賞析", "人物情感"], "passage": "伯兮朅兮，邦之桀兮。伯也執殳，為王前驅。自伯之東，首如飛蓬。豈無膏沐，誰適為容。其雨其雨，杲杲出日。願言思伯，甘心首疾。焉得諼草，言樹之背。願言思伯，使我心痗。", "translation": "我的丈夫多麼英武啊，是國家的傑出人才。他手拿長殳，替君王在前開路。自從他東征以後，我的頭髮亂得像飛散的蓬草。難道沒有髮油可以梳洗嗎？只是打扮給誰看呢？盼望下雨、盼望下雨，偏偏出來的是明亮的太陽。一心想念著他，想到頭痛也心甘情願。哪裡能找到忘憂草，把它種在北堂？一心想念著他，使我心裡憂傷成病。", "keywords": [{"w": "伯", "m": "妻子對丈夫的稱呼"}, {"w": "朅", "m": "英武雄壯的樣子"}, {"w": "桀", "m": "同「傑」，傑出的人"}, {"w": "殳", "m": "竹木做的長兵器"}, {"w": "膏沐", "m": "潤髮的油和洗頭"}, {"w": "適", "m": "取悅、為了"}, {"w": "杲杲", "m": "明亮的樣子"}, {"w": "諼草", "m": "萱草，即忘憂草"}, {"w": "背", "m": "北堂"}, {"w": "痗", "m": "憂傷成病"}], "questions": [{"n": 13, "qtype": "單選", "stem": "「伯兮朅兮，邦之桀兮。伯也執殳，為王前驅。自伯之東，首如飛蓬。豈無膏沐，誰適為容。其雨其雨，杲杲出日。願言思伯，甘心首疾。焉得諼草，言樹之背。願言思伯，使我心痗。」(《詩經‧伯兮》)依據上文，下列選項何者錯誤？", "options": {"A": "「朅」意指英武雄壯", "B": "「杲杲」意指黑暗", "C": "為婦人思念遠征丈夫之詩", "D": "「諼草」俗稱忘憂草"}, "answer": "B", "explain": "題目問「錯誤」。(B)「其雨其雨，杲杲出日」，盼下雨卻出了大太陽，「杲」字上面是日、下面是木，太陽升到樹梢，「杲杲」是明亮的樣子，不是黑暗，所以(B)錯，是答案。(A)「伯兮朅兮」的「朅」形容丈夫英武雄壯，正確。(C)全詩寫丈夫「為王前驅」、「自伯之東」，妻子在家無心打扮、相思成病，是思婦想念遠征丈夫的詩，正確。(D)「諼」是忘，「諼草」就是萱草，俗稱忘憂草，正確。", "skill": "看字形猜字義：「杲」日在木上＝明亮，「杳」日在木下＝昏暗，一組記起來。"}], "difficulty": "易", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-14", "exam": "et101", "nums": [14], "form": "單題", "img": "img/et101-14.png", "source": "蘇軾〈和子由澠池懷舊〉", "author": "蘇軾", "genre": "古典詩詞曲", "types": ["主旨寓意", "詩詞賞析", "比較閱讀"], "passage": "人生到處知何似？應似飛鴻踏雪泥。泥上偶然留指爪，鴻飛那復計東西！", "translation": "人生四處奔走，像什麼呢？應該就像飛鴻踩在雪地上吧。雪泥上偶然留下了爪印，鴻雁飛走後，哪裡還會在意這些痕跡在東邊還是西邊呢！", "keywords": [{"w": "飛鴻踏雪泥", "m": "比喻人生行跡偶然、短暫，後成語「雪泥鴻爪」"}, {"w": "那復", "m": "哪裡還"}, {"w": "計東西", "m": "計較東邊西邊"}], "questions": [{"n": 14, "qtype": "單選", "stem": "蘇軾〈和子由澠池懷舊〉：「人生到處知何似？應似飛鴻踏雪泥。泥上偶然留指爪，鴻飛那復計東西！」請問作者的人生態度與下列何者最為接近？", "options": {"A": "少壯不努力，老大徒傷悲", "B": "晝短苦夜長，何不秉燭遊", "C": "身似行雲常自在，心如流水任東西", "D": "今朝有酒今朝醉，明日愁來明日愁"}, "answer": "C", "explain": "蘇軾把人生比作飛鴻踏雪：留下爪印是偶然，飛走了也不必回頭計較在東在西，是一種隨緣自在、不執著的態度。(C)「身似行雲常自在，心如流水任東西」同樣是隨遇而安、任意東西，最接近，是答案。(A)「少壯不努力，老大徒傷悲」是勸人及早努力；(B)「晝短苦夜長，何不秉燭遊」是及時行樂；(D)「今朝有酒今朝醉」是消極、得過且過。這三者都沒有「不執著、隨緣」的意味。", "skill": "比較人生態度題，先用一個詞概括原詩（例如「隨緣」），再找選項中意思相同的關鍵字（自在、任東西）。"}], "difficulty": "中", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-15", "exam": "et101", "nums": [15], "form": "單題", "img": "img/et101-15.png", "source": "《世說新語‧品藻》", "author": "劉義慶", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "王黃門兄弟三人俱詣謝公，子猷、子重多說俗事，子敬寒溫而已。既出，坐客問謝公：「向三賢孰勝？」謝公曰：「小者最勝。」客曰：「何以知之？」謝公曰：「『吉人之辭寡，躁人之辭多』，推此知之。」", "translation": "王家三兄弟（王徽之、王操之、王獻之）一起去拜訪謝安。子猷、子重多半在談世俗瑣事，子敬只是問候幾句寒暖而已。他們離開後，在座的客人問謝安：「剛才三位賢士誰最好？」謝安說：「最小的那位最好。」客人問：「怎麼知道的？」謝安說：「『善良的人話少，浮躁的人話多』，從這點推想就知道了。」", "keywords": [{"w": "詣", "m": "拜訪"}, {"w": "寒溫", "m": "寒暄問候冷暖"}, {"w": "向", "m": "剛才"}, {"w": "孰勝", "m": "誰比較好"}, {"w": "吉人", "m": "善良賢德的人"}, {"w": "躁人", "m": "浮躁的人"}], "questions": [{"n": 15, "qtype": "單選", "stem": "「王黃門兄弟三人俱詣謝公，子猷、子重多說俗事，子敬寒溫而已。既出，坐客問謝公：『向三賢孰勝？』謝公曰：『小者最勝。』客曰：『何以知之？』謝公曰：『「吉人之辭寡，躁人之辭多」』，推此知之。」(《世說新語》)依據上文，子敬被謝安推為最勝的原因為何？", "options": {"A": "言笑自若", "B": "言寡而實", "C": "言方行圓", "D": "言聽計從"}, "answer": "B", "explain": "謝安的理由就是引用的那句話：「吉人之辭寡，躁人之辭多」。子敬只寒暄幾句，話少而得體，所以被評為最好，答案(B)言寡而實。(A)「言笑自若」是談笑神色如常，文中沒有寫他的神態；(C)「言方行圓」是說話正直、做事圓融，文中沒提到行為；(D)「言聽計從」是別人說什麼都照做，與文意無關。", "skill": "人物評價題，答案常常就藏在人物自己說的理由裡，先找「何以知之？」後面的回答。"}], "difficulty": "易", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-16", "exam": "et101", "nums": [16], "form": "單題", "img": "img/et101-16.png", "source": "沈括《夢溪筆談‧神奇》（試卷標作《天工開物‧隕石》）", "author": "沈括", "genre": "筆記小品", "types": ["句意理解", "文意推論"], "passage": "是時火息，視地中有一竅如杯大，極深。下視之，星在其中，熒熒然。良久漸暗，尚熱不可近。又久之，發其竅，深三尺餘，乃得一圓石，猶熱，其大如拳，一頭微銳，色如鐵，重亦如之。", "translation": "這時火已經熄滅，看見地上有一個像杯子那麼大的洞，非常深。往下看，那顆星就在洞裡，閃閃發光。過了很久才慢慢變暗，但還是燙得不能靠近。又過了好一段時間，挖開那個洞，深三尺多，才得到一塊圓石頭，仍然是熱的，大小像拳頭，一頭稍尖，顏色像鐵，重量也像鐵一樣。", "keywords": [{"w": "竅", "m": "洞、孔"}, {"w": "熒熒然", "m": "閃閃發光的樣子"}, {"w": "發", "m": "挖開"}, {"w": "銳", "m": "尖"}, {"w": "重亦如之", "m": "重量也像鐵"}], "questions": [{"n": 16, "qtype": "單選", "stem": "「是時火息，視地中有一竅如杯大，極深。下視之，星在其中，熒熒然。良久漸暗，尚熱不可近。又久之，發其竅，深三尺餘，乃得一圓石，猶熱，其大如拳，一頭微銳，色如鐵，重亦如之。」(《天工開物‧隕石》)依據上文，下列敘述何者錯誤？", "options": {"A": "記載隕石的溫度、重量", "B": "記載隕石的形狀、色澤", "C": "記載隕石墜地後的撞擊凹洞", "D": "記載隕石墜地時的撞擊聲音"}, "answer": "D", "explain": "題目問「錯誤」，逐項回原文找證據。(A)溫度：「尚熱不可近」「猶熱」；重量：「重亦如之」（像鐵一樣重），有記載。(B)形狀：「圓石」「其大如拳，一頭微銳」；色澤：「色如鐵」「熒熒然」，有記載。(C)撞擊凹洞：「地中有一竅如杯大，極深」「深三尺餘」，有記載。(D)引文從「是時火息」開始，寫的都是墜地之後的情形，完全沒有提到聲音，所以(D)錯，是答案。", "skill": "「何者錯誤」的閱讀題，把每個選項拆成關鍵詞（溫度、重量、形狀……），一個個回原文畫線，找不到證據的就是答案。"}], "difficulty": "易", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-19", "exam": "et101", "nums": [19], "form": "單題", "img": "img/et101-19.png", "source": "柳永〈雨霖鈴〉", "author": "柳永", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法", "人物情感"], "passage": "寒蟬淒切，對長亭晚，驟雨初歇。都門帳飲無緒，方留戀處，蘭舟摧發。執手相看淚眼，竟無語凝噎。", "translation": "秋蟬叫得淒涼急切，面對著傍晚的長亭，一陣急雨剛停。在京城外搭帳設宴送別，卻沒有心情喝酒；正依依不捨的時候，船家已經催著要出發了。兩人握著手，看著彼此的淚眼，竟然說不出一句話，喉嚨像被哽住了一樣。", "keywords": [{"w": "長亭", "m": "古代送別的地方"}, {"w": "帳飲", "m": "在郊外搭帳篷設宴餞別"}, {"w": "無緒", "m": "沒有心情"}, {"w": "蘭舟", "m": "船的美稱"}, {"w": "摧發", "m": "原詞作「催發」，催促出發"}, {"w": "凝噎", "m": "喉嚨哽住，說不出話"}], "questions": [{"n": 19, "qtype": "單選", "stem": "「寒蟬淒切，對長亭晚，驟雨初歇。都門帳飲無緒，方留戀處，蘭舟摧發。執手相看淚眼，竟無語凝噎。」(柳永〈雨霖鈴〉)依據上文，下列選項，何者最能顯示作者運用語文的矛盾張力以渲染離別之痛？", "options": {"A": "寒蟬−長亭", "B": "淒切−驟雨", "C": "都門−蘭舟", "D": "摧發−凝噎"}, "answer": "D", "explain": "「矛盾張力」是指兩個方向相反的力量互相拉扯。(D)「催發」是船家一直催、時間往前推，非走不可；「凝噎」是情感凝住、哽住說不出話，想停住卻停不了。外在的「快」和內在的「停」互相衝突，最能把離別之痛拉滿，是答案。(A)寒蟬、長亭都是送別的景物；(B)淒切、驟雨都在營造淒涼氣氛；(C)都門、蘭舟只是地點和交通工具。這三組都是同一方向的鋪陳，沒有對立的張力。", "skill": "找「張力」就找相反：一快一慢、一動一靜、一外一內，兩個詞方向相反的那組通常就是答案。"}], "difficulty": "中", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-20", "exam": "et101", "nums": [20], "form": "單題", "img": "img/et101-20.png", "source": "〈宋定伯捉鬼〉（舊題曹丕《列異傳》）", "author": "曹丕（舊題）", "genre": "寓言故事", "types": ["文意推論", "人物情感"], "passage": "行欲至宛市，定伯便擔鬼著肩上，急執之。鬼大呼，聲咋咋然，索下，不復聽之。徑之宛市中，下著地，化為一羊，便賣之。恐其變化，唾之。得錢千五百，乃去。", "translation": "快要走到宛城市集時，宋定伯就把鬼扛在肩上，緊緊抓住它。鬼大聲喊叫，發出咋咋的聲音，要求下來，定伯不再理會它。一路直接走到宛城市集中，把鬼放到地上，鬼變成了一隻羊，定伯就把它賣了。怕它再變化，就朝它吐口水。賣得一千五百錢，才離開。", "keywords": [{"w": "擔", "m": "扛"}, {"w": "執", "m": "抓住"}, {"w": "咋咋然", "m": "大聲叫喊的樣子"}, {"w": "索下", "m": "要求下來"}, {"w": "徑", "m": "直接"}, {"w": "唾", "m": "吐口水（相傳鬼怕人的唾液）"}], "questions": [{"n": 20, "qtype": "單選", "stem": "「行欲至宛市，定伯便擔鬼著肩上，急執之。鬼大呼，聲咋咋然，索下，不復聽之。徑之宛市中，下著地，化為一羊，便賣之。恐其變化，唾之。得錢千五百，乃去。」(曹丕〈宋定伯〉)依據上文，下列選項何者正確？", "options": {"A": "可見定伯肩上的鬼怪既緊張又害怕", "B": "反映定伯對於鬼怪抱持敬畏之心", "C": "鬼怪神通廣大，能擺脫定伯的束縛", "D": "害人的鬼怪最後得錢一千五百"}, "answer": "A", "explain": "(A)鬼被扛在肩上「大呼，聲咋咋然，索下」，又叫又求著要下來，可見它既緊張又害怕，正確，是答案。(B)定伯抓鬼、賣鬼、還對它吐口水，毫無敬畏之心，錯。(C)鬼一路沒能掙脫，最後被變成羊賣掉，並沒有擺脫束縛，錯。(D)「得錢千五百」的是宋定伯，不是鬼，錯。", "skill": "讀故事題先分清主詞：「得錢千五百，乃去」省略了主詞，往前找誰在做「賣之、唾之」的動作。"}], "difficulty": "易", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-21", "exam": "et101", "nums": [21], "form": "單題", "img": "img/et101-21.png", "source": "《易經‧繫辭上》", "author": "", "genre": "經典語錄", "types": ["句意理解", "字詞解釋"], "passage": "君子之道，或出或處，或默或語。二人同心，其利斷金。同心之言，其臭如蘭。", "translation": "君子處世的方式，有時出來做官，有時退隱在家；有時沉默，有時發言。兩個人同心協力，那股力量銳利得可以切斷金屬。同心之人說出來的話，那氣味就像蘭花一樣芬芳。", "keywords": [{"w": "出", "m": "出仕做官"}, {"w": "處", "m": "退隱在家"}, {"w": "利", "m": "銳利"}, {"w": "斷金", "m": "切斷金屬"}, {"w": "臭", "m": "音ㄒㄧㄡˋ，氣味"}, {"w": "蘭", "m": "蘭花，比喻芬芳"}], "questions": [{"n": 21, "qtype": "單選", "stem": "「君子之道，或出或處，或默或語。二人同心，其利斷金。同心之言，其臭如蘭。」(《易經．繫辭上》)依據上文，下列選項何者正確？", "options": {"A": "有志一同，可互蒙利益；臭味相投，則言不由衷", "B": "「其利斷金」意指志同之利可斷金錢引誘", "C": "同心志堅，其利可切金；言語相契，則芳香如蘭", "D": "「其臭如蘭」意指臭腐之味如蘭香般遠播"}, "answer": "C", "explain": "兩句的重點：「其利斷金」＝同心的力量鋒利到能切斷金屬；「其臭如蘭」＝同心的話氣味像蘭花一樣香，「臭」古代泛指氣味。(C)「同心志堅，其利可切金；言語相契，則芳香如蘭」完全吻合，是答案。(A)「臭味相投，則言不由衷」，原文說同心之言芬芳如蘭，不是言不由衷，錯。(B)「斷金」是切斷金屬、形容力量大，不是「斷絕金錢引誘」，錯。(D)把「臭」當成臭腐之味，錯，這裡的「臭」是中性的氣味。", "skill": "「臭」在古文多半是「氣味」（讀ㄒㄧㄡˋ），不一定是臭味；看到「其臭如蘭」要直接想到香氣。"}], "difficulty": "易", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-22", "exam": "et101", "nums": [22], "form": "單題", "img": "img/et101-22.png", "source": "柳宗元〈鈷鉧潭西小丘記〉", "author": "柳宗元", "genre": "山水遊記", "types": ["主旨寓意", "文意推論"], "passage": "噫！以茲丘之勝，致之灃鎬鄂杜，則貴遊之士爭買者，日增千金而愈不可得。今棄是州也，農夫、漁夫過而陋之，賈四百，連歲不能售，而我與深源、克己獨喜得之。是其果有遭乎？書於石，以賀茲丘之遭也。", "translation": "唉！憑這座小丘的美景，如果把它放在京城附近的灃、鎬、鄠、杜等地，那些愛遊玩的貴族爭著購買，價錢每天增加千金，反而越買不到。現在它被丟在這偏遠的永州，農夫、漁夫經過都看不起它，標價只要四百文，好幾年都賣不出去，卻只有我和李深源、元克己高興地買下它。這難道真的是它有了好的際遇嗎？我把這些寫在石頭上，來祝賀這座小丘遇到了知音。", "keywords": [{"w": "勝", "m": "美景"}, {"w": "致", "m": "放置"}, {"w": "灃鎬鄠杜", "m": "長安附近的地名，代指京城繁華地帶"}, {"w": "貴遊之士", "m": "喜好遊樂的達官貴族"}, {"w": "陋", "m": "輕視、看不起"}, {"w": "賈", "m": "同「價」"}, {"w": "售", "m": "賣出"}, {"w": "遭", "m": "遇合、好際遇"}], "questions": [{"n": 22, "qtype": "單選", "stem": "「噫！以茲丘之勝，致之灃鎬鄂杜，則貴遊之士爭買者，日增千金而愈不可得。今棄是州也，農夫、漁夫過而陋之，賈四百，連歲不能售，而我與深源、克己獨喜得之。是其果有遭乎？書於石，以賀茲丘之遭也。」(柳宗元〈鈷鉧潭西小丘記〉)依據上文，下列選項何者正確？", "options": {"A": "此文旨在說明小丘受到世俗大眾的賞識", "B": "作者的眼光比不上貴遊之士、農夫、漁夫", "C": "作者為爭買此地，費盡千金仍不可得", "D": "感慨小丘美景，若在都會應該價值不菲"}, "answer": "D", "explain": "這段的重點是對比：小丘在京城會被搶著買、價值千金；在永州卻被農夫漁夫看不起、四百文都賣不掉。柳宗元借小丘感慨自己有才卻被貶到偏遠之地。(D)「若在都會應該價值不菲」正是「致之灃鎬鄠杜……日增千金而愈不可得」，是答案。(A)小丘在永州「過而陋之」，並沒有受到世俗大眾賞識，錯。(B)真正懂得欣賞的是作者，眼光反而勝過那些人，錯。(C)作者是用四百文便宜買到，「爭買、千金不可得」說的是假設在京城的情形，錯。", "skill": "柳宗元的山水記常「借景寫己」：看到「棄、陋、不能售」這類字眼，就要聯想到他被貶、懷才不遇。"}], "difficulty": "中", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-24", "exam": "et101", "nums": [24], "form": "單題", "img": "img/et101-24.png", "source": "李白〈長干行〉", "author": "李白", "genre": "古典詩詞曲", "types": ["人物情感", "詩詞賞析"], "passage": "早晚下三巴，欲將書報家。相迎不道遠，直至長風沙。", "translation": "你什麼時候要從三巴順江而下，請先寫封信告訴家裡。我去迎接你，不會嫌路遠，會一直走到長風沙。", "keywords": [{"w": "早晚", "m": "何時"}, {"w": "三巴", "m": "巴郡、巴東、巴西，今四川東部一帶"}, {"w": "書", "m": "書信"}, {"w": "不道遠", "m": "不說遠、不嫌遠"}, {"w": "長風沙", "m": "地名，在今安徽安慶附近，距南京長干里有數百里"}], "questions": [{"n": 24, "qtype": "單選", "stem": "李白〈長干行〉：「早晚下三巴，欲將書報家。相迎不道遠，直至長風沙。」下列選項，何者最能表達詩中主角的心情寫照？", "options": {"A": "小心翼翼", "B": "坐困愁城", "C": "氣定神閒", "D": "迫不及待"}, "answer": "D", "explain": "妻子對遠行的丈夫說：你哪天要回來先寫信通知我，我不嫌路遠，要一路迎到幾百里外的長風沙。這份急切想見面的心情，就是(D)迫不及待。(A)小心翼翼是謹慎小心，詩中沒有；(B)坐困愁城是被愁緒困住、無計可施，但這幾句是積極地要去迎接；(C)氣定神閒是從容不迫，正好和急切相反。", "skill": "讀詩找「誇張的動作」：願意跑幾百里去接人，情緒就是「急切」，選項找同方向的詞。"}], "difficulty": "易", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-27", "exam": "et101", "nums": [27], "form": "單題", "img": "img/et101-27.png", "source": "宋玉〈登徒子好色賦〉", "author": "宋玉", "genre": "其他", "types": ["寫作手法"], "passage": "天下之佳人，莫若楚國；楚國之麗者，莫若臣里；臣里之美者，莫若臣東家之子。東家之子，增之一分則太長，減之一分則太短，著粉則太白，施朱則太赤；眉如翠羽，肌如白雪，腰如束素，齒如含貝；嫣然一笑，惑陽城，迷下蔡。", "translation": "天下的美女，沒有比得上楚國的；楚國的美女，沒有比得上我家鄉的；我家鄉的美女，沒有比得上我東邊鄰居家的女兒。這位鄰家女子，增高一分就太高，減少一分就太矮；搽上粉就太白，抹上胭脂就太紅。眉毛像翠鳥的羽毛，肌膚像白雪，腰身像一束白絹，牙齒像含著貝殼。她甜甜一笑，就能讓陽城、下蔡兩地的貴公子神魂顛倒。", "keywords": [{"w": "莫若", "m": "沒有比得上"}, {"w": "臣里", "m": "我的家鄉"}, {"w": "東家之子", "m": "東邊鄰家的女兒"}, {"w": "著粉", "m": "搽粉"}, {"w": "施朱", "m": "抹胭脂"}, {"w": "束素", "m": "一束白絹，形容腰細"}, {"w": "含貝", "m": "形容牙齒潔白整齊"}, {"w": "嫣然", "m": "笑容美好的樣子"}, {"w": "陽城、下蔡", "m": "楚國貴族封邑，代指貴族子弟"}], "questions": [{"n": 27, "qtype": "單選", "stem": "「天下之佳人，莫若楚國；楚國之麗者，莫若臣里；臣里之美者，莫若臣東家之子。東家之子，增之一分則太長，減之一分則太短，著粉則太白，施朱則太赤；眉如翠羽，肌如白雪，腰如束素，齒如含貝；嫣然一笑，惑陽城，迷下蔡。」(宋玉〈登徒子好色賦〉)上文未使用下列何種修辭技巧？", "options": {"A": "頂真", "B": "譬喻", "C": "層遞", "D": "回文"}, "answer": "D", "explain": "題目問「未使用」。(A)頂真：上一句結尾當下一句開頭，「莫若楚國；楚國之麗者」「莫若臣里；臣里之美者」「莫若臣東家之子。東家之子」，有使用。(B)譬喻：「眉如翠羽，肌如白雪，腰如束素，齒如含貝」，有使用。(C)層遞：天下→楚國→臣里→東家之子，範圍一層層縮小，有使用。(D)回文是句子正著讀、倒著讀都成立（如「人人為我，我為人人」），文中沒有，是答案。", "skill": "修辭判斷題先抓「形式」：重複接龍＝頂真、如／似＝譬喻、範圍逐步縮放＝層遞、正反都能讀＝回文。"}], "difficulty": "中", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-28", "exam": "et101", "nums": [28], "form": "單題", "img": "img/et101-28.png", "source": "綜合（多篇古文）", "author": "", "genre": "山水遊記", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "〈桃花源記〉", "m": "東晉陶淵明"}, {"w": "永州八記", "m": "唐代柳宗元被貶永州時所作八篇遊記"}, {"w": "〈滿井遊記〉", "m": "明代袁宏道"}, {"w": "〈紀水沙連〉", "m": "清代藍鼎元，記日月潭一帶風光"}], "questions": [{"n": 28, "qtype": "單選", "stem": "下列遊記作品與作者的對應關係，何者錯誤？", "options": {"A": "桃花源記：陶淵明", "B": "永州八記：柳宗元", "C": "滿井遊記：王安石", "D": "紀水沙連：藍鼎元"}, "answer": "C", "explain": "題目問「錯誤」。(C)〈滿井遊記〉的作者是明代公安派的袁宏道，寫北京郊外滿井的早春景色，不是王安石，所以是答案。(A)〈桃花源記〉是東晉陶淵明，正確。(B)「永州八記」是柳宗元被貶永州時寫的八篇山水遊記，正確。(D)〈紀水沙連〉是清代藍鼎元描寫日月潭一帶的遊記，正確。", "skill": "常考古典遊記一次背：〈桃花源記〉陶淵明、〈始得西山宴遊記〉等永州八記柳宗元、〈岳陽樓記〉范仲淹、〈醉翁亭記〉歐陽脩、〈晚遊六橋待月記〉〈滿井遊記〉袁宏道。"}], "difficulty": "易", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-29", "exam": "et101", "nums": [29], "form": "單題", "img": "img/et101-29.png", "source": "〈二十四節氣歌〉", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "春雨驚春清穀天，夏滿芒夏暑相連，秋處露秋寒霜降，冬雪雪冬小大寒。", "translation": "春季：立春、雨水、驚蟄、春分、清明、穀雨；夏季：立夏、小滿、芒種、夏至、小暑、大暑；秋季：立秋、處暑、白露、秋分、寒露、霜降；冬季：立冬、小雪、大雪、冬至、小寒、大寒。", "keywords": [{"w": "驚蟄", "m": "春雷驚醒冬眠的蟲"}, {"w": "芒種", "m": "有芒的穀物可以播種"}, {"w": "白露", "m": "天氣轉涼，露水凝結"}, {"w": "寒露", "m": "露水更冷，將要結霜"}], "questions": [{"n": 29, "qtype": "單選", "stem": "中國傳統文化中有〈二十四節氣歌〉：「春雨驚春清穀天，夏滿芒夏暑相連，秋處露秋寒霜降，冬雪雪冬小大寒。」下列關於節氣的名稱，何者錯誤？", "options": {"A": "「驚」指驚蟄", "B": "「芒」指芒種", "C": "「露」指露雨", "D": "「小」指小寒"}, "answer": "C", "explain": "每個字對應一個節氣的第一個字（或特別的字）。(A)「驚」＝驚蟄，正確。(B)「芒」＝芒種，正確。(C)「秋處露秋寒霜降」中的「露」是「白露」，沒有「露雨」這個節氣（「雨」是春天的「雨水」），所以(C)錯，是答案。(D)「小大寒」的「小」＝小寒，正確。", "skill": "節氣歌每句對應一季六個節氣，記住「立、分、至」是骨架，其餘就好填了。"}], "difficulty": "易", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-30", "exam": "et101", "nums": [30], "form": "單題", "img": "img/et101-30.png", "source": "小說發展史（話本與章回小說）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "話本", "m": "宋元說書人講故事的底本"}, {"w": "講史", "m": "說書的一類，講歷代興亡與戰爭"}, {"w": "章回小說", "m": "分回標目的長篇小說，由講史話本發展而來"}], "questions": [{"n": 30, "qtype": "單選", "stem": "從話本小說到章回小說的發展，下列選項何者正確？", "options": {"A": "話本是說書人的底本，說書是明代興起的娛樂活動", "B": "章回體小說由講史話本發展而來，講史多講歷史興亡和爭戰故事", "C": "《五代史平話》經說書人補充與文人加工，成為後來的《水滸傳》", "D": "章回小說是古典長篇小說的主要形式，與說書的回次毫無關聯"}, "answer": "B", "explain": "(B)章回小說是從宋元「講史」話本發展而來，講史多說歷代興亡、征戰故事（如《三國演義》就從講三國的話本演變），正確，是答案。(A)說書在唐代已有，宋代瓦舍勾欄中最興盛，不是明代才興起，錯。(C)《水滸傳》的雛形是《大宋宣和遺事》中的梁山故事；《五代史平話》講的是五代歷史，錯。(D)章回小說「分回」正是沿襲說書人一次講一段、「欲知後事如何，且聽下回分解」的習慣，不是毫無關聯，錯。", "skill": "章回小說的關鍵字：「宋元話本→明清章回」「講史→演義」，看到「毫無關聯」這種絕對說法要特別警覺。"}], "difficulty": "中", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-42", "exam": "et101", "nums": [42, 43, 44], "form": "題組", "img": "img/et101-42.png", "source": "歐陽修〈養魚記〉", "author": "歐陽修", "genre": "寓言故事", "types": ["字詞解釋", "主旨寓意", "文意推論"], "passage": "折檐之前有隙地，方四五丈，直對非非堂，修竹環繞蔭映，未嘗植物，因洿以為池。不方不圓，任其地形；不愁不築，全其自然。縱鍤以浚之，汲井以盈之。湛乎汪洋，晶乎清明，微風而波，無波而平，若星若月，精彩下入。予偃息其上，潛形於毫芒；循漪沿岸，渺然有江潮千里之想，斯足以舒憂隘而娛窮獨也。乃求漁者之罟，市數十魚，童子養之乎其中。童子以為斗斛之水不能廣其容，蓋活其小者而棄其大者。怪而問之，且以是對。嗟乎！其童子無乃嚚昏而無識矣乎！予觀巨魚枯涸在旁不得其所，而群小魚游戲乎淺狹之間，有若自足焉，感之而作〈養魚記〉。", "translation": "房屋折角的屋簷前有一塊空地，大約四五丈見方，正對著非非堂，四周有修長的竹子環繞遮蔭，從沒種過東西，我就把它挖成水池。不方也不圓，順著地形；池壁不砌磚也不築堤，保全它的自然樣貌。用鍬把它挖深，汲取井水把它注滿。水面深廣、晶瑩清澈，微風吹來就起波紋，沒風時就平靜如鏡，星星月亮的光彩都倒映在水中。我躺在池邊休息，連細微的身影都映在水裡；沿著岸邊看著漣漪，心中隱約有了面對千里江潮的遐想，這足以舒解我的憂悶，在困窮孤獨中自得其樂。\n於是向漁夫要來魚網，買了幾十條魚，叫童子把魚養在池裡。童子認為這一點點水不能容納所有的魚，就留下小魚、丟掉大魚。我覺得奇怪而問他，他就拿這個理由回答。唉！這童子難道是愚昧糊塗而沒有見識嗎！我看見大魚在旁邊乾枯，不得其所；而一群小魚卻在淺狹的池子裡嬉戲，好像很滿足的樣子，有感於此，寫了這篇〈養魚記〉。", "keywords": [{"w": "折檐", "m": "房屋轉角處的屋簷"}, {"w": "隙地", "m": "空地"}, {"w": "洿", "m": "挖地成池"}, {"w": "不愁不築", "m": "通行本作「不甃不築」，不砌磚、不築堤"}, {"w": "鍤", "m": "挖土的鍬"}, {"w": "浚", "m": "挖深"}, {"w": "偃息", "m": "仰臥休息"}, {"w": "潛形於毫芒", "m": "連細微的身形都映在水中"}, {"w": "憂隘", "m": "憂愁鬱悶"}, {"w": "窮獨", "m": "困窮孤獨"}, {"w": "罟", "m": "魚網"}, {"w": "斗斛之水", "m": "形容水量少"}, {"w": "嚚昏", "m": "愚昧糊塗"}], "questions": [{"n": 42, "qtype": "單選", "stem": "文中「予偃息其上，潛形於毫芒」的「偃」字，與下列何者意思不同？", "options": {"A": "息「偃」在床", "B": "「偃」鼠飲河", "C": "風行草「偃」", "D": "「偃」旗息鼓"}, "answer": "B", "explain": "「予偃息其上」的「偃」是「仰臥、躺下」。(A)「息偃在床」（《詩經‧北山》）是躺在床上休息，意思相同。(C)「風行草偃」是風吹過草就倒伏，(D)「偃旗息鼓」是把旗子放倒，都是「倒下、臥倒」，與躺下意思相近。(B)「偃鼠飲河」（《莊子‧逍遙遊》）的「偃鼠」是鼴鼠，是動物名稱，跟「躺下」完全無關，所以意思不同，是答案。", "skill": "一字多義題先找「詞性不同」的那個：其他都是動詞「倒、臥」，只有一個是名詞（動物名），它就最可疑。"}, {"n": 43, "qtype": "單選", "stem": "依據上文，下列何者是作者撰寫本文的動機？", "options": {"A": "藉買魚放生池中，積功德，做善事", "B": "有感於池水清澈明淨，漣漪激盪，微風輕送，景色動人", "C": "希望能朝夕欣賞非非堂的池畔美景", "D": "胸中有自足之感，即使心有憂隘，處境窮獨，也盡得舒展"}, "answer": "D", "explain": "作者在第一段結尾自己說了動機：「斯足以舒憂隘而娛窮獨也」，挖池養魚是為了排解憂悶、在困窮孤獨中自得其樂，(D)最符合，是答案。(A)作者買魚是要養在池中，文中沒有放生、積功德的意思。(B)池水清澈動人是描寫的景物，不是寫作動機。(C)文中沒有說希望朝夕欣賞非非堂的美景。", "skill": "問「動機、目的」時，找原文中「以……」「斯足以……」「所以……」的句子，作者通常會直接交代。"}, {"n": 44, "qtype": "單選", "stem": "作者在文中所描述的內容，不包括下列何者？", "options": {"A": "作者以順應自然地形的方式挖出水池", "B": "童子棄大魚而活小魚，是因為水池太小", "C": "作者感嘆無知的童子讓大魚不能得其所", "D": "作者以池中的小魚自比身分卑微，不受重視"}, "answer": "D", "explain": "題目問「不包括」。(A)「不方不圓，任其地形；不愁（甃）不築，全其自然」，順應自然地形挖池，有寫到。(B)「童子以為斗斛之水不能廣其容，蓋活其小者而棄其大者」，有寫到。(C)「其童子無乃嚚昏而無識矣乎！予觀巨魚枯涸在旁不得其所」，有寫到。(D)作者是為大魚「不得其所」而感嘆，暗喻賢才被棄；文中沒有拿小魚自比身分卑微，反而小魚「有若自足」象徵得志的小人，所以(D)不包括，是答案。", "skill": "寓言式散文要分清「誰象徵誰」：被同情的（大魚）通常是作者或賢才，被批評、自得的（小魚）多是小人。"}], "difficulty": "中", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-45", "exam": "et101", "nums": [45, 46, 47], "form": "題組", "img": "img/et101-45.png", "source": "《晏子春秋‧內篇雜下》", "author": "", "genre": "史傳人物", "types": ["句意理解", "文意推論", "人物情感"], "passage": "景公病疽在背，高子、國子請。公曰：「職當撫瘍。」高子進而撫瘍，公曰：「熱乎？」曰：「熱。」「熱何如？」曰：「如火。」「其色何如？」曰：「如未熟李。」「大小何如？」曰：「如豆。」「墮者何如？」曰：「如屨辨。」二子者出，晏子請見。公曰：「寡人有病，不能勝衣冠以出見夫子，夫子其辱視寡人乎？」晏子入，呼宰人具盥，御者具巾，刷手溫之，發席傅薦，跪請撫瘍。公曰：「其熱何如？」曰：「如日。」「其色何如？」曰：「如蒼玉。」「大小何如？」曰：「如璧。」「其墮者何如？」曰：「如珪。」晏子出，公曰：「吾不見君子，不知野人之拙也。」", "translation": "齊景公背上長了毒瘡，大夫高子、國子請求探望。景公說：「你們的職責正該撫摸察看瘡口。」高子上前撫摸瘡口，景公問：「熱嗎？」答：「熱。」「熱得像什麼？」答：「像火。」「顏色像什麼？」答：「像沒熟的李子。」「大小像什麼？」答：「像豆子。」「潰爛凹陷的地方像什麼？」答：「像破掉的鞋片。」兩人出去後，晏子請求晉見。景公說：「我生了病，沒辦法穿戴整齊出去見您，您願意委屈一下進來看我嗎？」晏子進門，叫掌膳食的人準備洗手的水，叫侍從準備手巾，洗淨雙手並把手弄溫，掀開席子、鋪好草墊，跪著請求撫摸瘡口。景公問：「熱得像什麼？」答：「像太陽。」「顏色像什麼？」答：「像青玉。」「大小像什麼？」答：「像璧玉。」「潰爛凹陷的地方像什麼？」答：「像珪玉。」晏子出去後，景公說：「我不見到君子，就不知道粗鄙之人有多笨拙啊。」", "keywords": [{"w": "疽", "m": "深而惡性的毒瘡"}, {"w": "職當撫瘍", "m": "你們的職責正該撫摸瘡口"}, {"w": "瘍", "m": "瘡"}, {"w": "屨辨", "m": "破鞋片"}, {"w": "墮者", "m": "瘡口潰爛凹陷的部分"}, {"w": "勝衣冠", "m": "承受得起穿戴衣冠"}, {"w": "辱", "m": "謙辭，委屈您"}, {"w": "宰人", "m": "掌管膳食的官"}, {"w": "具盥", "m": "準備洗手的水"}, {"w": "發席傅薦", "m": "掀開坐席，鋪上草墊"}, {"w": "珪", "m": "上尖下方的玉器"}, {"w": "野人", "m": "粗鄙無禮的人"}], "questions": [{"n": 45, "qtype": "單選", "stem": "依據上文，「夫子其辱視寡人乎」的解釋，下列選項何者正確？", "options": {"A": "夫子因此就輕視寡人了嗎", "B": "夫子願委屈入內探視寡人嗎", "C": "夫子的探望讓我感到屈辱", "D": "不會因這樣寡人就鄙視夫子"}, "answer": "B", "explain": "「夫子其辱視寡人乎」：「其」表示委婉的請求，「辱」是謙辭，意思是「讓您受委屈」，「視」是探視。整句是景公客氣地請晏子：您願意委屈自己進來看看我嗎？(B)是答案。(A)把「辱視」當作「輕視」，錯。(C)說探望讓景公覺得屈辱，與景公客氣邀請的語氣相反，錯。(D)主客顛倒，也不是「鄙視」的意思，錯。", "skill": "古文的「辱」常當謙辭（辱臨、辱教＝委屈您來、委屈您指教），不要直接翻成「侮辱」。"}, {"n": 46, "qtype": "單選", "stem": "張自烈《正字通》云：「癰之深者曰疽。」文中晏子以何者比喻疽之深者？", "options": {"A": "日", "B": "珪", "C": "蒼玉", "D": "璧"}, "answer": "B", "explain": "《正字通》說疽就是「深的癰」，所以題目問的是：瘡最深、潰爛凹陷的部分晏子比作什麼？對應景公問的「其墮者何如」，晏子答「如珪」，答案(B)。(A)「日」是比喻瘡的熱度（如日）；(C)「蒼玉」是比喻顏色；(D)「璧」是比喻大小。四個問題各對一個答案，一一對號就不會錯。", "skill": "問答排比的文章，把「問題→答案」列成對照表（熱→日、色→蒼玉、大小→璧、墮者→珪），再對照題目問的是哪一項。"}, {"n": 47, "qtype": "單選", "stem": "上文中景公所指的「野人」，下列選項何者正確？", "options": {"A": "高子", "B": "晏子", "C": "御者", "D": "宰人"}, "answer": "A", "explain": "景公最後說「吾不見君子，不知野人之拙也」，「君子」指說話得體、比喻典雅（日、蒼玉、璧、珪）的晏子；「野人」就是先前說話粗俗、比喻難聽（火、未熟李、豆、破鞋）的高子、國子，選項中只有(A)高子。(B)晏子是君子；(C)御者、(D)宰人只是幫忙準備器具的侍從，沒有被評論。", "skill": "「不見A，不知B」是對比句：A、B 是相反的兩方，先確定 A 是誰，B 就是另一邊。"}], "difficulty": "中", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et101-48", "exam": "et101", "nums": [48, 49, 50], "form": "題組", "img": "img/et101-48.png", "source": "崔述〈冉氏烹狗〉", "author": "崔述", "genre": "寓言故事", "types": ["文意推論", "主旨寓意", "人物情感"], "passage": "縣人冉氏，有狗而猛，遇行人輒搏噬之，往往為所傷，傷則主人躬詣請罪，出財救療，如是者數矣。冉氏以是頗患苦狗，然以其猛也，未忍殺，故置之。居數月，冉氏之鄰至，問其狗，曰：「烹之矣。」驚而詰其故，曰：「日者冉氏有盜，主人覺之，呼二子起，操械共逐之，盜驚而遁。主人疑狗之不吠也，呼之不應，遍索之無有也。將寢，聞臥床下若有微息者，燭之則狗也。卷曲蹲伏，不敢少轉側，垂頭閉目，若惟恐人之聞其聲者。主人曰：『嘻！吾向之隱忍不之殺也，為其有倉卒一旦之用也，惡知其搏行人則勇，而見盜則怯乎哉？』以是故，遂烹之也。」", "translation": "縣城裡有個姓冉的人，養了一隻很兇猛的狗，遇到路人就撲上去咬，常常有人被咬傷。被咬傷了，主人就親自上門賠罪，拿錢幫人醫治，這樣的事發生了好幾次。冉氏因此很苦惱這隻狗，但因為牠兇猛，捨不得殺，所以就留著牠。\n過了幾個月，冉氏的鄰居來了，（我）問起那隻狗，鄰居說：「煮來吃了。」（我）驚訝地追問原因，鄰居說：「前些日子冉家來了小偷，主人發覺了，叫兩個兒子起床，拿著棍棒一起追，小偷嚇得逃走了。主人奇怪狗怎麼沒叫，叫牠也不回應，到處找都找不到。準備睡覺時，聽到床底下好像有微弱的呼吸聲，拿燈一照，原來是狗。牠蜷縮蹲伏著，不敢稍微翻身，低著頭、閉著眼，好像只怕人聽到牠的聲音。主人說：『唉！我先前忍耐著不殺牠，是因為牠在緊急時可能派得上用場，哪知道牠咬路人很勇猛，看見小偷卻那麼膽怯呢？』因為這個緣故，就把牠煮了。」", "keywords": [{"w": "搏噬", "m": "撲上去咬"}, {"w": "躬詣", "m": "親自前往"}, {"w": "患苦", "m": "苦惱、厭惡"}, {"w": "置之", "m": "把牠留下來"}, {"w": "詰", "m": "追問"}, {"w": "日者", "m": "前些日子"}, {"w": "遁", "m": "逃走"}, {"w": "燭之", "m": "用燈火照牠"}, {"w": "倉卒一旦之用", "m": "緊急時的用處"}, {"w": "惡知", "m": "哪裡知道"}], "questions": [{"n": 48, "qtype": "單選", "stem": "冉氏最後決定將狗烹了，下列何者是主要原因？", "options": {"A": "咆哮喧鬧，惹惱鄰舍", "B": "屢傷行人，徒增困擾", "C": "臨危畏縮，有失職責", "D": "行止髒亂，有礙觀瞻"}, "answer": "C", "explain": "冉氏自己說了原因：原本忍著不殺牠，是指望「倉卒一旦之用」，沒想到「搏行人則勇，而見盜則怯」，真正該發揮作用時卻躲在床底下。所以主因是(C)臨危畏縮、沒盡到看門的職責。(B)屢傷行人雖然困擾，但冉氏當時「未忍殺，故置之」，不是烹狗的主因。(A)惹惱鄰舍、(D)髒亂有礙觀瞻，文中都沒有。", "skill": "「主要原因」要找事件的轉折點：之前忍住不殺、之後決定殺，中間發生的事就是主因。"}, {"n": 49, "qtype": "單選", "stem": "冉氏狗是屬於下列何種性格？", "options": {"A": "欺善怕惡", "B": "忠心護主", "C": "動心忍性", "D": "好勇鬥狠"}, "answer": "A", "explain": "這隻狗對手無寸鐵的路人「輒搏噬之」，遇到真正的壞人（盜賊）卻「卷曲蹲伏，不敢少轉側」，正是(A)欺善怕惡。(B)小偷來了躲起來，談不上忠心護主；(C)「動心忍性」是在困境中磨練心志，與狗的行為無關；(D)好勇鬥狠只說對了一半，牠見盜就怕，並不是真的勇猛。", "skill": "性格題要同時對照「兩種情境下的表現」：對誰兇、對誰怕，兩相對照就是答案。"}, {"n": 50, "qtype": "單選", "stem": "上文隱含以狗性諷喻人性之意，下列何者最符合其所影射的人性？", "options": {"A": "吃香喝辣，好逸惡勞", "B": "自私自利，枉顧公益", "C": "勇於私鬥，怯於公戰", "D": "違法亂紀，破壞秩序"}, "answer": "C", "explain": "狗「搏行人則勇，見盜則怯」，影射某些人在私下爭鬥、欺負弱者時很勇猛，到了需要為公眾挺身而出時卻膽怯退縮，正是(C)「勇於私鬥，怯於公戰」（《史記‧商君列傳》說商鞅變法後「民勇於公戰，怯於私鬥」，這裡正好反過來用）。(A)好逸惡勞是貪圖安逸，(B)自私自利、(D)違法亂紀，都沒有扣住「對內勇、對外怯」這個對比。", "skill": "寓言的諷喻題，把動物的行為換成「人」來說一遍：咬路人＝欺負自己人，怕盜賊＝面對真正敵人退縮。"}], "difficulty": "易", "label": "101二技", "year": 101, "kind": "二技"}, {"id": "et102-05", "exam": "et102", "nums": [5], "form": "單題", "img": "img/et102-05.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["文化常識", "詩詞賞析"], "passage": "(甲)獨在異鄉為異客，每逢佳節倍思親。遙知兄弟登高處，遍插茱萸少一人。\n(乙)爆竹聲中一歲除，春風送暖入屠蘇；千門萬戶曈曈日，總把新桃換舊符。\n(丙)競渡深悲千載冤，忠魂一去詎能還。國亡身殞今何有，只留離騷在世間。\n(丁)春城無處不飛花，寒食東風御柳斜。日暮漢宮傳蠟燭，輕煙散入五侯家。", "translation": "(甲)王維〈九月九日憶山東兄弟〉：獨自在他鄉作客，每到佳節就加倍思念親人。遙想兄弟們登高的時候，人人插著茱萸，只少了我一個。（重陽節）\n(乙)王安石〈元日〉：在爆竹聲中舊的一年過去了，春風把暖意吹進屠蘇酒裡；初升的太陽照著千家萬戶，家家都把舊桃符換成新的。（春節）\n(丙)文秀〈端午〉：龍舟競渡，深深哀悼千年前屈原的冤屈，忠魂一去哪能再回來？國家滅亡、自身殞命，如今還留下什麼？只留下〈離騷〉在人間。（端午節）\n(丁)韓翃〈寒食〉：春天的京城處處飛花，寒食節的東風吹斜了御苑的柳枝。傍晚宮中傳送蠟燭，輕煙飄散到權貴之家。（寒食節）", "keywords": [{"w": "茱萸", "m": "重陽節登高時插戴的植物"}, {"w": "屠蘇", "m": "元旦飲用的藥酒"}, {"w": "桃符", "m": "門上避邪的桃木板，後演變為春聯"}, {"w": "競渡", "m": "端午划龍舟"}, {"w": "寒食", "m": "清明前一兩天，禁火吃冷食"}, {"w": "傳蠟燭", "m": "寒食禁火，皇帝特賜近臣燭火"}], "questions": [{"n": 5, "qtype": "單選", "stem": "(甲)「獨在異鄉為異客，每逢佳節倍思親。遙知兄弟登高處，遍插茱萸少一人。」\n(乙)「爆竹聲中一歲除，春風送暖入屠蘇；千門萬戶曈曈日，總把新桃換舊符。」\n(丙)「競渡深悲千載冤，忠魂一去詎能還。國亡身殞今何有，只留離騷在世間。」\n(丁)「春城無處不飛花，寒食東風御柳斜。日暮漢宮傳蠟燭，輕煙散入五侯家。」\n上列詩歌各自敘述一年之中不同的節日，依時間前後順序排列，正確的選項是：", "options": {"A": "甲乙丙丁", "B": "乙甲丁丙", "C": "乙丁丙甲", "D": "乙丙甲丁"}, "answer": "C", "explain": "先找每首詩的節日線索：(乙)「爆竹」「屠蘇」「新桃換舊符」＝春節（正月初一）；(丁)明寫「寒食」（清明前，約農曆三月）；(丙)「競渡」「離騷」＝端午（五月五日）；(甲)「登高」「茱萸」＝重陽（九月九日）。依時間排列是乙→丁→丙→甲，答案(C)。(A)甲乙丙丁把重陽放最前；(B)乙甲丁丙把重陽放在寒食前；(D)乙丙甲丁把寒食放到最後，都不對。", "skill": "節日詩抓「習俗關鍵字」：爆竹屠蘇＝春節、寒食禁火＝寒食清明、競渡屈原＝端午、登高茱萸＝重陽、月圓團圓＝中秋。"}], "difficulty": "易", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-06", "exam": "et102", "nums": [6], "form": "單題", "img": "img/et102-06.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "故聖人以治天下為事者，惡得不禁惡而勸愛／參差荇菜，左右流之。窈窕淑女，寤寐求之／今者燭滅，有引妾衣者。妾援得其冠纓持之，趣火來上，視絕纓者／正所謂棋高一著，縛手縛腳", "translation": "所以把治理天下當作自己責任的聖人，怎麼能不禁止人們互相憎惡、而勸人彼此相愛呢／長短不齊的荇菜，順著水流左右去採。美好賢淑的女子，我醒著睡著都想追求她／剛才燭火熄滅時，有人拉扯我的衣服。我扯下他帽子上的帶子拿在手裡，請趕快拿燈火來，看看是誰的帽帶斷了／正如俗話說的，棋藝高人一步，對手就被綁手綁腳、施展不開", "keywords": [{"w": "惡得", "m": "惡讀ㄨ，怎麼能"}, {"w": "參差", "m": "讀ㄘㄣ ㄘ，長短不齊"}, {"w": "趣", "m": "通「促」，讀ㄘㄨˋ，催促、趕快"}, {"w": "一著", "m": "著讀ㄓㄠ，下棋的一步"}], "questions": [{"n": 6, "qtype": "單選", "stem": "下列選項「」內的文字，何者讀音正確？", "options": {"A": "故聖人以治天下為事者，「惡」得不禁惡而勸愛：ㄨˋ(《墨子．兼愛》)", "B": "參「差」荇菜，左右流之。窈窕淑女，寤寐求之：ㄔㄚ(《詩經．關雎》)", "C": "今者燭滅，有引妾衣者。妾援得其冠纓持之，「趣」火來上，視絕纓者：ㄘㄨˋ(劉向《說苑．復恩》)", "D": "正所謂棋高一「著」，縛手縛腳：ㄓㄨˋ(淩濛初《二刻拍案驚奇》卷二)"}, "answer": "C", "explain": "(C)〈絕纓〉故事中，楚王的美人說「趣火來上」，是「趕快拿燈火來」，「趣」通「促」，讀ㄘㄨˋ，正確，是答案。(A)「惡得不禁惡而勸愛」的第一個「惡」是疑問詞「怎麼、哪裡」，讀ㄨ，不是ㄨˋ。(B)「參差」是長短不齊，讀ㄘㄣ ㄘ，不是ㄔㄚ。(D)「棋高一著」的「著」指下棋的一步，讀ㄓㄠ，不是ㄓㄨˋ。", "skill": "破音字先判斷詞性和意思：當疑問詞的「惡」讀ㄨ、當厭惡讀ㄨˋ、當壞讀ㄜˋ，意思對了讀音就跟著對。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-07", "exam": "et102", "nums": [7], "form": "單題", "img": "img/et102-07.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "吾寧悃悃款款，朴以忠乎／刑罰不中，民無所錯手足／夫能不以遊墮事，而瀟然於山石草木之間者，惟此官也／凡人用物，蘄其質良價廉，此情之所必趨，勢之所必至", "translation": "我寧可誠懇忠實、質樸而忠心嗎／刑罰不得當，百姓就連手腳都不知道該往哪裡放／能夠不因為遊玩而荒廢公事，又能自在地徜徉在山石草木之間的，只有這種官職了／一般人使用東西，都希望品質好、價錢便宜，這是人情必然的趨向，也是情勢必然的結果", "keywords": [{"w": "悃悃款款", "m": "誠懇忠實的樣子"}, {"w": "朴", "m": "通「樸」，質樸"}, {"w": "錯", "m": "通「措」，放置"}, {"w": "墮", "m": "通「隳」，荒廢"}, {"w": "蘄", "m": "通「祈」，祈求"}], "questions": [{"n": 7, "qtype": "單選", "stem": "下列選項「」內的通用字，何者錯誤？", "options": {"A": "〈卜居〉：「吾寧悃悃款款，朴以忠乎？」「朴」通「僕」", "B": "《論語．子路》：「刑罰不中，民無所錯手足。」「錯」通「措」", "C": "〈滿井遊記〉：「夫能不以遊墮事，而瀟然於山石草木之間者，惟此官也。」「墮」通「隳」", "D": "〈用機器殖財養民說〉：「凡人用物，蘄其質良價廉，此情之所必趨，勢之所必至。」「蘄」通「祈」"}, "answer": "A", "explain": "題目問「錯誤」。(A)〈卜居〉「吾寧悃悃款款，朴以忠乎」，問的是：我寧可誠懇老實、質樸而忠心嗎？「朴」通「樸」，是質樸，不是通「僕」（僕人），所以錯，是答案。(B)「民無所錯手足」是百姓不知道手腳該往哪裡放，「錯」通「措」，正確。(C)「不以遊墮事」是不因為遊玩而荒廢公事，「墮」通「隳」，正確。(D)「蘄其質良價廉」是希望東西品質好、價錢便宜，「蘄」通「祈」，正確。", "skill": "判斷通同字：把通用後的字放回原句讀讀看，「朴以忠」換成「樸以忠」很通順，換成「僕以忠」就不通。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-09", "exam": "et102", "nums": [9], "form": "單題", "img": "img/et102-09.png", "source": "《莊子‧秋水》", "author": "莊子", "genre": "寓言故事", "types": ["句意理解", "主旨寓意"], "passage": "井蛙不可以語於海者，拘於虛也；夏蟲不可以語於冰者，篤於時也；曲士不可以語於道者，束於教也。", "translation": "不能跟井底的青蛙談論大海，因為牠受居住的地方限制；不能跟夏天的蟲談論冰雪，因為牠受生存的季節限制；不能跟見識淺陋的人談論大道，因為他被所受的教養束縛住了。", "keywords": [{"w": "虛", "m": "同「墟」，所居住的地方"}, {"w": "篤", "m": "固守、受限"}, {"w": "曲士", "m": "鄉曲之士，見識淺陋的人"}, {"w": "束於教", "m": "被所受的教育、禮教束縛"}], "questions": [{"n": 9, "qtype": "單選", "stem": "《莊子‧秋水》：「井蛙不可以語於海者，拘於虛也；夏蟲不可以語於冰者，篤於時也；曲士不可以語於道者，束於教也。」這段話的意思是：", "options": {"A": "君子無友不如己者，過則勿憚改。", "B": "坐井觀天，易致差迷，無從就正。", "C": "真積力久則入，活到老學到老。", "D": "作人不可狼狽為奸，結黨營私。"}, "answer": "B", "explain": "三個比喻都在說：見識被環境、時間、教養所限制，就無法理解更大的道理。(B)「坐井觀天，易致差迷，無從就正」，正是因眼界狹小而容易犯錯、也無從改正，最接近，是答案。(A)出自《論語‧學而》，講交友與改過；(C)講長期累積學習、活到老學到老；(D)講不可勾結作惡。這三項都和「受限於見識」無關。", "skill": "排比的寓言句，先抓三句共同的骨架（拘於、篤於、束於＝被限制），再找選項中同義的說法。"}], "difficulty": "易", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-10", "exam": "et102", "nums": [10], "form": "單題", "img": "img/et102-10.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "吾道一以貫之／果予以未時還家，而汝以辰時氣絕／余嘉其能行古道，作〈師說〉以貽之／古人秉燭夜遊，良有以也", "translation": "我的學說是用一個根本道理貫串起來的／果然我在未時回到家，而你在辰時就已經斷氣了／我讚許他能實行古人從師的正道，寫了這篇〈師說〉來送給他／古人拿著蠟燭在夜裡遊玩，確實是有原因的", "keywords": [{"w": "一以貫之", "m": "用一個道理貫串一切；以＝用"}, {"w": "以未時還家", "m": "在未時回到家；以＝在"}, {"w": "以貽之", "m": "來贈送他；以＝來"}, {"w": "良有以也", "m": "確實是有原因的；以＝原因"}], "questions": [{"n": 10, "qtype": "單選", "stem": "下列選項「」內的字義，何者作「在」的意思解釋？", "options": {"A": "吾道一「以」貫之", "B": "果予「以」未時還家，而汝「以」辰時氣絕。", "C": "余嘉其能行古道，作〈師說〉「以」貽之。", "D": "古人秉燭夜遊，良有「以」也。"}, "answer": "B", "explain": "(B)袁枚〈祭妹文〉「果予以未時還家，而汝以辰時氣絕」，意思是我在未時回到家，而你在辰時就斷氣了，兩個「以」都表示時間「在」，是答案。(A)《論語‧里仁》「吾道一以貫之」，「以」是「用」。(C)韓愈〈師說〉「作〈師說〉以貽之」，「以」是「來、用來」，連接目的。(D)李白〈春夜宴從弟桃花園序〉「良有以也」，「以」是名詞「原因」。", "skill": "「以」後面接時間詞（辰時、某年某月）時，多半就是「在」；接名詞多為「用」；放在兩個動作中間多為「來、而」。"}], "difficulty": "易", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-12", "exam": "et102", "nums": [12], "form": "單題", "img": "img/et102-12.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "今宵酒醒何處，楊柳岸，曉風殘月／回首向來蕭瑟處，歸去，也無風雨也無晴／少年聽雨歌樓上，紅燭昏羅帳／過盡千帆皆不是，斜暉脈脈水悠悠", "translation": "今晚酒醒時，我會在哪裡呢？大概是長著楊柳的岸邊，只有清晨的冷風和天邊的殘月／回頭看看剛才遇到風雨的地方，回去吧，對我來說既沒有風雨，也沒有晴天／年少時在歌樓上聽雨，紅燭的光昏昏地照著羅帳／上千艘船都開過去了，卻都不是心上人的船，只有夕陽含情斜照，江水悠悠流去", "keywords": [{"w": "過盡千帆皆不是", "m": "一艘艘船都過去了，卻都不是心上人的船"}, {"w": "斜暉脈脈", "m": "夕陽含情般地斜照"}, {"w": "蕭瑟處", "m": "風雨淒涼的地方"}], "questions": [{"n": 12, "qtype": "單選", "stem": "以下文句中，何者最能表現「期待終究落空」的心情：", "options": {"A": "今宵酒醒何處，楊柳岸，曉風殘月。(柳永〈雨霖鈴〉)", "B": "回首向來蕭瑟處，歸去，也無風雨也無晴。(蘇軾〈定風波〉)", "C": "少年聽雨歌樓上，紅燭昏羅帳。(蔣捷〈虞美人〉)", "D": "過盡千帆皆不是，斜暉脈脈水悠悠。(溫庭筠〈憶江南〉)"}, "answer": "D", "explain": "(D)溫庭筠〈憶江南〉寫女子倚樓盼望，看過了上千艘帆船，卻沒有一艘是心上人的，只剩夕陽斜照、江水悠悠，一整天的盼望終究落空，是答案。(A)柳永〈雨霖鈴〉寫離別後酒醒，只見楊柳岸、曉風殘月，是離別的孤寂，不是等待落空。(B)蘇軾〈定風波〉回頭看風雨之處，覺得也無風雨也無晴，是超然曠達。(C)蔣捷〈虞美人〉回憶少年時在歌樓聽雨的歡樂，是今昔對比的感慨。", "skill": "「期待落空」要同時有「期待」和「落空」：找出盼望的動作（看千帆）加上失望的結果（皆不是）的那一句。"}], "difficulty": "易", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-14", "exam": "et102", "nums": [14], "form": "單題", "img": "img/et102-14.png", "source": "對聯", "author": "", "genre": "其他", "types": ["典故出處", "文化常識"], "passage": "李白借問誰家好，劉伶還言此處佳。", "translation": "李白若要問哪一家的（酒）最好，劉伶會回答說這裡最好。", "keywords": [{"w": "李白", "m": "唐代詩人，嗜酒，杜甫稱「李白一斗詩百篇」"}, {"w": "劉伶", "m": "竹林七賢之一，嗜酒，作〈酒德頌〉"}, {"w": "借問", "m": "請問"}], "questions": [{"n": 14, "qtype": "單選", "stem": "某戶商家貼了一副對聯，上聯是「李白借問誰家好」，下聯是「劉伶還言此處佳」，則此商家所賣的商品最有可能是：", "options": {"A": "中藥", "B": "水果", "C": "酒", "D": "書"}, "answer": "C", "explain": "對聯中的兩位人物都是有名的酒徒：李白「斗酒詩百篇」，劉伶寫〈酒德頌〉、出門常帶一壺酒。上聯「借問誰家好」也讓人想到杜牧「借問酒家何處有」。所以這是酒店的對聯，答案(C)酒。(A)中藥、(B)水果、(D)書都和這兩位人物的典故無關。", "skill": "行業對聯題先認人物：李白、劉伶、杜康→酒；陸羽→茶；華佗、扁鵲→醫；魯班→木工。"}], "difficulty": "易", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-15", "exam": "et102", "nums": [15], "form": "單題", "img": "img/et102-15.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["典故出處", "詩詞賞析", "文化常識"], "passage": "鳴箏金粟柱，素手玉房前／嘈嘈切切錯雜彈，大珠小珠落玉盤／錦瑟無端五十絃，一絃一柱思華年／興來三弄有桓子，賦就一篇懷馬融", "translation": "彈奏著裝有金粟柱的箏，潔白的手在玉房前撥弄琴弦／粗重的聲音和細碎的聲音交錯彈奏，就像大大小小的珍珠落在玉盤上／精美的瑟無緣無故有五十根弦，每一根弦、每一個柱都讓人追想美好的年華／興致來了，就像桓伊那樣吹奏三曲笛子；寫成一篇賦，令人懷念作〈長笛賦〉的馬融", "keywords": [{"w": "箏", "m": "弦樂器"}, {"w": "嘈嘈切切", "m": "白居易〈琵琶行〉寫琵琶聲"}, {"w": "瑟", "m": "弦樂器，相傳有五十弦"}, {"w": "三弄", "m": "東晉桓伊善吹笛，曾為王徽之吹〈梅花三弄〉"}, {"w": "馬融", "m": "東漢學者，作〈長笛賦〉"}], "questions": [{"n": 15, "qtype": "單選", "stem": "下列敘述，何者是描寫管樂器的聲音？", "options": {"A": "鳴箏金粟柱，素手玉房前。", "B": "嘈嘈切切錯雜彈，大珠小珠落玉盤。", "C": "錦瑟無端五十絃，一絃一柱思華年。", "D": "興來三弄有桓子，賦就一篇懷馬融。"}, "answer": "D", "explain": "管樂器是用吹的（笛、簫、笙）。(D)「三弄」指東晉桓伊吹笛三弄的典故，「馬融」作有〈長笛賦〉，兩個典故都和笛子有關，是答案。(A)「鳴箏金粟柱」寫的是箏，屬弦樂器。(B)「嘈嘈切切錯雜彈，大珠小珠落玉盤」是〈琵琶行〉的琵琶聲，弦樂器。(C)「錦瑟無端五十絃」寫的是瑟，弦樂器，而且看到「絃」「彈」就知道是弦樂。", "skill": "先用字找樂器類別：出現「彈、弦（絃）、柱」多是弦樂；出現「吹、弄、笛、簫」多是管樂。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-16", "exam": "et102", "nums": [16], "form": "單題", "img": "img/et102-16.png", "source": "《禮記‧學記》", "author": "", "genre": "經典語錄", "types": ["主旨寓意", "文意推論"], "passage": "良冶之子，必學為裘；良弓之子，必學為箕；始駕馬者反之，車在馬前。", "translation": "好鐵匠的兒子，一定先學縫補皮衣；好弓匠的兒子，一定先學編製畚箕；剛開始學拉車的小馬，要反過來把牠繫在車後，讓車在馬的前面（跟著大馬看、跟著走）。", "keywords": [{"w": "冶", "m": "冶煉金屬的工匠"}, {"w": "裘", "m": "皮衣"}, {"w": "箕", "m": "柳條編的畚箕"}, {"w": "始駕馬者", "m": "剛學拉車的小馬"}, {"w": "反之", "m": "反過來繫在車後"}], "questions": [{"n": 16, "qtype": "單選", "stem": "〈學記〉：「良冶之子，必學為裘；良弓之子，必學為箕；始駕馬者反之，車在馬前。」旨在說明什麼的重要性？", "options": {"A": "觀摩示範", "B": "創新發明", "C": "血融於水", "D": "恢復道統"}, "answer": "A", "explain": "鐵匠之子先學補皮衣（把碎皮拼合，和補鍋的道理相通），弓匠之子先學編箕（把柳條彎曲，和揉製弓的道理相通），小馬先跟在車後看大馬怎麼拉車。三個例子都是從長輩的示範中觀察、模仿，循序漸進學會本事，所以強調(A)觀摩示範的重要。(B)創新發明，文中是學習既有技藝，不是發明；(C)血濃於水（選項作「血融於水」）講親情，與學習方法無關；(D)恢復道統是儒家傳承，與此無關。", "skill": "《學記》談的都是「教與學的方法」，看到「必學為……」「反之」這類例子，先往「學習方法」想。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-17", "exam": "et102", "nums": [17], "form": "單題", "img": "img/et102-17.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "諸侯以禮相與／失其所與／大塊假我以文章／假輿馬者，非利足也，而致千里／信可樂也／信非吾罪而棄逐兮／雲髻半偏新睡覺／睡覺寒燈裡", "translation": "諸侯之間依照禮節互相交往／失去了自己的盟友／大自然把美好的景色借給我們欣賞／借助車馬的人，並不是腳走得快，卻能到達千里之外／實在是值得快樂的事／確實不是我的罪過，卻被放逐／雲一般的髮髻半偏著，剛剛睡醒／在寒冷的燈光下睡醒過來", "keywords": [{"w": "相與", "m": "互相結交"}, {"w": "所與", "m": "結交、同盟的對象"}, {"w": "假我以文章", "m": "大自然給予我錦繡的景色；假＝給予"}, {"w": "假輿馬", "m": "借助車馬；假＝借助"}, {"w": "信可樂也", "m": "確實值得快樂"}, {"w": "睡覺", "m": "睡醒"}], "questions": [{"n": 17, "qtype": "單選", "stem": "下列「」內的字義，何者兩兩不同？", "options": {"A": "諸侯以禮相「與」(《禮記．禮運》)／失其所「與」(《左傳．燭之武退秦師》)", "B": "大塊「假」我以文章(李白〈春夜宴從弟桃花園序〉)／「假」輿馬者，非利足也，而致千里。(荀子〈勸學〉)", "C": "「信」可樂也(王羲之〈蘭亭集序〉)／「信」非吾罪而棄逐兮(屈原〈哀郢〉)", "D": "雲髻半偏新睡「覺」(白居易〈長恨歌〉)／睡「覺」寒燈裡(陸游〈夜遊宮〉)"}, "answer": "B", "explain": "題目問「兩兩不同」。(B)李白「大塊假我以文章」，是大自然「給予、借給」我美好的景色；荀子「假輿馬者」是「借助」車馬，一個是給出去、一個是憑藉利用，意思不同，是答案。(A)「諸侯以禮相與」是互相交往結交，「失其所與」是失去結交的盟友，都與「結交、親附」有關，意思相近。(C)兩個「信」都是「確實、的確」。(D)兩個「睡覺」都是「睡醒」，「覺」是醒來。", "skill": "「假」常見三義：借助（假舟楫）、給予（假我以文章）、虛假；注意主詞是「拿來用」還是「給別人」。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-18", "exam": "et102", "nums": [18], "form": "單題", "img": "img/et102-18.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "寫作手法"], "passage": "政通人和，百廢俱興／雖九死其猶未悔／不孝有三，無後為大／三折肱知為良醫", "translation": "政事順利、百姓和樂，各種荒廢的事都興辦起來了／即使死很多次，我也不後悔／不孝的事有三種，其中沒有後代最嚴重／手臂折斷過好幾次，就知道怎麼當個好醫生（比喻經驗多了自然精通）", "keywords": [{"w": "百廢俱興", "m": "各種荒廢的事都興辦起來；百＝虛指多"}, {"w": "九死", "m": "死很多次；九＝虛指極多"}, {"w": "不孝有三", "m": "不孝的事有三種"}, {"w": "三折肱", "m": "多次折斷手臂；三＝虛指多次"}], "questions": [{"n": 18, "qtype": "單選", "stem": "下列「」中的數字，何者非實數虛用？", "options": {"A": "政通人和，「百」廢俱興。(范仲淹〈岳陽樓記〉)", "B": "雖「九」死其猶未悔(屈原〈離騷〉)", "C": "不孝有「三」，無後為大。(《孟子．離婁》)", "D": "「三」折肱知為良醫(《左傳．定公十三年》)"}, "answer": "C", "explain": "題目問「非」實數虛用，也就是真的在算數的那個。(C)「不孝有三」，趙岐注明確列出三種：阿意曲從、家貧親老不為祿仕、不娶無子絕先祖祀，「三」是實數，是答案。(A)「百廢」不是剛好一百件，是虛指很多。(B)「九死」是死很多次，形容意志堅決，虛指。(D)「三折肱」是多次折斷手臂，久病成良醫，虛指多次。", "skill": "數字虛實的判斷：能具體列舉內容的是實數；誇張形容「很多」的（三、九、百、千、萬）多是虛數。"}], "difficulty": "易", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-19", "exam": "et102", "nums": [19], "form": "單題", "img": "img/et102-19.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["寫作手法", "詩詞賞析"], "passage": "滅燭憐光滿，披衣覺露滋／日暮鄉關何處是，煙波江上使人愁／穴去茅山近，江連巫峽長／春潮帶雨晚來急，野渡無人舟自橫", "translation": "吹熄蠟燭，更愛這滿屋的月光；披上衣服出門，才覺得露水漸漸濃重／天色已晚，我的故鄉在哪裡呢？江上煙霧籠罩的水波，讓人發愁／湖中的洞穴離茅山很近，江水一直連到遙遠的巫峽／春天的潮水夾帶著雨水，到傍晚流得更急；荒野的渡口沒有人，只有小船自己橫在水面上", "keywords": [{"w": "對仗", "m": "上下兩句字數相同、詞性相對、平仄相反"}, {"w": "鄉關", "m": "故鄉"}, {"w": "野渡", "m": "荒野的渡口"}], "questions": [{"n": 19, "qtype": "單選", "stem": "以對仗呈現文字排列形式上的優美，是中國古代詩歌的一大特色。下列詩句何者不是對句？", "options": {"A": "滅燭憐光滿，披衣覺露滋。(張九齡〈望月懷遠〉)", "B": "日暮鄉關何處是，煙波江上使人愁。(崔顥〈黃鶴樓〉)", "C": "穴去茅山近，江連巫峽長。(陰鏗〈渡青草湖〉)", "D": "春潮帶雨晚來急，野渡無人舟自橫。(韋應物〈滁州西澗〉)"}, "answer": "B", "explain": "對句要字字詞性相對。(B)崔顥〈黃鶴樓〉「日暮鄉關何處是，煙波江上使人愁」，「日暮」對「煙波」勉強，但「何處是」對「使人愁」詞性結構不同，是一句問、一句答的流水句，不是對句，是答案。(A)「滅燭／披衣」「憐／覺」「光滿／露滋」兩兩相對。(C)「穴／江」「去／連」「茅山／巫峽」「近／長」相對。(D)「春潮／野渡」「帶雨／無人」「晚來急／舟自橫」相對。", "skill": "檢查對仗就把兩句上下對齊，一個字一個字比詞性：名對名、動對動、形容詞對形容詞，對不起來的就不是對句。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-20", "exam": "et102", "nums": [20], "form": "單題", "img": "img/et102-20.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "主旨寓意"], "passage": "朱門酒肉臭，路有凍死骨。榮枯咫尺異，惆悵難再述／富家一碗燈，太倉一粒粟。貧家一碗燈，父子相聚哭。風流太守知不知？惟恨笙歌無妙曲／陶盡門前土，屋上無片瓦。十指不沾泥，鱗鱗居大廈／量力守故轍，豈不寒與飢？知音苟不存，已矣何所悲", "translation": "富貴人家酒肉多到發臭，路邊卻有凍死的屍骨。富貴和貧困只隔咫尺，卻天差地遠，讓人惆悵得說不下去／富人家點一碗燈油，就像大糧倉裡少一粒米；窮人家點一碗燈油，父子卻要聚在一起哭。風流的太守知不知道？他只遺憾宴會上的歌曲不夠美妙／燒陶的人挖光了門前的泥土，自己屋頂上卻沒有一片瓦。那些十根手指不沾泥土的人，卻住在屋瓦像魚鱗般排列的大房子裡／衡量自己的能力，堅守原本的路，難道不會受凍挨餓嗎？既然沒有知音，那就算了，又有什麼好悲傷的", "keywords": [{"w": "朱門", "m": "富貴人家"}, {"w": "榮枯咫尺異", "m": "富貴與貧困只隔咫尺，卻天差地遠"}, {"w": "太倉一粒粟", "m": "富家點一盞燈，就像大糧倉少一粒米，微不足道"}, {"w": "陶", "m": "燒製陶瓦"}, {"w": "鱗鱗", "m": "屋瓦像魚鱗般排列"}, {"w": "故轍", "m": "舊路，指固守的志節"}], "questions": [{"n": 20, "qtype": "單選", "stem": "以下詩句何者並未充分反映貧富階級的差異？", "options": {"A": "朱門酒肉臭，路有凍死骨。榮枯咫尺異，惆悵難再述。(杜甫〈自京赴奉先縣詠懷五百字〉)", "B": "富家一碗燈，太倉一粒粟。貧家一碗燈，父子相聚哭。風流太守知不知？惟恨笙歌無妙曲。(陳烈〈題燈〉)", "C": "陶盡門前土，屋上無片瓦。十指不沾泥，鱗鱗居大廈。(梅堯臣〈陶者〉)", "D": "量力守故轍，豈不寒與飢？知音苟不存，已矣何所悲。(陶潛〈詠貧士〉)"}, "answer": "D", "explain": "題目問「並未」反映貧富差異。(D)陶淵明〈詠貧士〉寫自己量力而行、堅守志節，雖然受凍挨餓也不悲傷，只寫貧士本身的安貧樂道，沒有和富人對照，是答案。(A)杜甫「朱門酒肉臭，路有凍死骨」直接對比富家與窮人。(B)陳烈〈題燈〉寫富家點燈微不足道、貧家點燈卻要父子哭，對比明顯。(C)梅堯臣〈陶者〉寫燒瓦的人屋上沒有片瓦，不沾泥的人卻住大廈，也是貧富對比。", "skill": "「反映貧富差異」必須同時出現兩種人；只寫一方的（只寫貧士）就是答案。"}], "difficulty": "易", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-21", "exam": "et102", "nums": [21], "form": "單題", "img": "img/et102-21.png", "source": "秦觀〈好事近‧夢中作〉", "author": "秦觀", "genre": "古典詩詞曲", "types": ["句意理解", "詩詞賞析"], "passage": "春路雨添花，花動一山春色。行到小溪深處，有黃鸝千百。飛雲當面化龍蛇，夭矯轉空碧。醉臥古藤陰下，了不知南北。", "translation": "春天的路上，一場雨讓花開得更多，花枝搖動，整座山都是春色。走到小溪深處，有成百上千的黃鸝鳥。天上的飛雲迎面變幻成龍蛇的樣子，矯健地在碧空中翻轉。我醉臥在古藤的濃蔭下，完全分不清東南西北了。", "keywords": [{"w": "添花", "m": "使花開得更多"}, {"w": "夭矯", "m": "屈伸自如、矯健的樣子"}, {"w": "空碧", "m": "碧藍的天空"}, {"w": "了不知", "m": "完全不知道"}], "questions": [{"n": 21, "qtype": "單選", "stem": "請將秦觀〈好事近〉詞依詞牌格律加上標點符號斷句，下列選項何者正確？", "options": {"A": "春路雨，添花花動，一山春色。行到小溪深處，有黃鸝千百。飛雲當面，化龍蛇夭矯，轉空碧。醉卧古藤陰下了，不知南北。", "B": "春路雨添花，花動一山，春色行到小溪，深處有黃鸝。千百飛雲，當面化龍蛇，夭矯轉空碧。醉卧古藤陰，下了不知南北。", "C": "春路雨添花，花動一山春色。行到小溪深處，有黃鸝千百。飛雲當面化龍蛇，夭矯轉空碧。醉卧古藤陰下，了不知南北。", "D": "春路雨，添花花動一山，春色行到小溪深處，有黃鸝千百飛。雲當面化龍蛇，夭矯轉空碧。醉卧古藤陰下了，不知南北。"}, "answer": "C", "explain": "〈好事近〉的句式是：上片五、六、六、五字；下片七、五、六、五字。(C)「春路雨添花（5），花動一山春色（6）。行到小溪深處（6），有黃鸝千百（5）。飛雲當面化龍蛇（7），夭矯轉空碧（5）。醉臥古藤陰下（6），了不知南北（5）」，句式和文意都通順，是答案。(A)「醉臥古藤陰下了」把「了」切到上句，文意不通，且「飛雲當面」斷開也不合句式。(B)「春色行到小溪」「千百飛雲」斷句錯亂，主語不明。(D)「有黃鸝千百飛。雲當面化龍蛇」把「飛雲」拆開，破壞詞意。", "skill": "斷句題先看「一個意思完整的單位」：「飛雲」「了不知」這類固定詞組不能拆，再對照字數是否整齊對稱。"}], "difficulty": "難", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-23", "exam": "et102", "nums": [23], "form": "單題", "img": "img/et102-23.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["寫作手法", "詩詞賞析"], "passage": "白髮三千丈，緣愁似箇長／桃李春風一杯酒，江湖夜雨十年燈／恨無長劍一千仞，劃斷頑雲看睛碧／安得壯士挽天河，淨洗甲兵長不用", "translation": "白髮有三千丈那麼長，是因為憂愁也這麼長／當年在桃李盛開的春風中一起喝酒；分別後各自漂泊江湖，十年來在夜雨中對著孤燈／只恨沒有一把一千仞長的寶劍，劈開頑固的烏雲，好看見晴朗的碧空／哪裡能找到壯士，把天上的銀河拉下來，把鎧甲兵器洗乾淨，永遠不再使用", "keywords": [{"w": "緣愁似箇長", "m": "因為憂愁才有這麼長"}, {"w": "仞", "m": "古代長度單位，一仞約七或八尺"}, {"w": "挽天河", "m": "拉來天上的銀河"}, {"w": "甲兵", "m": "鎧甲和兵器"}], "questions": [{"n": 23, "qtype": "單選", "stem": "古詩詞中，作者常以不合理的誇張，加上無理的奇想，以顯生動。下列何者非使用此種技巧？", "options": {"A": "白髮三千丈，緣愁似箇長。(李白〈秋浦歌〉)", "B": "桃李春風一杯酒，江湖夜雨十年燈。(黃庭堅〈寄黃幾復〉)", "C": "恨無長劍一千仞，劃斷頑雲看睛碧。(李沇〈秋霖〉)", "D": "安得壯士挽天河，淨洗甲兵長不用。(杜甫〈洗兵行〉)"}, "answer": "B", "explain": "題目問「非」誇張奇想。(B)黃庭堅〈寄黃幾復〉「桃李春風一杯酒，江湖夜雨十年燈」，用兩組意象對比當年相聚飲酒與十年分離各自漂泊，寫的是真實的人生境遇，沒有不合理的誇張，是答案。(A)白髮長到三千丈，極度誇張。(C)想要一千仞的長劍劈開烏雲，奇想加誇張。(D)要壯士把天上銀河拉下來洗淨兵器，同樣是無理的奇想。", "skill": "「誇張奇想」的句子放到現實中一定做不到（三千丈白髮、千仞劍、挽天河），能真實發生的那句就是答案。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-24", "exam": "et102", "nums": [24], "form": "單題", "img": "img/et102-24.png", "source": "出處待查（古人語）", "author": "", "genre": "經典語錄", "types": ["句意理解"], "passage": "讀書可不死，讀書可忘貧，至若不讀書，便是貧死人。", "translation": "讀書可以讓人（精神）不朽，讀書可以讓人忘記貧窮；至於不讀書的人，就是精神貧乏、活著如同死去的人。", "keywords": [{"w": "不死", "m": "精神長存、不朽"}, {"w": "忘貧", "m": "忘記物質上的貧窮"}, {"w": "至若", "m": "至於"}, {"w": "貧死人", "m": "心靈貧乏、雖生猶死的人"}], "questions": [{"n": 24, "qtype": "單選", "stem": "古人有云：「讀書可不死，讀書可忘貧，至若不讀書，便是貧死人。」的意思是：", "options": {"A": "年壽有時而盡，榮樂止乎其身，唯讀書可求得心靈富足。", "B": "貧者讀書而致富，富者讀書而永生。", "C": "人是活的，書是死的，盡信書，不如無書。", "D": "生也有涯，而知也無涯，皓首窮經，貧寒以終。"}, "answer": "A", "explain": "這句話不是說讀書能長生、能發財，而是說讀書讓人精神充實、心靈富足，就能超越物質的貧窮與生命的有限；不讀書的人才是真正貧乏。(A)「年壽有時而盡，榮樂止乎其身，唯讀書可求得心靈富足」，點出生命、富貴都有限，只有讀書帶來心靈富足，最符合，是答案。(B)把「不死、忘貧」照字面解成致富、永生，錯。(C)「盡信書不如無書」是勸人不要盲目相信書，與原意無關。(D)「皓首窮經，貧寒以終」是說讀一輩子書而窮死，與原意相反。", "skill": "格言常用「誇飾」表達精神層面：「不死」是精神不朽，「忘貧」是心靈富足，不要照字面當成物質上的好處。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-26", "exam": "et102", "nums": [26], "form": "單題", "img": "img/et102-26.png", "source": "國學常識", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "文房四寶", "m": "筆、墨、紙、硯"}, {"w": "四君子", "m": "梅、蘭、竹、菊"}, {"w": "歲寒三友", "m": "松、竹、梅"}, {"w": "元曲四大家", "m": "關漢卿、馬致遠、白樸、鄭光祖"}, {"w": "玉茗堂四夢", "m": "明代湯顯祖的四部劇作，又稱「臨川四夢」"}], "questions": [{"n": 26, "qtype": "單選", "stem": "關於專有名詞的敘述，下列選項，何者錯誤？", "options": {"A": "文房四寶：筆、墨、紙、硯", "B": "歲寒四友：梅、蘭、竹、菊", "C": "元曲四大家：關漢卿、馬致遠、白樸、張可久", "D": "玉茗堂四夢：《牡丹亭》、《南柯記》、《邯鄲記》、《紫釵記》"}, "answer": "C", "explain": "題目問「錯誤」。(C)元曲四大家是關漢卿、馬致遠、白樸、鄭光祖；張可久是元代散曲名家，但不在四大家之列，所以(C)錯，是答案。(A)文房四寶是筆、墨、紙、硯，正確。(D)湯顯祖住處名「玉茗堂」，四部劇作《牡丹亭》、《南柯記》、《邯鄲記》、《紫釵記》合稱玉茗堂四夢，正確。(B)要特別注意：梅蘭竹菊一般稱為「四君子」，「歲寒三友」則是松、竹、梅；「歲寒四友」是比較少見的說法，本題以錯得最明確的(C)為答案。", "skill": "「四大家」「三友」「四君子」這類數字常識最容易被偷換一個人或一樣東西，背的時候要整組背、記住容易混淆的替身（張可久、松）。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-27", "exam": "et102", "nums": [27], "form": "單題", "img": "img/et102-27.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文化常識"], "passage": "本無塵土氣，自在水雲鄉。楚楚淨如拭，亭亭生妙香／高節人相重，虛心世所知。鳳凰佳可食，一去一來儀／枝鬥纖腰葉鬥眉，春來何處不如絲。霸陵原上多離別，少有長條拂地垂／落盡殘紅始吐芳，佳名喚作百花王。競誇天下無雙豔，獨占人間第一香", "translation": "本來就沒有塵土的俗氣，自在地生長在水雲之鄉。清秀潔淨得像擦拭過一樣，挺直地散發美妙的香氣（蓮花）／高潔的節操受人敬重，虛心的品格世人皆知。它的果實是鳳凰愛吃的好食物，引得鳳凰飛來飛去（竹子）／枝條和美人比細腰，葉子和美人比眉毛，春天一到，哪裡不是柔細如絲？霸陵原上離別的人太多，枝條都被折去送別，很少有長長的枝條垂到地上（楊柳）／等百花凋謝殆盡才開始吐露芬芳，美名叫做「百花王」。人人爭相誇讚它是天下無雙的豔麗，獨占人間第一等的香氣（牡丹）", "keywords": [{"w": "亭亭", "m": "直立的樣子，常形容荷花"}, {"w": "高節、虛心", "m": "竹子有節、中空"}, {"w": "鳳凰佳可食", "m": "相傳鳳凰非竹實不食"}, {"w": "霸陵", "m": "長安東郊，古人在此折柳送別"}, {"w": "百花王", "m": "牡丹的美稱"}], "questions": [{"n": 27, "qtype": "單選", "stem": "下列詩文與植物的對應關係，何者正確？", "options": {"A": "本無塵土氣，自在水雲鄉。楚楚淨如拭，亭亭生妙香。／楊柳", "B": "高節人相重，虛心世所知。鳳凰佳可食，一去一來儀。／蓮花", "C": "枝鬥纖腰葉鬥眉，春來何處不如絲。霸陵原上多離別，少有長條拂地垂。／竹子", "D": "落盡殘紅始吐芳，佳名喚作百花王。競誇天下無雙豔，獨占人間第一香。／牡丹"}, "answer": "D", "explain": "(D)「佳名喚作百花王」「天下無雙豔」，牡丹被稱為花王，對應正確，是答案（此詩為唐代皮日休〈牡丹〉）。(A)「自在水雲鄉」「楚楚淨如拭，亭亭生妙香」，生在水中、潔淨有香氣，寫的是蓮花，不是楊柳。(B)「高節」「虛心」、鳳凰吃的竹實，寫的是竹子，不是蓮花。(C)「纖腰」「如絲」「長條拂地垂」、霸陵送別，寫的是楊柳，不是竹子。", "skill": "詠物詩抓物的「特徵詞」：虛心有節＝竹、出水亭亭＝蓮、長條如絲＝柳、花王國色＝牡丹、暗香疏影＝梅。"}], "difficulty": "易", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-28", "exam": "et102", "nums": [28], "form": "單題", "img": "img/et102-28.png", "source": "綜合（成語）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "", "translation": "", "keywords": [{"w": "兵", "m": "①兵器 ②士兵 ③軍事、用兵"}, {"w": "秣馬厲兵", "m": "餵飽馬、磨利兵器"}, {"w": "棄甲曳兵", "m": "丟下盔甲、拖著兵器（逃跑）"}, {"w": "兵銷革偃", "m": "銷毀兵器、收起甲冑，指停止戰爭"}], "questions": [{"n": 28, "qtype": "單選", "stem": "下列選項「」內的字義，何者兩兩相異？", "options": {"A": "秣馬厲「兵」／短「兵」相接", "B": "棄甲曳「兵」／「兵」銷革偃", "C": "「兵」疲食絕／「兵」驍將勇", "D": "「兵」不厭詐／「兵」強馬壯"}, "answer": "D", "explain": "題目問「兩兩相異」。(D)「兵不厭詐」的「兵」是用兵作戰、軍事；「兵強馬壯」的「兵」是士兵，意思不同，是答案。(A)「秣馬厲兵」磨利兵器、「短兵相接」刀劍等短兵器相交，都是「兵器」。(B)「棄甲曳兵」拖著兵器、「兵銷革偃」銷毀兵器，都是「兵器」。(C)「兵疲食絕」士兵疲憊、「兵驍將勇」士兵勇猛，都是「士兵」。", "skill": "「兵」的本義是兵器（字形是雙手持斧），後來才引申為士兵、軍事；先問「是東西、是人、還是打仗這件事」。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-30", "exam": "et102", "nums": [30], "form": "單題", "img": "img/et102-30.png", "source": "朱光潛〈當局者迷，旁觀者清——藝術和實際人生的距離〉", "author": "朱光潛", "genre": "其他", "types": ["字詞解釋", "文意推論"], "passage": "有所為而為／無所為而為", "translation": "有所為而為：帶著某種目的（功利）去做。無所為而為：不帶任何功利目的去做。", "keywords": [{"w": "為（ㄨㄟˋ）", "m": "為了，目的"}, {"w": "為（ㄨㄟˊ）", "m": "做"}, {"w": "無所為而為", "m": "不為任何目的而做，指純粹的審美態度"}], "questions": [{"n": 30, "qtype": "單選", "stem": "「持實用的態度看事物，它們都祇是實際生活的工具或障礙物，都祇能引起欲念或嫌惡。要見出事物本身的美，我們一定要從實用世界跳開，以『□□□□□』的精神欣賞它們本身的形相。」(朱光潛〈當局者迷，旁觀者清－藝術和實際人生的距離〉)文中缺空的語詞，下列何者最為恰當？", "options": {"A": "有所為而為", "B": "為其所不為", "C": "無所為而為", "D": "為其所當為"}, "answer": "C", "explain": "前文說用實用態度看事物，只會引起欲念或嫌惡；要看見事物本身的美，就要「從實用世界跳開」，也就是不帶功利目的地去欣賞。(C)「無所為而為」是不為了什麼目的而做，正符合，是答案。(A)「有所為而為」是帶著目的去做，正是作者要跳開的實用態度。(B)「為其所不為」是做自己原本不做的事，(D)「為其所當為」是做應該做的事，都是道德、行動層面，與審美態度無關。", "skill": "填空題先看空格前後的「轉折」：「要……一定要從實用世界跳開」，答案就是「實用」的反面。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-31", "exam": "et102", "nums": [31], "form": "單題", "img": "img/et102-31.png", "source": "姜夔〈揚州慢〉", "author": "姜夔", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文意推論"], "passage": "淮左名都，竹西佳處，解鞍少駐初程。過春風十里，盡薺麥青青。自胡馬、窺江去後，廢池喬木，猶厭言兵。漸黃昏、清角吹寒，都在空城。杜郎俊賞，算而今、重到須驚。縱豆蔻詞工，青樓夢好，難賦深情。二十四橋仍在，波心蕩、冷月無聲。念橋邊紅藥，年年知為誰生？", "translation": "揚州是淮南東路的名城，竹西亭是風景優美的地方，我在旅程之初解下馬鞍稍作停留。走過昔日繁華的十里長街，如今只見一片青青的薺菜和麥子。自從金兵侵犯長江一帶離去以後，連荒廢的池塘和高大的古樹都厭惡再談起戰爭。黃昏漸近，淒清的號角聲在寒風中吹響，迴盪在這座空城裡。當年杜牧欣賞揚州的風光，如果他今天再來，一定會大吃一驚。縱使他有寫「豆蔻」的好文筆、有「青樓夢」的好詩句，也難以寫出此刻的深沉感傷。二十四橋還在，橋下水波蕩漾，冷清的月影無聲地映在水中。想那橋邊的紅芍藥，年年開花，又是為誰而開呢？", "keywords": [{"w": "淮左", "m": "淮南東路，宋代行政區，揚州在此"}, {"w": "竹西", "m": "竹西亭，揚州名勝"}, {"w": "春風十里", "m": "杜牧詩「春風十里揚州路」，指昔日繁華大街"}, {"w": "薺麥", "m": "薺菜和麥子，形容荒涼"}, {"w": "胡馬窺江", "m": "金兵南侵到長江邊"}, {"w": "清角", "m": "淒清的號角聲"}, {"w": "杜郎", "m": "唐代詩人杜牧"}, {"w": "紅藥", "m": "紅芍藥"}], "questions": [{"n": 31, "qtype": "單選", "stem": "姜夔〈揚州慢〉：「淮左名都，竹西佳處，解鞍少駐初程。過春風十里，盡□□□□。自胡馬、窺江去後，廢池喬木，□□□□。漸黃昏、清角吹寒，都在空城。杜郎俊賞，算而今、□□□□。縱豆蔻詞工，青樓夢好，難賦深情。二十四橋仍在，波心蕩、□□□□。念橋邊紅藥，年年知為誰生？」文中□內的語詞，依序填入，下列何者最為恰當？", "options": {"A": "重到須驚／冷月無聲／薺麥青青／猶厭言兵", "B": "薺麥青青／猶厭言兵／重到須驚／冷月無聲", "C": "猶厭言兵／薺麥青青／重到須驚／冷月無聲", "D": "猶厭言兵／薺麥青青／冷月無聲／重到須驚"}, "answer": "B", "explain": "依文意一格格填：(1)「過春風十里，盡＿」，昔日繁華大街現在長滿野菜麥子，填「薺麥青青」。(2)「廢池喬木，＿」，連池塘樹木都厭惡談起戰爭，填「猶厭言兵」。(3)「杜郎俊賞，算而今、＿」，杜牧若再來一定吃驚，填「重到須驚」。(4)「二十四橋仍在，波心蕩、＿」，橋下水波中只有冷月無聲，填「冷月無聲」。順序是薺麥青青／猶厭言兵／重到須驚／冷月無聲，答案(B)。(A)把「重到須驚」放第一格，但「盡重到須驚」不通；(C)(D)第一格填「猶厭言兵」，「盡猶厭言兵」不通，而且(D)把「冷月」和「重到」顛倒。", "skill": "詞句填空先處理最有把握的一格（例如「盡＿」後面要接景物），往往一格就能刪掉大半選項。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-32", "exam": "et102", "nums": [32], "form": "單題", "img": "img/et102-32.png", "source": "綜合（多篇古文）", "author": "", "genre": "經典語錄", "types": ["典故出處", "文化常識"], "passage": "鍥而舍之，朽木不折；鍥而不舍，金石可鏤／勿以善小而不為，勿以惡小而為之／夫以銅為鏡，可以正衣冠；以古為鏡，可以知興替；以人為鏡，可以明得失／蓋文章，經國之大業，不朽之盛事", "translation": "雕刻到一半就放棄，連腐朽的木頭也刻不斷；堅持刻下去不放棄，連金屬石頭都能雕出花紋／不要因為善事小就不去做，不要因為壞事小就去做／用銅當鏡子，可以整理衣帽；用歷史當鏡子，可以知道國家興衰的道理；用人當鏡子，可以明白自己的得失／文章是治理國家的偉大事業，是可以永垂不朽的盛事", "keywords": [{"w": "鍥", "m": "刻"}, {"w": "鏤", "m": "雕刻"}, {"w": "興替", "m": "興盛和衰敗"}, {"w": "經國之大業", "m": "治理國家的大事業"}], "questions": [{"n": 32, "qtype": "單選", "stem": "(甲)「鍥而舍之，朽木不折；鍥而不舍，金石可鏤。」這是荀子的主張。\n(乙)「勿以善小而不為，勿以惡小而為之。」這是諸葛亮的主張。\n(丙)「夫以銅為鏡，可以正衣冠；以古為鏡，可以知興替；以人為鏡，可以明得失。」這是魏徵的主張。\n(丁)「蓋文章，經國之大業，不朽之盛事。」這是曹丕的主張。\n以上各項敘述，何者正確？", "options": {"A": "甲乙", "B": "乙丙", "C": "丙丁", "D": "甲丁"}, "answer": "D", "explain": "逐句檢查出處：(甲)「鍥而舍之，朽木不折；鍥而不舍，金石可鏤」出自荀子〈勸學〉，正確。(乙)「勿以善小而不為，勿以惡小而為之」是劉備臨終給兒子劉禪的遺詔，不是諸葛亮，錯。(丙)「以銅為鏡……以人為鏡，可以明得失」是唐太宗在魏徵死後說的話，是唐太宗的主張，不是魏徵，錯。(丁)「蓋文章，經國之大業，不朽之盛事」出自曹丕《典論‧論文》，正確。正確的是甲、丁，答案(D)。(A)甲乙、(B)乙丙、(C)丙丁都包含說錯人的乙或丙，所以不選。", "skill": "名句出處題，常把「說話者」和「被談論的人」對調（唐太宗談魏徵）、或把父子君臣對調（劉備與諸葛亮），要記清楚是誰說的。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-33", "exam": "et102", "nums": [33], "form": "單題", "img": "img/et102-33.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["典故出處"], "passage": "南畝耕，東山臥，世態人情經歷多／度兵大峴非無策，收泣新亭要有人／風吹易水衝冠髮，人唱陽關勸酒聲／著論準過秦，作賦擬子虛", "translation": "在南邊田裡耕作，像謝安那樣在東山隱居高臥，世態人情已經歷得夠多了／帶兵越過大峴山北伐並不是沒有計策，只是需要有像王導那樣能讓大家收起眼淚、振作起來的人／風吹過易水，就像荊軻告別時眾人怒髮衝冠；送行的人唱著〈陽關曲〉勸酒／寫論文以賈誼的〈過秦論〉為標準，作賦則模仿司馬相如的〈子虛賦〉", "keywords": [{"w": "東山臥", "m": "謝安隱居會稽東山，後出仕，成語「東山再起」"}, {"w": "新亭對泣", "m": "東晉初名士在新亭相對流淚，王導正色勸大家振作"}, {"w": "易水", "m": "荊軻刺秦前，在易水邊高歌「風蕭蕭兮易水寒」，聽者怒髮衝冠"}, {"w": "子虛", "m": "司馬相如的〈子虛賦〉"}], "questions": [{"n": 33, "qtype": "單選", "stem": "(甲)南畝耕，「東山臥」，世態人情經歷多。(關漢卿〈四塊玉．閒適〉)\n(乙)度兵大峴非無策，「收泣新亭要有人」。(陸游〈夜登千峯樹〉)\n(丙)「風吹易水衝冠髮」，人唱陽關勸酒聲。(林幼春〈送蔡培火蔣渭水陳逢源三君之京〉)\n(丁)著論準過秦，「作賦擬子虛」。(左思〈詠史〉其一)\n以上各句「」內所指稱的人物，依序排列應是：", "options": {"A": "荊軻／王導／司馬相如／謝安", "B": "謝安／王導／荊軻／司馬相如", "C": "王導／謝安／荊軻／司馬相如", "D": "謝安／王導／司馬相如／荊軻"}, "answer": "B", "explain": "(甲)「東山臥」是謝安隱居東山的典故；(乙)「收泣新亭」是東晉南渡後名士在新亭相對哭泣，王導說「當共戮力王室，克復神州，何至作楚囚相對」，要大家收起眼淚，指王導；(丙)「風吹易水衝冠髮」是荊軻在易水告別、眾人怒髮衝冠；(丁)「作賦擬子虛」是模仿司馬相如的〈子虛賦〉。依序是謝安／王導／荊軻／司馬相如，答案(B)。其他選項順序都對不上，例如(A)把荊軻放第一、(D)把荊軻與司馬相如對調、(C)把謝安與王導對調。", "skill": "典故題記「關鍵物」：東山＝謝安、新亭＝王導、易水＝荊軻、子虛上林＝司馬相如、楚囚＝亡國之悲。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-34", "exam": "et102", "nums": [34], "form": "單題", "img": "img/et102-34.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "文化常識"], "passage": "方今之時，臣以神遇而不以目視，官知止而神欲行／然君之職分難明，以俄頃淫樂，不易無窮之悲，雖愚者亦明之矣／移時，月漸暗，門人然燭來，則道士獨坐而客杳矣／甚者爪其膚以驗其生枯，搖其本以觀其疏密，而木之性日以離矣", "translation": "到了現在，我是用心神去接觸牛，而不用眼睛去看；感官的作用停止了，只憑心神在運行／然而君主的職分難以弄清楚，不拿片刻的享樂去換取無窮的悲哀，這個道理就算是愚笨的人也明白／過了一會兒，月光漸漸暗了，弟子點了蠟燭進來，只見道士獨自坐著，客人都不見了／更過分的，用指甲掐樹皮來檢驗它是活是枯，搖動樹根來看土是鬆是密，這樣樹木的天性就一天天喪失了", "keywords": [{"w": "止", "m": "象形，像腳掌，本義為腳，引申為停止"}, {"w": "易", "m": "象形，像蜥蜴"}, {"w": "然", "m": "形聲，从火、肰聲，本義為燃燒，即「燃」的本字"}, {"w": "爪", "m": "象形，像手爪向下抓"}], "questions": [{"n": 34, "qtype": "單選", "stem": "下列文句「」內的動詞，何者非象形字？", "options": {"A": "方今之時，臣以神遇而不以目視，官知「止」而神欲行。(《莊子．養生主》)", "B": "然君之職分難明，以俄頃淫樂，不「易」無窮之悲，雖愚者亦明之矣。(黃宗羲〈原君〉)", "C": "移時，月漸暗，門人「然」燭來，則道士獨坐而客杳矣。(蒲松齡〈勞山道士〉)", "D": "甚者「爪」其膚以驗其生枯，搖其本以觀其疏密，而木之性日以離矣。(柳宗元〈種樹郭橐駞傳〉)"}, "answer": "C", "explain": "四個字在句中都當動詞：止（停止）、易（交換）、然（點燃）、爪（用指甲掐）。(C)「門人然燭來」的「然」是「燃」的本字，字形是「肰」（狗肉）加「火」，以火為形、肰為聲，屬形聲字，不是象形字，是答案。(A)「止」甲骨文像一隻腳掌的形狀，象形。(B)「易」甲骨文像蜥蜴，象形（假借為交換）。(D)「爪」像手掌向下抓取的樣子，象形。", "skill": "判斷象形字：能畫出一個「具體東西形狀」的就是象形（止＝腳、爪＝手、易＝蜥蜴）；有明顯「表意偏旁＋聲符」結構的是形聲。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-35", "exam": "et102", "nums": [35], "form": "單題", "img": "img/et102-35.png", "source": "《老子》第八十章", "author": "老子", "genre": "經典語錄", "types": ["句意理解", "主旨寓意"], "passage": "小國寡民。使有什伯之器而不用，使民重死而不遠徙。雖有舟輿，無所乘之，雖有甲兵，無所陳之。使民復結繩而用之，甘其食，美其服，安其居，樂其俗。鄰國相望，雞犬之聲相聞，民至老死不相往來。", "translation": "國家要小，人民要少。即使有各種器具也不使用，讓人民重視生命而不往遠方遷徙。雖然有船和車，卻沒有地方要搭乘；雖然有鎧甲兵器，卻沒有地方要陳列使用。讓人民回到結繩記事的時代，吃得香甜，穿得美好，住得安適，過得快樂。鄰國彼此看得見，雞鳴狗叫的聲音互相聽得到，人民卻到老死也不互相往來。", "keywords": [{"w": "寡", "m": "少"}, {"w": "什伯之器", "m": "各種器具；一說十倍百倍人力的器械"}, {"w": "重死", "m": "看重死亡，即愛惜生命"}, {"w": "徙", "m": "遷移"}, {"w": "輿", "m": "車"}, {"w": "陳", "m": "陳列、擺陣"}, {"w": "結繩", "m": "上古未有文字時，以繩打結記事"}], "questions": [{"n": 35, "qtype": "單選", "stem": "「小國寡民。使有什伯之器而不用，使民重死而不遠徙。雖有舟輿，無所乘之，雖有甲兵，無所陳之。使民復結繩而用之，甘其食，美其服，安其居，樂其俗。鄰國相望，雞犬之聲相聞，民至老死不相往來。」(《老子》第八十章)「使民復結繩而用之」意謂：", "options": {"A": "回歸無文明影響的簡單生活", "B": "以質樸生活為文明與否之標準", "C": "人的生活應以超越大自然為目標，不應安於落後的生活。", "D": "文明若不思進步，則將回到茹毛飲血的生活。"}, "answer": "A", "explain": "「結繩」是文字發明前的記事方法，「復結繩而用之」就是回到沒有複雜文明制度的純樸生活，正是老子返璞歸真的理想，答案(A)。(B)老子不是在訂立「判斷文明的標準」，而是嚮往質樸；(C)說要超越大自然、不安於落後，與老子順應自然的主張相反；(D)說文明不進步就會退化，是在擔憂退步，也和老子主動回歸純樸的意思相反。", "skill": "讀老子先記住核心：無為、自然、返璞歸真；凡是主張「進步、超越自然」的選項，多半與老子相反。"}], "difficulty": "易", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-36", "exam": "et102", "nums": [36], "form": "單題", "img": "img/et102-36.png", "source": "陶淵明〈讀山海經〉其十", "author": "陶淵明", "genre": "古典詩詞曲", "types": ["字詞解釋", "典故出處"], "passage": "精衛銜微木，將以填滄海，刑天舞干戈，猛志固常在。", "translation": "精衛鳥銜著小小的樹枝，想要把大海填平；刑天被砍了頭還揮舞著盾牌和大斧，他勇猛的志氣始終都在。", "keywords": [{"w": "精衛", "m": "炎帝之女溺死東海，化為精衛鳥，銜木石填海"}, {"w": "刑天", "m": "與天帝爭位被斷首的神，以乳為目、以臍為口，仍持干戚而舞"}, {"w": "干", "m": "盾牌"}, {"w": "戈", "m": "一種長兵器"}], "questions": [{"n": 36, "qtype": "單選", "stem": "陶潛詩：「精衛銜微木，將以填滄海，刑天舞干戈，猛志固常在。」(〈讀山海經〉十三首之十)「干戈」意指：", "options": {"A": "糾紛", "B": "戰爭", "C": "武器", "D": "工具"}, "answer": "C", "explain": "「干」是盾牌、「戈」是長兵器，「舞干戈」是刑天手裡揮舞著盾和兵器，這裡用的是本義，指(C)武器。「干戈」常被引申為戰爭（如「化干戈為玉帛」），但這句的主詞是刑天「舞」干戈，舞的是具體的東西，所以不是(B)戰爭。(A)糾紛是更遠的引申義；(D)工具太籠統，干戈是作戰的兵器。", "skill": "同一個詞有本義和引申義時，看前面的動詞：「舞、執、持」後面接的多是具體物品，用本義。"}], "difficulty": "易", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-37", "exam": "et102", "nums": [37], "form": "單題", "img": "img/et102-37.png", "source": "應用文（題辭）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "桑梓福音／道範長存／華堂集瑞／億則屢中", "translation": "桑梓福音：家鄉的好消息（賀當選）。道範長存：道德風範永遠留存（輓師長）。華堂集瑞：華美的廳堂匯聚吉祥（賀新居）。億則屢中：預測行情常常猜中（賀開業）。", "keywords": [{"w": "桑梓", "m": "家鄉"}, {"w": "道範", "m": "道德風範，多用於輓師長"}, {"w": "華堂", "m": "華美的廳堂"}, {"w": "億則屢中", "m": "語出《論語‧先進》，子貢預測行情屢屢猜中，多用於賀商店開業"}], "questions": [{"n": 37, "qtype": "單選", "stem": "配合「新居」、「哀輓」、「開業」、「當選」等場合，下列幾則題辭的正確排序為何？\n(甲)桑梓福音\n(乙)道範長存\n(丙)華堂集瑞\n(丁)億則屢中", "options": {"A": "甲乙丙丁", "B": "丁乙甲丙", "C": "乙丙丁甲", "D": "丙乙丁甲"}, "answer": "D", "explain": "逐一對場合：新居→(丙)華堂集瑞（華美的房子聚集吉祥）；哀輓→(乙)道範長存（道德風範長存，輓師長）；開業→(丁)億則屢中（子貢做生意料事如神）；當選→(甲)桑梓福音（為家鄉帶來好消息）。順序是丙乙丁甲，答案(D)。(A)甲乙丙丁把當選放到最前；(B)丁乙甲丙把開業放到新居；(C)乙丙丁甲把哀輓放到新居，都不對。", "skill": "題辭看關鍵字：「堂、居、廈、輪奐」→新居；「範、德、儀、千古」→哀輓；「業、財、源、陶朱、億則屢中」→開業；「桑梓、民、眾望」→當選。"}], "difficulty": "易", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-38", "exam": "et102", "nums": [38], "form": "單題", "img": "img/et102-38.png", "source": "應用文（書信稱謂）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "夫子", "m": "可稱老師，也是妻子對丈夫的稱呼"}, {"w": "令、尊", "m": "稱對方親屬的敬詞"}, {"w": "家", "m": "稱自己的長輩（家父、家母）"}, {"w": "舍", "m": "稱自己的卑幼（舍弟、舍妹）"}, {"w": "亡", "m": "稱已過世的晚輩（亡弟、亡兒）"}, {"w": "姪、晚", "m": "對同學、朋友父母的自稱"}], "questions": [{"n": 38, "qtype": "單選", "stem": "關於書信稱謂，以下何者敘述正確？", "options": {"A": "女學生寫信給男老師時，不宜用「夫子」一詞。", "B": "信中提到對方的長輩，應該加上「貴」或「家」字以示尊敬。", "C": "提到自己已過世的晚輩時，則加上「舍」或「小」字，如「舍弟」、「小女」等。", "D": "寫信給同學的父母親，可以自稱「弟」或「妹」，以示自謙。"}, "answer": "A", "explain": "(A)「夫子」除了尊稱老師，也是古代妻子稱呼丈夫的用語，女學生寫給男老師時用了容易引起誤會，所以不宜使用，正確，是答案。(B)稱對方的長輩要用「令」「尊」（令尊、令堂），「家」是稱自己的長輩（家父、家母），錯。(C)「舍弟」「小女」用於自己在世的晚輩；已過世的晚輩要加「亡」（亡弟、亡女），錯。(D)寫給同學的父母，應自稱「姪」或「晚」，自稱「弟、妹」是平輩用語，錯。", "skill": "書信稱謂口訣：「家大舍小令他人」——稱自己長輩用家、自己晚輩用舍（小）、稱別人親屬用令。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-39", "exam": "et102", "nums": [39, 40], "form": "題組", "img": "img/et102-39.png", "source": "孟浩然〈臨洞庭上張丞相〉", "author": "孟浩然", "genre": "古典詩詞曲", "types": ["句意理解", "人物情感", "詩詞賞析"], "passage": "八月湖水平，涵虛混太清，氣蒸雲夢澤，波撼岳陽城。欲濟無舟楫，端居恥聖明。坐觀垂釣者，徒有羨魚情。", "translation": "八月的洞庭湖水漲得和岸齊平，水天相接，混成一片。水氣蒸騰籠罩著雲夢澤，波濤搖撼著岳陽城。我想渡湖卻沒有船和槳，在聖明的時代閒居在家，實在覺得羞愧。坐著看那些垂釣的人，只能白白地羨慕他們釣到魚。", "keywords": [{"w": "涵虛", "m": "水映著天空"}, {"w": "太清", "m": "天空"}, {"w": "雲夢澤", "m": "古代大澤，在洞庭湖北"}, {"w": "濟", "m": "渡河"}, {"w": "舟楫", "m": "船和槳，比喻引薦的人"}, {"w": "端居", "m": "閒居、不做官"}, {"w": "聖明", "m": "聖明的君主或時代"}, {"w": "羨魚情", "m": "羨慕釣到魚，比喻想要出仕"}], "questions": [{"n": 39, "qtype": "單選", "stem": "「欲濟無舟楫」意謂：", "options": {"A": "想要退隱，卻被慰留。", "B": "想要救濟貧民，沒有財力。", "C": "想要培養才華，沒錢讀書。", "D": "想要為官，無人引薦。"}, "answer": "D", "explain": "這是孟浩然寫給張九齡（丞相）的干謁詩。「欲濟無舟楫」表面說想渡湖卻沒有船，其實是比喻想出來做官、卻沒有人引薦，(D)是答案。下一句「端居恥聖明」（在聖明時代閒居而感到慚愧）也證明他想做官。(A)是想做官，不是想退隱；(B)「濟」是渡河，不是救濟；(C)與讀書沒錢無關。", "skill": "「上某官」的詩多是干謁詩（請求引薦），看到「無舟楫」「羨魚」這類比喻，直接翻成「想做官、求援引」。"}, {"n": 40, "qtype": "單選", "stem": "詩中「聖明」是指：", "options": {"A": "國君", "B": "張丞相", "C": "孟浩然", "D": "古代聖人"}, "answer": "A", "explain": "「端居恥聖明」意思是在聖明的時代閒居不仕，愧對聖明的君主，「聖明」指當今的國君（及其治世），答案(A)。(B)張丞相是詩人希望引薦他的人，詩中以「舟楫」暗指；(C)孟浩然是作者自己，不會自稱聖明；(D)與古代聖人無關，這裡講的是當代。", "skill": "古詩中「聖明、聖主、明時」多指當朝皇帝或太平盛世，是臣子對君王的頌稱。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-43", "exam": "et102", "nums": [43, 44], "form": "題組", "img": "img/et102-43.png", "source": "江盈科〈催科〉", "author": "江盈科", "genre": "寓言故事", "types": ["主旨寓意", "字詞解釋"], "passage": "昔有醫人，自媒能治背駝，曰：「如弓者，如鰕者，如曲環者，延吾治，可朝治而夕如矢。」一人信焉，而使治駝。乃索板二片，以一置地下，臥駝者其上，又以一壓焉，又即躧焉。駝者隨直，亦復隨死。其子欲鳴諸官，醫人曰：「我業治駝，但管人直，那管人死？」嗚呼！世之為令，但管錢糧完，不管百姓死，何以異於此醫也哉！", "translation": "從前有個醫生，自己宣稱能治駝背，他說：「像弓一樣彎的、像蝦子一樣彎的、像圓環一樣彎曲的，請我去治，早上治療，晚上就直得像箭。」有個人相信了，就請他治駝背。醫生就找來兩塊木板，一塊放在地上，讓駝背的人趴在上面，又用另一塊壓在他身上，接著就跳上去踩。駝子隨即被壓直了，也隨即死了。駝子的兒子想去官府告他，醫生說：「我的職業是治駝背，只管把人弄直，哪管人死不死？」唉！世上當縣令的，只管錢糧有沒有收齊，不管百姓死活，跟這個醫生有什麼不同呢！", "keywords": [{"w": "自媒", "m": "自我推薦、自誇"}, {"w": "鰕", "m": "同「蝦」"}, {"w": "延", "m": "請"}, {"w": "如矢", "m": "像箭一樣直"}, {"w": "索", "m": "找來"}, {"w": "躧", "m": "音ㄒㄧˇ，踩、踏"}, {"w": "鳴諸官", "m": "向官府申告"}, {"w": "業", "m": "以……為職業"}, {"w": "令", "m": "縣令"}], "questions": [{"n": 43, "qtype": "單選", "stem": "本文主旨在於說明：", "options": {"A": "為人處事，應當有始有終。", "B": "為官應視民如子，將心比心。", "C": "延醫應對症下藥，不可病急亂投醫。", "D": "累積眾多經驗，自然能藥到病除。"}, "answer": "B", "explain": "寓言最後一句點出主旨：「世之為令，但管錢糧完，不管百姓死，何以異於此醫也哉！」作者借醫生只管治直、不管人死，諷刺地方官只管收稅、不顧百姓死活，提醒為官者要愛護百姓、將心比心，答案(B)。(A)有始有終與文意無關；(C)雖然故事裡是病急亂投醫，但那只是表面情節，不是主旨；(D)醫生根本沒有經驗可言，與「經驗」無關。", "skill": "寓言主旨通常在最後的「嗚呼／嗟乎」議論句，直接看作者把故事比喻成什麼現實現象。"}, {"n": 44, "qtype": "單選", "stem": "文中「又即躧焉」意謂：", "options": {"A": "用水灑向病患", "B": "再綁上更多木板", "C": "立刻解開繩索", "D": "在其上踩跳"}, "answer": "D", "explain": "醫生先把一塊板放地上，讓駝子趴著，再用另一塊板壓在上面，「又即躧焉」就是接著跳上去踩，「躧」是踩踏，答案(D)。後文「駝者隨直，亦復隨死」也說明是被硬壓、硬踩致死。(A)灑水、(B)綁更多木板、(C)解開繩索，文中都沒有這些動作。", "skill": "不認得的字，看偏旁再對照上下文：「躧」从足，和腳有關，再接「隨直，亦復隨死」，就知道是用力踩。"}], "difficulty": "易", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et102-45", "exam": "et102", "nums": [45, 46], "form": "題組", "img": "img/et102-45.png", "source": "揚之水《詩經別裁》（評〈蒹葭〉）", "author": "揚之水", "genre": "其他", "types": ["文意推論", "詩詞賞析"], "passage": "溯迴、溯游，既無其事，在水一方，亦無其人。詩人感時撫景，忽焉有懷，而托言於一方，以寫其牢騷抑鬱之意。（戴君恩語，評《詩經‧秦風‧蒹葭》）", "translation": "（戴君恩這段話的意思）詩中逆流而上、順流而下地追尋，其實並沒有這回事；在水的另一邊，也並沒有那個人。詩人只是感受時節、觸景生情，忽然有所感懷，便假託說有人在水的一方，來抒寫他心中的牢騷與鬱悶。", "keywords": [{"w": "遇", "m": "相遇，指有具體情節的故事"}, {"w": "境", "m": "意境，以景象寄託情意"}, {"w": "興象", "m": "觸發情感的景象"}, {"w": "溯迴", "m": "逆流而上"}, {"w": "溯游", "m": "順流而下"}, {"w": "伊人", "m": "那個人"}, {"w": "托言", "m": "假託說"}], "questions": [{"n": 45, "qtype": "單選", "stem": "如上所述，本文評論〈蒹葭〉詩不是寫遇，而是寫一個境。意思是：", "options": {"A": "伊人未必真有其人，全詩意在興發感動，不在真實情節。", "B": "伊人是賢臣或美人，是男是女，語焉不詳，更顯痴人說夢，上下求索之難。", "C": "此詩貴在執著不悔的堅貞情意，並追求朝夕相處，最為精采。", "D": "伊人如果不真實存在，詩就少些浪漫的情懷。"}, "answer": "A", "explain": "「遇」是有人、有故事、有情節；「境」則不必有真實的人和事，而是用景象引發情意。作者還引戴君恩「既無其事……亦無其人」來說明。所以「寫境」就是：伊人未必真有其人，全詩重在興發感動、不在情節，答案(A)。(B)說「痴人說夢」帶有貶意，作者並沒有否定這份追尋；(C)「追求朝夕相處」是在講情節和結局，正是「寫遇」的方向；(D)作者正好認為伊人不必真實存在，也不會減少詩意。", "skill": "遇到作者自創的對比概念（遇／境），先把兩個概念的定義各寫一句，再判斷選項落在哪一邊。"}, {"n": 46, "qtype": "單選", "stem": "依據文意，下列敘述何者為非？", "options": {"A": "作者認為〈蒹葭〉詩不應只當作是一首風景詩來看", "B": "全文強調此詩以寫境為主，借興象以擴大想像，增加情意。", "C": "本文指出〈蒹葭〉一詩強調的是對於思的執著，感時撫景，忽焉有懷。", "D": "作者認為〈蒹葭〉不論是見情或寫景，皆有高尚或卑下之別。"}, "answer": "D", "explain": "題目問「為非」。(D)原文說「無論思賢臣還是思美女，這『思』都沒有高尚或卑下的區別」，選項卻說「皆有高尚或卑下之別」，與原文相反，是答案。(A)作者說〈蒹葭〉寫的是「境」，不只是實景，「天長水闊，秋景無限」是境象，不應只當風景詩看，正確。(B)「境則以興象見情見意」，以寫境為主、借興象擴大想像與情意，正確。(C)文末說詩人「倔強於自己這一份思的執著」，並引「感時撫景，忽焉有懷」，正確。", "skill": "「何者為非」先找跟原文「否定詞」相反的選項：原文說「沒有區別」，選項說「有區別」，最容易抓。"}], "difficulty": "中", "label": "102二技", "year": 102, "kind": "二技"}, {"id": "et103-01", "exam": "et103", "nums": [1], "form": "單題", "img": "img/et103-01.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "人固不能無失，然誠易地以處，平心而度之，吾果無一失乎？／聞爾官，吏目耳，俸不能五斗，爾率妻子躬耕可有也，烏為乎以五斗而易爾七尺之軀？／南陽劉子驥，高尚士也，聞之，欣然規往，未果，尋病終。／尋君去就之際，非有他故，直以不能內審諸己，外受流言，沉迷猖獗，以至於此。／深巷寒犬，吠聲如豹；村墟夜舂，復與疏鐘相間。／間關鶯語花底滑，幽咽泉流水下灘。／吳儈聞有漆，喜而逆諸郊，導以入吳國，勞而舍諸私館。／蓋亭之所見，南北百里，東西一舍；濤瀾洶湧，風雲開闔。", "translation": "人本來就不可能沒有過失，但如果真能交換立場來看，平心靜氣地衡量，我果真一點過失都沒有嗎？／聽說你的官職只是個吏目，俸祿不到五斗米，你帶著妻子兒女親自耕田也能得到，為什麼要用這五斗米換掉你堂堂七尺的身軀呢？／南陽的劉子驥是個高尚的隱士，聽說這件事，高興地計畫前往，還沒成行，不久就病死了。／推究你當初離去或留下的時候，並沒有別的原因，只是因為不能在內反省自己，在外又聽信流言，一時迷惑、行事狂亂，才落到這個地步。／幽深巷子裡的狗在寒夜吠叫，聲音像豹一樣；村落裡夜間舂米的聲音，又和稀疏的鐘聲交錯相間。／黃鶯在花下宛轉啼叫，聲音圓滑流利；泉水低聲嗚咽，流下沙灘。／吳國的商人聽說有漆，高興地到郊外迎接他，帶他進入吳國，慰勞他並安排他住進私人館舍。／從這座亭子能看到的範圍，南北有一百里，東西有三十里；波濤洶湧，風雲時開時合。", "keywords": [{"w": "易地以處", "m": "交換位置來看；易＝交換"}, {"w": "以五斗而易爾七尺之軀", "m": "用五斗米的俸祿換掉你的生命；易＝交換"}, {"w": "尋病終", "m": "不久就病死了；尋＝不久"}, {"w": "尋君去就之際", "m": "推究你離開或留下的時候；尋＝推究"}, {"w": "相間", "m": "互相交錯"}, {"w": "間關", "m": "形容鳥鳴宛轉的聲音"}, {"w": "舍諸私館", "m": "把他安置在私人館舍住宿；舍＝安置住宿"}, {"w": "一舍", "m": "三十里"}], "questions": [{"n": 1, "qtype": "單選", "stem": "下列選項「」內的字義，何者兩兩相同？", "options": {"A": "人固不能無失，然誠「易」地以處，平心而度之，吾果無一失乎？(錢大昕〈弈喻〉)／聞爾官，吏目耳，俸不能五斗，爾率妻子躬耕可有也，烏為乎以五斗而「易」爾七尺之軀？(王守仁〈瘞旅文〉)", "B": "南陽劉子驥，高尚士也，聞之，欣然規往，未果，「尋」病終。(陶淵明〈桃花源記〉)／「尋」君去就之際，非有他故，直以不能內審諸己，外受流言，沉迷猖獗，以至於此。(丘遲〈與陳伯之書〉)", "C": "深巷寒犬，吠聲如豹；村墟夜舂，復與疏鐘相「間」。(王維〈山中與裴迪秀才書〉)／「間」關鶯語花底滑，幽咽泉流水下灘。(白居易〈琵琶行并序〉)", "D": "吳儈聞有漆，喜而逆諸郊，導以入吳國，勞而「舍」諸私館。(劉基〈虞孚〉)／蓋亭之所見，南北百里，東西一「舍」；濤瀾洶湧，風雲開闔。(蘇轍〈黃州快哉亭記〉)"}, "answer": "A", "explain": "題目問「兩兩相同」。(A)錢大昕〈弈喻〉「誠易地以處」是真的交換立場來想；王守仁〈瘞旅文〉「以五斗而易爾七尺之軀」是用微薄俸祿換掉你的性命，兩個「易」都是「交換」，相同，是答案。(B)〈桃花源記〉「尋病終」的「尋」是「不久」；〈與陳伯之書〉「尋君去就之際」的「尋」是「推究、探求」，不同。(C)「復與疏鐘相間」是交錯夾雜；「間關鶯語」的「間關」是形容鳥聲宛轉，不同。(D)〈虞孚〉「舍諸私館」是安頓住宿（動詞）；〈黃州快哉亭記〉「東西一舍」是距離單位，一舍三十里，不同。", "skill": "字義比較題，把兩句的字各自換成一個白話詞代入（交換／交換），代得進去又通順才算相同。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-02", "exam": "et103", "nums": [2], "form": "單題", "img": "img/et103-02.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["寫作手法", "字詞解釋"], "passage": "(甲)宴酣之樂，非絲非竹，射者中，奕者勝，觥籌交錯，起坐而喧嘩者，眾賓歡也。\n(乙)其既得之也，敲剝天下之骨髓，離散天下之子女，以奉我一人之淫樂，視為當然。\n(丙)主人下馬客在船，舉酒欲飲無管絃。\n(丁)胡人不敢南下而牧馬，士不敢彎弓而報怨。", "translation": "(甲)〈醉翁亭記〉：宴會喝得盡興的快樂，不在於音樂；投壺的投中了，下棋的贏了，酒杯和酒籌交錯，一會兒起身一會兒坐下、大聲喧鬧的，是眾賓客在歡樂。\n(乙)〈原君〉：君主得到天下以後，就壓榨天下人的血汗財富，拆散天下人的子女，來供自己一個人荒淫享樂，還認為理所當然。\n(丙)〈琵琶行〉：主人下了馬，客人已在船上，舉起酒杯想喝，卻沒有音樂助興。\n(丁)〈過秦〉：胡人不敢南下放馬侵擾，（六國的）士人也不敢拉弓射箭來報仇。", "keywords": [{"w": "觥籌", "m": "酒杯和行酒令用的籌碼"}, {"w": "骨髓", "m": "借指百姓的血汗財富"}, {"w": "管絃", "m": "管樂器和弦樂器，借指音樂"}, {"w": "牧馬", "m": "放牧馬匹，借指南下侵略"}], "questions": [{"n": 2, "qtype": "單選", "stem": "(甲)宴酣之樂，非絲非竹，射者中，奕者勝，「觥籌」交錯，起坐而喧嘩者，眾賓歡也。(歐陽脩〈醉翁亭記〉)\n(乙)其既得之也，敲剝天下之「骨髓」，離散天下之子女，以奉我一人之淫樂，視為當然。(黃宗羲〈原君〉)\n(丙)主人下馬客在船，舉酒欲飲無「管絃」。(白居易〈琵琶行并序〉)\n(丁)胡人不敢南下而「牧馬」，士不敢彎弓而報怨。(賈誼〈過秦〉)\n上述文句「」中之字詞，不屬於「借代」修辭的選項是：", "options": {"A": "甲", "B": "乙", "C": "丙", "D": "丁"}, "answer": "A", "explain": "「借代」是不直接說本體，而借用相關的事物來代替。題目問「不屬於」借代。(A)〈醉翁亭記〉「觥籌交錯」，就是真的酒杯和籌碼在席間交錯，是字面實寫，沒有借代，是答案。(B)「敲剝天下之骨髓」，不是真的剝骨髓，而是借「骨髓」代指百姓的血汗財富，是借代。(C)「舉酒欲飲無管絃」，「管絃」借代音樂、樂聲。(D)「不敢南下而牧馬」，借「牧馬」代指胡人騎馬南下侵略。", "skill": "判斷借代：把詞照字面解釋，如果句子變得很怪（剝骨髓、放牧馬兒），就是借代；照字面完全合理的（酒杯交錯）就不是。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-04", "exam": "et103", "nums": [4], "form": "單題", "img": "img/et103-04.png", "source": "應用文（題辭）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "椿萱並茂／珠聯璧合／福蔭子孫／斗山安仰", "translation": "椿萱並茂：父母雙親都健康長壽。珠聯璧合：珍珠串連、美玉相合，比喻佳偶天成。福蔭子孫：福澤庇蔭後代。斗山安仰：泰山北斗倒了，往後還能仰望誰（輓師長、德高望重者）。", "keywords": [{"w": "椿萱", "m": "椿代父、萱代母"}, {"w": "珠聯璧合", "m": "賀結婚"}, {"w": "福蔭子孫", "m": "多用於居室、新居落成"}, {"w": "斗山", "m": "泰山北斗，比喻德高望重的人"}, {"w": "安仰", "m": "還能仰望誰"}], "questions": [{"n": 4, "qtype": "單選", "stem": "題辭是用來表達慶賀、讚頌、勸勉、紀念、哀悼等的文辭，一般以四字一句為最常見。如果依「壽慶、結婚、居室、哀輓」的用途順序來題寫，下列選項何者正確？", "options": {"A": "椿萱並茂、斗山安仰、珠聯璧合、福蔭子孫", "B": "福蔭子孫、椿萱並茂、斗山安仰、珠聯璧合", "C": "珠聯璧合、斗山安仰、椿萱並茂、福蔭子孫", "D": "椿萱並茂、珠聯璧合、福蔭子孫、斗山安仰"}, "answer": "D", "explain": "逐項對場合：壽慶→「椿萱並茂」（父母雙壽）；結婚→「珠聯璧合」；居室→「福蔭子孫」（房屋庇蔭後代）；哀輓→「斗山安仰」（泰山北斗已倒，從此還能仰望誰）。依序是(D)。(A)把「斗山安仰」放在結婚、「珠聯璧合」放在居室；(B)第一個就用「福蔭子孫」賀壽；(C)第一個用「珠聯璧合」賀壽，都不對。", "skill": "題辭先挑最好認的「哀輓」：有「安仰、千古、長存、遽歸道山」的一定是輓辭，放到最後一格就能刪掉大部分選項。"}], "difficulty": "易", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-05", "exam": "et103", "nums": [5], "form": "單題", "img": "img/et103-05.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "相看兩不厭，只有敬亭山／沾衣欲濕杏花雨，吹面不寒楊柳風／舊時王謝堂前燕，飛入尋常百姓家／春風不相識，何事入羅幃", "translation": "我和敬亭山互相看著，誰也不厭倦，只有敬亭山能這樣陪著我。／杏花時節的細雨，好像要沾濕衣裳卻又不濕；楊柳間吹來的春風，拂在臉上一點也不冷。／從前王導、謝安這些豪門大宅堂前的燕子，如今飛進了平常百姓的家。／春風啊，我和你素不相識，你為什麼要吹進我的羅帳裡來？", "keywords": [{"w": "相看兩不厭", "m": "李白〈獨坐敬亭山〉，人與山互相看不厭"}, {"w": "杏花雨、楊柳風", "m": "僧志南〈絕句〉，寫早春細雨和暖風"}, {"w": "王謝堂前燕", "m": "劉禹錫〈烏衣巷〉，以燕子寫世家沒落"}, {"w": "春風不相識", "m": "李白〈春思〉，責怪春風闖入閨房"}], "questions": [{"n": 5, "qtype": "單選", "stem": "以下詩句，何者並未將自然現象引申到人的情感之上？", "options": {"A": "相看兩不厭，只有敬亭山", "B": "沾衣欲濕杏花雨，吹面不寒楊柳風", "C": "舊時王謝堂前燕，飛入尋常百姓家", "D": "春風不相識，何事入羅幃"}, "answer": "B", "explain": "題目問「並未」把自然現象引申到人的情感。(B)「沾衣欲濕杏花雨，吹面不寒楊柳風」，只是描寫早春的細雨微濕衣裳、暖風吹面不冷，是純粹的感官寫景，沒有寄託情感，是答案。(A)李白把敬亭山當成知己，「相看兩不厭」寄託孤獨的心情。(C)燕子從王謝豪門飛入尋常百姓家，寄託世事變遷、繁華不再的感慨。(D)「春風不相識，何事入羅幃」，思婦埋怨春風擅入閨房，寄託思念丈夫、堅守情意的心情。", "skill": "分辨「寫景」與「借景抒情」：問自己「這句話背後有沒有一種心情（孤獨、感慨、思念）」，只有感官描寫的就是單純寫景。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-06", "exam": "et103", "nums": [6], "form": "單題", "img": "img/et103-06.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "因問明帝：「汝意謂長安何如日遠？」／素驕貴，又以時亂，天下之權重望崇者莫我若也，奢貴自奉，禮異人臣。／噫！微斯人，吾誰與歸！／近世寇萊公豪侈冠一時，然以功業大，人莫之非。", "translation": "（晉元帝）於是問明帝：「你認為長安和太陽相比，哪一個遠？」／（楊素）向來驕橫尊貴，又因為時局混亂，認為天下權位高、聲望大的人沒有比得上自己的，生活奢侈，排場禮數都和一般臣子不同。／唉！如果沒有這樣的人，我要追隨誰呢！／近代的寇萊公（寇準）豪華奢侈是當時第一，但因為功業大，沒有人批評他。", "keywords": [{"w": "何如", "m": "比……怎麼樣"}, {"w": "莫我若", "m": "沒有人比得上我；否定句代詞賓語前置"}, {"w": "誰與歸", "m": "與誰歸；疑問代詞賓語前置"}, {"w": "莫之非", "m": "沒有人批評他；否定句代詞賓語前置"}], "questions": [{"n": 6, "qtype": "單選", "stem": "下列選項有關「倒裝句」的解說，何者錯誤？", "options": {"A": "因問明帝：「汝意謂長安何如日遠？」「何如日遠」是「何遠如日」的倒裝。指哪裏會比太陽遠？(劉義慶《世說新語》)", "B": "素驕貴，又以時亂，天下之權重望崇者莫我若也，奢貴自奉，禮異人臣。「莫我若」是「莫若我」的倒裝。指沒有人比得上我。(杜光庭〈虬髯客傳〉)", "C": "噫！微斯人，吾誰與歸！「吾誰與歸」即「吾與誰歸」的倒裝，指我要歸附誰呢？(范仲淹〈岳陽樓記〉)", "D": "近世寇萊公豪侈冠一時，然以功業大，人莫之非。「人莫之非」即「人莫非之」的倒裝，指沒有人敢批評他。(司馬光〈訓儉示康〉)"}, "answer": "A", "explain": "題目問「錯誤」。(A)《世說新語》晉元帝問年幼的明帝「汝意謂長安何如日遠」，意思是「你覺得長安和太陽相比，哪一個遠？」，「何如」是「比起……怎麼樣」，整句是正常語序，並不是「何遠如日」的倒裝，也不是「哪裏會比太陽遠」，所以錯，是答案。(B)「莫我若」是否定句中代詞「我」提到動詞「若」前，正常語序是「莫若我」，沒有人比得上我，正確。(C)「吾誰與歸」是疑問代詞「誰」提到介詞「與」前，即「吾與誰歸」，正確。(D)「人莫之非」是否定句代詞「之」提前，即「人莫非之」，沒有人批評他，正確。", "skill": "文言倒裝兩大規則：否定句（莫、不、未）中代詞賓語提前；疑問句中疑問代詞（誰、何、安）賓語提前。不符合這兩種的，就要懷疑。"}], "difficulty": "難", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-07", "exam": "et103", "nums": [7], "form": "單題", "img": "img/et103-07.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "河東薛存義將行，柳子載肉於俎，崇酒於觴，追而送之江滸，飲食之。／作亭者誰？山之僧智僊也。名之者誰？太守自謂也。／夜披衣坐，聞雞鳴，即起盥櫛，走馬抵門。／於是廢先王之道，燔百家之言，以愚黔首。", "translation": "河東人薛存義將要離開，我把肉放在砧板上，把酒斟滿酒杯，追到江邊為他送行，請他吃喝。／蓋亭子的是誰？是山裡的和尚智僊。替亭子取名的是誰？是太守用自己的別號來命名的。／（求見權貴的人）半夜披著衣服坐著等，一聽到雞叫，就起床洗臉梳頭，騎著馬趕到權貴家門口。／（秦始皇）於是廢除古代聖王的治國之道，焚燒諸子百家的著作，來讓百姓變得愚昧。", "keywords": [{"w": "使動用法", "m": "主語使賓語產生某種動作或狀態"}, {"w": "飲食之", "m": "讓他吃喝"}, {"w": "名之", "m": "為它命名"}, {"w": "走馬", "m": "騎馬快跑"}, {"w": "愚黔首", "m": "使百姓愚昧"}], "questions": [{"n": 7, "qtype": "單選", "stem": "下列選項，何者不是動詞的「使動用法」？", "options": {"A": "河東薛存義將行，柳子載肉於俎，崇酒於觴，追而送之江滸，「飲食」之。(柳宗元〈送薛存義序〉)", "B": "作亭者誰？山之僧智僊也。「名」之者誰？太守自謂也。(歐陽脩〈醉翁亭記〉)", "C": "夜披衣坐，聞雞鳴，即起盥櫛，「走」馬抵門。(宗臣〈報劉一丈書〉)", "D": "於是廢先王之道，燔百家之言，以「愚」黔首。(賈誼〈過秦〉)"}, "answer": "C", "explain": "「使動」就是「使賓語怎麼樣」。(A)「飲食之」是讓薛存義吃喝，即「使之飲、使之食」，是使動。(B)「名之者誰」是誰給亭子取名，可理解為使它有名稱、為它命名。(D)「以愚黔首」是使百姓變得愚昧，「愚」是形容詞的使動，最典型。(C)「走馬抵門」是寫求見權貴的人天沒亮就騎著馬快跑到權貴門前，這裡把「走馬」理解為人「騎馬疾馳」的動作，重點在人怎麼趕路，而不是「使馬奔跑」，所以不算使動用法，是答案。", "skill": "判斷使動：把句子改寫成「使＋賓語＋動詞」（使百姓愚、使之飲食），改寫後意思不變的就是使動。"}], "difficulty": "難", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-08", "exam": "et103", "nums": [8], "form": "單題", "img": "img/et103-08.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["句意理解", "文意推論"], "passage": "(甲)每寒夜起立，振衣裳，甲上冰霜迸落，鏗然有聲。\n(乙)世溷濁而不清，蟬翼為重，千鈞為輕；黃鐘毀棄，瓦釜雷鳴；讒人高張，賢士無名。\n(丙)已而歌曰：「仙仙乎，而還乎，而幽我於廣寒乎！」其聲清越，烈如簫管。", "translation": "(甲)方苞〈左忠毅公軼事〉：（史可法）每到寒夜起身，抖動衣裳，鎧甲上的冰霜迸落下來，發出鏗鏘的聲音。\n(乙)屈原〈卜居〉：世道混濁不清，把蟬翼看得很重，把千鈞看得很輕；貴重的黃鐘被毀棄，粗陋的瓦鍋卻敲得像雷一樣響；說壞話的人氣焰高張，賢能的人默默無名。\n(丙)蒲松齡〈勞山道士〉：（嫦娥）接著唱道：「飄飄起舞啊，你們回到人間了嗎？卻把我幽禁在廣寒宮裡！」歌聲清亮高亢，響亮得像簫管吹奏一樣。", "keywords": [{"w": "鏗然", "m": "金石撞擊的響亮聲"}, {"w": "溷濁", "m": "混濁"}, {"w": "黃鐘", "m": "古代貴重的大鐘，比喻賢才"}, {"w": "瓦釜", "m": "陶製的鍋，比喻庸才"}, {"w": "仙仙", "m": "舞姿輕盈飄動的樣子"}, {"w": "清越", "m": "清脆悠揚"}, {"w": "烈", "m": "聲音響亮"}, {"w": "鳴金擊鼓", "m": "敲鑼打鼓，古代進退軍的信號"}], "questions": [{"n": 8, "qtype": "單選", "stem": "(甲)每寒夜起立，振衣裳，甲上冰霜迸落，□□□□。(方苞〈左忠毅公軼事〉)\n(乙)世溷濁而不清，蟬翼為重，千鈞為輕；黃鐘毀棄，□□□□；讒人高張，賢士無名。(屈原〈卜居〉)\n(丙)已而歌曰：「仙仙乎，而還乎，而幽我於廣寒乎！」其聲清越，□□□□。(蒲松齡〈勞山道士〉)\n(丁)於是，夏天什麼時候跨了門檻進來我並不知道；直到那天上文學史課的時候，突然四面楚歌、□□□□一般，所有的蟬都同時叫了起來，把我嚇了一跳。(簡媜〈夏之絕句〉)\n在上述文句□內依序填入語詞，正確的選項是：", "options": {"A": "鏗然有聲、瓦釜雷鳴、烈如簫管、鳴金擊鼓", "B": "鳴金擊鼓、瓦釜雷鳴、鏗然有聲、烈如簫管", "C": "瓦釜雷鳴、鏗然有聲、鳴金擊鼓、烈如簫管", "D": "鏗然有聲、鳴金擊鼓、烈如簫管、瓦釜雷鳴"}, "answer": "A", "explain": "逐句判斷：(甲)冰霜從鎧甲上迸落，金屬碰撞的聲音是「鏗然有聲」。(乙)與「黃鐘毀棄」對仗、批評小人得勢的是「瓦釜雷鳴」（貴重的鐘被丟掉，破瓦鍋卻響如雷）。(丙)嫦娥唱歌「其聲清越」，接「烈如簫管」形容歌聲響亮如吹簫管。(丁)簡媜寫蟬聲突然大作，接在「四面楚歌」後面的是戰場氣氛的「鳴金擊鼓」。依序是(A)。(B)把「鳴金擊鼓」放在甲；(C)把「瓦釜雷鳴」放在甲；(D)把「瓦釜雷鳴」放在丁、「鳴金擊鼓」放在乙，對仗和文意都不合。", "skill": "填空先找「對仗」的那格：「黃鐘毀棄」一定配「瓦釜雷鳴」，鎖定一格就能刪掉一半選項。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-10", "exam": "et103", "nums": [10], "form": "單題", "img": "img/et103-10.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀"], "passage": "停車坐愛楓林晚，霜葉紅於二月花。（杜牧〈山行〉）", "translation": "停下車來，只因為喜愛這傍晚的楓林；經霜的楓葉，比二月的春花還要紅。", "keywords": [{"w": "坐", "m": "因為"}, {"w": "霜葉", "m": "經霜變紅的楓葉"}, {"w": "霜齒一咬", "m": "余光中把秋霜比作牙齒，咬紅了葉子"}, {"w": "一掌血", "m": "形容楓葉像手掌、紅得像血"}], "questions": [{"n": 10, "qtype": "單選", "stem": "閱讀下列詩句後，請問此詩描寫的主體，與下列選項何者最為吻合？\n秋天，最容易受傷的記憶\n霜齒一咬\n噢，那樣輕輕　就咬出一掌血來(余光中)", "options": {"A": "回首向來蕭瑟處，也無風雨也無晴", "B": "疏影橫斜水清淺，暗香浮動月黃昏", "C": "出淤泥而不染，濯清漣而不妖", "D": "停車坐愛楓林晚，霜葉紅於二月花"}, "answer": "D", "explain": "余光中寫「秋天」「霜齒一咬」「咬出一掌血來」：秋霜像牙齒一咬，就咬出一片像手掌、紅如血的東西，寫的正是經霜變紅的楓葉。(D)杜牧〈山行〉「霜葉紅於二月花」寫的也是秋天經霜的楓葉，是答案。(A)蘇軾〈定風波〉寫人生態度，(B)林逋〈山園小梅〉寫梅花，(C)周敦頤〈愛蓮說〉寫蓮花，都不是秋天的楓葉。", "skill": "新舊詩比較題，先把新詩的意象拆出「季節＋形狀＋顏色」（秋、手掌、紅），再找古詩中特徵相同的物。"}], "difficulty": "易", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-11", "exam": "et103", "nums": [11], "form": "單題", "img": "img/et103-11.png", "source": "周興嗣《千字文》", "author": "周興嗣", "genre": "經典語錄", "types": ["句意理解", "文化常識"], "passage": "聆音察理，鑒貌辨色。箋牒簡要，顧答審詳。空谷傳聲，虛堂習聽。尺璧非寶，寸陰是競。", "translation": "聽別人說話要能察覺其中的道理，看別人的容貌要能分辨他的神色。寫書信公文要簡明扼要，回答問話要周到詳細。空曠的山谷能傳出回聲，空蕩的廳堂裡聲音會被聽得清楚（言語要謹慎）。一尺長的璧玉不算真正的寶貝，一寸光陰才值得爭取。", "keywords": [{"w": "聆", "m": "聽"}, {"w": "鑒", "m": "觀察"}, {"w": "箋牒", "m": "書信、公文"}, {"w": "顧答", "m": "回答"}, {"w": "審詳", "m": "周詳仔細"}, {"w": "虛堂", "m": "空蕩的廳堂"}, {"w": "尺璧", "m": "直徑一尺的璧玉"}, {"w": "寸陰", "m": "短暫的光陰"}], "questions": [{"n": 11, "qtype": "單選", "stem": "中國古代對於兒童啟蒙的教育非常重視，以下《千字文》中各句，與其所欲教導兒童的知識，何者配對正確？", "options": {"A": "聆音察理，鑒貌辨色—教導音樂知識", "B": "箋牒簡要，顧答審詳—書信寫作與口語對應", "C": "空谷傳聲，虛堂習聽—鍛練體魄，訓練體能", "D": "尺璧非寶，寸陰是競—寶物的價值在其大小尺寸"}, "answer": "B", "explain": "(B)「箋牒簡要，顧答審詳」：寫書信公文要簡要，回答別人的話要周詳，正是教書信寫作與口語應對，配對正確，是答案。(A)「聆音察理，鑒貌辨色」是聽話察理、看臉辨色，教的是待人察言觀色，不是音樂知識。(C)「空谷傳聲，虛堂習聽」是說聲音會傳開、會被聽見，提醒言行要謹慎，不是鍛鍊體能。(D)「尺璧非寶，寸陰是競」是說光陰比寶玉珍貴，要珍惜時間，不是寶物看尺寸大小。", "skill": "啟蒙讀物多在教做人道理，遇到「音、聲、寶」等字，不要只看字面，要問「這句在勸孩子做什麼」。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-12", "exam": "et103", "nums": [12], "form": "單題", "img": "img/et103-12.png", "source": "唐代傳奇小說", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "唐傳奇", "m": "唐代文言短篇小說，由六朝志怪發展而來"}, {"w": "〈虯髯客傳〉", "m": "杜光庭作，寫風塵三俠"}, {"w": "《西廂記》", "m": "元代王實甫作，源自元稹〈鶯鶯傳〉"}, {"w": "〈定婚店〉", "m": "李復言作，月下老人故事出處"}], "questions": [{"n": 12, "qtype": "單選", "stem": "請選出以下有關唐代傳奇小說的錯誤敘述：", "options": {"A": "以六朝小說作為基礎，並配合唐代的社會現況而發展出的一種文學體製", "B": "對於女性的角色描寫極具特色，例如〈無雙傳〉、〈聶隱娘傳〉等", "C": "影響後代的文學甚鉅，例如〈虯髯客傳〉至元代被改為《西廂記》", "D": "李復言的〈訂婚店〉，即為民間信仰中，有關月下老人的傳說"}, "answer": "C", "explain": "題目問「錯誤」。(C)元代王實甫的《西廂記》是由唐代元稹的傳奇〈鶯鶯傳〉（又名〈會真記〉）改編而來；〈虯髯客傳〉寫李靖、紅拂女、虯髯客的「風塵三俠」故事，與《西廂記》無關，所以錯，是答案。(A)唐傳奇以六朝志怪、志人小說為基礎，配合唐代社會發展而成，正確。(B)〈無雙傳〉的劉無雙、〈聶隱娘〉的女刺客，女性角色鮮明，正確。(D)李復言〈定婚店〉寫韋固遇月下老人以紅繩繫足定姻緣，是月老傳說的出處，正確。", "skill": "唐傳奇對後代戲曲的影響一組記：〈鶯鶯傳〉→《西廂記》、〈枕中記〉→《邯鄲記》、〈南柯太守傳〉→《南柯記》、〈霍小玉傳〉→《紫釵記》。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-13", "exam": "et103", "nums": [13], "form": "單題", "img": "img/et103-13.png", "source": "應用文（公文用語）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "鈞", "m": "下級機關對上級機關的稱謂"}, {"w": "鈞長", "m": "對上級機關首長的稱謂"}, {"w": "台端", "m": "機關對人民的稱謂"}, {"w": "貴", "m": "對無隸屬關係機關、團體的稱謂"}, {"w": "職", "m": "屬員對長官的自稱"}], "questions": [{"n": 13, "qtype": "單選", "stem": "有關公文寫作之用語，以下敘述何者為非？", "options": {"A": "有隸屬關係的下級機關對上級機關發文時，稱對方單位為「鈞」", "B": "公務機關發文給人民時，可以用「台端」或是「君」", "C": "公務機關稱民間團體之負責人，應用「鈞長」", "D": "下屬對長官自稱時，宜用「職」"}, "answer": "C", "explain": "題目問「為非」。(C)「鈞長」是對上級機關首長的尊稱；公務機關稱呼民間團體或其負責人時，用「貴」（如貴會、貴公司）或「台端」，不用「鈞長」，所以錯，是答案。(A)有隸屬關係的下級對上級機關，稱「鈞」（如鈞部、鈞府），正確。(B)機關對人民稱「台端」，也可稱「君」，正確。(D)屬員對長官自稱「職」，正確。", "skill": "公文稱謂看上下關係：對上用「鈞」、對平行或無隸屬用「貴」、對下用「貴」或「該」、對人民用「台端」、自稱「本」或「職」。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-14", "exam": "et103", "nums": [14], "form": "單題", "img": "img/et103-14.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "寫作手法"], "passage": "國家興亡，匹夫有責／陟罰臧否，不宜異同／曾不吝情去留／申之以盟誓", "translation": "國家的存亡，每個平凡人都有責任。／獎賞、懲罰、褒揚、批評，不應該有不同的標準。／（五柳先生）從來不會捨不得離開（喝醉了就走）。／再用盟約誓言來重申約定。", "keywords": [{"w": "偏義複詞", "m": "由兩個字組成，只取其中一個字的意思"}, {"w": "異同", "m": "偏「異」，不同"}, {"w": "忘記", "m": "偏「忘」"}, {"w": "興亡", "m": "偏「亡」"}, {"w": "去留", "m": "偏「去」"}, {"w": "恩怨", "m": "偏「怨」"}], "questions": [{"n": 14, "qtype": "單選", "stem": "修辭學中有所謂「複詞」的用法，「複詞」又分為同義、偏義及反義複詞三種，請選出以下選項中，「」內皆為偏義複詞者：", "options": {"A": "國家「興亡」，匹夫有責／上課要仔細「聆聽」", "B": "陟罰臧否，不宜「異同」／他連返校日都「忘記」了", "C": "曾不吝情「去留」／文氣如長江黃河，不可「遏阻」", "D": "申之以「盟誓」／兩國歷史上的「恩怨」，植根已深，累有衝突"}, "answer": "B", "explain": "偏義複詞是兩個字只取一個字的意思。(B)〈出師表〉「陟罰臧否，不宜異同」，獎懲不應該有「不同」標準，只取「異」；「忘記」只取「忘」（記住就不是忘了），兩者都是偏義複詞，是答案。(A)「國家興亡」重在「亡」，是偏義；但「聆聽」兩字都是聽，是同義複詞。(C)「曾不吝情去留」重在「去」，是偏義；但「遏阻」兩字都是阻止，是同義複詞。(D)「盟誓」兩字都是立誓，是同義複詞；「恩怨」在這裡偏重「怨」，是偏義，但一組不全對。", "skill": "偏義複詞的判斷：把兩個字各自放回句子試試，只有一個字放得進去、另一個放進去會違背文意，就是偏義。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-16", "exam": "et103", "nums": [16], "form": "單題", "img": "img/et103-16.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "當今之世，舍我其誰也？／此何地也，而汝來前！／師道之不傳也久矣！／此中人語云：不足為外人道也！", "translation": "在當今這個時代，除了我還有誰呢？／這是什麼地方，你竟然跑到這裡來！／從師學習的風氣不流傳已經很久了！／這裡的人叮囑說：不要對外面的人說啊！", "keywords": [{"w": "舍我其誰也", "m": "除了我還有誰呢；也＝耶，疑問"}, {"w": "此何地也", "m": "這是什麼地方呢；也＝疑問語氣"}, {"w": "師道之不傳也久矣", "m": "「也」用於句中停頓"}, {"w": "不足為外人道也", "m": "不必對外面的人說啊；也＝表祈使、叮囑"}], "questions": [{"n": 16, "qtype": "單選", "stem": "下列選項「」內的虛詞，何者表示祈使語氣？", "options": {"A": "當今之世，舍我其誰「也」？(《孟子．公孫丑下》)", "B": "此何地「也」，而汝來前！(方苞〈左忠毅公軼事〉)", "C": "師道之不傳「也」久矣！(韓愈〈師說〉)", "D": "此中人語云：不足為外人道「也」！(陶淵明〈桃花源記〉)"}, "answer": "D", "explain": "祈使語氣是請求、命令、叮嚀別人做或不做某事。(D)〈桃花源記〉村人叮囑漁人「不足為外人道也」，意思是「不要對外面的人說啊」，「也」表示叮囑、祈使，是答案。(A)「舍我其誰也」是反問「除了我還有誰呢」，「也」同「耶」，表疑問反詰。(B)左光斗怒斥「此何地也」，是質問「這是什麼地方」，表疑問。(C)「師道之不傳也久矣」，「也」放在句中表示停頓、提起下文。", "skill": "判斷語氣先看整句在「做什麼」：在問就是疑問、在感嘆就是感嘆、在叫人別做某事就是祈使，不必死記虛詞本身。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-17", "exam": "et103", "nums": [17], "form": "單題", "img": "img/et103-17.png", "source": "二十四節氣", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "驚蟄", "m": "春季第三個節氣，約國曆三月初"}, {"w": "芒種", "m": "夏季第三個節氣，約六月初"}, {"w": "白露", "m": "秋季第三個節氣，約九月初"}, {"w": "小雪", "m": "冬季第二個節氣，約十一月下旬"}], "questions": [{"n": 17, "qtype": "單選", "stem": "傳統上將一年分為二十四個節氣，若以春天為首，以下節氣的先後排序何者正確？", "options": {"A": "驚蟄、小雪、芒種、白露", "B": "驚蟄、芒種、白露、小雪", "C": "芒種、驚蟄、小雪、白露", "D": "白露、驚蟄、芒種、小雪"}, "answer": "B", "explain": "依四季判斷：驚蟄是春（春雨驚春），芒種是夏（夏滿芒夏），白露是秋（秋處露秋），小雪是冬（冬雪雪冬）。春→夏→秋→冬排列為驚蟄、芒種、白露、小雪，答案(B)。(A)把小雪放在芒種之前；(C)把芒種放在驚蟄之前；(D)把白露（秋）放在最前，都不對。", "skill": "節氣排序題，只要先判斷每個節氣屬於哪一季，再照春夏秋冬排就好，不需要記準確日期。"}], "difficulty": "易", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-18", "exam": "et103", "nums": [18], "form": "單題", "img": "img/et103-18.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "向不為斯役，則久已病矣／人皆嗤吾固陋，吾不以為病／君子病無能焉，不病人之不己知也／今日病矣，吾助苗長矣", "translation": "如果以前不做這份（捕蛇的）差事，早就困苦不堪了。／別人都譏笑我寒酸鄙陋，我不認為這是缺點。／君子只擔心自己沒有能力，不擔心別人不了解自己。／今天累壞了，我幫助禾苗長高了！", "keywords": [{"w": "久已病矣", "m": "早就困苦不堪了；病＝困苦"}, {"w": "吾不以為病", "m": "我不認為是缺點；病＝缺點、恥辱"}, {"w": "病無能", "m": "擔心自己沒有才能；病＝擔憂"}, {"w": "今日病矣", "m": "今天累壞了；病＝疲累"}], "questions": [{"n": 18, "qtype": "單選", "stem": "下列文句中的「病」字，何者意指「擔心」？", "options": {"A": "向不為斯役，則久已「病」矣(柳宗元〈捕蛇者說〉)", "B": "人皆嗤吾固陋，吾不以為「病」(司馬光〈訓儉示康〉)", "C": "君子「病」無能焉，不「病」人之不己知也(《論語．衛靈公》)", "D": "今日「病」矣，吾助苗長矣(《孟子．公孫丑上》)"}, "answer": "C", "explain": "(C)《論語》「君子病無能焉，不病人之不己知也」，君子只擔心自己沒有能力，不擔心別人不了解自己，「病」是「擔憂」，是答案。(A)〈捕蛇者說〉「向不為斯役，則久已病矣」，如果不做捕蛇這件差事，早就困苦不堪了，「病」是困苦。(B)〈訓儉示康〉「吾不以為病」，我不把它當作缺點、恥辱。(D)〈揠苗助長〉「今日病矣」，今天累壞了，「病」是疲累。", "skill": "「病」常見義：生病、困苦、疲累、缺點、擔憂。後面接「人之不己知、無能」這種「擔心的內容」時，就是「擔憂」。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-19", "exam": "et103", "nums": [19], "form": "單題", "img": "img/et103-19.png", "source": "綜合（成語出處）", "author": "", "genre": "其他", "types": ["典故出處"], "passage": "各抱地勢，鉤心鬥角。（杜牧〈阿房宮賦〉）", "translation": "（樓閣）各自依著地勢而建，屋心互相勾連，屋角互相對峙。", "keywords": [{"w": "鉤心鬥角", "m": "原指宮室結構精巧，屋心勾連、簷角相對；後比喻各用心機、互相排擠"}, {"w": "陳陳相因", "m": "原指糧倉裡的舊糧逐年堆積；後比喻因襲舊套"}, {"w": "舞文弄墨", "m": "原指玩弄法律條文；後指賣弄文筆"}, {"w": "變本加厲", "m": "原指事物在原基礎上更加發展；後指情況變得更嚴重"}], "questions": [{"n": 19, "qtype": "單選", "stem": "下列成語，何者原義形容宮殿建築結構的繁複精巧？", "options": {"A": "陳陳相因", "B": "鉤心鬥角", "C": "舞文弄墨", "D": "變本加厲"}, "answer": "B", "explain": "(B)「鉤心鬥角」出自杜牧〈阿房宮賦〉「各抱地勢，鉤心鬥角」，原本形容宮殿建築的屋心互相勾連、簷角彼此相對，結構繁複精巧，後來才引申為人與人之間各用心機，是答案。(A)「陳陳相因」出自《史記‧平準書》，原指糧倉的陳糧一年年堆積；(C)「舞文弄墨」原指玩弄法律條文、枉法；(D)「變本加厲」出自蕭統〈文選序〉，原指比原本更加發展。三者都和建築無關。", "skill": "成語「原義」題常考今義與古義差很大的詞，記住出處那篇文章在寫什麼（〈阿房宮賦〉寫宮殿），原義就跟著出來。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-20", "exam": "et103", "nums": [20], "form": "單題", "img": "img/et103-20.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "男兒寧當格鬥死，何能怫鬱築長城／誤落塵網中，一去十三年／洛陽親友如相問，一片冰心在玉壺／老僧已死成新塔，壞壁無由見舊題", "translation": "男子漢寧可在戰場上搏鬥而死，怎能鬱鬱不樂地在這裡修築長城！／不小心落入官場這張塵世的羅網，一去就是十三年。／洛陽的親友如果問起我，就說我的心仍像玉壺裡的冰一樣純潔。／當年的老和尚已經過世，只留下一座新塔；牆壁破損了，再也看不到我們從前題的詩。", "keywords": [{"w": "怫鬱", "m": "憂鬱不舒暢"}, {"w": "塵網", "m": "比喻官場"}, {"w": "冰心在玉壺", "m": "比喻心地純潔"}, {"w": "新塔", "m": "僧人死後火化，造塔存放骨灰"}, {"w": "舊題", "m": "從前在牆上題的詩"}], "questions": [{"n": 20, "qtype": "單選", "stem": "下列詩句，何者描寫世事變幻、人生無常的感慨？", "options": {"A": "男兒寧當格鬥死，何能怫鬱築長城(陳琳〈飲馬長城窟行〉)", "B": "誤落塵網中，一去十三年(陶淵明〈歸園田居〉)", "C": "洛陽親友如相問，一片冰心在玉壺(王昌齡〈芙蓉樓送辛漸〉)", "D": "老僧已死成新塔，壞壁無由見舊題(蘇軾〈和子由澠池懷舊〉)"}, "answer": "D", "explain": "(D)蘇軾〈和子由澠池懷舊〉「老僧已死成新塔，壞壁無由見舊題」，當年接待他們的老和尚已經過世，骨灰入了新塔；以前題詩的牆壁也破了，看不到舊日的字跡，寫的正是世事變幻、人生無常，是答案。(A)寫築長城的役夫寧願戰死也不願憂鬱地築城，是控訴勞役之苦。(B)陶淵明說自己誤入官場十三年，是歸隱田園的悔悟。(C)王昌齡表明自己心地純潔，是自我表白。", "skill": "「人生無常」的句子常有「今昔對照」：人死了、牆壞了、景物依舊人事全非，找有「已、無由、舊」這類時間落差字眼的選項。"}], "difficulty": "易", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-21", "exam": "et103", "nums": [21], "form": "單題", "img": "img/et103-21.png", "source": "年齡代稱", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "及笄", "m": "女子十五歲"}, {"w": "強仕", "m": "四十歲（《禮記》「四十曰強，而仕」）"}, {"w": "知命", "m": "五十歲（《論語》「五十而知天命」）"}, {"w": "耳順", "m": "六十歲（「六十而耳順」）"}, {"w": "古稀", "m": "七十歲（杜甫「人生七十古來稀」）"}], "questions": [{"n": 21, "qtype": "單選", "stem": "下列選項「」內的詞語皆為年齡的代稱，請依序由少至長加以重新排列？\n甲、顏淵未及「強仕之年」，猝然辭世，孔子哀痛逾恆\n乙、蘇軾年逾「耳順」，猶因新舊黨爭，遭貶海南，客死異鄉\n丙、劉基早年隱居著書，「知命」之年，始出山襄助朱元璋一統天下\n丁、余光中雖年逾「古稀」，依然創作不輟，誠可謂老而彌堅者也\n戊、張愛玲年甫「及笄」，即以短篇小說馳譽文壇", "options": {"A": "甲戊乙丙丁", "B": "戊甲乙丙丁", "C": "戊甲丙乙丁", "D": "戊丙甲乙丁"}, "answer": "C", "explain": "把每個代稱換成歲數：戊「及笄」15歲、甲「強仕」40歲、丙「知命」50歲、乙「耳順」60歲、丁「古稀」70歲。由少到長是戊甲丙乙丁，答案(C)。(A)甲戊乙丙丁把40歲放在15歲前；(B)戊甲乙丙丁把60歲放在50歲前；(D)戊丙甲乙丁把50歲放在40歲前，都不對。", "skill": "年齡代稱多半來自《論語‧為政》：十五志學、三十而立、四十不惑、五十知命、六十耳順、七十從心；再加上及笄（女15）、弱冠（男20）、強仕（40）、古稀（70）。"}], "difficulty": "易", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-22", "exam": "et103", "nums": [22], "form": "單題", "img": "img/et103-22.png", "source": "《易經》常識", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "爻", "m": "組成卦的符號，陽爻「—」、陰爻「--」"}, {"w": "九、六", "m": "陽爻稱九、陰爻稱六"}, {"w": "乾", "m": "象徵天；坤象徵地"}, {"w": "易有三義", "m": "簡易、變易、不易"}], "questions": [{"n": 22, "qtype": "單選", "stem": "下列選項對於《易經》的敘述，何者正確？", "options": {"A": "卦爻的陽爻叫做六", "B": "乾卦所代表的原始物象是地", "C": "易有三義指的是蜥易、變易、不易", "D": "陰爻的符號是––"}, "answer": "D", "explain": "(D)陰爻的符號是中間斷開的「--」，陽爻是連續的「—」，正確，是答案。(A)陽爻稱「九」，陰爻才稱「六」（如「初九」「六二」），錯。(B)乾卦象徵天，坤卦才象徵地，錯。(C)東漢鄭玄說「易一名而含三義」：簡易、變易、不易，不是「蜥易」，錯（「易」字形雖有像蜥蜴的說法，但三義不包括它）。", "skill": "易經基本款一次記：陽爻—稱九、陰爻--稱六；乾天、坤地；三義＝簡易、變易、不易。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-23", "exam": "et103", "nums": [23], "form": "單題", "img": "img/et103-23.png", "source": "史書常識", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "《尚書》", "m": "上古政事文獻彙編，被視為現存最早的史書"}, {"w": "《漢書》", "m": "班固作，第一部斷代紀傳體史書"}, {"w": "紀傳體", "m": "以人物傳記為中心，正史的主要體裁"}, {"w": "《隋書‧經籍志》", "m": "正式確立經史子集四部分類"}], "questions": [{"n": 23, "qtype": "單選", "stem": "下列選項對於史書的敘述，何者錯誤？", "options": {"A": "《尚書》是中國現存最早的史書", "B": "《漢書》是中國第一部斷代紀傳體的史書", "C": "紀傳體是中國史書的主要體裁", "D": "中國史書的分類最早見於《漢書．藝文志》"}, "answer": "D", "explain": "題目問「錯誤」。(D)《漢書‧藝文志》分為六藝、諸子、詩賦、兵書、數術、方技六略，史書（如《史記》）附在「六藝略」的春秋類之下，並沒有獨立的史書分類；史部正式獨立要到魏晉的四部分類法，到《隋書‧經籍志》確立「經史子集」，所以(D)錯，是答案。(A)《尚書》記上古帝王的誥命、政事，是現存最早的史書，正確。(B)《漢書》專寫西漢一代，是第一部斷代紀傳體史書，正確。(C)二十四史都是紀傳體，是中國史書的主要體裁，正確。", "skill": "圖書分類記兩個里程碑：《漢書‧藝文志》六略（史附於春秋），《隋書‧經籍志》四部（經史子集）。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-29", "exam": "et103", "nums": [29], "form": "單題", "img": "img/et103-29.png", "source": "《左傳‧宮之奇諫假道》", "author": "左丘明", "genre": "史傳人物", "types": ["虛詞句式", "字詞解釋"], "passage": "晉不可啓，寇不可翫，一之謂甚，其可再乎？／且虞能親於桓莊乎？其愛之也，桓莊之族何罪？而以為戮。／若晉取虞，而明德以薦馨香，神其吐之乎？／諺所謂：輔車相依，唇亡齒寒者，其虞虢之謂也。", "translation": "晉國的野心不可以開啟，外敵不可以輕忽，借一次路已經太過分了，難道可以再借第二次嗎？／況且虞國能比桓叔、莊伯的後代更親近晉國嗎？如果晉國愛護他們，桓叔、莊伯的家族有什麼罪，卻被殺光了？／如果晉國奪取虞國，而以美德來獻上芳香的祭品，神難道會吐出來不接受嗎？／俗話所說：「頰骨和牙床互相依存，嘴唇沒了牙齒就會受寒」，大概就是說虞國和虢國的關係吧。", "keywords": [{"w": "啓", "m": "開啟（野心）"}, {"w": "翫", "m": "輕忽"}, {"w": "甚", "m": "過分"}, {"w": "桓莊", "m": "晉獻公的同族桓叔、莊伯"}, {"w": "戮", "m": "殺害"}, {"w": "薦", "m": "進獻"}, {"w": "吐", "m": "吐出，指不接受祭品"}, {"w": "輔車", "m": "頰骨與牙床"}], "questions": [{"n": 29, "qtype": "單選", "stem": "下列選項中有關「其」字的意義，何者解釋正確？(〈宮之奇諫假道〉)", "options": {"A": "晉不可啓，寇不可翫，一之謂甚，「其」可再乎？其，作代詞。", "B": "且虞能親於桓莊乎？「其」愛之也，桓莊之族何罪？而以為戮。其，作代詞。", "C": "若晉取虞，而明德以薦馨香，神「其」吐之乎？其，用法同「豈」。", "D": "諺所謂：輔車相依，唇亡齒寒者，「其」虞虢之謂也。其，用法同「豈」。"}, "answer": "C", "explain": "(C)「神其吐之乎」，神難道會把祭品吐出來嗎？「其」表反問，用法同「豈」，正確，是答案。(A)「其可再乎」是「難道可以再一次嗎」，「其」也是反問語氣（同「豈」），不是代詞，錯。(B)「其愛之也」是「如果（晉國）愛他們的話」，「其」表假設，不是代詞，錯。(D)「其虞虢之謂也」是「大概說的就是虞、虢吧」，「其」表推測，同「殆」，不是「豈」，錯。", "skill": "句首「其」的判斷：句末有「乎」表反問→豈；句末有「也、矣」表推測→大概；後面接條件→如果；後面接名詞→他的、那個（代詞）。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-30", "exam": "et103", "nums": [30], "form": "單題", "img": "img/et103-30.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "匠人斲而小之／孔子登泰山而小天下／器小易盈／小不忍，則亂大謀", "translation": "工匠把木材砍削得小了。／孔子登上泰山，就覺得天下變小了。／器量狹小的人容易自滿。／小事情不能忍耐，就會壞了大計畫。", "keywords": [{"w": "斲而小之", "m": "把它砍削變小；小＝使……變小"}, {"w": "小天下", "m": "覺得天下變小了；小＝以……為小"}, {"w": "器小易盈", "m": "器量小容易滿足；小＝狹小"}, {"w": "小不忍", "m": "小事不能忍耐；小＝小事"}], "questions": [{"n": 30, "qtype": "單選", "stem": "下列選項「」內的「小」字，何者意指「小事、小地方」？", "options": {"A": "匠人斲而「小」之", "B": "孔子登泰山而「小」天下", "C": "器「小」易盈", "D": "「小」不忍，則亂大謀"}, "answer": "D", "explain": "(D)「小不忍，則亂大謀」（《論語‧衛靈公》），小事情不能忍耐，就會壞了大計畫，「小」當名詞「小事」，與「大謀」相對，是答案。(A)《孟子》「匠人斲而小之」，工匠把木材削小，「小」是使動「使它變小」。(B)「孔子登泰山而小天下」，覺得天下變小了，「小」是意動「以……為小」。(C)「器小易盈」，器量狹小容易自滿，「小」是一般形容詞。", "skill": "詞性判斷：「小」後面接名詞（小天下、小之）多是動詞用法；單獨當主語、和「大謀」相對的是名詞「小事」。"}], "difficulty": "易", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-31", "exam": "et103", "nums": [31], "form": "單題", "img": "img/et103-31.png", "source": "《荀子‧天論》", "author": "荀子", "genre": "說理議論", "types": ["主旨寓意", "句意理解"], "passage": "天行有常，不為堯存，不為桀亡。應之以治則吉，應之以亂則凶。", "translation": "大自然的運行有一定的規律，不會因為堯是聖君就存在，也不會因為桀是暴君就消失。用合理的方法去因應它就吉祥，用錯亂的方法去因應它就有凶禍。", "keywords": [{"w": "天行", "m": "大自然的運行"}, {"w": "常", "m": "常規、規律"}, {"w": "堯", "m": "上古聖君"}, {"w": "桀", "m": "夏朝暴君"}, {"w": "應", "m": "因應、對待"}], "questions": [{"n": 31, "qtype": "單選", "stem": "荀子曰：「天行有常，不為堯存，不為桀亡。應之以治則吉，應之以亂則凶。」(〈天論〉)由上文可以意會出荀子對天的看法是：", "options": {"A": "天只是自然現象，沒有意志，沒有情感", "B": "天具有道德和理性的意義", "C": "天具有賞善罰惡的意志", "D": "人定勝天"}, "answer": "A", "explain": "「天行有常，不為堯存，不為桀亡」，天只按自己的規律運行，不會因為君主好壞而改變，可見荀子認為天只是自然現象，沒有意志、也沒有情感，答案(A)。(B)「天具有道德和理性的意義」較接近孟子的「天」，荀子的天沒有道德意涵。(C)「賞善罰惡」正是天有意志的說法，與「不為堯存，不為桀亡」相反。(D)「人定勝天」強調人要戰勝天，但引文只說人要好好因應天，結果吉凶在人，不是要打敗天。", "skill": "荀子的天＝自然的天（天行有常、明於天人之分）；看到天有意志、賞善罰惡的選項，就不是荀子的立場。"}], "difficulty": "易", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-32", "exam": "et103", "nums": [32], "form": "單題", "img": "img/et103-32.png", "source": "班固《漢書‧藝文志‧諸子略》", "author": "班固", "genre": "其他", "types": ["文化常識"], "passage": "陰陽家者流，蓋出於羲和之官，敬順昊天，歷象日月星辰，敬授民時，此其所長也。", "translation": "陰陽家這一派，大概出自古代掌管天文曆法的羲和之官，他們恭敬地順應上天，推算日月星辰的運行，把節令時序恭敬地傳授給百姓，這是他們的長處。", "keywords": [{"w": "九流十家", "m": "儒、道、陰陽、法、名、墨、縱橫、雜、農九流，加小說家為十家"}, {"w": "羲和之官", "m": "古代掌管天文曆法的官"}, {"w": "歷象", "m": "推算觀測天象"}, {"w": "敬授民時", "m": "把曆法節令頒授給百姓"}], "questions": [{"n": 32, "qtype": "單選", "stem": "班固〈漢書藝文志諸子略敘〉一文，將先秦思想綜釐成九流十家，並評論各家之長。其中以觀測天象、訂定歲曆、敬授民時為長的是哪一家？", "options": {"A": "儒家", "B": "縱橫家", "C": "道家", "D": "陰陽家"}, "answer": "D", "explain": "觀測天象、制定曆法、教百姓按節令耕作，是(D)陰陽家的長處，〈諸子略〉說陰陽家「出於羲和之官……歷象日月星辰，敬授民時」。(A)儒家出於司徒之官，長處在「助人君順陰陽明教化」、重仁義；(B)縱橫家出於行人之官，長於外交辭令；(C)道家出於史官，長於「秉要執本，清虛以自守」。", "skill": "九流十家記「出自什麼官＋擅長什麼」：陰陽家＝羲和之官、天文曆法；縱橫家＝行人之官、外交；農家＝農稷之官、耕作。"}], "difficulty": "易", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-33", "exam": "et103", "nums": [33], "form": "單題", "img": "img/et103-33.png", "source": "綜合（《詩經》）", "author": "", "genre": "古典詩詞曲", "types": ["字詞解釋", "寫作手法"], "passage": "其雨其雨，杲杲出日／蒹葭蒼蒼，白露為霜／南山烈烈，飄風發發／風雨淒淒，雞鳴喈喈", "translation": "盼著下雨啊下雨，偏偏出來明亮的太陽。／蘆葦長得青蒼茂盛，白色的露水凝結成霜。／南山高大險峻，狂風呼呼地吹。／風雨淒冷，雞喈喈地啼叫。", "keywords": [{"w": "杲杲", "m": "日光明亮的樣子"}, {"w": "蒼蒼", "m": "茂盛、青蒼的樣子"}, {"w": "發發", "m": "風聲疾速"}, {"w": "淒淒", "m": "寒涼的樣子"}, {"w": "喈喈", "m": "雞鳴聲"}], "questions": [{"n": 33, "qtype": "單選", "stem": "《詩經》慣用疊字來象聲摹狀，以達到聲韻諧和的修辭效果，請問下列「」內的疊字，何者是狀聲詞？", "options": {"A": "其雨其雨，「杲杲」出日(〈伯兮〉)", "B": "蒹葭「蒼蒼」，白露為霜(〈蒹葭〉)", "C": "南山烈烈，飄風「發發」(〈蓼莪〉)", "D": "風雨「淒淒」，雞鳴喈喈(〈風雨〉)"}, "answer": "C", "explain": "狀聲詞是模仿聲音的詞。(C)〈蓼莪〉「飄風發發」，「發發」形容狂風呼呼吹的聲音，是狀聲詞，是答案。(A)「杲杲出日」，「杲杲」是日光明亮的樣子，摹視覺。(B)「蒹葭蒼蒼」，「蒼蒼」是蘆葦茂盛青蒼的樣子，摹視覺。(D)「風雨淒淒」，「淒淒」是風雨寒涼的樣子，摹觸覺；同一句的「喈喈」才是雞鳴的狀聲詞，但題目框起來的是「淒淒」。", "skill": "疊字題問自己「能不能用耳朵聽到」：能聽到的（發發、喈喈、關關）是狀聲；用眼睛看、皮膚感覺的是狀貌。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-34", "exam": "et103", "nums": [34], "form": "單題", "img": "img/et103-34.png", "source": "丘逢甲〈離臺詩〉", "author": "丘逢甲", "genre": "古典詩詞曲", "types": ["文意推論", "人物情感"], "passage": "宰相有權能割地，孤臣無力可回天。扁舟去作鴟夷子，迴首河山意黯然。", "translation": "宰相有權力把國土割讓出去，我這孤立無援的臣子卻沒有力量挽回局面。只好乘著小船離去，像范蠡一樣浪跡江湖，回頭看看故鄉的河山，心中無比悲傷。", "keywords": [{"w": "宰相", "m": "指簽訂《馬關條約》割讓臺灣的李鴻章"}, {"w": "孤臣", "m": "詩人自稱，指抗日失敗的丘逢甲"}, {"w": "回天", "m": "扭轉局勢"}, {"w": "鴟夷子", "m": "范蠡助越滅吳後，改名鴟夷子皮，乘舟遠去"}, {"w": "黯然", "m": "心情沮喪悲傷"}], "questions": [{"n": 34, "qtype": "單選", "stem": "「宰相有權能割地，孤臣無力可回天。扁舟去作鴟夷子，迴首河山意黯然。」(〈離台詩〉)，這首詩中的「宰相」、「孤臣」分別是指何人？", "options": {"A": "李鴻章、丘逢甲", "B": "沈葆楨、丘逢甲", "C": "沈葆楨、唐景崧", "D": "李鴻章、唐景崧"}, "answer": "A", "explain": "這首〈離臺詩〉是丘逢甲在甲午戰後臺灣割日、抗日失敗內渡時所作。「宰相有權能割地」指代表清廷簽訂《馬關條約》、割讓臺灣的李鴻章；「孤臣無力可回天」是詩人自稱，指自己組織義軍抗日卻無力回天。答案(A)李鴻章、丘逢甲。(B)(C)沈葆楨是清末經營臺灣的大臣，早在割臺前就過世，與割地無關。(C)(D)唐景崧是臺灣民主國總統，但他不是詩的作者，詩中的「孤臣」是作者自稱。", "skill": "歷史詩題先確定「作者是誰、寫於何時」：〈離臺詩〉＝丘逢甲、乙未割臺，再對應當時簽約的人（李鴻章）。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-35", "exam": "et103", "nums": [35, 36], "form": "題組", "img": "img/et103-35.png", "source": "琦君〈讀書瑣憶〉（引袁枚詩、張潮《幽夢影》）", "author": "琦君", "genre": "其他", "types": ["寫作手法", "字詞解釋"], "passage": "雙目時將秋水洗，一生不受古人欺。（袁枚）\n少年讀書，如隙中窺月。中年讀書，如庭中賞月。老年讀書，如臺上望月。（張潮《幽夢影》）", "translation": "袁枚：時常用秋水般清澈的眼光洗亮雙眼，一輩子不被古人（古書）欺騙。\n張潮：少年時讀書，像從門縫中偷看月亮；中年時讀書，像在庭院中欣賞月亮；老年時讀書，像在高臺上眺望月亮。", "keywords": [{"w": "袁子才", "m": "清代詩人袁枚，字子才"}, {"w": "時將", "m": "時常拿"}, {"w": "秋水", "m": "比喻清澈明亮的眼睛"}, {"w": "糟粕", "m": "酒渣，比喻無價值的東西"}, {"w": "張心齋", "m": "清代張潮，號心齋，著《幽夢影》"}, {"w": "隙中窺月", "m": "從縫隙中看月，所見有限"}, {"w": "入乎其中，出乎其外", "m": "能深入又能跳脫出來"}], "questions": [{"n": 35, "qtype": "單選", "stem": "對上文中修辭方式的解說，下列選項何者錯誤？", "options": {"A": "「雙目時將秋水洗，一生不受古人欺」屬於對偶式修辭", "B": "「何者是不可不讀之書，何者是可供瀏覽之書，何者是糟粕」屬於類疊式修辭", "C": "「臺上望月，則由入乎其中，而出乎其外」屬於頂真式修辭", "D": "「少年讀書，如隙中窺月。中年讀書，如庭中賞月。老年讀書，如臺上望月」屬於排比式修辭"}, "answer": "C", "explain": "題目問「錯誤」。(C)「臺上望月，則由入乎其中，而出乎其外」，頂真是上句末字當下句首字（如「……楚國；楚國……」），這句只是「入乎其中／出乎其外」的對照，前後沒有接龍，不是頂真，所以錯，是答案。(A)「雙目時將秋水洗」對「一生不受古人欺」，字數相等、詞性相對，是對偶，正確。(B)「何者是……，何者是……，何者是……」重複使用「何者是」，是類疊，正確。(D)「少年讀書，如……。中年讀書，如……。老年讀書，如……」三句結構相同、意思相關，是排比，正確。", "skill": "頂真的檢查法：把上一句最後一個詞圈起來，看下一句是不是用它開頭；沒有「接龍」就不是頂真。"}, {"n": 36, "qtype": "單選", "stem": "對上文中字句所作的解說，下列選項何者錯誤？", "options": {"A": "慧眼，佛家指能透視過去、未來、一切事相的智慧", "B": "「雙目時將秋水洗」的「時將」，指未來的時間", "C": "文中將「古」字改為「世」字除了作者所提出的理由外，若從詩的格律上說，平仄亦無錯誤", "D": "「何者是糟粕」的「糟粕」，本指製酒所剩的酒渣，在這裡借指廢棄物"}, "answer": "B", "explain": "題目問「錯誤」。(B)「雙目時將秋水洗」的「時將」是「時常拿（秋水）來洗」，「時」是時常，「將」是拿、用，不是「指未來的時間」，所以錯，是答案。(A)「慧眼」原是佛家五眼之一，指能看透一切事相的智慧之眼，正確。(C)原句「一生不受古人欺」，「古」與「世」都是仄聲字，替換後平仄不變，格律沒有問題，正確。(D)「糟粕」原指釀酒剩下的酒渣，這裡借指沒有價值、應丟棄的書，正確。", "skill": "文言的「將」常是「拿、用」（將＋名詞＋動詞），不要直接當成現代的「將要」。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-37", "exam": "et103", "nums": [37, 38], "form": "題組", "img": "img/et103-37.png", "source": "紀昀〈與子書〉", "author": "紀昀", "genre": "書信序跋", "types": ["句意理解", "主旨寓意", "人物情感"], "passage": "爾在官，不宜數問家事。道遠鴻稀，徒亂人意，正以無家信為平安耳。爾向家居本少，二老習為固然，歲時伏臘，不甚思念。今遣爾妻子赴任，未免增一番悵戀，想亦不過一時情緒，久後漸就平坦，無為過慮。山僻知縣，事簡責輕，最足鈍人志氣，須時時將此心提醒激發，無事尋出有事，有事終歸無事。今服官年餘，民情熟悉，正好興利除害。若因地方偏小，上司或存寬恕，偷安藏拙，日成痿痺，是為世界木偶人，無論將來不克大有作為，無以對此山谷愚民，且何以無負師門指授？", "translation": "你在外做官，不應該常常過問家裡的事。路途遙遠、書信難通，寫信回來只是讓人心煩意亂，正好把沒有家信當作平安的消息。你向來在家的日子本來就少，我們兩老早就習慣了，逢年過節也不怎麼想念。現在讓你的妻子兒女去你的任所，難免讓我們多一番惆悵依戀，想來也只是一時的情緒，日子久了就會漸漸平復，你不必過分擔心。\n在偏僻山區當知縣，事情簡單、責任輕，最容易消磨人的志氣，必須時時提醒、激勵自己這顆心：沒有事的時候要主動找出該做的事，有事的時候最終要把它妥善處理到沒事。現在你做官一年多了，民情已經熟悉，正好可以興辦有利的事、除去禍害。如果因為地方偏僻狹小，上級長官或許對你比較寬容，你就苟且偷安、藏拙不做事，一天天麻木下去，那就成了世上的木頭人，且不說將來不能有大作為，也沒有辦法對得起這些山中淳樸的百姓，又怎能不辜負師長的教導呢？", "keywords": [{"w": "數", "m": "屢次"}, {"w": "鴻", "m": "鴻雁，代指書信"}, {"w": "歲時伏臘", "m": "一年中的節日，泛指逢年過節"}, {"w": "悵戀", "m": "惆悵依戀"}, {"w": "鈍人志氣", "m": "消磨人的志氣"}, {"w": "偷安藏拙", "m": "苟且偷安、藏起不足而不做事"}, {"w": "痿痺", "m": "肢體麻木，比喻精神萎靡"}, {"w": "不克", "m": "不能"}, {"w": "師門指授", "m": "師長的教導"}], "questions": [{"n": 37, "qtype": "單選", "stem": "對於上文的解說，下列選項何者正確？", "options": {"A": "紀盷提醒孩子要常常寫家書回來，不能因為很少回家就懶得寫", "B": "紀盷之子在山中當知縣，常常惹出許多事來，所以告誡他", "C": "紀盷告誡其子，不可因為地處偏僻就苟且因循，應該為人民興利除害", "D": "因為所治地方偏小，紀盷之子已經養成偷安習慣，對不起其師長的教誨"}, "answer": "C", "explain": "第二段是全文重點：山僻小縣容易消磨志氣，你要時時激勵自己，趁熟悉民情「興利除害」，不可因地方偏小、上司寬容就「偷安藏拙」，(C)完全吻合，是答案。(A)紀昀正好叫兒子不要常寫家書（「不宜數問家事」「以無家信為平安」），錯。(B)「無事尋出有事」是要兒子主動找事做，不是說兒子常惹事，錯。(D)「若因地方偏小……」是假設語氣的提醒，不是說兒子已經養成偷安習慣，錯。", "skill": "家書的主旨通常在「須……」「若……則……」的叮嚀句，注意「若」是假設提醒，不是已發生的事實。"}, {"n": 38, "qtype": "單選", "stem": "對文中詞句的解釋，下列選項何者錯誤？", "options": {"A": "「道遠鴻稀，徒亂人意」是說「你在遠地書信來往不便，如果專程寫信來，反而令人心生煩亂」", "B": "「爾向家居本少，二老習為固然」是說「你向來居家時日就很少，我們二老早就習慣了」", "C": "「無事尋出有事，有事終歸無事」是指「沒事總弄出些事來，有事的時候又裝作沒事」", "D": "「若因地方偏小，上司或存寬恕，偷安藏拙，日成痿痺，是為世界木偶人」是說「如果因為地方偏僻，上級長官有時心存寬厚，你就偷懶裝呆，一天天麻痺下去，那你就成為這世上沒有知覺的木頭人了」"}, "answer": "C", "explain": "題目問「錯誤」。(C)「無事尋出有事，有事終歸無事」是說：沒事時要主動找出該做的事，有事時要把事情處理到妥善了結；選項解成「沒事找事、有事裝沒事」，意思完全相反，所以錯，是答案。(A)「道遠鴻稀，徒亂人意」，路遠信少，寫信回來只會讓人心亂，正確。(B)「爾向家居本少，二老習為固然」，你一向少在家，我們早就習慣了，正確。(D)「若因地方偏小……是為世界木偶人」，因地方偏僻、上司寬容就偷懶麻木，便成了沒有知覺的木頭人，正確。", "skill": "理解句子要配合上下文的態度：紀昀整段在勉勵兒子積極任事，解釋若出現「裝作沒事」這種消極意思，一定不合文意。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-39", "exam": "et103", "nums": [39, 40], "form": "題組", "img": "img/et103-39.png", "source": "顏之推《顏氏家訓‧教子》", "author": "顏之推", "genre": "說理議論", "types": ["主旨寓意", "文意推論"], "passage": "上智不教而成，下愚雖教無益，中庸之人，不教不知也。古者，聖王有胎教之法：懷子三月，出居別宮，目不邪視，耳不妄聽，音聲滋味，以禮節之。書之玉版，藏諸金匱。子生咳提，師保固明孝仁禮義，導習之矣。凡庶縱不能爾，當及嬰稚，識人顏色，知人喜怒，便加教誨，使為則為，使止則止。比及數歲，可省笞罰。父母威嚴而有慈，則子女畏慎而生孝矣。吾見世間，無教而有愛，每不能然；飲食運為，恣其所欲，宜誡翻獎，應訶反笑，至有識知，謂法當爾。驕慢已習，方復制之，捶撻至死而無威，忿怒日隆而增怨，逮于成長，終為敗德。孔子云：「少成若天性，習慣如自然」是也。俗諺曰：「教婦初來，教兒嬰孩。」誠哉斯語！", "translation": "天資最高的人不用教就能成材，天資最低的人即使教了也沒有用，中等資質的人，不教就不懂事理。古代的聖王有胎教的方法：王后懷孕三個月，就搬出去住在別的宮室，眼睛不看不正當的東西，耳朵不聽不正當的聲音，音樂和飲食都用禮來節制。把這些方法寫在玉版上，收藏在金櫃裡。孩子生下來還在幼兒時期，負責教導的師保就要闡明孝、仁、禮、義，引導他學習。一般人家即使做不到這樣，也應該在孩子還是嬰兒、能認得人的臉色、知道人的喜怒時，就加以教導，叫他做就做，叫他停就停。等到長到幾歲，就可以少用鞭打處罰。父母威嚴而又慈愛，子女就會敬畏謹慎而生出孝心。我看世上有些父母，不教導只溺愛，常常不是這樣：孩子的飲食行為，都放任他想怎樣就怎樣，該告誡時反而誇獎，該斥責時反而嘻笑，等到孩子懂事了，以為本來就該這樣。驕傲怠慢的習性已經養成，才要去制止，就算鞭打到死也建立不了威嚴，父母的怒氣一天天增加，孩子的怨恨也越來越深，到長大成人，終究成為品德敗壞的人。孔子說：「年少時養成的就像天性，習慣了就像自然一樣。」就是這個道理。俗話說：「教媳婦要在剛進門時，教孩子要在嬰孩時。」這句話說得真對啊！", "keywords": [{"w": "上智、下愚", "m": "天資最高與最低的人"}, {"w": "中庸之人", "m": "資質中等的人"}, {"w": "金匱", "m": "金屬做的櫃子"}, {"w": "咳提", "m": "同「孩提」，幼兒"}, {"w": "師保", "m": "負責教導王子的官"}, {"w": "凡庶", "m": "一般百姓"}, {"w": "笞罰", "m": "鞭打處罰"}, {"w": "運為", "m": "行為舉止"}, {"w": "宜誡翻獎", "m": "應該告誡的反而誇獎"}, {"w": "訶", "m": "同「呵」，斥責"}, {"w": "逮于", "m": "等到"}], "questions": [{"n": 39, "qtype": "單選", "stem": "本文主旨為何？", "options": {"A": "教育的重點在於及時糾正錯誤行為", "B": "棒下出孝子", "C": "教育應以威嚴為要，才能使兒童有效學習", "D": "父母應重視胎教，除此之外，別無他法"}, "answer": "A", "explain": "全文一再強調「趁早」：胎教、孩提時就教，「當及嬰稚……便加教誨」，等到驕慢已經養成「方復制之」就來不及了，最後以「教兒嬰孩」作結。重點是要及早、及時糾正孩子的錯誤行為，答案(A)。(B)「棒下出孝子」與文中「捶撻至死而無威」相反，作者並不主張打罵。(C)作者主張「威嚴而有慈」，不是只靠威嚴。(D)胎教只是古代聖王的例子，作者接著說一般人「縱不能爾」也要及早教誨，並非「除此之外別無他法」。", "skill": "主旨題找「重複出現的概念」：胎教、孩提、嬰稚、教兒嬰孩，都在講「早」，主旨就是及早教育。"}, {"n": 40, "qtype": "單選", "stem": "作者認為某些人成長後品行不良的原因為：", "options": {"A": "父母捶撻至死而無威", "B": "父母沒有聘用良師", "C": "父母威嚴有慈", "D": "父母恣其所欲，慣於驕慢的行為"}, "answer": "D", "explain": "作者說世間父母「無教而有愛」，「飲食運為，恣其所欲，宜誡翻獎，應訶反笑」，讓孩子驕慢成習，長大「終為敗德」，原因是(D)父母放縱孩子、讓他習慣驕慢。(A)「捶撻至死而無威」是驕慢養成後才補救的結果，不是根本原因。(B)聘請良師文中沒有提到是品行不良的原因。(C)「父母威嚴有慈」是正面做法，會使子女「畏慎而生孝」，正好相反。", "skill": "因果題要分清「原因」和「後果」：先放縱（原因）→後打罵無效（後果）→敗德（結果），選最源頭的那一個。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-41", "exam": "et103", "nums": [41, 42], "form": "題組", "img": "img/et103-41.png", "source": "應用文（書信）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "父親大人", "m": "書信中對父親的稱呼"}, {"w": "敬請 福安", "m": "對祖父母、父母的結尾問候語"}, {"w": "安啟", "m": "對長輩的啟封詞"}, {"w": "敝校、本校", "m": "稱自己的學校"}, {"w": "貴校", "m": "稱對方的學校"}, {"w": "食指浩繁", "m": "家中吃飯的人很多，指家庭負擔重"}], "questions": [{"n": 41, "qtype": "單選", "stem": "書信內文中各種用語，以下何者有誤？", "options": {"A": "信中稱到父親時，應該用「父親」或「父親大人」", "B": "書信中提到她自己所念的大學時，宜用「貴校」", "C": "結尾的祝福語，應該用「敬請　福安」", "D": "信封上的啟封詞，應用「安啟」"}, "answer": "B", "explain": "題目問「有誤」。(B)「貴校」是稱呼對方的學校；美麗提到自己就讀的大學，應用「本校」或「敝校」，所以錯，是答案。(A)寫給父親，稱「父親」或「父親大人」，正確。(C)對父母的結尾問候語用「敬請 福安」，正確。(D)寫給長輩的信封啟封詞用「安啟」，正確。", "skill": "「貴、令、尊」是稱對方，「敝、家、舍、本」是稱自己；寫信時先確認說的是誰的東西。"}, {"n": 42, "qtype": "單選", "stem": "美麗希望父親寄來生活費，以下用語，內容何者為宜？", "options": {"A": "最近需錢孔急，趕快寄來生活費吧", "B": "生不逢時，民不聊生，希望能早日收到生活費匯款", "C": "因為食指浩繁，入不敷出，希望能儘早收到生活費匯款", "D": "民生物價飛漲，又需支應學校購書所需，希望能早日收到生活費匯款"}, "answer": "D", "explain": "向父親要生活費，要說明合理原因、語氣恭敬。(D)說明物價上漲、又要買書，再委婉表示希望早日收到匯款，原因具體、語氣得體，是答案。(A)「趕快寄來生活費吧」是命令口氣，對父親不夠恭敬。(B)「生不逢時，民不聊生」是形容時局動盪、百姓無法生活，用在要生活費太誇張。(C)「食指浩繁」是家中人口多、吃飯的人多，是一家之主說家計負擔重的話，學生用在自己身上不恰當。", "skill": "應用文措辭題，先刪「語氣不敬」的，再刪「成語用錯對象或太誇張」的，剩下的通常就是答案。"}], "difficulty": "易", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-43", "exam": "et103", "nums": [43, 44], "form": "題組", "img": "img/et103-43.png", "source": "張說〈錢本草〉", "author": "張說", "genre": "寓言故事", "types": ["寫作手法", "句意理解", "主旨寓意"], "passage": "錢，味甘，大熱，有毒。偏能駐顏，采澤流潤，善療饑寒、困厄之患，立驗。能利邦國，汙賢達，畏清廉。貪婪者服之，以均平為良；如不均平，則冷熱相激，令人霍亂。其藥採無時，採至非禮，則傷神。此既流行，能役神靈，通鬼氣。如積而不散，則有水火盜賊之災生；如散而不積，則有饑寒困厄之患至。一積一散謂之道，不以為珍謂之德，取與合宜謂之義，無求非分謂之禮，博施濟眾謂之仁，出不失期謂之信，入不妨己謂之智。以此七術精煉方可，久而服之，令人長壽。若服之非禮，則弱志傷神，切須忌之。", "translation": "錢，味道甘甜，性質大熱，有毒。特別能讓人容顏不老、光彩潤澤，善於治療飢寒、困苦的病，立刻見效。能使國家富強，能玷污賢達的人，但害怕清廉的人。貪心的人服用它，要平均適量才好；如果不平均，就會冷熱交攻，讓人上吐下瀉。這味藥隨時都可以採，但用不合禮的方法去採，就會傷害精神。它流通之後，能役使神靈，能與鬼相通。如果只積聚而不散發，就會有水災、火災、盜賊的禍害發生；如果只散發而不積聚，就會有飢寒困苦的憂患到來。一積一散叫做「道」，不把它看得太珍貴叫做「德」，取得與給予都合宜叫做「義」，不求不該得的叫做「禮」，廣泛施捨救濟大眾叫做「仁」，借出去按時歸還叫做「信」，取得錢財而不傷害自己叫做「智」。用這七種方法精煉這味藥才可以，長期服用，能讓人長壽。如果用不合禮的方式服用，就會削弱志氣、傷害精神，千萬要避免。", "keywords": [{"w": "本草", "m": "藥物書"}, {"w": "駐顏", "m": "保持容顏不老"}, {"w": "采澤流潤", "m": "光彩潤澤"}, {"w": "汙", "m": "玷污"}, {"w": "霍亂", "m": "上吐下瀉的急病"}, {"w": "採無時", "m": "隨時可以採"}, {"w": "非分", "m": "不該得的"}, {"w": "出不失期", "m": "借出按期收回；一說支出不誤期限"}, {"w": "入不妨己", "m": "收入不傷害自己"}], "questions": [{"n": 43, "qtype": "單選", "stem": "本篇若就其行文方法來看，應是屬於：", "options": {"A": "諷喻文", "B": "論說文", "C": "抒情文", "D": "應用文"}, "answer": "A", "explain": "作者仿照藥書（本草）的寫法，說錢「味甘、大熱、有毒」，能治飢寒、會讓人霍亂，其實是借藥性來諷刺世人對錢的貪求、教人正確用錢，表面寫藥、實則諷勸，屬(A)諷喻文。(B)論說文是直接提出論點、論證，本文用擬物的方式間接表達；(C)抒情文以抒發個人情感為主，本文沒有；(D)應用文是書信、公文等實用文書，本文是模仿藥書的遊戲筆墨，並非真的實用文書。", "skill": "「用甲寫乙」的文章（以藥寫錢、以動物寫人）多是諷喻或寓言；先問作者真正想說的是不是字面上的東西。"}, {"n": 44, "qtype": "單選", "stem": "作者所列用錢七術中，稱「入不妨己謂之智」，意謂：", "options": {"A": "取得錢財但不傷害自己才是智慧", "B": "不讓別人管理自己的錢財才是智慧", "C": "自己或別人都不受錢之役使才是智慧", "D": "不能用錢妨害別人才是智慧"}, "answer": "A", "explain": "「入」是錢財進來、取得錢財；「不妨己」是不妨害自己。「入不妨己謂之智」意思是：取得錢財卻不因此傷害自己（品德、身家），才算聰明，答案(A)。(B)說不讓別人管理自己的錢，文中沒有；(C)「不受錢役使」比較接近「不以為珍謂之德」；(D)把「己」誤解成「別人」，原文說的是不妨害自己。", "skill": "七術每句都是「動作＋條件」：出／入是支出與收入，「己」就是自己；先把每個字照字面翻，再組合。"}], "difficulty": "中", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et103-45", "exam": "et103", "nums": [45, 46], "form": "題組", "img": "img/et103-45.png", "source": "蘇軾〈登州海市〉", "author": "蘇軾", "genre": "古典詩詞曲", "types": ["文意推論", "詩詞賞析", "典故出處"], "passage": "東方雲海空復空，群仙出沒空明中。蕩搖浮世生萬象，豈有貝闕藏珠宮。心知所見皆幻影，敢以耳目煩神工。歲寒水冷天地閉，為我起蟄鞭魚龍。重樓翠阜出霜曉，異事驚倒百歲翁。人間所得容力取，世外無物誰為雄。率然有請不我拒，信我人厄非天窮。潮陽太守南遷歸，喜見石廩堆祝融。自言正直動山鬼，豈知造物哀龍鍾。伸眉一笑豈易得，神之報汝亦已豐。斜陽萬里孤鳥沒，但見碧海磨青銅。新詩綺語亦安用，相與變滅隨東風。", "translation": "東方的雲海空了又空，一群仙人在空明的天光中時隱時現。浮動的人世搖盪出千萬種景象，哪裡真有用貝殼築成的宮闕、藏著珍珠的宮殿呢？我心裡明白所見的都是幻影，卻還是冒昧地用耳目所求來勞煩神明。年終天寒、水冷、天地閉塞，海神卻為我喚醒蟄伏的魚龍。重重的樓閣、青翠的山巒在結霜的清晨出現，這奇異的景象連百歲老翁都驚嘆。人間所能得到的東西可以靠力氣爭取，世外之物又有誰能稱雄呢？我隨口一請，海神竟然沒有拒絕我，可見我的困厄是人為的，並不是天要我窮困。韓愈當年從潮陽南遷北歸，高興地看見衡山的石廩峰、祝融峰；他自稱是正直感動了山鬼，哪知是造物者可憐他年老龍鍾。能舒展眉頭一笑哪裡容易得到呢？神明對你的報答已經很豐厚了。夕陽照著萬里海天，一隻孤鳥消失無蹤，只看見碧藍的海面像磨亮的青銅鏡。我這些新詩美語又有什麼用呢？就讓它和海市一起隨東風消散吧。", "keywords": [{"w": "海市", "m": "海市蜃樓，光線折射形成的幻景"}, {"w": "貝闕、珠宮", "m": "傳說中海神用貝殼、珍珠建的宮殿"}, {"w": "神工", "m": "神明"}, {"w": "起蟄", "m": "喚醒冬眠蟄伏的動物"}, {"w": "翠阜", "m": "青翠的山"}, {"w": "率然", "m": "隨意、輕率"}, {"w": "人厄", "m": "人為的困厄"}, {"w": "潮陽太守", "m": "指韓愈，曾被貶潮州"}, {"w": "石廩、祝融", "m": "衡山的山峰"}, {"w": "龍鍾", "m": "年老體衰的樣子"}, {"w": "磨青銅", "m": "海面平靜像磨亮的銅鏡"}], "questions": [{"n": 45, "qtype": "單選", "stem": "從上文看來，蘇軾認為自己得以目睹海市蜃樓的主要原因為何？", "options": {"A": "正直感動山鬼", "B": "誠心感動海神", "C": "見聞廣博，自然得見", "D": "純粹為詩人幻想"}, "answer": "B", "explain": "詩中說「歲寒水冷天地閉，為我起蟄鞭魚龍」，冬天本來不會有海市，海神卻特地為他喚醒魚龍；又說「率然有請不我拒」，他隨口一求，神就沒有拒絕。可見蘇軾認為是自己的請求感動了海神，答案(B)誠心感動海神。(A)「自言正直動山鬼」說的是韓愈（潮陽太守）的事，蘇軾還笑他「豈知造物哀龍鍾」，不是蘇軾自己的看法。(C)見聞廣博文中沒有提到。(D)雖說「心知所見皆幻影」，但他確實見到了海市，不是純粹幻想。", "skill": "詩中出現另一個人的典故時（潮陽太守＝韓愈），要分清楚哪些話是在說別人、哪些才是作者自己的事。"}, {"n": 46, "qtype": "單選", "stem": "以下成語，何者是「海市蜃樓」的相似詞？", "options": {"A": "沉魚落雁", "B": "呼風喚雨", "C": "閉月羞花", "D": "夢幻泡影"}, "answer": "D", "explain": "「海市蜃樓」是光線折射造成的幻象，比喻虛幻不實的事物；(D)「夢幻泡影」出自《金剛經》，比喻一切虛幻不實，意思最相近，是答案。(A)「沉魚落雁」、(C)「閉月羞花」都是形容女子貌美；(B)「呼風喚雨」是形容神通廣大或能操控局勢，都與虛幻無關。", "skill": "成語近義題先把題目的成語翻成一個核心概念（虛幻），再找核心概念相同的選項。"}], "difficulty": "難", "label": "103二技", "year": 103, "kind": "二技"}, {"id": "et104-03", "exam": "et104", "nums": [3], "form": "單題", "img": "img/et104-03.png", "source": "漢樂府〈有所思〉", "author": "佚名", "genre": "古典詩詞曲", "types": ["詩詞賞析", "字詞解釋"], "passage": "妃呼唏！秋風肅肅晨風颸，東方須臾高知之。", "translation": "唉！秋風颯颯地吹，晨風鳥在悲鳴；等東方一亮，天就會明白我的心意了。", "keywords": [{"w": "妃呼唏", "m": "樂府中表聲的嘆詞，相當於「唉」，表示歎息；一般版本寫作「妃呼豨」"}, {"w": "肅肅", "m": "風聲"}, {"w": "晨風", "m": "鳥名，即鸇；一說為晨間的風"}, {"w": "颸", "m": "疾速、悲涼的樣子"}, {"w": "須臾", "m": "一會兒"}, {"w": "高", "m": "通「皓」，天色發白"}], "questions": [{"n": 3, "qtype": "單選", "stem": "樂府詩〈有所思〉：「妃呼唏！秋風肅肅晨風颸，東方須臾高知之」，句中「妃呼唏」表達何種情緒？", "options": {"A": "歎息", "B": "懷疑", "C": "驚訝", "D": "喝斥"}, "answer": "A", "explain": "〈有所思〉寫女子聽說情人變心，決定把信物燒掉、一刀兩斷，可是又想起當初的情意而不捨，「妃呼唏」（一般版本寫作「妃呼豨」）就是這時發出的一聲長嘆，接著寫秋風悲鳴、等天亮再說，滿是無奈。(A)正確，是歎息聲。(B)懷疑：句子沒有疑問、猜測的語氣。(C)驚訝：她早已知道對方變心，不是突然吃驚。(D)喝斥：沒有對人發怒罵人，後文是自言自語的感傷。", "skill": "樂府、古詩裡的「妃呼豨」「噫吁嚱」這類怪字，多半是表聲的嘆詞，先看前後情境是悲是喜，再判斷情緒。"}], "difficulty": "中", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-04", "exam": "et104", "nums": [4], "form": "單題", "img": "img/et104-04.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "文化常識"], "passage": "孤違蹇叔，以辱二三子／僕少小好為文章，迄至於今／今急而求子，是寡人之過也／公子若反晉國，則何以報不穀", "translation": "(A)我違背了蹇叔的勸告，連累了各位。(B)我從小就喜歡寫文章，直到現在。(C)如今情勢危急才來求您，這是我的過錯。(D)公子如果回到晉國，要拿什麼來報答我？", "keywords": [{"w": "孤", "m": "諸侯謙稱自己，意思是寡德之人"}, {"w": "寡人", "m": "國君謙稱，寡德之人"}, {"w": "不穀", "m": "國君謙稱，不善之人"}, {"w": "僕", "m": "一般人謙稱自己，像「在下」"}], "questions": [{"n": 4, "qtype": "單選", "stem": "下列「」內的詞，何者不是古代君主的自稱？", "options": {"A": "「孤」違蹇叔，以辱二三子", "B": "「僕」少小好為文章，迄至於今", "C": "今急而求子，是「寡人」之過也", "D": "公子若反晉國，則何以報「不穀」"}, "answer": "B", "explain": "古代國君謙稱自己常用「孤、寡人、不穀」，都帶有「我德行不夠」的自謙意味。(A)是秦穆公在崤之戰後自責的話，「孤」是國君自稱。(B)正確，出自曹植〈與楊德祖書〉，「僕」是一般人謙稱自己，像現在說「在下」，不是君主專用。(C)出自〈燭之武退秦師〉，鄭文公向燭之武認錯，「寡人」是國君自稱。(D)是楚成王問重耳將來如何報答，「不穀」是楚王自稱。", "skill": "把「孤、寡人、不穀、朕」記成君主專用組，「僕、愚、鄙人、在下」是一般謙稱組，看到就分組。"}], "difficulty": "易", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-06", "exam": "et104", "nums": [6], "form": "單題", "img": "img/et104-06.png", "source": "《朱子語錄》；梁實秋《雅舍談吃‧序言》", "author": "朱熹；梁實秋", "genre": "經典語錄", "types": ["比較閱讀", "文意推論"], "passage": "問：「飲食之間，孰為天理？孰為人欲？」曰：「飲食者，天理也；要求美味，人欲也。學者須是革盡人欲，復盡天理，方始是學。」", "translation": "有人問：「吃喝這件事，哪部分是天理？哪部分是人欲？」朱熹回答：「吃飯喝水是天理；講究要吃得美味，就是人欲。求學的人必須把人欲完全去除，恢復全部的天理，這才算是真正在學習。」", "keywords": [{"w": "孰", "m": "哪一個"}, {"w": "天理", "m": "自然、合理的本分"}, {"w": "人欲", "m": "個人的私欲"}, {"w": "革盡", "m": "完全去除"}, {"w": "方始", "m": "才"}], "questions": [{"n": 6, "qtype": "單選", "stem": "閱讀下文，推斷何者最符合梁實秋對「要求美味」的想法？\n《朱子語錄》云：「問：『飲食之間，孰為天理？孰為人欲？』曰：『飲食者，天理也；要求美味，人欲也。學者須是革盡人欲，復盡天理，方始是學。』」我的想法異於是。我以為要求美味固是人欲，然而何曾有背於天理？(梁實秋《雅舍談吃‧序言》)", "options": {"A": "既無關天理，也無關人欲", "B": "原即天理，豈能視為人欲", "C": "有時是人欲，有時是天理", "D": "既是人欲，也在天理之中"}, "answer": "D", "explain": "朱熹認為吃飽是天理、講究美味是人欲，必須去掉。梁實秋說「我以為要求美味固是人欲，然而何曾有背於天理？」——前半句承認它是人欲，後半句說它並不違背天理。(D)正確，既是人欲也在天理之中。(A)他明說「固是人欲」，不是無關。(B)他沒有否認是人欲，只是說不違背天理。(C)他沒有分「有時」，而是同時成立。", "skill": "遇到「固是……，然而……」的句型，前半是讓步承認，後半才是作者真正立場，兩半都要放進答案。"}], "difficulty": "易", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-07", "exam": "et104", "nums": [7], "form": "單題", "img": "img/et104-07.png", "source": "《論語》", "author": "孔子及其弟子", "genre": "經典語錄", "types": ["主旨寓意", "句意理解"], "passage": "學而不思則罔，思而不學則殆。／學如不及，猶恐失之。／學而時習之，不亦說乎？", "translation": "只讀書而不思考，就會迷惘沒有收穫；只空想而不讀書，就會疑惑危險。／求學要像追趕不上似的努力，學到了還怕會忘掉。／學了之後時常溫習，不也很快樂嗎？", "keywords": [{"w": "罔", "m": "迷惘，沒有收穫"}, {"w": "殆", "m": "疑惑、危險"}, {"w": "說", "m": "同「悅」，快樂"}], "questions": [{"n": 7, "qtype": "單選", "stem": "閱讀下文，推斷最符合其要旨的文句為何？（引文：我們暫不自行思索而拿書來讀時，會覺得很輕鬆，然而在讀書時，我們的頭腦實際上成為別人思想的運動場了。所以，讀書愈多，或整天沉浸讀書的人，雖然可藉以休養精神，但他的思維能力必將漸次喪失。）", "options": {"A": "學而不思則罔", "B": "思而不學則殆", "C": "學如不及，猶恐失之", "D": "學而時習之，不亦說乎"}, "answer": "A", "explain": "引文說只顧讀書、不自己思考，頭腦就成了別人思想的運動場，思考能力會慢慢喪失——重點是「讀很多卻不思考」的壞處。(A)正確，「學而不思則罔」正是只學不想會迷惘。(B)講的是反方向：只想不學會危險，和引文相反。(C)勉勵人勤學、怕來不及，沒有批評讀太多。(D)說學習並溫習很快樂，和「思考能力喪失」無關。", "skill": "先把白話引文濃縮成「做了甲、沒做乙→壞處」，再找文言句中甲乙位置相同的那一句，小心正反顛倒的陷阱。"}], "difficulty": "易", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-08", "exam": "et104", "nums": [8], "form": "單題", "img": "img/et104-08.png", "source": "《古今圖書集成‧醫部全錄》", "author": "陳夢雷等編", "genre": "筆記小品", "types": ["文意推論", "字詞解釋"], "passage": "歷代方士皆謂有不死藥以惑時君，既而煉藥不成，或勸服藥反速其至死者多矣。金末，道士丘處機應蒙古國主聘，問：「有好長生之藥麼？」對曰：「有衞生之道，無長生之藥。」可謂傑然不群者矣。", "translation": "歷代的方士都說有長生不死的藥，用來迷惑當時的君王；後來藥煉不成，或是勸君王服藥反而加速死亡的例子很多。金朝末年，道士丘處機應蒙古國君的邀請，國君問他：「有好的長生藥嗎？」他回答：「只有保養生命的方法，沒有長生不老的藥。」真可說是卓越出眾、與眾不同的人啊。", "keywords": [{"w": "方士", "m": "講求煉丹求仙的人"}, {"w": "惑", "m": "迷惑、欺騙"}, {"w": "速", "m": "加快、招致"}, {"w": "聘", "m": "邀請"}, {"w": "衞生", "m": "保養、保護生命"}, {"w": "傑然不群", "m": "傑出而與眾不同"}], "questions": [{"n": 8, "qtype": "單選", "stem": "閱讀下文，推斷作者認為丘處機「傑然不群」的原因為何？", "options": {"A": "不向異族透露長生秘方", "B": "不假長生之藥害人利己", "C": "倡導養心可保長生不死", "D": "主張製藥須重清潔衛生"}, "answer": "B", "explain": "文章先說其他方士都用不死藥騙君王、害死人；丘處機面對有權勢的國君，卻老實說「無長生之藥」，不拿假藥討好、圖利，所以說他與眾不同。(B)正確。(A)他根本說沒有長生藥，不是藏起秘方不說。(C)他講的是保養生命，而且明說沒有長生，不是說能長生不死。(D)「衞生」是保護生命的意思，不是今天說的清潔衛生。", "skill": "文中先寫「大家都怎樣」再寫「某人不一樣」，答案就是兩者的差別；另外小心古今詞義不同，如「衞生」。"}], "difficulty": "易", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-09", "exam": "et104", "nums": [9], "form": "單題", "img": "img/et104-09.png", "source": "杜甫〈石壕吏〉", "author": "杜甫", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文意推論"], "passage": "暮投石壕村，有吏夜捉人。老翁逾墻走，老婦出門看。吏呼一何怒，婦啼一何苦。聽婦前致詞：三男鄴城戍，一男附書至，二男新戰死。存者且偷生，死者長已矣。室中更無人，惟有乳下孫。有孫母未去，出入無完裙。老嫗力雖衰，請從吏夜歸。急應河陽役，猶得備晨炊。夜久語聲絕，如聞泣幽咽。天明登前途，獨與老翁別。", "translation": "傍晚我投宿石壕村，夜裡有差吏來抓人。老先生翻牆逃走，老婆婆出門應付。差吏吼得多兇，婆婆哭得多苦。聽她上前說：三個兒子都去鄴城防守，一個兒子捎信來，兩個兒子剛戰死。活著的暫且苟活，死去的永遠走了。家裡再沒有別人，只有還在吃奶的孫子。因為有孫子，媳婦還沒離開，進出連件完整的裙子都沒有。老婦我雖然力氣衰弱，請讓我連夜跟您回去，趕去應付河陽的差役，還來得及準備早飯。夜深了說話聲停了，好像聽到低低的哭聲。天亮我上路時，只能和老先生一人道別。", "keywords": [{"w": "逾墻走", "m": "翻牆逃走"}, {"w": "一何", "m": "多麼"}, {"w": "戍", "m": "防守邊地"}, {"w": "長已矣", "m": "永遠結束了"}, {"w": "老嫗", "m": "老婦人自稱"}, {"w": "應", "m": "應付、服役"}], "questions": [{"n": 9, "qtype": "單選", "stem": "閱讀杜甫〈石壕吏〉，推斷誰在「有吏夜捉人」事件被迫隨官吏離家？", "options": {"A": "老翁", "B": "石壕吏", "C": "老翁之妻", "D": "老翁之子"}, "answer": "C", "explain": "老婦說「老嫗力雖衰，請從吏夜歸」，主動要求跟差吏去河陽服役；隔天詩人「獨與老翁別」，可見老婦已被帶走。(C)正確。(A)老翁翻牆躲起來，天亮後還在，詩人和他道別。(B)石壕吏本來就是來抓人的差吏，不是被迫離家。(D)三個兒子早已在鄴城從軍，兩個戰死，當晚並不在家。", "skill": "敘事詩問「誰怎麼了」，抓最後一句的結果（獨與老翁別）回推少了誰。"}], "difficulty": "易", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-10", "exam": "et104", "nums": [10], "form": "單題", "img": "img/et104-10.png", "source": "《論語‧陽貨》", "author": "孔子及其弟子", "genre": "經典語錄", "types": ["文意推論", "人物情感"], "passage": "子之武城，聞弦歌之聲，夫子莞爾而笑，曰：「割雞焉用牛刀？」子游對曰：「昔者偃也聞諸夫子曰：『君子學道則愛人，小人學道則易使也。』」子曰：「二三子！偃之言是也，前言戲之耳！」", "translation": "孔子到武城，聽到彈琴唱歌的聲音，微笑著說：「殺雞哪用得著宰牛的刀？」子游回答：「以前我聽老師說過：『在上位的人學了道就會愛護百姓，百姓學了道就容易聽從指揮。』」孔子說：「各位！子游說得對，我剛剛只是跟他開玩笑罷了！」", "keywords": [{"w": "之", "m": "往、到"}, {"w": "弦歌", "m": "彈琴唱歌，指禮樂教化"}, {"w": "莞爾", "m": "微笑的樣子"}, {"w": "偃", "m": "子游的名"}, {"w": "易使", "m": "容易差遣、教導"}, {"w": "戲", "m": "開玩笑"}], "questions": [{"n": 10, "qtype": "單選", "stem": "閱讀下文，選出符合文中敘述的選項：", "options": {"A": "子游行政才能不足，孔子以鼓勵代替責備", "B": "子游於小城施行禮樂，孔子始終不以為然", "C": "子游認為，教化對各個階層皆有正面價值", "D": "子游自覺辜負老師的期許，內心深感慚愧"}, "answer": "C", "explain": "子游在小小的武城推行禮樂，孔子半開玩笑說「殺雞用牛刀」；子游引老師的話，說君子學道會愛人、百姓學道好教導，孔子馬上承認他說得對。(C)正確，「君子」「小人」兩個階層學道都有好處。(A)武城有弦歌之聲，表示子游治理得好，不是能力不足。(B)孔子最後說「偃之言是也」，是認同，不是始終反對。(D)子游是有理有據地回應，沒有慚愧。", "skill": "對話題看「最後一句誰說了什麼」，孔子的結論常會推翻前面的玩笑或質疑。"}], "difficulty": "易", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-11", "exam": "et104", "nums": [11], "form": "單題", "img": "img/et104-11.png", "source": "藍鼎元〈紀水沙連〉", "author": "藍鼎元", "genre": "山水遊記", "types": ["文意推論", "字詞解釋"], "passage": "嶼無田，岸多蔓草。番取竹木結為桴，架水上，藉草承土以耕，遂種禾稻，謂之浮田。", "translation": "湖中小島沒有田地，湖岸長了很多蔓草。原住民拿竹子木頭綁成木筏，架在水面上，用蔓草墊底、上面承接泥土來耕作，於是種起稻子，稱為「浮田」。", "keywords": [{"w": "嶼", "m": "小島，指日月潭中的拉魯島"}, {"w": "番", "m": "清代對原住民的稱呼"}, {"w": "桴", "m": "竹木筏"}, {"w": "藉", "m": "墊"}, {"w": "承", "m": "承接、托住"}], "questions": [{"n": 11, "qtype": "單選", "stem": "閱讀下文，推斷「浮田」的特徵為何？", "options": {"A": "原住民逐水草而居，駕木筏於湖岸開墾農地", "B": "乘木筏剷除島嶼周邊的蔓草，填土擴張農地", "C": "在木筏先種植蔓草，再用來種稻的浮動農地", "D": "在水上以蔓草、木筏為基礎，覆土形成農地"}, "answer": "D", "explain": "做法依序是：竹木綁成筏→架在水上→鋪蔓草→放土→種稻。(D)正確，以木筏和蔓草當底座，上面覆土成田。(A)田是浮在水上，不是在湖岸開墾，也沒提逐水草而居。(B)蔓草是拿來墊的材料，不是剷除。(C)蔓草是岸邊現成的，不是先在筏上種蔓草。", "skill": "說明「怎麼做」的文言句，把動詞一個個圈出來排成步驟，再比對選項的順序與材料。"}], "difficulty": "易", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-14", "exam": "et104", "nums": [14], "form": "單題", "img": "img/et104-14.png", "source": "鄭板橋〈濰縣署中與舍弟墨第二書‧書後又一紙〉", "author": "鄭燮（板橋）", "genre": "書信序跋", "types": ["文意推論", "寫作手法"], "passage": "所云不得籠中養鳥，而予又未嘗不愛鳥，但養之有道耳，欲養鳥莫如多種樹，使遶屋數百株，扶疏茂密為鳥國鳥家。", "translation": "我說不可以把鳥關在籠子裡養，但我又不是不愛鳥，只是養鳥要有方法罷了。想要養鳥，不如多種樹，讓房子四周圍繞幾百棵樹，枝葉茂密，成為鳥兒的國度與家園。", "keywords": [{"w": "所云", "m": "所說的"}, {"w": "未嘗不", "m": "並不是不"}, {"w": "有道", "m": "有方法"}, {"w": "莫如", "m": "不如"}, {"w": "遶", "m": "同「繞」，環繞"}, {"w": "扶疏", "m": "枝葉繁茂的樣子"}], "questions": [{"n": 14, "qtype": "單選", "stem": "下列是一段中間拆散的古文，請依文意選出排列順序最恰當的選項：所云不得籠中養鳥，而予又未嘗不愛鳥，甲、欲養鳥莫如多種樹，乙、使遶屋數百株，丙、但養之有道耳，扶疏茂密為鳥國鳥家。(鄭板橋〈濰縣署中與舍弟墨第二書‧書後又一紙〉)", "options": {"A": "甲乙丙", "B": "甲丙乙", "C": "丙甲乙", "D": "丙乙甲"}, "answer": "C", "explain": "「並不是不愛鳥」後面要接轉折「但養之有道耳」（丙），先說原則；接著提出方法「欲養鳥莫如多種樹」（甲）；再說樹要多到「使遶屋數百株」（乙），最後接「扶疏茂密」形容樹林。順序丙甲乙，(C)正確。(A)(B)把「但」放到後面，轉折接不上「未嘗不愛鳥」。(D)乙「使遶屋數百株」前沒提到樹，「株」沒有著落。", "skill": "排序題先找連接詞（但、莫如、使）和代稱的對象（株＝樹），能接頭尾的先固定。"}], "difficulty": "易", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-15", "exam": "et104", "nums": [15], "form": "單題", "img": "img/et104-15.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式", "句意理解"], "passage": "誰習計會，能為文收責於薛者乎／吾師道也，夫庸知其年之先後生於吾乎／遷客騷人，多會於此，覽物之情，得無異乎／乃知真人之興也，非英雄所冀，況非英雄者乎", "translation": "(A)誰熟悉會計，能替我到薛地收債呢？(B)我學的是道，哪管他年紀比我大還是小呢？(C)被貶的官員、多愁的詩人常聚在這裡，看到景物的心情，恐怕會不一樣吧？(D)這才知道真命天子的出現，不是英雄能妄想的，更何況不是英雄的人呢？", "keywords": [{"w": "計會", "m": "會計、算帳"}, {"w": "責", "m": "同「債」"}, {"w": "庸", "m": "哪裡、何必"}, {"w": "得無……乎", "m": "恐怕……吧，表推測"}, {"w": "冀", "m": "希望、企圖"}], "questions": [{"n": 15, "qtype": "單選", "stem": "下列含有「乎」的句子，何者屬於「徵詢答案」的問句？", "options": {"A": "誰習計會，能為文收責於薛者乎", "B": "吾師道也，夫庸知其年之先後生於吾乎", "C": "遷客騷人，多會於此，覽物之情，得無異乎", "D": "乃知真人之興也，非英雄所冀，況非英雄者乎"}, "answer": "A", "explain": "「徵詢答案」是真的不知道、想要對方回答。(A)正確，出自〈馮諼客孟嘗君〉，孟嘗君貼出公告問門客誰會算帳、能替他去薛地收債，後來馮諼就應徵了。(B)出自韓愈〈師說〉，意思是「哪管他年紀大小」，是反問，答案已在話中。(C)出自〈岳陽樓記〉，「得無……乎」是推測語氣，「恐怕不同吧」。(D)出自〈虬髯客傳〉，「況……乎」是「更何況」的反問加強語氣。", "skill": "看到「庸……乎」「況……乎」先判反問，「得無……乎」判推測，只有真正等人回答的才是詢問。"}], "difficulty": "中", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-16", "exam": "et104", "nums": [16], "form": "單題", "img": "img/et104-16.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "將軍向寵，性行淑均，曉暢軍事。", "translation": "將軍向寵，性情善良、品行公正，通曉軍事。", "keywords": [{"w": "錯綜", "m": "把原本整齊的詞語交錯排列，如「性淑行均」寫成「性行淑均」"}, {"w": "淑", "m": "善良"}, {"w": "均", "m": "公正"}], "questions": [{"n": 16, "qtype": "單選", "stem": "諸葛亮〈出師表〉：「將軍向寵，性行淑均，曉暢軍事」，句中「性行淑均」以錯綜方式構詞，意同於「性淑行均」。下列文句「」內，何者也運用相同的構詞方式？", "options": {"A": "小人寡欲，則能謹身節用，「遠罪豐家」", "B": "以考其信，著有過，「刑仁講讓」，示民有常", "C": "郭攸之、費褘、董允等，此皆良實，「志慮忠純」", "D": "此地有崇山峻嶺，茂林脩竹，又有「清流激湍」，映帶左右"}, "answer": "C", "explain": "「性行淑均」＝性淑＋行均，前兩字是主角、後兩字分別描述它們。(C)正確，也出自〈出師表〉，「志慮忠純」＝志忠＋慮純，心志忠誠、思慮純正。(A)出自〈訓儉示康〉，「遠罪豐家」是遠離罪過、使家豐足，兩組動詞加受詞，本來就整齊，不是交錯。(B)出自《禮記‧禮運》，「刑仁講讓」是以仁為法、講求謙讓，也是兩組動賓。(D)出自〈蘭亭集序〉，「清流激湍」是清澈的流水和湍急的水流，兩個名詞並列。", "skill": "試著把四字詞拆成「1、3字一組，2、4字一組」，拆完通順就是錯綜；拆了變怪就不是。"}], "difficulty": "中", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-18", "exam": "et104", "nums": [18], "form": "單題", "img": "img/et104-18.png", "source": "應用文（書信信封）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "中式信封收件人欄的寫法：姓＋職稱＋名（名字縮小偏右側書）＋啟封詞，例如「林經理之凡　鈞啟」。", "keywords": [{"w": "側書", "m": "把收件人的名字寫小、偏向一側，表示不敢直呼其名的敬意"}, {"w": "鈞啟", "m": "啟封詞，請長官、尊長拆信"}], "questions": [{"n": 18, "qtype": "單選", "stem": "信封的收件人欄使用「側書」，係為表示敬意。下列側書寫法，何者最恰當？", "options": {"A": "林經理之凡　鈞啟（「之凡」縮小側書）", "B": "林經理之凡　鈞啟（「之凡」未側書，「鈞啟」縮小）", "C": "林之凡經理　鈞啟（「經理」縮小側書）", "D": "林之凡經理　鈞啟（「之凡」縮小側書，「鈞啟」縮小）"}, "answer": "A", "explain": "信封收件人的標準格式是「姓＋職稱＋名＋啟封詞」，其中「名」要寫小、偏一側，表示不敢直接叫對方名字；啟封詞照正常大小寫。(A)正確。(B)名字沒有側書，啟封詞反而縮小，錯。(C)職稱放在全名後，而且側書的是職稱不是名字，錯。(D)職稱放錯位置，啟封詞也不該縮小。", "skill": "記一句口訣：「姓、稱謂、小名字、啟封詞」，側書只給名字。"}], "difficulty": "中", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-19", "exam": "et104", "nums": [19], "form": "單題", "img": "img/et104-19.png", "source": "《孟子》", "author": "孟子", "genre": "經典語錄", "types": ["典故出處", "文化常識"], "passage": "甲、仁者無敵　乙、性無善無不善　丙、人皆有不忍人之心　丁、君子以王天下為樂", "translation": "甲、行仁政的人天下無敵。乙、人性本來沒有善也沒有不善。丙、人人都有不忍心看別人受苦的心。丁、君子把稱王天下當作快樂。", "keywords": [{"w": "不忍人之心", "m": "不忍見別人受苦的同情心"}, {"w": "王天下", "m": "統治天下，「王」作動詞"}], "questions": [{"n": 19, "qtype": "單選", "stem": "下列何者符合孟子的觀點？甲、仁者無敵　乙、性無善無不善　丙、人皆有不忍人之心　丁、君子以王天下為樂", "options": {"A": "甲丙", "B": "乙丁", "C": "甲丙丁", "D": "甲乙丙丁"}, "answer": "A", "explain": "甲「仁者無敵」是孟子勸梁惠王行仁政的話，符合。乙「性無善無不善」是告子的主張，孟子主張性善，正和他辯論，不符合。丙「人皆有不忍人之心」出自〈公孫丑上〉，是性善說的根據，符合。丁孟子說「君子有三樂，而王天下不與存焉」，稱王天下不在君子之樂中，正好相反。所以是甲丙，(A)正確；(B)(C)(D)都含有乙或丁。", "skill": "孟子＝性善、仁政、民本；看到「無善無不善」想到告子，「王天下不與存焉」記成三樂之外。"}], "difficulty": "中", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-20", "exam": "et104", "nums": [20], "form": "單題", "img": "img/et104-20.png", "source": "綜合（典籍常識）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "甲、《左傳》　乙、《漢書》　丙、《隋唐演義》　丁、《資治通鑑》　戊、《臺灣通史》", "translation": "甲、《左傳》：相傳左丘明為解說《春秋》而寫的書。乙、《漢書》：東漢班固寫的西漢一代歷史。丙、《隋唐演義》：清代褚人穫寫的章回小說。丁、《資治通鑑》：北宋司馬光主編的編年體通史。戊、《臺灣通史》：連橫寫的臺灣歷史。", "keywords": [{"w": "經史子集", "m": "古代圖書四大類：經＝儒家經典，史＝歷史，子＝諸子百家，集＝詩文集"}], "questions": [{"n": 20, "qtype": "單選", "stem": "下列書籍，何者屬於經、史、子、集中的「史部」？甲、《左傳》　乙、《漢書》　丙、《隋唐演義》　丁、《資治通鑑》　戊、《臺灣通史》", "options": {"A": "甲乙戊", "B": "乙丁戊", "C": "甲乙丙戊", "D": "乙丙丁戊"}, "answer": "B", "explain": "甲《左傳》雖然記歷史，但它是解釋《春秋》的傳，列入十三經，屬經部。乙《漢書》是正史，屬史部。丙《隋唐演義》是章回小說，不是史書。丁《資治通鑑》是編年體史書，屬史部。戊《臺灣通史》是連橫寫的紀傳體史書，屬史部。所以是乙丁戊，(B)正確。", "skill": "「春秋三傳」（左傳、公羊、穀梁）一律歸經部；名字有「演義」的是小說，不是史書。"}], "difficulty": "中", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-21", "exam": "et104", "nums": [21], "form": "單題", "img": "img/et104-21.png", "source": "綜合（多首絕句）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "(A)林中觀易罷，溪上對鷗閒。楚俗饒詞客，何人最往還　(B)此地別燕丹，壯士髮衝冠。昔時人已沒，今日水猶寒　(C)小苑鶯歌歇，長門蝶舞多。眼看春又去，翠輦不曾過　(D)落日五湖遊，煙波處處愁。浮沉千古事，誰語問東流", "translation": "(A)在林中讀完《易經》，在溪邊悠閒地看著鷗鳥。楚地多文人，誰和你來往最密切？(B)就在這裡，荊軻告別燕太子丹，壯士怒髮衝冠。當年的人已經不在，今天易水仍然寒冷。(C)小園裡黃鶯不唱了，長門宮中蝴蝶飛舞很多。眼看春天又要過去，皇帝的車駕始終沒有來。(D)夕陽下遊五湖，煙波處處都是愁。千古以來的興衰往事，該向誰去問那東流的江水？", "keywords": [{"w": "對仗", "m": "上下兩句字數相同、詞性相對、意思相關"}, {"w": "翠輦", "m": "皇帝的車駕"}], "questions": [{"n": 21, "qtype": "單選", "stem": "近體詩不只律詩講究對仗，絕句也會使用對仗。下列絕句，何者詩中沒有使用對仗？", "options": {"A": "林中觀易罷，溪上對鷗閒。楚俗饒詞客，何人最往還", "B": "此地別燕丹，壯士髮衝冠。昔時人已沒，今日水猶寒", "C": "小苑鶯歌歇，長門蝶舞多。眼看春又去，翠輦不曾過", "D": "落日五湖遊，煙波處處愁。浮沉千古事，誰語問東流"}, "answer": "D", "explain": "逐聯檢查。(A)「林中／溪上」「觀易／對鷗」「罷／閒」，前兩句對仗。(B)出自駱賓王〈於易水送人〉，「昔時／今日」「人已沒／水猶寒」，後兩句對仗。(C)「小苑／長門」「鶯歌歇／蝶舞多」，前兩句對仗。(D)正確，「落日五湖遊」對「煙波處處愁」，「五湖」是地名、「處處」是副詞，詞性不相對；「浮沉千古事」對「誰語問東流」也對不起來，全詩沒有對仗。", "skill": "判斷對仗先看同位置的詞性：名對名、數字對數字、方位對方位，有一處對不上就不是。"}], "difficulty": "中", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-22", "exam": "et104", "nums": [22], "form": "單題", "img": "img/et104-22.png", "source": "韓信墓聯", "author": "", "genre": "其他", "types": ["典故出處", "文化常識"], "passage": "生死一知己，存亡兩婦人。", "translation": "他一生的成敗生死，都繫於一位知己；他的存活與滅亡，都繫於兩位婦人。", "keywords": [{"w": "知己", "m": "指蕭何：月下追韓信、推薦他當大將，後來又設計把他騙進宮中被殺"}, {"w": "兩婦人", "m": "漂母（救他一命）與呂后（殺了他）"}], "questions": [{"n": 22, "qtype": "單選", "stem": "韓信墓前有對聯云：「生死一知己，存亡兩婦人」，下列關於「知己」、「婦人」的解釋，何者正確？", "options": {"A": "知己：蕭何；婦人：漂母、呂后", "B": "知己：蕭何；婦人：虞姬、呂后", "C": "知己：劉邦；婦人：漂母、呂后", "D": "知己：劉邦；婦人：虞姬、呂后"}, "answer": "A", "explain": "韓信能當上大將是因為蕭何月下追回並大力推薦；後來韓信被殺，也是蕭何替呂后設計騙他入宮——這就是「成也蕭何，敗也蕭何」，所以「生死一知己」是蕭何。年輕落魄時漂母給他飯吃，讓他活下來；最後呂后在長樂宮殺了他，所以「存亡兩婦人」是漂母和呂后。(A)正確。(B)(D)虞姬是項羽的寵姬，與韓信無關。(C)(D)劉邦雖然拜他為將，卻一直猜忌他，不算知己。", "skill": "人物對聯題，先想這個人一生「誰捧他、誰害他」，常是同一人或成對的人。"}], "difficulty": "易", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-32", "exam": "et104", "nums": [32, 33, 34], "form": "題組", "img": "img/et104-32.png", "source": "《閱微草堂筆記》卷8", "author": "紀昀", "genre": "筆記小品", "types": ["文意推論", "句意理解", "主旨寓意"], "passage": "景城有姜三莽者，勇而戇。一日，聞人說宋定伯賣鬼得錢事，大喜曰：「吾今乃知鬼可縛。如每夜縛一鬼，唾使變羊，曉而牽賣於屠市，足供一日酒肉資矣。」於是夜夜荷梃執繩，潛行墟墓間，如獵者之伺狐兔，竟不能遇。即素稱有鬼之處，佯醉寢以誘致之，亦寂然無睹。一夕，隔林見數磷火，踴躍奔赴，未至間，已星散去，懊恨而返。如是月餘，無所得，乃止。蓋鬼之侮人，恆乘人之畏。三莽確信鬼可縛，意中已視鬼蔑如矣，其氣焰足以懾鬼，故鬼反避之也。", "translation": "景城有個叫姜三莽的人，勇敢又憨直。有一天，他聽人講宋定伯把鬼賣掉換錢的故事，非常高興地說：「我現在才知道鬼可以綁。如果每晚綁一隻鬼，吐口水讓牠變成羊，天亮牽到屠宰市場賣掉，就夠付一天的酒肉錢了。」於是每天晚上扛著棍子、拿著繩子，偷偷在荒墳間走動，像獵人等狐狸兔子一樣，竟然一隻也沒遇到。就算到了大家都說鬧鬼的地方，假裝喝醉睡下來引鬼出來，也安安靜靜什麼都沒看見。有一晚，隔著樹林看到幾點磷火，他興奮地跑過去，還沒到，磷火已經像星星般散去，他只好懊惱地回家。這樣過了一個多月，什麼也沒抓到，才停止。原來鬼欺負人，總是趁人害怕的時候。三莽堅信鬼可以綁，心裡早就看不起鬼了，他的氣勢足以嚇住鬼，所以鬼反而躲著他。", "keywords": [{"w": "戇", "m": "憨直、傻氣"}, {"w": "縛", "m": "綁"}, {"w": "荷梃", "m": "扛著棍棒"}, {"w": "伺", "m": "守候、等待"}, {"w": "蔑如", "m": "輕視、不放在眼裡"}, {"w": "懾", "m": "使害怕"}, {"w": "乘", "m": "趁著"}], "questions": [{"n": 32, "qtype": "單選", "stem": "依據上文，下列關於姜三莽的敘述，何者正確？", "options": {"A": "向宋定伯學捉鬼術", "B": "通曉擒鬼變羊之法", "C": "欲縛鬼卻苦無機會", "D": "因法術失靈而懊悔"}, "answer": "C", "explain": "他每晚出門找鬼，「竟不能遇」，裝醉引誘也「寂然無睹」，一個多月都沒抓到。(C)正確。(A)他只是「聞人說」宋定伯的故事，沒有拜師。(B)「唾使變羊」只是他照故事想像的計畫，從沒成功過，談不上通曉。(D)他懊恨是因為磷火跑掉了，根本沒施過什麼法術。", "skill": "「聽說」和「學會」、「打算」和「做到」要分清，選項常把想像偷換成事實。"}, {"n": 33, "qtype": "單選", "stem": "依據上文，姜三莽捉鬼的動機為何？", "options": {"A": "賣鬼換錢", "B": "表現勇氣", "C": "為民除害", "D": "破除迷信"}, "answer": "A", "explain": "他自己說：把鬼變成羊「牽賣於屠市，足供一日酒肉資矣」，目的就是賺酒肉錢。(A)正確。(B)他雖然勇敢，但捉鬼不是為了表現。(C)文中沒有提到要替人除害。(D)他「確信鬼可縛」，相信有鬼，談不上破除迷信。", "skill": "問動機，直接找人物自己說的「如……，足……」這類計畫句。"}, {"n": 34, "qtype": "單選", "stem": "上文中「鬼之侮人，恆乘人之畏」的意思為何？", "options": {"A": "閻王好見，小鬼難當", "B": "心裡怕鬼，鬼就找上你", "C": "人鬼殊途，用不著害怕", "D": "夜路走多了，難免碰到鬼"}, "answer": "B", "explain": "「侮」是欺負，「乘」是趁著，整句是說鬼欺負人總是趁人害怕的時候——反過來看，姜三莽不怕鬼，鬼就躲他。(B)正確。(A)指大官好說話、小人物反而刁難，意思不同。(C)說人鬼不同路，沒有提到「怕」才招鬼。(D)比喻壞事做多了總會出事，與害怕無關。", "skill": "先把關鍵字逐字翻（侮＝欺負、乘＝趁、畏＝害怕），再找意思一樣的白話俗語。"}], "difficulty": "易", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-35", "exam": "et104", "nums": [35, 36, 37], "form": "題組", "img": "img/et104-35.png", "source": "《太平廣記》卷243", "author": "李昉等編", "genre": "筆記小品", "types": ["文意推論", "虛詞句式", "人物情感"], "passage": "唐裴明禮，河東人。善於理生，收人間所棄物，積而鬻之，以此家產巨萬。又於金光門外，市不毛地。多瓦礫，非善價者。乃於地際豎標，懸以筐，中者輒酬以錢，十百僅一二中。未洽浹，地中瓦礫盡矣。乃舍諸牧羊者，糞既積，預聚雜果核，具犁牛以耕之。歲餘滋茂，連車而鬻，所收復致巨萬。乃繕甲第，周院置蜂房以營蜜，廣栽蜀葵雜花果，蜂采花逸而蜜豐矣。營生之妙，觸類多奇，不可勝數。貞觀中，自古台主簿拜殿中侍御史，轉兵吏員外中書舍人，累遷太常卿。", "translation": "唐朝的裴明禮是河東人。他很會經營生計，收集別人丟棄的東西，累積起來再賣，因此家產上萬。他又在金光門外買下一塊寸草不生的地，地上滿是瓦礫，賣不到好價錢。他就在地邊立一根竿子，掛上竹筐，有人拿瓦礫丟進筐裡就給錢，一百個人裡只有一兩個丟得中。還沒輪完一遍，地上的瓦礫就被撿光了。接著他把地借給牧羊人放羊，等羊糞累積夠了，預先收集各種果核，備好牛和犁來耕種。一年多後果樹長得茂盛，一車一車地賣，又賺了上萬。於是他修建大宅，在院子四周放蜂箱養蜂採蜜，大量種植蜀葵和各種花果，蜜蜂採花又近又輕鬆，蜂蜜就豐收了。他經營的巧妙，凡事都能想出新奇的辦法，數也數不完。貞觀年間，他從古台主簿升任殿中侍御史，又轉任兵部、吏部員外郎、中書舍人，一路升到太常卿。", "keywords": [{"w": "理生", "m": "經營生計"}, {"w": "鬻", "m": "賣"}, {"w": "市", "m": "買"}, {"w": "不毛地", "m": "長不出草木的地"}, {"w": "標", "m": "竿子"}, {"w": "中", "m": "投中"}, {"w": "輒", "m": "就"}, {"w": "酬", "m": "給予報酬"}, {"w": "洽浹", "m": "周遍"}, {"w": "舍", "m": "給、讓……使用"}, {"w": "繕甲第", "m": "修建豪宅"}], "questions": [{"n": 35, "qtype": "單選", "stem": "依據上文，下列關於裴明禮的敘述，何者正確？", "options": {"A": "基於濟助貧困而經營多項生意", "B": "善於開發常人未見的商業價值", "C": "藉多種理財管道謀取升官機會", "D": "經常利用官職之便經營其副業"}, "answer": "B", "explain": "別人丟的東西他收來賣，別人看不上的瓦礫地他變成果園，處處把沒人要的東西變成財富。(B)正確。(A)文中說他「善於理生」、家產巨萬，是為了經營致富，沒有濟貧的說法。(C)升官的事放在最後另外交代，沒說他用錢求官。(D)他致富的例子都沒有用到官職。", "skill": "人物題先為主角下一個關鍵詞（這裡是「化廢為寶」），再看哪個選項同義。"}, {"n": 36, "qtype": "單選", "stem": "依據上文，下列何者是裴明禮的經營之術？", "options": {"A": "低價購入土地高價售出", "B": "辦挖寶競賽誘眾人翻土", "C": "無償取得肥料以利耕種", "D": "夷平宅第改建蜂房養蜂"}, "answer": "C", "explain": "「舍諸牧羊者，糞既積」——把地讓牧羊人放羊，不用花錢就得到羊糞當肥料，再來種果樹。(C)正確。(A)他買地後是自己種果樹賣果子，沒有把地轉賣。(B)他是掛筐讓人丟瓦礫、丟中給錢，是投擲遊戲，用來清除瓦礫，不是挖寶。(D)「繕甲第」是修建大宅，蜂房是放在院子四周，不是拆房子。", "skill": "經營步驟題，把原文每一招和選項一一對照，注意動詞是否被改寫成相反意思（繕≠夷平）。"}, {"n": 37, "qtype": "單選", "stem": "依據上文，下列文句中的「以」，何者可解釋為「因為」？", "options": {"A": "「以」此家產巨萬", "B": "中者輒酬「以」錢", "C": "具犁牛「以」耕之", "D": "周院置蜂房「以」營蜜"}, "answer": "A", "explain": "(A)正確，「以此家產巨萬」＝因為這樣而家產上萬，「以」是因為。(B)「酬以錢」＝用錢酬謝，「以」是用、拿。(C)「具犁牛以耕之」＝準備牛犁來耕種，「以」是連詞「來、用來」。(D)「置蜂房以營蜜」＝放蜂箱來經營蜂蜜，「以」也是「來、用來」。", "skill": "「以」後面接名詞多是「用」，在兩個動作中間多是「來」，句子在說結果的原因時才是「因為」。"}], "difficulty": "中", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et104-38", "exam": "et104", "nums": [38, 39, 40], "form": "題組", "img": "img/et104-38.png", "source": "《後漢書‧方術列傳》", "author": "范曄", "genre": "史傳人物", "types": ["字詞解釋", "文意推論", "人物情感"], "passage": "郭玉者，廣漢雒人也。……和帝時，為太醫丞，多有效應。帝奇之，仍試令嬖臣美手腕者與女子雜處帷中，使玉各診一手，問所疾苦。玉曰：「左陽右陰，脈有男女，狀若異人，臣疑其故。」帝歎息稱善。玉仁愛不矜，雖貧賤廝養，必盡其心力，而醫療貴人，時或不愈。帝乃令貴人羸服變處，一針即差。召玉詰問其狀，對曰：「醫之為言意也。腠理至微，隨氣用巧，針石之間，毫芒即乖，神存於心手之際，可得解而不可得言也。夫貴者處尊高以臨臣，臣懷怖懾以承之。其為療也，有四難焉：自用意而不任臣，一難也；將身不謹，二難也；骨節不彊，不能使藥，三難也；好逸惡勞，四難也。針有分寸，時有破漏，重以恐懼之心，加以裁慎之志，臣意且猶不盡，何有於病哉！此其所為不愈也。」帝善其對。", "translation": "郭玉是廣漢郡雒縣人。漢和帝時擔任太醫丞，治病常有效。和帝覺得他很神奇，就試他：讓一位手腕秀美的寵臣和一名女子一起躲在帷幕裡，讓郭玉各診一隻手，問是什麼病。郭玉說：「左手是陽脈、右手是陰脈，脈象有男有女，好像是兩個不同的人，我懷疑其中有緣故。」和帝讚嘆稱好。郭玉仁慈而不驕傲，即使是窮苦的僕役，也一定盡心盡力；可是替貴人治病，有時卻治不好。和帝就叫貴人穿上破舊衣服、換個住處，郭玉一針就治好了。和帝召他來問原因，他回答：「醫字的意思就是『意』，要用心意。人體肌理非常細微，要順著氣血運用技巧，下針之間差一點點就會出錯，精神集中在心與手之間，能夠理解卻說不出來。貴人居高臨下對待我，我懷著恐懼去伺候。替他們治療有四個難處：自己作主而不信任醫生，是第一難；不謹慎保養身體，是第二難；筋骨不強健，承受不了藥力，是第三難；貪圖安逸、討厭勞動，是第四難。下針有一定的分寸，還要避開不宜的時機，再加上恐懼的心情和過度謹慎的念頭，我連自己的心意都發揮不完全，哪還能治好病呢！這就是治不好的原因。」和帝認為他回答得好。", "keywords": [{"w": "嬖臣", "m": "受寵的近臣"}, {"w": "帷", "m": "帷幕"}, {"w": "不矜", "m": "不驕傲"}, {"w": "廝養", "m": "做粗活的僕役"}, {"w": "羸服", "m": "穿破舊的衣服"}, {"w": "差", "m": "同「瘥」，痊癒"}, {"w": "詰問", "m": "追問"}, {"w": "腠理", "m": "人體肌理"}, {"w": "毫芒即乖", "m": "差一點點就出錯"}, {"w": "自用意", "m": "自作主張"}, {"w": "破漏", "m": "針刺宜忌的時機"}], "questions": [{"n": 38, "qtype": "單選", "stem": "依據上文，下列文句「」內的解釋，何者正確？", "options": {"A": "「狀若異人」，臣疑其故：表情異於常人", "B": "帝乃令貴人「羸服變處」：改穿破舊的衣服", "C": "玉「仁愛不矜」：當仁不讓而不拘小節", "D": "針石之間，「毫芒即乖」：稍加針治便神清氣順"}, "answer": "B", "explain": "(B)正確，「羸服」是穿破舊衣服，「變處」是換住處，讓貴人假扮成平民，結果郭玉一針就治好。(A)「狀若異人」是說兩隻手的脈象像來自兩個不同的人，跟表情無關。(C)「仁愛不矜」是仁慈而不驕傲自大，不是當仁不讓。(D)「毫芒即乖」是差一點點就出錯，和「神清氣順」意思相反。", "skill": "字詞題要放回上下文：郭玉在講診脈和下針的困難，解釋就不會是「表情」或「效果很好」。"}, {"n": 39, "qtype": "單選", "stem": "依據上文，郭玉所稱的「四難」大致可歸納為：", "options": {"A": "要御醫診治，要內廷供藥", "B": "要湯藥可口，要一帖見效", "C": "不勤於運動，不害怕病痛", "D": "不聽從醫囑，不保養身體"}, "answer": "D", "explain": "四難是：自作主張不信任醫生、不謹慎保養身體、筋骨弱受不了藥、貪圖安逸不勞動。歸納起來就是「不聽醫生的話」加上「不好好照顧身體」，(D)正確。(A)(B)文中沒有提到要御醫或要藥好喝。(C)「不勤於運動」勉強對應好逸惡勞，但「不害怕病痛」原文沒有。", "skill": "歸納題先把每一點縮成四個字，再看哪個選項能一次涵蓋，有一半對不上就刪。"}, {"n": 40, "qtype": "單選", "stem": "依據上文，郭玉認為「醫療貴人，時或不愈」的主要原因為何？", "options": {"A": "醫者與貴人間主客觀條件難以配合", "B": "醫者害怕說出真實病因而遭到懲罰", "C": "帝王關切貴人病況而干預診治方式", "D": "貴人諱疾忌醫而錯過最佳治療時期"}, "answer": "A", "explain": "郭玉從兩方面說：醫生這邊，面對居高臨下的貴人會「懷怖懾」，心意發揮不出來；貴人那邊有「四難」，不配合又不保養。兩邊條件都不對，所以治不好，(A)正確。(B)他怕的是貴人的身分，不是怕說出病因被罰。(C)和帝只是事後問原因，沒有干預治療。(D)貴人有請醫生治，沒有逃避看病。", "skill": "問「主要原因」時，看作者的解釋是不是分成幾方面，能同時包住各方面的選項才是答案。"}], "difficulty": "中", "label": "104二技", "year": 104, "kind": "二技"}, {"id": "et105-01", "exam": "et105", "nums": [1], "form": "單題", "img": "img/et105-01.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "伯兮朅兮，邦之桀兮／問其價，曰：止四百／依乎天理，批大郤，導大窾／幼稚盈室，缾無儲粟", "translation": "(A)我的丈夫多英武啊，是國家的傑出人才。(B)問它的價錢，說：「只要四百。」(C)順著牛身體天然的紋理，劈開筋骨間的大空隙，引刀進入骨節間的大孔。(D)小孩子擠滿屋子，瓶子裡沒有存糧。", "keywords": [{"w": "通假", "m": "古書中用音近或音同的字代替本字"}, {"w": "桀", "m": "通「傑」，傑出"}, {"w": "止", "m": "通「只」，只要"}, {"w": "郤", "m": "通「隙」，空隙"}, {"w": "缾", "m": "同「瓶」，裝糧的瓦器"}], "questions": [{"n": 1, "qtype": "單選", "stem": "下列「」內音義相近且可通用的字，何者錯誤？", "options": {"A": "伯兮朅兮，邦之「桀」兮：通「傑」", "B": "問其價，曰：「止」四百：通「只」", "C": "依乎天理，批大「郤」，導大窾：通「隙」", "D": "幼稚盈室，「缾」無儲粟：通「平」"}, "answer": "D", "explain": "(D)錯誤，所以是答案。出自陶淵明〈歸去來辭‧序〉，「缾」是「瓶」的異體字，指裝糧食的瓦罐，「缾無儲粟」是罐子裡沒有存糧，和「平」無關。(A)出自《詩經‧衛風‧伯兮》，「桀」通「傑」，傑出的人，正確。(B)「止四百」就是「只要四百」，「止」通「只」，正確。(C)出自《莊子‧庖丁解牛》，「郤」通「隙」，筋骨間的空隙，正確。", "skill": "通假題把本字代回原句讀讀看，讀得通才對；「平無儲粟」講不通，馬上就能排除。"}], "difficulty": "中", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-03", "exam": "et105", "nums": [3], "form": "單題", "img": "img/et105-03.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "句意理解"], "passage": "故知勝有五：識眾寡之同者勝，上下同欲者勝／貪慕富貴，枉道速禍／絃而鼓之，金聲而玉應／漢懲秦王孤立，於是大建庶孽而多諸侯", "translation": "(A)所以預知勝利的情況有五種：懂得兵多兵少不同用法的會勝，上下同心同德的會勝。(B)貪圖富貴，違背正道而招來災禍。(C)裝上琴弦彈奏，聲音像金玉一樣清脆響亮。(D)漢朝以秦朝孤立無援而亡為戒，於是大量分封宗室子弟，多立諸侯。", "keywords": [{"w": "同欲", "m": "有相同的意願、目標"}, {"w": "枉道", "m": "違背正道"}, {"w": "速禍", "m": "招來災禍"}, {"w": "金聲而玉應", "m": "琴聲像金石般清越"}, {"w": "懲", "m": "以……為戒"}, {"w": "庶孽", "m": "庶出子孫，泛指宗室子弟"}], "questions": [{"n": 3, "qtype": "單選", "stem": "下列「」中的詞語，何者解釋正確？", "options": {"A": "故知勝有五：識眾寡之同者勝，「上下同欲」者勝：全軍上下同心同德", "B": "貪慕富貴，「枉道速禍」：白費心力加速災難到來", "C": "絃而鼓之，「金聲而玉應」：鑼聲伴隨響板演奏", "D": "漢懲秦王孤立，於是「大建庶孽」而多諸侯：廣封百姓，拉攏人心"}, "answer": "A", "explain": "(A)正確，出自《孫子兵法‧謀攻》，上下有共同的目標，就是同心同德。(B)出自司馬光〈訓儉示康〉，「枉道」是違背正道，不是白費心力。(C)出自劉基〈工之僑獻琴〉，「金聲而玉應」是形容琴聲像金玉般清亮悅耳，不是真的有鑼和響板。(D)「庶孽」是宗室的庶出子孫，「大建庶孽」是大量封宗室子弟為王，不是封百姓。", "skill": "文言的「金、玉」常是比喻聲音或品質美好，別直接當成樂器或物品；「庶孽」「宗子」這類詞跟皇族有關。"}], "difficulty": "中", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-04", "exam": "et105", "nums": [4], "form": "單題", "img": "img/et105-04.png", "source": "《荀子‧大略》", "author": "荀子", "genre": "說理議論", "types": ["主旨寓意", "句意理解"], "passage": "有法者以法行，無法者以類舉。以其本知其末，以其左知其右，凡百事異理而相守也。", "translation": "有法規可依的，就依照法規去做；沒有法規的，就用類推的方法處理。從根本推知末節，從左邊推知右邊，各種事情道理雖然不同，卻彼此相通、互相關聯。", "keywords": [{"w": "以類舉", "m": "依類推方式處理"}, {"w": "本、末", "m": "根本與枝節"}, {"w": "相守", "m": "互相依存、關聯"}], "questions": [{"n": 4, "qtype": "單選", "stem": "荀子〈大略〉：「有法者以法行，無法者以類舉。以其本知其末，以其左知其右，凡百事異理而相守也。」上文的要旨為：", "options": {"A": "知本執要，舉一反三", "B": "法之有無，存乎一心", "C": "瞻顧左右，務求周全", "D": "左右逢源，因勢利導"}, "answer": "A", "explain": "重點在「以類舉」「以其本知其末」：掌握根本，就能類推到其他事。(A)正確，「知本執要」對應以本知末，「舉一反三」對應以類舉。(B)荀子沒說法規有沒有全看人心。(C)「以其左知其右」是由此推彼，不是要左顧右盼面面俱到。(D)「左右逢源」是處事順利，與類推無關。", "skill": "找文中重複出現的句型（以……知……），它就是要旨；別被「左右」等字面誘答。"}], "difficulty": "易", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-05", "exam": "et105", "nums": [5], "form": "單題", "img": "img/et105-05.png", "source": "曹學佺〈錢伯庸文序〉", "author": "曹學佺", "genre": "書信序跋", "types": ["文意推論", "寫作手法"], "passage": "今之作文者，如人相見，作揖曲躬之際，闊別致謝，寒溫都盡。及其執茶對坐，別無可說，不過再理前詞，往往重複。又如俗人唱曲，以一句為數句，以一字為數字，不死不活，希圖延場；及其當唱之處，則又草草讀過而已。", "translation": "現在寫文章的人，就像人見面一樣：作揖彎腰的時候，久別的話、道謝的話、問候冷暖的話都講完了；等到端著茶對坐，再也沒話可說，只好把前面的話再講一遍，往往重複。又像俗人唱曲，把一句拉成好幾句，一個字拖成好幾個字，半死不活，只想拖時間；等到真正該唱的地方，卻又草草帶過而已。", "keywords": [{"w": "作揖曲躬", "m": "拱手彎腰行禮"}, {"w": "寒溫", "m": "問候冷暖的客套話"}, {"w": "再理前詞", "m": "重提前面說過的話"}, {"w": "希圖延場", "m": "企圖拖延時間"}], "questions": [{"n": 5, "qtype": "單選", "stem": "閱讀下文，作者認為今日作文的毛病，主要在於：", "options": {"A": "結構有頭無尾", "B": "習慣長話短說", "C": "修辭不夠精美", "D": "內容貧乏冗贅"}, "answer": "D", "explain": "兩個比喻都在說同一件事：客套話講完就沒話說、只好重複；唱曲拉長拖時間，重點處卻草草帶過——文章沒有真內容，只好重複和拖長。(D)正確。(A)不是沒有結尾，而是中間空洞。(B)恰好相反，是短話長說。(C)作者批評的是內容空，不是文字不漂亮。", "skill": "作者連用兩個比喻時，找兩者的共同點，就是他要批評的重點。"}], "difficulty": "易", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-06", "exam": "et105", "nums": [6], "form": "單題", "img": "img/et105-06.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "臨池學書，池水盡黑，此為其故跡，豈信然邪？", "translation": "在池邊練字，池水都染黑了，這裡就是他的舊跡，難道真的是這樣嗎？", "keywords": [{"w": "信", "m": "確實、真的"}, {"w": "疑信相參", "m": "可疑的和可信的混雜"}], "questions": [{"n": 6, "qtype": "單選", "stem": "曾鞏〈墨池記〉：「臨池學書，池水盡黑，此為其故跡，豈信然邪？」句中的「信」的意義，與下列何者最接近？", "options": {"A": "選賢與能，講「信」修睦", "B": "郭公夏五，疑「信」相參，則徵文難", "C": "仁者播其惠，「信」者效其忠", "D": "願陛下親之「信」之，則漢室之隆，可計日而待也"}, "answer": "B", "explain": "〈墨池記〉「豈信然邪」的「信」是「真實、確實」。(B)正確，出自連橫〈臺灣通史序〉，「疑信相參」是可疑的和可信（真實）的混在一起。(A)出自《禮記‧禮運》，「講信」是講求信用。(C)出自魏徵〈諫太宗十思疏〉，「信者」是守信、誠實的人。(D)出自〈出師表〉，「信之」是信任他們。", "skill": "「信」常見四義：真實、信用、守信的人、信任；看它前後是形容事實還是形容人或動作。"}], "difficulty": "中", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-07", "exam": "et105", "nums": [7], "form": "單題", "img": "img/et105-07.png", "source": "《籌辦夷務始末》", "author": "清廷官修", "genre": "說理議論", "types": ["文意推論"], "passage": "天下之大，不患無才。如以天文、算學必須講習，博採旁求，必有精其術者，何必夷人，何必師事夷人？且夷人，吾仇也。倘延夷人為師，禍患無窮，甚至亡國滅種。", "translation": "天下這麼大，不怕沒有人才。如果認為天文、算學一定要學，廣泛尋訪，必定有精通的人，何必找外國人，何必拜外國人為師？況且外國人是我們的仇人。如果請外國人當老師，災禍無窮，甚至會亡國滅種。", "keywords": [{"w": "不患", "m": "不擔心"}, {"w": "博採旁求", "m": "廣泛尋求"}, {"w": "夷人", "m": "指外國人"}, {"w": "延", "m": "聘請"}], "questions": [{"n": 7, "qtype": "單選", "stem": "依據下文，何者不是作者反對學習夷人的理由？", "options": {"A": "中國幅員廣大，人才濟濟", "B": "以夷人為師，恐導致亡國", "C": "學夷人武備兵器之學，數典忘祖", "D": "國人天文算學俱優，不輸夷人"}, "answer": "C", "explain": "作者的理由有三：天下大、不缺人才（A）；國內只要找，一定有精通天文算學的人（D）；外國人是仇人，請來當老師會亡國滅種（B）。(C)不是理由，所以是答案——文中談的是天文、算學，沒有提到武備兵器，也沒有「數典忘祖」的說法。", "skill": "「何者不是」題，先把原文的理由列成清單，選項中找不到出處的就是答案。"}], "difficulty": "易", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-08", "exam": "et105", "nums": [8], "form": "單題", "img": "img/et105-08.png", "source": "《韓非子‧說林下》", "author": "韓非", "genre": "寓言故事", "types": ["主旨寓意", "文意推論"], "passage": "三蝨相與訟，一蝨過之，曰：「訟者奚說？」三蝨曰：「爭肥饒之地。」一蝨曰：「若亦不患臘之至而茅之燥耳，若又奚患？」於是乃相與聚嘬其母而食之。彘臞，人乃弗殺。", "translation": "三隻蝨子在吵架，另一隻蝨子經過，問：「你們在吵什麼？」三隻蝨子說：「在爭豬身上肥美的地方。」那隻蝨子說：「你們難道不擔心臘祭快到了、茅草燒起來（豬就要被殺來祭祀）嗎？你們還擔心別的什麼？」於是牠們一起聚在一處吸豬的血。豬變瘦了，人就沒殺牠。", "keywords": [{"w": "訟", "m": "爭吵"}, {"w": "奚", "m": "什麼"}, {"w": "若", "m": "你們"}, {"w": "臘", "m": "年終的臘祭，要殺豬祭祀"}, {"w": "茅之燥", "m": "用乾茅草燒豬毛"}, {"w": "嘬", "m": "吸、叮咬"}, {"w": "彘", "m": "豬"}, {"w": "臞", "m": "瘦"}], "questions": [{"n": 8, "qtype": "單選", "stem": "閱讀下文，對文章寓意的闡釋，何者最為妥適？", "options": {"A": "疾惡如仇，守正不阿為貴", "B": "目光如豆，圖近利必有失", "C": "君子愛財，取之必有其道", "D": "知足常樂，切勿貪得無厭"}, "answer": "B", "explain": "三隻蝨子只顧著爭豬身上最肥的一塊，卻沒想到豬養肥了就要被殺，大家都活不了；經提醒後放下小爭執，反而保住了命。寓意是只看眼前小利的短視會招來大禍。(B)正確。(A)和正直無關。(C)和取財方法無關。(D)重點不在知足，而在看清更大的危機。", "skill": "寓言題先問「角色原本犯了什麼錯」，答案通常就是對那個錯的警告。"}], "difficulty": "中", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-10", "exam": "et105", "nums": [10], "form": "單題", "img": "img/et105-10.png", "source": "綜合（多首古詩）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "人物情感"], "passage": "(A)踏花歸去馬蹄疾，一朝看盡長安花　(B)其雨其雨，杲杲出日，願言思伯，甘心首疾　(C)聞君有他心，拉雜摧燒之。摧燒之，當風揚其灰　(D)兔絲附蓬麻，引蔓故不長。嫁女與征夫，不如棄路旁", "translation": "(A)騎馬踏著落花回去，馬蹄輕快，一天就看遍長安的花。(B)盼望下雨吧盼望下雨，偏偏太陽高照；我一心想念丈夫，想到頭痛也甘願。(C)聽說你有了二心，就把信物砸碎燒掉，燒完了，還要迎風揚掉它的灰。(D)菟絲攀附在蓬草和麻上，藤蔓本來就長不長；把女兒嫁給出征的人，還不如丟在路邊。", "keywords": [{"w": "杲杲", "m": "太陽明亮的樣子"}, {"w": "伯", "m": "妻子對丈夫的稱呼"}, {"w": "首疾", "m": "頭痛"}, {"w": "拉雜", "m": "折斷、砸碎"}, {"w": "兔絲", "m": "菟絲，寄生植物"}], "questions": [{"n": 10, "qtype": "單選", "stem": "下列文句，何者屬於妻子心繫丈夫，情深無悔的感情？", "options": {"A": "踏花歸去馬蹄疾，一朝看盡長安花", "B": "其雨其雨，杲杲出日，願言思伯，甘心首疾", "C": "聞君有他心，拉雜摧燒之。摧燒之，當風揚其灰", "D": "兔絲附蓬麻，引蔓故不長。嫁女與征夫，不如棄路旁"}, "answer": "B", "explain": "(B)正確，出自《詩經‧衛風‧伯兮》，妻子思念出征的丈夫，想到頭痛也心甘情願，正是情深無悔。(A)化用孟郊〈登科後〉的心境，寫考中後的得意，與夫妻無關。(C)出自漢樂府〈有所思〉，女子得知情人變心，決裂燒掉信物，是決絕不是無悔。(D)出自杜甫〈新婚別〉，新娘感嘆嫁給征夫的悲苦，是怨嘆語氣。", "skill": "「無悔」的關鍵詞是「甘心、願」；看到「摧燒、棄」就是決絕或怨嘆。"}], "difficulty": "易", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-12", "exam": "et105", "nums": [12], "form": "單題", "img": "img/et105-12.png", "source": "《徐霞客遊記‧遊恆山日記》", "author": "徐弘祖（霞客）", "genre": "山水遊記", "types": ["文意推論", "字詞解釋"], "passage": "西崖之半，層樓高懸，曲榭斜倚，望之如蜃吐重台者，懸空寺也。五台北壑亦有懸空寺，擬此未能具體。仰之神飛，鼓勇獨登。入則樓閣高下，檻路屈曲。崖既矗削，為天下巨觀，而寺之點綴，兼能盡勝。依岩結構，而不為岩石累者，僅此。而僧寮位置適序，凡客坐禪龕，明窗暖榻，尋丈之間，肅然中雅。既下，又行峽中者三四轉，則洞門豁然，巒壑掩映，若別有一天者。又一里，澗東有門榜三重，高列阜上，其下石級數百層承之，則北嶽恒山廟之山門也。", "translation": "西邊山崖的半腰，層層樓閣高高懸著，曲折的水榭斜靠崖壁，看起來像海市蜃樓吐出的重重樓台，那就是懸空寺。五台山北邊山谷也有懸空寺，但和這裡比起來規模不夠完整。抬頭一看，心神飛揚，我鼓起勇氣獨自登上去。進去後樓閣高低錯落，欄杆和走道曲折。山崖本來就高聳陡峭，是天下壯觀，而寺廟點綴其間，更是美到極點。依著岩壁建造，卻不被岩石所拖累的，只有這座寺。僧房的位置安排得當，客房、坐禪的佛龕，明亮的窗、溫暖的床，在一丈見方的小空間裡，莊嚴而雅致。下來之後，又在峽谷中轉了三四個彎，洞門豁然開朗，山巒溝壑互相掩映，好像另有一片天地。再走一里，溪澗東邊有三重門匾，高高立在土山上，下面有幾百層石階承托，就是北嶽恆山廟的山門。", "keywords": [{"w": "榭", "m": "建在高台或水邊的屋子"}, {"w": "蜃吐重台", "m": "像海市蜃樓吐出的層層樓台"}, {"w": "擬", "m": "比"}, {"w": "具體", "m": "規模完備"}, {"w": "矗削", "m": "高聳陡峭"}, {"w": "累", "m": "拖累、受限"}, {"w": "僧寮", "m": "僧人住的房舍"}, {"w": "尋丈", "m": "八尺到一丈，形容空間小"}], "questions": [{"n": 12, "qtype": "單選", "stem": "閱讀下文，依據文意選出正確的選項：", "options": {"A": "所遊為五台山而不是恒山", "B": "建築受地形限制集中一處", "C": "建築物奢華富麗可比宮殿", "D": "懸空寺甚高位在西崖之上"}, "answer": "D", "explain": "開頭就說「西崖之半，層樓高懸……懸空寺也」，懸空寺高懸在西邊山崖上。(D)正確。(A)五台山的懸空寺只是拿來比較，最後到的是「北嶽恒山廟」，遊的是恆山。(B)原文說「依岩結構，而不為岩石累」，而且樓閣高下錯落，並不受地形限制。(C)房舍是「肅然中雅」，莊嚴雅致，不是奢華。", "skill": "遊記題注意「比較對象」和「實際所在」別混淆；描寫用語（雅、肅然）可以直接刪掉相反形容的選項。"}], "difficulty": "中", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-13", "exam": "et105", "nums": [13], "form": "單題", "img": "img/et105-13.png", "source": "綜合（多首古詩）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀"], "passage": "(A)蟬噪林逾靜，鳥鳴山更幽　(B)千山鳥飛絕，萬徑人蹤滅　(C)舊宅在山中，閑門與寺通　(D)空山不見人，但聞人語響", "translation": "(A)蟬聲喧鬧，樹林反而更顯寂靜；鳥兒鳴叫，山中更顯幽深。(B)千山萬嶺看不到一隻飛鳥，所有小路都沒有人的足跡。(C)舊居就在山中，安靜的門戶和寺院相通。(D)空寂的山裡看不到人，只聽到人說話的聲音。", "keywords": [{"w": "逾", "m": "更加"}, {"w": "以動襯靜", "m": "用聲音反襯環境的寂靜"}], "questions": [{"n": 13, "qtype": "單選", "stem": "閱讀下文，哪一個選項與文中所呈現的山中景色最相近？（引文：問余何事棲碧山，笑而不答，山已經代我回答了，其實山並未回答，是鳥代答了，是蟲，松風代山答了，山是禪機深藏的高僧，輕易不開口的。余光中〈沙田山居〉）", "options": {"A": "蟬噪林逾靜，鳥鳴山更幽", "B": "千山鳥飛絕，萬徑人蹤滅", "C": "舊宅在山中，閑門與寺通", "D": "空山不見人，但聞人語響"}, "answer": "A", "explain": "余光中寫山本身沉默，只有鳥、蟲、松風這些自然的聲音在「代答」，用自然聲響襯出山的靜。(A)正確，出自王籍〈入若耶溪〉，蟬鳴鳥叫反而讓山林更幽靜，也是以自然聲音襯靜。(B)出自柳宗元〈江雪〉，連鳥都沒有，是死寂孤絕，沒有聲音。(C)只寫住處和寺院相通，沒寫山中聲響。(D)出自王維〈鹿柴〉，雖也是以聲襯靜，但響的是「人語」，與文中鳥、蟲、松風的自然聲不同。", "skill": "比較景色時，同一手法的選項不只一個，要再比「聲音的來源」等細節，選最貼近的。"}], "difficulty": "中", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-14", "exam": "et105", "nums": [14], "form": "單題", "img": "img/et105-14.png", "source": "綜合（文言詞語）", "author": "", "genre": "其他", "types": ["字詞解釋", "虛詞句式"], "passage": "撫弦登陴／甲、天搖地動　乙、橫槊賦詩　丙、神清氣爽　丁、引觴滿酌", "translation": "撫弦登陴：彈著弓弦（或琴弦）登上城牆。橫槊賦詩：橫拿長矛吟詩。引觴滿酌：拿起酒杯斟滿酒。天搖地動：天搖晃、地震動。神清氣爽：精神清朗、心情舒暢。", "keywords": [{"w": "陴", "m": "城牆上的矮牆"}, {"w": "槊", "m": "長矛"}, {"w": "觴", "m": "酒杯"}, {"w": "酌", "m": "斟酒"}], "questions": [{"n": 14, "qtype": "單選", "stem": "以下詞語何者與「撫弦登陴」的結構相同，都是「動詞+名詞+動詞+名詞」的組合？甲、天搖地動　乙、橫槊賦詩　丙、神清氣爽　丁、引觴滿酌", "options": {"A": "甲丙", "B": "甲乙", "C": "乙丁", "D": "丙丁"}, "answer": "C", "explain": "「撫弦登陴」＝撫（動）弦（名）＋登（動）陴（名）。乙「橫槊賦詩」＝橫拿（動）長矛（名）＋吟作（動）詩（名），出自蘇軾〈赤壁賦〉，相同。丁「引觴滿酌」＝拿起（動）酒杯（名）＋斟滿（動）酒（名），相同。甲「天搖地動」是名＋動＋名＋動，順序相反。丙「神清氣爽」是名＋形容詞＋名＋形容詞。所以是乙丁，(C)正確。", "skill": "結構題逐字標詞性，只要第一個字是名詞（天、神）就可以直接刪。"}], "difficulty": "中", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-15", "exam": "et105", "nums": [15], "form": "單題", "img": "img/et105-15.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式", "句意理解"], "passage": "吾嘗求古仁人之心，或異二者之為，何哉／夫晉，何厭之有，既東封鄭，又肆欲西封／然則何為而可，曰：縱而來歸，殺之無赦／然則將何之，曰：將避地太原", "translation": "(A)我曾經探求古代仁人的心思，或許和這兩種人的表現不同，這是為什麼呢？(B)晉國哪有滿足的時候？已經在東邊把鄭國當作疆界，又想放肆地向西擴張。(C)那麼怎樣做才可以呢？答：放了他們，等他們回來，就殺了不赦免。(D)那麼要到哪裡去呢？答：要到太原去避難。", "keywords": [{"w": "何厭之有", "m": "有什麼滿足呢，即「沒有滿足」"}, {"w": "封", "m": "疆界，作動詞是「當作疆界」"}, {"w": "肆", "m": "放縱"}, {"w": "之", "m": "往、到"}], "questions": [{"n": 15, "qtype": "單選", "stem": "下列「」中的文句，何者屬於反面提出問題，答案不言而喻的反問修辭？", "options": {"A": "吾嘗求古仁人之心，或異二者之為，「何哉」", "B": "夫晉，「何厭之有」，既東封鄭，又肆欲西封", "C": "「然則何為而可」，曰：縱而來歸，殺之無赦", "D": "「然則將何之」，曰：將避地太原"}, "answer": "B", "explain": "反問是「問了但答案就在反面」，不需要回答。(B)正確，出自〈燭之武退秦師〉，「晉國哪有滿足？」意思就是晉國貪得無厭。(A)出自〈岳陽樓記〉，問完「何哉」後馬上自己回答「不以物喜，不以己悲」，是設問（提問）。(C)出自歐陽脩〈縱囚論〉，後面「曰：縱而來歸，殺之無赦」是自問自答，也是設問。(D)出自〈虬髯客傳〉，是真的在詢問去處，對方回答要去太原。", "skill": "問句後面緊接「曰」或答案的，是設問或詢問；問句本身就藏著否定答案的，才是反問。"}], "difficulty": "中", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-18", "exam": "et105", "nums": [18], "form": "單題", "img": "img/et105-18.png", "source": "綜合（多篇詩文）", "author": "", "genre": "其他", "types": ["字詞解釋", "寫作手法"], "passage": "雕闌玉砌應猶在，只是朱顏改／雲中誰寄錦書來，雁字回時，月滿西樓／慨當以慷，憂思難忘。何以解憂，唯有杜康／男女衣著，悉如外人，黃髮垂髫，並怡然自樂", "translation": "(A)雕花欄杆和玉石台階應該還在，只是美好的容顏已經改變。(B)雲中有誰寄書信來？雁群飛回時，月光灑滿西樓。(C)情緒激昂慷慨，憂思難以忘懷。用什麼來解憂？只有酒。(D)男女的穿著，都像外地人一樣；老人和小孩，都安適快樂。", "keywords": [{"w": "借代", "m": "用相關的事物代替本來要說的事物"}, {"w": "朱顏", "m": "紅潤的容顏，代青春美貌"}, {"w": "錦書", "m": "書信"}, {"w": "杜康", "m": "傳說中造酒的人，代酒"}, {"w": "黃髮", "m": "老人"}, {"w": "垂髫", "m": "小孩"}], "questions": [{"n": 18, "qtype": "單選", "stem": "下列文句「」中的詞語，其借代事物意義的闡釋，何者正確？", "options": {"A": "雕闌玉砌應猶在，只是「朱顏」改：時間", "B": "雲中誰寄「錦書」來，雁字回時，月滿西樓：禮服", "C": "慨當以慷，憂思難忘。何以解憂，唯有「杜康」：美酒", "D": "男女衣著，悉如外人，「黃髮」垂髫，並怡然自樂：兒童"}, "answer": "C", "explain": "(C)正確，出自曹操〈短歌行〉，杜康是傳說中發明釀酒的人，用他代指酒。(A)出自李煜〈虞美人〉，「朱顏」代紅潤的容顏、青春年華，不是時間。(B)出自李清照〈一剪梅〉，「錦書」是書信，不是禮服。(D)出自〈桃花源記〉，「黃髮」指老人（老人頭髮轉黃），「垂髫」才是兒童。", "skill": "常見借代要背熟：杜康＝酒、黃髮＝老人、垂髫＝小孩、錦書／尺素＝信、汗青＝史書。"}], "difficulty": "易", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-19", "exam": "et105", "nums": [19], "form": "單題", "img": "img/et105-19.png", "source": "應用文（婚嫁賀聯）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "二姓聯盟成大禮", "translation": "兩個家族結為姻親，完成婚姻大禮。", "keywords": [{"w": "二姓", "m": "兩個家族，指男女雙方"}, {"w": "偕老", "m": "一起白頭到老"}], "questions": [{"n": 19, "qtype": "單選", "stem": "「二姓聯盟成大禮」為祝賀結婚之上聯，其下聯應該補上：", "options": {"A": "一室長凝珠寶光", "B": "桃符萬戶布新春", "C": "百年偕老樂長春", "D": "孝友允為子弟箴"}, "answer": "C", "explain": "對聯要對仗、內容相關。「二姓／百年」數字相對，「聯盟／偕老」動作相對，「成大禮／樂長春」相對，而且「百年偕老」正是祝新人白頭到老。(C)正確。(A)寫珠寶的光彩，像是珠寶店的聯。(B)「桃符」「新春」是春聯。(D)講孝順友愛是子弟的規範，是家訓或勸勉聯。", "skill": "賀聯題先抓用途關鍵詞：婚嫁看「偕老、于歸、鳳凰」，春聯看「桃符、新春」，再檢查字面對仗。"}], "difficulty": "易", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-20", "exam": "et105", "nums": [20], "form": "單題", "img": "img/et105-20.png", "source": "綜合（典籍常識）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "甲、蕭統《昭明文選》　乙、劉勰《文心雕龍》　丙、趙崇祚《花間集》　丁、嚴羽《滄浪詩話》　戊、王國維《人間詞話》", "translation": "甲、蕭統編的《昭明文選》：選錄先秦到南朝梁的詩文，是詩文總集。乙、劉勰的《文心雕龍》：討論文章創作與評論的理論專書。丙、趙崇祚編的《花間集》：收錄晚唐五代的詞，是詞的總集。丁、嚴羽的《滄浪詩話》：以禪理比喻作詩、評論詩歌的著作。戊、王國維的《人間詞話》：用「境界」來評論詞的著作。", "keywords": [{"w": "文學批評", "m": "評論作品好壞、討論創作理論的著作"}, {"w": "總集", "m": "收錄多位作家作品的選集"}], "questions": [{"n": 20, "qtype": "單選", "stem": "下列何者屬於「文學批評」類的著作？甲、蕭統《昭明文選》　乙、劉勰《文心雕龍》　丙、趙崇祚《花間集》　丁、嚴羽《滄浪詩話》　戊、王國維《人間詞話》", "options": {"A": "乙丁戊", "B": "甲乙丁", "C": "乙丙戊", "D": "甲丙丁"}, "answer": "A", "explain": "乙《文心雕龍》是南朝系統性的文學理論巨著；丁《滄浪詩話》以禪喻詩，評論詩歌；戊《人間詞話》提出「境界說」評論詞作——三本都是文學批評。甲《昭明文選》是詩文總集（選文章），丙《花間集》是第一部詞的總集，都屬於作品選集，不是批評。所以是乙丁戊，(A)正確。", "skill": "書名有「話」「論」「雕龍」的多半是評論；書名有「選」「集」的多半是作品選集。"}], "difficulty": "易", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-21", "exam": "et105", "nums": [21], "form": "單題", "img": "img/et105-21.png", "source": "綜合（古代文體）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "表", "m": "臣子向君主陳情言事的奏章"}, {"w": "贈序", "m": "送別時贈給友人的序文"}, {"w": "檄", "m": "官府徵召或聲討的文書"}, {"w": "書", "m": "書信"}], "questions": [{"n": 21, "qtype": "單選", "stem": "下列古代文體類型的描述，何者錯誤？", "options": {"A": "「表」是古代用以陳情的公文書，如〈出師表〉", "B": "「序」用於贈人者稱之為贈序，如〈送董邵南序〉", "C": "「檄」是官府用以徵召或聲討的文書，如〈討武曌檄〉", "D": "「書」是古代陳述著作旨趣的文體，如〈與元微之書〉"}, "answer": "D", "explain": "(D)錯誤，所以是答案。「書」是書信，〈與元微之書〉是白居易寫給好友元稹的信；陳述著作旨趣的是「序」（書序），例如〈臺灣通史序〉。(A)「表」是臣子上給君主的奏章，諸葛亮〈出師表〉正確。(B)韓愈〈送董邵南序〉是送別友人的贈序，正確。(C)駱賓王〈討武曌檄〉是聲討武則天的檄文，正確。", "skill": "看篇名開頭：「與……書」「答……書」是書信；「……序」若是「送……序」是贈序，書名後的序是書序。"}], "difficulty": "易", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-22", "exam": "et105", "nums": [22], "form": "單題", "img": "img/et105-22.png", "source": "《西遊記》回目", "author": "吳承恩", "genre": "其他", "types": ["文化常識"], "passage": "第五回　亂蟠桃大聖偷丹　反天宮諸神捉怪／第六回　觀音赴會問原因　小聖施威降大聖／第七回　八卦爐中逃大聖　五行山下定心猿／第八回　我佛造經傳極樂　觀音奉旨上長安", "translation": "第五回：孫悟空擾亂蟠桃會、偷吃仙丹，天宮眾神出兵捉拿。第六回：觀音赴蟠桃會詢問原因，二郎神施展神威收服孫悟空。第七回：孫悟空從八卦爐中逃出，被如來壓在五行山下。第八回：如來造經要傳往東土，觀音奉命到長安尋找取經人。", "keywords": [{"w": "回目", "m": "章回小說每一回的標題，多為兩句對偶"}, {"w": "大聖", "m": "齊天大聖孫悟空"}, {"w": "小聖", "m": "二郎神"}], "questions": [{"n": 22, "qtype": "單選", "stem": "老師上課時播放下面投影片，關於投影片的內容敘述，何者正確？（投影片為《西遊記》第五至八回回目及插圖）", "options": {"A": "體例屬於章回小說", "B": "內容為佛教講經經文", "C": "結合史論時事與詩詞", "D": "受朝廷重視列為科舉項目"}, "answer": "A", "explain": "投影片列出「第五回」到「第八回」，每回有兩句對偶的標題，內容是孫悟空大鬧天宮——這是《西遊記》的回目，屬於分回敘事的章回小說。(A)正確。(B)雖然出現觀音、我佛，但它是神魔小說，不是佛經。(C)內容是神話故事，不是評論歷史或時事。(D)小說在古代不受朝廷重視，更不是科舉考試科目。", "skill": "看到「第○回」加兩句對偶標題，直接判定章回小說，再回想是哪一部名著。"}], "difficulty": "易", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-23", "exam": "et105", "nums": [23], "form": "單題", "img": "img/et105-23.png", "source": "綜合（史籍常識）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "編年體", "m": "依年月先後記事的史書體例"}, {"w": "斷代史", "m": "只記一個朝代的史書"}], "questions": [{"n": 23, "qtype": "單選", "stem": "明華想了解三國時代曹魏國家發展的軌跡，他應該選擇哪一本書？", "options": {"A": "《史記》", "B": "《漢書》", "C": "《世說新語》", "D": "《資治通鑑》"}, "answer": "D", "explain": "(D)正確，《資治通鑑》是司馬光主編的編年體通史，從戰國寫到五代，三國時期正是以曹魏年號紀年，能按年份看國家的發展。(A)《史記》只寫到漢武帝。(B)《漢書》是西漢的斷代史。(C)《世說新語》記東漢末到東晉名士的言行軼事，是筆記小說，看不到國家發展的脈絡。", "skill": "史書題先確認每本書的「時間範圍」，不包含所問年代的立刻刪。"}], "difficulty": "易", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-24", "exam": "et105", "nums": [24, 25, 26], "form": "題組", "img": "img/et105-24.png", "source": "張大復《梅花草堂筆談》", "author": "張大復", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "宋天禧中，宰相王欽若奏以杭州西湖為放生池，禁捕魚鳥，為人主祈福。每歲四月八日，郡人數萬會於湖上，所活羽毛鱗介以萬萬計。此王侯宰官今生作者之因也。吾鄉亦有放生會。每朔望輸錢於櫃，至期買羽水二族放之，亦是一事。第流浪陋劣之徒，乘機捕逐甚，有伺其釋放，而網罟之者，又不知作何慈悲，可免此厄，可度此等人也。正旦放生，人競逐之。論者以為不如勿放，此亦一時不得已之談。廣大教化，當不如是。僧本源欲建放生堂於玉柱塔之側，不知何時可了此願。塔在三江口，地闊天空，即不能禁民勿捕。於此放生，必多得所者。", "translation": "宋朝天禧年間，宰相王欽若奏請把杭州西湖作為放生池，禁止捕捉魚鳥，替皇上祈福。每年四月八日，當地幾萬人聚在湖上，放生的鳥獸魚蝦數以億計。這是王侯官員今生種下的善因。我家鄉也有放生會：每月初一、十五把錢投進櫃子，到時候買鳥和魚放生，也算是一件好事。只是那些遊手好閒的低劣之徒，趁機大肆捕捉，有人等著放生後再用網捕回去，真不知道要用什麼慈悲，才能讓這些生物免於災難，又能度化這種人。元旦放生時，大家爭相追捕。有人認為不如不要放，這也只是一時無可奈何的說法，真正廣大的教化，不應該是這樣。僧人本源想在玉柱塔旁建放生堂，不知何時能完成心願。玉柱塔在三江口，地方空曠、天空遼闊，即使不能禁止人民捕捉，在這裡放生，一定有很多生物能得到安身之所。", "keywords": [{"w": "人主", "m": "君主"}, {"w": "羽毛鱗介", "m": "鳥獸魚蝦等各類動物"}, {"w": "朔望", "m": "每月初一和十五"}, {"w": "輸錢", "m": "捐錢"}, {"w": "第", "m": "只是"}, {"w": "網罟", "m": "用網捕捉"}, {"w": "厄", "m": "災難"}, {"w": "正旦", "m": "農曆正月初一"}, {"w": "得所", "m": "得到適當的安身之處"}], "questions": [{"n": 24, "qtype": "單選", "stem": "依據上文，王欽若奏請以西湖為放生池，目的是為了：", "options": {"A": "向神明謝恩", "B": "增國君福報", "C": "讓蒼生獲福蔭", "D": "為飼主求平安"}, "answer": "B", "explain": "原文說「為人主祈福」，「人主」就是君主，目的是替皇帝增添福報。(B)正確。(A)沒有提到謝神。(C)祈福對象是君主，不是百姓。(D)放生池放的是野生魚鳥，和飼主無關。", "skill": "目的題直接找「為……」「以……」後面接的對象，再認清古詞（人主＝君主）。"}, {"n": 25, "qtype": "單選", "stem": "依據上文，下列何者符合作者對「買魚鳥放生」的看法？", "options": {"A": "實誤解佛教教義，危害風俗教化", "B": "既非慈悲為懷，也無益於消災解厄", "C": "使無道之徒為牟利而濫捕，加深罪孽", "D": "未顧及放生處原始生態，造成生態災難"}, "answer": "C", "explain": "作者肯定放生「亦是一事」，但擔心「流浪陋劣之徒，乘機捕逐甚，有伺其釋放而網罟之者」，讓壞人趁機捕捉牟利，連這些人都需要被「度」——表示他們的罪業更深了。(C)正確。(A)作者沒說放生誤解教義。(B)作者並不否定放生的慈悲。(D)文中沒有談到生態。", "skill": "作者態度題，先找他肯定的句子（亦是一事）和擔憂的句子（第……），答案通常落在「擔憂」那一段。"}, {"n": 26, "qtype": "單選", "stem": "依據上文，作者對「建放生堂於玉柱塔之側」的看法為何？", "options": {"A": "因地方空曠而不適放生", "B": "將使魚鳥濫捕更為嚴重", "C": "可讓更多民眾到此祈福", "D": "對被放生的魚鳥較有利"}, "answer": "D", "explain": "作者說玉柱塔在三江口，「地闊天空，即不能禁民勿捕，於此放生，必多得所者」——地方遼闊，就算有人捕捉，大多數魚鳥也能找到安身之處。(D)正確。(A)正好相反，空曠是優點。(B)作者認為在這裡放生能減少被捕的損害。(C)文中沒提到祈福的人數。", "skill": "「即……，必……」是讓步句，後半「必多得所」才是作者的結論。"}], "difficulty": "中", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-27", "exam": "et105", "nums": [27, 28, 29], "form": "題組", "img": "img/et105-27.png", "source": "張孝祥〈念奴嬌‧過洞庭〉", "author": "張孝祥", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀", "人物情感"], "passage": "洞庭青草，近中秋、更無一點風色。玉鑑瓊田三萬頃，著我扁舟一葉。素月分輝，明河共影，表裡俱澄澈。悠然心會，妙處難與君說。應念嶺海經年，孤光自照，肝肺皆冰雪。短髮蕭騷襟袖冷，穩泛滄浪空闊。盡吸西江，細斟北斗，萬象為賓客。扣舷獨笑，不知今夕何夕。", "translation": "洞庭湖和青草湖，接近中秋，一點風都沒有。像玉鏡般的湖面有三萬頃，載著我這一葉小船。皎潔的月光灑下光輝，銀河倒映在湖中，天上水下一片清澈透明。我悠然領會其中的美妙，卻難以向你說清楚。想起在嶺南任官的這一年，只有孤月照著我，我的心肝肺腑像冰雪一樣純潔。稀疏的短髮、單薄的衣袖帶著涼意，我穩穩地泛舟在空闊的湖上。我要吸盡西江的水當酒，用北斗星當酒勺細細斟酌，邀請天地萬物當我的賓客。敲著船舷獨自歡笑，不知道今晚是什麼樣的夜晚。", "keywords": [{"w": "風色", "m": "風的蹤影"}, {"w": "玉鑑瓊田", "m": "像玉鏡、玉田般的湖面"}, {"w": "著", "m": "放置、容納"}, {"w": "明河", "m": "銀河"}, {"w": "嶺海", "m": "兩廣一帶，作者曾在此任官"}, {"w": "孤光", "m": "孤月的光"}, {"w": "蕭騷", "m": "稀疏"}, {"w": "扣舷", "m": "敲打船邊"}], "questions": [{"n": 27, "qtype": "單選", "stem": "依據上文，下列選項何者錯誤？", "options": {"A": "依文體形式判斷，本篇作品為詞", "B": "季節為秋天，且以夜晚為書寫背景", "C": "觸動作者心緒的洞庭景物，主要為月亮", "D": "作者張孝祥宦途順遂，恬然退隱"}, "answer": "D", "explain": "(D)錯誤，所以是答案。「應念嶺海經年，孤光自照，肝肺皆冰雪」，是作者在嶺南任官一年後遭人誣陷罷官北歸，以冰雪自明清白，並非宦途順遂、自願退隱。(A)〈念奴嬌〉是詞牌，正確。(B)「近中秋」「素月」「明河」，是秋天夜晚，正確。(C)素月分輝、孤光自照，月光貫穿全篇，正確。", "skill": "「肝肺皆冰雪」「孤光自照」這類表白清白的話，通常暗示作者曾受冤屈或失意。"}, {"n": 28, "qtype": "單選", "stem": "以下范仲淹〈岳陽樓記〉中所敘寫的景境（季節不論），何者完全沒有出現在張孝祥作品中？", "options": {"A": "長煙一空，皓月千里", "B": "上下天光，一碧萬頃", "C": "漁歌互答，此樂何極", "D": "浩浩湯湯，橫無際涯"}, "answer": "C", "explain": "張詞寫的是一人獨自泛舟，「扣舷獨笑」，沒有別人。(C)「漁歌互答」是漁夫們互相對唱，詞中完全沒有，正確。(A)皓月千里，對應「素月分輝」。(B)天光水色相映，對應「明河共影，表裡俱澄澈」「玉鑑瓊田三萬頃」。(D)湖面廣闊無邊，對應「三萬頃」「滄浪空闊」。", "skill": "比較兩篇景物時，留意「人物多寡」：獨處的作品裡不會有熱鬧的人聲。"}, {"n": 29, "qtype": "單選", "stem": "關於本文的賞析，完全正確的是：", "options": {"A": "「更無一點風色」，以寒風淒景襯托孤獨", "B": "「素月分輝」，運用了擬物的手法，使意境生動", "C": "「肝肺皆冰雪」，展現張孝祥清越凜然的胸襟", "D": "「不知今夕何夕」，以反問作結，餘韻無窮"}, "answer": "C", "explain": "(C)正確，以冰雪比喻內心光明純潔，展現清高凜然的胸懷。(A)「更無一點風色」是說一點風都沒有，湖面平靜如鏡，不是寒風淒景。(B)「素月分輝」是月亮把光輝分給湖面，帶有擬人意味，不是擬物。(D)「不知今夕何夕」是陶醉到忘了時間的感嘆，不是反問。", "skill": "賞析題逐字核對：「無風」不能變「寒風」，「感嘆」不能說成「反問」，一字之差就是錯。"}], "difficulty": "中", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-30", "exam": "et105", "nums": [30, 31, 32], "form": "題組", "img": "img/et105-30.png", "source": "陳壽《三國志‧蜀書‧龐統傳》", "author": "陳壽", "genre": "史傳人物", "types": ["文意推論", "句意理解", "人物情感"], "passage": "龐統，字士元，襄陽人也。少時樸鈍，未有識者。潁川司馬徽清雅有知人鑒，統弱冠往見徽，徽採桑於樹上坐，統在樹下，共語自晝至夜。徽甚異之，稱統當南州士之冠冕，由是漸顯。後郡命為功曹，性好人倫，勤於長養。每所稱述，多過其才，時人怪而問之，統答曰：「當今天下大亂，雅道陵遲，善人少而惡人多。方欲興風俗，長道業，不美其譚即聲名不足慕企，不足慕企而為善者少矣。今拔十失五，猶得其半，而可以崇邁世教，使有志者自勵，不亦可乎？」……先主領荊州，統以從事守耒陽令，在縣不治，免官。吳將魯肅遺先主書曰：「龐士元非百里才也，使處治中、別駕之任，始當展其驥足耳。」諸葛亮亦言之於先主，先主見與善譚，大器之，以為治中從事，親待亞於諸葛亮。", "translation": "龐統，字士元，襄陽人。年少時樸實遲鈍，沒有人賞識他。潁川的司馬徽清高雅正，有識人的眼光；龐統二十歲時去拜見他，司馬徽坐在樹上採桑葉，龐統在樹下，兩人從白天談到夜晚。司馬徽非常驚奇，稱讚龐統應是南方士人中的第一人，龐統從此漸漸出名。後來郡裡任命他為功曹，他喜歡品評人物，熱心培養人才。每次稱讚別人，常常超過那人的實際才能，當時的人覺得奇怪就問他，龐統回答：「現在天下大亂，正道衰微，好人少壞人多。正要振興風俗、增長道德，如果不美言稱讚，名聲就不足以讓人羨慕仰望；不讓人羨慕仰望，願意行善的人就少了。現在提拔十個人，即使錯了五個，還是得到一半，卻可以推崇提升社會教化，讓有志向的人自我勉勵，不也很好嗎？」……劉備兼任荊州牧時，龐統以從事身分代理耒陽縣令，在縣裡沒有治理好，被免職。東吳將領魯肅寫信給劉備說：「龐士元不是只能治理百里小縣的人才，讓他擔任治中、別駕這類重要職位，才能施展他的長才。」諸葛亮也向劉備推薦他，劉備和他會面後談得很投機，非常器重他，任命他為治中從事，親近信任的程度僅次於諸葛亮。", "keywords": [{"w": "樸鈍", "m": "樸實遲鈍"}, {"w": "知人鑒", "m": "識別人才的眼光"}, {"w": "弱冠", "m": "二十歲"}, {"w": "冠冕", "m": "首位、第一"}, {"w": "人倫", "m": "品評人物"}, {"w": "長養", "m": "培養"}, {"w": "陵遲", "m": "衰微"}, {"w": "譚", "m": "同「談」，言論"}, {"w": "慕企", "m": "羨慕仰望"}, {"w": "百里才", "m": "只能治理一縣的才能"}, {"w": "驥足", "m": "良馬的腳力，比喻高才"}, {"w": "亞", "m": "次於"}], "questions": [{"n": 30, "qtype": "單選", "stem": "依據上文，下列人物與龐統的互動，何者錯誤？", "options": {"A": "魯肅請劉備留意他", "B": "司馬徽稱許他為賢才", "C": "諸葛亮希望劉備重用他", "D": "劉備有意讓他取代諸葛亮"}, "answer": "D", "explain": "(D)錯誤，所以是答案。原文說「親待亞於諸葛亮」，劉備對他的親信只次於諸葛亮，並沒有要取代諸葛亮。(A)魯肅寫信說他「非百里才」，正確。(B)司馬徽稱他是「南州士之冠冕」，正確。(C)「諸葛亮亦言之於先主」，向劉備推薦，正確。", "skill": "「亞於」＝次於、排第二，不是超過或取代。"}, {"n": 31, "qtype": "單選", "stem": "依據上文，魯肅對龐統的評價為何？", "options": {"A": "大材不宜小用", "B": "才高能屈能伸", "C": "自負且難驅遣", "D": "淺薄難堪重任"}, "answer": "A", "explain": "魯肅說龐統「非百里才」，當縣令委屈了他，要擔任治中、別駕才能「展其驥足」——就是大材不該小用。(A)正確。(B)魯肅正是說小官不適合他，不是說他能屈能伸。(C)沒有提到他自負難管。(D)正好相反，魯肅認為他能擔重任。", "skill": "「非……才也，使處……始……」的句型，就是在說「放錯位置、該給更大舞台」。"}, {"n": 32, "qtype": "單選", "stem": "下列對「方欲興風俗，長道業，不美其譚即聲名不足慕企，不足慕企而為善者少矣」的解釋，何者正確？", "options": {"A": "世俗因尚美名而趨於浮誇", "B": "高潔之士多不願沽名釣譽", "C": "顯揚善者可鼓舞世人向善", "D": "士人因徒具虛名而遭鄙薄"}, "answer": "C", "explain": "龐統解釋自己為什麼稱讚人總是誇大：要振興風俗，就要把好人說得好一點，讓大家羨慕，才會有更多人去行善。(C)正確，表揚善人能鼓勵大家向善。(A)他不是批評世俗浮誇，而是主動利用美名來教化。(B)沒有談到高潔之士的態度。(D)沒有說誰因虛名被看不起。", "skill": "連鎖句「不A則不B，不B則C」倒過來讀成「A→B→不C」，就是作者真正的主張。"}], "difficulty": "中", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et105-46", "exam": "et105", "nums": [46], "form": "單題", "img": "img/et105-46.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式", "句意理解"], "passage": "見漁人，乃大驚，問所從來。", "translation": "（桃花源的人）看見漁人，非常驚訝，問他從哪裡來。", "keywords": [{"w": "省略", "m": "文言常省略主語、受詞，要從上下文補出"}, {"w": "崩殂", "m": "帝王去世"}, {"w": "掩戶", "m": "關上門"}, {"w": "窮", "m": "走到盡頭"}], "questions": [{"n": 46, "qtype": "單選", "stem": "〈桃花源記〉：「見漁人，乃大驚，問所從來」，動詞「問」的後面，省略「問」的對象「漁人」。下列文句，何者也有此種敘述方式？", "options": {"A": "先帝創業未半，而中道崩殂", "B": "公閱畢，即解貂覆生，為掩戶", "C": "每覽昔人興感之由，若合一契", "D": "日與其徒上高山，入深林，窮迴谿"}, "answer": "B", "explain": "(B)正確，出自〈左忠毅公軼事〉，左光斗「閱畢」，看的是史可法的文稿，「閱」後面省略了對象；「為掩戶」也是「為（生）掩戶」，省略了替誰關門。(A)出自〈出師表〉，「崩殂」是去世，本來就不需要接對象。(C)出自〈蘭亭集序〉，「覽」後面有「昔人興感之由」，對象完整。(D)出自〈始得西山宴遊記〉，「上高山、入深林、窮迴谿」動詞後面都有地點。", "skill": "檢查每個動詞：問自己「做什麼？對誰？」，答案沒寫在句子裡、要靠上文補的，就是省略。"}], "difficulty": "中", "label": "105二技", "year": 105, "kind": "二技"}, {"id": "et106-01", "exam": "et106", "nums": [1], "form": "單題", "img": "img/et106-01.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "放於利而行，多怨／舍其路而弗由，放其心而不知求，哀哉／以亂易整，不武，吾其還也／蠟燭有心還惜別，替人垂淚到天明／有善始者實繁，能克終者蓋寡／忠志之士忘身於外者，蓋追先帝之殊遇／夫天地者，萬物之逆旅也／政之所興，在順民心；政之所廢，在逆民心", "translation": "(A)依照利益去做事，會招來很多怨恨／捨棄正路不走，丟失了本心卻不知道去找回來，真可悲啊。(B)用混亂代替整齊，不算勇武，我們還是回去吧／蠟燭好像有心，也捨不得離別，替人流淚到天亮。(C)有好的開始的人確實很多，能堅持到最後的大概很少／忠心的將士在外奮不顧身，大概是追念先帝的特殊恩遇。(D)天地是萬物的旅舍／政事能興盛，在於順應民心；政事會敗壞，在於違逆民心。", "keywords": [{"w": "放於利", "m": "依據利益（放，音ㄈㄤˇ）"}, {"w": "放其心", "m": "丟失本心"}, {"w": "還", "m": "回去；仍、還是"}, {"w": "蓋", "m": "大概，表推測"}, {"w": "逆旅", "m": "迎接旅客的地方，旅舍"}, {"w": "逆民心", "m": "違背民心"}], "questions": [{"n": 1, "qtype": "單選", "stem": "下列各組「」內的詞，何者意思相同？", "options": {"A": "「放」於利而行，多怨／舍其路而弗由，「放」其心而不知求，哀哉", "B": "以亂易整，不武，吾其「還」也／蠟燭有心「還」惜別，替人垂淚到天明", "C": "有善始者實繁，能克終者「蓋」寡／忠志之士忘身於外者，「蓋」追先帝之殊遇", "D": "夫天地者，萬物之「逆」旅也／政之所興，在順民心；政之所廢，在「逆」民心"}, "answer": "C", "explain": "(C)正確，前句出自魏徵〈諫太宗十思疏〉，後句出自〈出師表〉，兩個「蓋」都是「大概」，帶推測語氣。(A)《論語》的「放於利」是依照，《孟子》的「放其心」是丟失，不同。(B)〈燭之武退秦師〉的「還」是回去、撤兵；杜牧〈贈別〉的「還」是仍然、還是，不同。(D)李白〈春夜宴從弟桃花園序〉的「逆旅」，「逆」是迎接；《管子》「逆民心」的「逆」是違背，不同。", "skill": "一詞多義題，把每個字代入「動詞／副詞／名詞」哪一種，詞性不同就幾乎一定意思不同。"}], "difficulty": "中", "label": "106二技", "year": 106, "kind": "二技"}, {"id": "et106-02", "exam": "et106", "nums": [2], "form": "單題", "img": "img/et106-02.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "策扶老以流憩，時翹首而遐觀／乞其餘，不足，又顧而之他／馮崑崙以瞰霧兮，隱岷山以清江／執柯以伐柯，睨而視之，猶以為遠", "translation": "(A)拄著手杖到處走走歇歇，不時抬頭遠望。(B)向人討剩下的酒菜，不夠，又四處張望到別處去。(C)登上崑崙山俯瞰雲霧，憑著岷山眺望清澈的江水。(D)拿著斧頭去砍木頭做斧柄，斜著眼睛比對，還覺得差得很遠。", "keywords": [{"w": "遐觀", "m": "遠望"}, {"w": "顧", "m": "回頭看、四處張望"}, {"w": "瞰", "m": "從高處往下看"}, {"w": "睨", "m": "斜著眼睛看"}, {"w": "柯", "m": "斧柄"}], "questions": [{"n": 2, "qtype": "單選", "stem": "下列選項「」中的詞，何者是「斜著眼睛看」的意思？", "options": {"A": "策扶老以流憩，時翹首而遐「觀」", "B": "乞其餘，不足，又「顧」而之他", "C": "馮崑崙以「瞰」霧兮，隱岷山以清江", "D": "執柯以伐柯，「睨」而視之，猶以為遠"}, "answer": "D", "explain": "(D)正確，出自《中庸》，拿著斧頭砍樹枝做斧柄，「睨而視之」是斜眼比對手中斧柄的樣子。(A)出自陶淵明〈歸去來辭〉，「遐觀」是抬頭遠望。(B)出自《孟子》齊人章，「顧」是回頭看、四下張望。(C)「瞰」是由高處往下看，俯視。", "skill": "「看」的字要分方向：觀＝遠看、顧＝回頭、瞰＝俯視、睨＝斜看、睇＝斜視偷看。"}], "difficulty": "易", "label": "106二技", "year": 106, "kind": "二技"}, {"id": "et106-03", "exam": "et106", "nums": [3], "form": "單題", "img": "img/et106-03.png", "source": "綜合（多首古詩）", "author": "", "genre": "其他", "types": ["字詞解釋", "詩詞賞析"], "passage": "林木蕭森，離離蔚蔚，乃在霞氣之表。", "translation": "樹林幽深茂密，一片蓊鬱，高聳在雲霞之上。", "keywords": [{"w": "離離", "m": "①草木茂盛 ②清楚分明、歷歷可見"}, {"w": "蔚蔚", "m": "茂盛"}, {"w": "表", "m": "外、上方"}], "questions": [{"n": 3, "qtype": "單選", "stem": "酈道元《水經注》：「林木蕭森，離離蔚蔚，乃在霞氣之表。」句中的「離離」為草木茂盛的意思。下列選項中的「離離」，何者的意思與此相同？", "options": {"A": "夜峯何「離離」，月明落石底", "B": "「離離」原上草，一歲一枯榮", "C": "姦雄僭竊何足數，青史「離離」後人看", "D": "「離離」短幅開平遠，漠漠疎林寄秋晚"}, "answer": "B", "explain": "(B)正確，出自白居易〈賦得古原草送別〉，「離離原上草」是原野上茂盛的青草。(A)夜裡的山峰在月光下輪廓清晰，「離離」是分明的樣子。(C)篡位的奸雄在史書上記得清清楚楚，讓後人評判，「離離」是歷歷分明。(D)小小畫幅展開平遠的景色，「離離」也是清楚分明的樣子。", "skill": "疊字詞看它形容的東西：形容草木多半是茂盛，形容山、史書、畫面多半是清楚分明。"}], "difficulty": "中", "label": "106二技", "year": 106, "kind": "二技"}, {"id": "et106-04", "exam": "et106", "nums": [4], "form": "單題", "img": "img/et106-04.png", "source": "《叔苴子》", "author": "莊元臣", "genre": "寓言故事", "types": ["主旨寓意", "文意推論"], "passage": "鴝鵒之鳥，出於南方。南人羅而調其舌，久之，能效人言。但能效數聲而止，終日所唱，惟數聲也。蟬鳴於庭，鳥聞而笑之。蟬謂之曰：「子能人言，甚善。然子所言者，未嘗言也。曷若我自鳴其意哉！」鳥俯首而慚，終身不復效人言。", "translation": "八哥這種鳥產在南方。南方人把牠捕來訓練牠的舌頭，久了，就能模仿人說話。但只能學幾句就停了，一整天叫來叫去，也只有那幾句。蟬在庭院裡鳴叫，八哥聽了就嘲笑牠。蟬對牠說：「你會說人話，很好。可是你說的，等於沒說（你自己並不懂）。哪比得上我自己叫出自己的心意呢！」八哥低下頭很慚愧，一輩子不再學人說話。", "keywords": [{"w": "鴝鵒", "m": "八哥鳥"}, {"w": "羅", "m": "用網捕捉"}, {"w": "調其舌", "m": "訓練牠的舌頭"}, {"w": "效", "m": "模仿"}, {"w": "曷若", "m": "哪裡比得上"}], "questions": [{"n": 4, "qtype": "單選", "stem": "閱讀下文，下列選項何者錯誤？", "options": {"A": "作者藉此故事，諷刺只會模仿而不知其意的人", "B": "蟬因羨慕鴝鵒能夠模仿人說話，因而自慚形穢", "C": "南方人網羅鴝鵒，花了很長的時間教導牠說話", "D": "鴝鵒能仿效人言而沾沾自喜，遂譏笑蟬的鳴聲"}, "answer": "B", "explain": "(B)錯誤，所以是答案。蟬並沒有羨慕八哥，反而說「曷若我自鳴其意哉」，最後「俯首而慚」的是八哥。(A)八哥只會學舌卻不懂意思，諷刺盲目模仿的人，正確。(C)「南人羅而調其舌，久之」，花了很長時間訓練，正確。(D)八哥聽到蟬叫就「笑之」，可見自以為了不起，正確。", "skill": "寓言題的陷阱常是「主角互換」，把慚愧、嘲笑等動作的主詞對清楚。"}], "difficulty": "易", "label": "106二技", "year": 106, "kind": "二技"}, {"id": "et106-05", "exam": "et106", "nums": [5], "form": "單題", "img": "img/et106-05.png", "source": "洪邁《容齋續筆》", "author": "洪邁", "genre": "筆記小品", "types": ["文意推論", "字詞解釋"], "passage": "蛛之結網也，布絲引經，捷急上下，其始為甚難。至於緯而織之，轉盼可就，疏密分寸，未嘗不齊。門檻及花梢竹間，則不終日，必為人與風所敗。唯閑屋垝垣，人迹罕至，乃可久久而享其安。", "translation": "蜘蛛結網時，先拉出直向的絲，快速地上下來回，開頭是最困難的。到了織橫向的絲時，一眨眼就完成了，疏密間距沒有不整齊的。結在門檻和花枝竹叢間的網，不到一天就一定會被人或風破壞。只有在空屋和倒塌的牆邊，很少有人走過，才能長久安穩。", "keywords": [{"w": "經", "m": "直向的絲"}, {"w": "緯", "m": "橫向的絲"}, {"w": "轉盼", "m": "轉眼之間"}, {"w": "就", "m": "完成"}, {"w": "不終日", "m": "不到一整天"}, {"w": "敗", "m": "破壞"}, {"w": "垝垣", "m": "倒塌的牆"}], "questions": [{"n": 5, "qtype": "單選", "stem": "閱讀下文，依文意選出正確選項：", "options": {"A": "蜘蛛結網是先橫絲後直絲", "B": "蜘蛛網的橫絲比直絲難結", "C": "結在門檻及花梢竹間的蜘蛛網須在一天內完成", "D": "結在閑屋垝垣之處的蜘蛛網比較能夠長久完好"}, "answer": "D", "explain": "(D)正確，「唯閑屋垝垣，人迹罕至，乃可久久而享其安」。(A)先「布絲引經」（直絲），再「緯而織之」（橫絲），順序相反。(B)開頭的直絲「甚難」，橫絲「轉盼可就」，是直絲較難。(C)「不終日，必為人與風所敗」是說不到一天就被破壞，不是要一天內完成。", "skill": "經＝直、緯＝橫，像地球的經線緯線；「不終日」後面接的動作才是重點。"}], "difficulty": "易", "label": "106二技", "year": 106, "kind": "二技"}, {"id": "et106-06", "exam": "et106", "nums": [6], "form": "單題", "img": "img/et106-06.png", "source": "朱熹《朱子語類‧論讀書》", "author": "朱熹", "genre": "經典語錄", "types": ["文意推論", "主旨寓意"], "passage": "今人觀書，先自立了意後方觀，盡率古人語言入做自家意思中來，如此只是推廣得自家意思，如何見得古人意思？須得退步者，不要自作意思，只虛此心，將古人語言放前面，看他意思倒殺向何處去，如此玩心，方可得古人意，有長進處。", "translation": "現在的人讀書，先在心裡立好自己的想法才去讀，把古人的話全部拉進自己的意思裡，這樣只是擴充了自己的想法，怎麼能看懂古人的意思？必須退一步，不要自己先下定見，只要虛心，把古人的話擺在前面，看他的意思到底走向哪裡，這樣用心體會，才能得到古人的本意，才會有進步。", "keywords": [{"w": "立了意", "m": "先有了成見"}, {"w": "率", "m": "帶領、拉"}, {"w": "虛此心", "m": "使內心空虛，不帶成見"}, {"w": "倒殺", "m": "到底、究竟"}, {"w": "玩心", "m": "用心反覆體會"}], "questions": [{"n": 6, "qtype": "單選", "stem": "閱讀下文，依文意選出正確選項：", "options": {"A": "選自己認為有意思的書來讀，不能一味率從古人", "B": "以玩樂的心情來讀書，才能事半功倍而快速長進", "C": "先將古人語言譯成今人語言，才能體會古人的意思", "D": "應先去除自身的成見，從古人語言理解古人的意思"}, "answer": "D", "explain": "朱熹批評讀書先有成見，主張「不要自作意思，只虛此心」，從古人的話去看他的本意。(D)正確。(A)朱熹談的是讀書的態度，不是選書，而且他正要人尊重古人原意。(B)「玩心」是用心反覆體會，不是玩樂。(C)文中沒有提到翻譯。", "skill": "小心「玩、意思」這類古今意義不同的詞，「玩心」「玩味」都是仔細體會。"}], "difficulty": "易", "label": "106二技", "year": 106, "kind": "二技"}, {"id": "et106-07", "exam": "et106", "nums": [7], "form": "單題", "img": "img/et106-07.png", "source": "司馬遷《史記‧貨殖列傳》", "author": "司馬遷", "genre": "說理議論", "types": ["文意推論", "主旨寓意"], "passage": "禮生於有而廢於無，故君子富，好行其德；小人富，以適其力。淵深而魚生之，山深而獸往之，人富而仁義附焉。", "translation": "禮儀在富足時產生，在貧困時廢棄。所以君子富有了，喜歡施行恩德；一般百姓富有了，就能發揮自己的能力、安居樂業。水深了魚就會生長，山深了野獸就會前往，人富足了仁義就會依附而來。", "keywords": [{"w": "有、無", "m": "富有、貧窮"}, {"w": "小人", "m": "一般百姓"}, {"w": "適其力", "m": "發揮其能力"}, {"w": "附", "m": "依附"}], "questions": [{"n": 7, "qtype": "單選", "stem": "閱讀下文，依文意選出正確選項：", "options": {"A": "人民衣食富足之後更利於禮義教化", "B": "人富裕了就會停止謀利而追求禮義", "C": "每個人都想追求利益會使國家敗亡", "D": "政府須以禮義教化來抑制人民謀利"}, "answer": "A", "explain": "「禮生於有」「人富而仁義附焉」，司馬遷認為經濟富足是禮義的基礎。(A)正確。(B)他沒說富了就不再謀利，「小人富，以適其力」仍在發揮能力。(C)他肯定求富，沒說會亡國。(D)他主張先讓人富足，而不是用禮義壓抑謀利。", "skill": "「淵深而魚生之」這種比喻句，前面是條件、後面是結果，套回「人富→仁義」就是主旨。"}], "difficulty": "易", "label": "106二技", "year": 106, "kind": "二技"}, {"id": "et106-16", "exam": "et106", "nums": [16], "form": "單題", "img": "img/et106-16.png", "source": "應用文（柬帖用語）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "得年", "m": "六十歲以下過世用"}, {"w": "享年／享壽", "m": "六十歲以上過世用"}, {"w": "明珠入掌", "m": "賀生女兒"}, {"w": "湯餅之宴", "m": "嬰兒出生三日或滿月的宴席"}, {"w": "花燭之敬", "m": "賀男子結婚的禮金封套用語"}, {"w": "花粉之敬", "m": "賀女子出嫁的禮金封套用語"}], "questions": [{"n": 16, "qtype": "單選", "stem": "下列選項中的柬帖用詞，何者正確？", "options": {"A": "七十歲過世可稱「得年七十」", "B": "賀店鋪開張可用「明珠入掌」", "C": "小孩滿月酒席可稱「湯餅之宴」", "D": "祝賀男子成婚可用「花粉之敬」"}, "answer": "C", "explain": "(C)正確，古人在孩子出生後請親友吃湯餅，所以滿月或三朝的宴席稱「湯餅之宴」。(A)「得年」用在六十歲以下過世的人，七十歲應稱「享壽」或「享年」。(B)「明珠入掌」是賀人生女兒，店鋪開張要用「駿業宏開」之類。(D)「花粉之敬」是送女方出嫁用，男子結婚用「花燭之敬」。", "skill": "禮金封套記對照：男婚＝花燭、女嫁＝花粉；生男＝弄璋、生女＝弄瓦／明珠入掌。"}], "difficulty": "易", "label": "106二技", "year": 106, "kind": "二技"}, {"id": "et106-17", "exam": "et106", "nums": [17], "form": "單題", "img": "img/et106-17.png", "source": "《月令廣義》", "author": "馮應京", "genre": "其他", "types": ["文意推論", "寫作手法"], "passage": "天河之東有織女，天帝之子也，年年機杼勞役，織成雲錦天衣，容貌不暇整，帝憐其獨處，許嫁河西牽牛郎，嫁後遂廢織紝，天帝怒，責令歸河東，許一年一度相會。", "translation": "銀河東邊有個織女，是天帝的女兒，年年辛苦地織布，織出雲錦做的天衣，忙到沒空打扮。天帝可憐她獨自生活，答應把她嫁給銀河西邊的牛郎；出嫁後她就荒廢了織布，天帝很生氣，命令她回到銀河東邊，只准一年見面一次。", "keywords": [{"w": "子", "m": "兒女，這裡指女兒"}, {"w": "機杼", "m": "織布機"}, {"w": "不暇整", "m": "沒空整理打扮"}, {"w": "織紝", "m": "織布"}, {"w": "責令", "m": "命令"}], "questions": [{"n": 17, "qtype": "單選", "stem": "下列是一段中間拆散的文句，請依文意選出排列順序最恰當的選項：天河之東有織女，天帝之子也，甲、許嫁河西牽牛郎，嫁後遂廢織紝，乙、年年機杼勞役，織成雲錦天衣，丙、容貌不暇整，帝憐其獨處，丁、天帝怒，責令歸河東，許一年一度相會。", "options": {"A": "甲丙丁乙", "B": "乙丙甲丁", "C": "丙丁甲乙", "D": "丁甲乙丙"}, "answer": "B", "explain": "故事順序是：織女辛勤織布（乙）→忙到沒空打扮，天帝可憐她孤單（丙）→答應嫁給牛郎，婚後荒廢織布（甲）→天帝生氣，罰她回河東（丁），最後接「許一年一度相會」。乙丙甲丁，(B)正確。(A)一開始就嫁人，前面沒交代原因。(C)(D)天帝發怒放在嫁人之前，因果顛倒。", "skill": "故事排序抓因果：先有「憐其獨處」才「許嫁」，先「廢織紝」才「怒」。"}], "difficulty": "易", "label": "106二技", "year": 106, "kind": "二技"}, {"id": "et106-20", "exam": "et106", "nums": [20], "form": "單題", "img": "img/et106-20.png", "source": "綜合（多篇詩文）", "author": "", "genre": "其他", "types": ["字詞解釋", "寫作手法"], "passage": "楚雖三戶，亡秦必楚。", "translation": "楚國即使只剩下三戶人家，滅亡秦國的也一定是楚國。", "keywords": [{"w": "借代", "m": "以部分代全體、以特徵代本體等"}, {"w": "絲竹", "m": "弦樂器與管樂器，代音樂"}, {"w": "翰墨", "m": "筆墨，代文章、寫作"}, {"w": "社稷", "m": "土神與穀神，代國家"}, {"w": "斗牛", "m": "北斗星與牽牛星，代天空"}], "questions": [{"n": 20, "qtype": "單選", "stem": "「楚雖三戶，亡秦必楚」。戶原指門，代指一戶人家，這是以部分代指全體的修辭技巧。下列「」內的詞語，何者所代指的意義錯誤？", "options": {"A": "潯陽地僻無音樂，終歲不聞「絲竹」聲：音樂", "B": "是以古之作者，寄身於「翰墨」，見意於篇籍：官場", "C": "能執干戈以衛「社稷」，雖欲勿殤也，不亦可乎：國家", "D": "志吞虎彪，氣沖「斗牛」，大丈夫當及時出展經綸手：天空"}, "answer": "B", "explain": "(B)錯誤，所以是答案。出自曹丕〈典論論文〉，「翰」是毛筆、「墨」是墨汁，「寄身於翰墨」是把生命寄託在寫作上，代指文章、寫作，不是官場。(A)出自白居易〈琵琶行〉，絲竹代音樂，正確。(C)出自《禮記》，社稷原指土神穀神，代國家，正確。(D)斗、牛是兩個星宿，「氣沖斗牛」形容氣勢直衝天上，代天空，正確。", "skill": "借代題把被代的詞放回句子：「寄身於官場，見意於篇籍」前後不搭，就知道錯了。"}], "difficulty": "易", "label": "106二技", "year": 106, "kind": "二技"}, {"id": "et106-22", "exam": "et106", "nums": [22], "form": "單題", "img": "img/et106-22.png", "source": "綜合（文學常識）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "陰陽家", "m": "以陰陽五行解說天道人事的學派，代表人物鄒衍"}, {"w": "元曲四大家", "m": "關漢卿、白樸、馬致遠、鄭光祖"}, {"w": "十三經", "m": "儒家十三部經典，含《論語》《孟子》"}], "questions": [{"n": 22, "qtype": "單選", "stem": "下列敘述，何者錯誤？", "options": {"A": "韓非子、列子，都是陰陽家", "B": "關漢卿、白樸，都是元曲四大家", "C": "《論語》、《孟子》，都是十三經", "D": "《三國志》、《新唐書》，都是廿五史"}, "answer": "A", "explain": "(A)錯誤，所以是答案。韓非子是法家集大成者，列子是道家，陰陽家的代表是鄒衍。(B)元曲四大家是關漢卿、白樸、馬致遠、鄭光祖，正確。(C)十三經包含《論語》《孟子》，正確。(D)廿五史包含《三國志》和《新唐書》，正確。", "skill": "諸子學派記代表人物：儒（孔孟荀）、道（老莊列）、法（韓非、商鞅）、墨（墨翟）、陰陽（鄒衍）。"}], "difficulty": "易", "label": "106二技", "year": 106, "kind": "二技"}, {"id": "et106-23", "exam": "et106", "nums": [23], "form": "單題", "img": "img/et106-23.png", "source": "杜甫〈自京赴奉先縣詠懷五百字〉", "author": "杜甫", "genre": "其他", "types": ["文化常識", "典故出處"], "passage": "朱門酒肉臭，路有凍死骨。", "translation": "富貴人家的酒肉多到放臭了，路邊卻有凍死的人的屍骨。", "keywords": [{"w": "朱門", "m": "紅漆大門，代指富貴人家"}, {"w": "詩史", "m": "後人稱杜甫的詩如實記錄時代，有史詩價值"}], "questions": [{"n": 23, "qtype": "單選", "stem": "若利用網路搜尋，同時符合下列條件的文人是：詩史／關懷現實社會人生／朱門酒肉臭，路有凍死骨", "options": {"A": "辛棄疾", "B": "杜甫", "C": "陸游", "D": "白居易"}, "answer": "B", "explain": "「詩史」是後人對杜甫的稱號，他的詩記錄了安史之亂前後的社會；「朱門酒肉臭，路有凍死骨」出自他的〈自京赴奉先縣詠懷五百字〉。(B)正確。(A)辛棄疾是南宋豪放派詞人。(C)陸游是南宋愛國詩人。(D)白居易也寫社會寫實的新樂府，但「詩史」和這兩句詩都屬於杜甫。", "skill": "多條件題找最獨特的那一條（這裡是名句），一條就能鎖定人物。"}], "difficulty": "易", "label": "106二技", "year": 106, "kind": "二技"}, {"id": "et106-24", "exam": "et106", "nums": [24], "form": "單題", "img": "img/et106-24.png", "source": "綜合（經書常識）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "甲：風、雅、頌、賦、比、興／思無邪　乙：天、地、風、山、水、火／始於乾，終於未濟　丙：典、謨、訓、誥、誓、命／孔壁古文、盤庚、伏生　丁：公羊、穀梁、左氏／孔子筆削、微言大義、亂臣賊子懼", "translation": "甲：風、雅、頌是三種詩歌類別，賦、比、興是三種寫作手法，合稱「六義」；孔子說這本書的精神可以用「思無邪」（思想純正）一句話概括。乙：天、地、風、山、水、火是八卦所象徵的事物；全書的卦從乾卦開始，到未濟卦結束。丙：典、謨、訓、誥、誓、命是這本書裡的六種文體；漢代從孔子舊宅牆壁中發現古文本，〈盤庚〉是其中的篇名，伏生是漢初傳授這本書的學者。丁：公羊傳、穀梁傳、左傳是解說這本書的三部「傳」；這本書是孔子刪修而成，用簡短的字句寄寓褒貶（微言大義），使作亂的臣子、不孝的兒子感到害怕。", "keywords": [{"w": "六義", "m": "風、雅、頌（體裁）與賦、比、興（作法），指《詩經》"}, {"w": "未濟", "m": "《易經》最後一卦"}, {"w": "典謨訓誥誓命", "m": "《尚書》的六種文體"}, {"w": "伏生", "m": "漢初傳授《尚書》的人"}, {"w": "春秋三傳", "m": "公羊傳、穀梁傳、左傳"}], "questions": [{"n": 24, "qtype": "單選", "stem": "下表為小華的課堂筆記片斷，請根據筆記內容，依甲、乙、丙、丁的順序，選出正確的書名：", "options": {"A": "《詩》、《易》、《尚書》、《春秋》", "B": "《樂》、《春秋》、《論語》、《詩》", "C": "《樂》、《尚書》、《論語》、《易》", "D": "《詩》、《論語》、《樂》、《春秋》"}, "answer": "A", "explain": "甲：風雅頌賦比興是《詩經》的六義，「思無邪」是孔子對《詩經》的評語→《詩》。乙：天地風山水火是八卦的象，六十四卦從乾卦開始、未濟卦結束→《易》。丙：典謨訓誥誓命是《尚書》的文體，孔壁古文、〈盤庚〉、伏生都與《尚書》有關→《尚書》。丁：三傳都是解釋《春秋》的，孔子筆削《春秋》，「亂臣賊子懼」→《春秋》。所以是(A)。其他選項第一項就錯了（甲不是《樂》），可以直接刪。", "skill": "每部經記一個「招牌關鍵詞」：思無邪＝詩、乾坤卦＝易、典謨訓誥＝書、三傳＝春秋。"}], "difficulty": "易", "label": "106二技", "year": 106, "kind": "二技"}, {"id": "et106-25", "exam": "et106", "nums": [25, 26, 27], "form": "題組", "img": "img/et106-25.png", "source": "陳其元《庸閒齋筆記》卷三", "author": "陳其元", "genre": "筆記小品", "types": ["文意推論", "字詞解釋", "人物情感"], "passage": "福建漳、泉二府，頂兇之案極多。富戶殺人，出多金給貧者，代之抵死，雖有廉明之官，率受其蔽，所謂「宰白鴨」也。先大夫在讞局，嘗訊一鬬殺案，正兇年甫十六歲，檢屍格則傷有十餘處，非一人所能為，且年稚弱，似亦非力所能為。提取覆訊，則供口滔滔汨汩，與詳文無絲忽差。再令覆述，一字不誤，蓋讀之熟矣。加以駁詰，矢口不移。再四開導，始垂泣稱冤，即所謂「白鴨」者也。乃駁回縣更訊。未幾，縣又頂詳，仍照前議。再提犯問之，則斷斷不肯翻供矣。他委員嗤先大夫之迂，逕行提訊，遂如縣詳定案。比臬使過堂問之，仍執前供。因訊：「爾年紀甚輕，安能下此毒手？」則對曰：「恨極耳。」案定後發還縣，先大夫遇諸門，問曰：「爾何故如是執之堅？」則涕泗曰：「極感公解網恩，然發回之後，縣官更加酷刑，求死不得；父母又來罵曰：『賣爾之錢已用盡，爾乃翻供，以害父母乎？若出獄，必處爾死！』我思進退皆死，無甯順父母而死耳。」先大夫亦為之淚下。遂辭讞局差。", "translation": "福建漳州、泉州兩府，找人頂罪的案子非常多。有錢人殺了人，拿很多錢給窮人，讓他代替抵命，即使是清廉明察的官員，大多也被蒙蔽，這就是所謂的「宰白鴨」。我已故的父親在審判局任職時，曾審一件鬥毆殺人案，兇手才十六歲，查驗屍單發現傷口有十幾處，不是一個人能造成的，而且他年紀小、身體弱，看來也沒有那種力氣。提來重審，他供詞說得滔滔不絕，和公文記載一絲不差；再叫他複述，一字不錯，顯然是背熟了。加以反駁追問，他堅持不改口。再三開導，他才哭著喊冤，就是所謂的「白鴨」。於是把案子駁回縣裡重審。不久，縣裡又照原來的說法呈報上來。再提犯人來問，他卻堅決不肯翻供了。其他委員笑我父親迂腐，直接提審，就照縣裡的呈報定案。等到按察使過堂審問，他仍然堅持原來的供詞。按察使問：「你年紀這麼輕，怎麼下得了這種毒手？」他回答：「恨透了而已。」定案後發回縣裡，我父親在門口遇到他，問：「你為什麼這樣堅持？」他哭著說：「非常感激您想救我，可是發回縣裡後，縣官對我用更重的酷刑，求死都不能；父母又來罵我說：『賣你的錢已經花光了，你竟然翻供，要害父母嗎？如果你出獄，一定把你處死！』我想進退都是死，不如順從父母而死。」我父親也為他流淚，於是辭去了審判局的差事。", "keywords": [{"w": "頂兇", "m": "代替真兇頂罪"}, {"w": "率", "m": "大多"}, {"w": "蔽", "m": "蒙蔽"}, {"w": "讞局", "m": "審判案件的機構"}, {"w": "屍格", "m": "驗屍的紀錄表"}, {"w": "詳文", "m": "下級呈報上級的公文"}, {"w": "矢口不移", "m": "堅持說法不改"}, {"w": "迂", "m": "迂腐、不知變通"}, {"w": "比", "m": "等到"}, {"w": "臬使", "m": "按察使，掌管司法的官員"}, {"w": "解網恩", "m": "想要解救他的恩情"}, {"w": "無甯", "m": "不如"}], "questions": [{"n": 25, "qtype": "單選", "stem": "依上文，下列敘述何者正確？", "options": {"A": "文中的案件全為正兇一人所為", "B": "正兇寧願順父母之意頂罪而死", "C": "縣衙最後改變判決而使案情真相大白", "D": "讞局因正兇沒有稱冤而未曾駁回更審"}, "answer": "B", "explain": "少年最後說「我思進退皆死，無甯順父母而死耳」，寧可順從父母頂罪而死。(B)正確。(A)屍體「傷有十餘處，非一人所能為」，不是一人所為。(C)縣裡「又頂詳，仍照前議」，最後照原案定罪，真相沒有大白。(D)少年曾「垂泣稱冤」，讞局也確實「駁回縣更訊」。", "skill": "故事題注意結局：中間的轉折（稱冤、駁回）和最後結果（定案）常被選項混在一起。"}, {"n": 26, "qtype": "單選", "stem": "依上文，福建漳、泉地區所謂「白鴨」者為何？", "options": {"A": "長相白皙而身材稚弱的年輕罪犯", "B": "縣衙官吏在暗中安排的污點證人", "C": "因家貧而收人錢財來頂替死罪的窮人", "D": "熟悉訴狀內容而口齒伶俐的狡猾罪犯"}, "answer": "C", "explain": "開頭就定義：「富戶殺人，出多金給貧者，代之抵死……所謂宰白鴨也」，白鴨就是收錢替人抵命的窮人。(C)正確。(A)名稱和長相無關。(B)他不是證人，而是被當成兇手。(D)他熟背供詞是被安排好的，本身是可憐的受害者，不是狡猾罪犯。", "skill": "名詞解釋題回到文中「所謂……也」的前一句，那就是定義。"}, {"n": 27, "qtype": "單選", "stem": "依上文，作者父親淚下辭官的主要原因為何？", "options": {"A": "受到正兇父母嚴厲的責難", "B": "沒有得到其他屬官的認同", "C": "不滿正兇的供詞前後反覆", "D": "無法挽救頂罪惡習的悲劇"}, "answer": "D", "explain": "父親聽到少年被父母出賣、被縣官酷刑，明知冤枉卻救不了他，「為之淚下」，於是辭職。(D)正確，他無力改變頂罪的惡習。(A)被父母責罵的是少年，不是作者父親。(B)其他委員嘲笑他確有其事，但他是聽完少年的話才流淚辭職，主因是悲劇無法挽救。(C)他同情少年，不是不滿他翻來覆去。", "skill": "問「主要原因」，找緊接在行動（淚下、辭差）前面的那件事。"}], "difficulty": "中", "label": "106二技", "year": 106, "kind": "二技"}, {"id": "et106-28", "exam": "et106", "nums": [28, 29, 30], "form": "題組", "img": "img/et106-28.png", "source": "蘇軾〈日喻〉；錢大昕〈奕喻〉", "author": "蘇軾；錢大昕", "genre": "說理議論", "types": ["比較閱讀", "字詞解釋", "主旨寓意"], "passage": "（甲）生而眇者不識日，問之有目者。或告之曰：「日之狀如銅盤。」扣盤而得其聲。他日聞鐘，以為日也。或告之曰：「日之光如燭。」捫燭而得其形。他日揣籥，以為日也。日之與鐘、籥亦遠矣，而眇者不知其異，以其未嘗見而求之人也。道之難見也甚於日，而人之未達也，無以異於眇。達者告之，雖有巧譬善導，亦無以過於盤與燭也。自盤而之鐘，自燭而之籥，轉而相之，豈有既乎？故世之言道者，或即其所見而名之，或莫之見而意之，皆求道之過也。（乙）予觀奕於友人所，一客數敗，嗤其失算，輒欲易置之，以為不逮己也。頃之，客請與予對局，予頗易之。甫下數子，客已得先手。局將半，予思益苦，而客之智尚有餘。竟局數之，客勝予十三子，予赧甚，不能出一言。後有招予觀奕者，終日默坐而已。今之學者，讀古人書，多訾古人之失；與今人居，亦樂稱人失。人固不能無失，然試易地以處，平心而度之，吾果無一失乎？吾能知人之失而不能見吾之失，吾能指人之小失而不能見吾之大失。吾求吾失且不暇，何暇論人哉！", "translation": "（甲）天生眼盲的人不認識太陽，就去問看得見的人。有人告訴他：「太陽的形狀像銅盤。」他敲銅盤聽到了聲音，有一天聽到鐘聲，就以為那是太陽。有人告訴他：「太陽的光像蠟燭。」他摸蠟燭知道了形狀，有一天摸到籥（管狀樂器），就以為那是太陽。太陽和鐘、籥差得很遠，盲人卻不知道其中的不同，因為他沒親眼見過，只是向別人打聽。道比太陽更難看見，而沒有通達的人和盲人沒什麼兩樣。通達的人告訴他，即使有巧妙的比喻和善意的引導，也不會比銅盤和蠟燭的比喻更好。從盤到鐘，從燭到籥，輾轉比附下去，哪有盡頭？所以世上談道的人，有的拿自己看到的就當作是道，有的根本沒看見就憑空猜測，都是求道的錯誤。（乙）我在朋友家看下棋，一位客人屢次輸棋，我嘲笑他算錯，總想替他改換棋子的位置，認為他比不上我。不久，客人請我和他下一局，我很輕視他。才下幾顆子，客人已經取得先手。下到一半，我想得越來越吃力，客人卻還游刃有餘。下完一數，客人贏我十三子，我非常羞愧，一句話也說不出來。後來有人找我看下棋，我只是整天默默坐著。現在讀書的人，讀古人的書，常批評古人的錯；和今人相處，也喜歡指出別人的錯。人當然不可能沒有錯，但試著換個立場，平心想想，我真的一點錯都沒有嗎？我能知道別人的錯，卻看不見自己的錯；我能指出別人的小錯，卻看不見自己的大錯。我找自己的錯都來不及了，哪有空去評論別人！", "keywords": [{"w": "眇", "m": "瞎眼"}, {"w": "扣", "m": "敲"}, {"w": "捫", "m": "摸"}, {"w": "揣", "m": "摸索"}, {"w": "籥", "m": "古代管狀樂器，形似笛"}, {"w": "轉而相之", "m": "輾轉比附"}, {"w": "既", "m": "盡、完"}, {"w": "意", "m": "揣測、猜想"}, {"w": "嗤", "m": "譏笑"}, {"w": "易置", "m": "更換位置"}, {"w": "易", "m": "輕視"}, {"w": "不逮", "m": "比不上"}, {"w": "赧", "m": "羞愧臉紅"}, {"w": "訾", "m": "批評、指責"}], "questions": [{"n": 28, "qtype": "單選", "stem": "關於上列兩文的比較，下列選項何者正確？", "options": {"A": "皆採先敘後議的結構布局", "B": "皆主張學貴致用的重要性", "C": "皆以古史事件為論證案例", "D": "皆強調力求甚解的治學法"}, "answer": "A", "explain": "兩篇都是先講一個小故事（盲人識日、觀棋輸棋），再發表議論（求道之過、勿輕論人失），(A)正確。(B)〈日喻〉談求道要親身體會，〈奕喻〉談反省自己，都不是在講學以致用。(C)兩個故事都是生活寓言或親身經歷，不是歷史事件。(D)〈奕喻〉的重點是不要只看別人的錯，與「力求甚解」無關。", "skill": "「喻」體文章幾乎都是先說故事再講道理，比較題先看結構最穩。"}, {"n": 29, "qtype": "單選", "stem": "依上列兩文，下列選項何者錯誤？", "options": {"A": "〈日喻〉云「轉而相之」，意謂：輾轉以各種事物來比附", "B": "〈日喻〉中眇者「他日揣籥，以為日也」，是基於形狀的推想", "C": "〈奕喻〉云「予頗易之」，意謂：我曾經好幾次都想要更動棋子", "D": "〈奕喻〉「輒欲易置之」與「予頗易之」，兩「易」字之義不同"}, "answer": "C", "explain": "(C)錯誤，所以是答案。「予頗易之」的「易」是輕視，意思是我很看不起他；想更動棋子的是前面「輒欲易置之」。(A)從盤到鐘、從燭到籥，一路比附下去，正確。(B)他摸過蠟燭的形狀，摸到同樣是長條狀的籥就以為是太陽，正確。(D)「易置」是更換，「頗易之」是輕視，兩者不同，正確。", "skill": "同一篇裡出現兩次的字，常故意考不同意思；「易」可作交換、容易、輕視。"}, {"n": 30, "qtype": "單選", "stem": "關於上列兩文主要意涵的敘述，下列選項何者正確？", "options": {"A": "〈日喻〉主張求道必須要志向遠大，並博覽群書", "B": "〈奕喻〉主張論人必須要以古證今，並擇善固執", "C": "〈日喻〉說明世之言道者都能求真而免流於臆測", "D": "〈奕喻〉說明常人易犯闇於自見而長於論人之弊"}, "answer": "D", "explain": "(D)正確，「吾能知人之失而不能見吾之失」就是看不清自己（闇於自見）、卻擅長評論別人。(A)〈日喻〉說的是不能只聽別人描述，要親身體會，沒提志向和博覽群書。(B)〈奕喻〉要人先反省自己，不是以古證今或擇善固執。(C)正好相反，蘇軾說世上談道的人不是以偏概全就是憑空臆測，「皆求道之過也」。", "skill": "主旨題找文末的結論句（皆求道之過也／何暇論人哉），和選項逐字比對正反。"}], "difficulty": "中", "label": "106二技", "year": 106, "kind": "二技"}, {"id": "et106-31", "exam": "et106", "nums": [31, 32, 33], "form": "題組", "img": "img/et106-31.png", "source": "應劭《風俗通義‧怪神》", "author": "應劭", "genre": "筆記小品", "types": ["文意推論", "主旨寓意"], "passage": "汝南鮦陽，有於田得麇者，其主未敢取也。商車十餘乘，經澤中行，望見此麇著繩，因持去。念其不事，持一鮑魚置其處。有頃，其主往，不見所得麇，反見鮑魚。澤中非人道路，怪其如是，大以為神，轉相告語。治病求福，多有效驗。因為起祀舍，眾巫數十，帷帳鐘鼓。方數百里，皆來禱祀，號「鮑君神」。其後數年，鮑魚主來，歷祠下尋問其故。曰︰「此我魚也，當有何神？」上堂取之，遂從此壞。傳曰︰「物之所聚斯有神。」言人共獎成之耳。", "translation": "汝南郡鮦陽縣，有人在田裡用繩索捉到一隻獐子，主人還沒敢去拿。有十幾輛商人的車經過沼澤地，看到這隻被繩子綁住的獐子，就拿走了。商人想到白拿人家東西不好，就放了一條鹹魚在原處。過了一會兒，主人來了，不見捉到的獐子，反而看到一條鹹魚。沼澤裡不是人走的路，他覺得奇怪，以為是神蹟，大家互相傳說。有人來治病求福，常常有效驗。於是替它蓋了祠堂，有幾十個巫師，掛帷帳、設鐘鼓。方圓幾百里的人都來祈禱祭祀，稱它為「鮑君神」。幾年後，那個放鹹魚的商人經過，到祠堂下打聽緣故，說：「這是我的魚啊，哪有什麼神？」上堂把魚拿走，這個神從此就沒落了。古書說：「東西聚集的地方就會有神。」意思是說，神是人們一起捧出來的罷了。", "keywords": [{"w": "麇", "m": "獐子，一種鹿"}, {"w": "著繩", "m": "被繩索套住"}, {"w": "不事", "m": "不勞而獲、不合事理"}, {"w": "鮑魚", "m": "鹹魚"}, {"w": "有頃", "m": "不久"}, {"w": "起祀舍", "m": "蓋祠堂"}, {"w": "歷", "m": "經過"}, {"w": "獎成", "m": "助長、捧出來"}], "questions": [{"n": 31, "qtype": "單選", "stem": "依上文，下列選項何者正確？", "options": {"A": "田中的麇是由經過的商人所發現並抓住", "B": "汝南鮦陽人拿鮑魚去和商人買賣麇來養", "C": "商人和汝南鮦陽人共同築舍設帳來祭祀鮑魚", "D": "最先宣揚鮑魚有神力是最初抓到麇的那個人"}, "answer": "D", "explain": "抓到獐子的主人回來看見鹹魚，「怪其如是，大以為神，轉相告語」，是他最先說這是神蹟。(D)正確。(A)獐子是田主用繩子套住的，商人只是看到就拿走。(B)是商人自己留下鹹魚，雙方根本沒見面交易。(C)蓋祠堂的是當地百姓，商人早就離開了。", "skill": "人物多的故事，先把「誰做了什麼」列成時間表，再一一比對選項的主詞。"}, {"n": 32, "qtype": "單選", "stem": "依上文，下列關於「鮑君神」的敘述，何者正確？", "options": {"A": "鮑君神在經過數年後，因神力衰退而逐漸被人淡忘", "B": "鮑君神原是商人帶走麇之後，而留置在田中的鮑魚", "C": "鮑君神是由田中的麇變化而來，因而常有神蹟出現", "D": "鮑君神最先是由鮑魚主所供奉，並裝神弄鬼而來的"}, "answer": "B", "explain": "鮑君神就是商人拿走獐子後放在原處的那條鹹魚。(B)正確。(A)它是被鹹魚主人揭穿「此我魚也」，拿走後才沒落，不是神力衰退。(C)不是獐子變成的。(D)鹹魚主人是揭穿真相的人，不是供奉的人。", "skill": "「遂從此壞」前面的動作就是沒落的原因，別被「數年」這種時間詞誤導。"}, {"n": 33, "qtype": "單選", "stem": "下列選項，何者最能說明「鮑君神」的形成原因？", "options": {"A": "因原得麇者捕風捉影，進而人云亦云", "B": "因鮑魚主的精誠所至，進而金石為開", "C": "因鮑魚不斷精進修練，進而得道成神", "D": "因眾巫能夠洞燭機先，進而建廟祀禱"}, "answer": "A", "explain": "獐子主人沒弄清楚原因就認定是神（捕風捉影），大家又跟著傳（人云亦云），最後「言人共獎成之耳」——神是眾人一起捧出來的。(A)正確。(B)鹹魚主人只是隨手留下魚，沒有精誠祈求。(C)鹹魚不會修練。(D)巫師是後來才加入的，並非他們預先看出什麼。", "skill": "結尾「言……耳」是作者的評論，用它來對照選項中的成語。"}], "difficulty": "易", "label": "106二技", "year": 106, "kind": "二技"}, {"id": "et106-40", "exam": "et106", "nums": [40, 41, 42], "form": "題組", "img": "img/et106-40.png", "source": "李白〈下江陵〉（〈早發白帝城〉）；葉珊〈唐詩舉例〉", "author": "李白；葉珊（楊牧）", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法", "比較閱讀"], "passage": "朝辭白帝彩雲間，千里江陵一日還；兩岸猿聲啼不住，輕舟已過萬重山。（文中並引：三山半落青天外，二水中分白鷺洲／即從巴峽穿巫峽，便下襄陽向洛陽／長安一片月，萬戶擣衣聲）", "translation": "清晨告別高聳在彩雲間的白帝城，千里外的江陵一天就到了；兩岸猿猴的啼聲還響個不停，輕快的小船已經穿過了重重山巒。", "keywords": [{"w": "白帝", "m": "白帝城，在今重慶奉節，地勢高"}, {"w": "江陵", "m": "今湖北荊州"}, {"w": "啼不住", "m": "叫個不停"}, {"w": "萬重山", "m": "重重疊疊的山"}], "questions": [{"n": 40, "qtype": "單選", "stem": "依上文，下列敘述，何者不是作者對詩歌的看法？", "options": {"A": "「即從巴峽穿巫峽，便下襄陽向洛陽」在杜甫詩中屬於快速節奏", "B": "「三山半落青天外，二水中分白鷺洲」在李白詩中屬於慢板節奏", "C": "「兩岸猿聲啼不住」是李白使用擬人手法描寫與友人離別的場面", "D": "「朝辭白帝彩雲間」展現李白透過意象佈置達到藝術表現的成就"}, "answer": "C", "explain": "(C)不是作者看法，所以是答案。作者說「兩岸猿聲」是用「相關客體」的技巧——不寫快字，而用猿聲還沒停、船已過萬重山，襯托船行之快；不是擬人，也不是寫和朋友離別。(A)作者說杜甫這兩句「好像也是……飛馳節奏」，符合。(B)作者說「三山半落」兩句是「嫺靜的抒寫」、慢板，符合。(D)作者說李白善於佈置意象，「彩雲間」一出現就確定了全詩風貌，符合。", "skill": "評論文章的「不是作者看法」題，回到原文找作者對該句的評語，術語一換（相關客體→擬人）就是陷阱。"}, {"n": 41, "qtype": "單選", "stem": "作者說，「朝辭白帝彩雲間」不是「早上離開彩雲的白帝城」，而是「早上離開白帝城，白帝城在彩雲裏」。下列選項，何者不是作者的觀點？", "options": {"A": "李白使用了後設的形容技巧", "B": "李白在一句間交代了兩個動作", "C": "整句使用日記體而平淡乏味", "D": "善於佈置意象使句中高潮迭起"}, "answer": "C", "explain": "作者說「朝辭白帝」四字是平淡的日記體，但因為「彩雲間」突然出現，整句就變得不平凡。(C)說整句平淡乏味，不是作者觀點，所以是答案。(A)作者說「彩雲間」是後設的形容，符合。(B)作者說「一句之間已交代了兩個動作」，符合。(D)作者說李白「善為各種意象的佈置，一句之間高潮迭起」，符合。", "skill": "留意範圍詞：作者批評的是「前四字」，選項卻說「整句」，範圍擴大就錯。"}, {"n": 42, "qtype": "單選", "stem": "依上文，畫線處（一句之間已交代了兩個動作）指的是哪兩個動作？（甲）辭別登船（乙）回頭發現（丙）登高遠眺（丁）上岸還鄉（戊）逐浪疾行", "options": {"A": "甲乙", "B": "甲丁", "C": "丙戊", "D": "丙丁"}, "answer": "A", "explain": "作者解釋「彩雲間」是「辭別剎那登船頃刻，猛回頭才發現的風景」——兩個動作就是辭別登船（甲）和回頭發現（乙），(A)正確。丙「登高遠眺」文中沒有；丁「上岸還鄉」是第二句的事；戊「逐浪疾行」是後兩句船行的描寫，都不是第一句的動作。", "skill": "「指的是什麼」題，答案通常就在畫線句的前一兩句，把動詞圈出來就好。"}], "difficulty": "中", "label": "106二技", "year": 106, "kind": "二技"}, {"id": "et107-01", "exam": "et107", "nums": [1], "form": "單題", "img": "img/et107-01.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "相與枕藉乎舟中，不知東方之既白／羸兵為人馬所蹈藉，陷泥中，死者甚眾／裹足不入秦，此所謂藉寇兵而齎盜糧者也／輒啟兵戎，喋血山河，藉言恢復，而舊志亦不備載也", "translation": "(A)大家互相枕著、靠著睡在船裡，不知道東方已經發白。(B)瘦弱的士兵被人馬踩踏，陷在泥裡，死了很多人。(C)讓天下賢士止步不敢進秦國，這就是所謂把兵器借給敵人、把糧食送給盜賊啊。(D)動不動就發動戰爭，血流山河，假借「收復」的名義，舊的方志也沒有完整記載。", "keywords": [{"w": "枕藉", "m": "縱橫交錯地躺著"}, {"w": "蹈藉", "m": "踐踏"}, {"w": "藉寇兵", "m": "把兵器借給敵人"}, {"w": "藉言", "m": "假借名義、藉口"}], "questions": [{"n": 1, "qtype": "單選", "stem": "下列選項中的「藉」，何者解釋正確？", "options": {"A": "相與枕「藉」乎舟中，不知東方之既白：雜草", "B": "羸兵為人馬所蹈「藉」，陷泥中，死者甚眾：藉口", "C": "裹足不入秦，此所謂「藉」寇兵而齎盜糧者也：雜草", "D": "輒啟兵戎，喋血山河，「藉」言恢復，而舊志亦不備載也：藉口"}, "answer": "D", "explain": "「藉」的意思要看前後搭配。(A)錯，出自蘇軾〈赤壁賦〉，「枕藉」是大家橫七豎八地互相枕靠著睡，不是雜草。(B)錯，出自《資治通鑑‧赤壁之戰》，「蹈藉」是踐踏，弱兵被人馬踩死，不是藉口。(C)錯，出自李斯〈諫逐客書〉，「藉寇兵」是把兵器借給敵人，「藉」通「借」。(D)正確，出自連橫〈臺灣通史序〉，「藉言恢復」是假借收復的名義，「藉」就是藉口、假託。", "skill": "同一個字出現在常見詞組時，先把它放回整句換成白話試讀，讀得通的解釋才對。"}], "difficulty": "中", "label": "107二技", "year": 107, "kind": "二技"}, {"id": "et107-02", "exam": "et107", "nums": [2], "form": "單題", "img": "img/et107-02.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "微管仲，吾其被髮左衽矣／細草微風岸，危檣獨夜舟／駑馬十駕，功在不舍／蓋亭之所見，南北百里，東西一舍／人之生也直，罔之生也幸也免／舉直錯諸枉，能使枉者直／泰山不讓土壤，故能成其大／數之以不忠死亡之罪，讓三老孝弟以不教誨之過", "translation": "(A)如果沒有管仲，我們恐怕要披散頭髮、衣襟左開（淪為夷狄）了／微風吹著岸邊的細草，高高的桅桿孤單地停在夜裡。(B)劣馬拉車走十天也能走很遠，功勞在於不停止／從亭上望去，南北一百里，東西三十里。(C)人能生存是靠正直，不正直的人能活著只是僥倖逃過災禍／提拔正直的人放在邪曲的人之上，能使邪曲的人也變正直。(D)泰山不拒絕任何泥土，所以能成就它的高大／數落他不忠、讓百姓死亡的罪，責備三老、孝弟沒有教誨百姓的過失。", "keywords": [{"w": "微", "m": "若非、如果沒有／細小"}, {"w": "舍", "m": "停止／古代三十里為一舍"}, {"w": "直", "m": "正直"}, {"w": "讓", "m": "推辭、拒絕／責備"}], "questions": [{"n": 2, "qtype": "單選", "stem": "下列各組「」中的詞語，何者意義相同？", "options": {"A": "「微」管仲，吾其被髮左衽矣／細草「微」風岸，危檣獨夜舟", "B": "駑馬十駕，功在不「舍」／蓋亭之所見，南北百里，東西一「舍」", "C": "人之生也「直」，罔之生也幸也免／舉直錯諸枉，能使枉者「直」", "D": "泰山不「讓」土壤，故能成其大／數之以不忠死亡之罪，「讓」三老孝弟以不教誨之過"}, "answer": "C", "explain": "(C)正確，兩句都出自《論語》，「直」都是正直：人活著要靠正直；把正直的人提拔上來，能讓邪曲的人也變正直。(A)錯，《論語》的「微管仲」是「如果沒有」；杜甫〈旅夜書懷〉的「微風」是輕微的風。(B)錯，《荀子‧勸學》「功在不舍」是不停止；蘇轍〈黃州快哉亭記〉「東西一舍」是三十里的距離單位。(D)錯，〈諫逐客書〉「不讓土壤」是不拒絕；後句「讓三老孝弟」是責備。", "skill": "比較兩句同字時，先判斷詞性（虛詞、動詞、量詞），詞性不同，意思多半也不同。"}], "difficulty": "中", "label": "107二技", "year": 107, "kind": "二技"}, {"id": "et107-03", "exam": "et107", "nums": [3], "form": "單題", "img": "img/et107-03.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "景翳翳以將入，撫孤松而盤桓／向之所欣，俛仰之間，已為陳跡／在西池射堂上，躍馬顧盼，自以為一世之雄／參差荇菜，左右流之，窈窕淑女，寤寐求之", "translation": "(A)陽光漸漸昏暗，太陽快要下山，我撫著孤松徘徊不去。(B)過去所喜愛的事物，一低頭一抬頭之間，已經成了陳跡。(C)在西池射堂上，騎馬左右顧看，自以為是當代的英雄。(D)長短不齊的荇菜，左右撈取它；美好的淑女，醒時睡時都在追求她。", "keywords": [{"w": "翳翳", "m": "昏暗的樣子"}, {"w": "俛仰", "m": "低頭抬頭之間，比喻時間極短"}, {"w": "顧盼", "m": "左右張望，有得意之態"}, {"w": "寤寐", "m": "醒著和睡著，指日日夜夜"}], "questions": [{"n": 3, "qtype": "單選", "stem": "下列選項「」中的詞語，何者是「時間短暫」的意思？", "options": {"A": "景「翳翳」以將入，撫孤松而盤桓", "B": "向之所欣，「俛仰」之間，已為陳跡", "C": "在西池射堂上，躍馬「顧盼」，自以為一世之雄", "D": "參差荇菜，左右流之，窈窕淑女，「寤寐」求之"}, "answer": "B", "explain": "(B)正確，出自王羲之〈蘭亭集序〉，「俛仰之間」就是低頭抬頭那麼一下子，形容時間極短，快樂轉眼成過去。(A)錯，陶淵明〈歸去來辭〉的「翳翳」是天色昏暗，描寫景象不是時間長短。(C)錯，「顧盼」是左右看，寫人意氣風發的樣子。(D)錯，《詩經‧關雎》的「寤寐」是醒著睡著都想，反而是「時時刻刻」，不是短暫。", "skill": "題目指定某種意思時，把每個詞換成那個意思放回句中，只有語意順的才是答案。"}], "difficulty": "易", "label": "107二技", "year": 107, "kind": "二技"}, {"id": "et107-04", "exam": "et107", "nums": [4], "form": "單題", "img": "img/et107-04.png", "source": "《霞外雜俎》（改寫）", "author": "鐵腳道人（舊題，明）", "genre": "筆記小品", "types": ["主旨寓意", "文意推論"], "passage": "和氣湯（專治一切客氣、怒氣、怨氣、抑鬱不平之氣）先用一個「忍」字，後用一個「忘」字，上二味和勻，用「不語」唾送下。此方先之以忍，可免一朝之忿也；繼之以忘，可無終身之戚也。", "translation": "和氣湯（專門治療各種客套的虛氣、怒氣、怨氣和悶在心裡的不平之氣）：先用一個「忍」字，再用一個「忘」字，把這兩味藥調勻，用「不說話」的口水吞下去。這帖藥先用「忍」，可以避免一時的憤怒衝突；接著用「忘」，可以不留下一輩子的憂傷。", "keywords": [{"w": "味", "m": "藥方中的一種藥材"}, {"w": "忿", "m": "憤怒"}, {"w": "戚", "m": "憂傷"}], "questions": [{"n": 4, "qtype": "單選", "stem": "閱讀下文，下列選項何者與和氣湯的處世哲學最為相近？", "options": {"A": "多言賈禍，退一步海闊天空", "B": "知足常樂，身後有餘應縮手", "C": "虛懷若谷，忠言逆耳利於行", "D": "危言危行，滄浪之水濯吾纓"}, "answer": "A", "explain": "和氣湯的三個重點是「忍」「忘」「不語」：少說話、忍一時、放下怨氣。(A)正確，「多言賈禍」對應「不語」，「退一步海闊天空」對應忍讓與放下。(B)錯，講的是知足、見好就收，和忍怒忘怨無關。(C)錯，講謙虛接受別人的勸告，重點在聽取意見。(D)錯，「危言危行」是說話做事正直敢言，「濯吾纓」是依時勢決定出仕或隱退，跟「不語」「忍讓」正好相反。", "skill": "仿藥方、仿公文的文章，先把每味「藥材」列出來，再找能一一對應的選項。"}], "difficulty": "易", "label": "107二技", "year": 107, "kind": "二技"}, {"id": "et107-05", "exam": "et107", "nums": [5], "form": "單題", "img": "img/et107-05.png", "source": "《禮記‧中庸》", "author": "子思（相傳）", "genre": "經典語錄", "types": ["主旨寓意", "句意理解"], "passage": "子曰：「道不遠人。人之為道而遠人，不可以為道。詩云：『伐柯伐柯，其則不遠。』執柯以伐柯，睨而視之，猶以為遠。故君子以人治人，改而止。」", "translation": "孔子說：「道並不遠離人。如果有人追求道卻遠離了人情常理，那就不能算是道。《詩經》說：『砍斧柄啊砍斧柄，斧柄的樣式就在眼前。』拿著斧柄去砍新的斧柄，只要斜眼看一下就有樣子可照，還有人覺得很遠。所以君子用人本身的道理來治理人，對方改正了就停止。」", "keywords": [{"w": "柯", "m": "斧頭的柄"}, {"w": "則", "m": "法則、樣式"}, {"w": "睨", "m": "斜眼看"}, {"w": "改而止", "m": "對方改正就停止，不苛求"}], "questions": [{"n": 5, "qtype": "單選", "stem": "閱讀下段文字，推論該段文字的主旨應該是：", "options": {"A": "討論治人之道", "B": "傳授伐柯技巧", "C": "揭示養生方法", "D": "闡釋互助意涵"}, "answer": "A", "explain": "文章最後一句是結論：「故君子以人治人，改而止」，砍斧柄只是比喻，說明做人的道理就在人自己身上，要用人本身的道理去治理人。(A)正確。(B)錯，伐柯是比喻，不是真的教木工技巧。(C)錯，全文沒有談身體保養。(D)錯，沒有講人與人互相幫助。", "skill": "說理文常先用比喻再下結論，看到「故」「是以」後面那句，通常就是主旨。"}], "difficulty": "易", "label": "107二技", "year": 107, "kind": "二技"}, {"id": "et107-06", "exam": "et107", "nums": [6], "form": "單題", "img": "img/et107-06.png", "source": "《東坡志林‧子瞻患眼疾》", "author": "蘇軾", "genre": "筆記小品", "types": ["文意推論", "句意理解"], "passage": "余患赤目，或言不可食膾。余欲聽之，而口不可，曰：「我與子為口，彼與子為眼，彼何厚，我何薄？以彼患而廢我食，不可。」子瞻不能決。口謂眼曰：「他日我瘖，汝視物，吾不禁也。」", "translation": "我得了紅眼病，有人說不可以吃生魚片。我想聽從，可是嘴巴不答應，它說：「我是你的嘴，它是你的眼睛，為什麼對它那麼好，對我那麼差？因為它生病就不讓我吃東西，不行。」我（子瞻）無法決定。嘴巴對眼睛說：「哪天我啞了，你要看東西，我也不會禁止你。」", "keywords": [{"w": "赤目", "m": "眼睛紅腫的病"}, {"w": "膾", "m": "切細的生魚或生肉"}, {"w": "厚／薄", "m": "優待／虧待"}, {"w": "瘖", "m": "啞，不能說話"}], "questions": [{"n": 6, "qtype": "單選", "stem": "閱讀下段文字，不合乎該段文字內容的選項是：", "options": {"A": "嘴巴認為，口與眼應該得到相同對待，不應有差別", "B": "嘴巴埋怨眼睛可以看，自己卻因為眼睛生病不能吃", "C": "嘴巴不服氣，主人為了不讓嘴巴食膾而製造眼疾的理由", "D": "嘴巴對眼睛說，他日自己瘖瘂，不會干涉眼睛做任何事"}, "answer": "C", "explain": "這是蘇軾的幽默小品，把嘴巴擬人化，替自己想吃生魚片找理由。(C)不合，眼病是真的（「余患赤目」），不是主人「製造」出來的理由，嘴巴只是不服因眼病被禁口。(A)合，「彼何厚，我何薄」就是要求公平對待。(B)合，「以彼患而廢我食」正是埋怨因眼睛的病而不能吃。(D)合，「他日我瘖，汝視物，吾不禁也」。", "skill": "選「不合」的題目，逐項回原文找對應句；找不到根據、或和事實相反的就是答案。"}], "difficulty": "易", "label": "107二技", "year": 107, "kind": "二技"}, {"id": "et107-07", "exam": "et107", "nums": [7], "form": "單題", "img": "img/et107-07.png", "source": "《日知錄》", "author": "顧炎武", "genre": "說理議論", "types": ["主旨寓意", "文意推論"], "passage": "詩文之所以代變，有不得不變者。一代之文，沿襲已久，不容人人皆道此語。今且千數百年矣，而猶取古人之陳言一一而摹仿之，以是為詩可乎？故不似則失其所以為詩，似則失其所以為我。李、杜之詩所以獨高於唐人者，以其未嘗不似，而未嘗似也。", "translation": "詩文之所以每個時代都在變，是因為有不得不變的原因。一個時代的文風沿用久了，不能讓每個人都說同樣的話。如今已經過了一千多年，還拿古人的老話一句句模仿，這樣寫詩可以嗎？所以，完全不像古人，就失去了詩之所以為詩的根本；太像古人，又失去了自己。李白、杜甫的詩之所以在唐人中特別高明，是因為他們沒有不像古人的地方，卻又從來不只是模仿古人。", "keywords": [{"w": "代變", "m": "隨時代而改變"}, {"w": "陳言", "m": "陳舊的話語"}, {"w": "所以為詩", "m": "詩之所以成為詩的根本"}], "questions": [{"n": 7, "qtype": "單選", "stem": "閱讀下段文字，合乎該段文字內容的選項是︰", "options": {"A": "摹仿是創造的動力，高手無不藉摹仿之助而登峰造極", "B": "主流傳統不可輕棄，不斷刻意追求新變反而易失自我", "C": "詩文演變有其定則，但不輕易順隨時代改變才是正道", "D": "創造不能缺少傳統，但只知一味摹仿也不能稱為創造"}, "answer": "D", "explain": "關鍵句是「不似則失其所以為詩，似則失其所以為我」：要繼承傳統（似），也要有自己（不似）。(D)正確，正好說出這兩面。(A)錯，作者反對「一一而摹仿之」，沒有說模仿是動力。(B)錯，作者擔心的是一味模仿而失去自我，不是追求新變而失去自我。(C)錯，作者說詩文「有不得不變者」，主張要隨時代改變。", "skill": "遇到「不似則…，似則…」這種正反並列句，答案通常要兩邊都顧到。"}], "difficulty": "中", "label": "107二技", "year": 107, "kind": "二技"}, {"id": "et107-14", "exam": "et107", "nums": [14], "form": "單題", "img": "img/et107-14.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式", "句意理解"], "passage": "孟嘗君出記，問門下諸客：「誰習計會，能為文收責於薛者乎？」／為大臣而無所不取，無所不為，則天下其有不亂，國家其有不亡者乎？／良曰：「料大王士卒足以當項王乎？」沛公默然，曰：「固不如也。」／公辨其聲，而目不可開，乃奮臂以指撥眥，目光如炬，怒曰：「庸奴！此何地也，而汝來前！」", "translation": "(A)孟嘗君拿出帳冊，問門下食客：「誰熟悉會計，能替我到薛地收債？」(B)當大臣卻什麼都拿、什麼都做，那天下哪有不亂、國家哪有不亡的呢？(C)張良說：「您估計大王的士兵足以抵擋項王嗎？」沛公沉默，說：「本來就比不上。」(D)左公聽出他的聲音，眼睛卻睜不開，於是用力舉起手臂用手指撥開眼眶，目光像火炬，生氣地說：「蠢奴才！這是什麼地方，你竟敢來！」", "keywords": [{"w": "計會", "m": "會計、算帳"}, {"w": "責", "m": "同「債」"}, {"w": "料", "m": "估量"}, {"w": "眥", "m": "眼眶"}], "questions": [{"n": 14, "qtype": "單選", "stem": "漢語問句類型中有「是非問句」，指的是提出的問題只要求對方作肯定或否定的回答，不需要回答具體的人物、事件、原因等等。下列選項畫線中的句子何者屬於是非問句？", "options": {"A": "孟嘗君出記，問門下諸客：「誰習計會，能為文收責於薛者乎？」", "B": "為大臣而無所不取，無所不為，則天下其有不亂，國家其有不亡者乎？", "C": "良曰：「料大王士卒足以當項王乎？」沛公默然，曰：「固不如也。」", "D": "公辨其聲，而目不可開，乃奮臂以指撥眥，目光如炬，怒曰：「庸奴！此何地也，而汝來前！」"}, "answer": "C", "explain": "是非問句只要回答「是／不是」。(C)正確，出自《史記‧項羽本紀》，張良問「能不能擋住項王」，沛公答「固不如也」（不能），就是肯定否定式的回答。(A)錯，出自《戰國策‧馮諼客孟嘗君》，問「誰」，要回答具體人物，是特指問句。(B)錯，出自顧炎武〈廉恥〉（引用歐陽脩《新五代史》的話），是不需要回答的反問句，意思是天下一定會亂。(D)錯，出自方苞〈左忠毅公軼事〉，「此何地也」是用問句表達責罵的反詰，不是真的要對方答是或否。", "skill": "判斷問句類型：有「誰、何、安」等疑問代詞多是特指問；答案已藏在問句裡的是反問；只能答是或否的才是是非問。"}], "difficulty": "中", "label": "107二技", "year": 107, "kind": "二技"}, {"id": "et107-15", "exam": "et107", "nums": [15], "form": "單題", "img": "img/et107-15.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "可以養松喬之壽，鳴琴垂拱，不言而化／交戟之衛士欲止不內，樊噲側其盾以撞／微夫人之力不及此。因人之力而敝之，不仁／河海不擇細流，故能就其深；王者不卻眾庶，故能明其德", "translation": "(A)可以像赤松子、王子喬那樣長壽，彈琴垂衣拱手，不用發號施令天下就能教化。(B)持戟交叉守門的衛士想阻止他、不讓他進去，樊噲把盾牌側過來一撞。(C)如果沒有那個人的力量，我到不了今天。靠了人家的力量卻反過來傷害他，是不仁厚的。(D)河海不挑選細小的水流，所以能那麼深；君王不拒絕眾多百姓，所以能彰顯他的德行。", "keywords": [{"w": "內", "m": "同「納」，使進入"}, {"w": "仁", "m": "仁厚"}, {"w": "卻", "m": "拒絕、推辭"}], "questions": [{"n": 15, "qtype": "單選", "stem": "下列選項「」中的詞語，何者的詞性說明正確？", "options": {"A": "可以養松喬之壽，鳴琴垂拱，不「言」而化：表動作的動詞", "B": "交戟之衛士欲止不「內」，樊噲側其盾以撞：表方位的名詞", "C": "微夫人之力不及此。因人之力而敝之，不「仁」：表程度的副詞", "D": "河海不擇細流，故能就其深；王者不「卻」眾庶，故能明其德：表轉折的連接詞"}, "answer": "A", "explain": "(A)正確，出自魏徵〈諫太宗十思疏〉，「不言而化」是不必說話（下命令）就能教化，「言」是說話的動作，屬動詞。(B)錯，出自《史記‧鴻門宴》，「內」通「納」，是讓人進去，屬動詞，不是方位名詞。(C)錯，出自《左傳‧燭之武退秦師》，「不仁」是不仁厚，「仁」是形容詞。(D)錯，出自李斯〈諫逐客書〉，「卻」是拒絕，屬動詞，和前句「不擇」對應。", "skill": "判斷詞性時，看它前面有沒有「不」：「不＋X」的X通常是動詞或形容詞，再看能不能接受詞。"}], "difficulty": "中", "label": "107二技", "year": 107, "kind": "二技"}, {"id": "et107-17", "exam": "et107", "nums": [17], "form": "單題", "img": "img/et107-17.png", "source": "應用文（柬帖）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "2018年國曆六月二日（星期六）農曆四月十九日為令慈七秩壽辰敬備桃觴　恭請台光　陳○○　謹訂", "translation": "2018年國曆6月2日（星期六），也就是農曆4月19日，是「令慈」（這是尊稱別人母親的詞，用在自己母親身上是錯的）七十歲生日，恭敬地準備了壽宴，誠心邀請您光臨。陳○○恭敬地邀請。", "keywords": [{"w": "令慈", "m": "敬稱對方的母親"}, {"w": "家母", "m": "謙稱自己的母親"}, {"w": "七秩", "m": "七十歲"}, {"w": "桃觴", "m": "壽酒，指壽宴"}, {"w": "台光", "m": "敬請對方光臨"}], "questions": [{"n": 17, "qtype": "單選", "stem": "下列是一則陳○○邀請親友前來慶賀自己母親七十歲生日的柬帖，老師請班上學生修改其中的錯誤，哪一個選項的修改正確？", "options": {"A": "學生甲：「令慈要改為家母才是！」", "B": "學生乙：「壽辰要改為湯餅才是！」", "C": "學生丙：「桃觴應改為六禮才對！」", "D": "學生丁：「台光應改為謹約才對！」"}, "answer": "A", "explain": "這是陳○○替自己母親辦壽宴的請帖。(A)正確，「令慈」是稱呼「別人的」母親，自己的母親要稱「家母」。(B)錯，「湯餅」是嬰兒滿月或週歲的宴會，七十大壽用「壽辰」才對。(C)錯，「桃觴」是壽酒，用在祝壽很恰當；「六禮」是婚禮的程序。(D)錯，「恭請台光」是請對方光臨的固定用語，「謹約」不能這樣用。", "skill": "稱謂題口訣：「家大舍小令外人」——稱自己長輩用「家」，稱對方親屬用「令」。"}], "difficulty": "易", "label": "107二技", "year": 107, "kind": "二技"}, {"id": "et107-21", "exam": "et107", "nums": [21], "form": "單題", "img": "img/et107-21.png", "source": "張可久〈賣花聲‧客況〉", "author": "張可久", "genre": "古典詩詞曲", "types": ["典故出處", "詩詞賞析"], "passage": "登樓北望思王粲，高臥東山憶謝安，悶來長鋏為誰彈？當年射虎，將軍何在？冷淒淒霸陵古岸。", "translation": "登上高樓向北眺望，想起寫〈登樓賦〉的王粲；想起當年高臥東山的謝安。心中苦悶時，長劍要彈給誰聽呢？當年射虎的李廣將軍，如今在哪裡？只剩冷清淒涼的霸陵古岸。", "keywords": [{"w": "長鋏", "m": "長劍；馮諼曾彈鋏而歌"}, {"w": "高臥東山", "m": "謝安隱居東山"}, {"w": "射虎將軍", "m": "李廣"}], "questions": [{"n": 21, "qtype": "單選", "stem": "閱讀以下詩歌，哪一句運用了與孟嘗君有關的典故？", "options": {"A": "登樓北望思王粲", "B": "高臥東山憶謝安", "C": "悶來長鋏為誰彈", "D": "當年射虎將軍何在"}, "answer": "C", "explain": "(C)正確，戰國時馮諼投靠孟嘗君，覺得待遇不好就彈著長劍唱「長鋏歸來乎」，後來成為孟嘗君的重要門客，「彈鋏」常比喻懷才不遇、求人賞識。(A)錯，王粲寄居荊州，寫〈登樓賦〉抒發思鄉與不得志。(B)錯，謝安隱居東山，後來出山救國。(D)錯，是漢代飛將軍李廣射虎、晚年失意的故事，霸陵也是李廣被霸陵尉羞辱的地方。", "skill": "典故題先把句中人名、器物抓出來（王粲、謝安、長鋏、射虎），再對應熟悉的故事。"}], "difficulty": "中", "label": "107二技", "year": 107, "kind": "二技"}, {"id": "et107-22", "exam": "et107", "nums": [22, 23, 24], "form": "題組", "img": "img/et107-22.png", "source": "《顏氏家訓‧名實》", "author": "顏之推", "genre": "說理議論", "types": ["文意推論", "主旨寓意", "句意理解"], "passage": "吾見世人，清名登而金貝入，信譽顯而然諾虧，不知後之矛戟，毀前之干櫓也。虙子賤云：「誠於此者形於彼。」人之＿＿＿＿，無不見乎迹，但察之未熟耳。一為察之所鑒，巧偽不如拙誠，承之以羞大矣。伯石讓卿，王莽辭政，當於爾時，自以巧密；後人書之，留傳萬代，可為骨寒毛豎也。近有大貴，以孝著聲，前後居喪，哀毀踰制，亦足以高於人矣。而嘗於苫塊之中，以巴豆塗臉，遂使成瘡，表哭泣之過。左右童豎，不能掩之，益使外人謂其居處飲食，皆為不信。以一偽喪百誠者，乃貪名不已故也。", "translation": "我看世上有些人，清廉的名聲一建立就開始收錢，誠信的名聲一顯揚就不守承諾，不知道後來自己的矛戟，會毀掉先前的盾牌。虙子賤說：「在這裡真誠，就會在那裡表現出來。」人心的虛實真假，沒有不從行跡中顯露的，只是旁人觀察得不夠仔細罷了。一旦被看穿，耍巧作假還不如笨拙而真誠，隨之而來的羞辱可大了。伯石假意推辭卿位、王莽假意辭讓政權，當時自以為巧妙周密；後人把它寫進史書，流傳萬代，真令人毛骨悚然。最近有位大貴人，以孝順出名，前後守喪時哀傷得超過禮制，也足以比別人高了。可是他曾在守喪的草席土塊間，用巴豆塗臉，弄出瘡來，裝作哭得很厲害。身邊的僮僕沒能替他掩飾，反而讓外人連他守喪時的起居飲食都不相信了。因為一次作假而喪失了上百次的真誠，就是因為貪求名聲沒有止境啊。", "keywords": [{"w": "金貝", "m": "錢財"}, {"w": "然諾", "m": "答應別人的承諾"}, {"w": "干櫓", "m": "盾牌"}, {"w": "迹", "m": "行跡、表現"}, {"w": "苫塊", "m": "守喪時睡草席、枕土塊，借指居喪"}, {"w": "巴豆", "m": "有刺激性的藥材"}], "questions": [{"n": 22, "qtype": "單選", "stem": "閱讀上文，文中舉出伯石、王莽兩例，其令人「骨寒毛豎」的可能原因為何？", "options": {"A": "言行輕浮，受到史家無情貶抑", "B": "虛情假意，欺世之名終被揭穿", "C": "聚斂財富，生活奢侈為人嫌惡", "D": "惡名昭彰，史書刻意吹捧失實"}, "answer": "B", "explain": "伯石三次推辭卿位最後還是接受，王莽假裝謙讓政權最後篡漢，兩人都是表面謙讓、骨子裡貪求，當時自以為高明，卻被史書記下流傳萬代。(B)正確，正是虛偽被揭穿。(A)錯，他們不是輕浮，而是偽裝得很周密，史家也只是如實記錄。(C)錯，文中重點不在聚斂財富或奢侈。(D)錯，史書沒有「吹捧」他們，而是揭露。", "skill": "例證題先問：作者舉這兩個人，是要證明哪一句論點？找到論點，原因就出來了。"}, {"n": 23, "qtype": "單選", "stem": "依上文推斷，文中＿＿處最適合填入下列哪一個句子？", "options": {"A": "虛實真偽在乎心", "B": "為學其病在貪逸", "C": "成事在理不在勢", "D": "性也情也善惡混"}, "answer": "A", "explain": "空格前引「誠於此者形於彼」（內在真誠會表現在外），空格後是「無不見乎迹」（都會在行跡上顯露），中間要填「內心的真假」。(A)正確，「人之虛實真偽在乎心，無不見乎迹」，心裡的真假一定會從行為露出來。(B)錯，談求學毛病，和名實無關。(C)錯，談做事靠道理不靠權勢，接不上「見乎迹」。(D)錯，談人性善惡，與全文的真偽主題無關。", "skill": "填空題前後文各抓一個關鍵詞（形於彼、見乎迹），答案要能同時接上兩邊。"}, {"n": 24, "qtype": "單選", "stem": "依據上文，以下選項何者與作者的觀點最為接近？", "options": {"A": "賞不加於無功，罰不加於無罪", "B": "善為吏者樹德，不善者則樹怨", "C": "功不可以虛成，名不可以偽立", "D": "明者因時而變，知者隨時而制"}, "answer": "C", "explain": "作者反覆強調：名聲要靠真誠，作假終會被揭穿，「以一偽喪百誠」。(C)正確，功業不能憑空得來、名聲不能靠作假建立，正是全文觀點。(A)錯，談賞罰公平，是治理原則。(B)錯，談當官施德或結怨。(D)錯，談順應時勢變通，與真偽無關。", "skill": "找觀點相近的句子時，把全文濃縮成一個關鍵詞（這篇是「名實相符」），再挑出講同一件事的選項。"}], "difficulty": "中", "label": "107二技", "year": 107, "kind": "二技"}, {"id": "et107-25", "exam": "et107", "nums": [25, 26, 27], "form": "題組", "img": "img/et107-25.png", "source": "《史記‧淮陰侯列傳》", "author": "司馬遷", "genre": "史傳人物", "types": ["人物情感", "文意推論", "主旨寓意"], "passage": "（韓）信數與蕭何語，何奇之。至南鄭，諸將行道亡者數十人，信度何等已數言上，上不我用，即亡。何聞信亡，不及以聞，自追之。人有言上曰：「丞相何亡。」上大怒，如失左右手。居一二日，何來謁上，上且怒且喜，罵何曰：「若亡，何也？」何曰：「臣不敢亡也，臣追亡者。」上曰：「若所追者誰？」何曰：「韓信也。」上復罵曰：「諸將亡者以十數，公無所追；追信，詐也。」何曰：「諸將易得耳。至如信者，國士無雙。王必欲長王漢中，無所事信；必欲爭天下，非信無所與計事者。顧王策安所決耳。」王曰：「吾亦欲東耳，安能鬱鬱久居此乎？」何曰：「王計必欲東，能用信，信即留；不能用，信終亡耳。」王曰：「吾為公以為將。」何曰：「雖為將，信必不留。」王曰：「以為大將。」何曰：「幸甚。」", "translation": "韓信多次和蕭何談話，蕭何覺得他很不平凡。到了南鄭，半路逃跑的將領有幾十人，韓信估計蕭何等人已經多次向漢王推薦過自己，漢王還是不重用，就也逃走了。蕭何聽說韓信逃走，來不及報告，親自去追。有人告訴漢王：「丞相蕭何逃走了。」漢王大怒，像失去了左右手。過了一兩天，蕭何回來拜見，漢王又氣又喜，罵他：「你逃跑，為什麼？」蕭何說：「我不敢逃，我是去追逃跑的人。」漢王問：「你追的是誰？」蕭何說：「韓信。」漢王又罵：「逃走的將領數以十計，你一個都不追；追韓信，是騙人的。」蕭何說：「那些將領很容易得到。至於韓信，是全國獨一無二的人才。大王如果只想長久在漢中稱王，用不著韓信；如果一定要爭天下，除了韓信沒有人能和您商量大事。就看大王的打算怎麼決定了。」漢王說：「我也想向東發展，怎能悶悶不樂地長久待在這裡？」蕭何說：「大王決心向東，能重用韓信，他就會留下；不能重用，他終究還是會走。」漢王說：「我看在你的面子上讓他當將軍。」蕭何說：「就算當將軍，韓信也一定不會留下。」漢王說：「那就讓他當大將。」蕭何說：「太好了。」", "keywords": [{"w": "奇之", "m": "認為他不平凡"}, {"w": "度", "m": "估計"}, {"w": "國士無雙", "m": "國內獨一無二的人才"}, {"w": "顧", "m": "只是、但看"}, {"w": "幸甚", "m": "太好了"}], "questions": [{"n": 25, "qtype": "單選", "stem": "閱讀上文，若要根據文中情節設計一款電玩遊戲，以下名稱何者最為恰當？", "options": {"A": "亂世英雄輓歌", "B": "武林風雲再起", "C": "王將青雲之路", "D": "三國爭雄奇謀"}, "answer": "C", "explain": "故事主線是韓信從不被重用、逃跑，到被蕭何追回、拜為大將，一路「青雲直上」。(C)正確，「王將青雲之路」點出漢王與大將、仕途高升。(A)錯，「輓歌」是哀悼，故事結局是被重用，不是悲劇。(B)錯，這是楚漢相爭的朝廷故事，不是江湖武林。(D)錯，時代是秦末楚漢，不是三國。", "skill": "幫故事下標題時，先抓「開頭狀態→結尾狀態」的變化，標題要能涵蓋這個轉折。"}, {"n": 26, "qtype": "單選", "stem": "承上題，若要根據上文內容設計電玩遊戲之人物——蕭何，下列何者最符合文中蕭何的形象？", "options": {"A": "性格：優柔寡斷；特長：耐心循循善誘；作風：謹小慎微", "B": "性格：擇善固執；特長：善於發掘人才；作風：思慮縝密", "C": "性格：積極大膽；特長：領導統御才能；作風：猜疑多忌", "D": "性格：唯我獨尊；特長：喜怒變換自如；作風：不諳人情"}, "answer": "B", "explain": "蕭何看出韓信是「國士無雙」，不顧可能被誤會而連夜去追，回來後一步步說服漢王，堅持要給「大將」才罷休。(B)正確：擇善固執、善於發掘人才、分析局勢周密。(A)錯，他「不及以聞，自追之」，行動果斷，不是優柔寡斷。(C)錯，「猜疑多忌」是漢王的反應（以為他逃跑、說他騙人），不是蕭何。(D)錯，「喜怒變換」「且怒且喜」說的是漢王；蕭何很懂得揣摩人心。", "skill": "人物形象題要分清楚：每個形容詞是在說誰？把「且怒且喜」這類描寫對回主詞，就不會張冠李戴。"}, {"n": 27, "qtype": "單選", "stem": "若此一電玩遊戲設有四道關卡，依文中內容，請問在哪一道關卡向劉邦勸諫，最能使劉邦重用韓信統領全軍？", "options": {"A": "第一關：信數與蕭何語，何奇之", "B": "第二關：信度何等已數言上，上不我用", "C": "第三關：何曰：「臣不敢亡也，臣追亡者。」", "D": "第四關：何曰：「必欲爭天下，非信無所與計事者。」"}, "answer": "D", "explain": "劉邦真正被打動，是蕭何把「用不用韓信」和「能不能爭天下」綁在一起。(D)正確，「必欲爭天下，非信無所與計事者」直接扣住劉邦想東進的野心，之後劉邦才一路從「將」升到「大將」。(A)錯，這只是蕭何私下欣賞韓信，還沒向劉邦進言。(B)錯，這時推薦無效，韓信因此逃走。(C)錯，這句只是解釋自己沒逃，劉邦反而罵他騙人。", "skill": "說服成功的關鍵句，通常是把對方最在意的目標（劉邦想爭天下）和自己的主張連在一起的那句。"}], "difficulty": "易", "label": "107二技", "year": 107, "kind": "二技"}, {"id": "et107-28", "exam": "et107", "nums": [28, 29, 30], "form": "題組", "img": "img/et107-28.png", "source": "陶淵明〈桃花源記〉、柳宗元〈始得西山宴遊記〉", "author": "陶淵明、柳宗元", "genre": "山水遊記", "types": ["比較閱讀", "主旨寓意", "文意推論"], "passage": "（一）晉太元中，武陵人，捕魚為業。緣溪行，忘路之遠近。忽逢桃花林，夾岸數百步，中無雜樹，芳草鮮美，落英繽紛。漁人甚異之。復前行，欲窮其林。林盡水源，便得一山。山有小口，彷彿若有光。便捨船，從口入。初極狹，纔通人；復行數十步，豁然開朗。土地平曠，屋舍儼然。有良田、美池、桑、竹之屬，阡陌交通，雞犬相聞。其中往來種作，男女衣著，悉如外人；黃髮垂髫，並怡然自樂。\n（二）今年九月二十八日，因坐法華西亭，望西山，始指異之。遂命僕過湘江，緣染溪，斫榛莽，焚茅茷，窮山之高而止。攀援而登，箕踞而遨，則凡數州之土壤，皆在衽席之下。其高下之勢，岈然洼然，若垤若穴，尺寸千里，攢蹙累積，莫得遯隱。縈青繚白，外與天際，四望如一。然後知是山之特出，不與培塿為類。悠悠乎與灝氣俱，而莫得其涯；洋洋乎與造物者遊，而不知其所窮。", "translation": "（一）東晉太元年間，有個武陵人以捕魚為生。他沿著溪流划船，忘了走了多遠。忽然遇到一片桃花林，夾著兩岸長達數百步，中間沒有別的樹，芳草鮮美，落花紛紛。漁人覺得很奇怪，繼續往前，想走到林子盡頭。林子在溪水源頭結束，就看到一座山，山上有個小洞口，隱約好像有光。他就下船從洞口進去。起初非常狹窄，只能讓一個人通過；又走了幾十步，忽然開闊明亮。土地平坦寬廣，房屋整整齊齊，有肥沃的田、美麗的池塘和桑樹竹子之類，田間小路交錯相通，到處聽得到雞鳴狗叫。在裡面來往耕作的人，男女穿著都和外面的人一樣；老人小孩都安閒快樂。\n（二）今年九月二十八日，我坐在法華寺西亭，遠望西山，才指著它覺得奇特。於是叫僕人渡過湘江，沿著染溪，砍掉雜亂的樹叢，燒掉茂密的茅草，一直爬到山的最高處才停下。攀爬上去後，伸開兩腿隨意坐著遊賞，附近幾州的土地都在我的坐席底下。地勢高低起伏，有的像山谷、有的像窪地，像蟻丘、像洞穴，千里遠的景物縮成一寸一尺，聚集堆疊，沒有一樣能躲藏起來。青山白水互相環繞，向外與天相接，四面看去都一樣。這才知道這座山特別突出，和那些小土丘不是同一類。我的心胸悠悠然與天地大氣合在一起，找不到邊際；廣大無邊地與造物者同遊，不知道盡頭在哪裡。", "keywords": [{"w": "緣", "m": "沿著"}, {"w": "窮", "m": "走到盡頭"}, {"w": "儼然", "m": "整齊的樣子"}, {"w": "黃髮垂髫", "m": "老人和小孩"}, {"w": "箕踞", "m": "兩腿伸開而坐，隨意自在"}, {"w": "培塿", "m": "小土丘"}, {"w": "灝氣", "m": "天地間的大氣"}], "questions": [{"n": 28, "qtype": "單選", "stem": "綜合上文，就兩段文字之內容推斷共同的主題最適合的是：", "options": {"A": "日常生活體驗", "B": "鄉野古蹟巡禮", "C": "身心慢活成長", "D": "超塵秘境訪尋"}, "answer": "D", "explain": "兩篇都是「發現一個不平凡的地方」：漁人意外闖入與世隔絕的桃花源；柳宗元費力開路登上「特出」的西山，感受與天地同遊。(D)正確，都是尋訪超脫塵世的祕境。(A)錯，兩者都不是日常經驗，而是奇遇。(B)錯，沒有寫古蹟。(C)錯，重點不在慢活或成長。", "skill": "比較閱讀先找兩篇的「共同動作」（都在找、都覺得「異」），再挑能概括兩邊的選項。"}, {"n": 29, "qtype": "單選", "stem": "綜合上文，兩段文字共同表現出何種特色？", "options": {"A": "著重描寫建築景觀", "B": "人與自然關係和諧", "C": "以人物刻畫為主體", "D": "抒發物換星移之感"}, "answer": "B", "explain": "(B)正確，桃花源的人「往來種作」「怡然自樂」，在田園中安居；柳宗元登頂後「與灝氣俱」「與造物者遊」，人與天地合一。(A)錯，桃花源只寫一句「屋舍儼然」，西山根本沒寫建築。(C)錯，兩篇重點都在景物與環境，不在刻畫某個人物。(D)錯，沒有感嘆時代變遷、人事已非。", "skill": "「共同特色」要兩篇都有才算，只在其中一篇出現的特徵直接刪去。"}, {"n": 30, "qtype": "單選", "stem": "綜合上文，下列哪一個景觀的描述最恰當？", "options": {"A": "武陵泛舟驚險刺激，美不勝收", "B": "法華西亭位居西山，氣象萬千", "C": "桃源幽境土地平曠，出入方便", "D": "西山特異居高臨下，視野極佳"}, "answer": "D", "explain": "(D)正確，「凡數州之土壤，皆在衽席之下」「是山之特出」，可見西山高聳、視野遼闊。(A)錯，漁人是悠閒「緣溪行」，沒有驚險。(B)錯，作者是坐在法華西亭「望」西山，西亭不在西山上。(C)錯，入口「初極狹，纔通人」，一點都不方便。", "skill": "景物描述題逐一回原文核對位置與狀態，注意「望」和「在」、「平曠」和「狹窄」這類細節陷阱。"}], "difficulty": "易", "label": "107二技", "year": 107, "kind": "二技"}, {"id": "et108-01", "exam": "et108", "nums": [1], "form": "單題", "img": "img/et108-01.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)室靡棄物，家無閒人／石崇以奢靡誇人　(B)凡百元首，承天景命／朝而往，暮而歸，四時之景不同　(C)蓋亭之所見，南北百里，東西一舍／唐浮圖慧褒始舍於其址　(D)如今人方為刀俎，我為魚肉，何辭為／我從去年辭帝京，謫居臥病潯陽城", "translation": "(A)屋裡沒有被丟棄的東西，家中沒有閒著的人／石崇以奢侈向人誇耀。(B)歷代君主承受上天偉大的使命／早上去、傍晚回，四季的景色各不相同。(C)從亭上望去，南北一百里，東西三十里／唐代和尚慧褒開始在這裡築屋居住。(D)現在人家是刀和砧板，我們是魚和肉，還告辭什麼呢／我從去年離開京城，貶官住在潯陽，臥病在床。", "keywords": [{"w": "靡", "m": "無／奢侈"}, {"w": "景", "m": "大／景色"}, {"w": "舍", "m": "三十里／築舍居住"}, {"w": "辭", "m": "辭別、離開"}], "questions": [{"n": 1, "qtype": "單選", "stem": "下列各組「」內的詞語，何者意義最相近？", "options": {"A": "室「靡」棄物，家無閒人／石崇以奢「靡」誇人", "B": "凡百元首，承天「景」命／朝而往，暮而歸，四時之「景」不同", "C": "蓋亭之所見，南北百里，東西一「舍」／唐浮圖慧褒始「舍」於其址", "D": "如今人方為刀俎，我為魚肉，何「辭」為／我從去年「辭」帝京，謫居臥病潯陽城"}, "answer": "D", "explain": "(D)正確，《史記‧鴻門宴》「何辭為」是何必告辭；白居易〈琵琶行〉「辭帝京」是離開京城，兩者都是「告別、離開」。(A)錯，歸有光〈先妣事略〉「室靡棄物」的「靡」是沒有，司馬光〈訓儉示康〉「奢靡」的「靡」是奢侈。(B)錯，魏徵〈諫太宗十思疏〉「景命」的「景」是大，歐陽脩〈醉翁亭記〉的「景」是景色。(C)錯，蘇轍〈黃州快哉亭記〉的「一舍」是三十里，王安石〈遊褒禪山記〉的「舍」是動詞，在那裡築屋居住。", "skill": "一詞多義題，先判斷是名詞、動詞還是否定詞，詞性一不同就可直接刪掉。"}], "difficulty": "中", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-02", "exam": "et108", "nums": [2], "form": "單題", "img": "img/et108-02.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)袁紹有姿貌威容，能折節下士，士多附之　(B)飯疏食，飲水，曲肱而枕之，樂亦在其中矣　(C)提刀而立，為之四顧，為之躊躇滿志，善刀而藏之　(D)修守戰之備，外連橫而鬥諸侯，於是秦人拱手而取西河之外", "translation": "(A)袁紹相貌威武，能放下身段禮待士人，士人多來歸附。(B)吃粗飯、喝白水，彎起手臂當枕頭，快樂也就在其中。(C)提著刀站起來，為此環顧四周，為此心滿意足，把刀擦乾淨收好。(D)整頓防守作戰的裝備，對外聯合各國使諸侯互鬥，於是秦人不費力就取得了西河以外的土地。", "keywords": [{"w": "折節", "m": "降低身分，謙虛待人"}, {"w": "曲肱", "m": "彎著手臂"}, {"w": "躊躇滿志", "m": "從容自得、心滿意足"}, {"w": "拱手", "m": "兩手相合，形容毫不費力"}], "questions": [{"n": 2, "qtype": "單選", "stem": "下列選項「」內的詞語，何者具有「謙讓虛心」的意思？", "options": {"A": "袁紹有姿貌威容，能「折節」下士，士多附之", "B": "飯疏食，飲水，「曲肱」而枕之，樂亦在其中矣", "C": "提刀而立，為之四顧，為之「躊躇」滿志，善刀而藏之", "D": "修守戰之備，外連橫而鬥諸侯，於是秦人「拱手」而取西河之外"}, "answer": "A", "explain": "(A)正確，「折節下士」是把自己的身段折下來，謙虛地對待士人，所以「士多附之」。(B)錯，《論語‧述而》的「曲肱」是彎著手臂當枕頭，寫安貧樂道。(C)錯，《莊子‧養生主》的「躊躇滿志」是得意滿足，和謙虛相反。(D)錯，賈誼〈過秦論〉的「拱手」是形容毫不費力。", "skill": "看到「下士」「禮賢」「虛己」這類搭配，前面的動作多半就是謙虛的表現。"}], "difficulty": "易", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-03", "exam": "et108", "nums": [3], "form": "單題", "img": "img/et108-03.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)緣染溪，斫榛莽，焚茅茷，窮山之高而止　(B)晉太元中，武陵人，捕魚為業。緣溪行，忘路之遠近　(C)月出於東山之上，徘徊於斗牛之間。白露橫江，水光接天　(D)舳艫千里，旌旗蔽空，釃酒臨江，橫槊賦詩，固一世之雄也", "translation": "(A)沿著染溪，砍掉雜亂的樹叢，燒掉茂密的茅草，一直到山頂才停。(B)東晉太元年間，有個武陵人以捕魚為業，沿著溪流前進，忘了路程遠近。(C)月亮從東山升起，在斗宿和牛宿之間徘徊；白茫茫的水氣籠罩江面，水光與天相接。(D)船隻首尾相接延綿千里，旌旗遮蔽天空，對著江水斟酒，橫著長矛吟詩，本來是一代英雄啊。", "keywords": [{"w": "斫", "m": "砍"}, {"w": "緣", "m": "沿著"}, {"w": "橫", "m": "橫貫、瀰漫"}, {"w": "釃", "m": "斟酒"}], "questions": [{"n": 3, "qtype": "單選", "stem": "下列選項「」內的詞語，何者解釋正確？", "options": {"A": "緣染溪，「斫」榛莽，焚茅茷，窮山之高而止：種植", "B": "晉太元中，武陵人，捕魚為業。「緣」溪行，忘路之遠近：前往", "C": "月出於東山之上，徘徊於斗牛之間。白露「橫」江，水光接天：混雜", "D": "舳艫千里，旌旗蔽空，「釃」酒臨江，橫槊賦詩，固一世之雄也：斟注"}, "answer": "D", "explain": "(D)正確，蘇軾〈赤壁賦〉「釃酒臨江」是對著江斟酒。(A)錯，柳宗元〈始得西山宴遊記〉「斫榛莽」是砍除雜樹，和後面「焚茅茷」一樣在開路，不是種植。(B)錯，〈桃花源記〉「緣溪行」是沿著溪走。(C)錯，〈赤壁賦〉「白露橫江」是白茫茫水氣橫貫江面，不是混雜。", "skill": "字義題可用上下文同類動作互證：「斫榛莽」和「焚茅茷」並列，兩個都是清除。"}], "difficulty": "易", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-04", "exam": "et108", "nums": [4], "form": "單題", "img": "img/et108-04.png", "source": "《應諧錄》", "author": "劉元卿", "genre": "寓言故事", "types": ["主旨寓意"], "passage": "昔人有癢，令其子索之，三索而三弗中。令其妻索之，五索而五弗中也。其人怒曰：「妻子內我者，而胡難我？」乃自引手一搔而癢絕。何則？癢者，人之所自知也。自知而搔，寧弗中乎！", "translation": "從前有人身上發癢，叫兒子幫他抓，抓了三次都沒抓對地方；叫妻子抓，抓了五次也沒抓中。這人生氣地說：「妻子、兒子是最親近我的人，為什麼這樣為難我？」於是自己伸手一抓，就不癢了。為什麼呢？癢在哪裡，只有自己最清楚。自己知道再自己抓，哪有抓不中的呢！", "keywords": [{"w": "索", "m": "尋找（癢處）"}, {"w": "內", "m": "親近"}, {"w": "胡", "m": "為什麼"}, {"w": "寧", "m": "難道"}], "questions": [{"n": 4, "qtype": "單選", "stem": "閱讀下文，最適合詮釋此文題旨的選項是：", "options": {"A": "人應無事不學，無時不學", "B": "人應反求諸己，才能切中要點", "C": "人應忍人所不能忍，為人所不能為", "D": "人應以齊家為本，家和自能萬事皆興"}, "answer": "B", "explain": "結論是「癢者，人之所自知也」：只有自己最知道問題在哪，靠自己才能解決。(B)正確，反求諸己就能切中要害。(A)錯，故事沒有談學習。(C)錯，不是在講忍耐。(D)錯，雖然出現妻子兒子，但重點不在家庭和睦，反而說家人幫不上忙。", "skill": "寓言題最後的「何則？……」是作者自己的解釋，直接抓那一句就是寓意。"}], "difficulty": "易", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-05", "exam": "et108", "nums": [5], "form": "單題", "img": "img/et108-05.png", "source": "唐寅〈桃花庵歌〉", "author": "唐寅", "genre": "古典詩詞曲", "types": ["詩詞賞析", "句意理解"], "passage": "車塵馬足貴者趣，酒盞花枝貧者緣。若將富貴比貧者，一在平地一在天。若將貧賤比車馬，他得驅馳我得閒。別人笑我忒瘋癲，我笑他人看不穿。不見五陵豪傑墓，無花無酒鋤作田。", "translation": "車馬奔走揚塵是富貴人的樂趣，酒杯和花枝是窮人的緣分。如果拿富貴和貧窮相比，一個在地上一個在天上；如果拿貧賤和車馬勞碌相比，他們得奔波，我卻得清閒。別人笑我太瘋癲，我笑別人看不透。你看不到嗎？五陵那些豪傑的墳墓，如今沒有花也沒有酒，被人鋤平當成田地了。", "keywords": [{"w": "趣", "m": "樂趣、追求"}, {"w": "忒", "m": "太"}, {"w": "五陵", "m": "漢代五座帝陵，附近多住豪門貴族"}], "questions": [{"n": 5, "qtype": "單選", "stem": "閱讀下詩，與劃線處句子意義最接近的選項是：", "options": {"A": "眾人皆醉，何不餔其糟而啜其醨", "B": "大江東去，浪淘盡，千古風流人物", "C": "莊生曉夢迷蝴蝶，望帝春心託杜鵑", "D": "以儉立名，以侈自敗者多矣，不可遍數"}, "answer": "B", "explain": "劃線句「不見五陵豪傑墓，無花無酒鋤作田」：再風光的豪傑，死後墳墓也被剷平當田，富貴終歸塵土。(B)正確，蘇軾〈念奴嬌‧赤壁懷古〉說大江把千古英雄人物都沖刷殆盡，同樣感嘆英雄終將消逝。(A)錯，《楚辭‧漁父》勸人隨波逐流、與世推移。(C)錯，李商隱〈錦瑟〉寫人生如夢與哀怨寄託。(D)錯，司馬光〈訓儉示康〉談節儉與奢侈的成敗。", "skill": "找意思相近的詩句，先把劃線句濃縮成一句白話（這裡是「英雄終歸塵土」），再一個個比對。"}], "difficulty": "中", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-06", "exam": "et108", "nums": [6], "form": "單題", "img": "img/et108-06.png", "source": "秦觀〈鵲橋仙〉", "author": "秦觀", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文化常識"], "passage": "纖雲弄巧，飛星傳恨，銀漢迢迢暗度，金風玉露一相逢，便勝卻人間無數。", "translation": "纖細的雲彩變幻出巧妙的圖樣，流星傳遞著離別的愁恨，牛郎織女悄悄渡過遙遠的銀河。在秋風白露的時節相逢一次，就勝過人間無數次的相聚。", "keywords": [{"w": "銀漢", "m": "銀河"}, {"w": "金風", "m": "秋風（五行中秋屬金）"}, {"w": "玉露", "m": "秋天的白露"}], "questions": [{"n": 6, "qtype": "單選", "stem": "下列詞作為秦觀〈鵲橋仙〉，其中所描寫的季節，出現在下列哪一句成語的□中？", "options": {"A": "妙手回□", "B": "炎炎□日", "C": "多事之□", "D": "臘盡□殘"}, "answer": "C", "explain": "這闋詞寫七夕牛郎織女相會，七夕在農曆七月，屬秋天；「金風」是秋風（秋屬金），「玉露」是秋露。(C)正確，「多事之秋」填「秋」。(A)錯，「妙手回春」是春。(B)錯，「炎炎夏日」是夏。(D)錯，「臘盡冬殘」是冬。", "skill": "古詩詞的季節線索：金風、玉露、七夕、鴻雁屬秋；記住「秋屬金」就能秒判。"}], "difficulty": "易", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-07", "exam": "et108", "nums": [7], "form": "單題", "img": "img/et108-07.png", "source": "袁中道〈陳無異寄生篇序〉", "author": "袁中道", "genre": "書信序跋", "types": ["主旨寓意", "文意推論"], "passage": "士生而處豐厚，安居飽食，毫不沾風霜冰雪之氣，即有所成，去凡品不遠。惟夫計窮慮迫，困衡之極，有志者往往淬勵磨練，琢為美器。", "translation": "讀書人一生下來就生活富足，安穩地住、吃得飽，一點都沒受過風霜冰雪的磨難，就算有些成就，也和平凡的人差不多。只有在走投無路、憂慮緊迫、困苦到極點的時候，有志氣的人往往能自我砥礪磨練，把自己雕琢成優秀的人才。", "keywords": [{"w": "凡品", "m": "平凡的人"}, {"w": "困衡", "m": "困於心、衡於慮，極度困苦"}, {"w": "淬勵", "m": "磨練、激勵"}, {"w": "美器", "m": "優秀的人才"}], "questions": [{"n": 7, "qtype": "單選", "stem": "閱讀下文，合乎該段文字內容的選項是︰", "options": {"A": "富貴僅能一時，處世唯應修心", "B": "困阨造就卓越，安逸導致平凡", "C": "智者隱藏鋒芒，君子惡名過實", "D": "為學應先立志，立志方能窮理"}, "answer": "B", "explain": "文章兩段對比：安逸的人「去凡品不遠」，困苦中的有志者「琢為美器」。(B)正確，前半對應困苦造就人才，後半對應安逸導致平凡。(A)錯，文中沒說富貴短暫，也沒談修心。(C)錯，沒有談隱藏鋒芒或名實相符。(D)錯，雖然提到「有志者」，但重點是逆境磨練，不是立志窮理。", "skill": "文章用兩種人對比時，答案通常是把兩邊結果都說出來的選項。"}], "difficulty": "易", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-08", "exam": "et108", "nums": [8], "form": "單題", "img": "img/et108-08.png", "source": "《墨子‧非攻上》", "author": "墨子", "genre": "說理議論", "types": ["文意推論", "句意理解"], "passage": "殺一人謂之不義，必有一死罪矣，若以此說往，殺十人十重不義，必有十死罪矣；殺百人百重不義，必有百死罪矣。當此，天下之君子皆知而非之，謂之不義。今至大為不義攻國，則弗知非，從而譽之，謂之義，情不知其不義也，故書其言以遺後世。若知其不義也，夫奚說書其不義以遺後世哉？今有人於此，少見黑曰黑，多見黑曰白，則以此人不知白黑之辯矣。", "translation": "殺一個人叫做不義，一定要判一個死罪。照這個道理推下去，殺十個人就是十倍的不義，一定有十個死罪；殺一百人就是百倍的不義，一定有一百個死罪。這種事，天下的君子都知道要譴責，說它不義。可是現在做了最大的不義——攻打別國，卻不知道譴責，反而跟著稱讚，說它是義，實在是不知道它不義，所以還把稱讚的話寫下來留給後代。如果知道它不義，又怎麼會把不義的事寫下來留給後代呢？假如有個人，看到一點黑說是黑，看到很多黑卻說是白，那就可以說這個人分不清黑白了。", "keywords": [{"w": "非", "m": "指責、反對"}, {"w": "譽", "m": "稱讚"}, {"w": "情", "m": "實在、確實"}, {"w": "奚說", "m": "有什麼理由"}, {"w": "辯", "m": "同「辨」，分辨"}], "questions": [{"n": 8, "qtype": "單選", "stem": "閱讀下文，合乎該段文字內容的選項是：", "options": {"A": "殺害他人性命與發動戰爭攻打他國罪惡相同，應加以指責", "B": "非常特殊的情況下，發動戰爭也是實現正義的不得已作為", "C": "「少見黑曰黑，多見黑曰白」指人應增廣見聞以正確判斷", "D": "所謂不義，和殺害他人數目成正比關係，故量刑亦應倍增"}, "answer": "A", "explain": "墨子的推理：殺一人是不義，攻打別國就是更大規模的殺人，同樣是不義，大家卻反而稱讚。(A)正確，兩者本質都是不義的殺人，都應該指責。(B)錯，墨子主張「非攻」，全文沒有替戰爭找正當理由。(C)錯，這句是比喻世人小惡知道反對、大惡反而稱讚，是「是非不分」，不是叫人增廣見聞。(D)錯，「十重不義」只是推理的過程，墨子要說的是攻國的不義，不是在討論量刑制度。", "skill": "說理文用「由小推大」論證時，答案要抓住最後被推出的結論，而不是推理中間的步驟。"}], "difficulty": "中", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-09", "exam": "et108", "nums": [9], "form": "單題", "img": "img/et108-09.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["文意推論", "詩詞賞析"], "passage": "(A)十年寒窗無人問，一舉成名天下知　(B)今朝有酒今朝醉，明日愁來明日愁　(C)古來聖賢皆寂寞，惟有飲者留其名　(D)人生代代無窮已，江月年年只相似", "translation": "(A)苦讀十年沒人過問，一考上就天下聞名。(B)今天有酒今天就喝醉，明天的煩惱明天再說。(C)自古以來聖賢都很寂寞，只有會喝酒的人留下名聲。(D)人一代一代無窮無盡地延續，江上的月亮年年看起來都一樣。", "keywords": [{"w": "無窮已", "m": "沒有窮盡"}], "questions": [{"n": 9, "qtype": "單選", "stem": "閱讀下文，與文章意旨最接近的選項是：", "options": {"A": "十年寒窗無人問，一舉成名天下知", "B": "今朝有酒今朝醉，明日愁來明日愁", "C": "古來聖賢皆寂寞，惟有飲者留其名", "D": "人生代代無窮已，江月年年只相似"}, "answer": "D", "explain": "隱地的文章說：萬物都會由新變舊、生老病死，一代代人看到的太陽月亮山水卻都一樣，生命不停地兜圈子。(D)正確，張若虛〈春江花月夜〉說人一代代更替，江月年年相似，正是「人事更替、自然恆常」。(A)錯，講苦讀後成名。(B)錯，羅隱〈自遣〉講及時行樂、不管明天。(C)錯，李白〈將進酒〉借酒抒發懷才不遇。", "skill": "白話文配古詩句的題目，先把文章意旨濃縮成兩個對比詞（人會變／景不變），再找同樣有這組對比的詩句。"}], "difficulty": "易", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-10", "exam": "et108", "nums": [10], "form": "單題", "img": "img/et108-10.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["文意推論", "詩詞賞析"], "passage": "(A)復行數十步，豁然開朗。土地平曠，屋舍儼然　(B)君自故鄉來，應知故鄉事。來日綺窗前，寒梅著花未　(C)孟夏草木長，繞屋樹扶疏。眾鳥欣有託，吾亦愛吾廬　(D)今大道既隱，天下為家，各親其親，各子其子，貨力為己", "translation": "(A)又走了幾十步，忽然開闊明亮，土地平坦寬廣，房屋整齊。(B)你從故鄉來，應該知道故鄉的事：你來的那天，我家雕花窗前的寒梅開花了沒有？(C)初夏草木生長，屋子四周樹木枝葉茂密。鳥兒高興有地方棲息，我也喜愛我的小屋。(D)現在大道已經消失，天下成為一家一姓所有，人們只親愛自己的親人，只疼愛自己的孩子，財物和勞力都只為自己。", "keywords": [{"w": "扶疏", "m": "枝葉繁茂的樣子"}, {"w": "託", "m": "寄託、棲身之處"}, {"w": "廬", "m": "簡陋的房屋"}], "questions": [{"n": 10, "qtype": "單選", "stem": "閱讀下文，與文章意旨最接近的選項是：", "options": {"A": "復行數十步，豁然開朗。土地平曠，屋舍儼然", "B": "君自故鄉來，應知故鄉事。來日綺窗前，寒梅著花未", "C": "孟夏草木長，繞屋樹扶疏。眾鳥欣有託，吾亦愛吾廬", "D": "今大道既隱，天下為家，各親其親，各子其子，貨力為己"}, "answer": "C", "explain": "林文月說：有一個家或房間圍住我們，讓人覺得屬於這個世界，又有抽離外界的安全感。(C)正確，陶淵明〈讀山海經〉說鳥兒高興有巢可託，我也愛我的小屋，正是對「家」的歸屬與安心。(A)錯，〈桃花源記〉描寫發現世外桃源的景象，不是自己的家。(B)錯，王維〈雜詩〉是思念故鄉，重點在思鄉，不是擁有一個安身之處。(D)錯，《禮記‧禮運》描寫小康社會人人自私，「天下為家」不是指住家。", "skill": "小心字面陷阱：選項出現「家」「屋舍」不一定對，要看它講的是不是同一種感受。"}], "difficulty": "中", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-15", "exam": "et108", "nums": [15], "form": "單題", "img": "img/et108-15.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "(A)月景尤不可言，花態柳情，山容水意，別是一種趣味　(B)庭中通南北為一，迨諸父異爨，內外多置小門牆，往往而是　(C)夫臺灣固海上之荒島爾。篳路藍縷，以啟山林，至於今是賴　(D)三顧臣於草廬之中，諮臣以當世之事，由是感激，遂許先帝以驅馳", "translation": "(A)月下的景色更是說不出的美，花的姿態、柳的情致、山的容貌、水的意趣，別有一種趣味。(B)庭院原本南北相通連成一片，等到伯父叔父們分家，裡外加了許多小門和牆，到處都是這樣。(C)臺灣本來是海上的荒島，先人駕著柴車、穿著破衣開墾山林，到今天還仰賴這些。(D)先帝三次到草屋拜訪我，向我詢問天下大事，因此我感動奮發，就答應為先帝奔走效力。", "keywords": [{"w": "是", "m": "是（判斷）／此、這樣（代詞）"}, {"w": "異爨", "m": "分灶吃飯，指分家"}, {"w": "由是", "m": "因此"}], "questions": [{"n": 15, "qtype": "單選", "stem": "下列選項中的「是」，何者不是代名詞的用法？", "options": {"A": "月景尤不可言，花態柳情，山容水意，別「是」一種趣味", "B": "庭中通南北為一，迨諸父異爨，內外多置小門牆，往往而「是」", "C": "夫臺灣固海上之荒島爾。篳路藍縷，以啟山林，至於今「是」賴", "D": "三顧臣於草廬之中，諮臣以當世之事，由「是」感激，遂許先帝以驅馳"}, "answer": "A", "explain": "代名詞的「是」等於「此、這」。(A)正確，袁宏道〈晚遊六橋待月記〉「別是一種趣味」的「是」就是現代的「是」，判斷用法，不是代詞。(B)錯，歸有光〈項脊軒志〉「往往而是」是到處都是「這樣」，代詞。(C)錯，連橫〈臺灣通史序〉「至於今是賴」是「至今賴是」，仰賴「這些」，代詞前置。(D)錯，諸葛亮〈出師表〉「由是」是「因為這樣」，代詞。", "skill": "把「是」換成「這」讀讀看，讀得通是代詞；換了不通、只能當「是」用的，就是判斷用法。"}], "difficulty": "中", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-16", "exam": "et108", "nums": [16], "form": "單題", "img": "img/et108-16.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["寫作手法"], "passage": "(A)君子居必擇鄉，遊必就士，所以防邪僻，而近中正也　(B)泰山不讓土壤，故能成其大，河海不擇細流，故能就其深　(C)使老有所終，壯有所用，幼有所長，矜寡孤獨廢疾者皆有所養　(D)伯牙絕絃于鍾期，仲尼覆醢于子路，痛知音之難遇，傷門人之莫逮", "translation": "(A)君子居住一定選擇好的鄉里，交遊一定接近有德的人，用來防止邪僻、親近中正。(B)泰山不拒絕泥土，所以能成就它的高大；河海不挑選細流，所以能成就它的深廣。(C)讓老人得到善終，壯年人有所任用，小孩得到養育，鰥寡孤獨和身體殘疾的人都能得到照顧。(D)伯牙因鍾子期死去而斷弦不再彈琴，孔子因子路死去而倒掉肉醬，是痛心知音難遇、哀傷弟子無人能及。", "keywords": [{"w": "錯綜", "m": "刻意交錯詞句順序的修辭"}, {"w": "覆醢", "m": "倒掉肉醬"}, {"w": "莫逮", "m": "沒有人比得上"}], "questions": [{"n": 16, "qtype": "單選", "stem": "錯綜修辭是將上下詞句調動次序，使其安排得參差不齊。如：「句讀之不知，惑之不解，或師焉，或不焉」語次可以解為「句讀之不知，或師焉；惑之不解，或不焉」的錯綜形式。下列何者也使用錯綜修辭？", "options": {"A": "君子居必擇鄉，遊必就士，所以防邪僻，而近中正也", "B": "泰山不讓土壤，故能成其大，河海不擇細流，故能就其深", "C": "使老有所終，壯有所用，幼有所長，矜寡孤獨廢疾者皆有所養", "D": "伯牙絕絃于鍾期，仲尼覆醢于子路，痛知音之難遇，傷門人之莫逮"}, "answer": "D", "explain": "錯綜的特徵是兩組事情先並列，再把各自的結果放在後面，要「拆開重組」才順。(D)正確，曹丕〈與吳質書〉可還原為「伯牙絕絃于鍾期，痛知音之難遇；仲尼覆醢于子路，傷門人之莫逮」。(A)錯，《荀子‧勸學》句子順序本來就通順，是平鋪直敘。(B)錯，李斯〈諫逐客書〉是兩組結構相同、各自完整的對偶句。(C)錯，《禮記‧禮運》是一連串「有所…」的排比。", "skill": "判斷錯綜：試著把句子拆成「A1＋B1；A2＋B2」重排，重排後更順的就是錯綜。"}], "difficulty": "中", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-17", "exam": "et108", "nums": [17], "form": "單題", "img": "img/et108-17.png", "source": "應用文（對聯）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "(A)畫屏射雀成雙璧，桂樹鳴鸞慶百年　(B)里有仁風春日永，家餘德澤福星明　(C)桃花人面紅相映，楊柳春風綠更多　(D)天上人間齊煥彩，椿庭萱舍共稱觴", "translation": "(A)在畫屏上射中孔雀眼得到佳偶，月中桂樹、鸞鳥和鳴，慶賀百年好合。(B)鄉里有仁德的風氣，春日長久；家中留有德澤，福星照耀。(C)桃花與人面相映而紅，楊柳在春風裡更綠。(D)天上人間一齊煥發光彩，父母雙全一同舉杯祝壽。", "keywords": [{"w": "射雀", "m": "雀屏中選，指選婿成婚"}, {"w": "椿庭萱舍", "m": "椿代表父親，萱代表母親"}, {"w": "稱觴", "m": "舉杯祝壽"}], "questions": [{"n": 17, "qtype": "單選", "stem": "下列對聯均有祝賀之意，何者最適用於祝賀長輩壽誕？", "options": {"A": "畫屏射雀成雙璧，桂樹鳴鸞慶百年", "B": "里有仁風春日永，家餘德澤福星明", "C": "桃花人面紅相映，楊柳春風綠更多", "D": "天上人間齊煥彩，椿庭萱舍共稱觴"}, "answer": "D", "explain": "(D)正確，「椿庭萱舍」指父親母親，「稱觴」是舉杯祝壽，適合祝長輩（雙親）壽誕。(A)錯，「射雀」用雀屏中選的典故，「成雙璧」「鳴鸞」都是祝賀新婚。(B)錯，稱頌鄉里仁風與家族德澤，是一般春聯或稱頌家門的吉祥話，看不出壽誕。(C)錯，桃花、人面、楊柳春風，多用於新婚或春景，不是祝壽。", "skill": "對聯題找關鍵字：椿萱、松鶴、南山、稱觴是壽；雀屏、鸞鳳、百年是婚；德澤、仁風多為通用頌詞。"}], "difficulty": "易", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-22", "exam": "et108", "nums": [22, 23, 24], "form": "題組", "img": "img/et108-22.png", "source": "連橫《臺灣通史‧宗教志‧景教》（改寫）", "author": "連橫", "genre": "史傳人物", "types": ["文意推論", "句意理解"], "passage": "英國長老教會派牧師馬雅谷來臺。雅谷精刀圭術，以藥醫人，而傳其教，設教堂於府治（臺南府城）看西街，從者頗多。仇教者肆為蜚語以排擠之。有司慮禍，照會英領事請移口岸。雅谷乃去之旗後，別設教堂於鳳治（鳳山縣城），聚徒傳播，相安無事。始，城中兒每遺失，或言洋人潛殺，剖其腦製藥。雅谷固業醫，縣役貓角命人盜童骸埋之室中，計欲以實其事。翌日，知縣凌定國往勘，觀者如堵。貓角又力言。掘地及室，見白骨，信之。拘長嚴鞫，不服。下之獄，以狀白郡，並照會英領事。領事以為誣，馳稟駐京公使，與總理衙門交涉，各執一辭。乃命興泉永道曾獻德偕廈門英領事吉普理渡臺會辨，諗為貓角所為，定其罪，案始結。", "translation": "英國長老教會派牧師馬雅谷（馬雅各）來臺灣。雅谷精通醫術，用藥替人治病，同時傳教，在臺南府城看西街設了教堂，信徒很多。仇視洋教的人到處散布謠言排擠他。官府怕出事，照會英國領事請他遷到通商口岸。雅谷就到旗後，另外在鳳山縣城設教堂，招收信徒傳教，相安無事。當初，城裡常有小孩失蹤，有人說是洋人偷偷殺了他們，剖開腦袋做藥。雅谷本來就是醫生，縣衙差役貓角派人偷了孩童的骸骨埋在他屋裡，想坐實這件事。隔天，知縣凌定國去查看，圍觀的人多得像一堵牆。貓角又極力指控。挖開屋內地面，看到白骨，知縣就相信了。把（教會）負責人抓來嚴厲審問，對方不認罪，就關進牢裡，把案情報告府城，並照會英國領事。領事認為是誣陷，急忙報告駐北京公使，和總理衙門交涉，雙方各說各話。朝廷就派興泉永道曾獻德和廈門英國領事吉普理一起渡海來臺會審，查明是貓角做的，判了他的罪，案子才了結。", "keywords": [{"w": "刀圭術", "m": "醫術"}, {"w": "蜚語", "m": "流言"}, {"w": "照會", "m": "外交上的正式通知"}, {"w": "觀者如堵", "m": "圍觀的人多得像一面牆"}, {"w": "鞫", "m": "審問"}, {"w": "諗", "m": "知悉、查明"}], "questions": [{"n": 22, "qtype": "單選", "stem": "依據上文，下列關於馬雅谷事件的敘述，何者正確？", "options": {"A": "因醫療糾紛而下獄", "B": "透過外交手段平反", "C": "勾結縣役製造偽藥", "D": "受到廈門領事誣陷"}, "answer": "B", "explain": "(B)正確，英國領事認為是誣陷，報告駐京公使和總理衙門交涉，最後派官員與英領事會審才查明真相，是靠外交途徑平反。(A)錯，被抓是因為貓角栽贓「殺童製藥」，不是醫療糾紛。(C)錯，誣陷他的正是縣役貓角，雅谷沒有勾結。(D)錯，廈門英領事吉普理是來會審、幫忙查明真相的人，誣陷者是貓角。", "skill": "事件題先畫出人物關係：誰陷害、誰被害、誰來救，選項把角色對調就是陷阱。"}, {"n": 23, "qtype": "單選", "stem": "從上文中可知，事件中的馬雅谷曾出現在哪些地方？(甲)泉州(乙)廈門(丙)臺南(丁)鳳山(戊)旗後", "options": {"A": "(甲)(乙)(丁)", "B": "(乙)(丙)(丁)", "C": "(乙)(丙)(戊)", "D": "(丙)(丁)(戊)"}, "answer": "D", "explain": "雅谷先在府治（臺南）看西街設教堂，再「去之旗後」，又在鳳治（鳳山）設教堂，所以是臺南、鳳山、旗後。(D)正確。泉州、廈門只出現在官名「興泉永道」與「廈門英領事」，是別人的職稱或駐地，雅谷沒去過，所以(A)(B)(C)都錯。", "skill": "地名題要分辨：地名是「人物去過的地方」還是只是「官名、職稱」的一部分。"}, {"n": 24, "qtype": "單選", "stem": "依據上文，下列敘述何者正確？", "options": {"A": "西醫確實以兒童的腦煉藥物", "B": "臺灣社會對於西醫理解有限", "C": "牧師經常介入臺灣政治鬥爭", "D": "臺灣人對待外國牧師皆和善"}, "answer": "B", "explain": "(B)正確，小孩失蹤就傳說洋人剖腦製藥，而且知縣看到白骨就相信，可見當時社會對西醫很陌生、容易誤解。(A)錯，那是謠言，最後證實是貓角栽贓。(C)錯，文中牧師只是行醫傳教，沒有介入政治。(D)錯，有「仇教者肆為蜚語以排擠之」，不是都很和善。", "skill": "「皆」「確實」「經常」這種絕對詞，要原文有明確證據才能選。"}], "difficulty": "中", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-25", "exam": "et108", "nums": [25, 26, 27], "form": "題組", "img": "img/et108-25.png", "source": "司空圖〈移雨神〉", "author": "司空圖", "genre": "說理議論", "types": ["文意推論", "主旨寓意", "人物情感"], "passage": "夏滿不雨，民前後走神所，刳羊豕而跪乞者凡三，而後得請。民大喜，且將報祀，愚獨以為惑。何者？天以神乳育百苗穀，必時既豐，然後民相率以勞神之勤，於是而祀焉。今始吝其施，以愁疲民，是神怠天之職也。必希民之求而遂應，是神玩天之權也。既應而俾民輸怨於天，歸惠於己，是神攘天之德也。推怨何以為義？利腥膻之饋，何以為仁？怠天下之事，何以為敬？蔑是數者，何以為神？……噫！天不可終謾，民不可久侮。竊為神危之，奈何！", "translation": "整個夏天都不下雨，百姓先後跑到神廟，殺羊殺豬跪著祈求，前後三次，才得到降雨。百姓非常高興，還準備祭祀報答，只有我覺得疑惑。為什麼呢？上天派神來養育百穀，應該按時降雨讓收成豐盛之後，百姓才一起慰勞神的辛勞而祭祀它。現在神一開始就吝於施雨，讓疲困的百姓發愁，這是神怠忽上天交付的職責。一定要等百姓來求才回應，這是神玩弄上天的權柄。回應之後又讓百姓把怨恨推給上天、把恩惠歸給自己，這是神竊取上天的功德。推卸怨恨怎能算義？貪圖祭品的葷腥，怎能算仁？怠忽天下的事，怎能算敬？沒有這幾樣德行，憑什麼算是神？……唉！上天不能永遠被欺瞞，百姓不能長久被欺侮。我私下替這位神感到危險，該怎麼辦呢！", "keywords": [{"w": "刳", "m": "剖開、宰殺"}, {"w": "得請", "m": "請求得到允許，指終於下雨"}, {"w": "勞", "m": "慰勞"}, {"w": "希", "m": "等待、迎合"}, {"w": "攘", "m": "竊取"}, {"w": "謾", "m": "欺騙"}], "questions": [{"n": 25, "qtype": "單選", "stem": "依據上文，關於祈雨過程與結果的敘述，何者正確？", "options": {"A": "百姓多次祈求後，終於天降甘霖", "B": "等待到夏天結束之後，自然降雨", "C": "太守虔誠祈求降雨，連月行齋戒", "D": "天地自有意志，降雨實無關人事"}, "answer": "A", "explain": "(A)正確，「刳羊豕而跪乞者凡三，而後得請」，百姓祈求三次後才下雨。(B)錯，「夏滿不雨」是整個夏天都不下雨，接著百姓去求才下，不是自然降雨。(C)錯，祈雨的是百姓，文中沒有太守，也沒有齋戒。(D)錯，作者認為雨是神該按天意施予的，問題在神怠職，並沒有說降雨和人事無關。", "skill": "過程題用「誰、做了什麼、結果」三要素去核對，文中沒有出現的人物直接刪。"}, {"n": 26, "qtype": "單選", "stem": "依據上文，作者對雨神的態度是：", "options": {"A": "信者恆信", "B": "存而不論", "C": "質疑挑戰", "D": "敬之畏之"}, "answer": "C", "explain": "作者在大家歡喜答謝時「獨以為惑」，接著連用「何以為義？何以為仁？何以為敬？何以為神？」一連串質問，最後還說「竊為神危之」。(C)正確，是質疑、挑戰雨神。(A)錯，作者不是盲目相信。(B)錯，他不但談了，還大力批評。(D)錯，口氣是責備，不是敬畏。", "skill": "態度題看語氣詞與句式：連續反問句通常代表質疑、批判。"}, {"n": 27, "qtype": "單選", "stem": "下列何者與作者所認知天、雨神、民之關係最為符合？", "options": {"A": "神可自由改變上天意志，任意施為", "B": "雨神之地位雖高，仍須為百姓造福", "C": "天、民、神互相制衡，民不能無天", "D": "民需積福造福，敬畏鬼神以合天道"}, "answer": "B", "explain": "作者認為：天派神來養育百穀，神的職責就是按時降雨造福百姓，不能怠職、玩權、搶功。(B)正確。(A)錯，作者批評的正是神「玩天之權」，認為神不該任意而為。(C)錯，文中是「天→神→民」的上下職責關係，沒有互相制衡的說法。(D)錯，作者沒有要百姓敬畏鬼神，反而替百姓抱不平。", "skill": "關係題先畫出文中的權力方向（天派神、神服務民），再看選項有沒有把方向弄反。"}], "difficulty": "中", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-28", "exam": "et108", "nums": [28, 29, 30], "form": "題組", "img": "img/et108-28.png", "source": "《左傳‧燭之武退秦師》", "author": "左丘明（相傳）", "genre": "史傳人物", "types": ["比較閱讀", "人物情感", "文意推論"], "passage": "晉侯、秦伯圍鄭，以其無禮於晉，且貳於楚也。晉軍函陵，秦軍氾南。佚之狐言於鄭伯曰：「國危矣！若使燭之武見秦君，師必退。」公從之。辭曰：「臣之壯也，猶不如人。今老矣，無能為也已。」公曰：「吾不能早用子，今急而求子，是寡人之過也。然鄭亡，子亦有不利焉。」許之，夜縋而出。見秦伯曰：「秦晉圍鄭，鄭既知亡矣。若亡鄭而有益於君，敢以煩執事。越國以鄙遠，君知其難也。焉用亡鄭以陪鄰？鄰之厚，君之薄也。若舍鄭以為東道主，行李之往來，共其乏困，君亦無所害。且君嘗為晉君賜矣，許君焦、瑕，朝濟而夕設版焉，君之所知也。夫晉，何厭之有？既東封鄭，又欲肆其西封，若不闕秦，將焉取之？闕秦以利晉，唯君圖之。」秦伯說，與鄭人盟。使杞子、逢孫、楊孫戍之，乃還。", "translation": "晉文公、秦穆公包圍鄭國，因為鄭國曾對晉國無禮，而且依附晉國的同時又親近楚國。晉軍駐紮在函陵，秦軍駐紮在氾水南邊。佚之狐對鄭文公說：「國家危險了！如果派燭之武去見秦君，秦軍一定會撤退。」鄭文公聽從了。燭之武推辭說：「我壯年時都比不上別人，現在老了，什麼也做不了。」鄭文公說：「我沒有早點重用您，現在危急了才來求您，是我的過錯。但是鄭國滅亡了，對您也不利啊。」燭之武就答應了，夜裡用繩子從城牆吊下去。見到秦穆公說：「秦晉圍鄭，鄭國已經知道要亡了。如果滅了鄭國對您有好處，那就勞煩您的部下動手吧。可是越過別的國家把遠方的土地當作邊邑，您知道這很難。何必滅了鄭國去增加鄰國（晉）的土地呢？鄰國變強，就是您變弱。如果留下鄭國當作東方路上的主人，秦國使者往來，鄭國供給他們缺少的東西，對您也沒有壞處。況且您曾經對晉君有恩，他答應割焦、瑕兩城給您，結果早上渡河回國，晚上就築牆防備您，這是您知道的。晉國哪有滿足的時候？既然向東把鄭國當成疆界，又會想擴張西邊的疆界，如果不削減秦國，要從哪裡取得土地呢？削弱秦國來讓晉國得利，希望您好好考慮。」秦穆公聽了很高興，和鄭國結盟，派杞子、逢孫、楊孫駐守鄭國，就撤兵回去了。", "keywords": [{"w": "貳", "m": "有二心"}, {"w": "縋", "m": "用繩子吊下"}, {"w": "鄙遠", "m": "把遠地當作邊邑"}, {"w": "陪", "m": "增加"}, {"w": "東道主", "m": "東方路上的主人，招待過客者"}, {"w": "行李", "m": "外交使者"}, {"w": "厭", "m": "滿足"}, {"w": "闕", "m": "削減、損害"}], "questions": [{"n": 28, "qtype": "單選", "stem": "依據(甲)、(乙)兩文，對(甲)文中的角色進行分析，下列何者完全正確？", "options": {"A": "鄭伯以認錯讓步的態度來降低燭之武怨恨，並試圖說服燭之武出馬", "B": "燭之武回應鄭伯的話，嘗試將人與情緒問題分開，以誠懇求取同情", "C": "晉君屬於立場強硬的鷹派客戶，當年殺雞取卵豪奪強取以削弱秦國", "D": "佚之狐預期燭之武說秦必能成，實因洞察燭之武與秦伯有深厚交情"}, "answer": "A", "explain": "(A)正確，鄭伯先說「是寡人之過也」認錯，降低燭之武的不滿，再說「鄭亡，子亦有不利焉」把雙方利益綁在一起，成功說服他。(B)錯，燭之武說「今老矣，無能為也已」，是帶著怨氣推辭，並不是把情緒分開、也不是求同情。(C)錯，文中晉君是答應給秦國焦、瑕卻反悔設防，是失信，不是「殺雞取卵」去削弱秦國。(D)錯，文中沒有提到燭之武和秦伯有交情。", "skill": "跨文本分析時，每個選項都要回到原文找那個角色真正說過的話，再套用另一篇的概念。"}, {"n": 29, "qtype": "單選", "stem": "(甲)文中，燭之武對秦伯所說的一段話，沒有使用(乙)文哪一項雙贏談判要點？", "options": {"A": "抽離主觀情緒", "B": "關注利益，而非立場", "C": "找出對彼此有利方案", "D": "堅持用客觀標準"}, "answer": "D", "explain": "燭之武整段話都在冷靜分析秦國的利害。(D)正確，他沒有引用法律或專家意見之類的客觀標準。(A)有用，他不哭求、不訴苦，冷靜就事論事。(B)有用，「焉用亡鄭以陪鄰？鄰之厚，君之薄也」，談的是秦國的實際利益，而非秦晉同盟的立場。(C)有用，「舍鄭以為東道主」對秦鄭雙方都有好處。", "skill": "「沒有使用」題逐一找證據，能在原文找到對應句的刪掉，剩下找不到的就是答案。"}, {"n": 30, "qtype": "單選", "stem": "若燭之武以簡報的方式站在秦國立場向秦伯提案，文中「舍鄭以為東道主，行李之往來，共其乏困」應該放在表格中的哪個位子？", "options": {"A": "甲", "B": "乙", "C": "丙", "D": "丁"}, "answer": "C", "explain": "留下鄭國當東方的主人，秦國使者到東方往來時，鄭國會供應物資，這是發生在秦國「境外」的事，而且對秦國「有利」，所以放在丙。(C)正確。(A)(B)錯，這不是秦國內部的事。(D)錯，這對秦國是好處，不是壞處。", "skill": "表格分類題分兩步判斷：先判斷「內／外」，再判斷「利／弊」，交叉就是答案。"}], "difficulty": "中", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-31", "exam": "et108", "nums": [31, 32, 33], "form": "題組", "img": "img/et108-31.png", "source": "《列子‧周穆王》", "author": "列子（列禦寇）", "genre": "寓言故事", "types": ["文意推論", "人物情感", "主旨寓意"], "passage": "宋陽里華子，中年病忘，朝取而夕忘，夕與而朝忘；在塗則忘行，在室則忘坐；今不識先，後不識今。闔室毒之。謁史而卜之，弗占；謁巫而禱之，弗禁；謁醫而攻之，弗已。魯有儒生，自媒能治之，華子之妻子以居產之半請其方。儒生曰：「吾試化其心，變其慮，庶幾其瘳乎！」於是試露之而求衣，饑之而求食，幽之而求明。儒生欣然告其子曰：「疾可已也。然吾之方密，傳世不以告人。試屏左右，獨與居室七日。」從之。莫知其所施為也，而積年之疾，一朝都除。華子既悟，迺大怒，黜妻罰子，操戈逐儒生。宋人執而問其以。華子曰：「曩吾忘也，蕩蕩然不覺天地之有無。今頓識既往，數十年來存亡、得失、哀樂、好惡，擾擾萬緒起矣。吾恐將來之存亡得失哀樂好惡之亂吾心如此也，須臾之忘，可復得乎？」", "translation": "宋國陽里有個叫華子的人，中年得了健忘症，早上拿的東西晚上就忘了，晚上給人的東西早上就忘了；走在路上忘了要走，待在屋裡忘了要坐；現在不記得以前，以後又不記得現在。全家都為此苦惱。請史官占卜，占不出結果；請巫師祈禱，止不住病；請醫生治療，治不好。魯國有個儒生，自我推薦說能治，華子的妻兒拿出一半家產求他的藥方。儒生說：「我試著改變他的心思和念頭，也許能治好吧！」於是試著讓他光著身子，他會找衣服穿；讓他挨餓，他會找東西吃；把他關在暗處，他會找光亮。儒生高興地告訴華子的兒子：「病可以治好。但我的方法是祕密，世代相傳不告訴別人。請讓旁人都退開，我單獨和他在屋裡住七天。」家人照辦了。沒人知道他做了什麼，而多年的病一下子全好了。華子清醒後，竟然大怒，趕走妻子、處罰兒子，拿著戈追趕儒生。宋國人抓住他，問他原因。華子說：「從前我健忘時，心中空蕩蕩的，連天地存不存在都感覺不到。現在一下子記起過去，幾十年來的生死、得失、悲喜、愛恨，千頭萬緒紛紛湧上心頭。我怕將來這些生死得失悲喜愛恨還會這樣擾亂我的心，片刻的遺忘，還能再得到嗎？」", "keywords": [{"w": "病忘", "m": "患健忘症"}, {"w": "毒", "m": "苦惱、憂慮"}, {"w": "攻", "m": "治療"}, {"w": "已", "m": "痊癒、停止"}, {"w": "自媒", "m": "自我推薦"}, {"w": "瘳", "m": "病癒"}, {"w": "曩", "m": "從前"}], "questions": [{"n": 31, "qtype": "單選", "stem": "文中華子「謁史而卜之，弗占；謁巫而禱之，弗禁；謁醫而攻之，弗已」，與下列何者的描述最接近？", "options": {"A": "隨遇而安，諱疾忌醫", "B": "苦思良方，一籌莫展", "C": "三折其肱，自悟解方", "D": "久病成醫，應接不暇"}, "answer": "B", "explain": "占卜、祈禱、看醫生，各種辦法都試了，卻都沒效。(B)正確，到處找好方法卻一點辦法也沒有。(A)錯，家人積極求醫，不是隨遇而安，更不是避諱看醫生。(C)錯，「三折肱」是經驗多而成良醫，華子並沒有自己找到解方，是儒生治好的。(D)錯，華子沒有變成醫生，文中也沒有「忙不過來」的意思。", "skill": "排比句「謁…弗…」連用三次，重點在三個「弗」：全部失敗。"}, {"n": 32, "qtype": "單選", "stem": "依據上文，下列關於儒生的敘述，何者正確？", "options": {"A": "因華子妻子誠意請託，故承諾免收取費用為華子治病", "B": "專精藥理，以為只要施用藥物即可醫治華子積年之疾", "C": "使用變化心術之秘方，與華子獨處七日而治癒其病症", "D": "擅長養氣吐納之術，指示華子需居於幽暗處獨自調養"}, "answer": "C", "explain": "(C)正確，儒生說要「化其心，變其慮」，又要求「獨與居室七日」，結果「積年之疾，一朝都除」。(A)錯，妻兒是用「居產之半」來請他，並非免費。(B)錯，他的方法是改變心思，文中沒有用藥。(D)錯，「幽之而求明」是測試華子會不會找光亮，不是叫他住在暗處調養；文中也沒提吐納。", "skill": "人物做法題，把人物說的話（化其心、變其慮）當成關鍵證據，選項說法要與它一致。"}, {"n": 33, "qtype": "單選", "stem": "依據上文，華子「大怒，黜妻罰子，操戈逐儒生」的可能原因為何？", "options": {"A": "以重陷人世間紛擾為憂", "B": "受到儒生花言巧語誆騙", "C": "治療健忘之症曠日廢時", "D": "長年服藥副作用太強烈"}, "answer": "A", "explain": "華子自己說：忘記時心裡空蕩自在，現在想起幾十年的得失哀樂，「擾擾萬緒起矣」，害怕以後還會這樣亂心。(A)正確，他是因為又掉回人世的煩惱而生氣。(B)錯，儒生真的治好了他，沒有騙他。(C)錯，只用了七天，不算久。(D)錯，文中根本沒有服藥。", "skill": "人物行為的原因，通常就在他自己接下來的那段話裡，直接找「吾恐…」這類心聲。"}], "difficulty": "中", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-42", "exam": "et108", "nums": [42], "form": "單題", "img": "img/et108-42.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "典故出處"], "passage": "(A)狡兔有三窟，僅得免其死耳。今君有一窟，未得高枕而臥也　(B)暮春之初，會于會稽山陰之蘭亭，修禊事也。群賢畢至，少長咸集　(C)先世避秦時亂，率妻子、邑人來此絕境，不復出焉，遂與外人間隔　(D)因摸地上刑械，作投擊勢。史噤不敢發聲，趨而出，後常流涕述其事", "translation": "(A)狡猾的兔子有三個洞穴，才能免於一死；現在您只有一個洞，還不能高枕無憂。(B)暮春三月初，在會稽山陰的蘭亭聚會，舉行修禊之事。許多賢士都來了，年長年少的都聚在一起。(C)祖先為了躲避秦時的戰亂，帶著妻子兒女和同鄉來到這個與世隔絕的地方，不再出去，於是和外界的人隔絕了。(D)左公就摸著地上的刑具，做出要投擊的樣子。史可法閉口不敢出聲，快步走出去，後來常流著淚說這件事。", "keywords": [{"w": "窟", "m": "洞穴"}, {"w": "僅", "m": "才、只"}, {"w": "修禊", "m": "古代三月上巳在水邊洗濯去災的習俗"}, {"w": "噤", "m": "閉口不說話"}, {"w": "趨", "m": "快步走"}], "questions": [{"n": 42, "qtype": "單選", "stem": "下列文句，何者用字完全正確？", "options": {"A": "狡兔有三窿，謹得免其死耳。今君有一窿，未得高枕而臥也", "B": "暮春之初，會于會稽山陰之蘭亭，休契事也。群賢必至，少長咸集", "C": "先世避秦時亂，率妻子、邑人來此絕境，不復出焉，遂與外人間隔", "D": "因摸地上刑械，作投擊勢。史敬不敢發聲，區而出，後常流涕述其事"}, "answer": "C", "explain": "這題考課文原句的字形，先回想課文怎麼寫。(C)正確，陶淵明〈桃花源記〉原句一字不差。(A)錯，《戰國策‧馮諼客孟嘗君》應為「狡兔有三『窟』，『僅』得免其死耳」。(B)錯，王羲之〈蘭亭集序〉應為「『修禊』事也」，「群賢『畢』至」也寫錯。(D)錯，方苞〈左忠毅公軼事〉應為「史『噤』不敢發聲，『趨』而出」。", "skill": "文言字形題，從意思反推字形：洞穴是「窟」、只是「僅」、閉嘴是「噤」、快走是「趨」。"}], "difficulty": "中", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et108-47", "exam": "et108", "nums": [47], "form": "單題", "img": "img/et108-47.png", "source": "諸葛亮〈出師表〉", "author": "諸葛亮", "genre": "書信序跋", "types": ["人物情感", "句意理解"], "passage": "臣本布衣，躬耕於南陽，苟全性命於亂世，不求聞達於諸侯。先帝不以臣卑鄙，猥自枉屈，三顧臣於草廬之中，諮臣以當世之事，由是感激，遂許先帝以驅馳。", "translation": "我本來是個平民，在南陽親自耕田，只求在亂世中保全性命，不想在諸侯間求取名聲。先帝不嫌我身分低微、見識淺陋，降低身分委屈自己，三次到草屋拜訪我，向我詢問天下大事，我因此感動奮發，就答應為先帝奔走效力。", "keywords": [{"w": "布衣", "m": "平民"}, {"w": "聞達", "m": "有名聲、地位顯達"}, {"w": "卑鄙", "m": "身分低微、見識淺陋"}, {"w": "猥自枉屈", "m": "降低身分、委屈自己"}, {"w": "驅馳", "m": "奔走效勞"}], "questions": [{"n": 47, "qtype": "單選", "stem": "老師要求同學使用成語形容下文〈出師表〉中的諸葛亮與劉備，下列何者的答案最貼切？", "options": {"A": "周同學：諸葛亮可謂「因禍得福」，劉備可謂「推心置腹」", "B": "魯同學：諸葛亮可謂「肝膽楚越」，劉備可謂「契若金蘭」", "C": "孫同學：諸葛亮可謂「披褐懷珠」，劉備可謂「禮賢下士」", "D": "曹同學：諸葛亮可謂「名山事業」，劉備可謂「探驪得珠」"}, "answer": "C", "explain": "諸葛亮是隱居的平民卻有大才；劉備放下身段三顧茅廬。(C)正確，「披褐懷珠」是穿粗布衣卻懷藏寶玉，比喻有才而不顯露；「禮賢下士」是尊重賢才、謙恭待人。(A)錯，諸葛亮沒有遭禍，談不上因禍得福。(B)錯，「肝膽楚越」指本來親近的人變得疏遠，不合；「契若金蘭」是交情深厚，此時兩人才剛認識。(D)錯，「名山事業」指不朽的著作；「探驪得珠」比喻文章抓到要旨，都和文意無關。", "skill": "成語套人物時，先用白話描述人物的處境（有才隱居、放下身段求才），再找成語的本義是否吻合。"}], "difficulty": "中", "label": "108二技", "year": 108, "kind": "二技"}, {"id": "et109-11", "exam": "et109", "nums": [11], "form": "單題", "img": "img/et109-11.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "甲：古之「學者」為己，今之學者為人／研究文章的歷史或理論的是文學家，是「學者」\n乙：身體面龐雖怯弱不勝，卻有一段自然的「風流」態度／吾愛孟夫子，「風流」天下聞\n丙：既與梁通好，「行李」往來，公私贈遺，一無所受／若舍鄭以為東道主，「行李」之往來，共其乏困\n丁：惟我「下流」二三小臣，穢損清風，愧于前人／以水性「下流」，當從下而泄，故治水當從下為始", "translation": "甲：古代求學的人是為了充實自己，現代求學的人是為了給別人看／研究文章歷史或理論的是文學家，是學者（研究學問的專家）。\n乙：身體臉龐雖然柔弱，卻有一種自然的風韻姿態／我敬愛孟夫子，他的風度文采天下聞名。\n丙：和梁國友好往來後，使者來來往往，公私饋贈一概不收／如果留下鄭國作為東方路上的主人，使者往來時，鄭國可供應他們缺少的物資。\n丁：只有我們這些地位低下的幾個小臣，玷汙了清明的風氣，愧對前人／因為水性往低處流，應該從下游排洩，所以治水要從下游開始。", "keywords": [{"w": "學者", "m": "求學的人／研究學問的專家"}, {"w": "風流", "m": "風度、風韻"}, {"w": "行李", "m": "使者"}, {"w": "下流", "m": "地位低下（自謙）／往低處流"}], "questions": [{"n": 11, "qtype": "單選", "stem": "下列文句「」中的詞語，哪幾組的意思前後相同？", "options": {"A": "甲乙", "B": "乙丙", "C": "丙丁", "D": "甲丁"}, "answer": "B", "explain": "甲不同：《論語‧憲問》「古之學者」是求學的人；後句是現代說的研究學問的專家。乙相同：《紅樓夢》寫林黛玉「自然的風流態度」，李白〈贈孟浩然〉「風流天下聞」，都指風度、風韻。丙相同：兩句的「行李」都是往來的使者（後句出自《左傳‧燭之武退秦師》）。丁不同：前句「下流」是地位低下，自謙之詞；後句是水往低處流。所以答案是乙丙，(B)正確，(A)(C)(D)都含錯誤組合。", "skill": "古今異義的詞（學者、行李、下流）是常考點，遇到就先想「古代意思和現在一樣嗎」。"}], "difficulty": "中", "label": "109二技", "year": 109, "kind": "二技"}, {"id": "et109-12", "exam": "et109", "nums": [12], "form": "單題", "img": "img/et109-12.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "(A)臣家貧，客至無器皿、肴、果，故就酒家觴之　(B)多情應笑我，早生華髮。人生如夢，一尊還酹江月　(C)瑩玉杯，青玉斝，恁般樓臺正宜夏，都輸他沉李浮瓜　(D)射者中，弈者勝，觥籌交錯，起坐而喧嘩者，眾賓懽也", "translation": "(A)我家裡窮，客人來了沒有器皿、菜餚和水果，所以到酒店請他喝酒。(B)（神遊故國）多情的人應該會笑我早早長出白髮。人生像一場夢，還是舉起一杯酒祭灑江上的月亮吧。(C)晶瑩的玉杯、青玉的酒器，這樣的樓臺正適合夏天，都比不上他泡在涼水裡的李子和瓜。(D)投壺的人投中了，下棋的人贏了，酒杯和籌碼交錯，或起或坐大聲喧鬧的，是眾賓客在歡樂。", "keywords": [{"w": "觴", "m": "酒杯；作動詞時指請人喝酒"}, {"w": "尊", "m": "同「樽」，酒杯"}, {"w": "斝", "m": "古代盛酒的器具"}, {"w": "觥", "m": "酒杯"}], "questions": [{"n": 12, "qtype": "單選", "stem": "下列文句「」中的詞語意思皆為水酒容器，何者不是當名詞使用？", "options": {"A": "臣家貧，客至無器皿、肴、果，故就酒家「觴」之", "B": "多情應笑我，早生華髮。人生如夢，一「尊」還酹江月", "C": "瑩玉杯，青玉「斝」，恁般樓臺正宜夏，都輸他沉李浮瓜", "D": "射者中，弈者勝，「觥」籌交錯，起坐而喧嘩者，眾賓懽也"}, "answer": "A", "explain": "(A)正確，「觴之」後面接受詞「之」（客人），意思是「請他喝酒」，名詞當動詞用（轉品）。(B)錯，蘇軾〈念奴嬌‧赤壁懷古〉「一尊」是一杯酒，名詞。(C)錯，「青玉斝」和「瑩玉杯」並列，是酒器名詞。(D)錯，歐陽脩〈醉翁亭記〉「觥籌交錯」，觥是酒杯，名詞。", "skill": "名詞後面直接接「之」或其他受詞，通常就轉成動詞了。"}], "difficulty": "中", "label": "109二技", "year": 109, "kind": "二技"}, {"id": "et109-13", "exam": "et109", "nums": [13], "form": "單題", "img": "img/et109-13.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "(A)君子坦蕩蕩，小人長戚戚　(B)無惛惛之事者，無赫赫之功　(C)安能以身之察察，受物之汶汶者乎　(D)母孫二人更相為命，是以區區不能廢遠", "translation": "(A)君子心胸寬廣坦蕩，小人總是憂愁不安。(B)沒有專心致志地做事，就不會有顯赫的功績。(C)怎麼能讓自己清白的身體，去沾染外界的汙濁呢？(D)祖孫二人相依為命，所以我出於私心捨不得離開（祖母）遠去。", "keywords": [{"w": "戚戚", "m": "憂懼的樣子"}, {"w": "惛惛", "m": "專心致志"}, {"w": "察察", "m": "潔白、清白"}, {"w": "區區", "m": "自己的私情、真心"}], "questions": [{"n": 13, "qtype": "單選", "stem": "下列選項「」中的詞語，何者解釋正確？", "options": {"A": "君子坦蕩蕩，小人長「戚戚」：親暱", "B": "無「惛惛」之事者，無赫赫之功：專一", "C": "安能以身之「察察」，受物之汶汶者乎：高大", "D": "母孫二人更相為命，是以「區區」不能廢遠：辛苦"}, "answer": "B", "explain": "(B)正確，《荀子‧勸學》「惛惛」是專心致志，和後面「赫赫之功」相對。(A)錯，《論語‧述而》「戚戚」是憂愁不安，和「坦蕩蕩」相對，不是親暱。(C)錯，《楚辭‧漁父》「察察」是潔白，和「汶汶」（汙濁）相對，不是高大。(D)錯，李密〈陳情表〉「區區」是自己的一片私情，不是辛苦。", "skill": "疊字詞常和句中另一個詞成對比（坦蕩蕩／戚戚、察察／汶汶），從反義推回來最快。"}], "difficulty": "中", "label": "109二技", "year": 109, "kind": "二技"}, {"id": "et109-14", "exam": "et109", "nums": [14], "form": "單題", "img": "img/et109-14.png", "source": "《郁離子》", "author": "劉基", "genre": "寓言故事", "types": ["主旨寓意"], "passage": "莊子之齊，見餓人而哀之，餓者從而求食，莊子曰：「吾已不食七日矣。」餓者吁曰：「吾見過我者多矣，莫我哀也，哀我者惟夫子。向使夫子不不食，其能哀我乎？」", "translation": "莊子到齊國去，看到一個挨餓的人而同情他，餓的人就跟著向他討東西吃。莊子說：「我已經七天沒吃東西了。」餓的人嘆氣說：「我看到經過我身邊的人很多，沒有人同情我，同情我的只有您。假如您不是也沒飯吃，還會同情我嗎？」", "keywords": [{"w": "之", "m": "往、到"}, {"w": "哀", "m": "同情、憐憫"}, {"w": "吁", "m": "嘆氣"}, {"w": "向使", "m": "假如"}], "questions": [{"n": 14, "qtype": "單選", "stem": "閱讀下文，此篇故事的旨意在說明：", "options": {"A": "在上位者應與百姓齊心協力，以共謀幸福", "B": "因自身困頓而怨天尤人，反而得不到幫助", "C": "對於困病有切身體會，方能同情他人疾苦", "D": "倘使自己都不能吃飽，又如何能哀憐他人"}, "answer": "C", "explain": "關鍵是餓者的最後一句：「假如您不是也餓著，還會同情我嗎？」意思是只有自己嘗過挨餓的苦，才真正懂得同情。(C)正確。(A)錯，莊子不是在上位者，故事也沒講齊心協力。(B)錯，沒有人怨天尤人。(D)錯，故事正好相反：莊子自己沒吃飽，反而最能同情別人。", "skill": "寓言的寓意常藏在最後一句反問裡，把反問改成肯定句就是答案。"}], "difficulty": "易", "label": "109二技", "year": 109, "kind": "二技"}, {"id": "et109-15", "exam": "et109", "nums": [15], "form": "單題", "img": "img/et109-15.png", "source": "《列女傳‧魯黔婁妻》", "author": "劉向", "genre": "史傳人物", "types": ["人物情感", "主旨寓意"], "passage": "魯黔婁先生之妻也。先生死，曾子與門人往弔之。其妻出戶，曾子弔之。上堂，見先生之尸在牖下，枕墼席槀，縕袍不表，覆以布被，首足不盡斂。覆頭則足見，覆足則頭見。曾子曰：「邪引其被，則斂矣。」妻曰：「邪而有餘，不如正而不足也。先生以不邪之故，能至於此。生時不邪，死而邪之，非先生意也。」曾子不能應。", "translation": "這是魯國黔婁先生的妻子。黔婁死了，曾子和學生去弔唁。他的妻子出門迎接，曾子向她致哀。走上廳堂，看見黔婁的遺體放在窗下，枕著土磚、墊著草蓆，穿著沒有面子的舊棉袍，蓋著一條布被，頭和腳都蓋不全。蓋住頭就露出腳，蓋住腳就露出頭。曾子說：「把被子斜著拉，就蓋得住了。」妻子說：「斜著而有餘，不如正著而不夠。先生因為一生不偏邪，才能有今天的名聲。活著時不偏邪，死了卻讓他歪斜，這不是先生的心意。」曾子無話可答。", "keywords": [{"w": "弔", "m": "弔唁、慰問喪家"}, {"w": "牖", "m": "窗戶"}, {"w": "墼", "m": "未燒的土磚"}, {"w": "縕袍", "m": "用亂麻舊絮做的袍子"}, {"w": "斂", "m": "覆蓋、收殮"}, {"w": "邪", "m": "同「斜」，也指不正"}], "questions": [{"n": 15, "qtype": "單選", "stem": "下列選項，何者符合下文所述黔婁及黔婁之妻所共同表現的精神？", "options": {"A": "人貧智短，與世推移", "B": "清貧自持，通權達變", "C": "貧賤夫妻，百事皆哀", "D": "安貧樂道，守正不阿"}, "answer": "D", "explain": "黔婁死時窮到被子蓋不全，妻子仍堅持「邪而有餘，不如正而不足」，夫妻都甘於貧窮、堅守正直。(D)正確。(A)錯，他們窮而不改志，不是隨世俗改變。(B)前半對，但「通權達變」是懂得變通，妻子正好拒絕曾子變通的建議，所以錯。(C)錯，「貧賤夫妻百事哀」是貧窮夫妻事事悲哀，文中妻子態度堅定，不是哀嘆。", "skill": "四字對句的選項要前後都對才選；只對一半的（如B）是最常見的陷阱。"}], "difficulty": "易", "label": "109二技", "year": 109, "kind": "二技"}, {"id": "et109-16", "exam": "et109", "nums": [16], "form": "單題", "img": "img/et109-16.png", "source": "《幕學舉要》", "author": "萬維翰（清）", "genre": "說理議論", "types": ["句意理解", "文意推論"], "passage": "荒政難辦，不能有功，但求無過。須安撫之，不使哀鴻離散；控御之，不使烏合逞兇。", "translation": "救荒的政事很難辦，不能要求有功勞，只求不出差錯。必須安撫災民，不讓流離失所的人四處離散；也要管理控制，不讓臨時聚集的群眾逞兇作亂。", "keywords": [{"w": "荒政", "m": "救濟饑荒的政事"}, {"w": "哀鴻", "m": "哀鳴的鴻雁，比喻流離失所的災民"}, {"w": "控御", "m": "控制管理"}, {"w": "烏合", "m": "像烏鴉一樣臨時聚集，無組織的群眾"}], "questions": [{"n": 16, "qtype": "單選", "stem": "閱讀下文，依據文意選出正確的選項：", "options": {"A": "救災時應並重人民的安撫與管理", "B": "救災時須分散民眾以免難以控制", "C": "由官府救災則容易出現烏合之眾", "D": "由官府負責救災才能有功而無過"}, "answer": "A", "explain": "文中兩個「須」：一是安撫，二是控御。(A)正確，安撫和管理要並重。(B)錯，文中說「不使哀鴻離散」，是不要讓民眾離散，和「分散民眾」相反。(C)錯，文中是提醒不要讓烏合之眾逞兇，沒說官府救災會造成烏合之眾。(D)錯，原文說「不能有功，但求無過」，不是「有功而無過」。", "skill": "短文題直接抓並列的兩個動作（安撫之、控御之），選項要兩個都有。"}], "difficulty": "易", "label": "109二技", "year": 109, "kind": "二技"}, {"id": "et109-17", "exam": "et109", "nums": [17], "form": "單題", "img": "img/et109-17.png", "source": "曾敏行《獨醒雜志》", "author": "曾敏行", "genre": "筆記小品", "types": ["文意推論", "寫作手法"], "passage": "東安一士人喜畫，作鼠一軸，獻之邑令。令初不知愛，漫懸於壁。旦而過之，軸必墜地，屢懸屢墜。令怪之，黎明物色，軸在地，而貓蹲其旁，逮舉軸，則踉蹌逐之。以試群貓，莫不然者，於是始知其畫為逼真。", "translation": "東安有個讀書人喜歡畫畫，畫了一幅老鼠，送給縣令。縣令起初不懂得珍惜，隨便掛在牆上。每天早上經過，畫軸一定掉在地上，掛了又掉、掉了又掛。縣令覺得奇怪，天剛亮就去察看，畫軸在地上，一隻貓蹲在旁邊；等到把畫軸舉起來，貓就跌跌撞撞地追過去。拿別的貓來試，沒有一隻不是這樣，這才知道這幅畫畫得非常逼真。", "keywords": [{"w": "軸", "m": "卷軸，指一幅畫"}, {"w": "漫", "m": "隨便"}, {"w": "物色", "m": "察看、尋找"}, {"w": "逮", "m": "等到"}, {"w": "踉蹌", "m": "跌跌撞撞"}], "questions": [{"n": 17, "qtype": "單選", "stem": "閱讀下文，依據文意選出正確的選項：", "options": {"A": "縣令仔細審視此畫作後，旋即懸於牆上邀畫友共賞", "B": "作者以貓作為描述對象，間接強調此畫的栩栩如生", "C": "士人以鼠作為繪畫對象，為了表現老鼠怕貓之天性", "D": "畫家每天早上拾起畫軸，乃因不捨此畫被群貓破壞"}, "answer": "B", "explain": "全文沒有直接誇畫得好，而是寫貓每晚把畫撲下來、看到畫就追，用貓的反應證明畫很逼真。(B)正確，這是側面烘托（間接描寫）。(A)錯，縣令「初不知愛，漫懸於壁」，是隨便掛著，沒有仔細看或邀人共賞。(C)錯，士人只是喜歡畫畫，文中沒有說要表現老鼠怕貓。(D)錯，每天看到畫掉在地上的是縣令，不是畫家。", "skill": "看到「不直接寫A，而寫別人對A的反應」，就是側面描寫（烘托）。"}], "difficulty": "易", "label": "109二技", "year": 109, "kind": "二技"}, {"id": "et109-19", "exam": "et109", "nums": [19], "form": "單題", "img": "img/et109-19.png", "source": "綜合（多篇古文）", "author": "", "genre": "經典語錄", "types": ["文意推論", "句意理解"], "passage": "(A)盡信書，則不如無書　(B)言者所以在意，得意而忘言　(C)讀書貴能領悟，洞察言外之意　(D)落花水面皆文章，萬物靜觀皆自得", "translation": "(A)完全相信書上寫的，還不如沒有書。(B)語言是用來表達意思的，得到意思就可以忘掉語言。(C)讀書可貴的是能夠領悟，看出文字以外的意思。(D)落花流水都是天然的好文章，靜心觀察萬物，都能有所領會。", "keywords": [{"w": "盡信", "m": "完全相信"}, {"w": "得意忘言", "m": "領會意思後就不拘泥於言語"}, {"w": "言外之意", "m": "文字沒有直接說出的意思"}], "questions": [{"n": 19, "qtype": "單選", "stem": "閱讀下文，選出最接近文意的選項：", "options": {"A": "盡信書，則不如無書", "B": "言者所以在意，得意而忘言", "C": "讀書貴能領悟，洞察言外之意", "D": "落花水面皆文章，萬物靜觀皆自得"}, "answer": "C", "explain": "梁宜生說：好書一定有文字沒表達出來的部分，真正受用的就在那裡，要看見才算讀通。(C)正確，就是要領悟言外之意。(A)錯，《孟子》這句是說讀書不要盲目全信，重點在懷疑與判斷，不是言外之意。(B)錯，《莊子》這句是說懂了意思就可以忘掉語言，重點在不執著文字，不是去挖掘文字沒寫出的部分。(D)錯，是說從大自然中處處有所體會，談的是觀察萬物而非讀書。", "skill": "幾個選項都和「讀書、語言」有關時，要比對「重點動作」：原文是「看見沒寫出的」，不是「不全信」或「忘掉語言」。"}], "difficulty": "中", "label": "109二技", "year": 109, "kind": "二技"}, {"id": "et109-20", "exam": "et109", "nums": [20], "form": "單題", "img": "img/et109-20.png", "source": "綜合（多篇古文）", "author": "", "genre": "經典語錄", "types": ["文意推論", "句意理解"], "passage": "(A)用之則行，捨之則藏　(B)當斷不斷，反受其亂　(C)疑則勿用，用則勿疑　(D)水能載舟，亦能覆舟", "translation": "(A)被任用就出來做事，不被任用就退隱。(B)應該決斷的時候不決斷，反而會受到禍亂。(C)懷疑一個人就不要用他，用了就不要懷疑他。(D)水能讓船浮起來，也能把船打翻。", "keywords": [{"w": "捨", "m": "捨棄，這裡指不被任用"}, {"w": "覆", "m": "翻倒"}], "questions": [{"n": 20, "qtype": "單選", "stem": "閱讀下文，選出最適合說明文章中「標籤」性質的選項：", "options": {"A": "用之則行，捨之則藏", "B": "當斷不斷，反受其亂", "C": "疑則勿用，用則勿疑", "D": "水能載舟，亦能覆舟"}, "answer": "D", "explain": "賴聲川說標籤一方面是創造力的「障礙」，一方面又是讓世界有秩序的「重要工具」，好壞兩面都有。(D)正確，水能載舟也能覆舟，正是同一件事有利也有害。(A)錯，出自《論語‧述而》，講出仕與隱退的進退態度。(B)錯，講要果斷，和標籤的兩面性無關。(C)錯，講用人要信任，也無關。", "skill": "文章出現「……是障礙；但……也是重要工具」這種正反並陳，就找講「一體兩面」的選項。"}], "difficulty": "易", "label": "109二技", "year": 109, "kind": "二技"}, {"id": "et109-22", "exam": "et109", "nums": [22], "form": "單題", "img": "img/et109-22.png", "source": "沈義父《樂府指迷》", "author": "沈義父", "genre": "其他", "types": ["寫作手法", "典故出處"], "passage": "說桃不可直說破桃，須用紅雨、劉郎等字；說柳不可直說破柳，須用章台、灞岸等字。", "translation": "寫桃花不可以直接說出「桃」字，要用「紅雨」「劉郎」這些字代替；寫柳樹不可以直接說出「柳」字，要用「章台」「灞岸」這些字代替。", "keywords": [{"w": "紅雨", "m": "李賀詩「桃花亂落如紅雨」，代指桃花"}, {"w": "劉郎", "m": "劉禹錫〈玄都觀桃花〉詩中自稱，代指桃花"}, {"w": "章台", "m": "章台柳的典故，代指柳"}, {"w": "灞岸", "m": "灞橋折柳送別，代指柳"}], "questions": [{"n": 22, "qtype": "單選", "stem": "「說桃不可直說破桃，須用紅雨、劉郎等字；說柳不可直說破柳，須用章台、灞岸等字。」這句話所強調的修辭法最接近下列何者？", "options": {"A": "借代", "B": "頂真", "C": "回文", "D": "互文"}, "answer": "A", "explain": "不直接說「桃」「柳」，而用和它們有關的詞語（紅雨、劉郎、章台、灞岸）來代替，就是用相關事物代替本名。(A)正確，是借代。(B)錯，頂真是前一句結尾作下一句開頭，如「看書看到眼花，眼花……」。(C)錯，回文是正讀倒讀都成文。(D)錯，互文是上下文意互相補足，如「秦時明月漢時關」。", "skill": "「不說本名，用相關的東西代替」＝借代；先記住這個定義，其他修辭一比就刪。"}], "difficulty": "中", "label": "109二技", "year": 109, "kind": "二技"}, {"id": "et109-24", "exam": "et109", "nums": [24], "form": "單題", "img": "img/et109-24.png", "source": "應用文（敬語謙詞）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "拙作", "m": "謙稱自己的作品"}, {"w": "斧正", "m": "請人修改文章的敬詞"}, {"w": "蓬蓽生輝", "m": "謙稱貴客來訪使自己的寒舍增光"}, {"w": "令堂", "m": "敬稱對方的母親"}, {"w": "府上", "m": "敬稱對方的家"}], "questions": [{"n": 24, "qtype": "單選", "stem": "人際相處時為了表示客套，常會運用敬語和謙詞，以下用法何者正確？", "options": {"A": "學生對老師：「贈送拙作一本，還請您賜教斧正！」", "B": "客人對主人：「你家裡經過裝潢後，真是蓬蓽生輝啊！」", "C": "兩好友對話：「鼠年新春吉祥如意，在此代我家令堂向您問候！」", "D": "兩同事對話：「我剛搬新家，你若有空，隨時歡迎你到府上拜訪！」"}, "answer": "A", "explain": "口訣：說自己用謙詞，說對方用敬詞。(A)正確，「拙作」謙稱自己的作品，「斧正」是請對方修改的敬詞，用得對。(B)錯，「蓬蓽生輝」是主人謙稱自己家簡陋、因貴客來而增光，客人不能拿來誇主人的家。(C)錯，「令堂」是稱對方的母親，自己的母親要說「家母」。(D)錯，「府上」是稱對方的家，邀請別人來自己家應說「寒舍」。", "skill": "敬謙詞題先判斷「說的是誰的東西」：自己的配謙詞（拙、寒、家），對方的配敬詞（令、府、貴）。"}], "difficulty": "易", "label": "109二技", "year": 109, "kind": "二技"}, {"id": "et109-25", "exam": "et109", "nums": [25], "form": "單題", "img": "img/et109-25.png", "source": "應用文（題辭）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "(甲)慈竹長青　(乙)鳳卜其昌　(丙)松柏同春　(丁)五福全歸　(戊)齒德俱尊", "translation": "(甲)母親像慈竹一樣長青（祝女性長輩壽）。(乙)占卜得吉兆，子孫昌盛（賀結婚）。(丙)夫妻像松柏一樣同享長春（祝夫妻雙壽）。(丁)五種福氣都已圓滿而歸（輓男性喪事）。(戊)年紀和德行都受人尊敬（祝男性長輩壽）。", "keywords": [{"w": "慈竹", "m": "喻母親"}, {"w": "鳳卜", "m": "占卜婚姻得吉兆"}, {"w": "松柏同春", "m": "夫妻雙壽"}, {"w": "五福全歸", "m": "輓詞，福壽全歸"}, {"w": "齒德", "m": "年齡與德行"}], "questions": [{"n": 25, "qtype": "單選", "stem": "下列哪些題辭適合祝壽？", "options": {"A": "甲乙丙", "B": "甲丙戊", "C": "乙丙丁", "D": "乙丁戊"}, "answer": "B", "explain": "甲「慈竹長青」祝女壽、丙「松柏同春」祝雙壽、戊「齒德俱尊」祝男壽，都適合祝壽，所以(B)正確。乙「鳳卜其昌」是賀結婚；丁「五福全歸」是輓詞，用在喪事。含乙或丁的(A)(C)(D)都錯。", "skill": "題辭分類記關鍵字：松、柏、椿、萱、齒德是壽；鳳、鸞、卜是婚；全歸、千古、仙逝是喪。"}], "difficulty": "易", "label": "109二技", "year": 109, "kind": "二技"}, {"id": "et109-26", "exam": "et109", "nums": [26], "form": "單題", "img": "img/et109-26.png", "source": "《山海經》、《淮南子》", "author": "", "genre": "其他", "types": ["典故出處", "文化常識"], "passage": "甲、女娃遊於東海，溺而不返，故為□□，常銜西山之木石，以堙於東海。\n乙、□□與帝至此爭神，帝斷其首……乃以乳為目，以臍為口，操干戚以舞。\n丙、□□煉五色石以補蒼天，斷鰲足以立四極，殺黑龍以濟冀州，積蘆灰以止淫水。", "translation": "甲、炎帝的女兒女娃到東海遊玩，淹死沒有回來，所以化為精衛鳥，常銜著西山的樹枝石頭，要填平東海。乙、刑天和天帝在這裡爭奪神位，天帝砍下他的頭……他就用兩乳當眼睛，用肚臍當嘴巴，拿著盾牌和大斧揮舞。丙、女媧熔煉五色石來修補青天，砍斷大龜的腳來撐起四方，殺死黑龍來拯救冀州，堆積蘆葦燒成的灰來止住洪水。", "keywords": [{"w": "堙", "m": "填塞"}, {"w": "干戚", "m": "盾牌和大斧"}, {"w": "鰲", "m": "傳說中的大龜"}, {"w": "淫水", "m": "氾濫的洪水"}], "questions": [{"n": 26, "qtype": "單選", "stem": "閱讀下文，空格處依序最適合填入者為何？", "options": {"A": "精衛／夸父／蚩尤", "B": "湘君／女媧／蚩尤", "C": "精衛／刑天／女媧", "D": "湘君／夸父／刑天"}, "answer": "C", "explain": "甲：女娃溺死東海後化成鳥，銜木石填海，是「精衛填海」。乙：被砍頭後以乳為目、以臍為口、拿著干戚繼續舞，是「刑天舞干戚」。丙：煉石補天，是「女媧補天」。所以(C)正確。夸父是追日的巨人，蚩尤是和黃帝作戰的部落首領，湘君是湘水之神，都對不上，(A)(B)(D)錯。", "skill": "神話題抓「招牌動作」：填海→精衛、追日→夸父、舞干戚→刑天、補天→女媧。"}], "difficulty": "易", "label": "109二技", "year": 109, "kind": "二技"}, {"id": "et109-33", "exam": "et109", "nums": [33, 34, 35], "form": "題組", "img": "img/et109-33.png", "source": "李白〈贈汪倫〉、宋本《李太白文集》題注、袁枚《隨園詩話補遺》", "author": "李白、袁枚", "genre": "古典詩詞曲", "types": ["比較閱讀", "詩詞賞析", "文意推論"], "passage": "甲、李白〈贈汪倫〉：「李白乘舟將欲行，忽聞岸上踏歌聲。桃花潭水深千尺，不及汪倫送我情。」\n乙、宋本《李太白文集》題下注：「白游涇縣桃花潭，村人汪倫常醞美酒以待白。倫之裔孫至今寶其詩。」\n丙、袁枚《隨園詩話補遺》：「唐時汪倫者，涇川豪士也，聞李白將至，修書迎之，詭云：『先生好游乎？此地有十里桃花，先生好飲乎？此地有萬家酒店。』李欣然至。乃告云：『桃花者，潭水名也，並無桃花；萬家者，店主人姓萬也，並無萬家酒店。』李大笑。款留數日，贈名馬八匹，官錦十端，而親送之。李感其意作桃花潭絕句一首。」", "translation": "甲、李白坐上船正要出發，忽然聽到岸上傳來踏著拍子唱歌的聲音。桃花潭的水就算深達千尺，也比不上汪倫送我的情誼深。\n乙、李白遊涇縣桃花潭，村人汪倫常常釀好酒招待他。汪倫的後代子孫到現在還把這首詩當成寶貝收藏。\n丙、唐代的汪倫，是涇川的豪傑之士，聽說李白要來，寫信邀請他，騙他說：「先生喜歡遊玩嗎？這裡有十里桃花。先生喜歡喝酒嗎？這裡有萬家酒店。」李白高興地來了。汪倫才告訴他：「桃花，是潭水的名字，並沒有桃花；萬家，是店主人姓萬，並沒有一萬家酒店。」李白大笑。汪倫殷勤留他住了幾天，送他八匹名馬、十端官錦，還親自送行。李白感念他的情意，寫了桃花潭絕句一首。", "keywords": [{"w": "踏歌", "m": "邊唱歌邊用腳踏地打拍子"}, {"w": "醞", "m": "釀酒"}, {"w": "裔孫", "m": "後代子孫"}, {"w": "寶", "m": "珍藏"}, {"w": "詭", "m": "假裝、欺騙"}, {"w": "款留", "m": "殷勤挽留"}], "questions": [{"n": 33, "qtype": "單選", "stem": "據丙文記載，李白去桃花潭的原因為何？", "options": {"A": "路過涇縣不期而至", "B": "欲贈汪倫名馬官錦", "C": "酒店老闆修書邀約", "D": "汪倫書信刻意誘導"}, "answer": "D", "explain": "(D)正確，汪倫「修書迎之，詭云」，用「十里桃花」「萬家酒店」的雙關話把李白騙來。(A)錯，李白是受邀而來，不是剛好路過。(B)錯，送名馬官錦的是汪倫，對象是李白。(C)錯，寫信的是汪倫，「萬」只是酒店老闆的姓，老闆並沒有邀請。", "skill": "「誰做了什麼」的題目，把動詞前的主詞找清楚，主客顛倒的選項就能刪掉。"}, {"n": 34, "qtype": "單選", "stem": "根據甲詩，下列選項何者正確？", "options": {"A": "以「水深千尺」描述行舟的輕快", "B": "「踏歌聲」寫村人歡迎李白到來", "C": "末二句凸顯水深情更深之意旨", "D": "全詩使用先議後敘的寫作手法"}, "answer": "C", "explain": "(C)正確，末兩句用桃花潭水深千尺作比較，說汪倫的情誼比潭水還深。(A)錯，水深是拿來比情深，不是寫船行得快。(B)錯，李白「乘舟將欲行」，是要離開，踏歌聲是汪倫來送別，不是歡迎。(D)錯，前兩句先敘述送別場景，後兩句才抒發感想，是先敘後議（抒情）。", "skill": "短詩賞析先分前後兩半：前半通常是敘事寫景，後半是抒情議論。"}, {"n": 35, "qtype": "單選", "stem": "若依據上述詩文進行①、②兩項推論，其成立的可能性是：①汪倫因經營萬家酒店而致富②袁枚的補述來自汪倫的後代", "options": {"A": "①可以推論，②無法判斷", "B": "①、②無法判斷", "C": "①、②可以推論", "D": "①無法判斷，②可以推論"}, "answer": "B", "explain": "①：丙文說「萬家」是店主人姓萬，並沒有萬家酒店，也沒說汪倫開酒店或怎麼致富，所以無法推論。②：乙文只說汪倫後代珍藏這首詩，丙文沒交代袁枚的資料從哪裡來，兩者連不起來，也無法判斷。所以(B)正確，(A)(C)(D)錯。", "skill": "推論題要嚴格：原文沒有直接證據把兩件事連起來，就選「無法判斷」。"}], "difficulty": "中", "label": "109二技", "year": 109, "kind": "二技"}, {"id": "et109-36", "exam": "et109", "nums": [36, 37, 38], "form": "題組", "img": "img/et109-36.png", "source": "蔣毓英《臺灣府志》", "author": "蔣毓英", "genre": "其他", "types": ["文意推論", "句意理解"], "passage": "澎湖一島，乃臺郡之門戶。門戶固守，則堂奧清寧，是所謂扼塞之大者，若澎湖若也。當大洋之衢而扼其吭者，鹿耳門是已。鹿耳門之上有大線頭，線南有澚曰海翁崛，可泊船隻，港口甚隘。大線頭設防，則寸板不得到鹿耳；守鹿耳，當先守大線也。拊一郡之背而挈其領者，安平鎭是已。然就海防海，亦就郡防郡，猶其近者也。若入海之道，南路之打狗港、淡水港、沙馬磯頭，北路之半線港、竹塹港、上淡水江，皆可以縱帆四出，陰謀不測之徒，不稽其往來可乎哉？", "translation": "澎湖這座島，是臺灣府的大門。大門守得牢，屋內就安寧，所謂最重要的險要之地，就是像澎湖這樣的地方。位在大洋要道上、掐住咽喉的，就是鹿耳門。鹿耳門上方有大線頭，大線頭南邊有個海灣叫海翁崛，可以停泊船隻，港口很狹窄。大線頭設了防守，連一片木板都到不了鹿耳門；要守鹿耳門，應當先守大線頭。按住整個府城的背、提起它的衣領的，就是安平鎮。不過，只就海防海、就府城防府城，還只是近處的防守。至於出入海洋的通道，南路有打狗港、淡水港、沙馬磯頭，北路有半線港、竹塹港、上淡水江，都可以揚帆四處進出，對於心懷陰謀、難以預料的人，能不查核他們的往來嗎？", "keywords": [{"w": "堂奧", "m": "房屋內部，比喻內地"}, {"w": "扼塞", "m": "險要的關口"}, {"w": "衢", "m": "四通八達的要道"}, {"w": "吭", "m": "咽喉"}, {"w": "拊", "m": "按住"}, {"w": "挈其領", "m": "提起衣領，比喻掌握要害"}, {"w": "稽", "m": "查核"}], "questions": [{"n": 36, "qtype": "單選", "stem": "上文主要從哪方面說明臺灣的防務扼塞？", "options": {"A": "臺灣山區的陸防", "B": "臺灣四周的島防", "C": "臺灣西半部的海防", "D": "臺灣東半部的海防"}, "answer": "C", "explain": "文中提到的澎湖、鹿耳門、大線頭、安平鎮，以及打狗、半線、竹塹等港口，都在臺灣西部沿海，談的是海上防守。(C)正確。(A)錯，沒有談山區。(B)錯，只有澎湖是島，其餘都是本島港口，不是「四周的島」。(D)錯，提到的地點都不在東部。", "skill": "地理類文章，把文中地名在腦中的地圖上點一點，就知道範圍在哪裡。"}, {"n": 37, "qtype": "單選", "stem": "下列選項，何者符合上文文意？", "options": {"A": "鹿耳門的重要性，為臺灣海防的咽喉", "B": "外敵若想拿下大線頭，須先攻入淡水港", "C": "入海之道中的北路各港口，進出皆不便利", "D": "如要制敵於先，臺灣海防要先守住海翁堀"}, "answer": "A", "explain": "(A)正確，「當大洋之衢而扼其吭者，鹿耳門是已」，吭就是咽喉。(B)錯，文中只說「守鹿耳，當先守大線」，沒說要先攻淡水港。(C)錯，北路港口「皆可以縱帆四出」，是進出方便，所以才要查核。(D)錯，海翁崛只是可泊船的海灣，文中要先守的是大線頭。", "skill": "「扼其吭」「挈其領」這類比喻，先把身體部位翻成「咽喉、要害」，再對照選項。"}, {"n": 38, "qtype": "單選", "stem": "如外敵已拿下澎湖，欲直接進攻安平，依上文所述臺灣海防位置的重要性，臺灣應優先守住何處？", "options": {"A": "大線頭、鹿耳門", "B": "打狗港、竹塹港", "C": "大線頭、打狗港", "D": "鹿耳門、竹塹港"}, "answer": "A", "explain": "從澎湖進到安平（府城），要經過扼住咽喉的鹿耳門；而「大線頭設防，則寸板不得到鹿耳；守鹿耳，當先守大線」，所以要先守大線頭和鹿耳門。(A)正確。(B)(C)(D)中的打狗港、竹塹港是南北路其他入海口，文中說它們要「稽其往來」，但不是通往安平的第一道防線。", "skill": "路線題照文中順序排出「外→內」的關卡（澎湖→大線頭→鹿耳門→安平），答案就是中間那幾關。"}], "difficulty": "中", "label": "109二技", "year": 109, "kind": "二技"}, {"id": "et109-39", "exam": "et109", "nums": [39, 40, 41], "form": "題組", "img": "img/et109-39.png", "source": "徐芳〈雁奴說〉", "author": "徐芳", "genre": "寓言故事", "types": ["文意推論", "主旨寓意"], "passage": "雁之性善睡，宿於野，恐人謀己，則使孤者司警。有所見，高鳴戛戛，若傳呼然，群雁輒隨之起，謂之雁奴。有黠者貯火竹管中，潛行至近處搖之，火星噴出爛然，旋韜而伏。雁見火至，謂有寇，瞿然而叫，群雁鼓翅交應。久之，寂然無所睹，於是怪奴欺己，小啄之，復就宿。少頃，伏者再起，舉火搖之，奴又輒叫，群雁又輒應。已又寂然，則益怪，啄之加甚。如是數四火，即數四驚，又數四啄。奴見火之無害，而啄不勝苦也，意稍怏，不敢復警；即再警，群雁亦不復應。於是張網遍其宿處，噪而攻之，群雁夢中起，盡在網中，不可復脫。自後捕雁者皆用其術。", "translation": "雁的天性很愛睡，在野外過夜時，怕人算計牠們，就讓落單的雁負責警戒。一看到動靜，就高聲「戛戛」地叫，好像在傳令呼喊，群雁就跟著飛起，這隻雁叫做雁奴。有個狡猾的人把火藏在竹管裡，偷偷走到附近搖動，火星噴出很明亮，接著馬上把火收起來趴下。雁奴看到火，以為有敵人來，驚慌地叫，群雁拍著翅膀互相呼應。過了很久，靜悄悄什麼也沒看到，群雁就怪雁奴騙牠們，輕輕啄牠，又回去睡。不久，躲著的人又起來舉火搖動，雁奴又叫，群雁又應。之後又靜悄悄，群雁更奇怪，啄得更兇。這樣火來了好幾次，就驚了好幾次，也啄了好幾次。雁奴看火沒有危害，被啄又痛苦不堪，心裡有些不滿，不敢再警告；就算再警告，群雁也不再理會。於是那人在雁群睡的地方布滿網子，大聲喧嘩攻擊，群雁從夢中驚起，全都落在網裡，再也逃不掉。從此以後，捕雁的人都用這個方法。", "keywords": [{"w": "司警", "m": "負責警戒"}, {"w": "黠", "m": "狡猾"}, {"w": "韜", "m": "收藏、掩蔽"}, {"w": "瞿然", "m": "驚恐的樣子"}, {"w": "怏", "m": "不滿、不高興"}], "questions": [{"n": 39, "qtype": "單選", "stem": "依據上文，雁奴與雁群之間的關係，何者敘述正確？", "options": {"A": "雁奴因貪睡失責，受到雁群指責", "B": "雁奴因貪玩謊報，而被雁群孤立", "C": "雁群終未理雁奴警示，被一網成擒", "D": "雁群屢啄雁奴，雁奴只好獨自奔逃"}, "answer": "C", "explain": "(C)正確，「即再警，群雁亦不復應」，結果「群雁夢中起，盡在網中」。(A)錯，雁奴一直盡責示警，貪睡的是群雁。(B)錯，雁奴每次都是真的看到火才叫，不是貪玩謊報，是被人設計。(D)錯，文中沒有說雁奴獨自逃走。", "skill": "故事因果題，從結局倒推：群雁為什麼被抓？因為不理警報。為什麼不理？因為以為被騙。"}, {"n": 40, "qtype": "單選", "stem": "依據上文，下列關於捕雁者的敘述何者正確？", "options": {"A": "為避免打草驚蛇，先設計捕捉落單雁奴", "B": "採聲東擊西法，轉移雁群對火的警覺性", "C": "點火用煙燻法使雁群昏睡，再設網捕雁", "D": "運用反間之計，離間雁群對雁奴的信任"}, "answer": "D", "explain": "捕雁者反覆舉火又藏起來，讓雁奴每次示警都「落空」，群雁以為雁奴說謊而啄牠，最後不再相信雁奴。(D)正確，這是挑撥雙方信任的反間之計。(A)錯，他沒有去抓雁奴。(B)錯，他沒有在別處製造假動作吸引注意，而是在同一處反覆製造假警報。(C)錯，火是用來引發警報，不是煙燻。", "skill": "計謀題要看「對方最後是怎麼失敗的」：雁群敗在不再信任雁奴，所以計謀的重點就是破壞信任。"}, {"n": 41, "qtype": "單選", "stem": "依據上文，作者想要傳達的寓意，下列何者較為接近？", "options": {"A": "堅定立場，不隨之起舞，謠言止於智者", "B": "安危相易，禍福相生，難有永遠的安逸", "C": "設警防患，反責示警者，無異自我蒙蔽", "D": "世局混亂，人心不古，獨善其身是良策"}, "answer": "C", "explain": "群雁本來設雁奴防患，卻因為幾次「沒事」就責怪雁奴，最後讓雁奴不敢再警告，自己全軍覆沒。(C)正確，責罰示警的人，等於自己把眼睛蒙起來。(A)錯，雁奴的警告不是謠言。(B)錯，重點不是禍福輪替，而是錯怪示警者。(D)錯，故事沒有提倡獨善其身。", "skill": "寓言寓意要對應「誰犯了錯」：這裡犯錯的是群雁（錯怪示警者），選項要指出這個錯。"}], "difficulty": "易", "label": "109二技", "year": 109, "kind": "二技"}, {"id": "et110-11", "exam": "et110", "nums": [11], "form": "單題", "img": "img/et110-11.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "行視鯀之治水無狀，乃殛鯀於羽山以死。／梁王勝墜馬死，誼自傷為傅無狀，常哭泣。／此子前者出言無狀，且燒吾海，父王不合放還其人。／你這潑猴，十分無狀！師父傳你道法，卻與師父頂嘴。", "translation": "（舜）巡視鯀治水沒有成效，就把鯀處死在羽山。／梁懷王劉勝墜馬而死，賈誼自責身為太傅失職、沒盡到責任，常常哭泣。／這孩子先前說話放肆無禮，又燒了我的海，父王不該放他回去。／你這潑猴，太沒規矩了！師父傳你道法，你卻跟師父頂嘴。", "keywords": [{"w": "無狀", "m": "沒有成績、沒有功勞；也可指行為放肆無禮，依上下文判斷"}, {"w": "殛", "m": "誅殺"}, {"w": "傅", "m": "太傅，負責教導王子的老師"}], "questions": [{"n": 11, "qtype": "單選", "stem": "下列選項中的「無狀」，何者解釋正確？", "options": {"A": "行視鯀之治水「無狀」，乃殛鯀於羽山以死：無禮", "B": "梁王勝墜馬死，誼自傷為傅「無狀」，常哭泣：無能", "C": "此子前者出言「無狀」，且燒吾海，父王不合放還其人：無情", "D": "你這潑猴，十分「無狀」！師父傳你道法，卻與師父頂嘴：無聊"}, "answer": "B", "explain": "「無狀」字面是「沒有像樣的表現」，引申出兩個意思：一是沒有功績、沒有能力（失職），二是行為不像樣、放肆無禮。(A)出自《史記‧夏本紀》，鯀治水九年沒有成效才被處死，是「沒有成績」，不是「無禮」，錯。(B)出自《史記‧屈原賈生列傳》，賈誼當梁懷王的太傅，學生墜馬而死，他自責沒盡到責任，「無狀」就是沒有能力、失職，解為「無能」正確。(C)龍王控訴哪吒說話冒犯又燒海，是「放肆無禮」，不是「無情」，錯。(D)孫悟空跟師父頂嘴，是「沒規矩、無禮」，不是「無聊」，錯。", "skill": "一詞多義題先看「誰做了什麼」：被罰的辦事人多半是「沒成績」，被罵的晚輩多半是「無禮」。"}], "difficulty": "中", "label": "110二技", "year": 110, "kind": "二技"}, {"id": "et110-12", "exam": "et110", "nums": [12], "form": "單題", "img": "img/et110-12.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "文化常識"], "passage": "焚百家之言，以愚黔首。／王者不卻眾庶，故能明其德。／救黎民於水火，解百姓於倒懸。／豎子不足與謀！奪項王天下者，必沛公也。", "translation": "燒掉諸子百家的書，用來使百姓愚昧。／君王不拒絕眾多百姓，所以能彰顯他的德行。／把百姓從水深火熱中救出來，解除人民倒掛般的痛苦。／這小子不值得和他共謀大事！奪取項王天下的，一定是沛公。", "keywords": [{"w": "黔首", "m": "秦代對百姓的稱呼（黑頭巾）"}, {"w": "眾庶", "m": "眾多百姓"}, {"w": "黎民", "m": "百姓"}, {"w": "豎子", "m": "小子，輕視、罵人的稱呼"}], "questions": [{"n": 12, "qtype": "單選", "stem": "下列選項「」中的詞語，何者意義與其他不同？", "options": {"A": "焚百家之言，以愚「黔首」", "B": "王者不卻「眾庶」，故能明其德", "C": "救「黎民」於水火，解百姓於倒懸", "D": "「豎子」不足與謀！奪項王天下者，必沛公也"}, "answer": "D", "explain": "先把四個詞翻成白話就清楚了。(A)賈誼〈過秦論〉的「黔首」是秦朝對百姓的稱呼。(B)李斯〈諫逐客書〉的「眾庶」是眾多百姓。(C)「黎民」也是百姓，後半句還用「百姓」對應，更好判斷。(D)〈鴻門宴〉中范增說「豎子不足與謀」，「豎子」是罵人「小子、沒出息的傢伙」，指項羽，不是百姓。所以(D)與其他三者不同。", "skill": "找「意義不同」時，先把每個詞換成白話，三個同義的會自動歸成一組。"}], "difficulty": "易", "label": "110二技", "year": 110, "kind": "二技"}, {"id": "et110-13", "exam": "et110", "nums": [13], "form": "單題", "img": "img/et110-13.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "微管仲，吾其被髮左衽矣。／遠道不可思，宿昔夢見之。／距關，毋內諸侯，秦地可盡王也。／思厥先祖父，暴霜露，斬荊棘，以有尺寸之地。", "translation": "如果沒有管仲，我們恐怕都要披散頭髮、衣襟向左開（淪為夷狄）了。／遠在他方的人，再怎麼思念也見不到，只能在夜裡的夢中見到他。／守住函谷關，不讓諸侯進來，秦地就可以全部歸你統治。／想到他們的祖先，冒著霜露、砍除荊棘，才擁有一點點土地。", "keywords": [{"w": "被", "m": "通「披」"}, {"w": "宿昔", "m": "「宿」通「夙」；宿昔指昨夜、夜裡（一說早晚之間）"}, {"w": "內", "m": "通「納」，接納、放進"}, {"w": "暴", "m": "通「曝」，曝曬、冒著"}], "questions": [{"n": 13, "qtype": "單選", "stem": "下列「」內的詞語與意義通同的字，何者錯誤？", "options": {"A": "微管仲，吾其「被」髮左衽矣：通「披」", "B": "遠道不可思，「宿」昔夢見之：通「速」", "C": "距關，毋「內」諸侯，秦地可盡王也：通「納」", "D": "思厥先祖父，「暴」霜露，斬荊棘，以有尺寸之地：通「曝」"}, "answer": "B", "explain": "(A)《論語‧憲問》「被髮」就是披散頭髮，被通披，正確。(B)〈飲馬長城窟行〉「宿昔」的「宿」通「夙」（早），「宿昔」指昨夜或早晚之間，不是通「速」，錯誤，所以選(B)。(C)〈鴻門宴〉「毋內諸侯」是不要讓諸侯進來，內通納，正確。(D)蘇洵〈六國論〉「暴霜露」是曝露在霜露中，暴通曝，正確。", "skill": "通同字把本字代回句子讀讀看，意思通順才對；「宿昔」要記成「夙昔」。"}], "difficulty": "中", "label": "110二技", "year": 110, "kind": "二技"}, {"id": "et110-14", "exam": "et110", "nums": [14], "form": "單題", "img": "img/et110-14.png", "source": "馮夢龍《古今譚概》", "author": "馮夢龍", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "武帝時，有獻不死之酒者，東方朔竊飲之。帝怒，欲殺朔。朔曰：「臣所飲，不死之酒也。殺臣，臣亦不死；臣死，酒亦不驗。」", "translation": "漢武帝時，有人進獻喝了可以不死的酒，東方朔偷偷把它喝了。武帝大怒，要殺東方朔。東方朔說：「我喝的是不死之酒。您殺我，我如果死不了（就證明酒有效，您殺不了我）；我如果被殺死了，就證明這酒根本不靈驗。」", "keywords": [{"w": "竊", "m": "偷偷地"}, {"w": "驗", "m": "應驗、有效"}], "questions": [{"n": 14, "qtype": "單選", "stem": "閱讀下文，判斷東方朔「竊飲之」最可能的用意為何？", "options": {"A": "相信不死之酒的功效", "B": "破除不死之酒的荒誕", "C": "展現武帝愛才的心胸", "D": "炫耀自己應對的機警"}, "answer": "B", "explain": "東方朔的話是個兩難陷阱：殺不死我，表示酒有效、您也白殺；殺死我，就證明酒是假的。不管哪一種，「殺我」都沒有意義，重點是讓武帝明白「不死之酒」根本不可信。(A)他偷喝是為了拆穿，不是相信，錯。(B)破除荒誕，正確。(C)文中武帝是發怒要殺人，看不出愛才，也不是東方朔偷喝的目的，錯。(D)他的回答確實機智，但「偷喝」本身的用意是揭穿迷信，不是為了炫耀，錯。", "skill": "問「用意」時看人物最後那句話想讓對方明白什麼，而不是只看他表現得多聰明。"}], "difficulty": "易", "label": "110二技", "year": 110, "kind": "二技"}, {"id": "et110-15", "exam": "et110", "nums": [15], "form": "單題", "img": "img/et110-15.png", "source": "《孟子‧滕文公下》", "author": "孟子", "genre": "經典語錄", "types": ["文意推論", "主旨寓意"], "passage": "有楚大夫於此，欲其子之齊語也，則使齊人傅諸？使楚人傅諸？……使齊人傅之。", "translation": "假如有一位楚國大夫，想讓他的兒子學會說齊國話，那麼是請齊國人來教他呢？還是請楚國人來教他？……當然是請齊國人來教他。", "keywords": [{"w": "之", "m": "助詞，無義；「齊語」在這裡當動詞，指說齊國話"}, {"w": "傅", "m": "教導"}, {"w": "諸", "m": "「之乎」的合音"}], "questions": [{"n": 15, "qtype": "單選", "stem": "下列選項，何者最接近「使齊人傅之」所主張的學習觀念？", "options": {"A": "不要讓孩子輸在起跑點上", "B": "地球村時代，外語學習無止境", "C": "心有多大，學習的路就會有多長", "D": "線上真人互動，外籍母語家教到你家"}, "answer": "D", "explain": "要學齊國話，就請齊國人來教——意思是學語言要找「說這種話的人」當老師、置身在那種語言環境中。(A)強調「越早開始越好」，談的是時間，不是找誰教，錯。(B)強調「學不完、要一直學」，不是老師人選，錯。(C)強調企圖心，錯。(D)請以該語言為母語的外籍家教來教，正是「使齊人傅之」，正確。", "skill": "把古文的情境換成現代版本：楚人＝本國人，齊人＝母語人士，再去對選項。"}], "difficulty": "易", "label": "110二技", "year": 110, "kind": "二技"}, {"id": "et110-16", "exam": "et110", "nums": [16], "form": "單題", "img": "img/et110-16.png", "source": "劉劭《人物志》", "author": "劉劭", "genre": "說理議論", "types": ["文意推論", "句意理解"], "passage": "主德者，聰明平淡，達眾材而不以事自任者也。是故主道立，則眾材各得其任也。若道不平淡，與一材同好，則一材處權，而眾材失任矣。", "translation": "身為君主應有的德行，是聰明而平淡（不偏好），能通曉、任用各種人才，自己卻不親自包攬事務。所以君主之道確立了，各種人才都能得到適當的職位。如果君主不能平淡無偏，只跟某一種人才有相同的愛好，那麼這一種人才就會掌握大權，其他人才就失去發揮的位置了。", "keywords": [{"w": "主德", "m": "君主的德行"}, {"w": "平淡", "m": "不偏好、不偏私"}, {"w": "達", "m": "通曉、任用"}, {"w": "自任", "m": "自己擔任、包攬"}, {"w": "處權", "m": "掌握權力"}], "questions": [{"n": 16, "qtype": "單選", "stem": "依據下文對領導者特質的敘述，下列選項何者正確？", "options": {"A": "才能平庸並不會損害他發號施令的權威", "B": "凡事須親力親為才能妥善掌握執行效率", "C": "和下屬積極合作，才能發揮個人的能力", "D": "不能偏重單一人才，而須兼採各類專長"}, "answer": "D", "explain": "文章重點：好領導「不偏好」，讓各類人才都有位置；一旦偏愛某一種人，其他人才就被冷落。(A)「平淡」是不偏私，不是才能平庸，而且文中說他「聰明」，錯。(B)文中說「不以事自任」，正好相反，錯。(C)重點在讓眾材各得其任，不是發揮領導者「個人」能力，錯。(D)不偏重一材、兼用眾材，正確。", "skill": "看到「若……則……」的反面假設，就把它反過來，就是作者的主張。"}], "difficulty": "中", "label": "110二技", "year": 110, "kind": "二技"}, {"id": "et110-17", "exam": "et110", "nums": [17], "form": "單題", "img": "img/et110-17.png", "source": "袁宏道〈序陳正甫會心集〉", "author": "袁宏道", "genre": "書信序跋", "types": ["文意推論", "句意理解"], "passage": "夫趣得之自然者深，得之學問者淺……迨夫年漸長，官漸高，品漸大，有身如梏，有心如棘，毛孔骨節俱為聞見知識所縛，入理愈深，然其去趣愈遠矣。", "translation": "生活的趣味，從自然天性得來的就深刻，從學問得來的就淺薄……等到年紀漸漸大了，官位漸漸高了，品級漸漸提升了，身體像戴了刑具，心裡像長了荊棘，全身毛孔骨節都被見聞知識綁住，對道理懂得越深，離真正的趣味反而越遠了。", "keywords": [{"w": "趣", "m": "情趣、趣味"}, {"w": "迨", "m": "等到"}, {"w": "梏", "m": "手銬一類的刑具"}, {"w": "棘", "m": "荊棘"}, {"w": "縛", "m": "綑綁"}], "questions": [{"n": 17, "qtype": "單選", "stem": "閱讀下文，判斷「去趣愈遠」的原因：", "options": {"A": "外在事物拘限", "B": "迷失治學方向", "C": "長年惡疾纏身", "D": "沾染市賈之氣"}, "answer": "A", "explain": "原因就在「年漸長，官漸高，品漸大」以及「為聞見知識所縛」：年齡、官位、品級、知識這些外在東西把人綁住了。(A)外在事物拘限，正確。(B)文中說「入理愈深」，學問是越來越深，不是迷失方向，錯。(C)「有身如梏」是比喻被束縛，不是真的生病，錯。(D)文中沒提到商人氣息，錯。", "skill": "找原因題，鎖定結果句前面的「為……所……」被動句，那就是兇手。"}], "difficulty": "易", "label": "110二技", "year": 110, "kind": "二技"}, {"id": "et110-18", "exam": "et110", "nums": [18], "form": "單題", "img": "img/et110-18.png", "source": "余懷《板橋雜記‧序》", "author": "余懷", "genre": "書信序跋", "types": ["主旨寓意", "人物情感"], "passage": "一片歡場，鞠為茂草，紅牙碧串，妙舞清歌，不可得而聞也；洞房綺疏，湘簾綉幕，不可得而見也；名花瑤草，錦瑟犀毗，不可得而賞也。間亦過之，蒿藜滿眼，樓館劫灰，美人塵土，盛衰感慨，豈復有過此者乎！", "translation": "當年一片歌舞歡樂的地方，如今全長滿了野草。打拍子的檀板、碧玉串飾，美妙的舞蹈、清亮的歌聲，再也聽不到了；幽深的房間、雕花的窗格、湘竹簾子和繡花帷幕，再也看不到了；名貴的花草、華美的瑟和犀角飾物，再也無法欣賞了。偶爾經過那裡，滿眼都是雜草，樓閣成了劫後灰燼，美人化為塵土，興盛與衰敗的感慨，還有比這更深的嗎！", "keywords": [{"w": "鞠", "m": "盡、全"}, {"w": "紅牙", "m": "打拍子用的檀木板"}, {"w": "綺疏", "m": "雕刻花紋的窗格"}, {"w": "蒿藜", "m": "野草"}, {"w": "劫灰", "m": "戰亂後的灰燼"}], "questions": [{"n": 18, "qtype": "單選", "stem": "閱讀下文，作者所表達的感懷與下列何者最為接近？", "options": {"A": "成事不足，敗事有餘", "B": "物換星移，人事全非", "C": "盛名之下，其實難副", "D": "月滿則虧，水滿則溢"}, "answer": "B", "explain": "文章一再用「不可得而聞／見／賞」對比當年繁華和如今荒涼，是強烈的今昔之感。(A)說人沒能力只會壞事，無關。(B)景物變了、人事全不同，正是今昔感慨，正確。(C)說名聲大於實際，無關。(D)是「盛極必衰」的道理或警惕，文中重點是親眼見到繁華消逝的感傷，不是在說「別太滿」的道理，所以不如(B)貼切。", "skill": "看到「昔日如何、今日如何」的對照，先想「今昔之感、物是人非」。"}], "difficulty": "易", "label": "110二技", "year": 110, "kind": "二技"}, {"id": "et110-19", "exam": "et110", "nums": [19], "form": "單題", "img": "img/et110-19.png", "source": "劉半農〈相隔一層紙〉（選項引杜甫詩）", "author": "劉半農", "genre": "古典詩詞曲", "types": ["比較閱讀", "主旨寓意"], "passage": "朱門酒肉臭，路有凍死骨。", "translation": "富貴人家酒肉多到發臭，路邊卻有凍死的窮人屍骨。", "keywords": [{"w": "朱門", "m": "紅漆大門，指富貴人家"}], "questions": [{"n": 19, "qtype": "單選", "stem": "閱讀下文，依據文意選出正確的選項：", "options": {"A": "大雪兆豐年，無雪要遭殃", "B": "人老不算老，心老才算老", "C": "朱門酒肉臭，路有凍死骨", "D": "少壯不努力，老大徒傷悲"}, "answer": "C", "explain": "新詩寫屋裡的老爺嫌火太熱，屋外的乞丐快凍死，兩者只隔一層紙——貧富懸殊、冷暖兩個世界。(A)是農諺，講下雪對收成好，無關。(B)講心態年輕，無關。(C)杜甫〈自京赴奉先縣詠懷五百字〉的名句，富人奢侈、窮人凍死，正好對應，正確。(D)〈長歌行〉勸人及早努力，無關。", "skill": "先用一句話說出文章的「對比」，再找選項裡同樣有兩方對比的句子。"}], "difficulty": "易", "label": "110二技", "year": 110, "kind": "二技"}, {"id": "et110-22", "exam": "et110", "nums": [22], "form": "單題", "img": "img/et110-22.png", "source": "司馬遷《史記‧項羽本紀》（鴻門宴）", "author": "司馬遷", "genre": "史傳人物", "types": ["虛詞句式", "句意理解"], "passage": "范增數目項王，(甲)舉所佩玉玦以示之者三，項王默然不應。范增起，出，(乙)召項莊，(丙)謂(丁)曰：「君王為人不忍。若入，前為壽，壽畢，請以劍舞，因擊沛公於坐，殺之。不者，若屬皆且為所虜。」莊則入為壽，壽畢，(戊)曰：「君王與沛公飲，軍中無以為樂，請以劍舞。」項王曰：「諾。」項莊拔劍起舞，項伯亦拔劍起舞，(己)常以身翼蔽沛公，莊不得擊。", "translation": "范增多次向項王使眼色，又三次舉起身上佩戴的玉玦暗示他（下決心），項王沉默不回應。范增起身出去，叫來項莊，對他說：「君王為人心軟。你進去，上前敬酒，敬完酒，請求舞劍，趁機在座位上刺殺沛公。不這樣的話，你們這些人都將被他俘虜。」項莊就進去敬酒，敬完酒，說：「君王和沛公喝酒，軍中沒有什麼可以娛樂的，請讓我舞劍助興。」項王說：「好。」項莊拔劍起舞，項伯也拔劍起舞，常常用身體像鳥張開翅膀一樣掩護沛公，項莊無法下手。", "keywords": [{"w": "數目", "m": "多次用眼睛示意"}, {"w": "玦", "m": "有缺口的玉環，暗示「決斷」"}, {"w": "若", "m": "你"}, {"w": "若屬", "m": "你們這些人"}, {"w": "翼蔽", "m": "像翅膀一樣遮護"}], "questions": [{"n": 22, "qtype": "單選", "stem": "古文語法常有省略主、受詞的情形，請閱讀下文，判斷下列選項中對主、受詞省略的說明，何者正確？", "options": {"A": "甲：項王／乙：項伯／己：項王", "B": "乙：項王／丙：項莊／丁：范增", "C": "丙：項伯／丁：項莊／戊：范增", "D": "甲：范增／戊：項莊／己：項伯"}, "answer": "D", "explain": "順著動作的人走：范增使眼色→(甲)范增舉玉玦→范增出去→(乙)范增召項莊→(丙)范增對(丁)項莊說話→項莊進去敬酒→(戊)項莊說要舞劍→項伯也舞劍→(己)項伯用身體掩護沛公。(A)甲是范增、乙是范增、己是項伯，三個都錯。(B)乙是范增、丙是范增、丁是項莊，都錯。(C)丙是范增、戊是項莊，錯。(D)甲范增、戊項莊、己項伯，全對。", "skill": "補省略主詞時，從最近一個出現的人名往下追，誰在連續做動作，主詞就一直是他。"}], "difficulty": "中", "label": "110二技", "year": 110, "kind": "二技"}, {"id": "et110-23", "exam": "et110", "nums": [23], "form": "單題", "img": "img/et110-23.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式", "句意理解"], "passage": "孟嘗君為相數十年，無纖介之禍者，馮諼之計也。／（子產）治鄭二十六年而死。／李氏子蟠，年十七，好古文。／予出官二年，恬然自安。／自吾氏三世居是鄉，積於今六十歲矣，而鄉鄰之生日蹙。", "translation": "孟嘗君做宰相幾十年，沒有一點災禍，是馮諼的計策。／子產治理鄭國二十六年後去世。／李家的孩子李蟠，十七歲，愛好古文。／我被貶官出京兩年，一向安然自在。／自從我家三代住在這個鄉里，累積到現在已經六十年了，而鄉鄰的生活一天比一天困苦。", "keywords": [{"w": "纖介", "m": "細微"}, {"w": "出官", "m": "京官被貶到外地任職"}, {"w": "蹙", "m": "窘迫、困頓"}], "questions": [{"n": 23, "qtype": "單選", "stem": "在「孟嘗君為相數十年，無纖介之禍者，馮諼之計也」一句中，將時間名詞「數十年」置於動詞之後，意在補充說明孟嘗君為相的行為已持續進行了一段時間。下列選項中畫底線處，何者用法與此不同？", "options": {"A": "(子產)治鄭二十六年而死，丁壯號哭，老人兒啼", "B": "李氏子蟠，年十七，好古文，六藝經傳，皆通習之", "C": "予出官二年，恬然自安，感斯人言，是夕始覺有遷謫意", "D": "自吾氏三世居是鄉，積於今六十歲矣，而鄉鄰之生日蹙"}, "answer": "B", "explain": "題目要找「動詞＋一段時間」，說明動作持續多久。(A)《史記‧循吏列傳》「治鄭二十六年」：治理持續二十六年，相同。(B)韓愈〈師說〉「年十七」：是說李蟠的年齡十七歲，前面沒有動作、也不是持續時間，用法不同，選(B)。(C)白居易〈琵琶行并序〉「出官二年」：被貶在外持續兩年，相同。(D)柳宗元〈捕蛇者說〉「積於今六十歲」：住在這裡累積六十年，相同。", "skill": "先問自己：時間前面有沒有動作？有→表示持續多久；沒有→可能是年齡或時間點。"}], "difficulty": "中", "label": "110二技", "year": 110, "kind": "二技"}, {"id": "et110-25", "exam": "et110", "nums": [25], "form": "單題", "img": "img/et110-25.png", "source": "綜合（古典小說文學常識）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "章回小說", "m": "分回標目、每回有對句回目的長篇白話小說，如《水滸傳》《紅樓夢》《老殘遊記》"}, {"w": "傳奇", "m": "唐代文言短篇小說，如〈虬髯客傳〉"}, {"w": "筆記小說", "m": "魏晉南北朝記人記事的短篇，如《世說新語》"}], "questions": [{"n": 25, "qtype": "單選", "stem": "某出版社欲出版一套「中國古典章回小說」系列叢書，為增加銷售量，特為此叢書寫了一篇宣傳文案，其中所選書目，何者錯誤？（創社五十週年，空前鉅製／最佳章回小說，全新校點版本；名家導讀，精美印刷／話水滸①，看梁山好漢縱橫義氣；品紅樓②，味兒女情長意深濃／感受豪情壯志，在虬髯③；閒嗑名流軼事，有世說④；遍覽神州之奇，應隨老殘⑤／人生的風景，世情的冷暖，生命的苦甜，都在當中，幕升幕落，緣起緣滅……）", "options": {"A": "①②", "B": "③④", "C": "①③⑤", "D": "②④⑤"}, "answer": "B", "explain": "先分清楚文類：①《水滸傳》、②《紅樓夢》、⑤《老殘遊記》都是分回寫成的章回小說，正確。③〈虬髯客傳〉是唐代傳奇，是文言短篇；④《世說新語》是南朝劉義慶編的筆記小說，記錄名士言行，兩者都不是章回小說。所以錯的是③④，選(B)。(A)①②正確，不能選。(C)①⑤正確。(D)②⑤正確。", "skill": "看到「章回小說」，先想「明清長篇、分回」；短篇的唐傳奇、魏晉筆記一律排除。"}], "difficulty": "易", "label": "110二技", "year": 110, "kind": "二技"}, {"id": "et110-27", "exam": "et110", "nums": [27], "form": "單題", "img": "img/et110-27.png", "source": "應用文（家書）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "母親大人台鑒(甲)：\n您所寄禦寒衣物，兒已收到，值此歲末寒冬之時備感溫馨。\n昨天前往商店購買日用品，竟巧遇昔日鄰居陳叔叔。原來他就住在附近，我順便邀他到我府上(乙)拜訪。\n再過兩個星期就要放寒假，兒已歸心似箭。謹此，敬請\n福安(丙)\n兒小華叩上(丁)", "translation": "母親大人：您寄來的禦寒衣物，兒子已經收到，在這歲末寒冬時節感到格外溫暖。昨天去商店買日用品，竟然巧遇以前的鄰居陳叔叔，原來他就住在附近，我順便邀他到我家坐坐。再過兩個星期就要放寒假，兒子已經歸心似箭。在此敬祝您平安。兒子小華敬上", "keywords": [{"w": "膝下", "m": "寫給父母、祖父母的提稱語"}, {"w": "台鑒", "m": "寫給平輩的提稱語"}, {"w": "舍下／寒舍", "m": "對人稱自己家的謙詞"}, {"w": "府上", "m": "稱對方家的敬詞"}, {"w": "福安", "m": "對祖父母、父母的問候語"}, {"w": "叩上", "m": "對父母、祖父母的署名敬辭"}], "questions": [{"n": 27, "qtype": "單選", "stem": "以下是小華寫給母親的一封家書，下列選項何者完全錯誤？（甲：台鑒／乙：府上／丙：福安／丁：叩上）", "options": {"A": "甲、乙", "B": "乙、丙", "C": "甲、丙", "D": "乙、丁"}, "answer": "A", "explain": "逐項檢查：甲「台鑒」是給平輩用的，寫給母親應用「膝下」，錯。乙「府上」是稱別人家的敬詞，說自己家要用「舍下、寒舍」，錯。丙「福安」是對父母、祖父母的問候語，正確。丁「叩上」是對父母的署名敬辭，正確。兩個都錯的是甲、乙，選(A)。(B)(C)含正確的丙，(D)含正確的丁，都不是「完全錯誤」。", "skill": "書信用語記口訣：對父母「膝下、福安、叩上」；對人稱自己家用謙詞，稱別人家才用敬詞。"}], "difficulty": "易", "label": "110二技", "year": 110, "kind": "二技"}, {"id": "et110-28", "exam": "et110", "nums": [28], "form": "單題", "img": "img/et110-28.png", "source": "《荀子‧勸學》（閱讀心得）", "author": "荀子", "genre": "經典語錄", "types": ["文化常識", "典故出處"], "passage": "蓬生麻中，不扶而直；白沙在涅，與之俱黑。", "translation": "蓬草長在麻叢中，不用扶也會長得直；白沙放在黑泥裡，就跟著變黑了。", "keywords": [{"w": "涅", "m": "黑色的泥土、染料"}], "questions": [{"n": 28, "qtype": "單選", "stem": "以下是小名的閱讀心得，請根據書寫內容判斷應該屬於哪一本書？（‧以禮為宗，以為禮是治人治世的最佳工具。‧主張積善化性，強調教育與學習的重要。‧佳句：「蓬生麻中，不扶而直；白沙在涅，與之俱黑。」）", "options": {"A": "《孟子》", "B": "《荀子》", "C": "《莊子》", "D": "《韓非子》"}, "answer": "B", "explain": "「隆禮」「化性起偽（後天教育改變本性）」「重學習」都是荀子的招牌主張，佳句出自〈勸學〉，講環境對人的影響。(A)孟子主張性善、仁政，強調擴充本心，不是靠禮來改造本性，錯。(B)荀子，正確。(C)莊子講逍遙、齊物、順應自然，錯。(D)韓非子講法、術、勢，以法治國，錯。", "skill": "諸子辨識：禮＋學＋性惡化性＝荀子；性善＋仁政＝孟子；法術勢＝韓非；逍遙齊物＝莊子。"}], "difficulty": "易", "label": "110二技", "year": 110, "kind": "二技"}, {"id": "et110-30", "exam": "et110", "nums": [30, 31, 32], "form": "題組", "img": "img/et110-30.png", "source": "《四庫全書總目提要‧花間集》（改寫）", "author": "紀昀等", "genre": "書信序跋", "types": ["文意推論", "文化常識", "句意理解"], "passage": "詩餘體變自唐，而盛行於五代。自宋以後，體制益繁，選錄益眾，而溯源星宿，當以此集為最古。唐末名家詞曲，俱賴以僅存。……於作者不題名而題官，蓋即《文選》書字之遺意。惟一人之詞，時割數首入前後卷，以就每卷五十首之數，則體例為古所未有耳。……後有陸游跋，稱：「唐季、五代，詩愈卑，而倚聲者輒簡古可愛，能此不能彼，未易以理推也。」不知文之體格有高卑，人之學力有強弱。學力不足副其體格，則舉之不足；學力足以副其體格，則舉之有餘。律詩降於古詩，故中、晚唐古詩多不工，而律詩則時有佳作。詞又降於律詩，故五季人詩不及唐，詞乃獨勝。此猶能舉七十斤者，舉百斤則蹶，舉五十斤則運掉自如，有何不可理推乎！", "translation": "詞這種文體從唐代演變而來，到五代才盛行。宋代以後，詞的體制越來越多，選本也越來越多，但若追溯源頭，應以這本《花間集》最古老。唐末名家的詞作，都靠它才保存下來。……書中標注作者不寫名字而寫官職，大概是沿襲《文選》稱字不稱名的用意。只是同一個人的詞，有時拆幾首放到前一卷或後一卷，以湊足每卷五十首的數目，這種體例是以前沒有的。……書後有陸游的跋文，說：「晚唐、五代的詩越來越卑弱，填詞的人卻往往寫得簡潔古雅可愛，能寫好詞卻寫不好詩，這很難用常理推論。」（四庫館臣認為）陸游不明白：文體的格調有高有低，人的才力有強有弱。才力配不上文體的格調，寫起來就吃力；才力足以配得上，寫起來就游刃有餘。律詩的格調比古詩低，所以中晚唐的古詩多半寫不好，律詩卻常有佳作；詞的格調又比律詩低，所以五代人的詩比不上唐人，詞卻特別出色。這就像能舉七十斤的人，舉一百斤就會跌倒，舉五十斤就揮灑自如，怎麼會不能用道理推論呢！", "keywords": [{"w": "詩餘", "m": "詞的別稱"}, {"w": "溯源星宿", "m": "追溯源頭（星宿海是黃河源頭）"}, {"w": "倚聲", "m": "依照曲調填詞"}, {"w": "副", "m": "相稱、配得上"}, {"w": "蹶", "m": "跌倒"}, {"w": "運掉自如", "m": "揮動自如，形容輕鬆"}, {"w": "五季", "m": "五代"}], "questions": [{"n": 30, "qtype": "單選", "stem": "下列選項，何者符合甲文的文意？", "options": {"A": "《四庫提要》從《花間集》的體例，證明唐末五代詞不如宋詞", "B": "《四庫提要》認為陸游對詞之偏好多於詩，深受唐末五代影響", "C": "陸游以「能舉七十斤者，舉百斤則蹶」，說明《花間集》特色", "D": "陸游認為唐末五代詩與詞成就的高低，其緣由實難用常理推論"}, "answer": "D", "explain": "先分清楚誰說了什麼：陸游的話只有引號內那段「能此不能彼，未易以理推也」；後面「不知文之體格……」到舉重比喻，都是《四庫提要》反駁陸游的話。(A)文中只說《花間集》是最古的詞選、體例特別，沒有拿來比較宋詞高下，錯。(B)文中沒說陸游比較偏好詞，錯。(C)舉重的比喻是《四庫提要》說的，而且是解釋五代詩不如詞的原因，不是說《花間集》特色，錯。(D)陸游說「未易以理推也」，就是很難用常理推論，正確。", "skill": "引文題先把「誰的話」用括號圈出來，很多選項是把甲的話安到乙頭上。"}, {"n": 31, "qtype": "單選", "stem": "依甲文文意，乙表中的作者是以何種類別的稱呼呈現？", "options": {"A": "字號", "B": "官名", "C": "籍貫", "D": "諡號"}, "answer": "B", "explain": "甲文說「於作者不題名而題官」，也就是寫官職不寫名字。乙表的「助教、相、侍郎、給事、舍人、司徒、學士、太尉、少監」都是官名，例如溫助教是溫庭筠、韋相是韋莊。(A)字號是別名（如東坡），不是。(C)籍貫是出身地，不是。(D)諡號是死後評價的稱號（如文正），不是。答案(B)。", "skill": "表格題回頭找文章裡直接說明的那句話，常常一字就給答案（題官）。"}, {"n": 32, "qtype": "單選", "stem": "依乙表目錄，判斷下列選項中的作者與卷別，何者符合甲文「一人之詞，時割數首入前後卷」的說法？", "options": {"A": "韋相", "B": "薛侍郎", "C": "牛學士", "D": "尹參卿"}, "answer": "A", "explain": "「割數首入前後卷」就是同一個作者的詞被拆到相鄰兩卷。查表：(A)韋相在卷二22首、卷三26首，被拆成前後卷，正確。(B)薛侍郎只在卷三，錯。(C)牛學士只在卷五（卷三、卷四的是「牛給事」，是另一人），錯。(D)尹參卿只在卷九，錯。", "skill": "對表格要逐字核對稱呼，名字相像（牛給事／牛學士）的陷阱最常見。"}], "difficulty": "中", "label": "110二技", "year": 110, "kind": "二技"}, {"id": "et110-33", "exam": "et110", "nums": [33, 34, 35], "form": "題組", "img": "img/et110-33.png", "source": "《戰國策‧齊策》（魯仲連遺燕將書）", "author": "", "genre": "書信序跋", "types": ["文意推論", "句意理解", "寫作手法"], "passage": "初，燕將攻聊城，人或讒之。燕將懼誅，遂保守聊城，不敢歸。田單攻之歲餘，士卒多死，而聊城不下。魯連乃書，約之矢以射城中，遺燕將。曰：「今公行一朝之忿，不顧燕王之無臣，非忠也；殺身亡聊城，而威不信於齊，非勇也；功廢名滅，後世無稱，非知也。①故知者不再計，勇士不怯死。今死生榮辱，尊卑貴賤，此其一時也。願公之詳計而無與俗同也。②且楚攻南陽，魏攻平陸，齊無南面之心，以為亡南陽之害，不若得濟北之利，故定計而堅守之。今楚、魏交退，燕救不至，齊無天下之規，與聊城共據朞年之弊，即臣見公之不能得也。齊必決之於聊城，公無再計。故為公計者，不如罷兵休士，全車甲，歸報燕王，燕王必喜。士民見公，如見父母，交遊攘臂而議於世，功業可明矣。意者，亦捐燕棄世，東游與齊乎？請裂地定封，富比陶、衛，世世稱孤，與齊久存，此亦一計也。二者顯名厚實也，願公熟計而審處一也。」", "translation": "當初，燕國將領攻下聊城，有人向燕王說他的壞話。燕將怕被殺，就據守聊城，不敢回國。齊將田單攻打聊城一年多，士兵死了很多，卻攻不下來。魯仲連就寫了一封信，綁在箭上射進城裡，送給燕將。信上說：「現在您為了一時的憤怒，不顧燕王失去臣子，這不是忠；自己戰死、丟了聊城，威名卻不能在齊國伸張，這不是勇；功業廢棄、名聲消失，後世沒人稱頌，這不是智。所以聰明人不會猶豫反覆，勇士不會怕死。如今生死榮辱、尊卑貴賤，就決定在這個時刻。希望您仔細考慮，不要和一般人一樣見識。況且楚國攻打南陽，魏國攻打平陸，齊國卻無意向南應戰，認為失去南陽的損害，比不上得到濟北的利益，所以下定決心堅持攻城。現在楚、魏都退兵了，燕國的救兵又不來，齊國沒有其他的打算，和聊城耗了一整年，我看您是守不住了。齊國一定要在聊城決一勝負，您沒有別的出路。所以替您打算，不如收兵休息，保全兵車盔甲，回去向燕王報告，燕王一定高興。百姓見到您，就像見到父母一樣，朋友們會激動地在世上稱讚您，功業就能顯揚了。或者，您也可以拋棄燕國、離開世俗，往東投奔齊國吧？齊國會割地封您，財富比得上陶朱公、衛國的富豪，世世代代稱王稱侯，與齊國共存，這也是一個辦法。這兩條路都能讓您名聲顯赫、實利豐厚，希望您仔細考慮，選定其中一條。」", "keywords": [{"w": "讒", "m": "說壞話陷害"}, {"w": "遺", "m": "ㄨㄟˋ，送給"}, {"w": "知", "m": "通「智」"}, {"w": "朞年", "m": "一整年"}, {"w": "規", "m": "打算、謀劃"}, {"w": "捐", "m": "拋棄"}, {"w": "攘臂", "m": "捲起袖子，形容激動"}, {"w": "審處", "m": "慎重選擇"}], "questions": [{"n": 33, "qtype": "單選", "stem": "燕將之所以死守聊城的原因為何？", "options": {"A": "燕國後援軍已被楚魏阻退", "B": "受到讒言害怕歸燕後被殺", "C": "憂城破身死威名不能傳播", "D": "想要維持無敗戰績的紀錄"}, "answer": "B", "explain": "第一句就交代：「人或讒之。燕將懼誅，遂保守聊城，不敢歸」。(A)楚魏是攻齊的國家，文中說「燕救不至」，沒說被楚魏阻退，錯。(B)怕回去被殺，正確。(C)「威不信於齊」是魯仲連勸說時講的後果，不是燕將守城的原因，錯。(D)文中沒提到戰績紀錄，錯。", "skill": "問「原因」先找「懼、畏、恐」這類表示動機的字。"}, {"n": 34, "qtype": "單選", "stem": "下列關於上文文意的敘述，何者正確？", "options": {"A": "魯仲連認為燕將因愛慕榮利而犧牲戰士，實有違武者仁德", "B": "齊國有統一天下之志，故傾全國之兵欲解聊城之危以顯勇", "C": "齊國準備車輛甲冑，作為燕將退兵聊城並歸報燕王之大禮", "D": "魯仲連建議燕將可去燕留齊，並且許諾賜地並享富貴生活"}, "answer": "D", "explain": "(A)魯仲連批評的是燕將「行一朝之忿」，是一時意氣，不是愛慕榮利，錯。(B)文中說「齊無天下之規」，齊國沒有其他打算、只想拿下聊城，不是要統一天下，錯。(C)「全車甲」是勸燕將保全自己的兵車盔甲回國，不是齊國送禮，錯。(D)「捐燕棄世，東游與齊乎？請裂地定封，富比陶、衛」，就是勸他投齊、受封享富貴，正確。", "skill": "選項中的主詞（齊國／燕將）要回原文核對，常見把甲方的事安到乙方身上。"}, {"n": 35, "qtype": "單選", "stem": "下列關於上文畫底線處說服策略的說明，請選出正確選項：①說之以理：以燕將勿從俗而應作真正的智勇雙全者　②誘之以利：以燕國可得濟北之地誘之", "options": {"A": "①②皆正確", "B": "①②皆錯誤", "C": "①正確，②錯誤", "D": "①錯誤，②正確"}, "answer": "C", "explain": "①「知者不再計，勇士不怯死……願公之詳計而無與俗同也」，是講道理，要他做真正的智者、勇者，不要和俗人一樣，說明正確。②這段是說齊國認為「失南陽的害處，比不上得濟北的利益」，所以齊國下定決心攻聊城（聊城在濟北）——是在分析形勢、讓燕將知道齊國不會放手，「濟北之利」是齊國的利益，不是拿來誘惑燕將的好處，說明錯誤。所以選(C)。", "skill": "看到「利」字別急著判斷「誘之以利」，先問：這是誰的利益？"}], "difficulty": "難", "label": "110二技", "year": 110, "kind": "二技"}, {"id": "et110-36", "exam": "et110", "nums": [36, 37, 38], "form": "題組", "img": "img/et110-36.png", "source": "白居易〈養竹記〉", "author": "白居易", "genre": "說理議論", "types": ["字詞解釋", "文意推論", "主旨寓意"], "passage": "竹似賢，何哉？竹本固，固以樹德，君子見其本，則思善建不拔者；竹性直，直以立身，君子見其性，則思中立不倚者；竹心空，空以體道，君子見其心，則思應用虛受者；竹節貞，貞以立志，君子見其節，則思砥礪名行，夷險一致者。夫如是，故君子人多樹之，為庭實焉。貞元十九年春，居易以拔萃選及第，授校書郎，始於長安求假居處，得常樂里故關相國私第之東亭而處之。明日，履及於亭之東南隅，見叢竹於斯，枝葉殄瘁，無聲無色。詢於關氏之老，則曰此相國之手植者，自相國捐館，他人假居，繇是筐篚者斬焉，篲箒者刈焉，刑餘之才，長無尋焉，數無百焉，又有凡草木雜生其中，菶茸薈鬱，有無竹之心焉。居易惜其嘗經長者之手，而見賤俗人之目，翦棄若是，本性猶存，乃芟蘙薈，除糞壤，疏其間，封其下，不終日而畢。於是日出有清陰，風來有清聲，依依然，欣欣然，若有情於感遇也。嗟乎！竹，植物也，於人何有哉？以其有似於賢，而人愛惜之，封植之，況其真賢者乎？然則竹之於草木，猶賢之於眾庶。嗚呼！竹不能自異，惟人異之，賢不能自異，惟用賢者異之。故作〈養竹記〉，書於亭之壁，以貽其後之居斯者，亦欲以聞於今之用賢者云。", "translation": "竹子像賢人，為什麼呢？竹根穩固，穩固才能樹立德行，君子看到竹根，就想到要像它一樣根基穩固、不可動搖；竹性挺直，挺直才能立身，君子看到竹的本性，就想到要正直中立、不偏不倚；竹心中空，中空才能體悟大道，君子看到竹心，就想到要虛心接受；竹節堅貞，堅貞才能立定志向，君子看到竹節，就想到要磨練名節品行，無論順境逆境都始終如一。正因如此，君子大多種竹，作為庭院中的陳設。貞元十九年春天，我以拔萃科考中，被任命為校書郎，開始在長安找借住的地方，找到常樂里已故關相國私宅的東亭住下。第二天，走到亭子東南角，看見這裡有一叢竹子，枝葉枯萎憔悴，沒有聲響也沒有光彩。向關家的老僕人詢問，他說這是相國親手種的，自從相國過世，別人借住，於是做竹器的人來砍，做掃帚的人來割，被砍剩下的竹子，高不到八尺，數量不到一百根，又有雜草雜木混生其中，茂盛雜亂，好像沒有竹子存在了。我可惜這些竹子曾經過長者親手栽種，卻被俗人輕賤，被砍伐丟棄成這樣，但本性仍在，於是剪除雜草，清除糞土，疏通竹間空隙，在根部培土，不到一天就完成了。從此太陽出來有清涼的竹蔭，風吹來有清脆的竹聲，依依不捨、欣欣向榮，好像對得到賞識照顧心懷感激。唉！竹子只是植物，對人有什麼關係呢？因為它像賢人，人們就愛惜它、培土種植它，何況是真正的賢人呢？那麼竹子在草木之中，就像賢人在百姓之中。唉！竹子不能使自己與眾不同，只有人能使它與眾不同；賢人不能使自己與眾不同，只有任用賢人的人能使他與眾不同。所以寫了這篇〈養竹記〉，題在亭子的牆上，留給以後住在這裡的人，也希望讓當今任用賢才的人聽到。", "keywords": [{"w": "樹", "m": "樹立"}, {"w": "庭實", "m": "庭院中的陳設"}, {"w": "殄瘁", "m": "枯萎憔悴"}, {"w": "捐館", "m": "捐棄館舍，死亡的婉稱"}, {"w": "假居", "m": "借住"}, {"w": "刑餘之才", "m": "被砍伐後剩下的竹子"}, {"w": "尋", "m": "古代長度單位，八尺"}, {"w": "封", "m": "在根部培土"}, {"w": "異之", "m": "使它與眾不同，賞識它"}], "questions": [{"n": 36, "qtype": "單選", "stem": "下列「」內語句的詮釋，何者正確？", "options": {"A": "「見叢竹於斯，枝葉殄瘁」：枝繁葉茂，生機勃勃", "B": "「自相國捐館，他人假居」：相國捐贈館舍，供人租賃", "C": "「筐篚者斬焉，篲箒者刈焉」：任人取用來製作竹器或掃帚", "D": "「刑餘之才，長無尋焉」：擅於伐竹製作器具的人才，徧尋不著"}, "answer": "C", "explain": "(A)「殄瘁」是枯萎憔悴，後面還接「無聲無色」，不是生機勃勃，錯。(B)「捐館」是死亡的婉轉說法（丟下房子走了），不是捐贈館舍，錯。(C)做竹器的人來砍、做掃帚的人來割，就是被人任意取用，正確。(D)「刑餘之才」指被砍剩的竹子，「長無尋」是高不到八尺，不是找不到人才，錯。", "skill": "遇到婉辭（捐館＝死）和比喻（刑餘＝被砍剩），回到上下文看描寫的對象是人還是竹。"}, {"n": 37, "qtype": "單選", "stem": "依據上文，作者認為竹「翦棄若是，本性猶存」，以下何者最能說明其本性？", "options": {"A": "成人之美，功成不居", "B": "窮達一致，堅定不移", "C": "樂天知命，隨遇而安", "D": "獨善其身，寧折不彎"}, "answer": "B", "explain": "首段說竹「本固」「性直」「心空」「節貞」，又說「夷險一致」——不論順境逆境都一樣。被砍成這樣仍保有本性，正是「窮達一致，堅定不移」，選(B)。(A)講幫助別人、不居功，文中沒提。(C)「隨遇而安」偏向順應環境、不在乎處境，和竹的「堅貞」不同。(D)「寧折不彎」偏剛烈，竹被砍伐後仍存本性，重點在「不改變」，而且文中沒有獨善其身的意思。", "skill": "題目引的句子回到首段「竹的四種特質」去對，答案多半就在作者的定義裡。"}, {"n": 38, "qtype": "單選", "stem": "依據上文，作者寫作本文的主要意旨為何？", "options": {"A": "讚賞竹之美德，提示養竹應循序漸進", "B": "君子養竹樹德，強調居處絕不可無竹", "C": "用賢有如養竹，賢才仍待知遇者賞識", "D": "養竹貴循本性，與其張揚未若順自然"}, "answer": "C", "explain": "末段點題：「竹不能自異，惟人異之；賢不能自異，惟用賢者異之」，並說要「聞於今之用賢者」。作者是借養竹比喻用賢：賢才需要被賞識、培養。(A)沒提養竹要循序漸進。(B)「居不可無竹」是蘇軾的話，本文沒這樣說。(C)正確。(D)文中沒談「張揚」與「順自然」的比較。", "skill": "托物言志的文章，主旨通常在最後一段「嗟乎／嗚呼」之後。"}], "difficulty": "中", "label": "110二技", "year": 110, "kind": "二技"}, {"id": "et111-04", "exam": "et111", "nums": [4], "form": "單題", "img": "img/et111-04.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "虛詞句式"], "passage": "甲、夫子之道至大也，故天下莫能容夫子，夫子蓋少貶焉。／乙、有善始者實繁，能克終者蓋寡，豈其取之易而守之難乎？／丙、苟或不然，人爭非之，以為鄙吝，故不隨俗靡者蓋鮮矣。／丁、庖丁爲文惠君解牛……文惠君曰：嘻！善哉！技蓋至此乎？", "translation": "甲、老師的道太偉大了，所以天下沒有國家能容納老師，老師何不稍微降低一點標準呢？／乙、有好開始的人確實很多，能堅持到最後的大概很少，難道是取得天下容易而守住天下困難嗎？／丙、如果不這樣，別人就爭相責怪，認為他小氣，所以不跟隨奢侈風氣的人大概很少了。／丁、庖丁替文惠君宰牛……文惠君說：啊！好啊！技術怎麼能到這種地步呢？", "keywords": [{"w": "盍", "m": "何不；也可作「何」"}, {"w": "蓋", "m": "句中可表推測「大概」；也可通「盍」"}, {"w": "靡", "m": "奢侈"}], "questions": [{"n": 4, "qtype": "單選", "stem": "下列文句的「蓋」字替換為「盍」字後，原句意義不變的選項是：", "options": {"A": "甲乙", "B": "甲丁", "C": "乙丙", "D": "乙丁"}, "answer": "B", "explain": "「盍」是「何不」或「何」的意思，所以要找本身就當「何不／何」用的「蓋」。甲出自《史記‧孔子世家》，子貢勸孔子「何不稍微降低標準」，蓋通盍，可替換。乙出自魏徵〈諫太宗十思疏〉，「蓋寡」是「大概很少」，表推測，不能換。丙出自司馬光〈訓儉示康〉，「蓋鮮」也是「大概很少」，不能換。丁出自《莊子‧養生主》，「技蓋至此乎」是「技術怎麼到這地步」，蓋通盍（何），可替換。答案甲丁，選(B)。", "skill": "把「何不／怎麼」代進去讀：句子變成疑問或勸告且通順，就是「盍」；表示「大概」的就不是。"}], "difficulty": "難", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-05", "exam": "et111", "nums": [5], "form": "單題", "img": "img/et111-05.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "夫天地者，萬物之逆旅也。／逆閹防伺甚嚴，雖家僕不得近。／苟全性命於亂世，不求聞達于諸侯。／聞道有先後，術業有專攻。／微夫人之力不及此。／微斯人，吾誰與歸？／奉命於危難之間，爾來二十有一年矣。／新婦所乏唯容爾。", "translation": "天地是萬物的旅舍。／叛逆的宦官防範監視得很嚴，連家僕都不能靠近。／只求在亂世中保全性命，不求在諸侯間顯達揚名。／懂得道理有先有後，學問技藝各有專門。／如果沒有那個人的幫助，我到不了今天。／如果沒有這種人，我要跟誰在一起呢？／在危難時接受命令，從那時到現在已經二十一年了。／新娘所缺少的只有容貌罷了。", "keywords": [{"w": "逆旅", "m": "旅舍"}, {"w": "逆閹", "m": "叛逆的宦官"}, {"w": "聞達", "m": "有名聲、顯達"}, {"w": "微", "m": "如果沒有"}, {"w": "爾來", "m": "從那時以來"}, {"w": "爾", "m": "句末語氣詞，罷了"}], "questions": [{"n": 5, "qtype": "單選", "stem": "下列選項「」中的詞義，前後相同的選項是：", "options": {"A": "夫天地者，萬物之「逆」旅也／「逆」閹防伺甚嚴，雖家僕不得近", "B": "苟全性命於亂世，不求「聞」達于諸侯／「聞」道有先後，術業有專攻", "C": "子犯請擊之，公曰：不可。「微」夫人之力不及此／噫！「微」斯人，吾誰與歸", "D": "奉命於危難之間，「爾」來二十有一年／婦有四德，卿有其幾？婦曰：新婦所乏唯容「爾」"}, "answer": "C", "explain": "(A)李白〈春夜宴從弟桃花園序〉「逆旅」是迎接旅客的客舍（逆＝迎）；方苞〈左忠毅公軼事〉「逆閹」是叛逆的宦官，不同。(B)〈出師表〉「聞達」是有名聲；韓愈〈師說〉「聞道」是知道、懂得道理，不同。(C)〈燭之武退秦師〉「微夫人之力」和范仲淹〈岳陽樓記〉「微斯人」的「微」都是「如果沒有」，相同，選(C)。(D)〈出師表〉「爾來」的爾是「那時」；《世說新語》許允婦「唯容爾」的爾是句末語氣「罷了」，不同。", "skill": "「微＋人／事物」放在句首，後面接結果，多半是「如果沒有」。"}], "difficulty": "中", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-12", "exam": "et111", "nums": [12], "form": "單題", "img": "img/et111-12.png", "source": "《呂氏春秋‧用眾》", "author": "呂不韋（編）", "genre": "說理議論", "types": ["主旨寓意", "比較閱讀"], "passage": "物固莫不有長，莫不有短，人亦然。故善學者，假人之長以補其短。", "translation": "萬物本來就沒有不具長處、沒有不具短處的，人也是這樣。所以善於學習的人，會借用別人的長處來彌補自己的短處。", "keywords": [{"w": "固", "m": "本來"}, {"w": "假", "m": "借用"}], "questions": [{"n": 12, "qtype": "單選", "stem": "下列選項，何者最接近下文意旨？", "options": {"A": "適性揚才，成就每一個孩子", "B": "為學要如金字塔，要能博大要能高", "C": "三人之行必有我師，擇其善者而取法之", "D": "尺有所短而寸有所長，人各司其職以盡其才"}, "answer": "C", "explain": "重點在後半句「善學者，假人之長以補其短」——向別人學他的長處。(A)是發展每個人自己的才能，不是向別人學，錯。(B)講學問要廣又要深，錯。(C)《論語》的「三人行必有我師，擇其善者而從之」，就是學別人的優點，正確。(D)前半「尺短寸長」只對應「莫不有長、莫不有短」，後半「各司其職」講分工，偏離「向人學習補短」，錯。", "skill": "主旨通常在「故」字之後，前面只是鋪墊；小心只對到前半句的陷阱選項。"}], "difficulty": "易", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-13", "exam": "et111", "nums": [13], "form": "單題", "img": "img/et111-13.png", "source": "劉基《郁離子》", "author": "劉基", "genre": "寓言故事", "types": ["主旨寓意", "文意推論"], "passage": "女几之山，乾鵲所巢，有虎出于樸簌，鵲集而噪之。鴝鵒聞之，亦集而噪。鵯鶋見而問之曰：「虎行地者也，其如子何哉而噪之也？」鵲曰：「是嘯而生風，吾畏其顛吾巢，故噪而去之。」問於鴝鵒，鴝鵒無以對。鵯鶋笑曰：「鵲之巢木末也，畏風，故忌虎；爾穴居者也，何以噪為？」", "translation": "女几山上，是喜鵲築巢的地方。有隻老虎從樹叢中簌簌地走出來，喜鵲聚在一起對牠吵叫。八哥聽到了，也聚過來跟著吵叫。烏鴉看見了，問牠們說：「老虎是在地上走的，能把你們怎麼樣，為什麼要對牠叫呢？」喜鵲說：「牠一吼就會起風，我怕風吹翻我的巢，所以叫著要趕走牠。」烏鴉又問八哥，八哥答不出來。烏鴉笑著說：「喜鵲把巢築在樹梢，怕風，所以忌憚老虎；你是住在洞穴裡的，跟著叫什麼呢？」", "keywords": [{"w": "噪", "m": "吵雜地叫"}, {"w": "顛", "m": "使……翻倒"}, {"w": "木末", "m": "樹梢"}, {"w": "何以……為", "m": "為什麼要……呢"}], "questions": [{"n": 13, "qtype": "單選", "stem": "請閱讀並推論下文寓意，選出最接近現今社會現象的選項：", "options": {"A": "自由無下限，道德大淪喪", "B": "網軍帶風向，隨俗瞎起鬨", "C": "排隊拿優惠，人瘋小確幸", "D": "小道消息多，眾人樂八卦"}, "answer": "B", "explain": "喜鵲叫是有理由的（怕風吹翻巢），八哥跟著叫卻說不出理由——諷刺沒有自己的判斷、只會跟風的人。(A)講道德淪喪，無關。(B)有人帶風向，大家不明就裡跟著起鬨，正好像八哥，正確。(C)講追求小確幸，無關。(D)講愛聽八卦，重點不在盲從。", "skill": "寓言題找「被嘲笑的那個角色」錯在哪裡，再把它的缺點翻成現代說法。"}], "difficulty": "易", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-14", "exam": "et111", "nums": [14], "form": "單題", "img": "img/et111-14.png", "source": "對聯（詠屈原）", "author": "", "genre": "其他", "types": ["文化常識", "典故出處"], "passage": "大節仰忠貞，氣吐虹霓，天問九章歌浩蕩；修能明治亂，志存社稷，澤遺萬世頌離騷。", "translation": "他忠貞的大節令人景仰，氣勢如吐出彩虹，〈天問〉〈九章〉的歌聲浩大；他有美好的才能、明白治亂之道，心志在國家，恩澤留給萬世，人們傳頌〈離騷〉。", "keywords": [{"w": "天問、九章", "m": "屈原的作品"}, {"w": "修能", "m": "美好的才能，語出〈離騷〉「又重之以修能」"}], "questions": [{"n": 14, "qtype": "單選", "stem": "「大節仰忠貞，氣吐虹霓，天問九章歌浩蕩；修能明治亂，志存社稷，澤遺萬世頌□□。」依內容推斷這副對聯□□處，最適合填入的選項為何？", "options": {"A": "詩經", "B": "史記", "C": "論孟", "D": "離騷"}, "answer": "D", "explain": "上聯有「天問」「九章」，都是屈原的作品，再加上「忠貞」「志存社稷」，可知是詠屈原的對聯。下聯要對「天問九章」，填屈原的代表作〈離騷〉最合適，選(D)。(A)《詩經》是我國最早的詩歌總集，代表北方文學，不是屈原作品。(B)《史記》是司馬遷的史書。(C)《論語》《孟子》是孔孟之書。", "skill": "對聯題先從關鍵詞認出人物（天問、九章→屈原），再用上下聯對稱去填。"}], "difficulty": "易", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-15", "exam": "et111", "nums": [15], "form": "單題", "img": "img/et111-15.png", "source": "綜合（多篇古典詩）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "寫作手法"], "passage": "錦瑟無端五十弦，一弦一柱思華年。莊生曉夢迷蝴蝶，望帝春心託杜鵑。／籬落疏疏一徑深，樹頭花落未成陰。兒童急走追黃蝶，飛入菜花無處尋。／即心即佛眉拕地，非佛非心雙眼橫。蝴蝶夢中家萬里，子規枝上月三更。／白雲堆裡撿青槐，慣入深林鳥不猜。無意帶將花數朵，竟挑蝴蝶下山來。", "translation": "錦瑟無緣無故有五十根弦，每一弦每一柱都讓人追憶青春年華；莊周在清晨夢中迷失於化蝶，望帝把春天的哀怨寄託給杜鵑。／稀疏的籬笆旁一條小路伸向遠方，樹上的花落了、新葉還沒成蔭；孩子們跑著追黃色的蝴蝶，蝴蝶飛進黃色的菜花裡就找不到了。／（前兩句為禪語）夢中化作蝴蝶回到萬里外的家鄉，醒來只聽見子規在三更月下的枝頭啼叫。／在白雲深處撿拾青槐，常進深林，連鳥都不懷疑他；無意中帶了幾朵花，竟然挑著蝴蝶下山來。", "keywords": [{"w": "無端", "m": "無緣無故"}, {"w": "子規", "m": "杜鵑鳥"}, {"w": "猜", "m": "猜疑"}], "questions": [{"n": 15, "qtype": "單選", "stem": "文學藝術作品為了表現抽象意念，常用具體事物進行聯想及暗示。如以「踏花歸去馬蹄香」作為畫題，即是用一群蝴蝶翩翩飛舞於馬蹄之後的畫面，來具體表現看不見的花香氣味。下列選項的詩句中均有蝴蝶，何者最有可能也寓含這種聯想及暗示香味的作用？", "options": {"A": "錦瑟無端五十弦，一弦一柱思華年。莊生曉夢迷蝴蝶，望帝春心託杜鵑", "B": "籬落疏疏一徑深，樹頭花落未成陰。兒童急走追黃蝶，飛入菜花無處尋", "C": "即心即佛眉拕地，非佛非心雙眼橫。蝴蝶夢中家萬里，子規枝上月三更", "D": "白雲堆裡撿青槐，慣入深林鳥不猜。無意帶將花數朵，竟挑蝴蝶下山來"}, "answer": "D", "explain": "題目要的是：蝴蝶被花香吸引而跟著走，用「蝴蝶」暗示「香」。(A)李商隱〈錦瑟〉用莊周夢蝶的典故，談人生如夢、迷惘，與香味無關。(B)楊萬里〈宿新市徐公店〉寫黃蝶飛進黃菜花裡分不出來，是顏色相同，不是香味。(C)「蝴蝶夢中家萬里」也是用莊周夢蝶寫思鄉的夢，與香味無關。(D)擔子上無意帶了幾朵花，蝴蝶竟一路跟下山——蝴蝶是被花香引來的，和「馬蹄香」的手法相同，正確。", "skill": "看蝴蝶「為什麼出現」：是在追著東西走（香）、是融入顏色（色），還是典故（夢）。"}], "difficulty": "中", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-16", "exam": "et111", "nums": [16], "form": "單題", "img": "img/et111-16.png", "source": "綜合（詞語結構）", "author": "", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "欲以地事秦，猶如抱薪救火。／去國懷鄉，憂讒畏譏，滿目蕭然。", "translation": "想用割地來侍奉秦國，就像抱著柴草去救火。／離開京城、懷念家鄉，擔心被人說壞話、害怕被人批評，滿眼都是蕭條景象。", "keywords": [{"w": "抱薪救火", "m": "抱著柴去救火，比喻方法錯誤，反使災害擴大"}, {"w": "讒", "m": "說壞話陷害"}, {"w": "譏", "m": "批評、譏諷"}], "questions": [{"n": 16, "qtype": "單選", "stem": "「選賢舉能」第二、三字可調換為「選舉賢能」後，意義並無改變。下列「」內詞語以此法調換後，何者意義產生改變？", "options": {"A": "先民「翻山越嶺」，長途跋涉", "B": "欲以地事秦，猶如「抱薪救火」", "C": "去國懷鄉，「憂讒畏譏」，滿目蕭然", "D": "我那師父「呼風喚雨」，只在翻掌之間"}, "answer": "B", "explain": "「選賢舉能」是兩組「動詞＋名詞」並列，兩個動詞意思相近、兩個名詞也相近，所以能合併成「選舉＋賢能」。(A)翻越＋山嶺，意思不變。(B)「抱薪救火」是「抱著柴」去「救火」，前後是先後、目的關係，「抱」和「救」不同類，換成「抱救薪火」就講不通了，意義改變，選(B)（出自蘇洵〈六國論〉）。(C)〈岳陽樓記〉憂畏＋讒譏，不變。(D)呼喚＋風雨，不變。", "skill": "能互換的條件：兩個動詞同義、兩個名詞同類；一換就不通的，就是意義改變的那個。"}], "difficulty": "中", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-18", "exam": "et111", "nums": [18], "form": "單題", "img": "img/et111-18.png", "source": "應用文（信封書寫）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "李經理最大鈞啟", "translation": "請李最大經理拆信（「鈞啟」用於長官、上司）", "keywords": [{"w": "鈞啟", "m": "請收信人開信，用於長官、上司"}, {"w": "側書", "m": "名字寫小一點、偏右，表示尊敬或謙虛"}], "questions": [{"n": 18, "qtype": "單選", "stem": "小強是大學應屆畢業生，想在畢業前將個人履歷資料，郵寄給航海王公司人事部經理李最大。請問下列四種信封中間欄的寫法，何者最適當？（A：李 經理 最大〔小字〕 鈞啟／B：李 經理 最大〔小字〕 敬啟／C：李 經理〔小字〕 最大 鈞啟／D：李 經理〔小字〕 最大 敬啟）", "options": {"A": "(A)圖", "B": "(B)圖", "C": "(C)圖", "D": "(D)圖"}, "answer": "A", "explain": "信封中路有兩個判斷點。第一是啟封詞：「啟」是請收信人打開信，對長官、上司用「鈞啟」；「敬啟」等於要對方恭敬地拆信，敬意放錯了方向，不能用在收信人身上，所以(B)(D)錯。第二是職稱位置：職稱放在姓與名之間時，姓和職稱照常大字書寫，名字寫小、偏右側書，表示不直呼對方名字的敬意；(C)反而把對方的職稱縮小，主客顛倒。所以正確的是(A)。", "skill": "信封中路先看啟封詞（長官用鈞啟），再看大小字：要縮小的是名字，不是對方的職稱。"}], "difficulty": "中", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-19", "exam": "et111", "nums": [19], "form": "單題", "img": "img/et111-19.png", "source": "應用文（題辭）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "椿萱並茂／福壽全歸／鶯遷喬木／蓬蓽生輝", "translation": "椿萱並茂：父母都健在長壽。／福壽全歸：輓男性長者。／鶯遷喬木：賀遷居、升遷。／蓬蓽生輝：謙稱貴客使寒舍增光。", "keywords": [{"w": "椿萱並茂", "m": "椿指父、萱指母，祝賀雙親都健在長壽"}, {"w": "福壽全歸", "m": "輓男性長者的題辭"}, {"w": "鶯遷喬木", "m": "黃鶯飛上高樹，賀人遷居或升遷"}, {"w": "蓬蓽生輝", "m": "謙詞，指貴客來訪使寒舍增光"}], "questions": [{"n": 19, "qtype": "單選", "stem": "閱讀下列對話，判斷(甲)、(乙)依序最適合填入的詞語為何？（恭喜貴府，(甲)，令尊、令堂今年要同過七十大壽了。／感謝感謝！聽說您最近搬了新家，也恭喜您(乙)。）", "options": {"A": "椿萱並茂／鶯遷喬木", "B": "福壽全歸／鶯遷喬木", "C": "椿萱並茂／蓬蓽生輝", "D": "福壽全歸／蓬蓽生輝"}, "answer": "A", "explain": "(甲)父母一起過七十大壽，要用「椿萱並茂」（椿＝父，萱＝母，都健在）；「福壽全歸」是用在男性長輩過世的輓辭，用在祝壽非常失禮。(乙)賀人搬新家用「鶯遷喬木」；「蓬蓽生輝」是主人自謙，說客人來讓我家增光，不能拿來恭喜別人。所以選(A)。", "skill": "題辭先分「賀」與「輓」，再分「說自己」與「說別人」，謙詞不能送人。"}], "difficulty": "易", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-20", "exam": "et111", "nums": [20], "form": "單題", "img": "img/et111-20.png", "source": "應用文（對聯）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "甲：平理若衡照辭如鏡／動墨橫錦搖筆散珠　乙：宴爾嘉賓既多且旨／樂至君子喜壽爾康　丙：進屋來虬髯太歲／出門去白面書生　丁：春風大雅能容物／秋水文章不染塵", "translation": "甲：評論道理像秤一樣公平，鑑賞文辭像鏡子一樣清楚／一動墨就像鋪開錦繡，一揮筆就像散落珍珠。乙：宴請嘉賓，酒菜又多又美／君子快樂，祝您長壽安康。丙：進門時是滿臉鬍子的凶神，出門時成了白淨的書生。丁：像春風一樣高雅寬厚能包容萬物，像秋水一樣的文章不沾染塵俗。", "keywords": [{"w": "衡", "m": "秤"}, {"w": "旨", "m": "味美"}, {"w": "虬髯", "m": "捲曲的鬍子"}], "questions": [{"n": 20, "qtype": "單選", "stem": "下列四副對聯，適合貼在書房的選項是：", "options": {"A": "甲乙", "B": "乙丙", "C": "丙丁", "D": "甲丁"}, "answer": "D", "explain": "甲講評論文理、揮毫寫作（語出《文心雕龍》），適合書房。乙「宴爾嘉賓」「既多且旨」講宴客酒菜，適合宴會、餐廳或喜慶場合，不是書房。丙「進屋來鬍子滿臉，出門變白面書生」，是理髮店。丁講胸襟高雅、文章清新脫俗，適合書房。答案甲丁，選(D)。", "skill": "行業對聯找關鍵詞：筆墨文章→書房，酒菜賓客→宴會，鬍子變臉→理髮。"}], "difficulty": "易", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-21", "exam": "et111", "nums": [21], "form": "單題", "img": "img/et111-21.png", "source": "綜合（宋詞）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文化常識"], "passage": "莫道不銷魂，簾卷西風，人比黃花瘦。／大江東去，浪淘盡，千古風流人物。／稻花香裡說豐年，聽取蛙聲一片。／無可奈何花落去，似曾相識燕歸來。", "translation": "別說這不令人傷神，西風捲起簾子，人比菊花還要消瘦。／長江向東奔流，浪花淘盡了千古的英雄人物。／在稻花香氣中談論著豐收的年景，耳邊聽見一片蛙鳴。／花要凋落是無可奈何的事，燕子歸來卻好像曾經相識。", "keywords": [{"w": "銷魂", "m": "極度哀愁、傷神"}, {"w": "黃花", "m": "菊花"}], "questions": [{"n": 21, "qtype": "單選", "stem": "宋詞婉約者欲其辭情蘊藉，豪放者欲其氣象恢弘。下列表格中的宋詞引文之風格歸類，何者正確？", "options": {"A": "婉約：莫道不銷魂，簾卷西風，人比黃花瘦／豪放：大江東去，浪淘盡，千古風流人物", "B": "婉約：稻花香裡說豐年，聽取蛙聲一片／豪放：無可奈何花落去，似曾相識燕歸來", "C": "婉約：無可奈何花落去，似曾相識燕歸來／豪放：莫道不銷魂，簾卷西風，人比黃花瘦", "D": "婉約：大江東去，浪淘盡，千古風流人物／豪放：稻花香裡說豐年，聽取蛙聲一片"}, "answer": "A", "explain": "四句分別是：李清照〈醉花陰〉「人比黃花瘦」——細膩相思，婉約；蘇軾〈念奴嬌‧赤壁懷古〉「大江東去」——氣象壯闊，豪放；晏殊〈浣溪沙〉「無可奈何花落去」——含蓄惜春，婉約；辛棄疾〈西江月‧夜行黃沙道中〉「稻花香裡說豐年」——清新的田園小景，既不屬典型婉約也不是豪放。(A)兩欄都對，正確。(B)把晏殊放進豪放，錯。(C)把李清照放進豪放，錯。(D)把蘇軾的「大江東去」放進婉約，錯。", "skill": "婉約看「細、愁、花、簾」，豪放看「大江、千古、英雄」，先抓最明顯的兩句就能刪選項。"}], "difficulty": "易", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-22", "exam": "et111", "nums": [22], "form": "單題", "img": "img/et111-22.png", "source": "文學常識（書目）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "幽夢影", "m": "清代張潮的小品文集"}, {"w": "韓昌黎文集", "m": "韓愈文集"}, {"w": "袁中郎全集", "m": "袁宏道文集，公安派代表"}, {"w": "三國志", "m": "西晉陳壽所著史書"}], "questions": [{"n": 22, "qtype": "單選", "stem": "下表是4位同學依報告主題所借閱的書籍，哪些同學借的書籍正確？（索隆：魏晉南北朝小說—幽夢影；喬巴：唐代古文運動—韓昌黎文集；娜美：明代公安派—袁中郎全集；布魯克：清代章回小說—三國志）", "options": {"A": "索隆、布魯克", "B": "索隆、喬巴", "C": "喬巴、娜美", "D": "娜美、布魯克"}, "answer": "C", "explain": "逐一核對：索隆查魏晉南北朝小說，卻借清代張潮的小品《幽夢影》，錯（該借《世說新語》《搜神記》）。喬巴查唐代古文運動，借韓愈的《韓昌黎文集》，對。娜美查明代公安派，借袁宏道（字中郎）的《袁中郎全集》，對。布魯克查清代章回小說，借《三國志》，那是西晉陳壽的史書，錯（《三國演義》也是明代小說）。正確的是喬巴、娜美，選(C)。", "skill": "書目題先把每本書的「朝代＋文類」標出來，再對報告主題；《三國志》與《三國演義》最常被拿來設陷阱。"}], "difficulty": "易", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-23", "exam": "et111", "nums": [23, 24], "form": "題組", "img": "img/et111-23.png", "source": "王昌齡〈芙蓉樓送辛漸〉、蘇紹連〈〈芙蓉樓送辛漸〉變奏曲〉", "author": "王昌齡", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀"], "passage": "寒雨連江夜入吳，平明送客楚山孤。洛陽親友如相問，一片冰心在玉壺。", "translation": "冷雨連著江面，夜裡下進了吳地；天亮時送別客人，只剩楚山孤零零地立著。洛陽的親友如果問起我，就說我的心仍像玉壺裡的一片冰一樣純潔。", "keywords": [{"w": "平明", "m": "天剛亮"}, {"w": "楚山", "m": "楚地的山，這裡也寫出作者的孤獨"}, {"w": "冰心在玉壺", "m": "比喻心地純潔、品格清白"}], "questions": [{"n": 23, "qtype": "單選", "stem": "關於王昌齡詩的詮釋，下列何者最適當？", "options": {"A": "辛漸此行前往的地點應是洛陽", "B": "王昌齡託辛漸轉交玉壺給洛陽親友", "C": "楚山比喻前往洛陽的艱辛路途", "D": "以冰心表達對人際關係的灰心失意"}, "answer": "A", "explain": "「洛陽親友如相問」表示辛漸要去洛陽，到了會見到作者的親友，所以(A)正確。(B)「冰心在玉壺」是比喻自己心地清白，不是真的有一個玉壺要轉交，錯。(C)「楚山孤」寫送走朋友後山影孤單，也映出作者的孤寂，不是比喻路途艱辛，錯。(D)冰心是純潔，不是灰心，錯。", "skill": "詩中的「物」先問是實寫還是比喻；冰、玉這類意象多半是比喻品格。"}, {"n": 24, "qtype": "單選", "stem": "下列①②是甲、乙兩詩寫作手法的敘述，請選出正確選項：①兩詩皆以時間為順序，由早敘寫至晚　②兩詩皆敘明在春日寒雨中送別朋友的情景", "options": {"A": "①錯誤，②正確", "B": "①正確，②錯誤", "C": "①②皆正確", "D": "①②皆錯誤"}, "answer": "D", "explain": "①甲詩從「夜入吳」寫到「平明送客」，是由夜晚到天亮，不是由早到晚；乙詩是送別當下與想像，也沒有由早到晚的順序，錯誤。②兩首詩都只寫了「寒雨」，沒有寫明是春天；乙詩的「寒雨」更是記憶與想像中的情景，錯誤。兩者都錯，選(D)。", "skill": "判斷「皆」字題，只要找到一首不符合就整句錯；時間詞（夜、平明）要看清楚先後。"}], "difficulty": "中", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-25", "exam": "et111", "nums": [25, 26], "form": "題組", "img": "img/et111-25.png", "source": "楊名時〈徐霞客遊記序〉", "author": "楊名時", "genre": "書信序跋", "types": ["字詞解釋", "主旨寓意"], "passage": "霞客之遊也，升降於危崖絕壑，搜探於蛇龍窟宅，亙古人跡未到之區，不惜捐軀命，多方竭慮以赴之，期於必造其域，必窮其奧而後止。學者之於道也，若覃思鼓勇亦如霞客之於山水，則亦何深之不窮，何遠之不屆。", "translation": "徐霞客的遊歷，在險峻的山崖、深谷間上上下下，到蛇龍藏身的洞穴裡搜尋探查，那些自古沒有人跡到過的地方，他不惜犧牲性命，想盡辦法前往，一定要到達那個地方、走遍它最幽深隱密之處才肯停止。求學的人對於道理，如果也能像徐霞客對山水那樣深入思考、鼓起勇氣，那麼還有什麼深奧的道理不能窮究，還有什麼遙遠的境界不能到達呢？", "keywords": [{"w": "絕壑", "m": "深谷"}, {"w": "亙古", "m": "自古以來"}, {"w": "造", "m": "到達"}, {"w": "奧", "m": "幽深隱密之處"}, {"w": "覃思", "m": "深思"}, {"w": "屆", "m": "到達"}], "questions": [{"n": 25, "qtype": "單選", "stem": "上文「」內詞義的正確解釋，依序是：（期於必「造」其域，必窮其「奧」而後止）", "options": {"A": "培養／事物的核心", "B": "創建／深妙事理", "C": "建設／室的西南角", "D": "到訪／幽深隱祕"}, "answer": "D", "explain": "「必造其域」是一定要到達那個地方，「造」是到訪、到達（如「登門造訪」）；「必窮其奧」是走遍那裡最深處，「奧」是幽深隱祕之處。答案(D)。(A)培養、(B)創建、(C)建設都不是到達；「室的西南角」是「奧」的本義，但這裡說的是山水深處，不合；「深妙事理」是用在學問上的引申義，這句講的是霞客探險，也不合。", "skill": "字義題把候選意思代回句子：「一定要＿＿那個區域」，只有「到」最通。"}, {"n": 26, "qtype": "單選", "stem": "下列選項，何者最符合上文意旨？", "options": {"A": "徐霞客朝聞道夕死可矣的堅持，為有志者之典範", "B": "讀萬卷書還要行萬里路，才是成功者的不二法門", "C": "旅遊者須累積探訪古蹟經驗，才能達到窮奧境界", "D": "徐霞客深思勇敢不放棄的精神，值得學習者效法"}, "answer": "D", "explain": "文章前半寫霞客不怕危險、一定要到達深處；後半點題：學者求道若能「覃思鼓勇亦如霞客之於山水」，就沒有到不了的境界。(A)「朝聞道夕死」是說求道之急切，霞客追求的是山水，而且文章重點在勸學者效法，錯。(B)文中沒有比較讀書與旅行，錯。(C)文中沒說要累積探訪古蹟的經驗，錯。(D)深思、勇敢、不放棄，值得學習者效法，正確。", "skill": "序文常「先說人、後說理」，主旨在轉到「學者」的那一句。"}], "difficulty": "易", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-27", "exam": "et111", "nums": [27, 28, 29], "form": "題組", "img": "img/et111-27.png", "source": "梁章鉅《浪跡續談》", "author": "梁章鉅", "genre": "筆記小品", "types": ["文意推論", "主旨寓意", "句意理解"], "passage": "余官江蘇時，往來丹徒河干甚屢，習見一尼庵，頗冷落，近年過之，則門戶斬新，香火甚盛，相距不過十餘年耳。偶因夜泊，與庵旁一老翁詰其顛末，翁年逾七十矣，慨然曰：「凡寺觀之盛衰，雖關氣運，而人事亦與有功焉。此庵初不振，一日遇都天廟會，甚熱鬧，庵前趕會之船不少，有美婦趁船到此登岸，一足誤陷汙泥，急行入庵，眾目皆覩，而舟子忽譁，言婦給船錢一百，乃是冥資，急入庵理論，則庵中並無此婦。方與庵尼詰論，舟子忽見座上大士像一足徧染汙泥，乃大驚悟，伏地叩首，即將冥資焚於爐中，於是闐塞入庵聚觀者，無不合聲誦佛，信為大士顯靈。適舟中人又來報，香氣四騰，眾益駭異，遠近傳聞，自此施捨沓至，香火遂煊赫至今。實則婦與舟子皆庵尼所夥串，婦一入庵，即卸裝改容，而以汙泥移入大士足下耳。」", "translation": "我在江蘇做官時，常常往來丹徒的河岸，常見到一座尼姑庵，相當冷清；近年再經過，卻門戶煥然一新，香火很旺，前後不過十幾年。有一次夜裡停船，向庵旁一位老翁打聽事情的始末，老翁七十多歲了，感慨地說：「寺廟道觀的興衰，雖然和氣運有關，但人為因素也有功勞。這座庵起初不興旺，有一天遇上都天廟會，非常熱鬧，庵前趕廟會的船很多。有一位美麗婦人搭船到這裡上岸，一隻腳不小心陷進汙泥，急忙走進庵裡，大家都看見了。船夫忽然大叫，說婦人給的一百文船錢竟是冥紙，急忙進庵理論，庵裡卻沒有這位婦人。正和尼姑爭論時，船夫忽然看見座上觀音像的一隻腳沾滿汙泥，於是大為驚悟，趴在地上磕頭，立刻把冥紙燒在香爐裡。於是擠滿庵中圍觀的人，沒有不齊聲念佛、相信是觀音顯靈的。剛好船上的人又跑來說船上香氣四溢，大家更加驚奇，遠近傳開，從此捐獻接連而來，香火就旺盛到現在。其實婦人和船夫都是尼姑串通好的，婦人一進庵就卸妝換裝，再把汙泥抹到觀音腳下罷了。」", "keywords": [{"w": "河干", "m": "河岸"}, {"w": "顛末", "m": "始末"}, {"w": "冥資", "m": "冥紙"}, {"w": "大士", "m": "觀音菩薩"}, {"w": "闐塞", "m": "擠滿"}, {"w": "沓至", "m": "接連而來"}, {"w": "夥串", "m": "串通"}], "questions": [{"n": 27, "qtype": "單選", "stem": "依上文，舟子「乃大驚悟」的原因為何？", "options": {"A": "氣憤跑進尼庵理論，卻反被滿地汙泥困住", "B": "發現乘船婦人欺詐，所支付船資竟為冥錢", "C": "認為女子是菩薩化身，親眼見到大士顯靈", "D": "原本以為是一般寺廟，闖進才驚覺是尼庵"}, "answer": "C", "explain": "緊接在「乃大驚悟」前面的是「忽見座上大士像一足徧染汙泥」——腳沾泥的婦人＝腳沾泥的觀音，所以船夫（表演出來）「恍然大悟」那婦人是觀音化身。(A)沒有被汙泥困住，錯。(B)冥錢是他進庵理論的原因，不是驚悟的原因，錯。(C)正確。(D)文中沒有這回事，錯。", "skill": "問某動作的原因，看緊鄰在它前面的那件事。"}, {"n": 28, "qtype": "單選", "stem": "依上文，推論尼庵由冷落到香火鼎盛的原因，下列何者正確？", "options": {"A": "地理位置絕佳", "B": "宣傳手法精妙", "C": "佛像雕刻傳神", "D": "高僧弘法加持"}, "answer": "B", "explain": "老翁說「人事亦與有功焉」，結尾揭露是尼姑串通婦人、船夫，趁廟會人多上演「觀音顯靈」，再讓人「遠近傳聞」——是一場精心設計的宣傳。(A)位置一直沒變，以前照樣冷落，錯。(C)佛像本身沒提，錯。(D)沒有高僧，錯。", "skill": "結尾的「實則……」往往是作者真正想說的答案。"}, {"n": 29, "qtype": "單選", "stem": "若要為上文訂一個標題，下列何者最適切？", "options": {"A": "尼庵裡應外合設巧計", "B": "舟子識破神蹟假傳聞", "C": "世人不問蒼生問鬼神", "D": "勸世諸惡莫作終有報"}, "answer": "A", "explain": "尼姑在庵內、婦人和船夫在外配合，正是「裡應外合設巧計」，選(A)。(B)船夫是同夥，不是識破的人，錯。(C)出自李商隱〈賈生〉，諷刺君王不關心百姓只問鬼神，和本文主題不同，錯。(D)文中沒有惡有惡報的結局，錯。", "skill": "訂標題要涵蓋全文的「關鍵人物＋關鍵事件」，只寫到局部或扭曲角色的都刪。"}], "difficulty": "中", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-30", "exam": "et111", "nums": [30, 31, 32], "form": "題組", "img": "img/et111-30.png", "source": "蒲松齡《聊齋志異‧狼》", "author": "蒲松齡", "genre": "筆記小品", "types": ["文意推論", "句意理解", "比較閱讀"], "passage": "【甲】有屠人貨肉歸，日已暮，欻一狼來，瞰擔上肉，似甚垂涎，隨屠尾行數里。屠懼，示之以刃，少卻；及走，又從之。屠思狼所欲者肉，不如懸諸樹而早取之。遂鉤肉，翹足掛樹間，示以空擔。狼乃止。屠歸。昧爽往取肉，遙望樹上懸巨物，似人縊死狀，大駭。逡巡近視，則死狼也。仰首細審，見狼口中含肉，鉤刺狼齶，如魚吞餌。時狼皮價昂，直十餘金，屠小裕焉。緣木求魚，狼則罹之，是可笑也！【乙】一屠晚歸，擔中肉盡，止剩骨。途遇兩狼綴行甚遠。屠懼，投以骨，一狼得骨止，一狼又從；復投之，後狼止而前狼又至；骨已盡，而兩狼並驅如故。屠大窘，恐前後受其敵。顧野有麥場，場主以薪積其中，苫蔽成丘。屠乃奔倚其下，弛擔待刀。狼不敢前，眈眈相向。少時，一狼徑去；其一犬坐於前，久之，目似瞑，意暇甚。屠暴起，以刀劈狼首，又數刀斃之。轉視積薪後，一狼洞其中，意將隧入以攻其後也。身已半入，露其尾，屠自後斷其股，亦斃之。方悟前狼假寐，蓋以誘敵。狼亦黠矣！而頃刻兩斃，禽獸之變詐幾何哉，止增笑耳！", "translation": "【甲】有個屠夫賣完肉回家，天已經黑了，忽然來了一匹狼，盯著擔子上的肉，好像很嘴饞，跟在屠夫後面走了好幾里。屠夫害怕，拿刀給牠看，牠稍微退後；一走，又跟上來。屠夫想，狼要的是肉，不如把肉掛在樹上，明天早上再來拿。於是用鉤子鉤住肉，踮起腳掛在樹枝間，再把空擔子給狼看。狼才停下來。屠夫回家了。天剛亮去取肉，遠遠看見樹上掛著一個大東西，像人上吊的樣子，嚇了一大跳。猶豫地走近一看，原來是死狼。抬頭仔細看，狼嘴裡含著肉，鉤子刺穿了狼的上顎，就像魚吞了魚餌。當時狼皮價格很高，值十幾兩銀子，屠夫因此小小發了一筆財。「爬到樹上找魚」本來是不可能的事，狼卻真的落得這種下場（在樹上像魚一樣被鉤住），真是可笑！【乙】一個屠夫晚上回家，擔子裡的肉賣完了，只剩下骨頭。路上遇到兩匹狼，緊跟著走了很遠。屠夫害怕，丟骨頭給牠們，一匹狼得到骨頭停下，另一匹還跟著；又丟骨頭，後面那匹停下，前面那匹又跟上來；骨頭丟完了，兩匹狼還是一起跟著。屠夫非常窘迫，怕前後同時受到攻擊。看到野地裡有個麥場，場主把柴草堆在中間，覆蓋成小山。屠夫就跑過去靠在柴堆下，放下擔子拿起刀。狼不敢上前，瞪著眼睛對著他。一會兒，一匹狼走開了；另一匹像狗一樣蹲坐在前面，過了很久，眼睛好像閉上了，神情十分悠閒。屠夫突然跳起，用刀劈狼頭，又砍了幾刀把牠殺死。轉頭看柴堆後面，另一匹狼正在打洞，想要鑽進去從背後攻擊。身體已經進去一半，露出尾巴，屠夫從後面砍斷牠的大腿，也殺死了牠。屠夫這才明白前面那匹狼假裝睡覺，是用來引誘敵人的。狼也夠狡猾了！可是一下子兩匹都被殺死，禽獸的欺詐手段能有多少呢？只是增加笑料罷了！", "keywords": [{"w": "欻", "m": "忽然"}, {"w": "瞰", "m": "向下看、盯著"}, {"w": "昧爽", "m": "天剛亮"}, {"w": "逡巡", "m": "猶豫不前"}, {"w": "綴行", "m": "緊跟著走"}, {"w": "弛擔", "m": "放下擔子"}, {"w": "犬坐", "m": "像狗一樣蹲坐"}, {"w": "瞑", "m": "閉眼"}, {"w": "隧", "m": "挖地道"}, {"w": "黠", "m": "狡猾"}], "questions": [{"n": 30, "qtype": "單選", "stem": "下列對上文畫底線處的解說，何者正確？（①瞰擔上肉，似甚垂涎，隨屠尾行數里　②屠思狼所欲者肉，不如懸諸樹而早取之　③少時，一狼徑去；其一犬坐於前，久之，目似瞑，意暇甚　④轉視積薪後，一狼洞其中，意將隧入以攻其後也）", "options": {"A": "①描寫狼嗜肉的本性", "B": "②展現屠戶殺狼的巧詐意圖", "C": "③刻畫狼與犬的狡猾", "D": "④說明屠戶引狼入洞的機智"}, "answer": "A", "explain": "(A)①盯著肉、很饞、一路跟著，寫出狼貪肉的本性，正確。(B)②屠夫只是想把肉掛高、擺脫狼，明早再拿，並沒有要殺狼的計謀（狼死是意外），錯。(C)③「犬坐」是「像狗一樣坐著」，主角只有狼，沒有狗，錯。(D)④是狼自己打洞想從背後偷襲，不是屠夫引牠入洞，錯。", "skill": "「犬坐、人立」這類名詞放在動詞前，常是「像……一樣」，不是真的出現狗或人。"}, {"n": 31, "qtype": "單選", "stem": "根據甲、乙二文，下列表格中✓處的情節與故事內容相符的選項是：（A：時間從晚上到次日早晨—甲文；狼有攻擊屠戶意圖—甲文　B：時間—乙文；屠戶故意設陷阱殺狼—甲文　C：時間—甲文；狼有攻擊意圖—乙文　D：狼有攻擊意圖—甲文；屠戶設陷阱—乙文）", "options": {"A": "(A)", "B": "(B)", "C": "(C)", "D": "(D)"}, "answer": "C", "explain": "逐項判斷：時間從晚上到隔天早上——甲文「日已暮」到「昧爽往取肉」，符合；乙文只寫晚上，不符合。狼有攻擊屠戶的意圖——甲文的狼只想要肉，屠夫一掛肉牠就停下；乙文的狼一匹假睡誘敵、一匹挖洞「攻其後」，有攻擊意圖。屠戶故意設陷阱殺狼——甲文掛肉不是為了殺狼；乙文屠夫是見機反擊，也不是事先設陷阱，兩篇都不符合。所以只有(C)（時間－甲、攻擊意圖－乙）完全正確。", "skill": "表格勾選題，一格一格回原文找證據，只要有一格不符就刪掉那個選項。"}, {"n": 32, "qtype": "單選", "stem": "作者在甲、乙二文的文末皆以「笑」作結，其涵義最有可能是下列何者？", "options": {"A": "藉屠戶的行為嘲笑世人聰明反被聰明誤", "B": "都表明故事僅為道聽塗說不如一笑置之", "C": "甲文「是可笑也」，指屠戶早已識破狼的伎倆而將計就計", "D": "乙文「止增笑耳」，在笑狼的處心積慮也敵不過人的智慧"}, "answer": "D", "explain": "兩篇被笑的都是「狼」：甲文狼想吃肉反被鉤死，像「緣木求魚」；乙文狼用盡詐術，卻一下子兩匹都死了。(A)被笑的是狼不是屠夫，錯。(B)作者是借故事諷刺，不是說故事不可信，錯。(C)甲文屠夫並沒有識破什麼，掛肉只是想脫身，狼的死是意外，錯。(D)乙文狼的詭計敵不過人，只增加笑料，正確。", "skill": "文末評語的「笑」先問：笑的是誰？再問：笑他什麼？"}], "difficulty": "中", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-36", "exam": "et111", "nums": [36, 37, 38], "form": "題組", "img": "img/et111-36.png", "source": "司馬光〈訓儉示康〉（節錄）", "author": "司馬光", "genre": "書信序跋", "types": ["寫作手法", "比較閱讀", "文意推論"], "passage": "張文節為相，自奉養如為河陽掌書記時，所親或規之曰：「公今受俸不少，而自奉若此。公雖自信清約，外人頗有公孫布被之譏。公宜少從眾。」公歎曰：「吾今日之俸，雖舉家錦衣玉食，何患不能？顧人之常情，由儉入奢易，由奢入儉難。吾今日之俸豈能常有？身豈能常存？一旦異於今日，家人習奢已久，不能頓儉，必致失所。豈若吾居位、去位、身存、身亡，常如一日乎？」嗚呼！大賢之深謀遠慮，豈庸人所及哉！御孫曰：「儉，德之共也；侈，惡之大也。」共，同也；言有德者皆由儉來也。夫儉則寡欲：君子寡欲，則不役於物，可以直道而行；小人寡欲，則能謹身節用，遠罪豐家。故曰：「儉，德之共也。」侈則多欲：君子多欲則貪慕富貴，枉道速禍；小人多欲則多求妄用，敗家喪身；是以居官必賄，居鄉必盜。故曰：「侈，惡之大也。」", "translation": "張文節當宰相時，生活供養仍和他在河陽當掌書記時一樣，親近的人有的勸他說：「您現在俸祿不少，生活卻這樣簡樸。您雖然自認清廉儉約，外人卻頗有說您像公孫弘蓋布被子沽名釣譽的譏諷。您應該稍微隨俗一點。」張公嘆氣說：「以我現在的俸祿，即使全家穿錦衣、吃美食，有什麼做不到的？但人之常情，從節儉變奢侈容易，從奢侈變節儉困難。我現在的俸祿哪能永遠都有？身體哪能永遠存在？一旦和今天不同，家人奢侈慣了，不能一下子節儉，一定會流離失所。哪比得上我無論在位、離職、活著、死後，生活都像一天那樣始終如一呢？」唉！大賢人的深謀遠慮，哪是平庸的人比得上的！御孫說：「節儉是各種美德共同的根源；奢侈是最大的罪惡。」共，是同的意思；是說有德的人都是從節儉來的。節儉就會少欲望：君子少欲望，就不會被外物役使，可以依正道行事；一般人少欲望，就能謹慎持身、節省用度，遠離罪過、使家境富足。所以說「節儉是美德共同的根源」。奢侈就會多欲望：君子多欲望就會貪慕富貴，違背正道而招來災禍；一般人多欲望就會多所求取、任意花費，敗壞家業、喪失性命；因此做官的一定貪汙受賄，住在鄉里的一定偷盜。所以說「奢侈是最大的罪惡」。", "keywords": [{"w": "自奉養", "m": "自己的生活供養"}, {"w": "規", "m": "勸告"}, {"w": "公孫布被", "m": "漢代公孫弘當丞相卻蓋布被，被批評虛偽"}, {"w": "顧", "m": "但是"}, {"w": "失所", "m": "失去安身之處"}, {"w": "共", "m": "同，共同的根源"}, {"w": "役於物", "m": "被外物役使"}, {"w": "速禍", "m": "招來災禍"}], "questions": [{"n": 36, "qtype": "單選", "stem": "甲文對節儉之德的議論手法，下列何者正確？", "options": {"A": "以張文節的事例與御孫的言例作主要論據", "B": "以張文節和御孫對節儉的觀點作正反對比", "C": "以張文節及御孫為例進行互為因果的論證", "D": "以先議後敘的方式陳述節儉美德之重要性"}, "answer": "A", "explain": "甲文先敘張文節堅持儉樸的故事（事例），再引御孫的名言「儉，德之共也；侈，惡之大也」（言例）並加以闡述。(A)事例＋言例作論據，正確。(B)兩人都主張節儉，立場相同，不是正反對比，錯。(C)兩個例子是並列支持論點，沒有互為因果，錯。(D)是先敘（張文節故事）後議（說明儉與侈），順序相反，錯。", "skill": "分辨論據：講某人做過什麼＝事例，引某人說過的話＝言例。"}, {"n": 37, "qtype": "單選", "stem": "下列甲文中的文句，何者最符合乙文「棘輪效應」的定義？", "options": {"A": "由儉入奢易，由奢入儉難", "B": "儉，德之共也；侈，惡之大也", "C": "小人寡欲，則能謹身節用，遠罪豐家", "D": "君子寡欲，則不役於物，可以直道而行"}, "answer": "A", "explain": "棘輪效應＝消費習慣「易於向上而難於向下調整」。(A)從節儉變奢侈容易、從奢侈變節儉困難，完全對應，正確。(B)是對節儉、奢侈的道德評價，不是消費習慣的方向性，錯。(C)(D)講少欲望的好處，沒有「易上難下」的概念，錯。", "skill": "跨文本對讀先把現代名詞濃縮成一句話（易上難下），再到古文中找同樣結構的句子。"}, {"n": 38, "qtype": "單選", "stem": "根據乙文，下列何者最適合以「棘輪效應」來解釋？", "options": {"A": "箕子對紂王說：您用了象牙筷子，就一定不會用陶杯而會用玉杯；用了象牙筷和玉杯，就一定不會吃粗食而會吃高貴的食物", "B": "庖丁對文惠君說：技術一般的廚師每月換一把刀，技術好的廚師每年換一把刀，我這把刀用了十九年，刀刃就像新磨的一樣", "C": "《朱子治家格言》說：吃每一碗飯、穿每一件衣服，都要想到這些都是不容易得到的，所以一定要以儉約的生活來自我要求", "D": "馮諼對孟嘗君說：狡兔有三個洞窟，也才只能自保。現在您只有一個洞窟，還不能高枕無憂，就讓我為您再鑿挖兩個洞窟吧"}, "answer": "A", "explain": "(A)出自《韓非子》箕子見紂王用象牙筷而憂心：一旦享受升級，就回不去，只會越來越奢侈，正是消費「只能往上調」的棘輪效應，正確。(B)庖丁講技術高超、順應自然，與消費無關。(C)是勸人節儉，沒有「易上難下」的現象。(D)狡兔三窟講預留退路，與消費習慣無關。", "skill": "應用題先確認選項有沒有「消費升級後回不去」的情節，沒有就刪。"}], "difficulty": "中", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-39", "exam": "et111", "nums": [39, 40, 41], "form": "題組", "img": "img/et111-39.png", "source": "梁實秋〈書房〉（節錄）", "author": "梁實秋", "genre": "其他", "types": ["句意理解", "文意推論", "寫作手法"], "passage": "張華遊於洞宮，遇一人引至一處。別是天地，每室各有奇書，華歷觀諸室書，皆漢以前事，多所未聞者，問其地，曰：「瑯嬛福地也。」／丈夫擁有萬卷書，何假南面百城！", "translation": "張華在洞府中遊覽，遇到一個人帶他到一個地方。那裡別有天地，每間屋子都有奇書，張華一一看遍各室的書，都是漢代以前的事，很多是從沒聽過的，問這是什麼地方，對方說：「這是瑯嬛福地。」／大丈夫擁有一萬卷書，哪裡還需要當諸侯、統治上百座城池！", "keywords": [{"w": "瑯嬛福地", "m": "神話中天帝藏書的地方，比喻理想的書房"}, {"w": "何假", "m": "何須、哪裡需要"}, {"w": "南面百城", "m": "面南稱王、統治百城，指顯赫的權位"}, {"w": "庋藏", "m": "收藏"}], "questions": [{"n": 39, "qtype": "單選", "stem": "依文中對「丈夫擁有萬卷書，何假南面百城」的理解，作者認為說這句話的人應是：", "options": {"A": "胸無點墨，欺世盜名", "B": "似懂非懂，不求甚解", "C": "裝腔作勢，逢迎媚俗", "D": "功名未遂，故作豪邁"}, "answer": "D", "explain": "這句話字面是「有萬卷書就不需要當王侯」，聽起來很瀟灑；但作者說它「其實是心尚未安無可奈何的解嘲語，徒見其不丈夫」——說話的人其實沒得到權位，心裡不甘，只好用這句話自我安慰、裝出豪氣。(D)功名未遂，故作豪邁，正確。(A)說話者有萬卷書，不是沒學問，錯。(B)文中沒說他讀書不求甚解，錯。(C)解嘲是自我安慰，不是討好別人，錯。", "skill": "抓作者對引文的評語（解嘲語、心尚未安），比只看引文本身更重要。"}, {"n": 40, "qtype": "單選", "stem": "依文意，下列關於書房的敘述，何者正確？", "options": {"A": "書房擁有豐富藏書，方足以成為書香世家", "B": "書房要有良好通風，以避免印刷油墨怪味", "C": "書房貴能符合需要，為讀書人嚮往的勝地", "D": "書房空間侷促偏狹，易導致讀書效率降低"}, "answer": "C", "explain": "(A)作者說「書香」來自書房裡油墨與紙張的怪味，只有士大夫人家才有書房，並沒說藏書多才算書香世家，錯。(B)文中說「光線要好，空氣要流通」，是讀書寫作的條件，沒說是為了避免油墨怪味，錯。(C)「適合自己的需要便是」，又說書房是寒士「可望而不可即的豪華神仙世界」，正確。(D)作者說走廊一角也能當「讀書寫作的工廠，大量出貨」，錯。", "skill": "選項常把文中兩件不相干的事硬用「以、方」連成因果，要檢查原文有沒有這個因果。"}, {"n": 41, "qtype": "單選", "stem": "關於本文的文意脈絡，哪一個選項順序正確？", "options": {"A": "對比書香與銅臭→說明讀書人癖好→討論書房之好壞", "B": "點出書香之緣由→抒發讀書人希求→凸顯書房之用途", "C": "探討書房之歷史→展現讀書人抱負→分析書房之設計", "D": "讚嘆書房之設備→描寫讀書人生活→宣揚書房之重要"}, "answer": "B", "explain": "第一段解釋「書香」的由來（書房裡的怪味）；第二段寫寒士沒有書房，只能把理想讀書處寄託於「瑯嬛福地」；第三段說書房用途是藏書與讀寫，不在大小設備。(B)正確。(A)第一段重點不是對比銅臭，第二段也不是讀書人癖好。(C)沒談書房歷史。(D)作者反而說書房不在設備佳。", "skill": "脈絡題每段只取一句關鍵句，排起來再對選項。"}], "difficulty": "中", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et111-42", "exam": "et111", "nums": [42, 43, 44], "form": "題組", "img": "img/et111-42.png", "source": "孫思邈《千金翼方‧面膏方》（節錄）", "author": "孫思邈", "genre": "其他", "types": ["句意理解", "比較閱讀", "文意推論"], "passage": "杜蘅、牡蠣（熬）、防風、藁本、細辛、白附子、白芷、當歸、木蘭皮、白朮、獨活、萎蕤、天雄、茯苓、玉屑（各壹兩）、菟絲子、防巳、商陸、梔子花、橘皮、白斂、人參（各參兩）、甘松香、青木香、藿香、零陵香、丁香（各貳兩）、麝香（半兩）、白犬脂、白鵝脂、牛髓（各壹升）、羊酤（參具）。上參拾貳味，以水浸膏髓等五日，日別再易水；又五日，日別一易水；又十日，二日一易水，凡二十日止。以酒壹升，挼羊酤令消盡去脈，乃細切香於瓷器中浸之，密封一宿。曉以諸脂等合煎三上三下，以酒水氣盡為候，即以綿布絞去滓，研之千遍，待凝乃止，使白如雪。每夜塗面，晝則洗卻，更塗新者，十日以後，色等桃花。", "translation": "（以上藥材及份量略。）以上三十二味藥，先用水浸泡油脂骨髓等五天，每天換兩次水；再浸五天，每天換一次水；再浸十天，兩天換一次水，總共二十天為止。用一升酒，把羊胰揉搓到完全化開、去掉筋脈，再把香料切細放進瓷器中浸泡，密封一個晚上。天亮後把各種油脂等合在一起煎煮，煮沸三次、離火三次，以酒和水的氣味完全消失為準，就用綿布擰掉渣滓，研磨上千遍，等凝固才停止，使它白得像雪。每天晚上塗在臉上，白天洗掉，再塗新的，十天以後，臉色就像桃花一樣好看。", "keywords": [{"w": "易水", "m": "換水"}, {"w": "挼", "m": "揉搓"}, {"w": "宿", "m": "一夜"}, {"w": "滓", "m": "渣滓"}, {"w": "色等桃花", "m": "臉色如桃花般紅潤"}], "questions": [{"n": 42, "qtype": "單選", "stem": "依甲文，下列關於「面膏方」的敘述，何者正確？", "options": {"A": "製作時須以酒水交替浸泡二十天", "B": "使用時必須每天塗抹三次並洗淨", "C": "煎煮前須密封在瓷器中一個晚上", "D": "塗抹時將膏塗在綿布後貼在臉上"}, "answer": "C", "explain": "(A)二十天是用「水」浸泡膏髓、定時換水，不是酒水交替，錯。(B)「每夜塗面，晝則洗卻，更塗新者」，是晚上塗、白天洗，不是一天三次，錯。(C)「細切香於瓷器中浸之，密封一宿。曉以諸脂等合煎」——先密封一晚，天亮才煎，正確。(D)綿布是用來「絞去滓」過濾渣的，不是敷臉，錯。", "skill": "流程題把步驟按時間排一條線（浸→揉→密封一宿→煎→濾→研），再對選項。"}, {"n": 43, "qtype": "單選", "stem": "下列選項，何者是甲、乙二文有共同提及處？", "options": {"A": "產品功效", "B": "使用禁忌", "C": "保存方法", "D": "適用對象"}, "answer": "A", "explain": "甲文說「使白如雪」「十日以後，色等桃花」，乙文說「滋潤肌膚、防止老化……明亮有光澤」，兩者都寫了功效，選(A)。(B)甲文沒有寫禁忌。(C)保存方法（陰涼處、一年內用完）只有乙文有。(D)適用對象（30歲以上）只有乙文有。", "skill": "共同處題，以「資訊少的那篇」為準逐項檢查最快。"}, {"n": 44, "qtype": "單選", "stem": "下列關於甲、乙二文內容異同的敘述，何者正確？", "options": {"A": "甲文產品的取名融入功效，乙文沒有", "B": "甲文產品的製作時間較長，乙文較短", "C": "甲、乙二文都敘及固定材料及份量且不得調整", "D": "甲、乙二文都敘及產品發揮功效所需要的時間"}, "answer": "B", "explain": "(A)相反：甲文叫「面膏方」看不出功效，乙文「抗老防皺面霜」才有，錯。(B)甲文光浸泡就要二十天，再加密封一夜、煎煮研磨；乙文攪拌搖勻「即可使用」，正確。(C)乙文材料可選矽靈油或植物油，維他命A酯兩個月後可調高，可以調整，錯。(D)甲文有「十日以後」，乙文沒寫多久見效（兩個月是調整用量，不是見效時間），錯。", "skill": "比較題遇到「都」「不得」這類絕對詞，只要找到一篇不符合就能刪。"}], "difficulty": "中", "label": "111二技", "year": 111, "kind": "二技"}, {"id": "et112-04", "exam": "et112", "nums": [4], "form": "單題", "img": "img/et112-04.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "呈卷，即面署第一。／屬予作文以記之。／開瓊筵以坐花，飛羽觴而醉月。／一尊還酹江月。／緣督以為經，可以保身。／不敢服垢弊以矯俗干名，但順吾性而已。／往來桐城，必躬造左公第。／外人欲詣其社，必舉草火，以煙起為號。", "translation": "交上考卷，（左公）當面就評定為第一名。／囑託我寫一篇文章來記述這件事。／擺開華美的筵席坐在花間，傳遞酒杯醉倒在月下。／舉起一杯酒祭奠江上明月。／順著中道作為常法，可以保全自身。／不敢穿破舊骯髒的衣服故意違反習俗來求取名聲，只是順著我的本性罷了。／往來桐城時，一定親自到左公家拜訪。／外人想要到他們的村社，一定要舉起草火，以冒煙為信號。", "keywords": [{"w": "署", "m": "題寫，這裡指評定名次"}, {"w": "屬", "m": "通「囑」，囑託"}, {"w": "觴", "m": "酒杯"}, {"w": "尊", "m": "通「樽」，酒杯"}, {"w": "緣", "m": "順著"}, {"w": "造", "m": "到"}, {"w": "詣", "m": "到"}], "questions": [{"n": 4, "qtype": "單選", "stem": "下列選項「」中的詞義，前後最不相近的選項是：", "options": {"A": "呈卷，即面「署」第一／「屬」予作文以記之", "B": "開瓊筵以坐花，飛羽「觴」而醉月／一「尊」還酹江月", "C": "「緣」督以為經，可以保身／不敢服垢弊以矯俗干名，但「順」吾性而已", "D": "往來桐城，必躬「造」左公第／外人欲「詣」其社，必舉草火，以煙起為號"}, "answer": "A", "explain": "(A)方苞〈左忠毅公軼事〉「面署第一」的「署」是題寫、評定；范仲淹〈岳陽樓記〉「屬予作文」的「屬」通「囑」，是囑託，兩者意思不同，選(A)。(B)李白〈春夜宴從弟桃花園序〉的「觴」和蘇軾〈念奴嬌〉的「尊（樽）」都是酒杯，相近。(C)《莊子‧養生主》「緣督」的「緣」是順著，和〈訓儉示康〉「順吾性」的「順」相近。(D)「造左公第」的「造」和「詣其社」的「詣」都是到、前往，相近。", "skill": "比較字義題，把兩個字都換成白話動詞，換完一樣的就刪；「屬」常通「囑」要記住。"}], "difficulty": "中", "label": "112二技", "year": 112, "kind": "二技"}, {"id": "et112-05", "exam": "et112", "nums": [5], "form": "單題", "img": "img/et112-05.png", "source": "綜合（一字多義）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "三尺許", "translation": "大約三尺", "keywords": [{"w": "許", "m": "允許；答應；或許；約略（數量詞後）"}], "questions": [{"n": 5, "qtype": "單選", "stem": "下列選項中的「許」，何者與「只許州官放火，不許百姓點燈」的「許」意義最接近？", "options": {"A": "我在佛前「許」下一個心願", "B": "此次盛會只「許」成年人參與", "C": "「許」是飛累了，需要休息的罷", "D": "我們之間仍然維持著三尺「許」的距離"}, "answer": "B", "explain": "「只許州官放火」的「許」是允許、准許。(A)「許下心願」是承諾、許願，不同。(B)「只許成年人參與」是只允許成年人，相同，選(B)。(C)「許是飛累了」是或許、也許，不同。(D)「三尺許」是文言常見用法，放在數量後面表示「大約、左右」，不同。", "skill": "「許」接在數量詞後面（三尺許、百許人）就是「大約」，這是文言最常考的用法。"}], "difficulty": "易", "label": "112二技", "year": 112, "kind": "二技"}, {"id": "et112-06", "exam": "et112", "nums": [6], "form": "單題", "img": "img/et112-06.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "將軍向寵，性行淑均。／土地平曠，屋舍儼然。／霪雨霏霏，連月不開。／走卒類士服，農夫躡絲履。", "translation": "將軍向寵，性情品行善良公正。／土地平坦開闊，房屋整整齊齊。／連綿的雨下個不停，整個月都不放晴。／差役穿得像讀書人，農夫也穿起絲織的鞋子。", "keywords": [{"w": "淑均", "m": "善良公正"}, {"w": "儼然", "m": "整齊的樣子"}, {"w": "霏霏", "m": "雨雪綿密的樣子"}, {"w": "躡", "m": "穿（鞋）"}, {"w": "絲履", "m": "絲製的鞋子"}], "questions": [{"n": 6, "qtype": "單選", "stem": "下列選項「」中的詞義，何者解釋正確？", "options": {"A": "將軍向寵，性行「淑均」：善良公正", "B": "土地平曠，屋舍「儼然」：參差錯落", "C": "霪雨「霏霏」，連月不開：驟然大雨", "D": "走卒類士服，農夫躡「絲履」：腳步輕盈"}, "answer": "A", "explain": "(A)諸葛亮〈出師表〉「淑」是善良、「均」是公平，「淑均」就是善良公正，正確。(B)陶淵明〈桃花源記〉「儼然」是整齊的樣子，不是參差錯落，錯。(C)范仲淹〈岳陽樓記〉「霪雨霏霏」是連綿細密的雨，前面「霪雨」就是久雨，不是驟然大雨，錯。(D)司馬光〈訓儉示康〉「躡絲履」是穿絲織的鞋子，表示連農夫都奢侈，不是腳步輕盈，錯。", "skill": "國中高中讀過的名篇詞語最常被換成「相反意思」來考，先回想原文情境（桃花源是整齊的）。"}], "difficulty": "易", "label": "112二技", "year": 112, "kind": "二技"}, {"id": "et112-16", "exam": "et112", "nums": [16], "form": "單題", "img": "img/et112-16.png", "source": "應用文（電子郵件、書信用語）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "吳老師，您好：……謝謝，敬祝　大安　學生林小名　筆", "translation": "吳老師您好：學生因確診新冠肺炎，明天無法到校上課，向您請假一次。謝謝，敬祝您平安。學生林小名寫", "keywords": [{"w": "教安", "m": "對老師的問候語"}, {"w": "敬上", "m": "對長輩、師長的署名敬辭"}, {"w": "大安", "m": "對平輩的問候語"}, {"w": "筆", "m": "對晚輩或平輩的署名用語"}], "questions": [{"n": 16, "qtype": "單選", "stem": "下列電子郵件的修改建議，最適當的選項為何？（甲、「如內文」應改為「通告」　乙、「吳老師，您好：」應改為「吳老師：敬啟：」　丙、「敬祝 大安」應改為「敬祝 教安」　丁、「學生林小名 筆」應改為「學生林小名 敬上」）", "options": {"A": "甲乙", "B": "乙丙", "C": "丙丁", "D": "甲丁"}, "answer": "C", "explain": "甲：主旨「如內文」太籠統，應寫明「請假」之類的具體事由；改成「通告」更不對，學生寫信請假不是發布通告，錯。乙：電子郵件用「吳老師，您好：」已經得體；「敬啟」是開頭的啟事敬辭，寫成「吳老師：敬啟：」格式不通，錯。丙：寫給老師的問候語應用「教安」，「大安」是平輩用語，改得對。丁：學生對老師署名應用「敬上」，「筆」用於平輩或晚輩，改得對。正確的是丙丁，選(C)。", "skill": "書信用語看「寫給誰」：對師長問候用「教安」、署名用「敬上」。"}], "difficulty": "易", "label": "112二技", "year": 112, "kind": "二技"}, {"id": "et112-17", "exam": "et112", "nums": [17], "form": "單題", "img": "img/et112-17.png", "source": "古典小說回目", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "皇恩重元妃省父母，天倫樂寶玉呈才藻／梁山泊分金大買市，宋公明全夥受招安／歷山山下古帝遺蹤，明湖湖邊美人絕調／寧國府骨肉病災祲，大觀園符水驅妖孽", "translation": "（甲）皇帝恩重，元妃回家省親；天倫之樂，寶玉展現才華。（乙）梁山泊分財物大開市集，宋江率全體接受招安。（丙）歷山下有古代帝王遺跡，大明湖邊有美人絕妙的歌唱。（丁）寧國府骨肉相繼生病遭災，大觀園用符水驅趕妖孽。", "keywords": [{"w": "回目", "m": "章回小說每一回的標題，多為對句"}], "questions": [{"n": 17, "qtype": "單選", "stem": "下列為小說的章節回目名稱，請判斷何者出自《紅樓夢》？", "options": {"A": "甲乙", "B": "乙丙", "C": "丙丁", "D": "甲丁"}, "answer": "D", "explain": "從人名和地名判斷：甲有「元妃」「寶玉」，丁有「寧國府」「大觀園」，都是《紅樓夢》的人物和地點，所以甲丁出自《紅樓夢》，選(D)。乙有「梁山泊」「宋公明（宋江）」「招安」，是《水滸傳》。丙有「歷山」「明湖（大明湖）」，寫濟南景物，是劉鶚《老殘遊記》第二回（王小玉說書）。", "skill": "回目題抓專有名詞：寶玉、大觀園→紅樓；梁山、宋江→水滸；大明湖→老殘遊記。"}], "difficulty": "易", "label": "112二技", "year": 112, "kind": "二技"}, {"id": "et112-19", "exam": "et112", "nums": [19, 20], "form": "題組", "img": "img/et112-19.png", "source": "中國文學常識（四史、左傳、鴻門宴、詞的別稱）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "四史", "m": "《史記》《漢書》《後漢書》《三國志》"}, {"w": "左傳", "m": "記載春秋時期歷史的史書"}, {"w": "詩餘、長短句、曲子詞", "m": "都是「詞」的別稱"}, {"w": "詞餘", "m": "「曲」的別稱"}], "questions": [{"n": 19, "qtype": "單選", "stem": "下列選項中對小國、小文作答的敘述，正確的是：（①《三國演義》是不是「四史」之一？小國：是／小文：不是　②《左傳》寫的是不是春秋時期的歷史？小國：不是／小文：是　③寫出一位在〈鴻門宴〉中出現過的人物：小國：張良／小文：劉備　④「詞」的別稱：小國：詩餘／小文：長短句）", "options": {"A": "①③小國都答對", "B": "②④小文都答對", "C": "④小國、小文都答錯", "D": "小國答對的題數多於小文"}, "answer": "B", "explain": "先對答案：①四史是《史記》《漢書》《後漢書》《三國志》，《三國演義》是明代小說，不是，小文對、小國錯。②《左傳》記春秋歷史，是，小文對。③〈鴻門宴〉有張良，沒有劉備（劉備是三國人物），小國對。④詩餘、長短句都是詞的別稱，兩人都對。(A)小國①錯，錯。(B)小文②④都對，正確。(C)④兩人都對，錯。(D)小國對③④兩題，小文對①②④三題，錯。", "skill": "先自己把表格每格標上對錯，再看選項，不要邊看邊想。"}, {"n": 20, "qtype": "單選", "stem": "下列選項中對上表③④的敘述，正確的是：", "options": {"A": "③可填答：項莊；④可填答：曲子詞", "B": "③可填答：曹操；④可填答：曲子詞", "C": "③可填答：曹操；④可填答：詞餘", "D": "③可填答：項莊；④可填答：詞餘"}, "answer": "A", "explain": "③〈鴻門宴〉中舞劍要刺殺沛公的就是項莊，可以填；曹操是三國人物，不行。④「曲子詞」是詞的別稱，可以填；「詞餘」是「曲」的別稱，不行。所以選(A)。", "skill": "記清楚：詩餘＝詞，詞餘＝曲，一字之差就是兩種文體。"}], "difficulty": "易", "label": "112二技", "year": 112, "kind": "二技"}, {"id": "et112-23", "exam": "et112", "nums": [23, 24], "form": "題組", "img": "img/et112-23.png", "source": "王嘉《拾遺記》", "author": "王嘉", "genre": "筆記小品", "types": ["人物情感", "主旨寓意", "文意推論"], "passage": "賈逵年五歲，明惠過人。其姊韓瑤之婦，嫁瑤無嗣而歸居焉，亦以貞明見稱。聞鄰中讀書，旦夕抱逵隔籬而聽之。逵靜聽不言，姊以為喜。至年十歲，乃暗誦六經。姊謂逵曰：「吾家貧困，未嘗有教者入門，汝安知天下有《三墳》、《五典》而誦無遺句耶？」逵曰：「憶昔姊抱逵於籬間聽鄰家讀書，今萬不遺一。」乃剝庭中桑皮以為牒，或題於扉屏，且誦且記。期年，經文通遍。於閭里每有觀者，稱云振古無倫。門徒來學，不遠萬里，或襁負子孫，舍於門側，皆口授經文，贈獻者積粟盈倉。或云：「賈逵非力耕所得，誦經口倦，世所謂舌耕也。」", "translation": "賈逵五歲時，就聰明過人。他的姊姊是韓瑤的妻子，嫁給韓瑤後沒有子嗣，回到娘家住，也以貞節賢明受到稱讚。她聽到鄰居家有人讀書，就早晚抱著賈逵隔著籬笆聽。賈逵安靜地聽，不說話，姊姊很高興。到了十歲，賈逵竟能背誦六經。姊姊對他說：「我們家貧窮，從來沒有老師上門，你怎麼知道天下有《三墳》《五典》這些書，還能背得一句不漏呢？」賈逵說：「我記得以前姊姊抱我在籬笆邊聽鄰居讀書，現在一萬句也忘不了一句。」於是剝下院子裡的桑樹皮當作書寫的紙，有時寫在門板和屏風上，一邊背一邊記。一年後，經書全都讀通了。鄉里常有人來看，都稱讚他自古以來無人能比。學生來向他學習，不怕路途遙遠，有的還背著孩子孫子，住在他家門旁，他都口頭傳授經文，人們送來的糧食堆滿了倉庫。有人說：「賈逵的收入不是靠耕田得來的，而是誦經講到嘴巴都累了，這就是世人說的『舌耕』啊。」", "keywords": [{"w": "明惠", "m": "聰明（惠通慧）"}, {"w": "無嗣", "m": "沒有子孫"}, {"w": "暗誦", "m": "背誦"}, {"w": "牒", "m": "書寫用的簡片"}, {"w": "期年", "m": "一整年"}, {"w": "振古無倫", "m": "自古以來沒有人比得上"}, {"w": "襁負", "m": "用布兜背著（孩子）"}, {"w": "舌耕", "m": "靠教書維生"}], "questions": [{"n": 23, "qtype": "單選", "stem": "依據上文，下列文句何者最適合形容賈逵？", "options": {"A": "大智不形，大器晚成", "B": "見善則遷，有過則改", "C": "多聞闕疑，不恥下問", "D": "業精於勤，聰穎強識"}, "answer": "D", "explain": "賈逵五歲就「明惠過人」，隔籬聽書能「萬不遺一」——聰穎、記性好；又剝桑皮當紙「且誦且記」——勤奮。(D)業精於勤、聰穎強識，正確。(A)他十歲就能背六經，是早慧，不是大器晚成，錯。(B)文中沒有改過的情節，錯。(C)文中沒提到他向人請教，錯。", "skill": "形容人物的題目，把文中的「證據動作」分類：天分類、努力類，再找同時涵蓋兩者的選項。"}, {"n": 24, "qtype": "單選", "stem": "國文課堂上，老師要學生根據這則事蹟發表讀後感，哪些學生的解讀符合上文旨意？（學生甲：「雖然家貧，但姊姊替弟弟尋求讀書的機會，實在明智又難得！」　學生乙：「家世好未必是成功的保證，在困境中勤奮力學，才更為可貴！」　學生丙：「少壯不努力，老大徒傷悲，得謹記教訓，才不至於重蹈覆轍。」　學生丁：「雖然讀書有成，卻為盛名所累，由此可見『人生識字憂患始』。」）", "options": {"A": "甲乙", "B": "乙丙", "C": "丙丁", "D": "甲丁"}, "answer": "A", "explain": "甲：姊姊在貧困中抱弟弟隔籬聽書，確實明智又難得，符合。乙：賈逵家貧沒有老師，卻靠勤學成名，符合。丙：文中沒有人蹉跎歲月後悔，不符合。丁：賈逵學成後門徒眾多、收入豐厚，沒有被盛名拖累，不符合。答案甲乙，選(A)。", "skill": "讀後感題逐句檢查：文中有沒有這個情節？有，再看詮釋是否扭曲。"}], "difficulty": "易", "label": "112二技", "year": 112, "kind": "二技"}, {"id": "et112-27", "exam": "et112", "nums": [27, 28, 29], "form": "題組", "img": "img/et112-27.png", "source": "鍾惺〈夏梅說〉", "author": "鍾惺", "genre": "說理議論", "types": ["文意推論", "文化常識", "主旨寓意"], "passage": "梅之冷，易知也，然亦有極熱之候。冬春冰雪，繁花粲粲，雅俗爭赴，此其極熱時也。三四五月，累累其實，和風甘雨之所加，而梅始冷矣。花實俱往，時維朱夏，葉幹相守，與烈日爭，而梅之冷極矣。故夫看梅與詠梅者，未有於無花之時者也。張謂〈官舍早梅〉詩所詠者，花之終、實之始也。詠梅而及於實，斯已難矣，況葉乎？梅至於葉，而過時久矣。廷尉董崇相，官南都在告，有〈夏梅〉詩，始及於葉。何者？舍葉無所為夏梅也。予為梅感此誼，屬同志者和焉，而為圖卷以贈之。夫世固有處極冷之時之地，而名實之權在焉。巧者乘間赴之，有名實之得，而又無赴熱之譏。此趨梅於冬春冰雪者之人也，乃真附熱者也。苟真為熱之所在，雖與地之極冷，而有所必辯焉。此詠夏梅意也。", "translation": "梅花的冷清，是人人都知道的，但它也有極為熱鬧的時候。冬春冰雪之間，花開得繁盛燦爛，雅士俗人都爭著去看，這是它最熱鬧的時候。到了三四五月，結了累累果實，和風細雨滋潤著，梅開始冷清了。花和果實都過去了，到了炎夏，只剩葉子和枝幹相守，與烈日抗爭，這時梅冷清到了極點。所以看梅、詠梅的人，沒有在無花的時候去的。張謂〈官舍早梅〉詩寫的，是花將謝、果實初結的時候。詠梅寫到果實，已經很難得了，何況寫到葉子呢？梅到了只剩葉子，已經過了它的時節很久了。廷尉董崇相，在南京做官時正休假，寫了〈夏梅〉詩，才寫到梅葉。為什麼呢？除了葉子，就沒有可以稱為夏梅的東西了。我替梅花感激他這份情誼，囑託志同道合的朋友唱和，又畫成圖卷送給他。世上本來就有處在極冷清的時節與地位，而名聲與實利的權柄卻在那裡的。聰明巧詐的人趁機去趨附，既得到名利，又不會被譏笑為趨炎附勢。這種人就像在冬春冰雪時去看梅的人，才是真正趨附熱鬧的人。如果真是熱鬧所在，即使它處在極冷的時節、地位，也一定要分辨清楚。這就是我詠夏梅的用意。", "keywords": [{"w": "粲粲", "m": "鮮明燦爛"}, {"w": "赴", "m": "前往"}, {"w": "累累", "m": "一串串很多的樣子"}, {"w": "朱夏", "m": "夏天"}, {"w": "在告", "m": "休假中"}, {"w": "誼", "m": "情誼、道理"}, {"w": "屬", "m": "通「囑」，囑託"}, {"w": "乘間", "m": "趁機"}, {"w": "附熱", "m": "趨炎附勢"}], "questions": [{"n": 27, "qtype": "單選", "stem": "依據上文，首段敘述由「極熱」、「始冷」再至「冷極」，何者符合文意？", "options": {"A": "「極熱」是指春天適宜百花齊開而有盛況，「冷極」則是指冰天雪地極寒時節", "B": "意謂梅花不畏冷熱，堅毅不屈，展現「無意苦爭春，一任群芳妒」的獨特性格", "C": "從「極熱」而至「冷極」，指賞梅人潮由熱鬧盛況，逐漸消減，終至稀落冷清", "D": "由「極熱」而至「冷極」，指梅子結實的條件，在於必須經歷氣溫的劇烈變化"}, "answer": "C", "explain": "這裡的冷熱不是溫度，而是「人氣」：花開時「雅俗爭赴」最熱鬧；結果時開始冷清；夏天只剩葉子，無人理會，冷到極點。(A)極熱是「冬春冰雪」梅花盛開，冷極是盛夏，完全顛倒，錯。(B)文章談的是人對梅的態度，不是讚美梅的性格，錯。(C)賞梅人潮由盛到衰，正確。(D)和結果的氣溫條件無關，錯。", "skill": "古文中的「冷、熱」常比喻人情冷暖、受不受重視，先別當成溫度。"}, {"n": 28, "qtype": "單選", "stem": "依據上文「張謂〈官舍早梅〉詩所詠者，花之終、實之始也」，推斷此詩所詠的梅，應該屬於什麼時節？", "options": {"A": "仲春至季春", "B": "仲夏至季夏", "C": "孟秋至仲秋", "D": "孟冬至仲冬"}, "answer": "A", "explain": "文中說梅「冬春冰雪」開花，「三四五月，累累其實」。「花之終、實之始」就是花快謝完、剛開始結果的時候，大約在春天的中後段，也就是農曆二、三月左右。古人每季分孟（第一個月）、仲（第二個月）、季（第三個月），仲春到季春正是二到三月，選(A)。(B)夏天果實早就結了、花早已沒了。(C)(D)秋冬不是結果期，孟冬到仲冬梅花尚未開盛。", "skill": "孟、仲、季＝每季的第一、二、三個月，把文中的月份換算一下就能對上。"}, {"n": 29, "qtype": "單選", "stem": "依據上文，關於文章寫法及意旨的說明，何者正確？", "options": {"A": "前後對比，描摹形象，凸顯梅樹常綠不凋，強調士人堅毅不易之氣節", "B": "借花喻人，託物寓意，以梅花的冷熱際遇，批評趨炎附勢之世態人心", "C": "藉事說理，體物寫志，慰勉友人效法夏梅，勿因仕途挫折而消沉喪志", "D": "援古證今，贈人以言，歌頌冰清玉潔特性，讚賞與世無爭之孤高性格"}, "answer": "B", "explain": "末段點明：冬春冰雪時去看梅的人，看似風雅，其實是「真附熱者」——哪裡熱鬧就往哪裡去。作者借梅花有人看、沒人看的冷熱遭遇，批評趨炎附勢的人心，(B)正確。(A)文章沒有強調梅樹常綠不凋或堅毅氣節。(C)沒有慰勉友人不要因仕途挫折消沉。(D)沒有歌頌冰清玉潔或與世無爭。", "skill": "「說」體文章的主旨多在最後一段，看到「此……意也」就是作者自己說出用意。"}], "difficulty": "難", "label": "112二技", "year": 112, "kind": "二技"}, {"id": "et112-30", "exam": "et112", "nums": [30, 31, 32], "form": "題組", "img": "img/et112-30.png", "source": "黃麗群〈吃水蜜桃〉、焦桐《蔬果歲時記》（引文）", "author": "黃麗群、焦桐", "genre": "其他", "types": ["典故出處", "文意推論", "比較閱讀"], "passage": "桃之夭夭，灼灼其華。／投以木桃，報以瓊瑤。／去年今日此門中，人面桃花相映紅。人面不知何處去，桃花依舊笑春風。／夾岸數百步，中無雜樹，芳草鮮美，落英繽紛。", "translation": "桃樹茂盛，桃花開得鮮豔。／你送我木桃，我回贈你美玉。／去年的今天在這扇門裡，少女的臉龐和桃花互相輝映得通紅；如今少女不知到哪裡去了，只有桃花依舊在春風中盛開。／溪流兩岸幾百步，中間沒有別的樹，芳草鮮美，落花繽紛。", "keywords": [{"w": "夭夭", "m": "茂盛的樣子"}, {"w": "灼灼", "m": "鮮明的樣子"}, {"w": "瓊瑤", "m": "美玉"}, {"w": "落英", "m": "落花"}, {"w": "二桃殺三士", "m": "晏子用兩顆桃子使三位勇士爭功而自殺的典故"}, {"w": "彌子瑕", "m": "衛靈公的寵臣，曾把吃剩的半個桃子給衛靈公"}], "questions": [{"n": 30, "qtype": "單選", "stem": "甲文指出「好像沒有誰不喜歡桃子」，其所提及的理由不包括下列何者？", "options": {"A": "滋味美好，形態色澤豔麗", "B": "易於栽植，一年四季皆宜", "C": "富含氣質，形象正面清新", "D": "典故眾多，文化意蘊豐富"}, "answer": "B", "explain": "甲文提到：桃子「憨甜」、念起來「五光十色」（滋味美好、色澤豔麗）；「白桃黃桃，氣質清潔無比」「正大仙容」（形象正面清新）；舉了《詩經》、西王母、彌子瑕、二桃殺三士、桃園結義等典故（文化意蘊豐富）。只有「容易栽種、四季都適合」完全沒提，選(B)。", "skill": "「不包括」題，把每個選項回原文找一句證據，找不到的就是答案。"}, {"n": 31, "qtype": "單選", "stem": "依據甲文，「桃」這字眼可能具有加強感受的作用，可分成兩種類型：類型Ⅰ「單獨不清爽，與桃子接枝，感覺一下子好很多」、類型Ⅱ「美麗的則更美麗」。若依據文意並參酌下表，對甲、乙兩文所提及的①、②、③、④，進行類型Ⅰ、Ⅱ的歸類，下列何者最適當？（類型Ⅰ例：夸父死前拋開手杖，杖化為桃林，結出桃子，給路人解渴／類型Ⅱ例：「芳草鮮美，落英繽紛」的桃花源景象，從中寄託美好生活的渴望；①二桃殺三士②桃園三結義③人面桃花相映紅④桃之夭夭，灼灼其華）", "options": {"A": "①屬於類型Ⅱ", "B": "③屬於類型Ⅰ", "C": "②屬於類型Ⅱ、④屬於類型Ⅰ", "D": "①屬於類型Ⅰ、③屬於類型Ⅱ"}, "answer": "D", "explain": "類型Ⅰ：本來不好的事（死亡、險惡），因為有桃子而感覺變好；類型Ⅱ：本來就美好的事，加上桃更美。①「二桃殺三士」本是殺人的險惡計謀，作者卻說因為是桃子「也不覺得險惡」，屬類型Ⅰ。②桃園結義是「金蘭之約的美好」，加上桃花更美，屬類型Ⅱ。③美人與桃花相映，美上加美，屬類型Ⅱ。④〈桃夭〉寫出嫁的喜事，也是類型Ⅱ。(A)①應是Ⅰ，錯。(B)③應是Ⅱ，錯。(C)④應是Ⅱ，錯。(D)①Ⅰ、③Ⅱ，正確。", "skill": "分類題先判斷「原本的事是好是壞」，壞事變好→Ⅰ，好事更好→Ⅱ。"}, {"n": 32, "qtype": "單選", "stem": "下列關於甲、乙兩文內容的說明，何者正確？①兩文均凸顯作者對歷代書寫桃花作品優劣的評論　②兩文均強調食用桃子有趨吉避邪的傳統文化意涵", "options": {"A": "①、②皆正確", "B": "①、②皆錯誤", "C": "①正確，②錯誤", "D": "①錯誤，②正確"}, "answer": "B", "explain": "①兩文都只是列舉桃的典故與詩句，表達桃在文化中「總是美好的」，並沒有評論哪些作品寫得好或壞，錯誤。②乙文說壽桃象徵長壽吉祥，但沒提到「避邪」；甲文則完全沒談趨吉避邪，錯誤。兩者都錯，選(B)。", "skill": "「兩文均」的敘述，要兩篇都找得到才算對。"}], "difficulty": "中", "label": "112二技", "year": 112, "kind": "二技"}, {"id": "et112-36", "exam": "et112", "nums": [36, 37, 38], "form": "題組", "img": "img/et112-36.png", "source": "柳宗元〈種樹郭橐駝傳〉（節錄）", "author": "柳宗元", "genre": "寓言故事", "types": ["比較閱讀", "寫作手法", "主旨寓意"], "passage": "橐駝非能使木壽且孳也，以能順木之天，以致其性焉耳。凡植木之性，其本欲舒，其培欲平，其土欲故，其築欲密。既然已，勿動勿慮，去不復顧。其蒔也若子，其置也若棄，則其天者全，而其性得矣。故吾不害其長而已，非有能碩而茂之也；不抑耗其實而已，非有能蚤而蕃之也。問者曰：「以子之道，移之官理，可乎？」駝曰：「我知種樹而已，官理非吾業也。然吾居鄉，見長人者好煩其令，若甚憐焉，而卒以禍。旦暮，吏來而呼曰：『官命促爾耕，勗爾植，督爾獲。蚤繰而緒，蚤織而縷，字而幼孩，遂而雞豚。』鳴鼓而聚之，擊木而召之。吾小人輟飧饔以勞吏者，且不得暇，又何以蕃吾生而安吾性耶？」", "translation": "我郭橐駝並不能讓樹活得長久又長得茂盛，只是能順應樹木的天性，讓它的本性充分發揮罷了。凡是種樹，樹根要舒展，培土要平均，根上的土要用原來的舊土，搗土要結實。這樣做好以後，就不要再去動它、擔心它，離開後不再回頭看。種的時候要像照顧孩子一樣細心，種好後放著要像丟棄一樣不管，那麼樹的天性就能保全，本性就能發展了。所以我只是不妨害它生長罷了，並沒有使它長得高大茂盛的本事；只是不抑制、損耗它的果實罷了，並沒有使它提早結果、結得多的本事。問的人說：「把你種樹的方法，轉用到做官治民上，可以嗎？」橐駝說：「我只懂種樹而已，治理百姓不是我的事業。但我住在鄉下，看到那些當官的喜歡頻繁發布命令，好像很愛護百姓，結果卻帶來災禍。早晚都有小吏來喊：『官府命令催你們耕田，勉勵你們種植，督促你們收割。早點煮繭抽絲，早點紡紗織布，養育好你們的小孩，餵大你們的雞和豬。』一會兒打鼓集合大家，一會兒敲木梆召喚大家。我們小老百姓連早餐晚餐都停下來去慰勞小吏，都還沒有空閒，又怎麼能使我們生活富足、性情安定呢？」", "keywords": [{"w": "孳", "m": "繁殖、茂盛"}, {"w": "天", "m": "天性"}, {"w": "本", "m": "樹根"}, {"w": "故", "m": "舊的（原土）"}, {"w": "蒔", "m": "種植"}, {"w": "蚤", "m": "通「早」"}, {"w": "長人者", "m": "治理百姓的官員"}, {"w": "勗", "m": "勉勵"}, {"w": "繰", "m": "煮繭抽絲"}, {"w": "字", "m": "養育"}, {"w": "飧饔", "m": "晚飯與早飯"}], "questions": [{"n": 36, "qtype": "單選", "stem": "判斷①、②的意思，選出最接近甲、乙文種樹原理的選項：①依乎天理，批大郤，導大窾，因其固然　②天將降大任於是人也，必先苦其心志，勞其筋骨……，增益其所不能", "options": {"A": "甲、乙接近①", "B": "甲、乙接近②", "C": "甲接近①；乙接近②", "D": "甲接近②；乙接近①"}, "answer": "C", "explain": "①出自《莊子‧養生主》庖丁解牛，意思是順著牛天然的結構下刀——「順應天性」，正好對應甲文「順木之天，以致其性」。②出自《孟子》，意思是經過困苦磨練，才能增加能力——對應乙文鄰居故意少澆水，逼樹根往深處長，日後才抵得住強風。所以甲接近①、乙接近②，選(C)。", "skill": "先替每段引文下一個兩字標籤（順性／磨練），再去配對兩篇文章。"}, {"n": 37, "qtype": "單選", "stem": "下列關於甲、乙文寫作手法的敘述，何者正確？", "options": {"A": "皆借事喻理", "B": "皆虛實交錯", "C": "皆使用誇飾", "D": "皆先議後敘"}, "answer": "A", "explain": "甲文借種樹的方法比喻為官治民不可擾民；乙文借種樹少澆水比喻教養孩子要讓他經歷挫折。兩篇都是借事喻理，(A)正確。(B)兩文都是寫實的敘述與議論，沒有刻意虛實交錯。(C)沒有明顯誇飾。(D)乙文先敘述鄰居種樹的事，最後才說到對孩子的祈求，是先敘後議，所以不是「皆」先議後敘。", "skill": "寫作手法題用「皆」字時，只要有一篇不符就刪，先從最容易驗證的那篇下手。"}, {"n": 38, "qtype": "單選", "stem": "下列關於甲、乙文內容旨意的說明，何者正確？", "options": {"A": "兩文皆有反諷揠苗助長之意", "B": "兩文皆凸顯環境教育的重要", "C": "甲文寄託作者的為官使民之法", "D": "乙文強調適性揚才的教育理念"}, "answer": "C", "explain": "(A)甲文反對過度干預，有反揠苗助長的意味；但乙文是主張刻意給予困境，不是在反諷揠苗助長，所以不是「兩文皆」，錯。(B)兩文都不是談環境教育，錯。(C)甲文由種樹轉到「移之官理」，批評官吏擾民，寄託治民應順其自然的理念，正確。(D)乙文強調在挫折中扎下深根，不是適性揚才，錯。", "skill": "寓言式傳記的主旨在「轉折處」：本文從種樹轉到「移之官理」，那才是重點。"}], "difficulty": "中", "label": "112二技", "year": 112, "kind": "二技"}, {"id": "et112-39", "exam": "et112", "nums": [39, 40, 41], "form": "題組", "img": "img/et112-39.png", "source": "紀昀《閱微草堂筆記》", "author": "紀昀", "genre": "筆記小品", "types": ["虛詞句式", "文意推論", "主旨寓意"], "passage": "制府唐公嘗勘鞫一殺人案，獄具矣。一夜秉燭獨坐，忽微聞泣聲，似漸近窗戶。命小婢出視，噭然而仆。公自啟簾，則一鬼浴血跪階下；厲聲叱之，稽顙曰：「殺我者某，縣官乃誤坐某。仇不雪，目不瞑也。」公曰：「知之矣。」鬼乃去。翌日，自提訊，眾供死者衣履，與所見合。信益堅，竟如鬼言改坐某。問官申辯百端，終以為南山可移，此案不動。其幕友疑有他故，微叩公，始具言始末，亦無如之何。一夕，幕友請見，曰：「鬼從何來？」曰：「自至階下。」曰：「鬼從何去？」曰：「欻然越牆去。」幕友曰：「凡鬼有形而無質，去當奄然而隱，不當越牆。」因即越牆處尋視。雖甃瓦不裂，而新雨之後，數重屋上，皆隱隱有泥跡，直至外垣而下。指以示公曰：「此必囚賄捷盜所為也。」公沉思恍然，仍從原讞。諱其事，亦不復深求。", "translation": "總督唐公曾經審理一件殺人案，案子已經定讞了。一天夜裡他拿著蠟燭獨自坐著，忽然隱約聽到哭聲，好像漸漸靠近窗戶。叫小婢女出去看，她大叫一聲就昏倒了。唐公親自掀開簾子，只見一個滿身是血的鬼跪在台階下；唐公大聲喝斥，鬼磕頭說：「殺我的是某人，縣官卻誤判了另一個人的罪。仇不報，我死不瞑目。」唐公說：「我知道了。」鬼就離開了。第二天，唐公親自提審，眾人供述死者的衣服鞋子，和他昨晚看到的相符。他更加堅信，竟然照鬼說的改判某人有罪。承審的官員百般申辯，唐公始終認為「南山可以移動，這件案子不能改」。他的幕僚懷疑另有原因，委婉地問唐公，唐公才把事情始末全說出來，幕僚也拿他沒辦法。一天晚上，幕僚求見，問：「鬼從哪裡來？」唐公說：「自己到台階下的。」又問：「鬼從哪裡走？」唐公說：「忽然翻牆走了。」幕僚說：「鬼有形體而沒有實體，離開時應該忽然隱沒，不應該翻牆。」於是到翻牆的地方查看。雖然磚瓦沒有破裂，但剛下過雨，好幾層屋頂上都隱約有泥腳印，一直延伸到外牆才下去。幕僚指給唐公看，說：「這一定是囚犯買通身手矯捷的盜賊假扮的。」唐公沉思後恍然大悟，仍然維持原來的判決。他隱瞞這件事，也不再追究。", "keywords": [{"w": "勘鞫", "m": "審問案件"}, {"w": "獄具", "m": "案子已定"}, {"w": "噭然", "m": "大叫的樣子"}, {"w": "稽顙", "m": "以額觸地的敬禮"}, {"w": "坐", "m": "判罪"}, {"w": "幕友", "m": "幕僚"}, {"w": "叩", "m": "詢問"}, {"w": "欻然", "m": "忽然"}, {"w": "奄然", "m": "忽然、倏忽"}, {"w": "甃瓦", "m": "磚瓦"}, {"w": "讞", "m": "判決"}], "questions": [{"n": 39, "qtype": "單選", "stem": "上文畫線處的文句均省略了主詞，判斷下列選項在括弧中所補上的主詞，何者正確？", "options": {"A": "(唐公)信益堅", "B": "(囚)終以為南山可移", "C": "(幕友)始具言始末", "D": "(鬼)因即越牆處尋視"}, "answer": "A", "explain": "(A)唐公見眾人的供詞和他看到的鬼的衣履相合，於是「更加相信」，主詞是唐公，正確。(B)問官百般申辯，「終以為南山可移，此案不動」是唐公堅持不改判，不是囚犯，錯。(C)幕友「微叩公」，唐公「始具言始末」，說出原委的是唐公，錯。(D)聽了唐公回答後，「因即越牆處尋視」去查看的是幕友，不是鬼，錯。", "skill": "補主詞時看「前一句誰在說話或被問」：被問的人接著回答，追查的人接著行動。"}, {"n": 40, "qtype": "單選", "stem": "文中的判案經過兩次轉變，各次關鍵因素的搭配，何者正確？", "options": {"A": "第一次：鬼的衣履與死者相同／第二次：鬼的行動留下痕跡", "B": "第一次：幕友目擊案件的經過／第二次：問官提出新證據", "C": "第一次：問官提出新證據／第二次：鬼的衣履與死者相同", "D": "第一次：鬼的行動留下痕跡／第二次：幕友目擊案件的經過"}, "answer": "A", "explain": "第一次翻案：唐公提訊時「眾供死者衣履，與所見合」，因此相信鬼的話改判。第二次翻案：幕友發現「鬼」翻牆，屋上留下泥跡，證明是人假扮，唐公才「仍從原讞」。(A)正確。(B)幕友沒有目擊案件，問官也沒提出新證據。(C)問官只是申辯，沒有新證據，順序也錯。(D)順序顛倒，而且幕友沒有目擊。", "skill": "兩次轉折各找一個「因此改判」的觸發點，按時間排好再對表格。"}, {"n": 41, "qtype": "單選", "stem": "有關上文旨意，最適當的選項是：", "options": {"A": "平時不做虧心事，夜半不怕鬼敲門", "B": "衙門中官官相護，人民須據理力爭", "C": "眼見不一定為真，凡事應該認真辯證", "D": "為官應體恤下屬，拒絕關說為民興利"}, "answer": "C", "explain": "唐公親眼「見鬼」就深信不疑，差點冤枉好人；幕友用推理和實地查證（鬼不該翻牆、屋上有泥跡）揭穿騙局。主旨是：親眼所見也可能是假象，要認真查證，(C)正確。(A)故事不是講做了虧心事怕鬼。(B)文中沒有官官相護，反而是問官為原判申辯。(D)與體恤下屬、拒絕關說無關。", "skill": "筆記小說的旨意多由「誰被騙了、誰揭穿了」歸納出來。"}], "difficulty": "中", "label": "112二技", "year": 112, "kind": "二技"}, {"id": "et112-42", "exam": "et112", "nums": [42, 43, 44], "form": "題組", "img": "img/et112-42.png", "source": "〈隧道效應〉（改寫自《商業周刊》）；選項引〈鴻門宴〉等古文", "author": "", "genre": "其他", "types": ["比較閱讀", "文意推論"], "passage": "大行不顧細謹，大禮不辭小讓。／哀吾生之須臾，羨長江之無窮。／快哉此風！寡人所與庶人共者耶？／臣之壯也，猶不如人。今老矣，無能為也已。", "translation": "做大事不必顧慮小節，行大禮不必在意小的謙讓。／哀嘆我們的生命短暫，羨慕長江流水無窮無盡。／這風真暢快啊！這是我和百姓共同享有的嗎？／我年輕時，尚且比不上別人；現在老了，更沒有能力做什麼了。", "keywords": [{"w": "細謹", "m": "小節"}, {"w": "須臾", "m": "片刻，形容短暫"}], "questions": [{"n": 42, "qtype": "單選", "stem": "下列選項，何者最符合上文旨意？", "options": {"A": "擺脫隧道視野容易造成隧道效應", "B": "突破隧道效應是因為看見出口的光", "C": "只要覺得恐懼無助就會出現隧道效應", "D": "提高心智決策容量有助於突破隧道效應"}, "answer": "D", "explain": "(A)因果顛倒：是隧道效應造成隧道視野，擺脫隧道視野反而是好事，錯。(B)「只看得見出口的光」是被困時視野狹窄的表現，不是突破的原因，錯。(C)文中說恐懼無助會讓人做出不利決定，但沒說「只要恐懼就會出現」，說法太絕對，錯。(D)第三段說不要糾結小事、「避免浪費心智決策容量」，把心力留給重要的事，才能擺脫惡性循環，正確。", "skill": "說明文題目常把因果倒過來或把「容易」改成「只要就會」，要回原文核對方向和程度。"}, {"n": 43, "qtype": "單選", "stem": "請再次參閱前一題組的《閱微草堂筆記》，並研判其中的人物，何者符合上文畫線處的隧道效應情況？（畫線處：我們的認知資源會被眼前某件事情所佔據，通常只能看見立即、短淺的事物）", "options": {"A": "唐公", "B": "問官", "C": "幕友", "D": "囚犯"}, "answer": "A", "explain": "唐公一心只想著鬼魂喊冤這件事，認知被眼前事件佔據，聽不進問官「申辯百端」，甚至說「南山可移，此案不動」，正是隧道效應。(B)問官依證據為原判辯護，沒有被困住。(C)幕友冷靜推理、實地查證，正好是跳出隧道的人。(D)囚犯是設計騙局的一方，文中看不出他被眼前之事困住。", "skill": "把抽象概念（只看眼前、看不到其他路）套到人物身上，找「固執不聽其他聲音」的人。"}, {"n": 44, "qtype": "單選", "stem": "依據上文第三段文意，下列說話者的言論，何者最有助於畫線人物突破隧道效應？（畫線人物：劉邦、蘇子、宋玉、鄭伯）", "options": {"A": "樊噲對劉邦說：「大行不顧細謹，大禮不辭小讓」", "B": "客對蘇子說：「哀吾生之須臾，羨長江之無窮」", "C": "楚襄王對宋玉說：「快哉此風！寡人所與庶人共者耶」", "D": "燭之武對鄭伯說：「臣之壯也，猶不如人。今老矣，無能為也已」"}, "answer": "A", "explain": "第三段說要設定未來目標，「不要糾結或過多關注生活小事」，把目光放在影響一生的重要事情上。(A)〈鴻門宴〉中樊噲勸劉邦：做大事不必拘泥小節，不必回去辭行，趕快脫身——正是要他別糾結小事、抓住保命的大事，最有助突破，正確。(B)蘇軾〈赤壁賦〉中客人感嘆人生短暫，是悲觀情緒，無助於突破。(C)宋玉〈風賦〉中楚襄王只是享受涼風，與突破困境無關。(D)〈燭之武退秦師〉中燭之武推辭說自己老了沒用，是消極推託，無助於突破。", "skill": "古文應用題：先用一句白話翻出每句話的態度（積極抓重點／悲觀／享樂／推辭），再對應文章的建議。"}], "difficulty": "中", "label": "112二技", "year": 112, "kind": "二技"}, {"id": "et112-45", "exam": "et112", "nums": [45, 46, 47], "form": "題組", "img": "img/et112-45.png", "source": "劉禹錫〈鑒藥〉（節錄）", "author": "劉禹錫", "genre": "說理議論", "types": ["文意推論", "句意理解", "主旨寓意"], "passage": "劉子閒居，有負薪之憂，食精良弗知其旨。客有謂予：「子病，病積日矣。乃今我里有方士，淪跡於醫，厲者造焉而美肥，跛者造焉而善馳。矧常病也，將子詣諸？」予然之，之醫所。切脈、觀色、聆聲，參合而後言曰：「子之病，其興居之節舛，衣食之齊乖所由致也。……我能攻之。」乃出藥一丸，可兼方寸，以授予曰：「服是足以瀹昏煩而鉏蘊結，銷蠱慝而歸耗氣。然中有毒，須其疾瘳而止，過當則傷和，是以微其齊也。」予受藥以餌，過信而腿能輕，痹能和。或聞而慶予，且哄言曰：「子之獲是藥，幾神乎！誠難遭已！顧醫之態多嗇術以自貴，遺患以要財，盍重求之，所至益深矣！」予昧者也，……卒行其言。逮再餌半旬，厥毒果肆，岑岑周體，如痁作焉。悟而走諸醫，醫大吒曰：「吾固知夫子未達也。」促和蠲毒者投之，濱於殆而有喜。異日，進和藥，乃復初。", "translation": "我閒居在家，生了病，吃精美的食物也嘗不出味道。有位客人對我說：「你生病已經很多天了。現在我們鄉里有位方士，隱身在醫生行業裡，長癩瘡的人去找他就變得健美，跛腳的人去找他就能快跑。何況你只是一般的病，要不要帶你去找他？」我同意了，就去了醫生那裡。他把脈、觀察氣色、聽聲音，綜合判斷後說：「你的病，是起居作息失去節制、飲食調配失當造成的。……我能治好它。」於是拿出一顆藥丸，大約一寸見方，交給我說：「吃了這個，足以洗去昏沉煩悶、除去鬱結，消除體內的毒害、收回耗散的元氣。但是藥中有毒，等病好了就要停藥，吃過量就會傷害身體的和氣，所以我把劑量減小了。」我接過藥服下，過了兩夜，腿就輕快了，麻痺也緩和了。有人聽說了來恭喜我，還起鬨說：「你得到這種藥，簡直神了！實在難得碰到！但醫生常常藏著醫術來抬高身價，故意留著病根來要錢，何不加重分量吃，效果會更好！」我是糊塗人，……最後照他的話做了。等再服藥五天，藥毒果然發作，全身冒汗，像得了熱病一樣。我醒悟過來，趕去找醫生，醫生大聲責怪說：「我本來就知道你不明白道理。」趕緊給我解毒的藥，差點危及性命，才總算好轉。後來再服用溫補的藥，才恢復原來的健康。", "keywords": [{"w": "負薪之憂", "m": "生病的婉辭"}, {"w": "旨", "m": "味美"}, {"w": "厲者", "m": "生癩瘡的人"}, {"w": "矧", "m": "何況"}, {"w": "舛", "m": "錯亂"}, {"w": "齊", "m": "通「劑」，調配"}, {"w": "瀹", "m": "疏通、洗滌"}, {"w": "鉏", "m": "除去"}, {"w": "瘳", "m": "病癒"}, {"w": "微其齊", "m": "把劑量減小"}, {"w": "信", "m": "兩夜"}, {"w": "盍", "m": "何不"}, {"w": "岑岑", "m": "汗流的樣子"}, {"w": "痁", "m": "熱病"}, {"w": "蠲毒者", "m": "解毒的藥"}], "questions": [{"n": 45, "qtype": "單選", "stem": "下列選項，何者最符合上文旨意？", "options": {"A": "方士首次給藥且叮囑不可過量", "B": "方士診斷不精使劉子病況加重", "C": "劉子病急亂投醫導致病入膏肓", "D": "劉子貪小便宜不願意持續服藥"}, "answer": "A", "explain": "方士給藥時說「中有毒，須其疾瘳而止，過當則傷和，是以微其齊也」——病好就停、過量會傷身，所以特地把劑量減小，(A)正確。(B)方士診斷準確，劉子服藥兩夜就好轉，是劉子後來自行加藥才中毒，錯。(C)劉子是聽信旁人加重藥量，不是病急亂投醫，最後也救回來了，不到病入膏肓，錯。(D)劉子反而是多吃藥，不是不願服藥，錯。", "skill": "找責任歸屬：病情是在「誰做了什麼之後」惡化的，就是答案的關鍵。"}, {"n": 46, "qtype": "單選", "stem": "下表是劉子初診後所開的診斷證明書，依據上文，下列何者正確？", "options": {"A": "藥品種類：共3種", "B": "病因：興居之節舛，衣食之齊乖", "C": "病況：瀹昏煩而鉏蘊結，銷蠱慝而歸耗氣", "D": "醫師囑言：切脈、觀色、聆聲"}, "answer": "B", "explain": "(A)初診只給了「藥一丸」，不是三種藥（後來的解毒藥、溫補藥是複診的事），錯。(B)醫生說「子之病，其興居之節舛，衣食之齊乖所由致也」，這就是病因，正確。(C)「瀹昏煩而鉏蘊結……」是說藥的功效，不是病況，錯。(D)「切脈、觀色、聆聲」是醫生的診察方法，不是叮嚀囑咐，錯。", "skill": "表格欄位題，先確認原文那句話的功能（原因、功效、方法、叮嚀），再看有沒有放錯格。"}, {"n": 47, "qtype": "單選", "stem": "下表為「藥害救濟法」規範有下列各款情事之一者，不得申請藥害救濟。依文中劉子的情況，若提出藥害救濟申請，無法通過的原因為何？", "options": {"A": "劉子所服之藥乃是試驗用藥", "B": "劉子的熱病採急救方式施藥", "C": "劉子未遵醫囑導致藥害產生", "D": "劉子首次用藥後已獲得賠償"}, "answer": "C", "explain": "法條第一項說：藥害應由受害人等自己負責者，不得申請救濟。劉子明明被醫生叮嚀不可過量，卻聽信旁人「重求之」加量服用，藥害是自己造成的，所以(C)正確。(A)文中沒說是試驗用藥。(B)熱病是吃藥過量後的中毒症狀，不是急救用藥造成的。(D)文中沒有任何賠償。", "skill": "古文結合法條：先把法條每一款濃縮成關鍵詞，再回文中找對得上的情節。"}], "difficulty": "中", "label": "112二技", "year": 112, "kind": "二技"}, {"id": "et113-03", "exam": "et113", "nums": [3], "form": "單題", "img": "img/et113-03.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "衛士仆地／數罟不入洿池／友便辟，友善柔／晉楚治兵，遇於中原，其辟君三舍／矜寡孤獨廢疾者，皆有所養／矜功伐善，好揚人之惡", "translation": "衛士跌倒在地；細密的漁網不放進池塘；和逢迎諂媚的人交朋友、和表面柔順的人交朋友；晉楚兩國交戰，在中原相遇，我將退避三舍；老而無妻、老而無夫、孤兒、獨居老人與殘疾的人都能得到照顧；誇耀自己的功勞和長處，喜歡宣揚別人的缺點。", "keywords": [{"w": "仆", "m": "向前跌倒，讀ㄆㄨ"}, {"w": "數罟", "m": "細密的漁網，數讀ㄘㄨˋ"}, {"w": "便辟", "m": "逢迎諂媚，辟讀ㄆㄧˊ"}, {"w": "辟", "m": "同「避」，讀ㄅㄧˋ"}, {"w": "矜", "m": "讀ㄍㄨㄢ時同「鰥」，老而無妻；讀ㄐㄧㄣ時是誇耀"}], "questions": [{"n": 3, "qtype": "單選", "stem": "下列選項「」中的讀音，前後相同的是：", "options": {"A": "衛士「仆」地／前「仆」後繼", "B": "「數」罟不入洿池／「數」典而忘其祖", "C": "友便「辟」，友善柔／晉楚治兵，遇於中原，其「辟」君三舍", "D": "「矜」寡孤獨廢疾者，皆有所養／「矜」功伐善，好揚人之惡"}, "answer": "A", "explain": "(A)正確：兩個「仆」都是「向前跌倒」，都讀ㄆㄨ（〈鴻門宴〉樊噲撞倒衛士；前仆後繼是前面的人倒下、後面的人跟上）。(B)錯誤：「數罟」的數是「細密」，讀ㄘㄨˋ；「數典忘祖」的數是「一一列舉」，讀ㄕㄨˇ。(C)錯誤：「便辟」是逢迎諂媚，辟讀ㄆㄧˊ；「辟君三舍」的辟同「避」，讀ㄅㄧˋ。(D)錯誤：「矜寡」的矜同「鰥」，讀ㄍㄨㄢ；「矜功伐善」的矜是誇耀，讀ㄐㄧㄣ。", "skill": "破音字先判斷「在句中當什麼意思」，意思一換，讀音常跟著換。"}], "difficulty": "中", "label": "113二技", "year": 113, "kind": "二技"}, {"id": "et113-04", "exam": "et113", "nums": [4], "form": "單題", "img": "img/et113-04.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "向之所欣／向晚不適／既往不咎／難辭其咎／屢試不爽／秋高氣爽／旦日饗士卒／繕甲兵，具卒乘", "translation": "先前所喜愛的；傍晚時心情不暢快；過去的事不再責怪；難以推卸過錯；屢次試驗都沒有差錯；秋天天空高遠、空氣清爽；明天一早犒賞士兵；修整鎧甲兵器，備齊步兵和兵車。", "keywords": [{"w": "向", "m": "先前／接近、將近"}, {"w": "咎", "m": "責怪／過錯"}, {"w": "爽", "m": "差錯／清爽"}, {"w": "卒", "m": "士兵（卒乘：步兵與兵車）"}], "questions": [{"n": 4, "qtype": "單選", "stem": "下列「」內的詞義，前後相同的選項是：", "options": {"A": "「向」之所欣／「向」晚不適", "B": "既往不「咎」／難辭其「咎」", "C": "屢試不「爽」／秋高氣「爽」", "D": "旦日饗士「卒」／繕甲兵，具「卒」乘"}, "answer": "D", "explain": "(D)正確：〈鴻門宴〉「饗士卒」的卒是士兵；〈鄭伯克段于鄢〉「具卒乘」的卒是步兵，兩者都指兵士。(A)錯誤：「向之所欣」（〈蘭亭集序〉）的向是「先前」；「向晚」的向是「接近、將近」。(B)錯誤：「既往不咎」的咎是動詞「責怪」；「難辭其咎」的咎是名詞「過錯」。(C)錯誤：「屢試不爽」的爽是「差錯」；「秋高氣爽」的爽是「清爽」。", "skill": "同一字比較題，先看它在句中當動詞還是名詞，詞性不同，意思多半不同。"}], "difficulty": "中", "label": "113二技", "year": 113, "kind": "二技"}, {"id": "et113-05", "exam": "et113", "nums": [5], "form": "單題", "img": "img/et113-05.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["字詞解釋", "詩詞賞析"], "passage": "揮手自茲去，蕭蕭班馬鳴／憑欄明日意，池闊雨蕭蕭／風蕭蕭兮易水寒，壯士一去兮不復還／漫漫長路，蕭蕭兩鬢黃塵，騎驢漫與行人語", "translation": "揮手從此分別，離群的馬發出蕭蕭的嘶鳴；倚著欄杆想著明天，寬闊的池上雨聲蕭蕭；風聲蕭蕭，易水寒冷，壯士這一去就不再回來；漫長的旅途上，兩鬢稀疏、沾滿黃塵，騎著驢隨口和路人閒聊。", "keywords": [{"w": "蕭蕭", "m": "狀聲詞（馬鳴、雨聲、風聲），或形容稀疏"}, {"w": "班馬", "m": "離群的馬"}], "questions": [{"n": 5, "qtype": "單選", "stem": "下列選項中的「蕭蕭」，何者不是描寫聲音？", "options": {"A": "揮手自茲去，「蕭蕭」班馬鳴", "B": "憑欄明日意，池闊雨「蕭蕭」", "C": "風「蕭蕭」兮易水寒，壯士一去兮不復還", "D": "漫漫長路，「蕭蕭」兩鬢黃塵，騎驢漫與行人語"}, "answer": "D", "explain": "(D)正確：「蕭蕭」修飾「兩鬢」，是頭髮稀疏的樣子，寫旅途勞頓、人已老去，不是聲音。(A)錯誤：李白〈送友人〉，蕭蕭是馬的嘶鳴聲。(B)錯誤：蕭蕭寫雨聲。(C)錯誤：〈易水歌〉，蕭蕭寫風聲。", "skill": "疊字先看它黏著哪個名詞：黏著馬、雨、風多半是聲音，黏著頭髮、樹木多半是稀疏的樣子。"}], "difficulty": "易", "label": "113二技", "year": 113, "kind": "二技"}, {"id": "et113-06", "exam": "et113", "nums": [6], "form": "單題", "img": "img/et113-06.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "文化常識"], "passage": "甲、棄黔首以資敵國\n乙、元和十年，予左遷九江郡司馬\n丙、蘇秦起閭閻，連六國從親，此其智有過人者\n丁、傴僂提攜，往來而不絕者，滁人遊也", "translation": "甲、拋棄百姓去資助敵國。乙、元和十年，我被貶為九江郡司馬。丙、蘇秦出身平民里巷，卻能聯合六國合縱相親，這是他才智過人之處。丁、彎腰駝背的老人和被牽著走的小孩，來來往往不斷的，是滁州人在遊玩。", "keywords": [{"w": "黔首", "m": "百姓"}, {"w": "布衣", "m": "平民"}, {"w": "左遷", "m": "貶官"}, {"w": "真除", "m": "由代理改為正式任命"}, {"w": "閭閻", "m": "里巷，指平民"}, {"w": "朱門", "m": "紅漆大門，指富貴人家"}, {"w": "傴僂", "m": "彎腰駝背，指老人"}, {"w": "黃髮", "m": "老人"}], "questions": [{"n": 6, "qtype": "單選", "stem": "下列甲、乙、丙、丁前後「」中的詞語，替換後意義不變的選項是：", "options": {"A": "甲乙", "B": "乙丙", "C": "丙丁", "D": "甲丁"}, "answer": "D", "explain": "甲（李斯〈諫逐客書〉）：「黔首」是百姓，「布衣」是平民，可替換。乙（白居易〈琵琶行并序〉）：「左遷」是貶官，「真除」是正式任命官職，意思不同。丙（《史記‧蘇秦列傳》）：「閭閻」指平民里巷，「朱門」指富貴人家，意思相反。丁（歐陽脩〈醉翁亭記〉）：「傴僂」指駝背的老人，「黃髮」也指老人，可替換。所以甲丁正確，選(D)；(A)含乙、(B)含乙丙、(C)含丙，皆錯。", "skill": "文化常識詞記成對：百姓＝黔首、布衣；老人＝傴僂、黃髮；富貴＝朱門；平民＝閭閻。"}], "difficulty": "中", "label": "113二技", "year": 113, "kind": "二技"}, {"id": "et113-14", "exam": "et113", "nums": [14], "form": "單題", "img": "img/et113-14.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "三顧臣於草廬之中，諮臣以當世之事，由是感激，遂許先帝以驅馳。\n所以遣將守關者，備他盜之出入與非常也。\n負者歌於途，行者休於樹，前者呼，後者應。\n晉侯、秦伯圍鄭，以其無禮於晉，且貳於楚也。\n孟嘗君使人給其食用，無使乏，於是馮諼不復歌。", "translation": "先帝三次到草屋拜訪我，向我詢問當代大事，我因此感動奮發，就答應為先帝奔走效力。派將領守關的原因，是為了防備其他盜賊出入和意外變故。背東西的人在路上唱歌，走路的人在樹下休息，前面的人呼喊，後面的人回應。晉文公和秦穆公包圍鄭國，因為鄭國對晉無禮，又暗中依附楚國。孟嘗君派人供給馮諼母親的吃用，不讓她缺乏，於是馮諼不再唱歌抱怨。", "keywords": [{"w": "由是", "m": "因此"}, {"w": "所以……者", "m": "……的原因"}, {"w": "以", "m": "因為"}, {"w": "於是", "m": "因此、就"}], "questions": [{"n": 14, "qtype": "單選", "stem": "在〈出師表〉中，「三顧臣於草廬之中，諮臣以當世之事，(由是感激)，【遂許先帝以驅馳】」，屬於先因()後果【】的因果句。下列選項，何者語句用法與此相同？", "options": {"A": "(所以遣將守關者)，【備他盜之出入與非常也】", "B": "(負者歌於途，行者休於樹)，【前者呼，後者應】", "C": "(晉侯、秦伯圍鄭)，【以其無禮於晉，且貳於楚也】", "D": "(孟嘗君使人給其食用，無使乏)，【於是馮諼不復歌】"}, "answer": "D", "explain": "(D)正確：〈馮諼客孟嘗君〉，先有「孟嘗君供養馮母」這個原因，「於是」帶出「馮諼不再唱歌」的結果，先因後果。(A)錯誤：〈鴻門宴〉「所以……者」是先講結果（派兵守關），後面才說原因（防盜），屬先果後因。(B)錯誤：〈醉翁亭記〉是並列描寫遊人，沒有因果。(C)錯誤：〈燭之武退秦師〉先說「圍鄭」這件事，「以」字後面才補原因，屬先果後因。", "skill": "找因果連接詞：「由是、於是、故」後面接結果（先因後果）；「以、所以……者、因為」後面接原因（先果後因）。"}], "difficulty": "中", "label": "113二技", "year": 113, "kind": "二技"}, {"id": "et113-16", "exam": "et113", "nums": [16], "form": "單題", "img": "img/et113-16.png", "source": "訃聞（應用文）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "顯考李公○府君慟於中華民國一一二年六月十日農曆四月二十三日上午九時三十分壽終正寢，距生於民國二十六年五月三日，□□八十有七歲。孤子女等隨侍在側，親視含殮，遵禮成服，設靈於堂。謹擇於中華民國一一二年六月二十日農曆五月三日星期二上午八時三十分假臺北市殯儀館○○廳舉行家奠，九時公奠，後隨即發引火化。", "translation": "先父李○○先生於民國112年6月10日（農曆4月23日）上午9時30分在家中安然過世，生於民國26年5月3日，享壽87歲。子女們都陪在身邊，親自看著入殮，依禮穿上喪服，在家設立靈堂。謹定於民國112年6月20日（農曆5月3日，星期二）上午8時30分在臺北市殯儀館○○廳舉行家祭，9時舉行公祭，之後隨即出殯火化。", "keywords": [{"w": "顯考", "m": "對亡父的尊稱"}, {"w": "壽終正寢", "m": "男性長者在家中自然死亡"}, {"w": "享壽／得年", "m": "六十歲以上稱享壽，未滿六十稱得年"}, {"w": "孤子", "m": "父喪而母在時，子女自稱"}, {"w": "家奠／公奠", "m": "家屬祭拜／親友同事公開祭拜"}, {"w": "南極星沉", "m": "男性長者的輓辭"}], "questions": [{"n": 16, "qtype": "單選", "stem": "請檢視右列訃聞內容，選出正確選項：", "options": {"A": "□□應填入得年", "B": "治喪發訃聞者為亡者之妻", "C": "電子輓辭可選擇「南極星沉」", "D": "身為亡者之同事，應在八時三十分前抵達參加家祭"}, "answer": "C", "explain": "(C)正確：亡者是「顯考李公」，男性，87歲；「南極星沉」用於男性長者的喪事，適合。(A)錯誤：民國26年生、112年過世，87歲，超過六十應填「享壽」，不是「得年」。(B)錯誤：署名是「孤子女等」，發訃聞的是亡者的子女，訃聞中沒有出現妻子。(D)錯誤：同事是外人，應參加9時的「公奠」；8時30分的「家奠」是家屬的祭拜。", "skill": "看訃聞抓三點：性別（顯考／顯妣）、年齡（享壽／得年）、場次（家奠給家屬，公奠給親友同事）。"}], "difficulty": "中", "label": "113二技", "year": 113, "kind": "二技"}, {"id": "et113-17", "exam": "et113", "nums": [17], "form": "單題", "img": "img/et113-17.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["文化常識", "字詞解釋"], "passage": "冠蓋雲集／策馬飛輿／攬轡登車／重蹈覆轍", "translation": "官員們的帽子和車蓋像雲一樣聚集；鞭策馬匹讓車子飛馳；手持韁繩登上車子；再走上翻車的老路。", "keywords": [{"w": "蓋", "m": "車上的篷頂"}, {"w": "輿", "m": "車廂"}, {"w": "轡", "m": "駕馭馬的韁繩"}, {"w": "轍", "m": "車輪輾過留下的痕跡"}], "questions": [{"n": 17, "qtype": "單選", "stem": "下列選項「」中的馬車相關用語，與右圖對應錯誤的是：", "options": {"A": "甲：冠「蓋」雲集", "B": "乙：策馬飛「輿」", "C": "丙：攬「轡」登車", "D": "丁：重蹈覆「轍」"}, "answer": "D", "explain": "(D)正確（對應錯誤）：圖中丁指的是「車輪」，但「轍」是車輪壓過地面留下的痕跡，不是車輪本身。(A)對應正確：甲指車頂的篷蓋，就是「蓋」。(B)對應正確：乙指載人的車廂，就是「輿」。(C)對應正確：丙指馬頭連到車上的韁繩，就是「轡」。", "skill": "車字家族記部位：蓋在上、輿是箱、轡是繩、輪是輪、轍是輪印。"}], "difficulty": "中", "label": "113二技", "year": 113, "kind": "二技"}, {"id": "et113-19", "exam": "et113", "nums": [19, 20], "form": "題組", "img": "img/et113-19.png", "source": "《墨子‧公輸》", "author": "墨子", "genre": "說理議論", "types": ["文意推論", "寫作手法"], "passage": "公輸盤為楚造雲梯之械成，將以攻宋。子墨子聞之，起於齊，行十日十夜而至於郢，見公輸盤。公輸盤曰：「夫子何命焉為？」子墨子曰：「北方有侮臣者，願藉子殺之。」公輸盤不說。子墨子曰：「請獻十金。」公輸盤曰：「吾義固不殺人。」子墨子起，再拜曰：「請說之。吾從北方聞子為梯，將以攻宋。宋何罪之有？荊國有餘於地，而不足於民，殺所不足，而爭所有餘，不可謂智。宋無罪而攻之，不可謂仁。知而不爭，不可謂忠。爭而不得，不可謂強。義不殺少而殺眾，不可謂知類。」公輸盤服。", "translation": "公輸盤替楚國造好了雲梯這種攻城器械，準備用來攻打宋國。墨子聽到消息，從齊國出發，走了十天十夜到達楚都郢，去見公輸盤。公輸盤說：「先生有什麼指教？」墨子說：「北方有個欺侮我的人，想借您的力量殺了他。」公輸盤不高興。墨子說：「我願意奉上十金。」公輸盤說：「我講道義，絕不殺人。」墨子站起來，拜了兩拜說：「請讓我說明。我在北方聽說您造了雲梯，要去攻打宋國。宋國有什麼罪？楚國土地有餘而人口不足，犧牲不足的人民去爭奪多餘的土地，不能說是聰明。宋國無罪卻攻打它，不能說是仁。明白道理卻不勸諫楚王，不能說是忠。勸諫了卻沒成功，不能說是堅強。您講道義不肯殺一個人，卻要去殺很多人，不能說是懂得類推事理。」公輸盤被說服了。", "keywords": [{"w": "說", "m": "同「悅」，高興；「請說之」的說是解說"}, {"w": "荊國", "m": "楚國"}, {"w": "爭", "m": "同「諍」，勸諫"}, {"w": "知類", "m": "懂得類推事理"}], "questions": [{"n": 19, "qtype": "單選", "stem": "下列選項，何者最符合上文文意？", "options": {"A": "墨子前往楚國向公輸盤請教造雲梯之術", "B": "公輸盤欲以十金之酬請墨子殺侮他之人", "C": "公輸盤最後仍接受了墨子所贈送之戰服", "D": "墨子見公輸盤的目的在阻止他攻打宋國"}, "answer": "D", "explain": "(D)正確：墨子一聽說雲梯要攻宋，就日夜趕路到郢，最後指出「宋何罪之有」，目的就是阻止攻宋。(A)錯誤：墨子不是來學造雲梯，而是來勸阻。(B)錯誤：是墨子假裝請公輸盤殺人，並說要獻十金；公輸盤拒絕了。(C)錯誤：文中沒有「戰服」，結尾「公輸盤服」的服是「信服」。", "skill": "文言的「服」常是動詞「信服」，別直覺看成衣服。"}, {"n": 20, "qtype": "單選", "stem": "依上文，下列選項何者最能說明墨子說服公輸盤的策略？", "options": {"A": "藉彼喻此，說之以理", "B": "旁敲側擊，動之以情", "C": "虛張聲勢，曉之以弊", "D": "引君入甕，誘之以利"}, "answer": "A", "explain": "(A)正確：墨子先用「請你殺一個欺侮我的人」做比喻，讓公輸盤說出「吾義固不殺人」，再指出攻宋會殺更多人，最後連用智、仁、忠、強、知類五點講道理，正是藉彼喻此、說之以理。(B)錯誤：墨子是講道理，不是打感情牌。(C)錯誤：墨子沒有誇大聲勢嚇人。(D)錯誤：「獻十金」只是設局的一步，最後打動公輸盤的是道理，不是利益。", "skill": "說服策略題：找出說服者「先讓對方承認什麼、再用那句話反將一軍」，就是類比說理。"}], "difficulty": "易", "label": "113二技", "year": 113, "kind": "二技"}, {"id": "et113-21", "exam": "et113", "nums": [21, 22], "form": "題組", "img": "img/et113-21.png", "source": "史書常識（《史記》、《左傳》）", "author": "", "genre": "其他", "types": ["文化常識", "典故出處"], "passage": "", "translation": "", "keywords": [{"w": "紀傳體", "m": "以人物傳記為中心的史書體例，如《史記》"}, {"w": "編年體", "m": "依年月先後記事的史書體例，如《左傳》"}, {"w": "三傳", "m": "解釋《春秋》的《左傳》、《公羊傳》、《穀梁傳》"}, {"w": "四史", "m": "《史記》、《漢書》、《後漢書》、《三國志》"}], "questions": [{"n": 21, "qtype": "單選", "stem": "依上圖，判斷甲、乙應分別填入何者？", "options": {"A": "甲：《史記》／乙：《左傳》", "B": "甲：《史記》／乙：《戰國策》", "C": "甲：《左傳》／乙：《三國志》", "D": "甲：《三國志》／乙：《戰國策》"}, "answer": "A", "explain": "(A)正確：甲連到「紀傳體、項羽本紀、四史之一」，是《史記》；乙連到「編年體、三傳之一、魯僖公30年」，是《左傳》。(B)(D)錯誤：《戰國策》是國別體，不是編年體，也不屬於三傳。(C)錯誤：《左傳》是編年體不是紀傳體；《三國志》是紀傳體，且沒有〈項羽本紀〉。", "skill": "史書三體記代表作：紀傳體《史記》、編年體《左傳》、國別體《國語》《戰國策》。"}, {"n": 22, "qtype": "單選", "stem": "某國文課本收錄〈鴻門宴〉、〈燭之武退秦師〉兩篇文章，若要搭配上圖，放入①、②、③、④之中，何者正確？", "options": {"A": "①〈鴻門宴〉；②〈燭之武退秦師〉", "B": "①〈燭之武退秦師〉；③〈鴻門宴〉", "C": "②〈鴻門宴〉；④〈燭之武退秦師〉", "D": "③〈鴻門宴〉；④〈燭之武退秦師〉"}, "answer": "C", "explain": "(C)正確：〈鴻門宴〉選自《史記‧項羽本紀》，應放在接著「項羽本紀」的②；〈燭之武退秦師〉記魯僖公三十年的事，選自《左傳》，應放在接著「魯僖公30年」的④。(A)錯誤：〈燭之武退秦師〉不在《史記》之下。(B)錯誤：〈燭之武退秦師〉不屬於甲（《史記》），〈鴻門宴〉也不屬於乙（《左傳》）。(D)錯誤：〈鴻門宴〉出自《史記》，不能放在乙之下的③。", "skill": "課文出處要連到「篇名」層級：〈鴻門宴〉→〈項羽本紀〉，〈燭之武退秦師〉→《左傳》僖公三十年。"}], "difficulty": "易", "label": "113二技", "year": 113, "kind": "二技"}, {"id": "et113-25", "exam": "et113", "nums": [25, 26, 27], "form": "題組", "img": "img/et113-25.png", "source": "劉大櫆〈遊萬柳堂記〉", "author": "劉大櫆", "genre": "山水遊記", "types": ["主旨寓意", "人物情感", "寫作手法"], "passage": "昔之人貴極富溢，則往往為別館以自娛，窮極土木之工，而無所愛惜。既成，則不得久居其中，偶一至焉而已，有終身不得至者焉；而人之得久居其中者，力又不足以為之。夫賢公卿勤勞王事，固將不暇於此，而卑庸者類欲以此震耀其鄉里之愚。\n臨朐相國馮公，其在廷時無可訾，亦無可稱，而有園在都城之東南隅。其廣三十畝，無雜樹，隨地勢之高下，盡植以柳，而榜其堂曰「萬柳之堂」。短牆之外，騎行者可望而見，其中徑曲而深，因其窪以為池，而累其土以成山，池旁皆蒹葭，雲水蕭疏可愛。\n雍正之初，予始至京師，則好遊者咸為予言此地之勝。一至，猶稍有亭榭。再至，則向之飛梁架於水上者，今欹臥於水中矣。三至，則凡其所植柳，斬焉無一株之存。\n人世富貴之光榮，其與時升降，蓋略與此園等。然則士苟有以自得，宜其不外慕乎富貴。彼身在富貴之中者，方殷憂之不暇，又何必朘民之膏以為苑囿也哉！", "translation": "從前的人富貴到了極點，往往建造別墅來自娛，用盡土木工程的技巧，毫不吝惜花費。建好後卻不能長住，偶爾去一次罷了，甚至有一輩子都沒去過的；而能夠長住在裡面的人，財力又不足以建造。賢能的公卿忙於國事，本來就沒空做這種事，只有平庸低下的人才想用這個向鄉里的愚人炫耀。\n臨朐的馮相國，在朝廷時沒什麼可批評的，也沒什麼可稱讚的，他在京城東南角有座園子。占地三十畝，沒有雜樹，順著地勢高低全種上柳樹，把廳堂題名為「萬柳之堂」。矮牆外騎馬經過的人都望得見，園中小路彎曲幽深，就著低窪處挖成水池，把挖出的土堆成假山，池邊長滿蘆葦，雲影水光疏朗可愛。\n雍正初年，我剛到京城，喜愛遊覽的人都對我說這裡景色優美。第一次去，還稍有亭臺水榭。第二次去，從前架在水上的橋，現在已傾倒在水中了。第三次去，所種的柳樹全被砍光，一棵也不剩。\n人世間富貴的光榮，隨著時勢起落，大概就和這座園子差不多。那麼讀書人如果內心有自得之處，就應該不羨慕外在的富貴。那些身在富貴中的人，正憂慮都來不及，又何必搜刮百姓的血汗來建造園林呢！", "keywords": [{"w": "別館", "m": "別墅"}, {"w": "訾", "m": "批評、非議"}, {"w": "榜", "m": "題匾、題名"}, {"w": "欹臥", "m": "傾倒、斜躺"}, {"w": "朘", "m": "剝削、搜刮"}, {"w": "苑囿", "m": "園林"}], "questions": [{"n": 25, "qtype": "單選", "stem": "依據上文，作者寫作本文的主要意旨為何？", "options": {"A": "探討園林規模與官職地位的關聯性，故有財力未必就能擁有園林", "B": "稱頌馮公位高權重，仍保有優雅生活態度，建堂為後世留下美景", "C": "說明富貴難久恃，士人應有自身追求目標，對身外富貴不必羨慕", "D": "強調達官貴人誇耀財富之餘，也應重視與民同樂，避免浪費物資"}, "answer": "C", "explain": "(C)正確：末段「人世富貴之光榮，其與時升降」說富貴靠不住，「士苟有以自得，宜其不外慕乎富貴」說讀書人要有自己的追求，正是主旨。(A)錯誤：文章不是在討論園林規模和官位的關係。(B)錯誤：作者說馮公「無可訾，亦無可稱」，並沒有稱頌他，萬柳堂最後也荒廢了。(D)錯誤：作者批評的是「朘民之膏以為苑囿」，並沒有主張「與民同樂」。", "skill": "遊記的主旨多半藏在最後一段的議論句，先找「然則、宜、何必」這類收束詞。"}, {"n": 26, "qtype": "單選", "stem": "文中關於「一至」、「再至」、「三至」三遊萬柳堂的心情，與下列敘述何者最接近？", "options": {"A": "苑囿物是人非，令人不勝唏噓", "B": "古蹟徒具盛名，興發改建之念", "C": "美景昔盛今衰，尤覺反差失落", "D": "官場世態炎涼，倍感人情冷暖"}, "answer": "C", "explain": "(C)正確：別人說此地「勝」，作者三次去卻看到亭榭漸少、橋倒水中、柳樹砍光，一次比一次荒涼，和傳聞中的美景形成強烈反差。(A)錯誤：變的是景物，不是「物是人非」（景物依舊、人事已變）。(B)錯誤：作者沒有想要改建。(D)錯誤：這段寫的是園林景物的變化，不是官場人情。", "skill": "「一至、再至、三至」這類層遞，重點在比較每次的差別，從差別推心情。"}, {"n": 27, "qtype": "單選", "stem": "下列選項中依序對上文各段文意脈絡的說明，何者正確？", "options": {"A": "發表議論→敘述事例→景物對比→感發抒志", "B": "徵言論事→頌揚古人→反省自身→首尾照應", "C": "提出主張→對照反思→據事說理→卒章顯志", "D": "取譬為證→借事論理→回顧經驗→綜合結論"}, "answer": "A", "explain": "(A)正確：第一段議論富貴者建別館的現象；第二段敘述馮公萬柳堂的事例；第三段用三次遊覽對比景物盛衰；第四段由此感發，抒發不慕富貴的志向。(B)錯誤：第一段沒有引用他人言論，第二段也沒有頌揚馮公。(C)錯誤：第二段是敘述萬柳堂，不是「對照反思」；第三段是寫景，不是說理。(D)錯誤：第一段不是用比喻作證，第三段寫的是遊覽見聞，不只是回顧經驗。", "skill": "段落脈絡題：每段用一個動詞（議、敘、寫、抒）標記，再和選項逐段比對。"}], "difficulty": "中", "label": "113二技", "year": 113, "kind": "二技"}, {"id": "et113-28", "exam": "et113", "nums": [28, 29, 30], "form": "題組", "img": "img/et113-28.png", "source": "清《古今圖書集成》；元‧駱天驤《類編長安志‧卷之八》", "author": "駱天驤", "genre": "筆記小品", "types": ["文意推論", "比較閱讀", "典故出處"], "passage": "【甲】西安府白水縣拾遺廟因兵燬，鄉人建祠，塑十婦像，呼為十姨，至金令陳炳掘得詩碑，乃杜甫廟也，遂毀像祀甫。今廟廢。\n【乙】安祿山入潼關，法駕狩劍外。秋七月，肅宗即位於靈武殿，改元至德。二載，杜甫自賊中竄歸鳳翔，謁肅宗，授以左拾遺。甫詩云：「去年潼關破，妻子隔絕久。麻鞋見天子，衣袖露兩肘。涕淚受拾遺，流離主恩厚。」有詔許至川迎家，甫舅崔少府為泉尉，自三川挈妻子至白水而依居焉，有〈彭衙行〉。甫去，人思之，立拾遺祠，刻〈彭衙行〉立其中。\n經五季兵火，復建其祠，塑十婦人，呼為十阿姨廟。貞祐丙子，縣令陳炳勸農，問其故，父老指其地曰：「此古廟基也。」掘出石刻，命適安老人段子新為記，復建唐左拾遺杜甫祠，以〈彭衙行〉立其中。", "translation": "【甲】西安府白水縣的拾遺廟因戰火被毀，鄉人重建祠堂，塑了十個婦女像，稱為「十姨」。到了金代，縣令陳炳挖出刻詩的石碑，才知道這是杜甫廟，於是毀掉婦女像，改祭杜甫。現在廟已荒廢。\n【乙】安祿山攻入潼關，玄宗逃到劍閣以南。七月，肅宗在靈武即位，改年號為至德。至德二年，杜甫從叛軍占領區逃到鳳翔，拜見肅宗，被任命為左拾遺。杜甫的詩說：「去年潼關失守，和妻兒分隔很久。穿著麻鞋去見天子，衣袖破得露出兩肘。流著淚接受拾遺官職，流離中更覺君恩深厚。」皇帝下詔准他到三川接家人。杜甫的舅舅崔少府當時任白水縣尉，杜甫就帶著妻兒從三川到白水投靠他，寫了〈彭衙行〉。杜甫離開後，當地人懷念他，建了拾遺祠，把〈彭衙行〉刻石立在祠中。\n經過五代的戰火，祠堂重建，卻塑了十個婦人像，叫做「十阿姨廟」。金宣宗貞祐丙子年，縣令陳炳出巡勸導農事，問起緣由，老人指著那塊地說：「這是古廟的地基。」挖出石刻後，請適安老人段子新寫記，重建唐左拾遺杜甫祠，把〈彭衙行〉立在祠中。", "keywords": [{"w": "拾遺", "m": "唐代諫官名；「拾遺」與「十姨」音近"}, {"w": "法駕狩劍外", "m": "皇帝逃往劍閣以南（狩是避諱「逃難」的說法）"}, {"w": "挈", "m": "帶領"}, {"w": "五季", "m": "五代"}], "questions": [{"n": 28, "qtype": "單選", "stem": "依據上文，下列關於拾遺廟的敘述何者正確？", "options": {"A": "從唐末五代至明清時期，均誤傳為十阿姨廟", "B": "鄉人以杜甫居於白水時，所任官名建祠思念", "C": "於唐肅宗即位之前建成，至金貞祐年間廢廟", "D": "陳炳挖掘古廟地基之後，證實杜甫葬於此地"}, "answer": "B", "explain": "(B)正確：杜甫當時官任「左拾遺」，他離開白水後「人思之，立拾遺祠」，就是用他的官名建祠紀念。(A)錯誤：金代陳炳已更正為杜甫祠，並非到明清都誤傳。(C)錯誤：杜甫是在肅宗即位後才被授拾遺，祠在他離開白水後才建；金代是重建而非廢廟，甲文說「今廟廢」是清代的事。(D)錯誤：挖出的是〈彭衙行〉詩碑石刻，不是墳墓，沒有說杜甫葬在這裡。", "skill": "雙文本記事題，先排時間線（唐建祠→五代誤塑→金更正→清已廢），再一一核對選項。"}, {"n": 29, "qtype": "單選", "stem": "依據甲、乙二文，判斷下列①、②的敘述，選出正確選項：①甲文中所提及之「詩碑」，應指乙文所說的〈彭衙行〉石刻 ②杜甫因寫〈彭衙行〉一詩，肅宗遂詔許杜甫至三川迎接家人", "options": {"A": "①、②皆正確", "B": "①、②皆錯誤", "C": "①正確，②錯誤", "D": "①錯誤，②正確"}, "answer": "C", "explain": "①正確：乙文說祠中「刻〈彭衙行〉立其中」，陳炳「掘出石刻」，正是甲文的「詩碑」。②錯誤：順序弄反了。是肅宗先「有詔許至川迎家」，杜甫到白水投靠舅舅後才寫〈彭衙行〉，不是因為寫了詩才獲准接家人。所以選(C)；(A)(D)認為②對，(B)認為①錯，皆不對。", "skill": "「因為……所以……」的判斷題，最常見的陷阱是把前後順序對調，回原文核對先後。"}, {"n": 30, "qtype": "單選", "stem": "下列選項，何者與拾遺廟改塑十婦人像的致誤原因最接近？", "options": {"A": "因環境條件不同而產生變異，如「橘生淮北則為枳」", "B": "郢人誤書「舉燭」，燕相解以「舉賢」之意，而國大治", "C": "江陵有村民，事伍子胥神，誤呼「五髭鬚」，乃畫五丈夫", "D": "「己亥涉河」在傳抄刊刻過程中，因形近訛誤成「三豕涉河」"}, "answer": "C", "explain": "(C)正確：「拾遺」被聽成音近的「十姨」，就塑了十個婦人；「伍子胥」被聽成音近的「五髭鬚」，就畫了五個男人，都是「讀音相近而誤解，再照字面造像」。(A)錯誤：橘變枳是環境造成的變化，不是誤會。(B)錯誤：郢書燕說是對文字的曲解附會，不是讀音相近。(D)錯誤：「己亥」誤成「三豕」是字形相近造成的錯誤，不是讀音。", "skill": "致誤原因分三類：音近（聽錯）、形近（抄錯）、義解（解錯），先判斷題目是哪一類。"}], "difficulty": "中", "label": "113二技", "year": 113, "kind": "二技"}, {"id": "et113-31", "exam": "et113", "nums": [31, 32], "form": "題組", "img": "img/et113-31.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["句意理解", "文意推論"], "passage": "天無私覆，地無私載／天道忌滿，人道忌全／謀事在人，成事在天／安時處順，知命樂天", "translation": "天沒有偏私地覆蓋萬物，地沒有偏私地承載萬物；天道忌諱盈滿，人事忌諱求全；計畫在於人，成功與否在於天；安於時運、順應變化，明白天命而樂觀自在。", "keywords": [{"w": "無私", "m": "沒有偏私"}, {"w": "忌", "m": "忌諱、避免"}, {"w": "安時處順", "m": "安於時運、順應變化（語出《莊子》）"}], "questions": [{"n": 31, "qtype": "單選", "stem": "依據文意，文章中畫線處最適合填入的句子是：", "options": {"A": "總是樂在其中", "B": "常是來者不拒", "C": "往往是很曖昧", "D": "大致是較消極"}, "answer": "C", "explain": "(C)正確：空格後面接「既欣賞，又畏懼；既崇敬，卻又要加以征服」，都是兩種矛盾的態度並存，用「曖昧」（態度不明確、模稜兩可）最貼切。(A)錯誤：有畏懼、有征服，不只是快樂。(B)錯誤：「來者不拒」是全盤接受，和「畏懼、征服」不合。(D)錯誤：「加以征服」是積極的作為，不是消極。", "skill": "填空題看冒號後面的說明：說明內容彼此矛盾，就選能概括「矛盾」的詞。"}, {"n": 32, "qtype": "單選", "stem": "文章中提到「自然世界只是一個無所感的存在」，下列選項何者與此意旨最接近？", "options": {"A": "天無私覆，地無私載", "B": "天道忌滿，人道忌全", "C": "謀事在人，成事在天", "D": "安時處順，知命樂天"}, "answer": "A", "explain": "(A)正確：「天無私覆，地無私載」是說天地對萬物沒有偏愛，和文中「自然無所感，對人類的苦樂永遠保持中立」意思一致。(B)錯誤：講的是凡事不要求滿求全，和自然中立無關。(C)錯誤：強調成敗由天決定，反而是說天在主宰，不是中立。(D)錯誤：講人面對命運的態度要安順樂觀，主角是人不是自然。", "skill": "把文言選項先翻成一句白話，再和題目的關鍵詞（這裡是「中立、不偏私」）比對。"}], "difficulty": "中", "label": "113二技", "year": 113, "kind": "二技"}, {"id": "et113-39", "exam": "et113", "nums": [39, 40, 41], "form": "題組", "img": "img/et113-39.png", "source": "袁枚《子不語》", "author": "袁枚", "genre": "筆記小品", "types": ["人物情感", "文意推論", "寫作手法"], "passage": "溧陽馬孝廉豐，未第時，館于邑之西村李家。鄰有王某，性凶惡。妻饑餓，無以自存，竊李家雞烹食之。李知之，告其夫。夫方被酒，大怒，持刀牽妻至。審問得實，將殺之。妻大懼，誣雞為孝廉所竊。孝廉與爭，無以自明，曰：「村有關神廟，請往擲杯珓卜之。卦陰者婦人竊，卦陽者男子竊。」如其言，三擲皆陽。王投刀放妻歸，而孝廉以竊雞故，為村人所薄，失館數年。\n他日，有扶乩者方登壇，自稱關神。孝廉記前事，大罵神之不靈。乩書灰盤曰：「馬孝廉，汝將來有臨民之職，亦知事有緩急重輕耶？汝竊雞，不過失館；某妻竊雞，立死刀下矣。我寧受不靈之名，以救生人之命。上帝念我能識政體，故超升三級。汝乃怨我耶？」孝廉曰：「關神既封帝矣，何級之升？」乩神曰：「今四海九州皆有關神廟，焉得有許多關神分享血食。凡村鄉所立關廟，皆奉上帝命，擇里中鬼平生正直者代司其事，真關神在帝左右，何能降凡耶？」孝廉乃服。", "translation": "溧陽的舉人馬豐，還沒考中進士時，在縣城西村李家當家庭教師。鄰居王某性情凶惡。他的妻子餓得活不下去，偷了李家的雞煮來吃。李家知道了，告訴她丈夫。王某正喝醉酒，大怒，拿著刀把妻子拖來。審問屬實，要殺她。妻子非常害怕，誣賴雞是馬孝廉偷的。孝廉和她爭辯，卻沒辦法證明自己清白，就說：「村裡有關帝廟，請去擲筊占卜。陰卦是婦人偷的，陽卦是男人偷的。」照他的話去擲，三次都是陽卦。王某丟下刀放妻子回家，孝廉卻因偷雞的罪名被村人看不起，好幾年都找不到教書的工作。\n後來有一天，有人扶乩，降壇的神自稱關帝。孝廉想起從前的事，大罵神不靈驗。乩筆在沙盤上寫道：「馬孝廉，你將來會當治理百姓的官，難道不懂事情有輕重緩急嗎？你被說偷雞，不過丟了工作；王某的妻子偷雞，立刻就會死在刀下。我寧可背上不靈驗的名聲，也要救活人一命。上帝看我懂得治理的道理，所以把我連升三級。你竟然還怨我？」孝廉說：「關公已經封為帝了，還升什麼級？」乩神說：「現在天下到處都有關帝廟，哪有那麼多關公去享用祭品？凡是鄉村建的關帝廟，都是奉上帝之命，挑選鄉里中生前正直的鬼魂代管，真正的關帝在上帝身邊，怎麼能下凡呢？」孝廉這才信服。", "keywords": [{"w": "孝廉", "m": "明清時對舉人的稱呼"}, {"w": "館", "m": "當家庭教師（失館：失去教職）"}, {"w": "被酒", "m": "喝醉酒"}, {"w": "杯珓", "m": "占卜用的筊杯"}, {"w": "薄", "m": "輕視"}, {"w": "扶乩", "m": "請神降臨、以乩筆寫字的占卜方式"}, {"w": "血食", "m": "享用祭品"}], "questions": [{"n": 39, "qtype": "單選", "stem": "依據上文，馬孝廉的舉止思維，最符合下列何項敘述？", "options": {"A": "忍辱負重，極力蒐證尋求真相", "B": "忿懣不平，抱怨關神判決失準", "C": "大義凜然，蒙不白之冤以保全王妻", "D": "貪慕富貴，期望關神助他重獲官職"}, "answer": "B", "explain": "(B)正確：孝廉因為擲筊結果被冤枉、失業多年，一遇到關神降壇就「大罵神之不靈」，是滿腔怨氣、抱怨判決不準。(A)錯誤：他沒有蒐證，而是交給擲筊，事後也只是罵神。(C)錯誤：他是被動蒙冤，並非自願犧牲來救王妻；真正選擇救人的是關神。(D)錯誤：他當時只是失去教職，文中沒有他想求官的描寫。", "skill": "人物心態題，抓人物「說了什麼、做了什麼」的動詞，「大罵」就是最直接的證據。"}, {"n": 40, "qtype": "單選", "stem": "依據上文，判斷下列①、②關於事件中因果關係的敘述，選出正確選項：①因為李家嫉妒孝廉名聲，所以與村人共謀陷害 ②因為關神重好生之德，所以寧受不靈驗之名", "options": {"A": "①、②皆正確", "B": "①、②皆錯誤", "C": "①正確，②錯誤", "D": "①錯誤，②正確"}, "answer": "D", "explain": "①錯誤：陷害孝廉的是王妻，她是怕被丈夫殺死才誣賴孝廉，不是李家嫉妒共謀。②正確：關神說「我寧受不靈之名，以救生人之命」，就是重視保全生命。所以選(D)；(A)(C)認為①對，(B)認為②錯，皆不對。", "skill": "因果判斷先確認「是誰做的」，主詞一換，整句就錯。"}, {"n": 41, "qtype": "單選", "stem": "有關本文的寫作手法，下列敘述何者正確？", "options": {"A": "以兩個「無以」表示王妻被逼到極限", "B": "以兩個「不靈」表達神佛的不可信任", "C": "以順敘方式說明一日之間的事件過程", "D": "以神與人的對話增加故事的神怪特質"}, "answer": "D", "explain": "(D)正確：後半段用乩神和孝廉一問一答，透露關神升級、各地關廟由鬼魂代管等神界內幕，增添了神怪色彩。(A)錯誤：第一個「無以自存」說王妻，第二個「無以自明」說孝廉，不都是王妻。(B)錯誤：第一個「不靈」是孝廉罵神，第二個是關神自願承擔「不靈」之名，用意在說明神的權衡，不是說神佛不可信。(C)錯誤：事件橫跨數年（「失館數年」、「他日」），不是一天之內。", "skill": "「兩個相同詞語」的題目，要分別回原文看各自的主詞是誰。"}], "difficulty": "中", "label": "113二技", "year": 113, "kind": "二技"}, {"id": "et113-42", "exam": "et113", "nums": [42, 43, 44], "form": "題組", "img": "img/et113-42.png", "source": "蘇軾〈後赤壁賦〉（試卷標為〈赤壁賦〉）；林語堂《蘇東坡傳》", "author": "蘇軾", "genre": "古典詩詞曲", "types": ["寫作手法", "比較閱讀", "句意理解"], "passage": "於是攜酒與魚，復遊於赤壁之下。江流有聲，斷岸千尺。山高月小，水落石出。曾日月之幾何，而江山不可復識矣。予乃攝衣而上，履巉巖，披蒙茸。踞虎豹，登虬龍。攀栖鶻之危巢，俯馮夷之幽宮。蓋二客不能從焉。劃然長嘯，草木震動。山鳴谷應，風起水湧。予亦悄然而悲，肅然而恐，凜乎其不可久留也。反而登舟，放乎中流，聽其所止而休焉。時夜將半，四顧寂寥，適有孤鶴，橫江東來，翅如車輪，玄裳縞衣，戛然長鳴，掠予舟而西也。須臾客去，予亦就睡。", "translation": "於是帶著酒和魚，再次到赤壁下遊玩。江水奔流有聲，陡峭的江岸高達千尺。山很高，月亮顯得很小，水位下降，石頭露了出來。才隔了多少日子，江山景色竟已認不出來了。我於是提起衣襬往上爬，踩著險峻的岩石，撥開叢生的草木；坐在形似虎豹的怪石上，登上形似虬龍的樹木；攀到鶻鳥棲息的高巢，俯看水神馮夷的深宮。兩位客人沒辦法跟上來。我劃破寂靜長嘯一聲，草木都被震動，山谷鳴響回應，風起浪湧。我也不禁憂傷起來，肅然生出恐懼，覺得寒氣逼人不能久留。於是回到船上，把船放到江心，任它漂到哪裡就停在哪裡。這時快半夜了，四周冷清寂靜，剛好有一隻孤鶴從東邊橫越江面飛來，翅膀大得像車輪，黑色的下襬、白色的上衣（形容羽毛），長叫一聲，擦過我的船向西飛去。不久客人離開，我也睡了。", "keywords": [{"w": "曾", "m": "才、竟"}, {"w": "攝衣", "m": "提起衣襬"}, {"w": "巉巖", "m": "高險的岩石"}, {"w": "蒙茸", "m": "叢生的草木"}, {"w": "馮夷", "m": "傳說中的水神"}, {"w": "劃然", "m": "形容嘯聲劃破寂靜"}, {"w": "玄裳縞衣", "m": "黑裙白衣，形容鶴的羽色"}, {"w": "戛然", "m": "鳥鳴聲"}], "questions": [{"n": 42, "qtype": "單選", "stem": "下列關於甲文的說明，何者正確？", "options": {"A": "述及作者對青春歲月流逝的感悟", "B": "藉由自然之理明示人生處世之道", "C": "著重作者與二客登巖同遊的描述", "D": "依作者的遊歷動線順敘夜間情景"}, "answer": "D", "explain": "(D)正確：從到赤壁下、攝衣而上攀巖、長嘯後感到恐懼、回船放乎中流、夜半見孤鶴到就睡，完全照遊覽的路線與時間順序寫夜景。(A)錯誤：「曾日月之幾何」感嘆的是短短時間江山就變了樣，不是感嘆青春流逝。(B)錯誤：這段以寫景敘事為主，沒有藉自然之理講處世道理（那是〈赤壁賦〉前篇「水與月」的內容）。(C)錯誤：「二客不能從焉」，攀巖時只有作者一人。", "skill": "遊記敘述順序題，把文中的「移動動詞」（遊、上、反、登舟、睡）圈出來，就看得出動線。"}, {"n": 43, "qtype": "單選", "stem": "判斷下列①、②關於乙文解析甲文的說明，選出正確選項：①「有固定的節奏與較為寬泛的音韻」，可從甲文畫線處文句得到印證 ②「山水的細微處不易看出」所塑造的空間感，可與甲文「曾日月之幾何，而江山不可復識」呼應", "options": {"A": "①、②皆正確", "B": "①、②皆錯誤", "C": "①正確，②錯誤", "D": "①錯誤，②正確"}, "answer": "C", "explain": "①正確：畫線處「履巉巖，披蒙茸。踞虎豹，登虬龍。攀栖鶻之危巢，俯馮夷之幽宮」三字句兩兩成對、六字句成對，節奏整齊，「茸、龍、宮」又押韻，正好印證「固定的節奏與寬泛的音韻」。②錯誤：「曾日月之幾何，而江山不可復識」說的是時間不久、景物卻已大變，是時間的感慨；乙文「山水細微處不易看出」講的是人在廣大山水中顯得渺小的空間感，兩者不呼應。所以選(C)；(A)(D)認為②對，(B)認為①錯，皆不對。", "skill": "判斷「呼應」要先分清楚：一句講時間、一句講空間，就不能硬配在一起。"}, {"n": 44, "qtype": "單選", "stem": "若從字面的文句意思，將描摹景色的文句稱為「景語」，例如「清風徐來，水波不興」；將抒發情感的文句稱為「情語」，例如「是造物者之無盡藏也，而吾與子之所共適」。下列甲文中的文句，何者屬於「情語」？", "options": {"A": "江流有聲，斷岸千尺", "B": "山高月小，水落石出", "C": "予亦悄然而悲，肅然而恐", "D": "適有孤鶴，橫江東來，翅如車輪"}, "answer": "C", "explain": "(C)正確：「悄然而悲，肅然而恐」直接說出作者的悲傷與恐懼，是情語。(A)錯誤：寫江水聲與高岸，是景語。(B)錯誤：寫山、月、水、石，是景語。(D)錯誤：寫孤鶴飛來的樣子，是景語。", "skill": "字面上出現「悲、恐、喜、愁」等情緒字的，就是情語；只寫看得到聽得到的，是景語。"}], "difficulty": "中", "label": "113二技", "year": 113, "kind": "二技"}, {"id": "et114-05", "exam": "et114", "nums": [5], "form": "單題", "img": "img/et114-05.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "句意理解"], "passage": "甲、縱一葦之所如，凌萬頃之茫然，浩浩乎如馮虛御風\n乙、吾儕細人，朝饔夕飧，觀山而不窮其巔，望海而不極其源\n丙、仲尼獨薦顏淵為好學，然回也屢空，糟糠不厭，而卒蚤夭\n丁、託跡於侍從之臣，月俸不及數萬，爨桂炊玉，晦朔不相續", "translation": "甲、任憑小船漂到哪裡，越過茫茫無邊的江面，浩浩蕩蕩像是凌空駕風而行。乙、我們這些平凡人，早晚吃飯過日子，看山不追究到山頂，望海不追究到源頭。丙、孔子只推薦顏淵好學，但顏回常常貧窮困乏，連粗劣的食物都吃不飽，最後還早早過世。丁、寄身在侍從官的行列，月俸不到幾萬，柴貴如桂、米貴如玉，從月初到月底都接續不上。", "keywords": [{"w": "馮虛御風", "m": "凌空駕風"}, {"w": "朝饔夕飧", "m": "早餐和晚餐，指一般的日常生活"}, {"w": "屢空", "m": "常常貧窮困乏"}, {"w": "糟糠不厭", "m": "連酒渣米糠都吃不飽（厭：同「饜」，吃飽）"}, {"w": "爨桂炊玉", "m": "燒的柴貴如桂木、煮的米貴如玉，形容物價高、生活困苦"}, {"w": "晦朔", "m": "月底與月初"}], "questions": [{"n": 5, "qtype": "單選", "stem": "下列文句「」中的詞語，何者用來形容生活窮困？請選出正確選項。", "options": {"A": "甲乙", "B": "乙丙", "C": "丙丁", "D": "甲丁"}, "answer": "C", "explain": "丙：《史記‧伯夷列傳》說顏回「屢空，糟糠不厭」，連粗糧都吃不飽，形容窮困。丁：「爨桂炊玉」指柴米貴得像桂木和玉，再加上「晦朔不相續」，一個月都撐不過去，也是窮困。甲：蘇軾〈赤壁賦〉「馮虛御風」是凌空乘風的暢快感，和窮困無關。乙：「朝饔夕飧」只是早晚吃飯，指平凡人過日子，沒有說吃不飽。所以丙丁正確，選(C)；(A)(B)(D)都含甲或乙，皆錯。", "skill": "判斷「窮困」要找「吃不飽、錢不夠」的線索，像屢空、不厭、不相續；只寫吃飯本身不算。"}], "difficulty": "中", "label": "114二技", "year": 114, "kind": "二技"}, {"id": "et114-06", "exam": "et114", "nums": [6], "form": "單題", "img": "img/et114-06.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "文化常識"], "passage": "甲、夫天地者，萬物之逆旅\n乙、萬里拋朋侶，三年隔友于\n丙、武陵人誤入桃源，余曩者嘗疑其誕\n丁、人耄耋，皆得以壽終，恩澤廣及草木昆蟲", "translation": "甲、天地是萬物暫住的旅館。乙、遠行萬里拋下朋友，三年和兄弟分隔兩地。丙、武陵人誤入桃花源的事，我從前曾懷疑它是荒誕的。丁、人活到七八十歲，都能壽終正寢，恩惠遍及草木昆蟲。", "keywords": [{"w": "逆旅", "m": "旅館（逆：迎接）"}, {"w": "客舍", "m": "旅館"}, {"w": "友于", "m": "兄弟（典出《尚書》「友于兄弟」）"}, {"w": "考妣", "m": "已故的父母"}, {"w": "曩者", "m": "從前"}, {"w": "耄耋", "m": "七八十歲的老人"}, {"w": "總角", "m": "童年"}], "questions": [{"n": 6, "qtype": "單選", "stem": "下列甲、乙、丙、丁前後「」中的詞語，替換後意義不變的選項是：", "options": {"A": "甲乙", "B": "丙丁", "C": "甲丙", "D": "乙丁"}, "answer": "C", "explain": "甲（李白〈春夜宴從弟桃花園序〉）：「逆旅」就是旅館，換成「客舍」意思不變。丙：「曩者」是從前，換成「往昔」意思不變。乙：「友于」指兄弟，「考妣」是已過世的父母，不能換。丁：「耄耋」是七八十歲的老人，「總角」是小孩子綁髮髻的童年，意思相反。所以甲丙正確，選(C)；(A)含乙、(B)含丁、(D)乙丁，皆錯。", "skill": "年齡代稱成組記：總角（童年）、弱冠（二十）、而立（三十）、耄耋（七八十）。"}], "difficulty": "中", "label": "114二技", "year": 114, "kind": "二技"}, {"id": "et114-14", "exam": "et114", "nums": [14], "form": "單題", "img": "img/et114-14.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["字詞解釋", "詩詞賞析"], "passage": "知否，知否？應是綠肥紅瘦。／淚眼問花花不語，亂紅飛過鞦韆去／一騎紅塵妃子笑，無人知是荔枝來／去年今日此門中，人面桃花相映紅／停車坐愛楓林晚，霜葉紅於二月花", "translation": "你知道嗎？應該是綠葉茂盛、紅花凋零了。／含淚問花，花默然不語，零亂的落花飛過鞦韆而去。／一騎快馬揚起飛塵，貴妃笑了，沒人知道是荔枝送來了。／去年今天在這扇門裡，姑娘的臉和桃花互相映照，一片紅豔。／停下車來是因為喜愛傍晚的楓林，經霜的楓葉比二月的花還紅。", "keywords": [{"w": "紅", "m": "代指花（借代）"}, {"w": "紅塵", "m": "飛揚的塵土"}, {"w": "坐", "m": "因為"}], "questions": [{"n": 14, "qtype": "單選", "stem": "李清照〈如夢令〉：「知否，知否？應是綠肥『紅』瘦。」句中的「紅」本為紅色，在此代指「花」。下列文句中「紅」字的用法，何者與此相同？", "options": {"A": "淚眼問花花不語，亂「紅」飛過鞦韆去", "B": "一騎「紅」塵妃子笑，無人知是荔枝來", "C": "去年今日此門中，人面桃花相映「紅」", "D": "停車坐愛楓林晚，霜葉「紅」於二月花"}, "answer": "A", "explain": "(A)正確：歐陽脩〈蝶戀花〉「亂紅」是零亂的落花，「紅」借代花，和「綠肥紅瘦」相同。(B)錯誤：杜牧〈過華清宮〉「紅塵」指飛揚的塵土，不是花。(C)錯誤：崔護〈題都城南莊〉「相映紅」是形容臉和桃花映照出的紅色，是顏色本身。(D)錯誤：杜牧〈山行〉「紅於二月花」的紅是形容詞「比……還紅」，也是顏色。", "skill": "顏色字能被「名詞」替換（紅→花、綠→葉）就是借代；還是在講顏色就不是。"}], "difficulty": "易", "label": "114二技", "year": 114, "kind": "二技"}, {"id": "et114-15", "exam": "et114", "nums": [15], "form": "單題", "img": "img/et114-15.png", "source": "古典小說常識（《聊齋志異》、《西遊記》、《紅樓夢》、《三國演義》）", "author": "", "genre": "其他", "types": ["文化常識", "典故出處"], "passage": "", "translation": "", "keywords": [{"w": "章回小說", "m": "分回標目的長篇白話小說，如《三國演義》、《紅樓夢》"}, {"w": "四大奇書", "m": "《三國演義》、《水滸傳》、《西遊記》、《金瓶梅》"}], "questions": [{"n": 15, "qtype": "單選", "stem": "同學利用課堂分享自己的文學閱讀心得，請判斷以下哪幾位同學的敘述正確？同學甲：「《聊齋志異》是我最喜歡的一部章回小說，尤其書裡『勞山道士』和『范進中舉』這兩則故事，總吸引我一讀再讀。」同學乙：「《西遊記》作者為唐代吳承恩，是中國古典小說四大奇書之一。講述唐僧、孫悟空、豬八戒及沙僧等前往日本取經的歷程，全書充滿奇思異想，豐富讀者的想像力。」同學丙：「《紅樓夢》裡『劉姥姥進大觀園』的情節相當生動有趣，但最重要的意義，是藉由劉姥姥的見聞和感受，呈現賈府的富貴奢華，就像一面鏡子，映照出貧富懸殊的不同世界。」同學丁：「《三國演義》敘述魏、蜀、吳三國之間的歷史故事，其中『宴桃園豪傑三結義』是有關劉備、關羽、張飛三人結為兄弟的事蹟，已成為忠義精神的代表。」", "options": {"A": "甲乙", "B": "乙丙", "C": "丙丁", "D": "甲丁"}, "answer": "C", "explain": "丙正確：劉姥姥是鄉下窮老太太，透過她的眼睛看大觀園，正好對照出賈府的奢華。丁正確：桃園三結義是劉關張結拜，象徵忠義。甲錯誤：《聊齋志異》是清代蒲松齡的文言短篇小說集，不是章回小說；〈范進中舉〉出自吳敬梓《儒林外史》。乙錯誤：吳承恩是明代人，唐僧師徒是去西天（天竺，今印度）取經，不是日本。所以選(C)；(A)(B)(D)都含甲或乙，皆錯。", "skill": "小說常識記三件事：作者朝代、文言或白話（短篇或章回）、代表篇章出自哪本書。"}], "difficulty": "易", "label": "114二技", "year": 114, "kind": "二技"}, {"id": "et114-18", "exam": "et114", "nums": [18], "form": "單題", "img": "img/et114-18.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析"], "passage": "白毛浮綠水，紅掌撥清波／竹批雙耳峻，風入四蹄輕／大能吞巨象，長可遶崑崙／群行深谷間，百獸望風低", "translation": "白色羽毛浮在綠水上，紅色腳掌撥動清波。／耳朵像斜削的竹筒一樣尖挺，奔跑時四蹄像乘風般輕快。／大到能吞下巨象，長到能繞崑崙山一圈。／成群行走在深谷中，百獸遠遠看到就低頭畏服。", "keywords": [{"w": "竹批", "m": "像斜削的竹筒"}, {"w": "峻", "m": "高挺"}, {"w": "望風", "m": "遠遠看到氣勢"}], "questions": [{"n": 18, "qtype": "單選", "stem": "下列詩句皆是描述動物，何者配對正確？", "options": {"A": "白毛浮綠水，紅掌撥清波：貓", "B": "竹批雙耳峻，風入四蹄輕：馬", "C": "大能吞巨象，長可遶崑崙：鯨", "D": "群行深谷間，百獸望風低：狼"}, "answer": "B", "explain": "(B)正確：杜甫〈房兵曹胡馬〉，「雙耳峻」寫馬耳尖挺，「四蹄輕」寫奔跑輕快，是馬。(A)錯誤：駱賓王〈詠鵝〉，白毛、紅掌、在水上划水，是鵝不是貓。(C)錯誤：「吞巨象」用「巴蛇吞象」的典故，「長可遶崑崙」誇張身體極長，寫的是蛇，不是鯨。(D)錯誤：「百獸望風低」是百獸都低頭畏服的王者氣勢，不是狼的形象。", "skill": "詠物詩抓「外形特徵＋典故」：四蹄是走獸、紅掌撥波是水禽、吞象是蛇。"}], "difficulty": "易", "label": "114二技", "year": 114, "kind": "二技"}, {"id": "et114-19", "exam": "et114", "nums": [19, 20], "form": "題組", "img": "img/et114-19.png", "source": "喜帖、信封、賀幛（應用文）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "謹詹於中華民國一一四年國曆四月廿六日（農曆三月廿九日）星期六為長男玄米、次女薏仁舉行結婚典禮，敬治菲酌，恭請闔第光臨。陳蓬萊、劉私、孫青稞、吳燕麥鞠躬。", "translation": "謹定於民國114年4月26日（農曆3月29日）星期六，為長子玄米、次女薏仁舉行婚禮，備辦簡單酒席，恭請全家光臨。（雙方主婚人）陳蓬萊、劉私、孫青稞、吳燕麥敬邀。", "keywords": [{"w": "謹詹", "m": "謹慎選定（日期）"}, {"w": "敬治菲酌", "m": "恭敬備辦簡單的酒席（宴客謙詞）"}, {"w": "敬備湯餅", "m": "小孩彌月請客的用語"}, {"w": "闔第光臨", "m": "全家光臨"}, {"w": "緘", "m": "封口，信封上寄件人名後用"}, {"w": "台啟", "m": "請對方拆信，用於平輩"}, {"w": "秦晉之好", "m": "兩家聯姻，結婚賀辭"}], "questions": [{"n": 19, "qtype": "單選", "stem": "王綠豆接獲好友小孩結婚的喜帖，她準備了禮金欣然赴宴。依據甲、乙、丙的資訊，有關Ⅰ、Ⅱ、Ⅲ的研判，下列選項，何者正確？Ⅰ、甲的「敬治菲酌」也可改為「敬備湯餅」 Ⅱ、丙的「玉勝之喜」應該改為「秦晉之好」 Ⅲ、從甲、乙可推論，王綠豆應為男方親友", "options": {"A": "Ⅰ、Ⅱ正確，Ⅲ錯誤", "B": "Ⅰ正確，Ⅱ、Ⅲ錯誤", "C": "Ⅰ無法判斷，Ⅱ錯誤，Ⅲ正確", "D": "Ⅰ錯誤，Ⅱ正確，Ⅲ無法判斷"}, "answer": "D", "explain": "Ⅰ錯誤：「敬備湯餅」是小孩滿月請客的用語，不能用在喜宴，「敬治菲酌」才是一般宴客謙詞。Ⅱ正確：丙是送新人的禮金封，應寫結婚賀辭，「秦晉之好」指兩家聯姻，適合；「玉勝之喜」不是結婚賀辭。Ⅲ無法判斷：喜帖由男女雙方家長（陳蓬萊、劉私與孫青稞、吳燕麥）共同具名，信封也同時列了陳、孫兩家地址，看不出王綠豆是哪一方的朋友。所以選(D)。", "skill": "喜慶用語分場合：宴客「敬治菲酌」、彌月「敬備湯餅」、結婚「秦晉之好、百年好合」。"}, {"n": 20, "qtype": "單選", "stem": "乙為喜帖信封，①、②、③依序應填入：", "options": {"A": "緘／緘／台啟", "B": "啟／啟／敬啟", "C": "寄／寄／敬收", "D": "封／封／安啟"}, "answer": "A", "explain": "(A)正確：寄件人姓氏後寫「緘」（表示封好寄出），收件人是平輩的王綠豆小姐，用「台啟」請她拆閱。(B)錯誤：「啟」是請對方拆信，不能放在寄件人後面；「敬啟」也不是信封啟封詞的慣用語。(C)錯誤：「寄」雖可用於寄件人，但「敬收」不是信封的啟封詞。(D)錯誤：寄件人後不用「封」；「安啟」用於父母、祖父母等長輩，不適合平輩朋友。", "skill": "信封三件事：寄件人寫「緘」、平輩收件寫「台啟」、長輩寫「安啟／鈞啟」。"}], "difficulty": "中", "label": "114二技", "year": 114, "kind": "二技"}, {"id": "et114-23", "exam": "et114", "nums": [23, 24], "form": "題組", "img": "img/et114-23.png", "source": "蔣一葵《堯山堂外紀》", "author": "蔣一葵", "genre": "筆記小品", "types": ["文意推論", "寫作手法"], "passage": "文皇帝嘗謂解學士曰：「有一書句甚難其對，曰『色難』。」解應聲曰：「容易。」文皇不悟，顧謂解曰：「既云易矣，何久不屬對？」解曰：「適已對矣。」文皇始悟，為之大笑。", "translation": "明成祖曾對解縉學士說：「書上有一句話很難對下聯，叫做『色難』。」解縉隨口回答：「容易。」成祖沒聽懂，回頭對他說：「既然說容易，為什麼這麼久還不對出來？」解縉說：「剛才已經對好了。」成祖這才明白，因此大笑。", "keywords": [{"w": "文皇帝", "m": "明成祖（諡號文皇帝）"}, {"w": "解學士", "m": "解縉"}, {"w": "色難", "m": "出自《論語》，侍奉父母保持和顏悅色最難"}, {"w": "屬對", "m": "對對子"}, {"w": "適", "m": "剛才"}], "questions": [{"n": 23, "qtype": "單選", "stem": "依據上文，判斷文皇帝「始悟，為之大笑」的原因為何？", "options": {"A": "佩服解學士的雅量", "B": "發現解學士的破綻", "C": "領會解學士的巧答", "D": "嘲笑解學士的無知"}, "answer": "C", "explain": "(C)正確：解縉說的「容易」，表面是「這很簡單」，其實就是下聯：「容」對「色」（都指臉色），「易」對「難」。皇帝起初以為他只是在說很簡單，聽到「適已對矣」才明白這是雙關巧答，所以大笑。(A)錯誤：故事沒有涉及雅量、包容。(B)錯誤：解縉沒有破綻，是皇帝自己一時沒聽懂。(D)錯誤：無知的不是解縉，皇帝是欣賞而笑。", "skill": "「始悟」類題目，找出前面「不悟」的地方，那就是巧妙的關鍵。"}, {"n": 24, "qtype": "單選", "stem": "依據上文，解學士用「容易」作為「色難」的對句，下列畫線處的修辭方法，何者與此最相近？", "options": {"A": "飄飄何所似，天地一沙鷗（畫線：何所似、一沙鷗）", "B": "白髮三千丈，離愁似箇長（畫線：白髮、離愁）", "C": "孤帆遠影碧空盡，惟見長江天際流（畫線：孤帆遠影、惟見長江天際流）", "D": "春蠶到死絲方盡，蠟炬成灰淚始乾（畫線：絲方盡、淚始乾）"}, "answer": "D", "explain": "(D)正確：李商隱〈無題〉「絲」字面是蠶絲，又諧音「思」（相思）；「淚」字面是蠟燭的蠟油，又指人的眼淚，一詞兩義，和「容易」字面是簡單、實際是對句一樣，都是雙關。(A)錯誤：杜甫〈旅夜書懷〉用設問帶出譬喻，把自己比成沙鷗。(B)錯誤：李白〈秋浦歌〉用極度誇張說愁之深，是誇飾。(C)錯誤：李白〈黃鶴樓送孟浩然之廣陵〉寫望著帆影消失、只剩江水，是摹寫景物、寓情於景，沒有雙關。", "skill": "雙關的判斷：同一個字詞能同時讀出「字面義」和「暗藏義」兩層意思。"}], "difficulty": "中", "label": "114二技", "year": 114, "kind": "二技"}, {"id": "et114-25", "exam": "et114", "nums": [25, 26], "form": "題組", "img": "img/et114-25.png", "source": "王晫《今世說》", "author": "王晫", "genre": "筆記小品", "types": ["人物情感", "寫作手法"], "passage": "趙洞門為御史大夫，車馬輻輳，望塵者接踵於道。及罷歸，出國門，送者才三數人。尋召還，前去者復來如初。時吳園次獨落落然，不以欣戚改觀。趙每目送之，顧謂子友沂曰：「他日吾百年後，終當賴此人力。」未幾，友沂早世，趙亦以痛子歿於客邸。兩孫孤立，園次哀而振之。撫其幼者如子，字以愛女。", "translation": "趙洞門當御史大夫時，門前車馬聚集，追隨巴結的人在路上一個接一個。等到他被罷官回鄉，出京城時，來送行的只有三兩個人。不久他又被召回朝廷，先前離開的人又像當初一樣來了。當時只有吳園次始終淡然，不因趙家得意或失意而改變態度。趙洞門常常目送他，回頭對兒子友沂說：「將來我死後，終究要靠這個人幫忙。」不久友沂早逝，趙洞門也因傷痛兒子死在旅舍。兩個孫子孤苦無依，吳園次憐憫並救濟他們，撫養年幼的孫子如同自己的兒子，還把心愛的女兒許配給他。", "keywords": [{"w": "輻輳", "m": "像車輻集中於車轂，比喻人群聚集"}, {"w": "望塵者", "m": "望著車塵下拜的人，指巴結權貴者"}, {"w": "尋", "m": "不久"}, {"w": "落落然", "m": "淡然、不隨俗的樣子"}, {"w": "欣戚", "m": "得意與失意"}, {"w": "振", "m": "同「賑」，救濟"}, {"w": "字", "m": "女子許嫁"}], "questions": [{"n": 25, "qtype": "單選", "stem": "下列選項，何者最能描述吳園次的行為舉止？", "options": {"A": "錦上不添花，雪中能送炭", "B": "謀定而後動，知止而有得", "C": "為人強記覽，過眼不再讀", "D": "明知山有虎，偏向虎山行"}, "answer": "A", "explain": "(A)正確：趙家得勢時，吳園次不跟著巴結（錦上不添花）；趙家父子過世、孫子孤立時，他出手救濟、撫養並許嫁女兒（雪中送炭）。(B)錯誤：重點不是深思熟慮再行動。(C)錯誤：文中和記憶力、讀書無關。(D)錯誤：他照顧遺孤不是冒險犯難。", "skill": "人物品格題，把人物在「順境」和「逆境」的表現分開看，再找能同時概括兩者的選項。"}, {"n": 26, "qtype": "單選", "stem": "下列關於上文寫作手法的敘述，何者正確？", "options": {"A": "以插敘法說明趙洞門為官始末", "B": "以對比法凸顯吳園次異於他人", "C": "以對話方式說明趙吳兩家起落", "D": "以託物言志達到借古諷今目的"}, "answer": "B", "explain": "(B)正確：先寫一般人隨趙洞門得勢失勢而來去（望塵者接踵、送者三數人、前去者復來），再寫吳園次「獨落落然」，用眾人的勢利對比他的始終如一。(A)錯誤：文章依時間順敘，沒有插敘，也不是在交代趙的官場經歷。(C)錯誤：全文只有趙對兒子說的一句話，不是靠對話推動。(D)錯誤：文中沒有借物寄託志向。", "skill": "看到「獨」字，常是對比法的訊號：前面寫眾人，後面寫一個不一樣的人。"}], "difficulty": "易", "label": "114二技", "year": 114, "kind": "二技"}, {"id": "et114-27", "exam": "et114", "nums": [27, 28, 29], "form": "題組", "img": "img/et114-27.png", "source": "段成式《酉陽雜俎》（改寫）", "author": "段成式", "genre": "筆記小品", "types": ["句意理解", "字詞解釋", "寫作手法"], "passage": "吳洞妻卒，有女名葉限。父卒，為後母所苦，常令樵險汲深。嘗得一鱗，赬鰭金目，遂潛養於盆水，後大不能受，乃投池中。所得餘食，輒沉以食之。至池，魚必露。他人至，不復出。其母每伺之，魚未嘗見也。因詐女曰：「吾為爾新其襦。」乃易其敝衣，令汲於他泉。母衣其女衣，袖利刃，行向池呼魚，魚即出首，因斫殺之。味倍常魚，藏其骨於鬱棲之下。逾日，女至向池，不復見魚矣，乃哭於野。忽有人自天而降，慰女曰：「爾無哭，爾母殺爾魚矣！骨在糞下。爾歸取魚骨藏於室，所須第祈之，當隨爾。」女用其言，金衣玉食，隨欲而具。及節，母令女守庭果。女伺母行遠，亦往，衣翠紡上衣，躡金履。母所生女曰：「此甚似姊。」母亦疑之。女覺，遽反，遂遺一履，為洞人所得。母歸，但見女抱庭樹眠。洞人貨其履於陀汗國。國主得之，乃令一國婦人履之，竟無稱者。乃以履遍歷人家，若有女履者，捕之以告。得葉限，令履之而信。葉限躡履而進，色若天人。始具事於王，載魚骨與葉限還國，以為上婦。", "translation": "吳洞的妻子過世，留下一個女兒叫葉限。後來父親也死了，她被後母虐待，常被派去險峻的地方砍柴、深的地方打水。她曾撈到一條魚，紅色的鰭、金色的眼睛，就偷偷養在盆裡；後來魚長大，盆子容納不下，就把牠放進池中。她把吃剩的食物都沉到水裡餵牠。她一到池邊，魚就一定浮出來；別人來了，魚就不出來。後母常常偷看，魚從不現身。後母就騙葉限說：「我替你做件新短衣。」於是換下她的破衣服，叫她到別的泉水去打水。後母穿上葉限的衣服，袖裡藏著利刀，走到池邊呼喚魚，魚一探頭，就把牠砍死了。魚肉的美味勝過普通魚好幾倍，後母把魚骨藏在糞堆底下。過了一天，葉限到池邊，再也看不到魚，就在野外哭泣。忽然有人從天而降，安慰她說：「你別哭，是你後母殺了你的魚！骨頭在糞堆下。你回去把魚骨拿來藏在屋裡，需要什麼只管向它祈求，都會如你所願。」葉限照做，金衣美食，想要什麼就有什麼。到了節日，後母要她看守庭院的果樹。葉限等後母走遠，也去參加，穿著翠鳥羽毛織成的上衣，腳穿金鞋。後母親生的女兒說：「這人很像姊姊。」後母也起了疑心。葉限察覺，急忙回家，掉了一隻鞋，被洞中的人撿到。後母回來，只看到葉限抱著庭樹睡覺。洞人把鞋賣到陀汗國。國王得到鞋，命令全國婦女試穿，竟沒有一個人合腳。於是派人拿著鞋挨家挨戶找，有能穿上的女子，就抓來報告。找到葉限，讓她試穿，果然合腳。葉限穿著鞋走出來，容貌像天仙一般。她這才把事情原委告訴國王，國王載著魚骨和葉限回國，立她為正妻。", "keywords": [{"w": "赬", "m": "紅色"}, {"w": "受", "m": "容納"}, {"w": "伺", "m": "暗中觀察"}, {"w": "襦", "m": "短衣"}, {"w": "斫", "m": "砍"}, {"w": "鬱棲", "m": "糞堆"}, {"w": "第", "m": "只管、但"}, {"w": "遽反", "m": "急忙返回"}, {"w": "貨", "m": "賣"}, {"w": "上婦", "m": "正妻"}], "questions": [{"n": 27, "qtype": "單選", "stem": "上文畫底線處的文句均省略了主詞，判斷下列選項在括弧中所補上的主詞，何者正確？", "options": {"A": "(葉限)後大不能受", "B": "(母)令汲於他泉", "C": "(魚)所須第祈之", "D": "(洞人)乃以履遍歷人家"}, "answer": "B", "explain": "(B)正確：後母騙葉限換下破衣，接著「令汲於他泉」，下命令的人是後母，好支開葉限去殺魚。(A)錯誤：長大到盆子裝不下的是魚，不是葉限。(C)錯誤：「所須第祈之」是神人對葉限說「你需要什麼只管向它（魚骨）祈求」，祈求的人是葉限，魚骨是被祈求的對象。(D)錯誤：拿鞋挨家挨戶找人的是陀汗國國王（派人），洞人只是把鞋賣掉的人。", "skill": "補主詞時，把前一句的主詞帶進來試讀，讀不通就換成上下文中另一個人物。"}, {"n": 28, "qtype": "單選", "stem": "下列選項「」中的詞義，前後相同的選項是：", "options": {"A": "母衣其女「衣」／男女「衣」著，悉如外人", "B": "所須「第」祈之／往來桐城，必躬造左公「第」", "C": "金衣玉食，隨欲而「具」／良乃入，「具」告沛公", "D": "女覺，遽「反」／今其智乃「反」不能及，其可怪也歟"}, "answer": "A", "explain": "(A)正確：「母衣其女衣」第二個衣是名詞「衣服」；〈桃花源記〉「男女衣著」的衣也是衣服、穿戴的衣物，兩者相同。(B)錯誤：前者「第」是副詞「只管」；〈左忠毅公軼事〉「左公第」是名詞「宅第」。(C)錯誤：前者「具」是「齊備」；〈鴻門宴〉「具告」是「詳細地」。(D)錯誤：前者「反」同「返」，返回；〈師說〉「反不能及」是「反而」。", "skill": "「衣其女衣」這種同字連用，第一個常是動詞（穿），第二個是名詞（衣服）。"}, {"n": 29, "qtype": "單選", "stem": "故事的寫作手法中，常見預設安排的伏筆，以帶出下文情節並加以呼應。下列選項，何者的對應正確？", "options": {"A": "伏筆：魚「他人至，不復出」／呼應的情節：後母「衣其女衣」", "B": "伏筆：後母「藏其骨於鬱棲之下」／呼應的情節：令葉限「守庭果」", "C": "伏筆：魚「赬鰭金目」／呼應的情節：洞人「貨其履」", "D": "伏筆：後母為葉限「新其襦」／呼應的情節：葉限「衣翠紡上衣」"}, "answer": "A", "explain": "(A)正確：前面先交代魚只認葉限、別人來就不出來，所以後母才要穿上葉限的衣服假扮她去騙魚，前後呼應。(B)錯誤：魚骨藏在糞下，呼應的是神人說「骨在糞下」、葉限取骨祈願，和守庭果無關。(C)錯誤：魚的紅鰭金眼寫牠不凡，和洞人賣鞋沒有關係。(D)錯誤：「新其襦」是後母騙人換衣的藉口；翠紡上衣是魚骨賜予的，兩者沒有因果呼應。", "skill": "伏筆題問「後面那件事為什麼會發生」，回頭找前文提供理由的那一句。"}], "difficulty": "中", "label": "114二技", "year": 114, "kind": "二技"}, {"id": "et114-30", "exam": "et114", "nums": [30, 31, 32], "form": "題組", "img": "img/et114-30.png", "source": "《史記‧孟嘗君列傳》；王安石〈讀孟嘗君列傳〉", "author": "司馬遷、王安石", "genre": "史傳人物", "types": ["文意推論", "比較閱讀", "主旨寓意"], "passage": "【甲】孟嘗君在薛，招致諸侯賓客及亡人有罪者，皆歸孟嘗君。孟嘗君舍業厚遇之，以故傾天下之士。食客數千人，無貴賤一與文等。……士以此多歸孟嘗君。孟嘗君客無所擇，皆善遇之。……（秦昭王）囚孟嘗君，謀欲殺之。孟嘗君使人抵昭王幸姬求解。幸姬曰：「妾願得君狐白裘。」此時孟嘗君有一狐白裘，直千金，天下無雙，入秦獻之昭王，更無他裘。孟嘗君患之，徧問客，莫能對。最下坐有能為狗盜者，曰：「臣能得狐白裘。」乃夜為狗，以入秦宮臧中，取所獻狐白裘至，以獻秦王幸姬。幸姬為言昭王，昭王釋孟嘗君。孟嘗君得出，即馳去，更封傳，變名姓以出關。夜半至函谷關。秦昭王後悔出孟嘗君，求之已去，即使人馳傳逐之。孟嘗君至關，關法雞鳴而出客，孟嘗君恐追至，客之居下坐者有能為雞鳴，而雞齊鳴，遂發傳出。出如食頃，秦追果至關，已後孟嘗君出，乃還。始孟嘗君列此二人於賓客，賓客盡羞之，及孟嘗君有秦難，卒此二人拔之。自是之後，客皆服。\n【乙】世皆稱孟嘗君能得士，士以故歸之，而卒賴其力以脫於虎豹之秦。嗟乎！孟嘗君特雞鳴狗盜之雄耳，豈足以言得士？不然，擅齊之強，得一士焉，宜可以南面而制秦，尚何取雞鳴狗盜之力哉？夫雞鳴狗盜之出其門，此士之所以不至也。", "translation": "【甲】孟嘗君在薛地，招攬各國賓客和犯罪逃亡的人，這些人都來投靠他。孟嘗君捨棄家業優厚地款待他們，因此天下的士人都傾心歸附。食客有幾千人，不論貴賤，待遇都和自己（田文）一樣。……士人因此大多歸附孟嘗君。孟嘗君收門客不加挑選，一律好好對待。……秦昭王囚禁孟嘗君，打算殺他。孟嘗君派人找昭王寵愛的妃子求救。妃子說：「我想要您的白狐皮裘。」當時孟嘗君只有一件白狐皮裘，價值千金，天下無雙，入秦時已獻給昭王，再沒有別的了。孟嘗君很煩惱，問遍門客，沒人能回答。坐在最末座、會像狗一樣偷東西的門客說：「我能拿到白狐皮裘。」就趁夜裝成狗，潛入秦宮倉庫，把獻出的白狐皮裘偷出來，獻給昭王的寵妃。寵妃替孟嘗君向昭王說情，昭王就放了孟嘗君。孟嘗君一出來就快馬離開，更換通行證，改名換姓出關。半夜到了函谷關。秦昭王後悔放走孟嘗君，派人找他時他已離開，立刻派人乘驛車追趕。孟嘗君到了關口，按關法要雞叫才放行旅客，孟嘗君怕追兵趕到，末座的門客中有人會學雞叫，他一叫，附近的雞都跟著叫，於是驗過通行證出關。出關大約一頓飯的時間，秦國追兵果然到了關口，已經落在孟嘗君之後，只好回去。當初孟嘗君把這兩人列入賓客時，其他賓客都覺得羞恥，等到孟嘗君在秦國遭難，最後竟是靠這兩人解救。從此以後，門客都佩服了。\n【乙】世人都稱讚孟嘗君能得到賢士，賢士因此歸附他，最後還靠他們的力量從虎豹般的秦國脫身。唉！孟嘗君只不過是雞鳴狗盜之徒的首領罷了，哪裡稱得上得到賢士？如果不是這樣，憑著齊國的強大，只要得到一位真正的賢士，就應該可以稱王制服秦國，又何必靠雞鳴狗盜的力量呢？雞鳴狗盜之徒出入他的門下，這正是真正賢士不肯來的原因。", "keywords": [{"w": "舍業", "m": "捨棄家業"}, {"w": "文", "m": "孟嘗君名田文"}, {"w": "幸姬", "m": "受寵的妃子"}, {"w": "直", "m": "同「值」"}, {"w": "臧", "m": "同「藏」，倉庫"}, {"w": "封傳", "m": "通行證"}, {"w": "特", "m": "只是"}, {"w": "擅", "m": "擁有、憑藉"}, {"w": "南面", "m": "稱王"}], "questions": [{"n": 30, "qtype": "單選", "stem": "下列關於甲文文意的敘述，何者正確？", "options": {"A": "秦昭王以狗盜者困住孟嘗君", "B": "孟嘗君對昭王幸姬無禮而逃", "C": "孟嘗君對待食客皆一視同仁", "D": "秦昭王以狐白裘贈予孟嘗君"}, "answer": "C", "explain": "(C)正確：「無貴賤一與文等」、「客無所擇，皆善遇之」，孟嘗君對所有食客一視同仁。(A)錯誤：狗盜者是孟嘗君的門客，是幫他脫困的人。(B)錯誤：孟嘗君是請幸姬幫忙說情，沒有對她無禮。(D)錯誤：狐白裘是孟嘗君獻給昭王的，不是昭王送他的。", "skill": "史傳敘事題，留意「誰給誰」「誰幫誰」的方向，選項最愛把主客對調。"}, {"n": 31, "qtype": "單選", "stem": "下列關於乙文觀點的說明，何者正確？", "options": {"A": "讚賞孟嘗君能成為雞鳴狗盜之徒的領袖", "B": "佩服孟嘗君獨具有招攬天下賢士的眼光", "C": "主張以齊之強才能讓孟嘗君從秦國脫困", "D": "認為能助君主稱霸方為孟嘗君應求之士"}, "answer": "D", "explain": "(D)正確：王安石說憑齊國之強「得一士焉，宜可以南面而制秦」，他心目中的「士」是能幫國君稱霸、制服秦國的人才。(A)錯誤：「雞鳴狗盜之雄」是諷刺，不是讚賞。(B)錯誤：王安石正是反對「孟嘗君能得士」的說法。(C)錯誤：他是說有齊國之強再加上真正的賢士就能制秦，而不是說靠齊國強大才能脫困。", "skill": "翻案文章先找作者反駁的那句「世皆稱……」，作者的觀點就是它的反面。"}, {"n": 32, "qtype": "單選", "stem": "下列關於甲、乙二文的比較，何者正確？", "options": {"A": "甲、乙二文都藉由前人言論以評價孟嘗君的能力", "B": "甲、乙二文都用比較類推的手法印證孟嘗君聲望", "C": "甲文肯定孟嘗君的人品，乙文則稱頌孟嘗君的謀略", "D": "甲文記載孟嘗君能得士，乙文認為孟嘗君所得非士"}, "answer": "D", "explain": "(D)正確：甲文記孟嘗君廣納賓客，最後靠雞鳴狗盜脫險，「客皆服」，呈現他能得士；乙文說他只是「雞鳴狗盜之雄」，所得的不是真正的士。(A)錯誤：甲文是史傳敘事，沒有引前人言論評價。(B)錯誤：兩文都不是用比較類推來印證聲望，乙文更是在否定他的名聲。(C)錯誤：甲文著重他待客與脫險過程，不是肯定人品；乙文是批評，不是稱頌。", "skill": "雙文本比較，先各用一句話寫出「甲說什麼、乙說什麼」，再看選項是否兩邊都對。"}], "difficulty": "易", "label": "114二技", "year": 114, "kind": "二技"}, {"id": "et114-33", "exam": "et114", "nums": [33, 34, 35], "form": "題組", "img": "img/et114-33.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文意推論"], "passage": "草木有本心，何求美人折／歲老根彌壯，陽驕葉更陰／樹樹皆秋色，山山惟落暉／古木無人徑，深山何處鐘", "translation": "草木自有它的本性，何必求美人來攀折；樹越老根越粗壯，太陽越猛烈葉子越濃密成蔭；每棵樹都染上秋色，每座山只剩落日餘暉；古木參天，沒有人走的小路，深山裡哪裡傳來鐘聲。", "keywords": [{"w": "彌", "m": "更加"}, {"w": "陽驕", "m": "陽光猛烈"}, {"w": "陰", "m": "樹蔭濃密"}, {"w": "落暉", "m": "落日餘暉"}], "questions": [{"n": 33, "qtype": "單選", "stem": "依據上文，判斷「每隔兩、三年，這老橡樹開花結果，長出橡實」這一文句加在文中(甲)、(乙)、(丙)、(丁)何處最為適當？", "options": {"A": "甲", "B": "乙", "C": "丙", "D": "丁"}, "answer": "A", "explain": "(A)正確：(甲)前面寫「這棵老橡樹」的樣子，後面接「部落裡的小孩會去撿樹下發芽的橡實」，要先有老橡樹結出橡實，小孩才撿得到，句子放這裡最順。(B)錯誤：(乙)後面講的是「海岸常青橡樹」七八個月結果，和「這老橡樹」每兩三年結果不同，放這裡會互相矛盾。(C)錯誤：(丙)前後講南加州橡樹種類和橡樹融入美國生活，和結果無關。(D)錯誤：(丁)前後在寫山徑兩旁的橡樹林景色，與結果無關。", "skill": "句子插入題，找句中的指示詞（「這」老橡樹）和下文的承接詞（橡實），前後都接得上的位置就對。"}, {"n": 34, "qtype": "單選", "stem": "依文意推斷文末畫底線處缺空的詩句，最適合填入下列何者？", "options": {"A": "草木有本心，何求美人折", "B": "歲老根彌壯，陽驕葉更陰", "C": "樹樹皆秋色，山山惟落暉", "D": "古木無人徑，深山何處鐘"}, "answer": "B", "explain": "(B)正確：前文寫老橡樹「樹根深入土裡」、「在炎炎烈日下，開車經過，擋掉熱浪，頓覺清涼」，「歲老根彌壯」對應老樹根深，「陽驕葉更陰」對應烈日下枝葉濃蔭，最貼切。(A)錯誤：張九齡〈感遇〉講草木本性不求人賞識，是託物言志，和遮陽清涼無關。(C)錯誤：王績〈野望〉寫秋天黃昏，但文中常青橡樹在炎夏，季節不合。(D)錯誤：王維〈過香積寺〉寫深山古寺的幽靜，和開車經過樹廊的清涼不合。", "skill": "詩句填空，先圈出空格前的關鍵情境（老樹、根深、烈日、清涼），再找每個字都對得上的詩句。"}, {"n": 35, "qtype": "單選", "stem": "關於上文內容所提及橡樹的資訊，包括下列何者？請選出正確選項。①起源歷史 ②花果型態 ③全球分布 ④品種分類 ⑤生長特性", "options": {"A": "①、②", "B": "③、④", "C": "①、③、⑤", "D": "②、④、⑤"}, "answer": "D", "explain": "②有：雄花黃中帶綠、雌花綠中帶紅，橡實是圓錐體、有小帽子。④有：南加州橡樹分山谷橡樹（落葉）和常青橡樹。⑤有：雌雄同株、靠風傳粉、開花後七八個月結果、根深抓地。①沒有：文中說橡樹融入美國人的生活，但沒有講橡樹的起源。③沒有：只提到南加州，沒有說明全球分布。所以選(D)；(A)(C)含①、(B)含③，皆錯。", "skill": "「文中包括哪些資訊」題，每一項都要能在文中指出具體句子，指不出來就刪。"}], "difficulty": "中", "label": "114二技", "year": 114, "kind": "二技"}, {"id": "et114-36", "exam": "et114", "nums": [36, 37, 38], "form": "題組", "img": "img/et114-36.png", "source": "陶望齡〈養蘭說〉", "author": "陶望齡", "genre": "說理議論", "types": ["文意推論", "主旨寓意", "寫作手法"], "passage": "會稽多蘭，而閩產者貴。養之之法，喜潤而忌溼，喜燥而畏日，喜風而避寒，如富家嬌小兒女，特多態難奉。予舊嘗聞之，曰他花皆嗜穢而溉，閩蘭獨用茗汁，以爲草樹清香者無如蘭味，清者無如茗氣，類相合宜也。\n休園中有蘭二盆，溉之如法，然葉日短，色日瘁，無何其一槁矣。而他家所植者，茂而多花。予就問故，且告以聞。客嘆曰：「誤哉，子之術也。夫以甘食人者，百穀也；以芳悅人者，百卉也。其所謂甘與芳，子識之乎？臭腐之極，復爲神奇，物皆然矣。昔人有捕得龜者，曰龜之靈，不食也。篋藏之，旬而啓之，龜已饑死。由此言之，凡謂物之有不食者，與草木之有不嗜穢者，皆妄也。子固而溺所聞，子之蘭槁亦後矣。」\n予既歸，不懌，猶謂聞之不妄，術之不謬。既而疑曰：物固有久而易其嗜，喪其故，密化而不可知者。《離騷》曰：「蘭芷變而不芳兮，荃蕙化而爲茅。」夫其脆弱驕蹇，炫芳以自貴，余固以憂其難養，而不虞其易變也。嗟夫！於是使童子剔槁沃枯，運糞而漬之，遂盛。", "translation": "會稽盛產蘭花，而福建產的最珍貴。養蘭的方法是：喜歡濕潤卻怕太濕，喜歡乾燥卻怕日曬，喜歡通風卻要避寒，像富貴人家嬌生慣養的小兒女，特別難伺候。我以前聽說，別的花都喜歡用糞肥澆灌，只有閩蘭要用茶水，因為草木中最清香的是蘭花，最清雅的是茶氣，同類相配最合適。\n休園裡有兩盆蘭花，我照這方法澆灌，葉子卻一天比一天短，顏色一天比一天憔悴，不久其中一盆枯死了。而別人家種的卻茂盛又多花。我去請教原因，並告訴他我聽來的方法。那位客人嘆道：「你的方法錯了！能用甘美餵養人的是各種穀物，能用芳香取悅人的是各種花卉。它們的甘美和芳香從哪來，你知道嗎？腐臭到了極點，又化為神奇，萬物都是這樣。從前有人捉到一隻烏龜，說烏龜有靈性，不用吃東西，就把牠放在箱子裡，過了十天打開，烏龜已經餓死了。這樣說來，凡是說動物有不吃東西的、草木有不喜歡肥料的，都是胡說。你固執又沉溺於聽來的說法，你的蘭花枯死已經算晚了。」\n我回家後不高興，還認為聽來的說法沒錯、方法也不謬誤。後來又懷疑：事物本來就有時間久了改變嗜好、失去本性，在不知不覺中變化的。《離騷》說：「蘭芷變得不再芳香，荃蕙化成了茅草。」蘭花那麼嬌弱高傲，炫耀芬芳來抬高自己，我本來只擔心它難養，沒料到它也容易變啊。唉！於是叫童僕剪掉枯葉、澆灌乾枯的根，運來糞肥浸潤它，蘭花終於茂盛了。", "keywords": [{"w": "嗜穢", "m": "喜好糞肥"}, {"w": "溉", "m": "澆灌"}, {"w": "茗汁", "m": "茶水"}, {"w": "瘁", "m": "憔悴"}, {"w": "無何", "m": "不久"}, {"w": "槁", "m": "枯死"}, {"w": "篋", "m": "箱子"}, {"w": "溺", "m": "沉迷、拘泥"}, {"w": "懌", "m": "高興"}, {"w": "不虞", "m": "沒料到"}, {"w": "漬", "m": "浸潤"}], "questions": [{"n": 36, "qtype": "單選", "stem": "下列敘述，何者最符合本文文意？", "options": {"A": "閩茶價格高昂，所以能養出有清香的蘭花", "B": "不食靈龜與難養之蘭，說明作者興趣高雅", "C": "客對作者養蘭之法的評論，作者不以為然", "D": "作者將蘭花遷種其他地方，最後終於盛開"}, "answer": "C", "explain": "(C)正確：作者聽完客人的批評，「既歸，不懌，猶謂聞之不妄，術之不謬」，起初並不認同。(A)錯誤：文中說的是閩蘭珍貴，沒提閩茶價格；而且用茶水澆蘭正是失敗的做法。(B)錯誤：靈龜是客人舉的反例，說明萬物都要吃，不是說作者興趣高雅。(D)錯誤：作者沒有移植，而是改用糞肥澆灌，蘭花才茂盛。", "skill": "人物態度轉折題，留意「既歸」「既而」等時間詞，前後態度往往不同。"}, {"n": 37, "qtype": "單選", "stem": "下列①、②是對作者所養蘭花枯萎原因的說明，請選出正確選項。①作者認為照顧不周全，以致蘭花的本性改變。②客人認為作者拘泥所聞，以致養護方式錯誤。", "options": {"A": "①、②皆正確", "B": "①、②皆錯誤", "C": "①正確②錯誤", "D": "①錯誤②正確"}, "answer": "D", "explain": "①錯誤：作者最後的想法是「物固有久而易其嗜」，蘭花是自己隨時間改變了嗜好，不是因為他照顧不周（他明明「溉之如法」）。②正確：客人說「子固而溺所聞」，認為作者固執於聽來的方法，用茶水澆蘭才出錯。所以選(D)。", "skill": "分清「誰認為」：同一件事，作者和客人的解釋常常不同，要回到各自說的話找根據。"}, {"n": 38, "qtype": "單選", "stem": "下列關於本文寫作手法的敘述，何者正確？", "options": {"A": "以「無如蘭味」、「無如茗氣」層層遞進方法表現蘭花特性", "B": "以「不懌」、「不妄」、「不謬」類疊句型強化客人論述力", "C": "客人以「百穀」、「百卉」、「靈龜」暗喻作者的見識廣博", "D": "作者引用「蘭芷變而不芳兮」佐證自身對養蘭觀念有所改變"}, "answer": "D", "explain": "(D)正確：作者引《離騷》「蘭芷變而不芳兮」，證明連蘭花也會改變本性，用來支持自己改變養蘭的想法，後來改用糞肥，蘭花就茂盛了。(A)錯誤：「無如蘭味」、「無如茗氣」是並列說明蘭與茶同屬清香一類，不是層層遞進。(B)錯誤：「不懌、不妄、不謬」寫的是作者回家後的心情與堅持，不是客人的論述。(C)錯誤：百穀、百卉、靈龜是客人用來說明「萬物都需要養分」的例子，不是暗喻作者見識廣博。", "skill": "修辭判斷先確認「這句話是誰說的」，主角錯了，後面說明再漂亮也是錯。"}], "difficulty": "中", "label": "114二技", "year": 114, "kind": "二技"}, {"id": "et114-39", "exam": "et114", "nums": [39, 40, 41], "form": "題組", "img": "img/et114-39.png", "source": "王士禛《香祖筆記‧賈胡買石》（改寫）", "author": "王士禛", "genre": "寓言故事", "types": ["文意推論", "比較閱讀", "主旨寓意"], "passage": "江寧有西域賈胡，見人家几上一石，欲買之。凡數至，主人故高其值，未售也。\n一日，重磨洗，冀增其值。明日賈胡來，驚嘆曰：「此至寶，乃天然日晷，今惜無所用矣！」不顧而去。", "translation": "江寧有個西域來的胡商，看到一戶人家桌上有塊石頭，想買下來。他來了好幾次，主人故意抬高價錢，一直沒賣成。\n有一天，主人把石頭重新磨洗了一遍，希望能賣得更高價。第二天胡商來了，驚訝地嘆道：「這本來是最珍貴的寶物，是天然的日晷，可惜現在沒有用了！」頭也不回就走了。", "keywords": [{"w": "賈胡", "m": "胡人商人"}, {"w": "几", "m": "小桌子"}, {"w": "值", "m": "價錢"}, {"w": "冀", "m": "希望"}, {"w": "日晷", "m": "利用日影測時間的儀器"}, {"w": "不顧", "m": "不回頭"}], "questions": [{"n": 39, "qtype": "單選", "stem": "下列關於甲文文意的敘述，何者正確？", "options": {"A": "雙方討價還價，買賣先敗後成", "B": "主人貪得無厭，反而弄巧成拙", "C": "石頭本非至寶，賈胡錯估高價", "D": "賈胡出爾反爾，故意戲弄賣家"}, "answer": "B", "explain": "(B)正確：主人一再抬價還不滿足，又把石頭磨洗想賣更貴，結果磨掉了石上能當日晷的天然紋理，寶物變廢物，正是貪心反而弄巧成拙。(A)錯誤：最後賈胡「不顧而去」，買賣沒有成交。(C)錯誤：石頭原本確實是「至寶」，賈胡沒有看錯。(D)錯誤：賈胡不買是因為石頭已失去價值，不是故意戲弄。", "skill": "寓言先問「誰的哪個舉動造成了結局」，答案多半就是寓意。"}, {"n": 40, "qtype": "單選", "stem": "乙文使用詞語多處重複，下列關於這些詞語的說明，何者正確？", "options": {"A": "以「奇磔虬勁」形容石頭價格不菲", "B": "以「掙扎求活」表現頑強的生命力", "C": "以「傷痛」表達愛而不得的失落感", "D": "以「歌讚」比喻海浪沖蝕擊打聲響"}, "answer": "B", "explain": "(B)正確：「掙扎求活」重複出現在奇木奇石與龍坑岸石，強調它們在困境中求生的頑強生命力。(A)錯誤：「奇磔虬勁」形容奇木奇石扭曲剛勁的姿態，和價格無關。(C)錯誤：「傷痛」指生命奮鬥時承受的痛苦，不是愛而不得。(D)錯誤：「歌讚」是後人對紋痕之美的讚美，海浪聲是另外用「咻咻如哨」形容。", "skill": "重複詞語題，把每次出現的上下文都找出來，意思要能同時說得通。"}, {"n": 41, "qtype": "單選", "stem": "下列關於甲、乙二文的比較，何者正確？", "options": {"A": "甲文著眼實用價值，乙文著眼自然美感", "B": "甲文以石喻人勤勉，乙文借石抒志遣憂", "C": "甲文用石頭考驗人品，乙文以石頭砥礪人生", "D": "甲文重點是商業誠信，乙文強調逆境中重生"}, "answer": "A", "explain": "(A)正確：甲文石頭的價值在於「天然日晷」能測時間，是實用價值；乙文欣賞奇石在掙扎求活中形成的紋痕之美，是自然美感。(B)錯誤：甲文沒有拿石頭比喻人勤勉，乙文也不是抒發自己的志向或排遣憂愁。(C)錯誤：甲文不是用石頭考驗人品，乙文也不是在談磨練人生。(D)錯誤：甲文重點是貪心弄巧成拙，不是誠信；乙文講傷痛化為美，並非「重生」。", "skill": "比較題先替兩篇各找一個關鍵詞（甲：日晷→實用；乙：紋痕之美→美感），再對選項。"}], "difficulty": "中", "label": "114二技", "year": 114, "kind": "二技"}, {"id": "et114-48", "exam": "et114", "nums": [48, 49, 50], "form": "題組", "img": "img/et114-48.png", "source": "《世說新語‧方正》", "author": "劉義慶", "genre": "筆記小品", "types": ["文意推論", "字詞解釋", "比較閱讀"], "passage": "陳太丘與友期行，期日中。過中不至，太丘捨去，去後乃至。元方時年七歲，門外戲。客問元方：「尊君在不？」答曰：「待君久不至，已去。」友人便怒曰：「非人哉！與人期行，相委而去。」元方曰：「君與家君期日中。日中不至，則是無信；對子罵父，則是無禮。」友人慚，下車引之，元方入門不顧。", "translation": "陳太丘和朋友約好一起出門，約定中午出發。過了中午朋友還沒來，陳太丘就自己先走了，走後朋友才到。陳太丘的兒子元方當時七歲，正在門外玩。朋友問元方：「你父親在家嗎？」元方回答：「等您很久您都沒來，他已經走了。」朋友就生氣地說：「真不是人啊！和人約好同行，卻丟下別人自己走了。」元方說：「您和我父親約在中午。到了中午您沒來，就是不守信用；對著兒子罵他的父親，就是沒有禮貌。」朋友感到慚愧，下車想拉元方的手，元方走進門去，頭也不回。", "keywords": [{"w": "期", "m": "約定"}, {"w": "日中", "m": "中午"}, {"w": "捨去", "m": "不再等候而離開"}, {"w": "尊君", "m": "對別人父親的敬稱"}, {"w": "家君", "m": "對人稱自己的父親"}, {"w": "委", "m": "拋下"}, {"w": "引", "m": "拉"}, {"w": "顧", "m": "回頭看"}], "questions": [{"n": 48, "qtype": "單選", "stem": "下列選項，何者最符合甲文觀點？", "options": {"A": "語言行為中出現罵人的話，是構成詈罵的主要要件", "B": "以明喻和隱喻來拐彎詈罵，表示其缺少罵人的意圖", "C": "不論顯性的或隱性的詈罵，都必須以具罵意為前提", "D": "必須同時出現罵意與罵語，詈罵事件才算得上成立"}, "answer": "C", "explain": "(C)正確：甲文說罵意是詈罵的「充分必要條件」，顯性詈罵和隱性詈罵都是「以罵意基礎展現出來」，所以都要有罵意。(A)錯誤：甲文說罵語「不是必要條件，也非充分條件」，不是主要要件。(B)錯誤：用比喻拐彎罵人仍是詈罵，只是比較委婉，罵意還在。(D)錯誤：只要有罵意，不論有沒有罵語都算詈罵，不必同時出現。", "skill": "遇到「充分、必要條件」的論述，畫出「有A就一定B」「沒A就不會B」兩句，再驗證選項。"}, {"n": 49, "qtype": "單選", "stem": "下列關於乙文文句的解釋，何者錯誤？", "options": {"A": "「下車引之」的「之」乃指元方", "B": "「待君久不至」，指陳太丘遲到", "C": "「與人期行」的「人」乃指友人", "D": "「尊君」、「家君」、「父」均指同一人"}, "answer": "B", "explain": "(B)錯誤（本題答案）：「待君久不至」是「等『君』（您）很久您都沒來」，遲到的是友人，不是陳太丘。(A)正確：友人慚愧，下車要拉的是元方。(C)正確：「與人期行，相委而去」是友人在抱怨陳太丘和「人」（友人自己）約好卻丟下他，所以「人」指友人。(D)正確：尊君是友人敬稱元方的父親，家君是元方稱自己的父親，父也是陳太丘，三者同一人。", "skill": "文言的「君」常是第二人稱「您」，代入對話者就知道誰遲到。"}, {"n": 50, "qtype": "單選", "stem": "下列①、②關於甲、乙二文文意的研判，何者正確？①「非人哉！與人期行，相委而去」，乃屬用隱喻委婉罵人。②「日中不至，則是無信；對子罵父，則是無禮」屬於詈罵事件。", "options": {"A": "①正確，②錯誤", "B": "①錯誤，②正確", "C": "①、②皆正確", "D": "①、②皆錯誤"}, "answer": "B", "explain": "①錯誤：「非人哉」直接說對方不是人，是明白出現的罵語，屬顯性詈罵，不是用隱喻委婉地罵。②正確：元方說的話沒有髒字，但帶有指責對方「無信、無禮」的罵意，依甲文「只要有罵意……不論有沒有罵語，都不妨視為詈罵」，屬於詈罵事件。所以選(B)。", "skill": "把甲文的定義當尺：先問「有沒有罵意」，再問「罵語是直接說還是用比喻」。"}], "difficulty": "中", "label": "114二技", "year": 114, "kind": "二技"}, {"id": "et115-01", "exam": "et115", "nums": [1], "form": "單題", "img": "img/et115-01.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "其法取新纊中獨繭縷／心曠神怡，寵辱偕忘／足之所履，膝之所踦／左提右挈，共成犄角／覆載之間之藉有楮先生也／鶴汀鳧渚，窮島嶼之縈迴／汝來床前，為說稗官野史之事／必能裨補闕漏，有所廣益", "translation": "方法是從新絲綿中抽取一根單繭絲；心情開朗、精神愉快，榮辱全都忘了；腳踩的地方、膝蓋頂住的地方；互相扶持，共同形成夾擊之勢；天地之間要依靠紙張啊；白鶴棲息的水邊平地、野鴨聚集的小洲，極盡島嶼曲折迴環之美；你到床前來，我說些民間傳說、野史故事給你聽；一定能彌補缺失疏漏，得到更多的益處。", "keywords": [{"w": "纊", "m": "新絲綿，讀ㄎㄨㄤˋ"}, {"w": "踦", "m": "用膝蓋頂住，讀ㄧˇ"}, {"w": "犄角", "m": "夾擊、互相支援之勢，犄讀ㄐㄧ"}, {"w": "楮先生", "m": "紙的別稱，楮讀ㄔㄨˇ"}, {"w": "渚", "m": "水中小洲，讀ㄓㄨˇ"}, {"w": "稗官", "m": "記錄街談巷語的小官，借指小說，稗讀ㄅㄞˋ"}, {"w": "裨補", "m": "彌補，裨讀ㄅㄧˋ"}], "questions": [{"n": 1, "qtype": "單選", "stem": "下列選項「」中的讀音，前後相同的是：", "options": {"A": "其法取新「纊」中獨繭縷／心「曠」神怡，寵辱偕忘", "B": "足之所履，膝之所「踦」／左提右挈，共成「犄」角", "C": "覆載之間之藉有「楮」先生也／鶴汀鳧「渚」，窮島嶼之縈迴", "D": "汝來床前，為說「稗」官野史之事／必能「裨」補闕漏，有所廣益"}, "answer": "A", "explain": "(A)正確：「纊」（沈括《夢溪筆談》，新絲綿）和「曠」（范仲淹〈岳陽樓記〉）都讀ㄎㄨㄤˋ。(B)錯誤：〈庖丁解牛〉「膝之所踦」讀ㄧˇ；「犄角」讀ㄐㄧ。(C)錯誤：「楮」讀ㄔㄨˇ；王勃〈滕王閣序〉「鳧渚」讀ㄓㄨˇ。(D)錯誤：「稗官」讀ㄅㄞˋ；諸葛亮〈出師表〉「裨補」讀ㄅㄧˋ。", "skill": "形聲字別只看聲旁猜音，同聲旁的字常常讀音不同（踦／犄、稗／裨）。"}], "difficulty": "中", "label": "115二技", "year": 115, "kind": "二技"}, {"id": "et115-05", "exam": "et115", "nums": [5], "form": "單題", "img": "img/et115-05.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "奢靡之風，固不可長／根深柢固，不可動搖／七月既望，月色澄明／肴核既盡，觥籌交錯／百廢具興，乃重修岳陽樓／乃不知有漢，無論魏晉／苟全性命於亂世，不求聞達于諸侯／其聞道也，固先乎吾", "translation": "奢侈浪費的風氣，本來就不可以助長；根基深厚牢固，不能動搖；七月十六日，月色清澈明亮；菜餚果品已經吃完，酒杯酒籌交錯雜亂；各種荒廢的事業都振興起來，於是重新整修岳陽樓；竟然不知道有漢朝，更不用說魏晉了；只求在亂世中保全性命，不求在諸侯間顯達揚名；他懂得道理，本來就比我早。", "keywords": [{"w": "固", "m": "本來／牢固"}, {"w": "既望", "m": "農曆十六日（既：已經；望：十五日）"}, {"w": "既", "m": "已經"}, {"w": "乃", "m": "於是／竟然"}, {"w": "聞達", "m": "顯達有名"}, {"w": "聞", "m": "聽聞、懂得"}], "questions": [{"n": 5, "qtype": "單選", "stem": "下列選項「」內的詞義，何者前後相同？", "options": {"A": "奢靡之風，「固」不可長／根深柢「固」，不可動搖", "B": "七月「既」望，月色澄明／肴核「既」盡，觥籌交錯", "C": "百廢具興，「乃」重修岳陽樓／「乃」不知有漢，無論魏晉", "D": "苟全性命於亂世，不求「聞」達于諸侯／其「聞」道也，固先乎吾"}, "answer": "B", "explain": "(B)正確：「既望」是望日（十五）已經過了，即十六日；〈赤壁賦〉「肴核既盡」是菜餚已經吃完，兩個「既」都是「已經」。(A)錯誤：前者「固」是副詞「本來、當然」；「根深柢固」的固是「牢固」。(C)錯誤：〈岳陽樓記〉「乃重修」的乃是「於是」；〈桃花源記〉「乃不知有漢」的乃是「竟然」。(D)錯誤：〈出師表〉「聞達」是「顯達有名」；〈師說〉「聞道」是「聽聞、懂得」。", "skill": "「既望」記成「已經過了十五」就好懂，月相詞：朔（初一）、望（十五）、既望（十六）、晦（月底）。"}], "difficulty": "中", "label": "115二技", "year": 115, "kind": "二技"}, {"id": "et115-06", "exam": "et115", "nums": [6], "form": "單題", "img": "img/et115-06.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "甲、眾惡之，必察焉；眾好之，必察焉。\n乙、越國以鄙遠，君知其難也，焉用亡鄭以陪鄰。", "translation": "甲、大家都厭惡他，一定要考察他；大家都喜歡他，也一定要考察他。乙、越過別國把遠方的土地當作邊邑，您知道這很困難，何必滅掉鄭國來增加鄰國的土地呢？", "keywords": [{"w": "焉（句末）", "m": "於之，對他（具指示作用）"}, {"w": "焉用", "m": "何必（反詰）"}, {"w": "鄙", "m": "邊邑，作動詞「當作邊邑」"}, {"w": "陪", "m": "增加"}], "questions": [{"n": 6, "qtype": "單選", "stem": "參照右框「焉」的用法說明，下列甲、乙中的「焉」，最適當的歸類是：（右框：①具指示作用。如：心不在焉。②具反詰作用。如：塞翁失馬，焉知非福。③表示語氣，置句末。如：此何以稱焉。）甲、眾惡之，必察焉；眾好之，必察焉。乙、越國以鄙遠，君知其難也，焉用亡鄭以陪鄰。", "options": {"A": "甲屬於②；乙屬於③", "B": "甲屬於③；乙屬於①", "C": "甲屬於②；乙屬於①", "D": "甲屬於①；乙屬於②"}, "answer": "D", "explain": "甲（《論語》）：「必察焉」是「一定要考察他」，焉等於「於之」，指那個被眾人厭惡或喜愛的人，屬①指示作用。乙（〈燭之武退秦師〉）：「焉用亡鄭以陪鄰」是「何必滅鄭來增加鄰國」，焉是「何、怎麼」，屬②反詰作用。所以選(D)；(A)(C)把甲歸為反詰、(B)把甲歸為語氣詞，乙也都歸錯。", "skill": "「焉」放句首或動詞前多是「何、怎麼」（反詰）；放句末要試著換成「於此、於之」，能換就是指示。"}], "difficulty": "中", "label": "115二技", "year": 115, "kind": "二技"}, {"id": "et115-08", "exam": "et115", "nums": [8], "form": "單題", "img": "img/et115-08.png", "source": "杜甫〈秋述〉", "author": "杜甫", "genre": "書信序跋", "types": ["句意理解", "典故出處"], "passage": "秋，杜子臥病長安旅次，多雨生魚，青苔及榻。常時車馬之客，舊，雨來；今，雨不來。", "translation": "秋天，我杜甫在長安的旅舍裡臥病，雨下得多，積水中都生了魚，青苔長到床邊。平時那些乘車騎馬來往的客人，從前下雨也會來；如今，下雨就不來了。", "keywords": [{"w": "旅次", "m": "旅途中暫住的地方"}, {"w": "榻", "m": "床"}, {"w": "舊雨、今雨", "m": "後人用來代稱老朋友與新朋友"}], "questions": [{"n": 8, "qtype": "單選", "stem": "閱讀下文，何者最符合文中「」的意思？秋，杜子臥病長安旅次，多雨生魚，青苔及榻。常時車馬之客，「舊，雨來；今，雨不來」。（杜甫〈秋述〉）", "options": {"A": "天氣轉冷且多雨，故遊客稀稀落落", "B": "臥病在床逢雨天，感受人情的冷暖", "C": "今天這場及時雨，解除了心中愁悶", "D": "在貧病交迫之時，屋漏偏逢連夜雨"}, "answer": "B", "explain": "(B)正確：從前即使下雨，朋友也會來探望；如今杜甫落魄臥病，一下雨就沒人來了，感慨世態炎涼、人情冷暖。(A)錯誤：「車馬之客」是來拜訪的朋友，不是遊客；重點也不在天氣冷。(C)錯誤：文中的雨讓屋裡生魚長苔，不是解愁的及時雨。(D)錯誤：雖然處境困苦，但「」中比較的是朋友「從前來、現在不來」，重點是人情變化，不是災禍接連。", "skill": "看到「舊……今……」的對照句，答案通常落在「變化」上，問自己：什麼變了？"}], "difficulty": "易", "label": "115二技", "year": 115, "kind": "二技"}, {"id": "et115-09", "exam": "et115", "nums": [9], "form": "單題", "img": "img/et115-09.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "楚左尹項伯者，項羽季父也／菊，花之隱逸者也／醒能述以文者，太守也／以其無禮於晉，且貳於楚也／即公大兄無奕女，左將軍王凝之妻也", "translation": "楚國左尹項伯，是項羽的叔父；菊花，是花中的隱士；酒醒後能用文章記述這件事的，是太守；因為鄭國對晉國無禮，又暗中依附楚國；就是謝公大哥謝無奕的女兒、左將軍王凝之的妻子。", "keywords": [{"w": "……者，……也", "m": "文言判斷句的典型句式"}, {"w": "季父", "m": "叔父"}, {"w": "貳", "m": "有二心，暗中依附"}], "questions": [{"n": 9, "qtype": "單選", "stem": "表示肯定的判斷句，通常可在主語後面加上「是」字來理解，例如「楚左尹項伯者，項羽季父也」，意為「楚左尹項伯是項羽的叔父」。下列選項，何者不屬於肯定的判斷句？", "options": {"A": "菊，花之隱逸者也", "B": "醒能述以文者，太守也", "C": "以其無禮於晉，且貳於楚也", "D": "即公大兄無奕女，左將軍王凝之妻也"}, "answer": "C", "explain": "(C)正確（不屬於判斷句）：〈燭之武退秦師〉「以其無禮於晉，且貳於楚也」是說明晉秦圍鄭的「原因」，句中的「以」是「因為」，沒辦法加「是」來解釋成「A是B」。(A)屬判斷句：周敦頤〈愛蓮說〉，菊「是」花中的隱士。(B)屬判斷句：歐陽脩〈醉翁亭記〉，酒醒能寫文章的「是」太守。(D)屬判斷句：《世說新語》，這位女子「是」謝無奕的女兒、王凝之的妻子。", "skill": "判斷句檢驗法：在主語後面塞進「是」，讀得通就是判斷句；句尾有「也」不一定就是判斷句。"}], "difficulty": "易", "label": "115二技", "year": 115, "kind": "二技"}, {"id": "et115-14", "exam": "et115", "nums": [14], "form": "單題", "img": "img/et115-14.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "歸去來兮，田園將蕪胡不歸？／細重貨物，按輕重取價；粗鬆貨物，按方位取價。\n甲、宮中府中，俱為一體，陟罰臧否，不宜異同。\n乙、時止則止，時行則行，動靜不失其時，其道光明。", "translation": "回去吧！田園都要荒蕪了，為什麼還不回去？／精細沉重的貨物，按重量計價；粗大鬆散的貨物，按體積計價。甲、宮中和丞相府都是一個整體，獎懲褒貶不應該有所不同。乙、該停止時就停止，該行動時就行動，一動一靜都不錯失時機，這樣的道路就光明。", "keywords": [{"w": "偏義複詞", "m": "由兩個意思相反或相關的字組成，卻只取其中一字的意思"}, {"w": "異同", "m": "偏取「異」，不同"}, {"w": "陟罰臧否", "m": "升遷懲罰、褒獎批評"}, {"w": "動靜", "m": "行動與靜止，兩義並取"}], "questions": [{"n": 14, "qtype": "單選", "stem": "參閱下表，判斷下列甲、乙二句「」內詞語的取義方式，選出正確選項：（①歸「去來」兮，田園將蕪胡不歸？──「去來」一詞，僅取「去」義，不取「來」義。②細重貨物，按「輕重」取價；粗鬆貨物，按方位取價。──「輕重」一詞，「輕」、「重」二字皆各取義。）甲、宮中府中，俱為一體，陟罰臧否，不宜「異同」。乙、時止則止，時行則行，「動靜」不失其時，其道光明。", "options": {"A": "甲、乙都屬於①", "B": "甲、乙都屬於②", "C": "甲屬於②；乙屬於①", "D": "甲屬於①；乙屬於②"}, "answer": "D", "explain": "甲（〈出師表〉）：「不宜異同」是不應該有「不同」，只取「異」義，「同」字不取義，是偏義複詞，屬①。乙（《易經‧艮卦》）：「動靜不失其時」是行動和靜止都要合乎時機，「動」「靜」兩字都有意思，屬②。所以選(D)；(A)(B)(C)都至少歸錯一句。", "skill": "偏義複詞檢驗法：把兩字分開代入句子，只有一個字說得通，就是偏義複詞。"}], "difficulty": "中", "label": "115二技", "year": 115, "kind": "二技"}, {"id": "et115-16", "exam": "et115", "nums": [16], "form": "單題", "img": "img/et115-16.png", "source": "題辭（應用文）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "114年：誓約同心、齒德俱尊、桃李芬芳／113年：盟結良緣、北斗星沉、啟迪有方／112年：琴瑟和鳴、大展鴻圖、五福全歸", "translation": "114年：發誓同心相守（賀結婚）、年紀與德行都受人尊敬（賀男性長輩壽辰）、學生像桃李一樣美好眾多（謝師）／113年：結下美好姻緣（賀結婚）、北斗星沉落（哀悼男性過世）、啟發教導很有方法（謝師）／112年：夫妻像琴瑟合奏般和諧（賀結婚）、大大施展遠大的計畫（賀開業）、五種福分都圓滿而歸（哀悼過世）。", "keywords": [{"w": "誓約同心、盟結良緣、琴瑟和鳴", "m": "結婚賀辭"}, {"w": "齒德俱尊", "m": "男性壽辭"}, {"w": "北斗星沉", "m": "男喪輓辭"}, {"w": "五福全歸", "m": "男女通用的喪事輓辭"}, {"w": "桃李芬芳、啟迪有方", "m": "感謝師恩"}, {"w": "大展鴻圖", "m": "開業賀辭"}], "questions": [{"n": 16, "qtype": "單選", "stem": "某花藝公司根據近三年客戶所選擇贈送的題辭，彙整出當年度的排行榜如下表。下列選項，何者的敘述正確？（表：排行★★★★★：114年誓約同心、113年盟結良緣、112年琴瑟和鳴；排行★★★★：114年齒德俱尊、113年北斗星沉、112年大展鴻圖；排行★★★：114年桃李芬芳、113年啟迪有方、112年五福全歸）", "options": {"A": "三年的冠軍皆屬於婚嫁類題辭", "B": "三年皆有感謝師恩教導的題辭", "C": "113、114年題辭皆有祝賀女性壽星", "D": "112、113年題辭皆適用於喜慶場合"}, "answer": "A", "explain": "(A)正確：三年的第一名「誓約同心」、「盟結良緣」、「琴瑟和鳴」都是結婚賀辭。(B)錯誤：114年「桃李芬芳」、113年「啟迪有方」是謝師，但112年沒有（大展鴻圖是開業、五福全歸是喪事）。(C)錯誤：「齒德俱尊」是祝賀男性長者的壽辭；「北斗星沉」是男喪輓辭，更不是祝壽。(D)錯誤：113年的「北斗星沉」、112年的「五福全歸」都是喪事用語，不適用喜慶。", "skill": "題辭先分「喜、壽、喪、業、師」五類，再看性別：壽與喪常分男女（男：南極、北斗；女：寶婺、萱）。"}], "difficulty": "中", "label": "115二技", "year": 115, "kind": "二技"}, {"id": "et115-21", "exam": "et115", "nums": [21, 22, 23], "form": "題組", "img": "img/et115-21.png", "source": "《莊子‧養生主》", "author": "莊子", "genre": "寓言故事", "types": ["文意推論", "比較閱讀", "主旨寓意"], "passage": "始臣之解牛之時，所見無非全牛者；三年之後，未嘗見全牛也；方今之時，臣以神遇而不以目視，官知止而神欲行。依乎天理，批大郤，導大窾，因其固然。……雖然，每至於族，吾見其難為，怵然為戒，視為止，行為遲。動刀甚微，謋然已解，如土委地。", "translation": "我剛開始解牛的時候，眼中看到的都是一整頭牛；三年以後，就不再看到完整的牛了；到了現在，我是用心神去接觸牛，而不用眼睛看，感官停止作用，只憑心神運行。順著牛身天然的紋理，劈開筋骨間的大縫隙，引刀進入骨節間的空隙，依照牛本來的結構下刀。……即使如此，每當遇到筋骨交錯聚結的地方，我知道不容易處理，就小心警惕，目光專注，動作放慢。刀子輕輕一動，牛就嘩啦一聲解體了，像泥土散落在地上。", "keywords": [{"w": "以神遇", "m": "用心神去接觸"}, {"w": "官知止", "m": "感官的作用停止"}, {"w": "批", "m": "劈開"}, {"w": "郤", "m": "縫隙"}, {"w": "窾", "m": "空隙"}, {"w": "族", "m": "筋骨交錯聚結之處"}, {"w": "怵然", "m": "小心警惕的樣子"}, {"w": "謋然", "m": "牛體解開的聲音"}, {"w": "委", "m": "散落、堆放"}], "questions": [{"n": 21, "qtype": "單選", "stem": "甲文將庖丁視為「就像扮演生物生命轉化儀式的主持人」，下列何者最接近作者用意？", "options": {"A": "說明莊子強調技藝純熟的主張", "B": "評論世俗社會對屠戶者的成見", "C": "認為解牛過程是實踐道的行為", "D": "強調庖廚業對神秘力量的敬畏"}, "answer": "C", "explain": "(C)正確：甲文說庖丁「由道的視界去看」，把十九年屠殺「轉化為踐行大道的絕妙藝術」，說他像儀式主持人，就是說解牛是在實踐道。(A)錯誤：作者重點不在技術熟練，而在「道」的境界。(B)錯誤：文中沒有批評社會對屠夫的偏見。(D)錯誤：說的是順應天理、生死轉化，不是敬畏神秘力量。", "skill": "比喻題問「作者用意」，找比喻後面作者自己的解釋句（這裡是「踐行大道」）。"}, {"n": 22, "qtype": "單選", "stem": "甲文劃底線處①，最適合填入乙文的哪一句？", "options": {"A": "所見無非全牛者", "B": "未嘗見全牛也", "C": "以神遇而不以目視", "D": "每至於族，吾見其難為"}, "answer": "A", "explain": "(A)正確：①前面說庖丁「開始操刀為屠時，和凡俗的庖廚沒兩樣」，後面說「這時他所看到的死和世俗一樣」，對應乙文剛解牛時「所見無非全牛者」，眼中只是一整頭牛。(B)錯誤：「未嘗見全牛」是三年後的進步，甲文說三年後才開始轉變。(C)錯誤：「以神遇」是最高境界，不是剛開始。(D)錯誤：這是熟練後遇到難處仍謹慎，不是初學時的狀態。", "skill": "對應題先看時間詞：甲文「開始操刀時」就配乙文「始臣之解牛之時」。"}, {"n": 23, "qtype": "單選", "stem": "如以甲文對「解」、「委」二字的分析，解釋乙文「謋然已解，如土委地」之意，下列選項的說明，何者正確？", "options": {"A": "肢解後的牛隻肉體，以有用的部位滋養大地", "B": "牛的軀體雖已消解，生命卻回歸本然的狀態", "C": "牛隻死亡如同土壤分化，皆未具生命的價值", "D": "解牛結果如同土山崩塌，皆象徵生命的毀滅"}, "answer": "B", "explain": "(B)正確：甲文說被「解」的只是形軀，不是真正的生命；「委」有委託、復原之意，像土壤回歸大地，所以是形體消解、生命回歸本然。(A)錯誤：甲文沒有說牛肉用來滋養大地。(C)錯誤：甲文強調生命是回歸大化，不是說沒有價值。(D)錯誤：甲文正是要消除死亡的恐怖，不是象徵毀滅。", "skill": "「依甲文解釋乙文」題，答案一定要用甲文給的定義，不能用自己的直覺。"}], "difficulty": "中", "label": "115二技", "year": 115, "kind": "二技"}, {"id": "et115-28", "exam": "et115", "nums": [28, 29, 30], "form": "題組", "img": "img/et115-28.png", "source": "李漁《閒情偶寄》（改寫）", "author": "李漁", "genre": "筆記小品", "types": ["文意推論", "比較閱讀", "寫作手法"], "passage": "Ⅰ蟹之為物至美，而其味壞於食之之人。以之為羹者，鮮則鮮矣，而蟹之美質何地？以之為膾者，膩則膩矣，而蟹之真味不存。更可厭者，斷為兩截，和以油、鹽、豆粉而煎之，使蟹之色、蟹之香與蟹之真味全失。\nⅡ世間好物，利在孤行。蟹之鮮而肥，甘而膩，白似玉而黃似金，已造色香味三者之至極，更無一物可以上之。\nⅢ凡食蟹者，只合全其故體，蒸而熟之，貯以冰盤，列之几上，聽客自取自食。剖一筐，食一筐，斷一螯，食一螯，則氣與味纖毫不漏。出於蟹之軀殼者，即入於人之口腹，飲食之三昧，再有深入於此者哉？\nⅣ凡治他具，皆可人任其勞，我享其逸，獨蟹與瓜子、菱角三種，必須自任其勞。旋剝旋食則有味，人剝而我食之，不特味同嚼蠟，且似不成其為蟹與瓜子、菱角，而別是一物者。此與好香必須自焚，好茶必須自斟，僮僕雖多，不能任其力者，同出一理。", "translation": "Ⅰ螃蟹是極美味的東西，但它的滋味卻被吃的人糟蹋了。拿來煮湯的，鮮是鮮了，但螃蟹美好的本質在哪裡呢？拿來做成細切的膾，肥膩是肥膩了，但螃蟹的真味卻沒了。更討厭的是，把蟹切成兩半，拌上油、鹽、豆粉去煎，讓蟹的顏色、香氣和真味全都喪失。\nⅡ世上的好東西，貴在單獨品嘗。螃蟹的鮮美肥嫩、甘甜細膩，蟹肉白如玉、蟹黃黃如金，已經達到色香味三者的極致，沒有任何東西能超越它。\nⅢ凡是吃蟹，只應保全它原本的整體，蒸熟後放在冰盤裡，擺在桌上，讓客人自己拿自己吃。剖開一個殼吃一個殼，掰下一隻螯吃一隻螯，那麼香氣和滋味一絲一毫都不會流失。從蟹殼裡出來的，立刻就進到人的嘴裡，飲食的奧妙，還有比這更深的嗎？\nⅣ處理其他食物，都可以讓別人代勞，自己享受安逸，只有螃蟹、瓜子、菱角三種，必須自己動手。邊剝邊吃才有味道，別人剝好給我吃，不但味同嚼蠟，而且好像不再是螃蟹、瓜子、菱角，而變成另一種東西了。這和好香必須自己點、好茶必須自己倒，僮僕再多也不能替代，是同一個道理。", "keywords": [{"w": "羹", "m": "濃湯"}, {"w": "膾", "m": "切細的肉"}, {"w": "孤行", "m": "單獨食用，不搭配他物"}, {"w": "上", "m": "超過"}, {"w": "合", "m": "應該"}, {"w": "故體", "m": "原本的形體"}, {"w": "三昧", "m": "奧妙、訣竅"}, {"w": "治他具", "m": "處理其他食物"}, {"w": "旋", "m": "隨即、一邊"}], "questions": [{"n": 28, "qtype": "單選", "stem": "依據上文，下列關於李漁的看法，敘述正確的選項是：", "options": {"A": "吃蟹時在旁焚好香、煮好茶，更能增添風雅", "B": "螃蟹烹煮程序複雜，依序為羮、膾、煎、蒸", "C": "吃蟹時勿沾各類調味，但可配著瓜子和菱角", "D": "吃蟹必須自己剝食，才能享受食蟹過程之味"}, "answer": "D", "explain": "(D)正確：第Ⅳ段說蟹「必須自任其勞，旋剝旋食則有味」，別人剝好就「味同嚼蠟」。(A)錯誤：好香自焚、好茶自斟只是類比「要親自動手」的道理，不是說吃蟹時要焚香煮茶。(B)錯誤：羹、膾、煎是李漁批評的錯誤吃法，他只主張「蒸」，並不是依序的烹煮程序。(C)錯誤：瓜子、菱角是和蟹一樣「要自己剝」的食物，不是搭配著吃；而且第Ⅱ段說好物「利在孤行」，不宜搭配。", "skill": "注意「此與……同出一理」是類比，被拿來比的事物不是文章真正要做的事。"}, {"n": 29, "qtype": "單選", "stem": "下列甲、乙文句，依序可以對應上文哪一段文意？選出最適當選項。甲、袁枚《隨園食單》：「蟹宜獨食，不宜搭配他物。」乙、焦桐〈論螃蟹〉：「我尤其不能忍受新鮮的螃蟹被醬爆、炒、焗、炸，這是很保守的偏執。」", "options": {"A": "Ⅱ、Ⅰ", "B": "Ⅰ、Ⅳ", "C": "Ⅲ、Ⅱ", "D": "Ⅲ、Ⅳ"}, "answer": "A", "explain": "(A)正確：甲「蟹宜獨食，不宜搭配他物」對應第Ⅱ段「世間好物，利在孤行」；乙不能忍受螃蟹被醬爆炒炸，對應第Ⅰ段批評做羹、做膾、加油鹽豆粉煎，破壞真味。(B)錯誤：甲不是批評烹調方法，乙也和第Ⅳ段「自己剝」無關。(C)錯誤：第Ⅲ段講蒸蟹整隻自取，不是「獨食」；乙也不是讚美蟹的色香味。(D)錯誤：Ⅲ、Ⅳ講的是吃法與親自剝食，和甲乙都不對應。", "skill": "先替每段下一個標題（Ⅰ反對亂煮、Ⅱ單獨吃、Ⅲ整隻蒸、Ⅳ自己剝），再拿引文去配。"}, {"n": 30, "qtype": "單選", "stem": "上文劃線處的文句，何者屬於遞進的寫作手法？", "options": {"A": "①", "B": "②", "C": "③", "D": "④"}, "answer": "A", "explain": "(A)正確：①先說做膾失去真味，再用「更可厭者」帶出煎蟹讓色、香、味「全失」，程度一層比一層嚴重，是遞進。(B)錯誤：②「鮮而肥，甘而膩，白似玉而黃似金」是並列排比、譬喻蟹的美好，沒有層層加深。(C)錯誤：③是用反問「再有深入於此者哉」強調吃法的奧妙。(D)錯誤：④用「好香自焚、好茶自斟」作類比說理，是並列而非遞進。", "skill": "遞進的訊號詞：「更、甚至、何況、況且」，看到它再確認程度是否加深。"}], "difficulty": "中", "label": "115二技", "year": 115, "kind": "二技"}, {"id": "et115-31", "exam": "et115", "nums": [31, 32, 33], "form": "題組", "img": "img/et115-31.png", "source": "《名公書判清明集》", "author": "", "genre": "其他", "types": ["文意推論", "句意理解", "寫作手法"], "passage": "韓知丞通經名士，晚登科第，可見洞明理義，飽閱世故，豈不知愛妾之子，猶龍生於蛇腹耳。何忍委棄於賣菜之家，經涉年歲，不復收養，乃自輕遺體如此，何邪？其不可信者一也。周蘭姐若果懷妊而出，踰月而產，便當時挈還韓知丞之家。設若主母不容，亦合經官陳詞，以為後日證據之地。今其子董三八已娶妻生子矣，二十七年間，杳然無一狀及此，何邪？其不可信者二也。韓知丞已歷數任，脫寒素而享榮貴，棄虀鹽而植菑畬，非曩日比矣。周蘭姐不思抱衾之舊恩，恥破敗之窮態，反甘心聽其子之貧賤，鬻蔬菜於通衢，忍凍餒以度日，畧不攜造官所以求飽，何邪？此不可信者三也。韓知丞亦非多男，僅有前妻所生時宜一子而已，且體羸唇闕，未必愜幹蠱之望。設使韓知丞果有所生之子在外，豈不及早收養，飽之以膏粱，教之以詩禮，庶使子舍眾多，書種不絕。今乃恝然不恤，何邪？此不可信者四也。且周蘭姐稱，韓知丞甚有意收拾，奈何前孺人林氏妬忌，不容取歸，所以狼狽街頭日久。此說亦是，但林氏於寶慶二年（西元1226年）已身故，是時內無嫉妬之妻矣，董三八何不歸來舉服承重，韓知丞何不乘機收回撫養，此十餘年間，又略無一語及所生子，何邪？其不可信者五也。", "translation": "韓知丞是精通經學的名士，晚年考中進士，可見他明白道理、閱歷豐富，怎會不知道愛妾所生的兒子，就像蛇腹中生出的龍一樣珍貴。怎麼忍心把兒子丟在賣菜的人家，經過許多年都不收養，這樣輕賤自己的骨肉，為什麼？這是不可信的第一點。周蘭姐如果真是懷孕後離開韓家，過一個月就生產，就應當立刻帶孩子回韓家。就算主母不容，也應該向官府陳述，作為日後的證據。如今她的兒子董三八已經娶妻生子了，二十七年來，沒有一張狀紙提到這件事，為什麼？這是不可信的第二點。韓知丞已做過幾任官，脫離貧寒享受富貴，不再過粗茶淡飯的日子而擁有田產，和從前不能相比了。周蘭姐不想想從前侍寢的舊恩，不以破落窮困為恥，反而甘心讓兒子貧賤，在大街上賣菜，忍凍挨餓過日子，一點也不曾帶他到韓知丞的官署求溫飽，為什麼？這是不可信的第三點。韓知丞兒子不多，只有前妻生的時宜一個，而且身體瘦弱、嘴唇有缺陷，未必能符合繼承家業的期望。假使韓知丞真有親生兒子在外，怎會不及早收養，用好飯菜養他，用詩書禮義教他，讓兒子多一些，讀書的種子不斷絕。如今竟然漠不關心，為什麼？這是不可信的第四點。而且周蘭姐說，韓知丞很想收回兒子，無奈前妻林氏嫉妒，不讓帶回，所以母子長期在街頭落魄。這說法似乎有理，但林氏在寶慶二年已經過世，那時家中沒有嫉妒的妻子了，董三八為何不回來為父服喪、承擔宗祧，韓知丞為何不趁機收回撫養，這十幾年間，又完全沒有一句話提到這個兒子，為什麼？這是不可信的第五點。", "keywords": [{"w": "龍生於蛇腹", "m": "比喻妾（出身低微者）所生之子仍是珍貴的骨肉"}, {"w": "遺體", "m": "父母所生的身體，指親生骨肉"}, {"w": "挈", "m": "帶領"}, {"w": "杳然", "m": "毫無蹤影"}, {"w": "虀鹽", "m": "醃菜和鹽，指清貧生活"}, {"w": "菑畬", "m": "田地，指田產"}, {"w": "抱衾", "m": "侍寢，指妾的身分"}, {"w": "鬻", "m": "賣"}, {"w": "幹蠱", "m": "繼承並辦好父親的事業"}, {"w": "恝然", "m": "漠不關心的樣子"}, {"w": "舉服承重", "m": "為父服喪，承擔宗祧"}], "questions": [{"n": 31, "qtype": "單選", "stem": "依據上文，下列何者最可能是周蘭姐提出的陳述？", "options": {"A": "韓時覲並非韓家人，不應該干涉家務", "B": "韓時宜瞞騙韓家，不讓她兒子分家產", "C": "她未嫁獨力撫養孩子，韓家應給名分", "D": "韓家的主母妒忌，使她無法留在韓家"}, "answer": "D", "explain": "(D)正確：判詞第五點引周蘭姐的話「韓知丞甚有意收拾，奈何前孺人林氏妬忌，不容取歸」，就是主母妒忌讓她無法回韓家。(A)錯誤：韓時覲是韓知丞的姪子，文中沒有周蘭姐質疑他身分的說法。(B)錯誤：韓時宜只是阻擋董三八入屋，沒有提到「瞞騙韓家」。(C)錯誤：周蘭姐已嫁給賣菜的董三二，不是未嫁。", "skill": "「誰說的」題目，在原文找「某某稱、某某曰」的引述標記。"}, {"n": 32, "qtype": "單選", "stem": "下列選項，對於官員判詞的解釋，何者正確？", "options": {"A": "從「晚登科第」、「已歷數任」說明韓家官宦世家應善盡職責", "B": "從「忍凍餒以度日」、「狼狽街頭日久」證明韓知丞創業維艱", "C": "從「杳然無一狀」、「不歸來舉服承重」證明董三八非韓家之子", "D": "從「龍生於蛇腹」、「未必愜幹蠱之望」說明韓時宜的才能平庸"}, "answer": "C", "explain": "(C)正確：二十七年來沒有一張狀紙（杳然無一狀），林氏死後也不回來為父服喪（不歸來舉服承重），官員用這些不合常理之處推斷董三八不是韓家之子。(A)錯誤：「晚登科第」是說韓知丞明白事理，「已歷數任」是說他已富貴，用來論證他不可能放任親子流落，不是要韓家盡職責。(B)錯誤：「忍凍餒」、「狼狽街頭」說的是周蘭姐母子的處境，不是韓知丞創業艱難。(D)錯誤：「龍生於蛇腹」是說妾生的兒子同樣珍貴，與韓時宜才能無關。", "skill": "判詞的每個引句都是「論證材料」，先問它證明了什麼，再看選項說法是否一致。"}, {"n": 33, "qtype": "單選", "stem": "官員判詞以「五項不可信」逐條論證，其論證方式最接近下列何者？", "options": {"A": "由過去的案例推導出普遍性的法則", "B": "先假定結論正確再尋找有力的證人", "C": "引述權威人士們的言論以建立結論", "D": "以反證法排除對方主張成立的可能"}, "answer": "D", "explain": "(D)正確：官員先假設周蘭姐的說法成立（若董三八真是韓家之子），再推出「應該早就收養、早就告官、早就回來服喪」等結果，但事實都不是這樣，所以逐條推翻對方主張，屬反證法。(A)錯誤：判詞沒有引用過去的案例。(B)錯誤：官員沒有找證人，而是從常理推論。(C)錯誤：判詞沒有引用權威人士的話。", "skill": "反證法的樣子：「如果你說的是真的，那就應該……；但事實並非如此，所以你說的不成立。」"}], "difficulty": "難", "label": "115二技", "year": 115, "kind": "二技"}, {"id": "et115-34", "exam": "et115", "nums": [34, 35, 36], "form": "題組", "img": "img/et115-34.png", "source": "李肇《唐國史補》", "author": "李肇", "genre": "筆記小品", "types": ["句意理解", "寫作手法", "比較閱讀"], "passage": "【甲】李舟好事，嘗得村舍煙竹，截以為笛，堅如鐵石，以遺李牟。牟吹笛天下第一，月夜泛江，維舟吹之，寥亮逸發，上徹雲表。俄有客獨立於岸，呼船請載。既至，請笛而吹，甚為精壯，山河可裂，牟平生未嘗見。及入破，呼吸盤擗，其笛應聲粉碎，客散不知所之。舟著〈記〉，疑其蛟龍也。\n【乙】李牟，秋夜吹笛於瓜洲，舟楫甚隘。初發調，群動皆息。及數奏，微風颯然而至。又俄頃，舟人賈客，皆有怨歎悲泣之聲。", "translation": "【甲】李舟喜歡新奇的事，曾得到農家被煙燻過的竹子，截成一支笛子，堅硬得像鐵石，送給了李牟。李牟吹笛的技藝天下第一，他在月夜泛舟江上，把船繫好吹笛，笛聲清亮奔放，直上雲霄。不久有位客人獨自站在岸邊，呼喚船隻請求載他。上船後，向李牟借笛來吹，笛聲非常雄壯，好像山河都要被震裂，是李牟一生從未見過的。吹到樂曲急促的「入破」段落時，氣息盤旋激盪，笛子隨著聲音粉碎，客人也消失不知去向。李舟寫了一篇〈記〉，懷疑那位客人是蛟龍。\n【乙】李牟在秋夜於瓜洲吹笛，船隻擠得很滿。剛起調時，周遭一切聲響都靜止了。吹了幾曲之後，微風颯颯吹來。又過了一會兒，船夫和商人都發出哀怨悲泣的聲音。", "keywords": [{"w": "好事", "m": "喜歡新奇的事物"}, {"w": "遺", "m": "贈送"}, {"w": "維舟", "m": "繫船"}, {"w": "寥亮", "m": "聲音清亮"}, {"w": "雲表", "m": "雲外"}, {"w": "入破", "m": "唐代大曲中節奏急促的段落"}, {"w": "盤擗", "m": "盤旋激盪"}, {"w": "群動", "m": "各種聲響、動靜"}, {"w": "賈客", "m": "商人"}], "questions": [{"n": 34, "qtype": "單選", "stem": "下列關於甲文文句的說明，何者正確？", "options": {"A": "「以遺李牟」：笛子遺忘在李牟的住處", "B": "「維舟吹之」：李舟依靠著李牟吹笛", "C": "「呼船請載」：客人想上船聽李舟吹笛", "D": "「請笛而吹」：客人跟李牟借笛來吹"}, "answer": "D", "explain": "(D)正確：客人上船後「請笛而吹」，向李牟借了那支笛子來吹。(A)錯誤：「遺」讀ㄨㄟˋ，是「贈送」，李舟把笛子送給李牟，不是遺忘。(B)錯誤：「維舟」是把船繫住，吹笛的是李牟，不是李舟依靠李牟。(C)錯誤：在船上吹笛的是李牟，客人上船後也是自己借笛吹，不是聽李舟吹。", "skill": "「遺」當動詞接人名時多是「贈送」；李舟、李牟名字相近，作答前先確認每句的主角是誰。"}, {"n": 35, "qtype": "單選", "stem": "下列關於甲、乙二文寫作手法的敘述，何者正確？", "options": {"A": "甲文「上徹雲表」對比「山河可裂」展現出吹笛者技藝層次的高低", "B": "乙文「初發調」、「及數奏」、「又俄頃」呈現從晚吹到早的遞進", "C": "甲文「寥亮逸發」、乙文「怨歎悲泣之聲」都是直接描摹笛聲曲調", "D": "甲文「月夜泛江」、乙文「秋夜吹笛於瓜洲」皆明確點出季節地點"}, "answer": "A", "explain": "(A)正確：李牟的笛聲「上徹雲表」已經很高，客人的笛聲「山河可裂」更雄壯，「牟平生未嘗見」，用對比顯出客人技藝更高一層。(B)錯誤：這三個詞表示一段時間內的先後，「俄頃」是一會兒，並非從晚上吹到天亮。(C)錯誤：「怨歎悲泣之聲」是聽眾的反應，是側面烘托，不是直接寫笛聲。(D)錯誤：甲文「月夜泛江」只說月夜和江上，沒有點出季節，也沒有具體地名。", "skill": "「直接描寫」寫的是對象本身（笛聲如何），「側面烘托」寫的是旁人的反應。"}, {"n": 36, "qtype": "單選", "stem": "依據甲、乙二文，判斷①、②的敘述，選出正確選項：①乙文可作為甲文「李牟吹笛天下第一」的證明 ②《唐國史補》收錄甲文應晚於李舟所著的〈記〉", "options": {"A": "①、②皆錯誤", "B": "①正確、②錯誤", "C": "①錯誤、②無法判斷", "D": "①無法判斷、②正確"}, "answer": "D", "explain": "①無法判斷：乙文只寫出李牟笛聲動人，能讓萬籟俱寂、聽者悲泣，但沒有和別人比較，無法證明他是「天下第一」。②正確：甲文最後說「舟著〈記〉，疑其蛟龍也」，表示李舟先寫了〈記〉，《唐國史補》記下這件事（包括李舟寫記），收錄時間當然在〈記〉之後。所以選(D)。", "skill": "「能否證明」題要嚴格：證據只能證明它說到的範圍，「很厲害」不等於「第一」。"}], "difficulty": "中", "label": "115二技", "year": 115, "kind": "二技"}, {"id": "et115-37", "exam": "et115", "nums": [37, 38], "form": "題組", "img": "img/et115-37.png", "source": "《史記‧淮陰侯列傳》（改寫）", "author": "司馬遷", "genre": "史傳人物", "types": ["文意推論", "典故出處", "比較閱讀"], "passage": "淮陰侯韓信者，淮陰人也。信釣於城下，諸母漂，有一母見信飢，飯信，竟漂數十日。信喜，謂漂母曰：「吾必有以重報母。」母怒曰：「大丈夫不能自食，吾哀王孫而進食，豈望報乎！」\n及項梁渡淮，信杖劍從之。項梁敗，又屬項羽，羽以為郎中。數以策干項羽，羽不用。漢王之入蜀，信亡楚歸漢，未得知名，為連敖。\n信數與蕭何語，何奇之。信度何等已數言上，上不我用，即亡。何聞信亡，不及以聞，自追之。居一二日，何來謁上，上且怒且喜。何曰：「諸將易得耳。至如信者，國士無雙。王必欲長王漢中，無所事信；必欲爭天下，非信無所與計事者。」王曰：「吾為公以為將。」何曰：「雖為將，信必不留。」王曰：「以為大將。」何曰：「幸甚。」\n（淮陰侯表）侯功：兵初起，以卒從項梁，梁死屬項羽為郎中。至咸陽，亡從入漢，為連敖典客，蕭何言為大將軍。別定魏、齊，為王，徙楚（王）。坐擅發兵，廢為淮陰侯。高祖：六年四月，侯韓信元年。十一年，信謀反關中，呂后誅信，夷三族，國除。", "translation": "淮陰侯韓信是淮陰人。韓信在城下釣魚，有幾位婦人在河邊漂洗絲絮，其中一位看到韓信餓了，就拿飯給他吃，一直到漂洗完工的幾十天都是如此。韓信很高興，對漂母說：「我將來一定重重報答您。」漂母生氣地說：「大丈夫不能養活自己，我是可憐你這位公子才給你飯吃，哪裡是希望你報答！」\n項梁渡過淮河，韓信帶著劍去投靠他。項梁戰敗後，又歸屬項羽，項羽讓他當郎中。他多次向項羽獻策，項羽都不採用。漢王進入蜀地時，韓信離開楚軍投奔漢王，還沒有名氣，只當個叫「連敖」的小官。\n韓信多次和蕭何談話，蕭何認為他是奇才。韓信估計蕭何等人已經多次向漢王推薦，漢王卻不重用自己，就逃走了。蕭何聽說韓信逃走，來不及報告漢王，就親自去追。過了一兩天，蕭何回來拜見漢王，漢王又生氣又高興。蕭何說：「一般將領容易得到，至於像韓信這樣的人，是國內無人能比的傑出人才。大王如果只想長久在漢中稱王，就用不到韓信；如果想爭奪天下，除了韓信，沒有人能和您共商大計。」漢王說：「我看在你的面子上讓他當將軍。」蕭何說：「就算當將軍，韓信也一定不會留下。」漢王說：「那就讓他當大將。」蕭何說：「太好了。」\n（淮陰侯表）功績：起兵之初，以士兵身分跟隨項梁，項梁死後歸屬項羽，任郎中。到咸陽後，逃離項羽跟隨漢王入漢中，任連敖典客，蕭何推薦他為大將軍。另外領兵平定魏、齊，封為齊王，後改封楚王。因擅自發兵獲罪，被貶為淮陰侯。高祖六年四月，是韓信封淮陰侯的元年。高祖十一年，韓信在關中謀反，呂后誅殺韓信，滅三族，封國廢除。", "keywords": [{"w": "漂", "m": "在水中漂洗絲絮"}, {"w": "飯", "m": "作動詞，給人飯吃"}, {"w": "王孫", "m": "對年輕男子的尊稱"}, {"w": "干", "m": "求取，此指獻策求用"}, {"w": "連敖", "m": "楚漢時的低階官名"}, {"w": "度", "m": "估計"}, {"w": "國士無雙", "m": "國內最傑出、無人能比的人才"}, {"w": "坐", "m": "因……而獲罪"}], "questions": [{"n": 37, "qtype": "單選", "stem": "依據上文及下列「淮陰侯表」內容，下列敘述，何者正確？", "options": {"A": "「信釣於城下」約在「以卒從項梁」時", "B": "韓信為「大將」時，應該是在高祖六年", "C": "韓信「為淮陰侯」前，曾任齊王、楚王", "D": "表中「侯功」所述，全摘要自上文而來"}, "answer": "C", "explain": "(C)正確：表中說韓信「別定魏、齊，為王，徙楚（王）」，之後才「廢為淮陰侯」，所以當淮陰侯之前做過齊王和楚王。(A)錯誤：釣於城下、接受漂母給飯是他還沒從軍、窮困潦倒時的事，在投靠項梁之前。(B)錯誤：韓信當大將是剛入漢中時蕭何推薦的；高祖六年四月是他被封淮陰侯的元年。(D)錯誤：「別定魏、齊，為王，徙楚」、「坐擅發兵」等內容，上文都沒有提到。", "skill": "文本＋表格題，把兩邊的事件排成一條時間線，再一一對選項。"}, {"n": 38, "qtype": "單選", "stem": "依據上文及下列對話內容，判斷甲、乙的敘述，何者正確？（對話：根據司馬遷的記載，韓信本要起兵反漢，但被人告發，呂后便與蕭相國共謀，讓蕭相國把韓信騙到長樂宮，最後被呂后安排的人殺死，下場淒涼。所以後人對韓信一生，有「生死一知己，存亡兩婦人」的評價。）甲、「生死一知己」，意同「成也蕭何，敗也蕭何」。乙、「存亡兩婦人」，意指上文所說的「國士無雙」。", "options": {"A": "甲、乙皆正確", "B": "甲、乙皆錯誤", "C": "甲正確，乙錯誤", "D": "甲錯誤，乙正確"}, "answer": "C", "explain": "甲正確：知己蕭何追回韓信、推薦他當大將，讓他成功；後來又和呂后合謀把他騙進長樂宮，讓他喪命，正是「成也蕭何，敗也蕭何」。乙錯誤：「兩婦人」指救他一命的漂母和殺死他的呂后，與蕭何稱讚他「國士無雙」無關。所以選(C)。", "skill": "評語題把每個詞對到具體人物：「一知己」是誰？「兩婦人」是誰？對到人就不會錯。"}], "difficulty": "中", "label": "115二技", "year": 115, "kind": "二技"}, {"id": "et115-42", "exam": "et115", "nums": [42, 43, 44], "form": "題組", "img": "img/et115-42.png", "source": "李清照〈如夢令〉；朱淑貞〈菩薩蠻〉", "author": "李清照、朱淑貞", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀", "寫作手法"], "passage": "【甲】昨夜雨疏風驟，濃睡不消殘酒。試問卷簾人，卻道海棠依舊。知否？知否？應是綠肥紅瘦。\n【乙】山亭水榭秋方半，鳳幃寂寞無人伴。愁悶一番新，雙蛾只舊顰。起來臨繡戶，時有疏螢度。多謝月相憐，今宵不忍圓。", "translation": "【甲】昨夜雨點稀疏、風勢急猛，我睡得很沉，殘留的酒意還沒消。試著問捲簾的侍女，她卻說海棠花還是老樣子。你知道嗎？你知道嗎？應該是綠葉茂盛、紅花凋零了。\n【乙】山中亭子、水邊樓閣，秋天正過了一半，繡著鳳凰的帳子裡寂寞無人陪伴。愁悶又添了一番新的，雙眉依舊緊皺。起身走到繡花的窗戶前，不時有幾隻螢火蟲飛過。多謝月亮憐惜我，今晚不忍心圓滿。", "keywords": [{"w": "雨疏風驟", "m": "雨點稀疏、風勢猛烈"}, {"w": "卷簾人", "m": "捲簾的侍女"}, {"w": "綠肥紅瘦", "m": "葉茂花殘（綠代葉、紅代花）"}, {"w": "鳳幃", "m": "繡有鳳凰的帳子"}, {"w": "雙蛾", "m": "雙眉（蛾眉），借代女子"}, {"w": "顰", "m": "皺眉"}, {"w": "繡戶", "m": "雕飾華美的門窗，指閨房"}], "questions": [{"n": 42, "qtype": "單選", "stem": "下列關於甲、乙二詞的說明，何者正確？", "options": {"A": "兩詞皆書寫主角心中愁緒，同樣屬於婉約派的風格", "B": "兩詞皆藉過往景物的寥落，說明應珍惜易逝的時光", "C": "甲詞以殘酒暗示藏酒甚多，乙詞以山亭襯托眼前美景", "D": "甲詞以海棠傳達惜物心態，乙詞以疏螢說明家道中落"}, "answer": "A", "explain": "(A)正確：甲詞為落花而惆悵，乙詞寫獨守空閨的愁悶，兩位女詞人都以細膩含蓄的筆法寫閨中愁緒，屬婉約風格。(B)錯誤：兩詞寫的是眼前景物，也沒有勸人珍惜時光的說理。(C)錯誤：「殘酒」是昨夜喝醉還沒消的酒意，不是藏酒多；乙詞的山亭水榭是襯托秋夜的寂寞，不是美景。(D)錯誤：疏螢是點出夜深寂寥，與家道中落無關。", "skill": "詞風判斷：寫閨情、離愁、細膩含蓄是婉約；寫壯志、山河、豪放奔騰是豪放。"}, {"n": 43, "qtype": "單選", "stem": "下列關於甲、乙二詞寫作手法的說明，何者正確？", "options": {"A": "皆有借代，甲詞以綠與紅借代葉與花，乙詞以雙蛾借代女子", "B": "皆有設問，甲詞為「知否？知否？」，乙詞為「多謝月相憐」", "C": "皆有對話，甲詞為主角與卷簾人對話，乙詞為主角與鳳幃對話", "D": "皆有擬人，甲詞以「海棠」擬人的穿著，乙詞以「月」擬人的情感"}, "answer": "A", "explain": "(A)正確：「綠肥紅瘦」用顏色代替葉和花；「雙蛾」是女子的眉毛，用來代指女子本人，兩詞都有借代。(B)錯誤：「多謝月相憐」是陳述句，沒有提問，不是設問。(C)錯誤：甲詞確有主角問卷簾人，但乙詞主角沒有和鳳幃（帳子）對話。(D)錯誤：乙詞「月相憐、不忍圓」是擬人，但甲詞的海棠「依舊」只是說花的樣子，沒有把海棠寫成穿衣服的人。", "skill": "「皆有」的選項要兩邊都驗證，只要一邊不成立就刪。"}, {"n": 44, "qtype": "單選", "stem": "依甲、乙二詞之意，判斷①、②的敘述，選出正確選項：①兩詞皆描寫暮春時節所見的自然美景。②兩詞皆敘寫清晨醒後殘留的昨夜愁緒。", "options": {"A": "①正確，②錯誤", "B": "①錯誤，②正確", "C": "①、②皆錯誤", "D": "①、②皆正確"}, "answer": "C", "explain": "①錯誤：甲詞海棠凋零是暮春，但乙詞明說「秋方半」，是仲秋；而且兩詞重點是寫愁，不是寫美景。②錯誤：甲詞是清晨醒來、昨夜酒意未消；但乙詞「時有疏螢度」、「今宵不忍圓」，寫的是夜晚當下的愁，不是清晨。所以選(C)。", "skill": "詩詞時間題先找時間詞（昨夜、秋方半、今宵），季節與時辰一錯就整句錯。"}], "difficulty": "中", "label": "115二技", "year": 115, "kind": "二技"}, {"id": "et115-45", "exam": "et115", "nums": [45, 46, 47], "form": "題組", "img": "img/et115-45.png", "source": "劉基〈賣柑者言〉（試卷標為《郁離子》）", "author": "劉基", "genre": "寓言故事", "types": ["文意推論", "寫作手法", "比較閱讀"], "passage": "杭有賣果者，善藏柑，涉寒暑不潰。出之燁然，玉質而金色。置於市，賈十倍，人爭鬻之。予貿得其一，剖之，如有煙撲口鼻，視其中，則乾若敗絮。予怪而問之曰：「若所市於人者，將以實籩豆，奉祭祀、供賓客乎？將衒外以惑愚瞽乎？甚矣哉，為欺也！」", "translation": "杭州有個賣水果的人，很會貯藏柑橘，經過一整年都不腐爛。拿出來時光彩鮮亮，質地像玉、顏色像金。放到市場上，價錢比別人貴十倍，大家還是搶著買。我買了一個，剖開後，好像有一股煙撲向口鼻，看看裡面，乾得像破舊的棉絮。我覺得奇怪，問他說：「你賣給別人的柑，是要讓人裝在祭器裡祭祀祖先、招待賓客的呢？還是要炫耀外表來迷惑愚笨又看不清的人呢？你這樣欺騙人，實在太過分了！」", "keywords": [{"w": "涉寒暑", "m": "經過一冬一夏，指一整年"}, {"w": "潰", "m": "腐爛"}, {"w": "燁然", "m": "光彩鮮明的樣子"}, {"w": "賈", "m": "同「價」"}, {"w": "鬻", "m": "此處指買（原義為賣）"}, {"w": "貿", "m": "買"}, {"w": "籩豆", "m": "祭祀宴客用的竹器與木器"}, {"w": "衒", "m": "炫耀"}, {"w": "愚瞽", "m": "愚笨和眼盲的人"}], "questions": [{"n": 45, "qtype": "單選", "stem": "依據上文，包裝在行銷上的作用，何者正確？", "options": {"A": "能增加原產品的利用價值", "B": "能改變對產品的感官體驗", "C": "能促進消費者的回購機率", "D": "能提升品牌的特殊識別性"}, "answer": "B", "explain": "(B)正確：文中說「預期心理會改變實際的感官體驗」，同樣的咖啡裝在精緻陶瓷杯裡，喝起來覺得更香醇。(A)錯誤：包裝改變的是感覺，產品本身的用途沒有增加。(C)錯誤：文中沒有談回購率，反而說包裝過度承諾會讓品牌信用崩盤。(D)錯誤：文中沒有討論品牌識別。", "skill": "「依據上文」題，每個選項都要在文中找到對應句，找不到就是無中生有。"}, {"n": 46, "qtype": "單選", "stem": "上文的寫作手法，下列敘述，何者正確？", "options": {"A": "先敘後議，寫個人經驗以及省思", "B": "援引理論，以正反論述提出觀點", "C": "善用事例，由不同舉例歸納結論", "D": "借情喻理，強調主觀認知的力道"}, "answer": "B", "explain": "(B)正確：文章引用路易斯‧契斯金的「感覺轉移」理論，先從正面說包裝能提升感受，再從反面說過度包裝會造成「預期失驗」，最後提出「表裡一致」的觀點。(A)錯誤：文中沒有作者個人經驗。(C)錯誤：只舉了咖啡杯一個例子，不是用多個事例歸納。(D)錯誤：文章以理論說明為主，不是借抒情來說理。", "skill": "說明文手法題，先找文中有沒有「某某提出、理論、概念」，有就是援引理論。"}, {"n": 47, "qtype": "單選", "stem": "下文出自劉基《郁離子》，對應上文所述，下列推論，何者最適當？", "options": {"A": "①可以引申解釋「人爭鬻之」的原因", "B": "②可以說明「予」降低了購買欲望", "C": "③符合「奉祭祀、供賓客」的心理感受", "D": "④符合「賣柑者」的包裝行銷手法"}, "answer": "A", "explain": "(A)正確：①說人會把對外表精緻度、顏色的評價直接轉移給內容物；柑子外表「燁然，玉質而金色」，大家就認定裡面也好，所以價錢貴十倍仍「人爭鬻之」。(B)錯誤：②是說預期會讓感受變好，作者是剖開後才發現受騙，不是因預期而降低購買欲。(C)錯誤：③「一開始就沒期待」與「奉祭祀、供賓客」不合，用來祭祀待客的東西本來就被寄予很高期待。(D)錯誤：④「表裡一致」正好和賣柑者「金玉其外，敗絮其中」相反。", "skill": "文白對讀時，把古文情節翻成現代術語（外表好→大家搶買＝感覺轉移），再去配選項。"}], "difficulty": "中", "label": "115二技", "year": 115, "kind": "二技"}];
window.METHOD="<h2 style=\"margin-top:0\">二技的文言文，靠的是底子</h2>\n<p>二技國文裡，和文言、古典詩詞有關的題目大約占一半。除了閱讀題組，還常常單獨考<b>虛詞、句式和字詞</b>，也會考書信、題辭、柬帖這些<b>應用文</b>。</p>\n<p>如果你離開國文課已經一段時間，不用擔心：先把基本工具找回來，再配合這裡的歷屆題目練習，進步會很明顯。</p>\n<p>下面七個步驟，每次讀文言文都照著做一遍，做久了就會變成習慣。</p>\n\n<h2>讀文言文的七個步驟</h2>\n<div class=\"step\"><div class=\"num\">1</div><div><b>先看題目：知道要找什麼</b><br>先讀題幹和四個選項，再讀文章。把「依據上文」「何者正確／錯誤」「最適當」「無法判斷」這些限制詞圈起來，讀文章時才知道要找什麼。<br><span class=\"meta\">口訣：先看題，再看文，帶著問題去找答案。</span></div></div>\n<div class=\"step\"><div class=\"num\">2</div><div><b>想一想：考的是字詞，還是整篇？</b><br>前面的單題多半考字詞、虛詞、句式或應用文，要把選項的句子逐一放回語境比較；後面的題組才是讀整篇文章。先分清楚，才知道要用哪一套方法。<br><span class=\"meta\">口訣：單題比字詞，題組讀大意。</span></div></div>\n<div class=\"step\"><div class=\"num\">3</div><div><b>切成小段：看到「<span class=\"yue\">曰</span>」、人名就切一刀</b><br>文言句子很長，先切小一點。看到「<span class=\"yue\">曰</span>」（說，不是太陽的「日」）、人名，或句尾的「也、矣、乎、焉」，就畫一條斜線。生難字先圈起來跳過，不要卡住。<br><span class=\"meta\">口訣：見到「<span class=\"yue\">曰</span>」、見到人，就切一刀；不懂先圈，不要停。</span></div></div>\n<div class=\"step\"><div class=\"num\">4</div><div><b>每句都問：這句是「誰」做的？</b><br>文言常把主角省略不寫，這是最容易錯的地方。每一句前面補上「誰」，看到「之」「其」就畫箭頭連回它指的人或事。<br><span class=\"meta\">口訣：每句問誰，沒寫就補。</span></div></div>\n<div class=\"step\"><div class=\"num\">5</div><div><b>整理成一句白話（或一張圖）</b><br>不用逐字翻譯，看懂六七成就能作答。每一段寫成一句「誰＋做了什麼＋結果」。遇到圖表題，就把文章的意思對到圖上的位置，例如哪個象限、哪條線。<br><span class=\"meta\">口訣：抓大放小，一段一句白話。</span></div></div>\n<div class=\"step\"><div class=\"num\">6</div><div><b>逐項找證據，認出陷阱</b><br>每個選項都要指得出「是哪一句說的」。常見陷阱：把人換掉、範圍說太大、感情讀反、只對一半、加進文章沒說的事、時間先後顛倒、虛詞意思偷換。<br><span class=\"meta\">口訣：指不出證據的選項，就不要選。</span></div></div>\n<div class=\"step\"><div class=\"num\">7</div><div><b>回頭驗證，注意時間</b><br>選出答案後，把「題幹＋答案」念一遍，確認和文章一致。二技 50 題 80 分鐘，每題大約 1.5 分鐘，前面單題做快一點，把時間留給後面的長文章。<br><span class=\"meta\">口訣：題幹＋答案念一遍，說得通再作答。</span></div></div>\n\n<h2>先補齊文言工具箱</h2>\n<table>\n<tr><th>工具</th><th>要認得的</th></tr>\n<tr><td>常考虛詞</td><td>之、其、而、以、於、焉、然、乃、則、既、固、所、者、也</td></tr>\n<tr><td>常考句式</td><td>判斷句、被動句、倒裝句、省略句</td></tr>\n<tr><td>特殊詞語</td><td>偏義複詞（如「緩急」只取「急」）、詞類活用（名詞當動詞用）</td></tr>\n<tr><td>應用文</td><td>題辭（婚嫁、壽慶、喪輓、開業）、書信提稱語與敬辭、柬帖與訃聞用語、對聯</td></tr>\n</table>\n<p class=\"meta\">建議：每天讀一則兩三百字的文言短文，只做「切句、標出誰、寫一句白話」三件事，零碎時間也能累積。</p>\n\n<h2>最常掉進去的六個坑</h2>\n<table>\n<tr><th>坑</th><th>長什麼樣子</th><th>怎麼避開</th></tr>\n<tr><td>搞錯是誰做的</td><td>選項把 A 做的事說成 B 做的</td><td>每句補上「誰」；人多就畫人物關係圖</td></tr>\n<tr><td>說得太滿</td><td>文章說「有些」，選項說「全部」；文章沒提，選項卻下了結論</td><td>看到「一定、都、已經不存在」這類字要特別小心</td></tr>\n<tr><td>感情讀反或讀過頭</td><td>作者是無奈，選項說是憤怒；作者淡淡一提，選項說是強烈批判</td><td>找出表達心情的字，看看程度對不對</td></tr>\n<tr><td>只對一半</td><td>選項前半句完全正確，後半句偷偷改掉</td><td>選項要整句檢查，前後兩半都要有證據</td></tr>\n<tr><td>加進文章外的知識</td><td>看到熟悉的名字就自動聯想，例如看到「武侯」就想到楚漢相爭</td><td>只用文章裡給的線索判斷</td></tr>\n<tr><td>虛詞、句式偷換</td><td>「然」「焉」「乃」「既」在不同句子裡意思不同</td><td>把每個可能的意思放回句子，看哪個說得通</td></tr>\n</table>\n\n<h2>怎麼用這個練習場</h2>\n<ul>\n<li><b>剛開始</b>：在「練習」選「單題」，先練字詞、虛詞和應用文，把工具找回來。</li>\n<li><b>練熟了</b>：選「題組」，練習讀一整篇文章。</li>\n<li><b>想挑戰</b>：選「難」，這些是最能拉開分數的題目。</li>\n<li><b>做錯了</b>：看解析裡的「解題小撇步」，再到「錯題本」重做一次。錯題本會告訴你最常錯哪一種題型，就多練那一種。</li>\n</ul>\n";
